// ===================================================================
// MSRA STUDY APP — core data
//   window.SPECIALTIES — clinical tracker (Clinical Problem Solving blueprint)
//   window.PHASES      — adaptive revision plan (both papers)
//   window.TIPS        — strategy tips shown on the Plan view
//   window.EXAM_DATE / window.PLAN_START — default timeline (user-overridable)
//
// Specialty IDs are kept stable forever — statuses, notes and timestamps are
// keyed off the CONDITION ids. Several specialty ids deliberately match the
// constellation shape keys in index.html (cardiology, respiratory, gastro,
// renal, endocrinology, neurology, psychiatry, rheumatology, dermatology,
// infectious, haematology, ophthalmology, pharmacology) so the skill-tree
// renders a bespoke silhouette for each.
// ===================================================================

window.SPECIALTIES = [
  {
    id: "cardiology",
    name: "Cardiovascular",
    icon: "🫀",
    conditions: [
      { id: "cvs_hypertension", management: {"def": "A[\"Confirmed hypertension (ABPM/HBPM)\"]:::start --> B{\"Age and ethnicity\"}:::decision\nB -- \"under 55, not Black\" --> C[\"Step 1: ACE inhibitor or ARB\"]:::good\nB -- \"55+ or Black African/Caribbean\" --> D[\"Step 1: calcium-channel blocker\"]:::good\nC --> E[\"Step 2: ACEi/ARB + CCB\"]:::good\nD --> E\nE --> F[\"Step 3: add thiazide-like diuretic\"]:::good\nF --> G{\"Step 4: resistant? check potassium\"}:::decision\nG -- \"K+ 4.5 or less\" --> H[\"Add spironolactone\"]:::good\nG -- \"K+ above 4.5\" --> I[\"Add alpha- or beta-blocker\"]:::good", "tips": {"A": "Clinic BP 140/90+ confirmed by ambulatory (ABPM) or home (HBPM) 135/85+. Treat stage 1 if under 80 with risk factors/organ damage, and all stage 2.", "B": "First drug depends on age, ethnicity and diabetes.", "C": "Under 55 and not of Black African/Caribbean origin (or type 2 diabetes at any age): ACE inhibitor (ramipril) or ARB (losartan).", "D": "55 or over, or Black African/Caribbean origin at any age: a calcium-channel blocker (amlodipine). Use an ARB rather than ACE inhibitor if a Black patient needs one.", "E": "Combine an ACE inhibitor/ARB with a CCB (or a thiazide-like diuretic).", "F": "Add a thiazide-like diuretic (indapamide) as the third drug.", "G": "Resistant hypertension on three drugs: confirm adherence and check potassium.", "H": "If potassium is 4.5 mmol/L or lower, add low-dose spironolactone.", "I": "If potassium is above 4.5, add an alpha- or beta-blocker and seek specialist advice."}}, cluster: "Blood pressure", name: "Hypertension", keyFacts: "A persistent clinic blood pressure of 140/90 mmHg or more; the leading modifiable risk factor for stroke and ischaemic heart disease.", epidemiology: "Affects around a quarter of UK adults and rises steeply with age; commoner and often more severe in people of Black African or Caribbean descent.", aetiology: "About 95% is primary (essential); secondary causes include renal disease, primary hyperaldosteronism, phaeochromocytoma, Cushing's, coarctation and drugs (NSAIDs, steroids, the combined pill).", pathophysiology: "A sustained rise in systemic vascular resistance, driven by the renin-angiotensin-aldosterone system and sympathetic tone, causes progressive end-organ damage to heart, brain, kidneys and retinae.", presentation: "Usually asymptomatic; found on screening. Stages by clinic and ambulatory/home readings.", investigations: "ABPM/HBPM to confirm, U&E, HbA1c, lipids, ECG, urine ACR, QRISK.", treatment: "Lifestyle; ACE-i/ARB if <55 or diabetic, CCB if ≥55 or Black African/Caribbean; add thiazide-like diuretic; target <140/90 (<135/85 home)." },
      { id: "cvs_hypotension", management: {"def": "A[\"Dizziness or falls on standing: query orthostatic hypotension\"]:::start --> B[\"Lying and standing BP at 1 and 3 min\"]:::process\nB --> C{\"Drop 20+ systolic or 10+ diastolic with symptoms?\"}:::decision\nC -- \"no\" --> D[\"Consider other causes of dizziness/syncope\"]:::good\nC -- \"yes\" --> E[\"Confirm orthostatic hypotension, screen for cause\"]:::good\nE --> F[\"Review and reduce/stop culprit drugs, correct volume and anaemia\"]:::warn\nF --> G[\"Conservative: fluids and salt, slow rising, counter-manoeuvres, stockings, head-up sleep\"]:::good\nG --> H{\"Symptoms persist?\"}:::decision\nH -- \"no\" --> I[\"Continue measures, monitor, prevent falls\"]:::good\nH -- \"yes\" --> J[\"Add fludrocortisone or midodrine\"]:::good\nJ --> I", "tips": {"A": "Suspect orthostatic (postural) hypotension in anyone with light-headedness, unsteadiness, blurred vision or syncope on standing - a common and treatable cause of dizziness and falls, especially in older people and those with diabetes or Parkinson's disease.", "B": "The key bedside test is lying and standing blood pressure: measure after 5 minutes lying, then at 1 and 3 minutes after standing (a tilt-table test can be used if the diagnosis is unclear).", "C": "Orthostatic hypotension is a sustained fall of at least 20 mmHg systolic (or 30 mmHg in someone with supine hypertension) or at least 10 mmHg diastolic within 3 minutes of standing, ideally reproducing the patient's symptoms.", "D": "If there is no significant postural drop, consider other causes of dizziness or transient loss of consciousness - vasovagal (reflex) syncope, cardiac or arrhythmic syncope, or non-syncopal causes.", "E": "Once confirmed, look for the cause with a full medication review plus checks for dehydration or bleeding, anaemia, diabetes, adrenal insufficiency and autonomic failure.", "F": "The highest-yield step is to review and reduce or stop drugs that lower blood pressure (antihypertensives, diuretics, alpha-blockers, nitrates, tricyclics, dopaminergics) and to correct volume depletion or anaemia.", "G": "First-line treatment is non-pharmacological: increase fluid and (unless contraindicated) salt intake, stand up in stages, use physical counter-manoeuvres (leg crossing, muscle tensing), wear compression stockings, and raise the head of the bed at night.", "H": "Reassess symptoms after optimising medications and conservative measures.", "I": "If controlled, continue the measures with monitoring and falls prevention - postural hypotension is a strong predictor of falls and fracture.", "J": "For persistent symptoms add a drug: fludrocortisone (expands plasma volume - watch for oedema, hypokalaemia and supine hypertension) or midodrine (an alpha-agonist vasoconstrictor); specialist input helps in autonomic failure."}, "source": "NICE CKS"}, cluster: "Blood pressure", name: "Hypotension (incl. orthostatic)", keyFacts: "An abnormally low blood pressure (commonly taken as under 90/60 mmHg) that matters when it causes hypoperfusion; orthostatic (postural) hypotension - a sustained fall of at least 20 mmHg systolic or 10 mmHg diastolic within 3 minutes of standing - is the commonest form and a major cause of dizziness, syncope and falls.", epidemiology: "Orthostatic hypotension is very common in older people (affecting up to 20-30% of those over 65) and in people with diabetes or Parkinson's disease; it is an important and frequently missed cause of falls, syncope and fracture.", aetiology: "Orthostatic hypotension is caused by drugs (antihypertensives, diuretics, alpha-blockers, nitrates, tricyclics, dopaminergics), volume depletion (dehydration, haemorrhage, Addison's) or autonomic failure (diabetic neuropathy, Parkinson's, multiple system atrophy). Sustained hypotension more broadly may reflect sepsis, cardiogenic or other shock, or endocrine disease.", pathophysiology: "On standing, gravity pools around 500-1000 mL of blood in the legs and splanchnic circulation; normally baroreceptor-mediated sympathetic activation restores blood pressure within seconds. When this reflex fails or circulating volume is inadequate, cerebral perfusion falls and produces symptoms - the drop may be immediate or delayed.", presentation: "Light-headedness, dizziness, blurred vision, weakness or a coat-hanger ache across the neck and shoulders on standing, progressing to presyncope, syncope and falls; symptoms are worse in the morning, after meals, in hot weather and after exertion. Chronic hypotension may be asymptomatic.", investigations: "Lying and standing blood pressure is the key test (measure supine after 5 minutes, then at 1 and 3 minutes standing), looking for a postural drop with symptoms. Screen for causes - medication review, FBC (anaemia or bleeding), U and Es and glucose, and consider an ECG, a 9am cortisol (Addison's) and autonomic or tilt-table testing.", treatment: "Treat the cause and review or withdraw culprit drugs; conservative measures first - increase fluid and salt intake, stand up slowly, physical counter-manoeuvres, compression stockings and sleeping head-up; if refractory, add fludrocortisone or midodrine. For non-postural hypotension, treat the underlying problem (sepsis, blood loss, endocrine or cardiogenic cause)." },
      { id: "cvs_ihd", cluster: "Coronary artery disease", name: "Ischaemic heart disease", keyFacts: "Coronary atherosclerosis reducing myocardial blood supply; the umbrella term for stable angina, acute coronary syndromes and ischaemic cardiomyopathy.", epidemiology: "A leading cause of death in the UK, rising with age and higher in men and South Asian populations.", aetiology: "Modifiable risk factors (smoking, hypertension, diabetes, hyperlipidaemia, obesity) and non-modifiable ones (age, sex, family history).", pathophysiology: "Atherosclerotic narrowing limits coronary flow, causing ischaemia on demand and, when a plaque ruptures, acute events.", presentation: "Ranges from exertional angina to acute coronary syndrome, heart failure or sudden cardiac death.", investigations: "Cardiovascular risk assessment (QRISK), ECG, CT coronary angiography or functional imaging, and bloods.", treatment: "Risk-factor modification, antiplatelet and statin therapy, anti-anginal drugs, and revascularisation when indicated." },
      { id: "cvs_angina", management: {"def": "A[\"Symptomatic stable angina\"]:::start -- \"treat with\" --> B[\"Stable angina medication\"]:::process\nB -- \"all patients\" --> C[\"Aspirin and statin\"]:::good\nB -- \"for attacks\" --> D[\"Sublingual GTN\"]:::good\nB -- \"prevent attacks\" --> E{\"First-line antianginal choice\"}:::decision\nE -- \"choose BB\" --> F[\"Beta-blocker monotherapy\"]:::good\nE -- \"choose CCB\" --> G[\"Rate-limiting CCB monotherapy\"]:::good\nF -- \"if response poor\" --> H[\"Maximise tolerated dose\"]:::warn\nG -- \"if response poor\" --> H\nH -- \"reassess\" --> I{\"Persistent symptoms?\"}:::decision\nI -- \"can add\" --> J[\"Add complementary agent\"]:::good\nI -- \"cannot add\" --> K[\"Alternative antianginal agent\"]:::good\nJ -- \"still symptomatic\" --> L[\"Third drug pending revascularisation\"]:::good", "tips": {"A": "Predictable exertional chest discomfort from fixed coronary artery disease, relieved by rest or GTN.", "B": "Combine secondary-prevention drugs, symptom relief for attacks, and antianginal drugs to prevent attacks.", "C": "Secondary prevention for everyone: aspirin 75 mg (clopidogrel if intolerant) plus a statin; consider an ACE inhibitor if diabetic, and control risk factors.", "D": "Glyceryl trinitrate for acute attacks; repeat after 5 minutes, call 999 if pain persists 5 minutes after the second dose.", "E": "NICE: first-line is a beta-blocker OR a rate-limiting calcium-channel blocker — choose on comorbidity and preference.", "F": "e.g. bisoprolol or atenolol; do not stop abruptly; caution in asthma.", "G": "Rate-limiting CCB e.g. diltiazem or verapamil. Never combine verapamil with a beta-blocker (risk of bradycardia and heart block).", "H": "Optimise the first drug to the maximum tolerated dose before adding a second.", "I": "Still symptomatic on one drug at maximum tolerated dose? Reassess before escalating.", "J": "If on a beta-blocker or CCB, add the other class — use a dihydropyridine CCB (e.g. amlodipine) alongside a beta-blocker.", "K": "If a beta-blocker/CCB can't be added or tolerated, use a long-acting nitrate, ivabradine, nicorandil or ranolazine.", "L": "While awaiting assessment for revascularisation (PCI or CABG), a third antianginal may be added; refer if uncontrolled on two drugs."}}, cluster: "Coronary artery disease", name: "Stable angina", keyFacts: "Predictable exertional chest pain from fixed coronary narrowing, relieved by rest or glyceryl trinitrate (GTN).", epidemiology: "Common, increasing with age and the burden of cardiovascular risk factors.", aetiology: "Coronary atherosclerosis; the same risk factors as acute coronary syndrome, and anaemia or aortic stenosis can unmask it.", pathophysiology: "A fixed atheromatous stenosis limits coronary flow, so on exertion myocardial oxygen demand outstrips supply and produces transient, reversible ischaemia.", presentation: "Predictable exertional chest tightness relieved by rest or GTN.", investigations: "CT coronary angiography first line, ECG, bloods, assess risk factors.", treatment: "GTN spray for attacks; beta-blocker or CCB first line; aspirin and statin; consider revascularisation." },
      { id: "cvs_acs", management: {"def": "A[\"Acute coronary syndrome\"]:::start --> B[\"Aspirin 300 mg, ECG, troponin, analgesia\"]:::good\nB --> C{\"ST elevation on ECG?\"}:::decision\nC -- \"STEMI\" --> D[\"Primary PCI (or thrombolysis)\"]:::danger\nC -- \"NSTEMI / unstable angina\" --> E[\"Fondaparinux; GRACE score\"]:::good\nE --> F{\"GRACE risk\"}:::decision\nF -- \"high\" --> G[\"Early angiography +/- PCI\"]:::good\nF -- \"low\" --> H[\"Medical management\"]:::good\nD --> I[\"Secondary prevention\"]:::process\nG --> I\nH --> I\nI --> J[\"DAPT, statin, ACEi, beta-blocker, rehab\"]:::good", "tips": {"A": "Ischaemic chest pain; the ECG splits management into STEMI versus NSTEMI/unstable angina.", "B": "Aspirin 300 mg, 12-lead ECG, serial high-sensitivity troponin, oxygen only if hypoxic, GTN and morphine for pain.", "C": "ST elevation (or new left bundle branch block) = STEMI needing immediate reperfusion.", "D": "Primary PCI if within 12 h of onset and available within 120 min; otherwise fibrinolysis. Add a second antiplatelet (prasugrel or ticagrelor).", "E": "NSTEMI/unstable angina: give fondaparinux (if not going straight to angiography) and calculate the GRACE score.", "F": "GRACE stratifies 6-month mortality and the need for early invasive management.", "G": "Intermediate/high risk: coronary angiography within 72 h with PCI as indicated, plus ticagrelor/prasugrel.", "H": "Low risk: medical therapy with non-invasive ischaemia testing.", "I": "All ACS patients start long-term secondary prevention.", "J": "Dual antiplatelet therapy for 12 months, high-intensity statin, ACE inhibitor, beta-blocker and cardiac rehabilitation; modify risk factors."}}, cluster: "Coronary artery disease", name: "Acute coronary syndrome", keyFacts: "A spectrum (unstable angina, NSTEMI, STEMI) caused by acute coronary plaque events; STEMI needs immediate reperfusion.", epidemiology: "A leading cause of death in the UK; incidence rises with age and is higher in men and in South Asian populations.", aetiology: "Atherosclerotic plaque rupture with thrombosis; risk factors are smoking, diabetes, hypertension, hyperlipidaemia and family history.", pathophysiology: "Rupture of an atheromatous plaque triggers platelet aggregation and thrombus that partially (NSTEMI/unstable angina) or completely (STEMI) occludes a coronary artery, causing myocardial ischaemia or infarction.", presentation: "Central crushing chest pain, radiation to jaw/arm, sweating, nausea; may be silent in diabetics/elderly.", investigations: "ECG (ST changes), serial troponin.", treatment: "MONA plus dual antiplatelet; primary PCI for STEMI; risk-stratify NSTEM with GRACE." },
      { id: "cvs_mi", management: {"def": "A[\"Myocardial infarction (troponin rise)\"]:::start --> B[\"Initial: aspirin 300 mg, ECG, analgesia, oxygen if hypoxic\"]:::good\nB --> C{\"ST elevation or new LBBB?\"}:::decision\nC -- \"STEMI, within 12 h\" --> D{\"Primary PCI within 120 min?\"}:::decision\nD -- \"yes\" --> K[\"Primary PCI + prasugrel and aspirin\"]:::danger\nD -- \"no\" --> L[\"Fibrinolysis + antithrombin + antiplatelet\"]:::danger\nL --> M[\"Repeat ECG at 60-90 min\"]:::process\nM --> N{\"ST elevation resolved?\"}:::decision\nN -- \"no (failed)\" --> O[\"Immediate rescue PCI\"]:::danger\nN -- \"yes\" --> P[\"Angiography this admission\"]:::good\nC -- \"NSTEMI\" --> E[\"Fondaparinux, then GRACE score\"]:::good\nE --> F{\"GRACE risk\"}:::decision\nF -- \"high\" --> G[\"Angiography within 72 h +/- PCI\"]:::good\nF -- \"low\" --> H[\"Medical management, ischaemia testing\"]:::good\nK --> J[\"Secondary prevention: DAPT, statin, ACEi, beta-blocker, rehab\"]:::good\nO --> J\nP --> J\nG --> J\nH --> J", "tips": {"A": "Myocardial necrosis diagnosed by a troponin rise with ischaemic features; the ECG splits it into STEMI (ST elevation) and NSTEMI, which take different acute pathways.", "B": "Immediate treatment: aspirin 300 mg, a 12-lead ECG, analgesia (GTN and morphine) and oxygen only if saturations are low (the old MONA - but oxygen only if hypoxic).", "C": "ST elevation in two contiguous leads (or new left bundle branch block) means STEMI needing immediate reperfusion; otherwise treat as NSTEMI. NICE NG185 offers reperfusion if within 12 hours of symptom onset - and beyond 12 hours only if there is continuing myocardial ischaemia.", "D": "NICE NG185: primary PCI is the preferred reperfusion strategy if it can be delivered within 120 minutes of the time fibrinolysis could have been given; if it cannot, give fibrinolysis instead.", "K": "Primary PCI (radial access, drug-eluting stent). NICE second antiplatelet is prasugrel with aspirin; use clopidogrel if already on an oral anticoagulant, and consider ticagrelor or clopidogrel instead if aged 75 or over or at higher bleeding risk.", "L": "Give a fibrinolytic (a fibrin-specific agent such as tenecteplase or alteplase). NICE NG185: give an antithrombin (e.g. enoxaparin, fondaparinux or unfractionated heparin) at the SAME time, plus aspirin and a second antiplatelet (clopidogrel). Never repeat fibrinolysis if it fails.", "M": "NICE NG185: record an ECG 60 to 90 minutes after fibrinolysis to judge whether reperfusion has succeeded.", "N": "Successful reperfusion = resolution of ST-segment elevation (and settling pain); residual ST elevation suggests failed reperfusion.", "O": "Residual ST elevation (failed reperfusion): offer immediate coronary angiography with follow-on rescue PCI if indicated - do not give fibrinolysis again. Also seek urgent cardiology advice and angiography if ischaemia recurs after initially successful lysis.", "P": "After successful fibrinolysis, proceed to coronary angiography (with PCI if indicated) during the same admission - a pharmaco-invasive approach - rather than immediately.", "E": "NSTEMI: give fondaparinux (if not going straight to angiography) and calculate the GRACE score.", "F": "The GRACE score estimates 6-month mortality and guides how urgently to offer coronary angiography.", "G": "Intermediate-to-high-risk NSTEMI: coronary angiography (with PCI as needed) within 72 hours; add a second antiplatelet - ticagrelor, or prasugrel given at the time of PCI.", "H": "Low-risk NSTEMI: medical management with ticagrelor and aspirin (clopidogrel or aspirin alone if high bleeding risk) and non-invasive ischaemia testing.", "J": "All MI patients need long-term secondary prevention: dual antiplatelet therapy (up to 12 months), a high-intensity statin, an ACE inhibitor, a beta-blocker, and cardiac rehabilitation, plus risk-factor modification."}}, complications: "Immediate (0-24 h): cardiac arrest (usually ventricular fibrillation or pulseless VT); cardiogenic shock; tachyarrhythmias (ventricular tachycardia, VF, atrial fibrillation); bradyarrhythmias and heart block (especially inferior MI affecting the AV node).\nEarly (first 1-14 days): pericarditis (2-4 days); left ventricular free wall rupture (causing cardiac tamponade); ventricular septal defect (septal rupture, new pansystolic murmur); acute mitral regurgitation (papillary muscle rupture, acute pulmonary oedema).\nLate (weeks to months): left ventricular aneurysm (persistent ST elevation, heart failure, mural thrombus); chronic heart failure. Dressler's syndrome (autoimmune pericarditis at 2-6 weeks) is another classic late complication.", cluster: "Coronary artery disease", name: "Myocardial infarction", keyFacts: "Death of heart muscle from prolonged ischaemia, diagnosed by a troponin rise with ischaemic features; divided into STEMI and NSTEMI, and into type 1 (plaque rupture) and type 2 (supply-demand mismatch).", epidemiology: "A leading cause of death worldwide, with incidence rising with age and higher in men and South Asian populations.", aetiology: "Usually atherosclerotic plaque rupture with coronary thrombosis (type 1); type 2 arises from supply-demand mismatch such as anaemia, hypotension or tachyarrhythmia.", pathophysiology: "Critical coronary occlusion causes myocardial necrosis that evolves over hours; complications include arrhythmia, heart failure, cardiogenic shock, mechanical rupture and pericarditis.", presentation: "Central crushing chest pain radiating to the jaw or arm with sweating, nausea and breathlessness; may be silent in diabetics and the elderly.", investigations: "Serial 12-lead ECG (ST elevation, evolving T-wave and Q-wave changes), high-sensitivity troponin, and bloods (FBC, U&E, glucose, lipids); echocardiography and coronary angiography.", treatment: "Immediate reperfusion for STEMI (primary PCI, or thrombolysis if PCI is unavailable in time); dual antiplatelet therapy and anticoagulation; secondary prevention with aspirin, a second antiplatelet, a beta-blocker, an ACE inhibitor, a statin and cardiac rehabilitation." },
      { id: "cvs_heart_failure", management: {"def": "A[\"Chronic heart failure, reduced ejection fraction\"]:::start -- \"symptom relief\" --> B[\"Loop diuretic for congestion\"]:::good\nA -- \"disease-modifying\" --> C[\"First-line: ACE inhibitor + beta-blocker\"]:::good\nC -- \"titrate, one at a time\" --> D{\"Symptoms persist?\"}:::decision\nD -- \"yes\" --> E[\"Add MRA (spironolactone/eplerenone)\"]:::good\nE --> F[\"Add SGLT2 inhibitor\"]:::good\nF --> G[\"Specialist add-ons / devices\"]:::warn", "tips": {"A": "Ejection fraction below ~40% causing breathlessness, fatigue and fluid overload; confirmed on echo with a raised NT-proBNP. The two arrows from here are parallel - a loop diuretic for symptom relief and an ACE inhibitor plus beta-blocker as disease-modifying first-line are both started, not an either/or choice.", "B": "Furosemide/bumetanide relieve congestion but do not improve prognosis; titrate to symptoms.", "C": "Prognostic core: an ACE inhibitor (ARB if intolerant) plus a beta-blocker licensed for heart failure (bisoprolol, carvedilol, nebivolol).", "D": "Reassess symptoms and function once first-line drugs are optimised.", "E": "Add a mineralocorticoid receptor antagonist; monitor potassium and renal function.", "F": "Add dapagliflozin or empagliflozin (benefit even without diabetes).", "G": "Specialist: switch ACE inhibitor to sacubitril-valsartan; ivabradine if sinus rhythm and HR 75+; cardiac resynchronisation or implantable defibrillator in selected patients."}}, cluster: "Heart failure & cardiomyopathies", name: "Heart failure with reduced ejection fraction (HFrEF)", keyFacts: "Heart failure with a left ventricular ejection fraction under 40% (systolic failure); the type with the strongest evidence-based drug therapy - the four pillars.", epidemiology: "Common and rising with age, and more frequent in men; often follows myocardial infarction or long-standing hypertension.", aetiology: "Ischaemic heart disease (especially post-MI) is the commonest cause; also dilated cardiomyopathy, hypertension, valvular disease, arrhythmia, alcohol and myocarditis.", pathophysiology: "Impaired systolic contraction lowers stroke volume and ejection fraction; neurohormonal activation (renin-angiotensin-aldosterone and sympathetic) drives fluid retention and adverse remodelling.", presentation: "Exertional breathlessness, orthopnoea, paroxysmal nocturnal dyspnoea, fatigue and peripheral oedema; raised JVP, a displaced apex, a third heart sound and bibasal crackles.", investigations: "NT-proBNP, then echocardiography confirming an ejection fraction under 40%; ECG, chest X-ray and bloods, with coronary assessment for an ischaemic cause.", treatment: "The four pillars: ACE inhibitor or ARB (or sacubitril-valsartan), beta-blocker, MRA and an SGLT2 inhibitor; loop diuretic for congestion; device therapy (CRT/ICD) and treat the cause." },
      { id: "cvs_hfpef", management: {"def": "A[\"Suspected heart failure, preserved EF\"]:::start --> B[\"NT-proBNP + echocardiography\"]:::process\nB --> C{\"Preserved EF and diastolic dysfunction?\"}:::decision\nC -- \"no (EF under 50)\" --> D[\"Reassess: HFrEF/HFmrEF pathway\"]:::warn\nC -- \"yes, HFpEF\" --> E[\"Loop diuretic for congestion\"]:::good\nE --> F[\"Add SGLT2 inhibitor\"]:::good\nF --> G[\"Optimise comorbidities: BP, AF, obesity, diabetes\"]:::good\nG --> H[\"Cardiac rehab, specialist review if refractory\"]:::warn", "tips": {"A": "Heart failure symptoms and signs (breathlessness, oedema) with a suspected preserved ejection fraction, typically in an older hypertensive or obese patient; a diagnosis of exclusion (NICE NG106).", "B": "Measure NT-proBNP and arrange echocardiography; a very high NT-proBNP warrants urgent specialist referral and echo within 2 weeks.", "C": "HFpEF requires an ejection fraction of 50% or more with objective evidence of raised filling pressures or diastolic dysfunction (plus a raised natriuretic peptide); scores such as H2FPEF or HFA-PEFF help.", "D": "If the ejection fraction is reduced (under 40%) or mildly reduced (40-49%, HFmrEF), use the HFrEF pathway with its four pillars of therapy.", "E": "Give a loop diuretic (e.g. furosemide) to relieve congestion and oedema, titrated to symptoms - the mainstay of symptom control.", "F": "Add an SGLT2 inhibitor (dapagliflozin or empagliflozin) - the first drug class shown to improve outcomes in HFpEF.", "G": "Tightly manage the comorbidities that drive HFpEF: blood pressure, atrial fibrillation (rate/rhythm control and anticoagulation), obesity and diabetes.", "H": "Offer cardiac rehabilitation and refer to a specialist heart failure service if symptoms are refractory or the diagnosis is uncertain."}}, cluster: "Heart failure & cardiomyopathies", name: "Heart failure with preserved ejection fraction (HFpEF)", keyFacts: "Heart failure symptoms and signs with a preserved ejection fraction (50% or more) plus objective evidence of raised filling pressures or diastolic dysfunction; largely a diagnosis of exclusion.", epidemiology: "Increasingly common and now about half of all heart failure; typically older women with hypertension, obesity, atrial fibrillation and diabetes.", aetiology: "Hypertension is the main driver; also obesity, diabetes, atrial fibrillation and ageing, plus restrictive or hypertrophic cardiomyopathy, constrictive pericarditis and cardiac amyloid.", pathophysiology: "Impaired ventricular relaxation and a stiff, non-compliant ventricle raise filling pressures despite preserved contraction, causing pulmonary and systemic congestion with a normal ejection fraction.", presentation: "The same congestive picture - exertional breathlessness, orthopnoea and oedema - usually in an older, hypertensive or obese patient, often with atrial fibrillation.", investigations: "Raised NT-proBNP with echocardiography showing a preserved ejection fraction (50% or more), diastolic dysfunction, left atrial enlargement and left ventricular hypertrophy; scoring (H2FPEF or HFA-PEFF) supports the diagnosis.", treatment: "Loop diuretic for congestion, an SGLT2 inhibitor (dapagliflozin or empagliflozin, now evidence-based), and tight control of comorbidities (blood pressure, atrial fibrillation, obesity, diabetes); no other drug clearly improves mortality." },
      { id: "cvs_adhf", management: {"def": "A[\"Acute decompensated heart failure\"]:::start --> B[\"Sit up, O2 if hypoxic, IV access, monitor\"]:::good\nB --> C[\"NT-proBNP, ECG, CXR, troponin, U and Es, echo\"]:::process\nC --> D[\"IV loop diuretic (furosemide)\"]:::good\nD --> E{\"Blood pressure and perfusion?\"}:::decision\nE -- \"hypotensive/hypoperfused\" --> G[\"Cardiogenic shock pathway: inotrope + ICU\"]:::danger\nE -- \"adequate BP\" --> F[\"Add IV nitrate if hypertensive or ischaemic\"]:::good\nF --> H{\"Refractory pulmonary oedema or tiring?\"}:::decision\nH -- \"yes\" --> I[\"CPAP/NIV, consider ICU\"]:::warn\nH -- \"no\" --> J[\"Treat precipitant, monitor fluid balance\"]:::good\nI --> J\nJ --> K[\"Start/optimise HF therapy: ACEi/ARB, beta-blocker, MRA, SGLT2i\"]:::good", "tips": {"A": "Acute heart failure is the rapid onset or worsening of heart failure symptoms and signs needing urgent treatment; it may be new (de novo) or a decompensation of chronic heart failure (NICE NG187).", "B": "Initial resuscitation: sit the patient fully upright, give oxygen only if saturations are low (target 94-98%), obtain IV access and attach continuous monitoring; involve seniors early.", "C": "Investigate: NT-proBNP (a low level makes acute HF unlikely), ECG, chest X-ray, troponin, U and Es and a blood gas; arrange transthoracic echocardiography, performed within 48 hours and urgently if haemodynamically unstable.", "D": "The mainstay is an intravenous loop diuretic (e.g. furosemide) to offload fluid; monitor urine output, daily weight, renal function and potassium.", "E": "Assess blood pressure and perfusion - these guide the next step and identify cardiogenic shock (hypotension with hypoperfusion).", "F": "If the patient is hypertensive or has myocardial ischaemia with an adequate blood pressure, add an intravenous nitrate with close BP monitoring; NICE advises against routine nitrate use otherwise.", "G": "Hypotension with hypoperfusion means cardiogenic shock - move to inotropic/vasopressor support and critical care (see the cardiogenic shock pathway).", "H": "Reassess for worsening oxygenation, exhaustion or pulmonary oedema refractory to diuresis.", "I": "Non-invasive ventilation (CPAP) can be added for cardiogenic pulmonary oedema with respiratory failure; escalate to critical care and consider intubation if the patient tires.", "J": "Identify and treat the precipitant (ACS, arrhythmia such as fast AF, hypertension, infection, non-adherence) and monitor fluid balance carefully.", "K": "Once stabilised, start or optimise evidence-based chronic heart failure therapy (ACE inhibitor or ARB, beta-blocker, mineralocorticoid receptor antagonist and an SGLT2 inhibitor) with specialist follow-up. NICE advises not to offer opioids routinely in acute heart failure."}, "source": "NICE"}, cluster: "Heart failure & cardiomyopathies", name: "Acute decompensated heart failure", keyFacts: "The rapid onset or worsening of heart failure symptoms and signs needing urgent treatment; may be new (de novo) or an acute decompensation of chronic heart failure, with acute pulmonary oedema the classic life-threatening presentation.", epidemiology: "A leading cause of emergency hospital admission and of bed-days in adults over 65, with high in-hospital and 1-year mortality and frequent readmission.", aetiology: "Usually a precipitant acting on a failing heart: acute coronary syndrome, arrhythmia (especially fast AF), uncontrolled hypertension, non-adherence to medication or diet, infection, anaemia, renal dysfunction, and fluid-retaining or negatively inotropic drugs (NSAIDs). De novo causes include large MI and acute valve failure.", pathophysiology: "A precipitant tips the heart into a state where output cannot meet demand or filling pressures rise sharply; raised left atrial pressure drives pulmonary congestion and oedema, while neurohormonal activation (RAAS and sympathetic) causes further fluid retention and vasoconstriction.", presentation: "Acute breathlessness and orthopnoea, pink frothy sputum, tachypnoea and fine bibasal crepitations (pulmonary oedema); raised JVP, peripheral oedema and cool peripheries; may progress to type 1 respiratory failure or cardiogenic shock.", investigations: "NT-proBNP (a normal level makes acute heart failure unlikely), ECG, chest X-ray (upper-lobe diversion, Kerley B lines, effusions, cardiomegaly), ABG, troponin, U and Es and FBC; transthoracic echocardiography to assess ventricular function and valves, urgently if haemodynamically unstable.", treatment: "Sit upright, oxygen if hypoxic (target saturations) and an IV loop diuretic (furosemide) as the mainstay; IV nitrate if hypertensive or ischaemic; CPAP for refractory pulmonary oedema; treat the precipitant; inotropes/vasopressors and critical care if hypotensive or in cardiogenic shock; do not routinely offer opioids. Once stable, start or optimise guideline heart failure therapy." },
      { id: "cvs_cardiogenic_shock", management: {"def": "A[\"Cardiogenic shock: SBP under 90 + hypoperfusion\"]:::start --> B[\"ABC, high-flow O2, IV access, monitoring\"]:::good\nB --> C[\"ECG, troponin, ABG/lactate, urgent echo\"]:::process\nC --> D{\"Mechanical or reversible cause?\"}:::decision\nD -- \"tamponade/valve/PE/arrhythmia\" --> E[\"Treat cause: drain, surgery, thrombolysis, rhythm control\"]:::warn\nD -- \"acute MI\" --> F[\"Emergency revascularisation: primary PCI\"]:::danger\nF --> G[\"Cautious fluid only if not overloaded\"]:::good\nE --> G\nG --> H{\"Still hypoperfused?\"}:::decision\nH -- \"no\" --> L[\"ICU: optimise, treat acidosis, monitor\"]:::good\nH -- \"yes\" --> I[\"Inotrope (dobutamine) +/- vasopressor (noradrenaline)\"]:::warn\nI --> J{\"Refractory?\"}:::decision\nJ -- \"no\" --> L\nJ -- \"yes\" --> K[\"Mechanical support (Impella/VA-ECMO) + ICU\"]:::danger", "tips": {"A": "Cardiogenic shock is sustained hypotension (systolic BP under 90 mmHg, or needing support to maintain it) with end-organ hypoperfusion - cold peripheries, oliguria, confusion, raised lactate - due to a cardiac cause despite adequate filling.", "B": "Resuscitate: airway, high-flow oxygen titrated to saturations, large-bore IV access and continuous cardiac monitoring; involve cardiology and critical care early.", "C": "Investigate rapidly - a 12-lead ECG (STEMI or arrhythmia), troponin, arterial blood gas and lactate, and urgent bedside echocardiography to assess LV function and exclude mechanical causes.", "D": "Look for specifically treatable causes - cardiac tamponade, acute valve or septal rupture, massive PE, or a tachy/brady-arrhythmia - which need targeted emergency treatment rather than supportive care alone.", "E": "Treat the specific cause: pericardiocentesis for tamponade, urgent surgery for mechanical complications or acute valve failure, thrombolysis or embolectomy for massive PE, and rhythm control for arrhythmia.", "F": "Acute MI is the commonest cause - emergency reperfusion by primary PCI of the culprit vessel is the single most important intervention and improves survival (SHOCK trial).", "G": "Give only a small, cautious fluid challenge (about 250 mL) if there is no pulmonary oedema, reassessing frequently; most patients are congested and need diuresis instead.", "H": "Reassess perfusion - blood pressure, lactate, urine output and mental state - after treating the cause and optimising filling.", "I": "If still hypoperfused, add an inotrope for contractility (dobutamine) and a vasopressor (noradrenaline first-line) to keep mean arterial pressure around 65 mmHg; use the lowest effective dose as they raise myocardial oxygen demand.", "J": "Shock refractory to drugs warrants consideration of temporary mechanical circulatory support.", "K": "Mechanical circulatory support (e.g. Impella or veno-arterial ECMO) can bridge to recovery, revascularisation or transplant; the intra-aortic balloon pump is no longer routinely recommended (IABP-SHOCK II). Manage in intensive care.", "L": "Intensive care: optimise volume status, correct acidosis and electrolytes, treat arrhythmia, and provide organ support (ventilation, renal replacement) as needed."}, "source": "Cardiac emergency"}, cluster: "Heart failure & cardiomyopathies", name: "Cardiogenic shock", keyFacts: "A state of inadequate tissue perfusion caused by primary cardiac pump failure despite adequate intravascular volume; defined by sustained hypotension (systolic under 90 mmHg) with end-organ hypoperfusion, and carries a high mortality (around 40-50%).", epidemiology: "Complicates roughly 5-10% of acute myocardial infarctions and is the leading cause of in-hospital death after MI; incidence is rising with an ageing, comorbid population.", aetiology: "Most often extensive left ventricular infarction, or a mechanical complication of MI (papillary muscle rupture, ventricular septal rupture, free-wall rupture). Other causes: end-stage cardiomyopathy, fulminant myocarditis, arrhythmia, acute valvular failure, cardiac tamponade, massive PE and drug toxicity.", pathophysiology: "A critical fall in cardiac output reduces tissue perfusion; compensatory vasoconstriction and fluid retention raise afterload and filling pressures, worsening pulmonary oedema and myocardial ischaemia in a self-perpetuating downward spiral. A systemic inflammatory response may add inappropriate vasodilatation.", presentation: "Hypotension with cool, mottled peripheries, tachycardia and a thready pulse; raised JVP and pulmonary oedema (breathlessness, crepitations); oliguria and confusion or agitation from poor cerebral perfusion.", investigations: "ECG (MI, arrhythmia), troponin, ABG with lactate, U and Es, FBC and CXR; urgent echocardiography to assess LV function and exclude mechanical or valvular causes; coronary angiography if ischaemic; invasive monitoring (arterial line, central venous access).", treatment: "ABC with oxygen and a small cautious fluid challenge only if not overloaded; treat the cause - emergency revascularisation (primary PCI) for MI; inotropes (dobutamine) and a vasopressor (noradrenaline) to support perfusion; mechanical circulatory support (Impella or VA-ECMO; intra-aortic balloon pump no longer routine) if refractory; manage in intensive care with correction of acidosis and arrhythmia." },
      { id: "cvs_dcm", cluster: "Heart failure & cardiomyopathies", name: "Dilated cardiomyopathy", keyFacts: "The commonest cardiomyopathy: a dilated, poorly contracting left (or both) ventricle causing systolic heart failure.", epidemiology: "The leading cardiomyopathy and a common indication for heart transplantation.", aetiology: "Often idiopathic or genetic; also alcohol, post-viral myocarditis, peripartum, thyroid disease and chemotherapy (doxorubicin).", pathophysiology: "Ventricular dilatation with thin walls reduces contractile force, causing low output, mural thrombus and functional valve regurgitation.", presentation: "Features of heart failure (breathlessness, oedema, fatigue), arrhythmias and thromboembolism.", investigations: "Echocardiography (a dilated, poorly contracting ventricle), ECG, BNP, and screening for reversible causes.", treatment: "Standard heart failure therapy (ACE inhibitor, beta-blocker, MRA, SGLT2 inhibitor), treat the cause, anticoagulation and device therapy where indicated." },
      { id: "cvs_hcm", cluster: "Heart failure & cardiomyopathies", name: "Hypertrophic cardiomyopathy", keyFacts: "An inherited disease of asymmetric left ventricular hypertrophy; a leading cause of sudden cardiac death in young people and athletes.", epidemiology: "The commonest inherited cardiac condition, affecting roughly 1 in 500.", aetiology: "Autosomal dominant mutations in sarcomeric proteins (for example beta-myosin heavy chain).", pathophysiology: "Abnormal myocyte hypertrophy and disarray make a stiff ventricle with diastolic dysfunction and often dynamic left ventricular outflow obstruction and arrhythmia.", presentation: "Often asymptomatic; exertional breathlessness, chest pain, palpitations, syncope or sudden death; an ejection systolic murmur that is louder on Valsalva.", investigations: "Echocardiography (septal hypertrophy, systolic anterior motion of the mitral valve), ECG (left ventricular hypertrophy, deep Q waves), genetic testing and family screening.", treatment: "Beta-blockers or verapamil for symptoms; avoid dehydration and intense exertion; an implantable defibrillator for high sudden-death risk; septal reduction for refractory obstruction." },
      { id: "cvs_rcm", cluster: "Heart failure & cardiomyopathies", name: "Restrictive cardiomyopathy", keyFacts: "A stiff, non-compliant ventricle causing impaired filling and diastolic heart failure with preserved contraction.", epidemiology: "The least common of the cardiomyopathies.", aetiology: "Amyloidosis (commonest), sarcoidosis, haemochromatosis, endomyocardial fibrosis and radiation.", pathophysiology: "Infiltration or fibrosis stiffens the ventricular walls, restricting diastolic filling and raising filling pressures despite normal systolic function.", presentation: "Predominantly right heart failure (raised JVP, ascites, oedema) with exertional breathlessness; it can mimic constrictive pericarditis.", investigations: "Echocardiography, cardiac MRI, ECG (low voltage in amyloid), and tests for the underlying cause including biopsy.", treatment: "Treat the underlying infiltrative disease; cautious diuresis for congestion; transplantation in selected cases." },
      { id: "haem_amyloidosis", cluster: "Heart failure & cardiomyopathies", name: "Amyloidosis", keyFacts: "Deposition of misfolded protein (amyloid) in tissues causing progressive multi-organ failure; cardiac infiltration produces a restrictive cardiomyopathy.", epidemiology: "Uncommon; AL type is linked to plasma-cell disease, AA to chronic inflammation, and ATTR to ageing or a hereditary mutation.", aetiology: "A family of diseases grouped by the precursor protein. AL (primary) amyloidosis comes from monoclonal immunoglobulin light chains made by a plasma-cell clone (myeloma or MGUS) and is the type most associated with cardiac and renal disease. AA (secondary) amyloidosis arises from the acute-phase protein serum amyloid A in chronic inflammation - rheumatoid arthritis, inflammatory bowel disease, chronic infection (tuberculosis, bronchiectasis) and familial Mediterranean fever - and chiefly affects the kidneys. ATTR amyloidosis is from transthyretin, either wild-type (senile, in older men, mainly cardiac) or hereditary (a mutated TTR gene causing cardiac and neuropathic disease). Beta-2-microglobulin amyloid complicates long-term dialysis.", pathophysiology: "In every type a normally soluble precursor protein misfolds and aggregates into insoluble beta-pleated-sheet fibrils that resist breakdown and deposit in the extracellular space of many organs, staining with Congo red and showing apple-green birefringence under polarised light. Progressive deposition disrupts tissue architecture: in the heart it stiffens the ventricular walls to cause a restrictive cardiomyopathy and conduction disease; in the kidney it damages the glomerulus, causing heavy proteinuria; in peripheral and autonomic nerves it causes a neuropathy; and in the gut it impairs motility and absorption.", presentation: "The picture depends on which organs are infiltrated. Cardiac: a restrictive cardiomyopathy with predominantly right-sided heart failure (raised JVP, oedema, ascites), arrhythmias and heart block, and a low-voltage ECG despite thick walls on echo, with sensitivity to ACE inhibitors. Renal: nephrotic-range proteinuria and progressive renal failure. Neurological: a symmetrical peripheral neuropathy, bilateral carpal tunnel syndrome (often an early clue) and autonomic failure (postural hypotension, erectile dysfunction). Gastrointestinal: macroglossia (an enlarged tongue, characteristic of AL amyloid), malabsorption and hepatomegaly. Skin: periorbital purpura ('raccoon eyes') and easy bruising from vascular fragility.", investigations: "Biopsy with Congo red staining (apple-green birefringence under polarised light); serum and urine electrophoresis and serum free light chains for AL; echocardiography and cardiac MRI; ECG (low voltages); a SAP (serum amyloid P component) scan; genetic testing for hereditary ATTR.", treatment: "Treat the underlying process - chemotherapy against the plasma-cell clone in AL, control of inflammation in AA, and transthyretin stabilisers (tafamidis) or gene-silencing agents in ATTR; supportive care of heart failure (cautious diuretics; avoid digoxin and calcium-channel blockers in cardiac amyloid), and of renal and neurological complications; organ transplant in selected cases." },
      { id: "cvs_arvc", cluster: "Heart failure & cardiomyopathies", name: "Arrhythmogenic right ventricular cardiomyopathy", keyFacts: "Inherited replacement of right ventricular muscle by fat and fibrosis, predisposing to ventricular arrhythmia and sudden death in young athletes.", epidemiology: "An uncommon but important inherited cause of sudden cardiac death in the young.", aetiology: "Autosomal dominant mutations in desmosomal proteins.", pathophysiology: "Fibrofatty replacement of the right ventricular wall creates an arrhythmogenic substrate, causing ventricular tachycardia and progressive right ventricular failure.", presentation: "Palpitations, syncope or sudden death, often during exercise, with later right heart failure.", investigations: "ECG (T-wave inversion in V1 to V3, epsilon wave), echocardiography and cardiac MRI; genetic testing and family screening.", treatment: "Avoid competitive sport; beta-blockers and antiarrhythmics; an implantable defibrillator for high-risk patients; catheter ablation for recurrent ventricular tachycardia." },
      { id: "cvs_takotsubo", cluster: "Heart failure & cardiomyopathies", name: "Takotsubo cardiomyopathy", keyFacts: "Transient stress-induced left ventricular apical ballooning that mimics an acute myocardial infarction but with unobstructed coronary arteries.", epidemiology: "Predominantly affects postmenopausal women, typically after acute emotional or physical stress.", aetiology: "An intense catecholamine surge, usually triggered by emotional or physical stress (broken-heart syndrome).", pathophysiology: "A catecholamine surge causes transient myocardial stunning, classically apical ballooning with a hyperdynamic base, usually reversible over weeks.", presentation: "Acute chest pain and breathlessness with ECG changes and a troponin rise after a stressful trigger, clinically indistinguishable from a myocardial infarction.", investigations: "ECG (ST changes), troponin, and coronary angiography showing unobstructed arteries with characteristic apical ballooning on ventriculography or echocardiography.", treatment: "Supportive heart failure treatment; it usually recovers fully; manage complications and address the precipitating stressor." },
      { id: "cvs_af", management: {"def": "A[\"Atrial fibrillation\"]:::start --> B{\"Haemodynamically unstable?\"}:::decision\nB -- \"yes\" --> C[\"Emergency synchronised DC cardioversion\"]:::danger\nB -- \"no\" --> D[\"Manage stroke risk and rate/rhythm separately\"]:::process\nD --> E[\"Stroke risk CHA2DS2-VASc; bleeding risk ORBIT\"]:::process\nE --> F{\"Anticoagulate?\"}:::decision\nF -- \"2+ men / 1+ women\" --> G[\"DOAC first-line\"]:::good\nF -- \"0 in men\" --> H[\"No anticoagulation\"]:::good\nD --> I{\"Rate or rhythm control?\"}:::decision\nI -- \"first-line for most\" --> J[\"Rate: beta-blocker or diltiazem/verapamil\"]:::good\nI -- \"AF-related HF, new-onset, reversible cause, or still symptomatic\" --> K[\"Rhythm control\"]:::good\nK --> L{\"Cardioversion\"}:::decision\nL -- \"electrical\" --> M[\"DC cardioversion (anticoagulate 3 weeks or TOE if over 48h)\"]:::good\nL -- \"pharmacological\" --> N[\"Flecainide (no structural/IHD) or amiodarone (structural)\"]:::good\nK --> O[\"Maintain sinus rhythm; catheter ablation if drugs fail\"]:::warn", "tips": {"A": "Irregularly irregular pulse confirmed on ECG (absent P waves). Manage stroke prevention and rate/rhythm control as separate decisions (NICE NG196).", "B": "First assess haemodynamic stability - look for life-threatening features: shock, syncope, myocardial ischaemia or heart failure.", "C": "Life-threatening instability: immediate emergency electrical (synchronised DC) cardioversion, without delaying for anticoagulation.", "D": "In the stable patient, address two things in parallel - preventing stroke, and controlling rate or rhythm.", "E": "Stroke risk by CHA2DS2-VASc (cardiac failure, hypertension, age 65/75, diabetes, prior stroke/TIA, vascular disease, sex); bleeding risk by ORBIT (NICE-preferred). Modify reversible bleeding risks rather than withholding anticoagulation.", "F": "Decide anticoagulation on stroke risk, independent of the rate/rhythm strategy.", "G": "A DOAC first-line (apixaban, dabigatran, edoxaban, rivaroxaban); warfarin only if a mechanical valve or moderate-to-severe mitral stenosis. Aspirin is not used for stroke prevention in AF.", "H": "No anticoagulation if CHA2DS2-VASc is 0 in men (or 1 in women where the only point is female sex).", "I": "Offer rate control first-line for most people.", "J": "Rate control: a standard beta-blocker (not sotalol) or a rate-limiting calcium-channel blocker (diltiazem or verapamil). Digoxin monotherapy only if sedentary or in heart failure; combine drugs if one agent fails.", "K": "Choose rhythm control if AF is causing heart failure, is new-onset (under 48 hours), has a reversible cause, or symptoms persist despite rate control.", "L": "Cardioversion may be electrical or pharmacological. If AF has lasted over 48 hours, anticoagulate for at least 3 weeks first (or use TOE-guided cardioversion) and continue anticoagulation for at least 4 weeks afterwards.", "M": "Electrical: synchronised direct-current cardioversion under sedation or anaesthesia - preferred when AF is over 48 hours.", "N": "Pharmacological cardioversion: flecainide (or propafenone) if there is no structural or ischaemic heart disease; amiodarone if there is structural heart disease. For paroxysmal AF a 'pill-in-the-pocket' flecainide/propafenone strategy suits infrequent episodes with no LV, valvular or ischaemic disease.", "O": "To maintain sinus rhythm long-term: a standard beta-blocker first-line, then dronedarone, amiodarone (especially with LV impairment/heart failure), sotalol or flecainide by comorbidity. Offer catheter ablation if drug treatment fails."}}, cluster: "Arrhythmias & conduction disease", name: "Atrial fibrillation", keyFacts: "The commonest sustained arrhythmia; an irregularly irregular pulse whose chief danger is cardioembolic stroke.", epidemiology: "Prevalence rises sharply with age, affecting roughly 1 in 10 people over 75.", aetiology: "Hypertension, ischaemic heart disease, valvular and heart failure, hyperthyroidism, alcohol, sepsis and pulmonary disease.", pathophysiology: "Disorganised atrial electrical activity replaces coordinated contraction, so loss of atrial systole and stasis in the left atrial appendage predispose to thrombus formation.", presentation: "Palpitations, breathlessness, irregularly irregular pulse; may be incidental.", investigations: "ECG (absent P waves), TFTs, U&E, echocardiogram.", treatment: "Rate control with bisoprolol or diltiazem; anticoagulate by CHA₂DS₂-VASc balanced against ORBIT/HAS-BLED; DOAC first line." },
      { id: "cvs_atrial_flutter", cluster: "Arrhythmias & conduction disease", name: "Atrial flutter", keyFacts: "A regular atrial tachyarrhythmia, classically with a sawtooth baseline and a ventricular rate often around 150 (2:1 block).", epidemiology: "Commoner with age and structural heart or lung disease, and it often coexists with atrial fibrillation.", aetiology: "Hypertension, ischaemic heart disease, valve disease, COPD, thyrotoxicosis and cardiac surgery.", pathophysiology: "A macro-re-entry circuit, usually around the tricuspid annulus, drives a fast regular atrial rate that the AV node blocks in fixed ratios.", presentation: "Palpitations, breathlessness and chest discomfort, though it may be asymptomatic.", investigations: "ECG (sawtooth flutter waves with a regular rhythm), thyroid function tests and echocardiography.", treatment: "Rate control and anticoagulation as for atrial fibrillation (by CHA2DS2-VASc); cardioversion; catheter ablation is highly effective and often curative." },
      { id: "cvs_svt", management: {"source": "Resus Council UK", "def": "A[\"Supraventricular tachycardia (regular narrow complex)\"]:::start --> B{\"Adverse signs? (shock, syncope, ischaemia, HF)\"}:::decision\nB -- \"yes (unstable)\" --> C[\"Synchronised DC cardioversion\"]:::danger\nB -- \"no (stable)\" --> D[\"Vagal manoeuvres (modified Valsalva)\"]:::good\nD -- \"no response\" --> E[\"IV adenosine 6 mg, then 12 mg, then 18 mg\"]:::good\nE -- \"no response\" --> F[\"Rate control: verapamil or beta-blocker\"]:::warn\nE --> G[\"Reverts: monitor, consider ablation\"]:::process", "tips": {"A": "A regular narrow-complex tachycardia (e.g. AV nodal re-entry); follow the Resuscitation Council adult tachycardia algorithm.", "B": "First decide if the patient is stable - look for shock, syncope, myocardial ischaemia or heart failure.", "C": "Unstable (adverse features): urgent synchronised DC cardioversion with sedation, up to 3 attempts, then amiodarone.", "D": "Stable: try vagal manoeuvres first - a modified Valsalva is most effective; carotid sinus massage if no bruit.", "E": "If vagal fails, give IV adenosine as a rapid bolus (6 mg, then 12 mg, then 18 mg) with continuous ECG - warn about transient chest tightness/flushing. Avoid in asthma (use verapamil).", "F": "If adenosine fails, get expert help and consider rate control (verapamil or a beta-blocker) - do not combine IV verapamil with a beta-blocker.", "G": "If it reverts, monitor and refer for electrophysiology and catheter ablation if recurrent or symptomatic."}}, cluster: "Arrhythmias & conduction disease", name: "Supraventricular tachycardia", keyFacts: "A regular narrow-complex tachycardia arising above the ventricles, usually from a re-entry circuit and typically paroxysmal.", epidemiology: "Can occur at any age, often in otherwise healthy young adults, and is somewhat commoner in women.", aetiology: "Re-entry, most often atrioventricular nodal re-entrant tachycardia or an accessory pathway (Wolff-Parkinson-White); triggers include caffeine, alcohol and stress.", pathophysiology: "A self-sustaining electrical re-entry loop drives rapid, regular atrial and ventricular rates, shortening diastolic filling time.", presentation: "Sudden palpitations, regular narrow-complex tachycardia, sometimes chest discomfort.", investigations: "ECG during episode, TFTs, electrolytes.", treatment: "Vagal manoeuvres then IV adenosine; cardioversion if unstable; consider ablation for recurrence." },
      { id: "cvs_wpw", cluster: "Arrhythmias & conduction disease", name: "Wolff-Parkinson-White syndrome", keyFacts: "A congenital accessory pathway that pre-excites the ventricle, predisposing to tachyarrhythmias; the ECG shows a short PR interval and a delta wave.", epidemiology: "Usually presents in young, otherwise healthy people.", aetiology: "A congenital accessory atrioventricular pathway, the bundle of Kent.", pathophysiology: "The accessory pathway bypasses the AV node, allowing re-entry tachycardia; atrial fibrillation conducted down it can be dangerously fast.", presentation: "Palpitations and episodes of supraventricular tachycardia, and occasionally syncope or sudden death.", investigations: "ECG (short PR interval, delta wave, widened QRS) and an electrophysiological study to localise the pathway.", treatment: "Acute supraventricular tachycardia is treated with vagal manoeuvres or adenosine (avoid AV-blocking drugs if atrial fibrillation with pre-excitation); definitive treatment is catheter ablation of the pathway." },
      { id: "cvs_vt", management: {"source": "Resus Council UK", "def": "A[\"Ventricular tachycardia (broad complex)\"]:::start --> B{\"Pulse present?\"}:::decision\nB -- \"no pulse\" --> C[\"Treat as cardiac arrest (defibrillate)\"]:::danger\nB -- \"pulse, adverse signs\" --> D[\"Synchronised DC cardioversion\"]:::danger\nB -- \"pulse, stable\" --> E[\"IV amiodarone 300 mg\"]:::good\nD --> F[\"Amiodarone, then repeat cardioversion\"]:::good\nE --> G[\"Correct electrolytes, treat cause\"]:::good\nG --> H[\"Torsades: IV magnesium sulfate\"]:::warn", "tips": {"A": "A broad-complex tachycardia (QRS over 120 ms) - assume ventricular tachycardia until proven otherwise; the first question is whether there is a pulse.", "B": "Check for a pulse and for adverse features (shock, syncope, myocardial ischaemia, heart failure).", "C": "Pulseless VT is a cardiac arrest - defibrillate on the shockable arm of ALS.", "D": "VT with a pulse and adverse signs (unstable): urgent synchronised DC cardioversion (up to 3 attempts) with sedation.", "E": "VT with a pulse and stable: IV amiodarone 300 mg over 20-60 minutes (large or central vein), then an infusion.", "F": "If cardioversion fails, give amiodarone and repeat synchronised cardioversion.", "G": "Correct precipitants (potassium and magnesium) and treat ischaemia; get expert help.", "H": "For polymorphic VT with a long QT (torsades de pointes): IV magnesium sulfate and stop QT-prolonging drugs."}}, cluster: "Arrhythmias & conduction disease", name: "Ventricular tachycardia (monomorphic)", keyFacts: "A regular broad-complex tachycardia from a single ventricular focus (uniform QRS); a peri-arrest emergency that can degenerate into ventricular fibrillation.", epidemiology: "Most often in patients with structural heart disease, especially ischaemic scar after a myocardial infarction.", aetiology: "Re-entry around ischaemic scar (post-myocardial infarction) is commonest; also cardiomyopathy, electrolyte disturbance (low potassium or magnesium) and some drugs.", pathophysiology: "A re-entry circuit around ventricular scar, or an automatic focus, drives a rapid regular ventricular rhythm that impairs filling and cardiac output.", presentation: "Palpitations, chest pain, breathlessness, presyncope or collapse; it may be pulseless and present as cardiac arrest.", investigations: "ECG (a regular broad-complex tachycardia with features such as capture and fusion beats and concordance), electrolytes, and assessment for underlying structural heart disease.", treatment: "Pulseless VT is defibrillated under Advanced Life Support; unstable VT with a pulse needs synchronised DC cardioversion; stable VT is treated with amiodarone; correct electrolytes, and consider an implantable defibrillator and catheter ablation." },
      { id: "cvs_tdp", management: {"source": "Resus Council UK", "def": "A[\"Polymorphic VT / torsades de pointes\"]:::start --> B{\"Pulse and stability?\"}:::decision\nB -- \"pulseless\" --> C[\"Defibrillate (unsynchronised) - treat as cardiac arrest\"]:::danger\nB -- \"pulse but unstable\" --> D[\"Urgent shock - unsynchronised, as sync often fails\"]:::danger\nB -- \"pulse, stable\" --> E{\"QT interval on ECG?\"}:::decision\nE -- \"long QT = torsades\" --> F[\"IV magnesium sulfate 2 g over 10 min\"]:::good\nF --> G[\"Stop QT-prolonging drugs; correct K+ and Mg2+\"]:::good\nG --> H[\"Recurrent/pause-dependent: overdrive pacing or isoprenaline\"]:::warn\nE -- \"normal QT (ischaemic)\" --> I[\"Treat ischaemia; beta-blocker; amiodarone\"]:::good", "tips": {"A": "A polymorphic (varying QRS) broad-complex tachycardia; torsades de pointes is the long-QT subtype. Management hinges on the pulse, stability and the QT interval (Resuscitation Council UK peri-arrest framework).", "B": "Assess immediately - is there a pulse, and if so is the patient stable (no shock, syncope, myocardial ischaemia or heart failure)?", "C": "Pulseless polymorphic VT is a cardiac arrest - defibrillate (unsynchronised) on the shockable arm of Advanced Life Support.", "D": "Unstable with a pulse: deliver an urgent shock. Synchronising to the constantly varying QRS usually fails, so an unsynchronised (defibrillation) shock is used.", "E": "In the stable patient, measure the QT interval on the baseline or post-episode ECG - this separates torsades (long QT) from ischaemic polymorphic VT (normal QT).", "F": "Torsades: IV magnesium sulfate 2 g over 10 minutes is first-line, given even if the serum magnesium is normal.", "G": "Stop every QT-prolonging drug and correct potassium and magnesium; avoid QT-prolonging antiarrhythmics such as amiodarone and sotalol in torsades.", "H": "For recurrent or bradycardia-/pause-dependent torsades, raise the heart rate to shorten the QT with temporary overdrive pacing or an isoprenaline infusion; consider an implantable cardioverter-defibrillator for congenital long QT.", "I": "Normal QT (usually acute ischaemia): treat the ischaemia (revascularise) and give a beta-blocker; amiodarone is an option in this setting."}}, cluster: "Arrhythmias & conduction disease", name: "Polymorphic VT & torsades de pointes", keyFacts: "A broad-complex tachycardia whose QRS complexes continuously vary in amplitude and axis; torsades de pointes ('twisting of the points') is the subtype seen with a prolonged QT interval. It is haemodynamically unstable, often self-terminating but prone to recur and to degenerate into ventricular fibrillation.", epidemiology: "Less common than monomorphic ventricular tachycardia. Torsades arises in congenital long QT syndromes and, more often, from acquired QT prolongation (drugs and electrolyte disturbance); polymorphic VT with a normal QT usually complicates acute myocardial ischaemia.", aetiology: "Classified by the QT interval. Long QT (torsades): congenital long QT syndromes, or acquired QT prolongation from drugs (antiarrhythmics such as sotalol and amiodarone, macrolide and quinolone antibiotics, antipsychotics, methadone, ondansetron, tricyclics), electrolyte disturbance (hypokalaemia, hypomagnesaemia, hypocalcaemia), marked bradycardia or complete heart block, and hypothyroidism. Normal QT: acute myocardial ischaemia or infarction (the commonest cause), and catecholaminergic polymorphic VT.", pathophysiology: "In torsades, delayed ventricular repolarisation (the long QT) permits early afterdepolarisations that trigger a re-entrant circuit whose exit point continuously shifts, so the QRS axis appears to twist around the baseline. Rapid, disorganised ventricular activation impairs filling and output, and the rhythm often degenerates into ventricular fibrillation. In ischaemic polymorphic VT, regional differences in repolarisation across ischaemic myocardium create the unstable circuits.", presentation: "Palpitations, dizziness, recurrent syncope (classically in long QT syndrome, sometimes triggered by exertion, emotion or a sudden loud noise) and collapse; it may present as cardiac arrest. Episodes are often paroxysmal and self-limiting but recurrent.", investigations: "ECG shows a polymorphic broad-complex tachycardia with a continuously varying QRS amplitude and axis (torsades twists around the baseline); examine the corrected QT interval (QTc) on the baseline or post-episode ECG. Check potassium, magnesium and calcium, review the drug chart for QT-prolonging agents, and assess for ischaemia (ECG, troponin). Consider thyroid function, and after recovery arrange genetic testing and family screening for inherited long QT.", treatment: "Pulseless polymorphic VT is a cardiac arrest - defibrillate under Advanced Life Support. Unstable VT with a pulse needs an urgent shock, usually unsynchronised because synchronisation to the varying QRS often fails. For torsades (long QT): give IV magnesium sulfate (2 g over 10 minutes), stop all QT-prolonging drugs, correct potassium and magnesium, and for recurrent or bradycardia-dependent episodes use overdrive pacing or an isoprenaline infusion to raise the rate and shorten the QT. Polymorphic VT with a normal QT is usually ischaemic - treat the ischaemia and give a beta-blocker or amiodarone. Correct the underlying cause and consider an implantable cardioverter-defibrillator for inherited or recurrent disease." },
      { id: "cvs_vf", management: {"source": "Resus Council UK", "def": "A[\"Ventricular fibrillation (pulseless)\"]:::start --> B[\"Confirm cardiac arrest; CPR 30:2, call arrest team, attach defibrillator\"]:::danger\nB --> C[\"Shockable rhythm: single shock, then CPR 2 min\"]:::good\nC --> D{\"Reassess rhythm every 2 min\"}:::decision\nD -- \"still VF / pulseless VT\" --> E[\"Further shock, then 2 min CPR\"]:::good\nE --> F[\"After 3rd shock: adrenaline 1 mg + amiodarone 300 mg IV\"]:::good\nF --> G[\"Adrenaline every 3-5 min; amiodarone 150 mg after 5th shock\"]:::good\nD -- \"throughout\" --> H[\"Seek and treat reversible causes: 4 Hs and 4 Ts\"]:::warn\nD -- \"ROSC\" --> I[\"Post-resuscitation care; consider ICD\"]:::good", "tips": {"A": "A shockable, pulseless cardiac arrest rhythm - chaotic ventricular activity with no output. Immediate defibrillation is the single most important treatment (Resuscitation Council UK Advanced Life Support).", "B": "Confirm arrest (unresponsive, not breathing normally, no pulse), start high-quality CPR at 30:2, call the arrest team and attach a defibrillator/monitor without delay.", "C": "For a shockable rhythm (VF or pulseless VT) give a single unsynchronised shock and immediately resume CPR for 2 minutes before reassessing - minimise interruptions to compressions.", "D": "Pause briefly every 2 minutes to reassess the rhythm and check for return of spontaneous circulation (ROSC).", "E": "If still shockable, deliver a further shock and resume 2 minutes of CPR.", "F": "Give adrenaline 1 mg IV and amiodarone 300 mg IV after the third shock (lidocaine is an alternative if amiodarone is unavailable).", "G": "Repeat adrenaline 1 mg every 3-5 minutes (every other cycle) and give a further amiodarone 150 mg after the fifth shock.", "H": "Throughout, seek and correct reversible causes - the 4 Hs (hypoxia, hypovolaemia, hypo/hyperkalaemia and metabolic, hypothermia) and 4 Ts (thrombosis - usually coronary, tension pneumothorax, tamponade, toxins).", "I": "On ROSC: structured post-resuscitation care (ABCDE, 12-lead ECG, treat the cause, targeted temperature management). Survivors of VF arrest not due to a reversible cause usually need an implantable cardioverter-defibrillator (ICD)."}}, cluster: "Arrhythmias & conduction disease", name: "Ventricular fibrillation", keyFacts: "A pulseless, shockable cardiac arrest rhythm: chaotic, disorganised ventricular electrical activity with no effective contraction and therefore no cardiac output. It is the commonest initial rhythm in witnessed sudden cardiac death and the most survivable, provided defibrillation is early.", epidemiology: "The most frequent shockable rhythm in out-of-hospital cardiac arrest, particularly in the early hours after an acute coronary event; the chance of successful defibrillation falls by roughly 10% with every minute of delay.", aetiology: "Acute myocardial ischaemia or infarction is the commonest trigger; others are degeneration from ventricular tachycardia, electrolyte disturbance (hypokalaemia, hyperkalaemia, hypomagnesaemia), inherited channelopathies (long QT and Brugada syndromes), cardiomyopathy and structural heart disease, electrocution, hypothermia, and drug toxicity.", pathophysiology: "Multiple disorganised re-entrant wavelets depolarise the ventricular myocardium chaotically and asynchronously, so there is no coordinated contraction - the ventricles merely quiver, stroke volume is zero and perfusion ceases, causing irreversible brain injury within minutes unless circulation is restored.", presentation: "Sudden collapse with loss of consciousness, absent or agonal (gasping) breathing and no palpable pulse - clinically a cardiac arrest; it may be preceded by chest pain or palpitations when the cause is ischaemic.", investigations: "Immediate rhythm recognition on the defibrillator or monitor is paramount - a chaotic, irregular waveform of varying amplitude (coarse or fine) with no identifiable QRS complexes. After return of spontaneous circulation, seek the cause with a 12-lead ECG, troponin, electrolytes and an arterial blood gas, and arrange urgent coronary angiography if ischaemia is suspected.", treatment: "Immediate defibrillation is the definitive treatment. Follow the Resuscitation Council UK Advanced Life Support shockable arm: high-quality CPR at 30:2, a single unsynchronised shock followed by 2 minutes of CPR, adrenaline 1 mg and amiodarone 300 mg intravenously after the third shock (then adrenaline every 3-5 minutes and a further amiodarone 150 mg after the fifth shock), while seeking and treating reversible causes (the 4 Hs and 4 Ts). Provide structured post-resuscitation care after return of spontaneous circulation, and consider an implantable cardioverter-defibrillator in survivors whose VF was not due to a reversible cause." },
      { id: "cvs_bradycardia", management: {"def": "A[\"Heart rate below 60: bradycardia\"]:::start --> B[\"12-lead ECG: classify the rhythm\"]:::process\nB --> C{\"Adverse features? shock, syncope, ischaemia, heart failure\"}:::decision\nC -- \"yes\" --> D[\"Peri-arrest: IV atropine 500 micrograms\"]:::danger\nD --> E[\"Repeat atropine to 3 mg, then pacing or isoprenaline infusion\"]:::warn\nC -- \"no\" --> F[\"Look for a reversible cause\"]:::process\nF --> G[\"Stop or reduce rate-limiting drugs\"]:::good\nG --> H[\"Correct hyperkalaemia, hypothyroidism, hypothermia, ischaemia\"]:::good\nE --> H\nH --> I{\"Still symptomatic, or high-risk conduction block?\"}:::decision\nI -- \"no\" --> J[\"Observe, monitor, keep drugs under review\"]:::good\nI -- \"yes\" --> K[\"Refer for permanent pacemaker\"]:::good", "tips": {"A": "Bradycardia is a resting heart rate below 60 beats per minute. It is often physiological (athletes, sleep, high vagal tone) and needs no treatment; the task is to identify the minority who are compromised or have dangerous conduction disease.", "B": "A 12-lead ECG classifies the mechanism, which drives everything else: sinus bradycardia, sinus pauses or arrest, a junctional escape rhythm, or first-, second- (Mobitz I or II) or third-degree atrioventricular block.", "C": "Assess immediately for the Resuscitation Council UK adverse features: shock (hypotension, pallor, sweating, confusion), syncope, myocardial ischaemia, and heart failure. Their presence makes this a peri-arrest emergency.", "D": "With adverse features, follow the Resuscitation Council UK bradycardia algorithm: IV atropine 500 micrograms as the first drug (see also the Heart block entry, which carries the full algorithm).", "E": "If atropine is insufficient, repeat 500 microgram doses to a maximum of 3 mg, then move to transcutaneous pacing or a second-line drug such as an isoprenaline or adrenaline infusion, with expert help and transvenous pacing for high-grade block.", "F": "Without adverse features there is time to investigate: review every drug, and check U and Es, glucose, thyroid function and troponin. Consider ambulatory monitoring or a loop recorder if symptoms are intermittent.", "G": "Drugs are the commonest reversible cause: beta-blockers, rate-limiting calcium-channel blockers (verapamil, diltiazem), digoxin, amiodarone, ivabradine and cholinesterase inhibitors. Stopping or reducing the culprit often resolves the bradycardia.", "H": "Correct the other reversible causes: hyperkalaemia, hypothyroidism, hypothermia, raised intracranial pressure and acute ischaemia (inferior myocardial infarction classically causes atrioventricular nodal block, which is often transient).", "I": "Reassess once reversible causes are treated. Persisting symptoms, or an intrinsically high-risk block, mean the bradycardia will not be safely managed by observation alone.", "J": "Asymptomatic bradycardia with a benign rhythm (sinus bradycardia, or first-degree or Mobitz I block) needs only observation, with the drug list kept under review.", "K": "Permanent pacing is indicated for symptomatic sinus node disease and for high-risk conduction block - complete (third-degree) heart block, Mobitz type II block, and symptomatic pauses - once reversible causes are excluded."}, "source": "Resus Council UK / ESC"}, cluster: "Arrhythmias & conduction disease", name: "Bradycardia", keyFacts: "A resting heart rate below 60 beats per minute; frequently physiological and benign, but pathological bradycardia causing syncope or haemodynamic compromise is a peri-arrest emergency and may need permanent pacing.", epidemiology: "Very common. Physiological in athletes and during sleep; pathological bradycardia becomes commoner with age as the conduction system fibroses, and drug-induced bradycardia is frequent in older people taking rate-limiting drugs.", aetiology: "Physiological: athletic training, sleep and high vagal tone. Intrinsic conduction disease: sinus node dysfunction (sick sinus syndrome) and atrioventricular block from age-related fibrosis. Drugs: beta-blockers, verapamil and diltiazem, digoxin, amiodarone, ivabradine and cholinesterase inhibitors. Other: hypothyroidism, hyperkalaemia, hypothermia, raised intracranial pressure (Cushing reflex), obstructive sleep apnoea, inferior myocardial infarction, and infections such as Lyme carditis and typhoid.", pathophysiology: "Either reduced automaticity of the sinoatrial node or failure of conduction through the atrioventricular node and His-Purkinje system. Since cardiac output is heart rate multiplied by stroke volume, a healthy heart compensates by increasing stroke volume; when it cannot, cerebral and coronary perfusion fall, producing dizziness, syncope and myocardial ischaemia.", presentation: "Often asymptomatic and found incidentally. Symptomatic bradycardia causes fatigue, exercise intolerance, dizziness, presyncope and syncope. The Resuscitation Council adverse features are shock, syncope, myocardial ischaemia and heart failure. Sinus node disease may alternate with fast rhythms (tachy-brady syndrome), and complete heart block can cause Stokes-Adams attacks.", investigations: "A 12-lead ECG classifies the rhythm (sinus bradycardia, sinus pauses, junctional escape, or first-, second- or third-degree atrioventricular block); U and Es, glucose, thyroid function and troponin; a full drug review; ambulatory (Holter) monitoring or an implantable loop recorder for intermittent symptoms; echocardiography for structural disease; exercise testing if chronotropic incompetence is suspected.", treatment: "Treat the cause and withhold rate-limiting drugs. If adverse features are present, follow the Resuscitation Council UK bradycardia algorithm: IV atropine 500 micrograms repeated to a maximum of 3 mg, then transcutaneous pacing or an isoprenaline or adrenaline infusion, with transvenous pacing for high-grade block. Correct hyperkalaemia, hypothyroidism and hypothermia, and give specific antidotes in overdose (glucagon or high-dose insulin for beta-blockers, calcium and insulin-dextrose for calcium-channel blockers, digoxin-specific antibody fragments). Persistent symptomatic bradycardia, complete heart block or Mobitz type II block warrants a permanent pacemaker." },
      { id: "cvs_heart_block", management: {"source": "Resus Council UK", "def": "A[\"Bradycardia or heart block\"]:::start --> B{\"Adverse signs? (shock, syncope, ischaemia, HF)\"}:::decision\nB -- \"yes\" --> C[\"IV atropine 500 micrograms\"]:::good\nC -- \"no response\" --> D[\"Repeat atropine (to 3 mg), then pacing\"]:::warn\nD --> E[\"Isoprenaline or adrenaline infusion\"]:::good\nB -- \"no, but asystole risk\" --> F[\"Observe, prepare for pacing\"]:::process\nE --> G[\"Transvenous pacing for high-grade block\"]:::good", "tips": {"A": "Follow the Resuscitation Council UK bradycardia algorithm; treatment is driven by adverse features and the risk of asystole.", "B": "Look for adverse signs: shock, syncope, myocardial ischaemia or heart failure.", "C": "If adverse signs are present: IV atropine 500 micrograms, repeated as needed.", "D": "No response to atropine (or high risk): repeat atropine up to a total of 3 mg and start transcutaneous (external) pacing, with analgesia and sedation.", "E": "While arranging definitive pacing, an isoprenaline or adrenaline infusion (or other second-line drug) can maintain the rate; get expert help.", "F": "Even without adverse signs, watch for asystole risk (recent asystole, Mobitz II, complete heart block with broad QRS, ventricular pauses over 3 seconds) and prepare for pacing.", "G": "High-grade AV block (Mobitz II, complete heart block) needs transvenous pacing and usually a permanent pacemaker."}}, cluster: "Arrhythmias & conduction disease", name: "Heart block", keyFacts: "Impaired conduction of the atrial impulse to the ventricles, graded by severity. First-degree: every impulse conducts but is delayed. Second-degree Mobitz I (Wenckebach): progressive delay until a beat is dropped. Second-degree Mobitz II: intermittent sudden dropped beats without prior delay. Third-degree (complete): no atrial impulse reaches the ventricles, which depend on an escape rhythm.", epidemiology: "First-degree block and Mobitz I are common and can be normal in young, athletic or sleeping people with high vagal tone. Mobitz II, high-grade and third-degree block are less common, rise with age-related fibrosis of the conduction system, and usually indicate significant disease. Complete heart block is a recognised complication of acute (especially inferior) myocardial infarction and of degenerative conduction disease in the elderly.", aetiology: "Shared contributors are age-related conduction-system fibrosis, ischaemia, atrioventricular-nodal blocking drugs (beta-blockers, diltiazem or verapamil, digoxin, adenosine, amiodarone), electrolyte disturbance and high vagal tone. First-degree and Mobitz I: often high vagal tone (athletes, sleep), inferior myocardial infarction, or the drugs above, and the block is usually within the atrioventricular node. Mobitz II: almost always structural His-Purkinje disease (anterior myocardial infarction, or degenerative fibrosis - Lenegre-Lev disease). Third-degree: inferior or anterior myocardial infarction, degenerative fibrosis, cardiac surgery or transcatheter aortic valve implantation, and infiltrative disease; congenital complete block is linked to maternal anti-Ro/anti-La antibodies. Lyme carditis is an important reversible cause at any grade.", pathophysiology: "First-degree: conduction is slowed but every atrial impulse still reaches the ventricles, giving a fixed long PR interval. Mobitz I: decremental atrioventricular-nodal conduction lengthens the PR beat by beat until one impulse fails, then the cycle resets, and the escape rhythm (if needed) is usually reliable. Mobitz II: an all-or-nothing block in the His-Purkinje system means impulses either conduct normally or fail abruptly, often with a broad QRS and an unstable escape, so it readily progresses to complete block. Third-degree: complete atrioventricular dissociation - the atria and ventricles beat independently, the ventricles driven by a subsidiary pacemaker (junctional, narrow QRS at 40-60 per minute, or ventricular, broad QRS at 20-40) that is slow and unreliable.", presentation: "First-degree: asymptomatic, found incidentally on an ECG. Mobitz I: usually asymptomatic, occasionally palpitations or dropped beats. Mobitz II: dizziness, presyncope, palpitations and fatigue, with a risk of progressing to complete block. Third-degree: marked bradycardia, syncope (Stokes-Adams attacks - abrupt collapse from a ventricular standstill), presyncope, fatigue, breathlessness and heart failure, with a risk of asystole and sudden death; signs of atrioventricular dissociation include cannon A waves and a variable-intensity first heart sound.", investigations: "The ECG grades the block. First-degree: a fixed PR interval over 200 milliseconds. Mobitz I: progressive PR lengthening then a dropped QRS (grouped beating). Mobitz II: a constant PR with intermittent non-conducted P waves (often 2:1 conduction, frequently a broad QRS). Third-degree: complete atrioventricular dissociation, with P waves and QRS complexes at independent rates. In every case check electrolytes, thyroid function, a digoxin level and other rate-slowing drugs, and troponin if ischaemia is suspected; use ambulatory (Holter) monitoring for intermittent symptoms, echocardiography for structural disease, and Lyme serology where exposure is possible.", treatment: "Treat reversible causes first - stop or reduce culprit drugs, correct electrolytes, and treat ischaemia or Lyme carditis. First-degree and asymptomatic Mobitz I: no treatment, just observation. Acute symptomatic bradycardia: follow the Resuscitation Council UK bradycardia algorithm - IV atropine 500 micrograms (repeated to a maximum of 3 mg), then transcutaneous pacing or an isoprenaline or adrenaline infusion as a bridge. Mobitz II and third-degree (complete) block: admit for cardiac monitoring and arrange a permanent pacemaker, as the risk of asystole is high (temporary transvenous pacing if unstable, or while awaiting recovery when block complicates acute myocardial infarction)." },
      { id: "cvs_rbbb", cluster: "Arrhythmias & conduction disease", name: "Right bundle branch block", keyFacts: "Delayed conduction to the right ventricle, giving a broad QRS with an RSR pattern in V1 (the M shape).", epidemiology: "Common and often benign, increasing with age.", aetiology: "Often a normal variant; also pulmonary embolism, cor pulmonale, congenital heart disease and ischaemia.", pathophysiology: "Block of the right bundle means the right ventricle depolarises late via slow myocyte-to-myocyte spread, widening the QRS.", presentation: "Usually asymptomatic and incidental; any symptoms reflect the underlying cause.", investigations: "ECG (broad QRS, RSR in V1, the MaRRoW pattern, with a wide slurred S in the lateral leads); investigate for a cause if new.", treatment: "No treatment for isolated right bundle branch block; treat any underlying cause." },
      { id: "cvs_lbbb", cluster: "Arrhythmias & conduction disease", name: "Left bundle branch block", keyFacts: "Delayed conduction to the left ventricle, giving a broad QRS; new LBBB with chest pain is treated as an acute coronary syndrome.", epidemiology: "Less common than right bundle branch block and more often pathological.", aetiology: "Almost always underlying heart disease: ischaemic heart disease, hypertension, aortic stenosis or cardiomyopathy.", pathophysiology: "Block of the left bundle makes the left ventricle depolarise late and abnormally, widening the QRS and precluding normal ST and Q-wave interpretation.", presentation: "Usually asymptomatic; the significance lies in the underlying disease, and new LBBB may indicate acute infarction.", investigations: "ECG (broad QRS, the WiLLiaM pattern: W in V1 and M in V6); echocardiography and ischaemia assessment for new LBBB.", treatment: "Treat the underlying cause; new LBBB with ischaemic symptoms is managed as an acute coronary syndrome; consider cardiac resynchronisation in heart failure." },
      { id: "cvs_brugada", cluster: "Arrhythmias & conduction disease", name: "Brugada syndrome", keyFacts: "An inherited sodium-channel disorder causing a characteristic ECG pattern and a risk of sudden cardiac death from ventricular arrhythmia.", epidemiology: "Commoner in men and in South-East Asian populations; a cause of sudden death in young adults.", aetiology: "Autosomal dominant, most often a loss-of-function SCN5A sodium-channel mutation.", pathophysiology: "Abnormal cardiac sodium channels predispose to ventricular tachyarrhythmias, often during sleep or fever.", presentation: "Often asymptomatic; syncope, nocturnal agonal breathing, or sudden cardiac arrest, sometimes precipitated by fever.", investigations: "ECG (coved ST elevation in V1 to V2, the type 1 Brugada pattern), which may need a sodium-channel-blocker (ajmaline) challenge; genetic testing and family screening.", treatment: "Avoid and aggressively treat fever and precipitating drugs; an implantable cardioverter-defibrillator for those at high risk." },
      { id: "cvs_long_qt", cluster: "Arrhythmias & conduction disease", name: "Congenital long QT syndrome", keyFacts: "An inherited disorder of ventricular repolarisation that prolongs the QT interval and predisposes to torsades de pointes and sudden death.", epidemiology: "A cause of syncope and sudden death in children and young adults; several genetic subtypes.", aetiology: "Mutations in cardiac ion channels (commonly potassium channels); some syndromes include deafness (Jervell and Lange-Nielsen).", pathophysiology: "Delayed repolarisation lengthens the QT interval, allowing early after-depolarisations that trigger torsades de pointes.", presentation: "Syncope or cardiac arrest, often triggered by exertion, emotion or startle (for example an alarm), with a family history of sudden death.", investigations: "ECG (prolonged corrected QT interval), exercise testing, genetic testing and family screening.", treatment: "Avoid QT-prolonging drugs; beta-blockers; an implantable defibrillator for high-risk patients; lifestyle advice by subtype." },
      { id: "neuro_vasovagal", cluster: "Arrhythmias & conduction disease", name: "Vasovagal syncope", keyFacts: "The commonest cause of transient loss of consciousness; a benign neurally-mediated reflex faint.", epidemiology: "Very common, especially in young people.", aetiology: "Triggered by prolonged standing, heat, pain, emotion, micturition or the sight of blood.", pathophysiology: "A reflex surge of vagal tone with vasodilatation and bradycardia transiently drops cerebral perfusion.", presentation: "Prodrome of light-headedness, sweating, nausea, pallor and visual greying, then brief collapse with rapid, full recovery.", investigations: "Clinical diagnosis from the history; lying and standing BP and an ECG to exclude cardiac causes; tilt-table testing if uncertain.", treatment: "Reassurance, trigger avoidance, good hydration and salt intake, and counter-pressure manoeuvres; rarely needs further intervention." },
      { id: "cvs_periarrest", cluster: "Arrhythmias & conduction disease", name: "Peri-arrest arrhythmias", keyFacts: "Tachyarrhythmias and bradyarrhythmias that threaten to cause cardiac arrest; management hinges on whether adverse features are present.", epidemiology: "Encountered in acute and emergency care across many conditions.", aetiology: "Tachyarrhythmias (atrial fibrillation, SVT, VT, flutter) and bradyarrhythmias (heart block, sinus node disease, drugs); precipitated by ischaemia, electrolytes and drugs.", pathophysiology: "Rates too fast or too slow reduce cardiac output; adverse features signal decompensation.", presentation: "Assess for adverse features: shock, syncope, myocardial ischaemia (chest pain) and heart failure.", investigations: "12-lead ECG (broad versus narrow, regular versus irregular), continuous monitoring, electrolytes.", treatment: "Unstable tachyarrhythmia: synchronised DC cardioversion. Stable: vagal manoeuvres or adenosine (narrow) or amiodarone (broad). Unstable bradyarrhythmia: atropine 500 micrograms, then transcutaneous pacing or an adrenaline infusion." },
      { id: "cvs_cardiac_arrest", management: {"source": "Resus Council UK", "def": "A[\"Cardiac arrest\"]:::start --> B[\"CPR 30:2, attach defibrillator, call team\"]:::danger\nB --> C{\"Shockable rhythm?\"}:::decision\nC -- \"yes (VF / pulseless VT)\" --> D[\"Defibrillate, resume CPR 2 min\"]:::good\nC -- \"no (PEA / asystole)\" --> E[\"CPR 2 min, adrenaline now\"]:::good\nD --> F[\"Adrenaline and amiodarone after 3rd shock\"]:::good\nE --> G[\"Adrenaline every 3-5 min\"]:::good\nF --> H[\"Treat reversible causes (4 Hs and 4 Ts)\"]:::warn\nG --> H", "tips": {"A": "Follow the Resuscitation Council UK Adult Advanced Life Support algorithm; the key split is shockable versus non-shockable rhythms.", "B": "Start high-quality chest compressions (30:2 until the airway is secured, then continuous), attach a defibrillator/monitor, and call the arrest team.", "C": "Assess the rhythm during a brief pause - this determines the pathway.", "D": "Shockable (ventricular fibrillation or pulseless VT): deliver a single shock and immediately resume CPR for 2 minutes before reassessing.", "E": "Non-shockable (pulseless electrical activity or asystole): CPR for 2 minutes and give adrenaline 1 mg IV as soon as access is available.", "F": "In shockable rhythms, give adrenaline 1 mg and amiodarone 300 mg after the third shock (then adrenaline every 3-5 minutes).", "G": "In non-shockable rhythms, give adrenaline 1 mg every 3-5 minutes (every other cycle).", "H": "Throughout, seek and treat reversible causes - the 4 Hs (hypoxia, hypovolaemia, hypo/hyperkalaemia and metabolic, hypothermia) and 4 Ts (thrombosis, tension pneumothorax, tamponade, toxins)."}}, cluster: "Arrhythmias & conduction disease", name: "Cardiac arrest", keyFacts: "Sudden cessation of effective cardiac output; survival depends on early CPR and, for shockable rhythms, early defibrillation.", epidemiology: "Common; the commonest out-of-hospital presenting rhythm is non-shockable, but early ventricular fibrillation carries the best survival.", aetiology: "Shockable rhythms (ventricular fibrillation, pulseless VT) and non-shockable (pulseless electrical activity, asystole); seek reversible causes, the 4 Hs and 4 Ts.", pathophysiology: "Loss of coordinated ventricular contraction stops perfusion, causing rapid irreversible organ (especially brain) injury without intervention.", presentation: "Unresponsive with absent or abnormal (agonal) breathing and no pulse.", investigations: "Rhythm check to classify shockable versus non-shockable; identify reversible causes (4 Hs: hypoxia, hypovolaemia, hypo/hyperkalaemia, hypothermia; 4 Ts: thrombosis, tamponade, tension pneumothorax, toxins).", treatment: "Advanced Life Support: high-quality CPR, defibrillate shockable rhythms, adrenaline every 3-5 minutes (and amiodarone after the third shock in VF/VT), and correct reversible causes; structured post-arrest care." },
      { id: "cvs_aortic_stenosis", cluster: "Valvular heart disease", name: "Aortic stenosis", keyFacts: "The commonest valve lesion needing surgery; the triad of syncope, angina and dyspnoea signals severe disease.", epidemiology: "Largely a disease of the elderly (calcific); a congenital bicuspid valve presents earlier, in middle age.", aetiology: "Age-related calcification, a congenital bicuspid valve, or historically rheumatic heart disease.", pathophysiology: "Progressive valve narrowing obstructs left ventricular outflow, causing pressure overload, concentric hypertrophy and eventually reduced coronary perfusion and cardiac output.", presentation: "Exertional syncope, angina, dyspnoea; ejection systolic murmur radiating to carotids, slow-rising pulse.", investigations: "Echocardiogram (valve area, gradient), ECG.", treatment: "Valve replacement (surgical or TAVI) once symptomatic or severe; avoid vasodilators." },
      { id: "cvs_aortic_sclerosis", cluster: "Valvular heart disease", name: "Aortic sclerosis", keyFacts: "Age-related thickening and calcification of the aortic valve without significant obstruction; a benign ejection systolic murmur.", epidemiology: "Common in the elderly, and a precursor to aortic stenosis in some.", aetiology: "Degenerative calcification, sharing risk factors with atherosclerosis.", pathophysiology: "The valve leaflets thicken and calcify, but the valve area and gradient stay near normal, so there is no outflow obstruction.", presentation: "Asymptomatic, with an ejection systolic murmur but a normal pulse character and no radiation, which helps distinguish it from stenosis.", investigations: "Echocardiography confirms a normal valve gradient and area.", treatment: "No specific treatment; manage cardiovascular risk factors and monitor for progression to stenosis." },
      { id: "cvs_aortic_regurg", cluster: "Valvular heart disease", name: "Aortic regurgitation", keyFacts: "A diastolic leak of the aortic valve causing volume overload, with an early diastolic murmur and a wide pulse pressure.", epidemiology: "Chronic disease in adults; acute aortic regurgitation is rarer but life-threatening.", aetiology: "Chronic from a bicuspid valve, rheumatic disease or aortic root dilatation (Marfan); acute from endocarditis or aortic dissection.", pathophysiology: "The incompetent valve lets blood regurgitate into the left ventricle in diastole, causing volume overload, dilatation and eventually failure.", presentation: "Often asymptomatic for years, then exertional dyspnoea; a collapsing pulse, early diastolic murmur and wide pulse pressure.", investigations: "Echocardiography to grade severity and assess the aortic root; ECG and chest X-ray.", treatment: "Treat the cause; ACE inhibitors for symptoms; valve replacement when symptomatic or the ventricle dilates; urgent surgery for acute regurgitation." },
      { id: "cvs_mitral_stenosis", cluster: "Valvular heart disease", name: "Mitral stenosis", keyFacts: "Narrowing of the mitral valve, almost always rheumatic; a mid-diastolic murmur with left atrial dilatation.", epidemiology: "Now uncommon in developed countries as rheumatic fever has declined; commoner in women.", aetiology: "Rheumatic heart disease is by far the commonest cause; rarely congenital or from severe annular calcification.", pathophysiology: "The narrowed valve obstructs left atrial emptying, raising left atrial pressure and causing pulmonary congestion, atrial fibrillation and eventually right heart failure.", presentation: "Exertional breathlessness, a loud first heart sound and a low-pitched mid-diastolic murmur at the apex; atrial fibrillation, haemoptysis and a malar flush.", investigations: "Echocardiography (valve area and gradient), ECG (P mitrale, atrial fibrillation), chest X-ray (left atrial enlargement).", treatment: "Rate control and anticoagulation for atrial fibrillation; diuretics for congestion; percutaneous balloon valvuloplasty or valve replacement for severe disease." },
      { id: "cvs_mitral_regurg", cluster: "Valvular heart disease", name: "Mitral regurgitation", keyFacts: "Backflow through an incompetent mitral valve causing volume overload and a pansystolic murmur.", epidemiology: "One of the commonest valve lesions, increasing with age.", aetiology: "Degenerative (prolapse), ischaemic (papillary muscle dysfunction or rupture), functional (dilated ventricle), rheumatic, or endocarditis.", pathophysiology: "Regurgitation into the left atrium in systole causes volume overload with left atrial and ventricular dilatation and, eventually, heart failure.", presentation: "Often asymptomatic, then exertional breathlessness and fatigue; a pansystolic murmur at the apex radiating to the axilla with a displaced apex beat.", investigations: "Echocardiography to grade severity and mechanism; ECG and chest X-ray.", treatment: "Treat heart failure and any cause; surgical repair (preferred) or replacement for severe or symptomatic disease; acute severe regurgitation needs urgent surgery." },
      { id: "cvs_mvp", cluster: "Valvular heart disease", name: "Mitral valve prolapse", keyFacts: "Billowing of a mitral leaflet into the left atrium in systole; usually benign, with a mid-systolic click and late systolic murmur.", epidemiology: "The commonest valve abnormality, affecting a few percent of people, more often young women.", aetiology: "Myxomatous degeneration of the valve; associated with connective-tissue disorders (Marfan, Ehlers-Danlos).", pathophysiology: "Redundant, floppy leaflet tissue prolapses into the atrium, and progressive degeneration can cause mitral regurgitation or chordal rupture.", presentation: "Usually asymptomatic; atypical chest pain and palpitations; a mid-systolic click and a late systolic murmur that move with manoeuvres.", investigations: "Echocardiography is diagnostic; ECG.", treatment: "Reassurance for most; monitor and treat any significant mitral regurgitation; a beta-blocker for palpitations." },
      { id: "cvs_tricuspid_regurg", cluster: "Valvular heart disease", name: "Tricuspid regurgitation", keyFacts: "Backflow through the tricuspid valve, most often functional from a dilated right ventricle; causes right heart failure signs.", epidemiology: "Common, and usually secondary (functional).", aetiology: "Functional from right ventricular dilatation and pulmonary hypertension (commonest); also endocarditis (intravenous drug use), rheumatic disease and carcinoid.", pathophysiology: "Regurgitation into the right atrium in systole raises right atrial and venous pressure, producing systemic venous congestion.", presentation: "A raised JVP with giant V waves, a pulsatile liver, ascites and peripheral oedema; a pansystolic murmur at the left sternal edge, louder on inspiration.", investigations: "Echocardiography; ECG and assessment of the underlying cause (pulmonary hypertension).", treatment: "Treat the underlying cause and right heart failure (diuretics); valve surgery in selected severe cases." },
      { id: "cvs_pulmonary_stenosis", cluster: "Valvular heart disease", name: "Pulmonary stenosis", keyFacts: "Obstruction to right ventricular outflow, usually congenital; an ejection systolic murmur in the pulmonary area.", epidemiology: "A common congenital lesion, often isolated.", aetiology: "Usually congenital (isolated or part of tetralogy of Fallot, or Noonan syndrome); rarely rheumatic or carcinoid.", pathophysiology: "Valve narrowing obstructs right ventricular outflow, causing right ventricular pressure overload and hypertrophy.", presentation: "Often asymptomatic; an ejection systolic murmur at the upper left sternal edge, louder on inspiration, with a right ventricular heave in severe disease.", investigations: "Echocardiography (gradient), ECG (right ventricular hypertrophy).", treatment: "Balloon valvuloplasty for significant stenosis; surgery for complex or dysplastic valves." },
      { id: "cvs_rheumatic", cluster: "Valvular heart disease", name: "Rheumatic heart disease", keyFacts: "Chronic valve damage following rheumatic fever, an autoimmune sequel of group A streptococcal throat infection; mitral stenosis is the classic result.", epidemiology: "Now rare in developed countries but a major cause of valve disease worldwide; follows childhood streptococcal infection.", aetiology: "An autoimmune reaction to group A Streptococcus (molecular mimicry) after pharyngitis, causing acute rheumatic fever then chronic valve scarring.", pathophysiology: "Cross-reactive antibodies inflame the heart (pancarditis) and, over years, scar and deform the valves, most often causing mitral stenosis or regurgitation.", presentation: "Acute rheumatic fever (Jones criteria: carditis, migratory arthritis, chorea, erythema marginatum, subcutaneous nodules) weeks after a sore throat; later chronic valve disease.", investigations: "Throat culture and ASO or anti-DNase B titres, ECG, echocardiography; the Jones criteria for acute disease.", treatment: "Penicillin for the infection and anti-inflammatories (aspirin) for the acute phase; long-term penicillin prophylaxis; treat the resulting valve disease." },
      { id: "cvs_endocarditis", management: {"def": "A[\"Infective endocarditis\"]:::start --> B[\"Three sets of blood cultures before antibiotics\"]:::process\nB --> C[\"Echocardiography (TTE, then TOE)\"]:::process\nC --> D[\"Apply the modified Duke criteria\"]:::process\nD --> E[\"Prolonged IV antibiotics (4-6 weeks)\"]:::good\nE -- \"heart failure, abscess, emboli, resistant organism\" --> F[\"Cardiac surgery (valve repair/replace)\"]:::warn\nA --> G[\"Find the source, involve endocarditis MDT\"]:::process", "tips": {"A": "Infection of the endocardium or heart valves (Staph aureus, Streptococci, Enterococci): fever, a new or changing murmur, and embolic/immune phenomena (splinter haemorrhages, Osler nodes, Janeway lesions, Roth spots).", "B": "Take three sets of blood cultures from different sites before starting antibiotics (unless septic and unstable) - the cornerstone of diagnosis.", "C": "Echocardiography looks for vegetations, abscess or valve destruction - transthoracic first, then transoesophageal (more sensitive).", "D": "Diagnose using the modified Duke criteria (major: typical organism on cultures, endocardial involvement on echo; plus minor criteria such as fever, predisposition, vascular and immune phenomena).", "E": "Treat with prolonged IV antibiotics (typically 4-6 weeks), tailored to the organism and whether the valve is native or prosthetic.", "F": "Surgery (valve repair or replacement) for heart failure from valve destruction, perivalvular abscess, large mobile vegetations or recurrent emboli, or resistant/fungal organisms.", "G": "Identify and treat the source (dental, IV lines, injecting drug use), involve a multidisciplinary endocarditis team, and give prophylaxis to the highest-risk patients."}}, cluster: "Endocardial, myocardial & pericardial disease", name: "Infective endocarditis", keyFacts: "Infection of the endocardium or heart valves; suspect it with fever plus a new murmur, and diagnose on the modified Duke criteria.", epidemiology: "Uncommon but serious, with higher risk in those with prosthetic valves, intravenous drug use or structural heart disease.", aetiology: "Staphylococcus aureus (acute, and in drug users), Streptococcus viridans (subacute, after dental work), enterococci, and culture-negative organisms.", pathophysiology: "Bacteraemia seeds damaged or prosthetic valve endothelium, forming infected vegetations that destroy the valve and embolise systemically.", presentation: "Fever, new murmur, splinter haemorrhages, Janeway lesions, Osler nodes; risk with prosthetic valves/IVDU.", investigations: "Blood cultures (3 sets), echocardiogram; modified Duke criteria.", treatment: "Prolonged IV antibiotics; surgery for heart failure, abscess or large vegetations." },
      { id: "cvs_myocarditis", cluster: "Endocardial, myocardial & pericardial disease", name: "Myocarditis", keyFacts: "Inflammation of the myocardium, usually viral; it ranges from mild to fulminant heart failure and is a cause of sudden death in the young.", epidemiology: "Often affects younger, previously healthy people; an important cause of dilated cardiomyopathy.", aetiology: "Usually viral (Coxsackie B, adenovirus, parvovirus B19); also other infections, autoimmune disease, and drugs or toxins.", pathophysiology: "Direct infection and an immune response inflame and damage myocytes, impairing contraction and creating an arrhythmic substrate; it can evolve into dilated cardiomyopathy.", presentation: "A viral prodrome then chest pain, breathlessness, palpitations or heart failure; sometimes arrhythmia or sudden death.", investigations: "Raised troponin and inflammatory markers, ECG (ST and T changes, arrhythmia), echocardiography, cardiac MRI, and endomyocardial biopsy in selected cases.", treatment: "Supportive heart failure and arrhythmia management, rest and avoidance of exercise; treat the cause; most recover but some progress to dilated cardiomyopathy." },
      { id: "cvs_pericarditis", cluster: "Endocardial, myocardial & pericardial disease", name: "Pericarditis", keyFacts: "Inflammation of the pericardium causing pleuritic chest pain relieved by sitting forward, with a friction rub.", epidemiology: "A common cause of acute chest pain, particularly in younger adults.", aetiology: "Often viral or idiopathic; also post-myocardial infarction (Dressler's), uraemia, autoimmune disease, tuberculosis and malignancy.", pathophysiology: "Inflamed pericardial layers rub together and may exude fluid; a large or rapidly accumulating effusion can compress the heart and cause tamponade.", presentation: "Sharp pleuritic chest pain relieved by sitting forward; pericardial rub.", investigations: "ECG (saddle-shaped ST elevation, PR depression), troponin, echocardiogram.", treatment: "NSAID plus colchicine; treat underlying cause; watch for tamponade." },
      { id: "cvs_pericardial_effusion", cluster: "Endocardial, myocardial & pericardial disease", name: "Pericardial effusion", keyFacts: "Fluid in the pericardial sac; a large or rapidly accumulating effusion can cause life-threatening tamponade.", epidemiology: "Reflects many underlying causes and is common after pericarditis.", aetiology: "Pericarditis (viral, autoimmune), malignancy, uraemia, trauma, hypothyroidism and cardiac surgery.", pathophysiology: "Fluid accumulates between the pericardial layers, and if pressure exceeds cardiac filling pressure, tamponade impairs ventricular filling.", presentation: "Often asymptomatic; tamponade gives breathlessness, a raised JVP, muffled heart sounds and pulsus paradoxus (Beck's triad).", investigations: "Echocardiography is the key test; ECG (low voltage, electrical alternans) and chest X-ray (globular heart).", treatment: "Treat the cause; urgent pericardiocentesis for tamponade; drainage for large or recurrent effusions." },
      { id: "cvs_tamponade", management: {"source": "Cardiac emergency", "def": "A[\"Suspected cardiac tamponade\"]:::start --> B[\"Beck's triad + pulsus paradoxus, ABCDE\"]:::process\nB --> C[\"Urgent bedside echocardiogram\"]:::process\nC --> D{\"Haemodynamically unstable?\"}:::decision\nD -- \"yes / peri-arrest\" --> E[\"Emergency pericardiocentesis (echo-guided)\"]:::danger\nD -- \"stable\" --> F[\"IV fluids + urgent senior/cardiology review\"]:::good\nE --> G{\"Traumatic or aortic dissection?\"}:::decision\nG -- \"yes\" --> H[\"Emergency surgery (thoracotomy / pericardial window)\"]:::danger\nG -- \"no\" --> I[\"Drain, treat cause, watch for re-accumulation\"]:::good\nF --> I", "tips": {"A": "Cardiac tamponade is pericardial fluid compressing the heart and causing obstructive shock; it is a reversible cause of cardiac arrest (one of the 4 Ts). Recognise it clinically and confirm on echo.", "B": "Look for Beck's triad (hypotension, a raised jugular venous pressure and muffled heart sounds), tachycardia and pulsus paradoxus (systolic blood pressure falls over 10 mmHg on inspiration); resuscitate with an ABCDE approach.", "C": "Bedside echocardiography is the key investigation - a pericardial effusion with diastolic collapse of the right heart and a dilated, non-collapsing inferior vena cava. Do not delay treatment for imaging in a peri-arrest patient.", "D": "Decide the urgency by haemodynamic stability.", "E": "Unstable or peri-arrest: emergency pericardiocentesis - needle aspiration of the pericardial fluid, ideally echo-guided - relieves the compression immediately.", "F": "Stable: give IV fluids to support ventricular filling and get urgent senior/cardiology review while arranging drainage.", "G": "Establish the cause, because it changes the treatment.", "H": "A traumatic haemopericardium or a type A aortic dissection needs emergency surgery (thoracotomy or a surgical pericardial window), not needle drainage alone.", "I": "Otherwise drain the effusion, treat the underlying cause and watch for re-accumulation; a surgical pericardial window helps recurrent effusions."}}, cluster: "Endocardial, myocardial & pericardial disease", name: "Cardiac tamponade", keyFacts: "Accumulation of pericardial fluid under enough pressure to compress the heart and impair filling; an obstructive-shock emergency and a reversible cause of cardiac arrest (one of the 4 Ts).", epidemiology: "Reflects its causes; a rapidly accumulating effusion (for example haemopericardium after trauma or myocardial rupture) can cause tamponade with a small volume, whereas a slowly accumulating effusion may hold a large volume before decompensating.", aetiology: "Any cause of pericardial effusion - malignancy, pericarditis (viral, autoimmune, uraemic, tuberculous), trauma or a stab wound (haemopericardium), aortic dissection, myocardial free-wall rupture after infarction, and iatrogenic causes (cardiac surgery, pacing, central line, coronary intervention).", pathophysiology: "As intrapericardial pressure rises it exceeds the diastolic filling pressures of the right heart, so venous return and ventricular filling fall; stroke volume and cardiac output drop, producing obstructive shock. The rate of accumulation matters more than the volume, because the stiff pericardium cannot stretch acutely.", presentation: "Beck's triad - hypotension, a raised jugular venous pressure and muffled heart sounds - with breathlessness, tachycardia and pulsus paradoxus (a fall in systolic blood pressure over 10 mmHg on inspiration); Kussmaul's sign may occur. It can present as pulseless electrical activity cardiac arrest.", investigations: "Bedside echocardiography is the key test (a pericardial effusion with diastolic collapse of the right atrium and ventricle and a dilated, non-collapsing inferior vena cava); ECG shows low-voltage complexes and electrical alternans, and the chest X-ray a globular (water-bottle) heart. Do not delay treatment for imaging in a peri-arrest patient.", treatment: "Urgent pericardiocentesis (needle drainage, ideally echo-guided) is the definitive treatment; support with IV fluids to maintain filling while preparing. A traumatic haemopericardium or aortic dissection needs emergency surgery (thoracotomy or a pericardial window), not needle drainage alone. Treat the underlying cause and consider a surgical pericardial window for recurrent effusions." },
      { id: "cvs_vsd", cluster: "Congenital heart disease", name: "Ventricular septal defect", keyFacts: "A hole in the interventricular septum causing a left-to-right shunt; the commonest congenital heart defect.", epidemiology: "The most frequent congenital cardiac lesion, and many small defects close spontaneously.", aetiology: "Congenital (often isolated or syndromic) and occasionally acquired after a myocardial infarction.", pathophysiology: "Blood shunts left to right, overloading the pulmonary circulation and left heart; large shunts risk pulmonary hypertension and Eisenmenger syndrome.", presentation: "A loud pansystolic murmur (louder in small defects); large defects cause heart failure and failure to thrive in infancy.", investigations: "Echocardiography is diagnostic; ECG and chest X-ray gauge shunt size.", treatment: "Small defects are monitored; surgical or device closure for large or symptomatic defects, with endocarditis awareness." },
      { id: "cvs_pda", cluster: "Congenital heart disease", name: "Patent ductus arteriosus", keyFacts: "Persistence of the fetal ductus arteriosus after birth, giving a continuous machinery murmur and a left-to-right shunt.", epidemiology: "Commoner in premature and low-birthweight infants and with congenital rubella.", aetiology: "Failure of normal ductal closure, with risk from prematurity, hypoxia and maternal rubella.", pathophysiology: "Blood shunts from the aorta to the pulmonary artery, increasing pulmonary flow and left heart load; large shunts can cause pulmonary hypertension.", presentation: "Often asymptomatic, with a continuous machinery murmur and bounding pulses; large shunts cause heart failure or failure to thrive.", investigations: "Echocardiography is diagnostic; ECG and chest X-ray gauge shunt size.", treatment: "Indometacin or ibuprofen to close it in preterm infants; catheter or surgical closure for persistent or symptomatic cases." },
      { id: "cvs_tof", cluster: "Congenital heart disease", name: "Tetralogy of Fallot", keyFacts: "The commonest cyanotic congenital heart disease, with four features: a VSD, overriding aorta, pulmonary stenosis and right ventricular hypertrophy.", epidemiology: "The leading cyanotic congenital lesion to present after the neonatal period.", aetiology: "Congenital, and associated with 22q11 deletion (DiGeorge syndrome) and other syndromes.", pathophysiology: "Right ventricular outflow obstruction with a VSD causes right-to-left shunting and cyanosis, worsening during hypercyanotic (tet) spells.", presentation: "Cyanosis, a harsh ejection systolic murmur, and hypercyanotic spells relieved by squatting, with clubbing later.", investigations: "Echocardiography is diagnostic; the chest X-ray shows a boot-shaped heart and the ECG right ventricular hypertrophy.", treatment: "Manage tet spells (knee-to-chest position, oxygen) and undertake surgical repair in infancy." },
      { id: "cvs_tga", cluster: "Congenital heart disease", name: "Transposition of the great arteries", keyFacts: "The aorta and pulmonary artery are switched, creating two parallel circulations and cyanosis in the newborn.", epidemiology: "A common cause of cyanosis in the first days of life.", aetiology: "Congenital, usually sporadic.", pathophysiology: "Deoxygenated blood recirculates to the body and oxygenated blood to the lungs, so survival depends on mixing through a duct or septal defect.", presentation: "Cyanosis within the first day or two of life, worsening as the duct closes.", investigations: "Echocardiography is diagnostic; the chest X-ray may show an egg-on-side appearance.", treatment: "Prostaglandin to keep the duct open, balloon atrial septostomy, then arterial switch surgery." },
      { id: "cvs_coarctation", cluster: "Congenital heart disease", name: "Coarctation of the aorta", keyFacts: "Congenital narrowing of the aorta, usually near the ductus; causes upper-limb hypertension and weak, delayed femoral pulses (radiofemoral delay).", epidemiology: "A common congenital lesion, commoner in males and associated with Turner syndrome and a bicuspid aortic valve.", aetiology: "Congenital narrowing of the aortic arch, typically just distal to the left subclavian artery.", pathophysiology: "The narrowing obstructs aortic flow, causing hypertension proximally and reduced perfusion distally, with collateral vessels developing over time.", presentation: "Severe cases present with neonatal heart failure as the duct closes; older children and adults have hypertension, radiofemoral delay, weak femoral pulses and headaches.", investigations: "Four-limb blood pressure, echocardiography, CT or MRI aortography; chest X-ray may show rib notching.", treatment: "Prostaglandin to keep the duct open in critical neonatal cases; surgical or balloon and stent repair; treat residual hypertension." },
      { id: "cvs_aortic_dissection", management: {"def": "A[\"Acute aortic dissection\"]:::start --> B[\"CT angiography of the aorta\"]:::process\nB --> C[\"Control BP and heart rate: IV labetalol\"]:::good\nC --> D{\"Stanford type\"}:::decision\nD -- \"type A (ascending)\" --> E[\"Emergency cardiothoracic surgery\"]:::danger\nD -- \"type B (descending)\" --> F[\"Medical management, surgery if complicated\"]:::good", "tips": {"A": "A tear in the aortic intima lets blood track through the media: sudden severe tearing chest or back pain, a pulse or blood-pressure difference between arms, and possible new aortic regurgitation. A surgical emergency.", "B": "Confirm with CT angiography of the aorta (or transoesophageal echo if too unstable); give adequate opioid analgesia.", "C": "Reduce shear stress by controlling heart rate and blood pressure with an IV beta-blocker (labetalol) to a target systolic around 100-120 mmHg - beta-blocker first to avoid reflex tachycardia.", "D": "Management depends on whether the ascending aorta is involved (Stanford classification).", "E": "Type A (involving the ascending aorta): emergency cardiothoracic surgical repair - very high mortality untreated.", "F": "Type B (descending aorta only): usually medical management with strict blood-pressure control; endovascular or surgical repair is reserved for complications (rupture, malperfusion, refractory pain)."}}, cluster: "Aortic & peripheral arterial disease", name: "Aortic dissection", keyFacts: "A tear in the aortic intima lets blood track within the wall; a life-threatening emergency with tearing chest pain radiating to the back.", epidemiology: "Peaks in older hypertensive men; earlier in connective-tissue disease.", aetiology: "Hypertension is the main risk; also connective-tissue disorders (Marfan, Ehlers-Danlos), a bicuspid valve, pregnancy and trauma.", pathophysiology: "An intimal tear creates a false lumen in the media; Stanford type A involves the ascending aorta (surgical), type B the descending (usually medical).", presentation: "Sudden severe tearing chest pain radiating to the back, a blood pressure difference between the arms, a new aortic regurgitation murmur, and possible pulse deficits or stroke.", investigations: "CT angiography of the aorta (diagnostic); chest X-ray (widened mediastinum); ECG to exclude infarction; cross-match.", treatment: "Control blood pressure and heart rate (labetalol); emergency surgery for type A; usually medical management for uncomplicated type B." },
      { id: "cvs_aaa", cluster: "Aortic & peripheral arterial disease", name: "Abdominal aortic aneurysm", keyFacts: "Abnormal dilatation of the abdominal aorta to 3 cm or more; usually silent until it ruptures, which is often fatal.", epidemiology: "Mostly older male smokers; the UK offers men a single screening ultrasound at 65.", aetiology: "Atherosclerosis and connective-tissue weakening; risk factors are smoking, age, male sex, hypertension and family history.", pathophysiology: "Degeneration of the elastic media weakens the wall, which dilates under arterial pressure (Laplace's law) until it tears.", presentation: "Often asymptomatic; pulsatile mass; rupture gives sudden abdominal/back pain and collapse.", investigations: "Abdominal ultrasound (screening offered to men at 65); CT for sizing.", treatment: "Monitor if small; elective repair at ≥5.5 cm; emergency surgery if ruptured." },
      { id: "cvs_ruptured_aaa", cluster: "Aortic & peripheral arterial disease", name: "Ruptured abdominal aortic aneurysm", keyFacts: "A surgical emergency: rupture of an abdominal aortic aneurysm causing catastrophic retroperitoneal or intraperitoneal haemorrhage, with an overall mortality around 80%.", epidemiology: "Most ruptures occur in men over 65; risk rises steeply with aneurysm diameter (especially above 5.5 cm), rapid expansion and continued smoking.", aetiology: "A degenerative (atherosclerotic) aneurysm that weakens and tears; risk factors are smoking, hypertension, male sex, increasing age and a family history.", pathophysiology: "Progressive loss of medial elastin and collagen weakens the wall until wall stress exceeds its strength (Laplace's law) and it tears, usually into the retroperitoneum (initially contained) or freely into the peritoneum (rapidly fatal).", presentation: "Classic triad of sudden severe abdominal, back or flank pain, hypotension or collapse, and a pulsatile expansile abdominal mass; can mimic renal colic, so maintain a high index of suspicion in older patients.", investigations: "A clinical diagnosis in the unstable patient - do NOT delay for imaging; go straight to theatre. Reserve CT angiography for the haemodynamically stable patient to plan repair.", treatment: "Immediate ABCDE resuscitation with senior vascular surgery and anaesthetic help; large-bore access, crossmatch and activate the major haemorrhage protocol; permissive hypotension (target systolic around 90 mmHg); emergency endovascular (EVAR) or open repair.", management: {"source": "NICE", "def": "A[\"Ruptured abdominal aortic aneurysm\"]:::start --> B[\"ABCDE, call vascular surgery and anaesthetics\"]:::danger\nB --> C[\"Large-bore access, crossmatch, major haemorrhage protocol\"]:::good\nC --> D[\"Permissive hypotension (systolic ~90)\"]:::warn\nD --> E{\"Haemodynamically stable?\"}:::decision\nE -- \"unstable\" --> F[\"Straight to theatre (no imaging delay)\"]:::danger\nE -- \"stable\" --> G[\"CT angiogram to plan repair\"]:::good\nF --> H[\"Emergency EVAR or open repair\"]:::good\nG --> H", "tips": {"A": "Rupture of an abdominal aortic aneurysm - a surgical emergency with about 80% overall mortality. Suspect it in any older patient with abdominal or back pain and collapse.", "B": "ABCDE resuscitation with immediate senior vascular surgical and anaesthetic help; this is time-critical.", "C": "Two large-bore cannulae, urgent crossmatch, and activate the major haemorrhage protocol.", "D": "Permissive (hypotensive) resuscitation - keep systolic around 90 mmHg to avoid dislodging clot and worsening the bleed; avoid aggressive fluids.", "E": "Haemodynamic stability decides whether there is time for imaging.", "F": "An unstable patient with a known or suspected rupture goes straight to theatre - do not delay for a CT.", "G": "If stable, a CT angiogram confirms rupture and decides suitability for EVAR versus open repair.", "H": "Definitive treatment is emergency endovascular aneurysm repair (EVAR) or open surgical repair."}} },
      { id: "cvs_pad", cluster: "Aortic & peripheral arterial disease", name: "Peripheral arterial disease", keyFacts: "Atherosclerotic narrowing of the limb arteries causing claudication; a marker of widespread vascular disease.", epidemiology: "Common in older smokers and people with diabetes.", aetiology: "Atherosclerosis, strongly linked to smoking, diabetes, hypertension and hyperlipidaemia.", pathophysiology: "Progressive arterial stenosis reduces distal perfusion, so exercising muscle becomes ischaemic (claudication); critical ischaemia brings rest pain, ulceration and gangrene.", presentation: "Intermittent claudication, cold pale leg, absent pulses; critical ischaemia gives rest pain and ulcers.", investigations: "Ankle-brachial pressure index, duplex ultrasound.", treatment: "Risk factor control, supervised exercise, statin and antiplatelet; angioplasty/bypass for severe disease." },
      { id: "cvs_arterial_ulcer", cluster: "Aortic & peripheral arterial disease", name: "Arterial ulcers", keyFacts: "Painful, punched-out ulcers over pressure points and the foot from arterial insufficiency; a marker of peripheral arterial disease.", epidemiology: "Older patients with atherosclerosis, diabetes and a smoking history.", aetiology: "Peripheral arterial disease reducing the blood supply, often with diabetes and smoking.", pathophysiology: "Inadequate arterial perfusion starves the tissue of oxygen, so minor trauma fails to heal and the tissue breaks down.", presentation: "Painful, punched-out ulcers with a clean edge on the toes, foot and lateral malleolus; a cold, pale, hairless leg with absent pulses; pain worse on elevation.", investigations: "Ankle-brachial pressure index (reduced), duplex ultrasound and angiography.", treatment: "Revascularisation (angioplasty or bypass) is key; risk-factor control; careful wound care; avoid compression (unlike venous ulcers)." },      { id: "cvs_ali", management: {"def": "A[\"Acute limb ischaemia\"]:::start --> B[\"Recognise the 6 Ps, urgent vascular referral\"]:::danger\nB --> C[\"IV heparin, analgesia, oxygen\"]:::good\nC --> D{\"Limb viability (Rutherford)\"}:::decision\nD -- \"viable / threatened\" --> E[\"Revascularise: embolectomy, thrombolysis or bypass\"]:::good\nD -- \"irreversible (fixed mottling, paralysis)\" --> F[\"Primary amputation\"]:::danger\nE --> G[\"Treat cause, watch for reperfusion injury\"]:::warn", "tips": {"A": "A sudden drop in limb perfusion threatening viability - the 6 Ps: Pain, Pallor, Pulselessness, Perishingly cold, Paraesthesia and Paralysis. Paraesthesia and paralysis are late, ominous signs. An immediate vascular emergency.", "B": "Common causes are embolism (e.g. from AF) or in-situ thrombosis; refer to vascular surgery immediately.", "C": "Give IV heparin to prevent clot propagation, plus analgesia and oxygen, while planning revascularisation.", "D": "Classify limb viability (Rutherford) to choose treatment.", "E": "Viable or threatened limb: revascularise urgently - surgical embolectomy (Fogarty catheter), catheter-directed thrombolysis, angioplasty or bypass depending on cause and centre.", "F": "Irreversible ischaemia (fixed mottling, muscle paralysis, tense compartments): the limb is not salvageable - primary amputation.", "G": "Treat the underlying cause (anticoagulate for embolic AF) and watch for compartment syndrome and reperfusion injury (hyperkalaemia, rhabdomyolysis, acidosis)."}}, cluster: "Aortic & peripheral arterial disease", name: "Acute limb ischaemia", keyFacts: "A sudden threat to limb viability from arterial occlusion; the 6 Ps (pain, pallor, pulselessness, perishing cold, paraesthesia, paralysis) signal a surgical emergency.", epidemiology: "Mainly older patients with atherosclerosis or atrial fibrillation.", aetiology: "Embolism (often from atrial fibrillation or mural thrombus) or in-situ thrombosis of a diseased artery.", pathophysiology: "Abrupt arterial occlusion stops distal perfusion, and muscle and nerve tolerate only a few hours of ischaemia before irreversible damage.", presentation: "Sudden painful, pale, cold, pulseless limb with paraesthesia and weakness.", investigations: "Urgent clinical diagnosis with a handheld Doppler; CT or catheter angiography to plan revascularisation; ECG for atrial fibrillation.", treatment: "Immediate vascular referral, analgesia and heparin; embolectomy, thrombolysis or bypass; amputation if the limb is non-viable." },
      { id: "cvs_subclavian_steal", cluster: "Aortic & peripheral arterial disease", name: "Subclavian steal syndrome", keyFacts: "A proximal subclavian stenosis that steals blood from the vertebral artery on arm exercise, causing posterior circulation symptoms.", epidemiology: "Uncommon; affects older patients with atherosclerosis, more often on the left.", aetiology: "Atherosclerotic stenosis or occlusion of the subclavian artery proximal to the vertebral artery origin.", pathophysiology: "Arm exercise lowers distal pressure, reversing vertebral artery flow to supply the arm and diverting blood away from the brainstem.", presentation: "Arm claudication with dizziness, visual disturbance or syncope on exertion, and a blood pressure difference between the arms.", investigations: "An inter-arm blood pressure difference, with duplex ultrasound and angiography.", treatment: "Cardiovascular risk-factor control, with angioplasty and stenting or surgical bypass for significant symptoms." },
      { id: "cvs_cholesterol_embolism", cluster: "Aortic & peripheral arterial disease", name: "Cholesterol embolism", keyFacts: "Showers of cholesterol crystals from atheromatous plaques causing distal ischaemia, often after angiography or vascular surgery.", epidemiology: "Older patients with widespread atherosclerosis.", aetiology: "Plaque disruption, frequently iatrogenic (catheterisation, surgery) or after anticoagulation or thrombolysis.", pathophysiology: "Cholesterol crystals embolise to small arteries, lodge there and provoke an inflammatory reaction that occludes them.", presentation: "Livedo reticularis, blue toes with intact pulses, renal impairment and sometimes eosinophilia.", investigations: "A clinical pattern following a procedure, with eosinophilia; biopsy shows cholesterol clefts.", treatment: "Supportive: statins and cardiovascular risk control, avoiding further instrumentation, and managing organ complications." },
      { id: "cvs_dvt", management: {"def": "A[\"Suspected deep vein thrombosis\"]:::start --> B[\"Two-level DVT Wells score\"]:::process\nB --> C{\"DVT likely? (2+ points)\"}:::decision\nC -- \"likely\" --> D[\"Proximal leg vein ultrasound\"]:::good\nC -- \"unlikely\" --> E[\"D-dimer\"]:::good\nD -- \"scan delayed\" --> F[\"Interim anticoagulation, scan within 24 h\"]:::warn\nE -- \"positive\" --> D\nE -- \"negative\" --> H[\"DVT excluded\"]:::good\nD -- \"positive\" --> G[\"Anticoagulate: DOAC first-line\"]:::good\nG --> I[\"3+ months; investigate provoking cause\"]:::process", "tips": {"A": "Unilateral leg swelling, pain and warmth; risk-stratify with Wells before imaging.", "B": "The two-level DVT Wells score gives pretest probability.", "C": "2 or more points = DVT likely; 1 or less = unlikely.", "D": "DVT likely: proximal leg vein ultrasound, ideally within 4 hours.", "E": "DVT unlikely: D-dimer; if positive, proceed to ultrasound.", "F": "If the scan cannot be done within 4 hours, give interim anticoagulation and scan within 24 hours.", "G": "First-line anticoagulation is a DOAC (apixaban or rivaroxaban).", "H": "Negative D-dimer with an unlikely Wells score excludes DVT.", "I": "Anticoagulate for at least 3 months; longer if unprovoked or ongoing risk; consider cancer investigation for unprovoked DVT."}}, cluster: "Venous & thromboembolic disease", name: "Deep vein thrombosis", keyFacts: "Thrombus in a deep vein, usually of the leg; its main danger is propagation to a pulmonary embolism.", epidemiology: "Common as part of venous thromboembolism, which affects roughly 1-2 people per 1000 each year.", aetiology: "Virchow's triad: stasis (immobility, surgery), hypercoagulability (cancer, pregnancy, the combined pill, thrombophilia) and endothelial injury.", pathophysiology: "Venous stasis and a procoagulant state promote fibrin-rich clot in the deep veins, which can dislodge and embolise to the lungs.", presentation: "Unilateral calf swelling, tenderness, warmth, redness.", investigations: "Two-level Wells score; D-dimer if low risk; proximal leg vein ultrasound.", treatment: "DOAC for at least 3 months; longer if unprovoked or ongoing risk; investigate for cancer if unprovoked." },
      { id: "cvs_pe", management: {"def": "A[\"Suspected pulmonary embolism\"]:::start --> B[\"Two-level PE Wells score\"]:::process\nB --> C{\"PE likely? (over 4 points)\"}:::decision\nC -- \"likely\" --> D[\"CT pulmonary angiogram\"]:::good\nC -- \"unlikely\" --> E[\"D-dimer\"]:::good\nE -- \"positive\" --> D\nE -- \"negative\" --> F[\"PE excluded\"]:::good\nD -- \"positive\" --> G[\"Anticoagulate: DOAC first-line\"]:::good\nD -- \"massive PE with shock\" --> H[\"Thrombolysis\"]:::danger\nG --> I[\"Continue 3+ months; provoked vs unprovoked\"]:::process", "tips": {"A": "Consider PE with pleuritic pain, breathlessness, haemoptysis or unexplained tachycardia/hypoxia; risk-stratify before imaging.", "B": "The two-level pulmonary embolism Wells score gives the pretest probability.", "C": "Over 4 points = PE likely; 4 or less = PE unlikely.", "D": "PE likely (or D-dimer positive): CT pulmonary angiogram (V/Q scan if renal impairment, contrast allergy or pregnancy). Give interim anticoagulation if imaging is delayed.", "E": "PE unlikely: check D-dimer; a negative result excludes PE without imaging.", "F": "Negative D-dimer with low probability rules out PE; look for an alternative diagnosis.", "G": "First-line anticoagulation is a DOAC (apixaban or rivaroxaban); LMWH in pregnancy or antiphospholipid syndrome.", "H": "Haemodynamically unstable (massive PE with hypotension): systemic thrombolysis (alteplase).", "I": "Anticoagulate for at least 3 months; continue long-term if unprovoked or ongoing risk; investigate for cancer as guided."}}, cluster: "Venous & thromboembolic disease", name: "Pulmonary embolism", keyFacts: "Occlusion of the pulmonary arteries by embolus - most often thrombus from a leg deep vein thrombosis, but occasionally septic, fat, air, tumour or amniotic-fluid emboli; a medical emergency and a leading cause of preventable hospital death.", epidemiology: "Part of venous thromboembolism and a major cause of preventable in-hospital death.", aetiology: "Most emboli are thrombotic, from proximal lower-limb deep vein thrombosis (the same Virchow's-triad risk factors: stasis, endothelial injury and hypercoagulability). Non-thrombotic emboli include fat, air, amniotic fluid and tumour. Septic pulmonary emboli carry infected material to the lungs - classically from right-sided (tricuspid) infective endocarditis in intravenous drug users, infected central lines or pacemaker leads, and Lemierre's syndrome (Fusobacterium jugular septic thrombophlebitis).", pathophysiology: "Embolic obstruction raises pulmonary vascular resistance and impairs gas exchange, causing hypoxia and, if large, acute right ventricular strain and shock. Septic emboli additionally seed infection, producing multiple peripheral lung abscesses that often cavitate.", presentation: "Pleuritic chest pain, breathlessness, haemoptysis, tachycardia and hypoxia; a massive PE causes syncope, hypotension and right heart strain. Septic pulmonary emboli present with a swinging fever and respiratory symptoms, prompting a search for the infective source.", investigations: "Two-level PE Wells score; a positive D-dimer (if PE unlikely) prompts CT pulmonary angiography (V/Q scan if contrast is contraindicated); ECG (sinus tachycardia, sometimes S1Q3T3) and arterial blood gas. For suspected septic emboli, CT shows multiple bilateral peripheral nodules, often cavitating, with a feeding-vessel sign; take blood cultures and perform echocardiography to find the source.", treatment: "Anticoagulate - a DOAC (apixaban or rivaroxaban) first-line for at least 3 months (longer if unprovoked or ongoing risk); LMWH in pregnancy or antiphospholipid syndrome. Thrombolysis (alteplase) for massive PE with haemodynamic instability. Septic pulmonary emboli are treated by controlling the source and giving prolonged antibiotics (e.g. valve surgery or line removal in endocarditis)." },
      { id: "cvs_varicose_veins", cluster: "Venous & thromboembolic disease", name: "Varicose veins", keyFacts: "Dilated, tortuous superficial leg veins from valvular incompetence; usually a cosmetic and symptomatic issue but occasionally complicated.", epidemiology: "Very common, increasing with age, female sex, pregnancy and prolonged standing.", aetiology: "Incompetent venous valves, often with a family history, or secondary to obstruction (deep vein thrombosis, pelvic mass).", pathophysiology: "Valve failure allows venous reflux and raised pressure, dilating the superficial veins and causing skin changes over time.", presentation: "Visible dilated veins with aching, itching and heaviness; complications include venous eczema, ulceration and superficial thrombophlebitis.", investigations: "Venous duplex ultrasound to map the reflux.", treatment: "Compression and lifestyle advice; endothermal ablation, foam sclerotherapy or surgery for symptomatic or complicated disease." },
      { id: "derm_leg_ulcer", cluster: "Venous & thromboembolic disease", name: "Venous leg ulcers", keyFacts: "A chronic lower-leg ulcer, most often venous; assess the arterial supply before any compression.", epidemiology: "Common in the elderly, with venous disease the leading cause.", aetiology: "Venous hypertension is commonest; also arterial disease, neuropathy and pressure.", pathophysiology: "Sustained venous hypertension damages the skin of the gaiter area, which breaks down and heals poorly.", presentation: "Shallow ulcer over the gaiter area with haemosiderin staining and oedema.", investigations: "ABPI before compression, wound assessment.", treatment: "Compression bandaging if arterial supply adequate, emollients, treat infection, elevate." },
    ],
  },
  {
    id: "respiratory",
    name: "Respiratory",
    icon: "🫁",
    conditions: [
      { id: "resp_asthma", management: {"source": "NICE/BTS/SIGN NG245", "def": "A[\"Asthma (adult / 12+), confirmed\"]:::start --> B[\"Step 1: AIR - as-needed low-dose ICS/formoterol\"]:::good\nB -- \"regular symptoms or uncontrolled\" --> C[\"Step 2: low-dose MART\"]:::good\nC -- \"uncontrolled\" --> D[\"Step 3: moderate-dose MART\"]:::good\nD -- \"still uncontrolled\" --> E[\"Check FeNO and blood eosinophils\"]:::process\nE -- \"raised\" --> F[\"Refer to specialist\"]:::warn\nE -- \"not raised\" --> G[\"Trial LTRA or LAMA, then refer if needed\"]:::good", "tips": {"A": "Diagnosis confirmed by objective tests (spirometry with bronchodilator reversibility, FeNO, peak-flow variability). Management follows the 2024 NICE/BTS/SIGN guideline (NG245); a short-acting beta-2 agonist is no longer used on its own.", "B": "Step 1 - anti-inflammatory reliever (AIR): a low-dose inhaled corticosteroid/formoterol inhaler taken only as needed, for newly diagnosed or infrequent symptoms.", "C": "Step 2 - low-dose MART: the same low-dose ICS/formoterol inhaler taken regularly and as the reliever (maintenance and reliever therapy). Use if symptoms are regular or AIR does not control them.", "D": "Step 3 - step up to moderate-dose MART if still uncontrolled.", "E": "If still uncontrolled on moderate-dose MART, check fractional exhaled nitric oxide (FeNO) and the blood eosinophil count.", "F": "If FeNO or the eosinophil count is raised (continuing eosinophilic inflammation), refer to a specialist.", "G": "If neither is raised, trial a leukotriene receptor antagonist (montelukast) or a long-acting muscarinic antagonist and review; refer to a specialist if control is still not achieved."}}, cluster: "Airways disease", name: "Asthma", keyFacts: "A chronic, reversible inflammatory airway disease with variable wheeze, cough and breathlessness; reversibility distinguishes it from COPD.", epidemiology: "Common, often beginning in childhood; the UK has a high prevalence and significant numbers of preventable deaths.", aetiology: "Atopy and genetic predisposition with triggers such as allergens, exercise, cold air, infection, smoke and drugs (NSAIDs, beta-blockers).", pathophysiology: "Chronic airway inflammation and bronchial hyper-responsiveness cause reversible smooth-muscle constriction, mucus and oedema that narrow the airways.", presentation: "Episodic wheeze, cough and breathlessness with diurnal and trigger-related variation.", investigations: "Objective testing: spirometry with bronchodilator reversibility, fractional exhaled nitric oxide (FeNO), and peak-flow variability.", treatment: "Do not use a short-acting beta-2 agonist alone. Per the 2024 NICE/BTS/SIGN guideline (NG245), adults and children over 12 start anti-inflammatory reliever therapy (AIR - as-needed low-dose inhaled corticosteroid/formoterol), stepping up to low-dose then moderate-dose maintenance-and-reliever therapy (MART); if still uncontrolled, check FeNO and blood eosinophils and refer, or trial a leukotriene receptor antagonist or long-acting muscarinic antagonist. Always check inhaler technique and adherence before stepping up." },
      { id: "resp_asthma_acute", management: {"source": "BTS/SIGN", "def": "A[\"Acute asthma exacerbation\"]:::start --> B[\"Assess severity: PEF, SpO2, ABG, speech, RR, HR\"]:::process\nB --> C{\"Severity?\"}:::decision\nC -- \"moderate\" --> D[\"Salbutamol + oral prednisolone\"]:::good\nC -- \"acute severe\" --> E[\"O2 94-98%; neb salbutamol + ipratropium; steroids\"]:::good\nC -- \"life-threatening / near-fatal\" --> F[\"Add IV magnesium; urgent senior + ICU\"]:::danger\nD --> G[\"Reassess PEF and sats after 15-30 min\"]:::process\nE --> G\nF --> G\nG --> H[\"Not improving: escalate, admit, consider ventilation\"]:::warn", "tips": {"A": "An acute worsening ('attack') of asthma; grade the severity first, because it dictates treatment and disposition (BTS/SIGN).", "B": "Assess with peak expiratory flow (percentage of best or predicted), oxygen saturations, ability to speak in sentences, and respiratory and heart rate; do an arterial blood gas if saturations are under 92% or any life-threatening feature is present.", "C": "Grade the attack by BTS/SIGN criteria - moderate, acute severe, life-threatening or near-fatal.", "D": "Moderate (PEF 50-75%, no acute-severe features): inhaled salbutamol and oral prednisolone; often manageable without admission if it responds.", "E": "Acute severe (any of PEF 33-50%, respiratory rate 25+, heart rate 110+, cannot complete sentences): controlled oxygen to 94-98%, nebulised salbutamol (oxygen-driven, repeated or continuous) with nebulised ipratropium bromide, and steroids.", "F": "Life-threatening (any of PEF <33%, SpO2 <92%, PaO2 <8 kPa, normal PaCO2, silent chest, cyanosis, poor effort, arrhythmia, exhaustion, altered consciousness, hypotension) or near-fatal (raised PaCO2 or needing ventilation): add IV magnesium sulfate and get urgent senior, ICU and anaesthetic help; consider IV salbutamol or aminophylline.", "G": "Reassess peak flow and saturations 15-30 minutes after starting treatment.", "H": "If not improving, escalate treatment and admit; a normal or rising PaCO2 is ominous and may need ventilatory support. Do not discharge until stable, on discharge medication with PEF above 75%."}}, cluster: "Airways disease", name: "Acute asthma exacerbation", keyFacts: "An acute exacerbation ('attack') of asthma, graded by severity into moderate, acute severe, life-threatening and near-fatal. Grading drives treatment and disposition and rests on peak expiratory flow, oxygen saturations and clinical signs (speech, respiratory rate and heart rate) (BTS/SIGN).", epidemiology: "Common and a leading cause of emergency admission; triggers include respiratory infection, allergens, cold air, exercise, smoking and treatment non-adherence.", aetiology: "Bronchospasm, airway inflammation and mucus plugging, usually triggered by a viral upper respiratory infection or allergen exposure in a person with asthma.", pathophysiology: "Acute airflow obstruction increases the work of breathing and causes ventilation-perfusion mismatch. Early hyperventilation lowers the arterial carbon dioxide, so a normal PaCO2 signals fatigue (life-threatening) and a rising PaCO2 signals exhaustion needing ventilation (near-fatal).", presentation: "Breathlessness, wheeze, cough and chest tightness, graded by BTS/SIGN criteria. Moderate: PEF 50-75% best/predicted with no features of acute severe. Acute severe (any one): PEF 33-50%, respiratory rate 25 or more, heart rate 110 or more, or inability to complete sentences in one breath. Life-threatening (any one): PEF under 33%, SpO2 under 92%, PaO2 under 8 kPa, a normal PaCO2 (4.6-6.0 kPa), silent chest, cyanosis, poor respiratory effort, arrhythmia, exhaustion, altered consciousness or hypotension. Near-fatal: a raised PaCO2, or needing mechanical ventilation.", investigations: "Peak expiratory flow, oxygen saturations, and an arterial blood gas if saturations are under 92% or any life-threatening feature is present; chest X-ray if a pneumothorax or consolidation is suspected, or if the response is poor.", treatment: "Controlled oxygen to keep saturations 94-98%; high-dose inhaled salbutamol via an oxygen-driven nebuliser (repeated or continuous if severe); oral prednisolone 40-50 mg (or IV hydrocortisone) continued for at least 5 days; add nebulised ipratropium bromide in acute severe or life-threatening attacks; consider IV magnesium sulfate; urgent senior and ICU/anaesthetic review for life-threatening or near-fatal features. Do not discharge until stable (PEF above 75%, off nebulisers) with a steroid course and follow-up." },
      { id: "resp_occupational_asthma", cluster: "Airways disease", name: "Occupational asthma", keyFacts: "Asthma caused or worsened by a workplace sensitiser; symptoms characteristically improve away from work.", epidemiology: "A leading occupational lung disease, important to identify early for prevention and compensation.", aetiology: "Workplace sensitisers such as isocyanates (paint spraying), flour, wood dust, animal proteins and latex.", pathophysiology: "Sensitisation to an inhaled workplace agent provokes an airway inflammatory response and bronchial hyper-responsiveness.", presentation: "Wheeze, cough and breathlessness that worsen at work and improve on days off and during holidays.", investigations: "Serial peak flow recordings at and away from work, spirometry, and specific challenge or IgE testing.", treatment: "Removal from exposure is the key step, alongside standard asthma therapy and reporting as an occupational disease." },
      { id: "resp_copd", management: {"def": "A[\"COPD, breathless or exacerbating\"]:::start --> B[\"SABA or SAMA as needed\"]:::good\nA --> H[\"Stop smoking, vaccines, pulmonary rehab\"]:::process\nB --> C{\"Asthmatic / steroid-responsive features?\"}:::decision\nC -- \"no\" --> D[\"LABA + LAMA\"]:::good\nC -- \"yes\" --> E[\"LABA + ICS\"]:::good\nD --> F{\"Ongoing symptoms or exacerbations?\"}:::decision\nE --> F\nF -- \"yes\" --> G[\"Triple therapy: LABA + LAMA + ICS\"]:::good", "tips": {"A": "Fixed airflow obstruction (post-bronchodilator FEV1/FVC below 0.7) in a smoker; treat symptoms and prevent exacerbations.", "B": "Start a short-acting bronchodilator (beta-agonist or antimuscarinic) as needed.", "C": "Asthmatic/steroid-responsive features: previous asthma/atopy, high blood eosinophils, substantial FEV1 or peak-flow variability.", "D": "No asthmatic features: long-acting beta-agonist plus long-acting antimuscarinic.", "E": "Asthmatic features/steroid responsiveness: LABA plus inhaled corticosteroid.", "F": "Persisting day-to-day symptoms or exacerbations warrant stepping up.", "G": "Triple therapy: LABA + LAMA + ICS.", "H": "Most important is stopping smoking; plus flu and pneumococcal vaccination, pulmonary rehabilitation and self-management/rescue packs."}}, cluster: "Airways disease", name: "COPD", keyFacts: "A progressive, largely irreversible airflow obstruction, almost always caused by smoking.", epidemiology: "A major cause of morbidity and death, mostly in smokers over 35.", aetiology: "Cigarette smoking dominates; also occupational dusts and, in younger non-smokers, alpha-1 antitrypsin deficiency.", pathophysiology: "Chronic inflammation drives emphysema (alveolar destruction) and chronic bronchitis (mucus, airway narrowing), causing fixed airflow limitation and air trapping.", presentation: "Chronic productive cough, breathlessness, wheeze in a smoker over 35.", investigations: "Post-bronchodilator spirometry (FEV1/FVC <0.7), CXR, BMI, FBC.", treatment: "Stop smoking, vaccinate, pulmonary rehab; SABA/SAMA, then LABA/LAMA; add ICS if asthmatic features." },
      { id: "resp_iecopd", management: {"def": "A[\"Acute exacerbation of COPD\"]:::start -- \"medical therapy\" --> B[\"Increase SABA +/- ipratropium (nebuliser)\"]:::good\nB --> C[\"Oral prednisolone 30 mg for 5 days\"]:::good\nC --> D{\"Purulent sputum / infection?\"}:::decision\nD -- \"yes\" --> E[\"Antibiotic: amoxicillin, doxycycline or clarithromycin\"]:::good\nD -- \"no\" --> F[\"No antibiotic, review\"]:::good\nA -- \"respiratory support\" --> G[\"Controlled O2 via Venturi mask, check ABG\"]:::warn\nG --> H{\"Respiratory acidosis, pH under 7.35?\"}:::decision\nH -- \"yes\" --> I[\"NIV (BiPAP)\"]:::danger\nH -- \"no\" --> J[\"Continue therapy, monitor ABG\"]:::good\nI --> K[\"ICU / intubation if NIV fails\"]:::danger", "tips": {"A": "An acute, sustained worsening of COPD symptoms (breathlessness, cough, increased sputum volume and purulence, wheeze) beyond normal day-to-day variation; commonly triggered by viral or bacterial infection. Assess severity and for respiratory failure (NICE NG114/NG115). The two arrows from here are parallel arms - medical therapy and respiratory support are both given, not an either/or choice.", "B": "Step up inhaled bronchodilators: increase the dose and frequency of a short-acting beta-2 agonist (salbutamol) and add ipratropium; deliver by nebuliser if severe (air-driven, or oxygen-driven with care, in those at risk of CO2 retention).", "C": "Give oral prednisolone 30 mg once daily for 5 days (IV hydrocortisone if unable to take it orally) for all significant exacerbations.", "D": "Offer an antibiotic only if there is evidence of infection - more purulent sputum, or increased sputum volume or breathlessness (the Anthonisen criteria).", "E": "NICE NG114 first-line oral antibiotics: amoxicillin, doxycycline or clarithromycin for 5 days; send a sputum culture and adjust if not improving or at risk of resistant organisms (e.g. Pseudomonas in bronchiectasis).", "F": "If the exacerbation is not infective, withhold antibiotics; continue bronchodilators and steroids and review the response.", "G": "Give controlled oxygen: in COPD (at risk of hypercapnic type 2 respiratory failure) target saturations 88-92% using a 24-28% Venturi mask, and check an arterial blood gas for CO2 retention and acidosis.", "H": "A raised PaCO2 with a low pH (respiratory acidosis, pH under 7.35) despite optimal medical therapy signals type 2 respiratory failure.", "I": "Start non-invasive ventilation (BiPAP) for persistent hypercapnic respiratory acidosis (pH 7.25-7.35) after about 1 hour of maximal medical therapy.", "J": "If there is no acidosis, continue nebulisers, steroids and any antibiotic; monitor with repeat arterial blood gases and observations.", "K": "Consider intubation and intensive care if NIV fails or the pH is under 7.25; make a ceiling-of-care decision early."}}, cluster: "Airways disease", name: "Infective exacerbation of COPD (IECOPD)", keyFacts: "An acute, sustained worsening of COPD symptoms beyond normal day-to-day variation that needs a step-up in treatment; most are triggered by infection, and it is a leading cause of emergency hospital admission.", epidemiology: "Very common and a major cause of emergency respiratory admissions and bed-days; frequent exacerbations accelerate lung-function decline and increase mortality.", aetiology: "Often infective - viruses (rhinovirus, influenza, RSV) and bacteria (Haemophilus influenzae, Streptococcus pneumoniae, Moraxella catarrhalis; Pseudomonas in severe disease); non-infective triggers include air pollution and treatment non-adherence.", pathophysiology: "Increased airway inflammation, bronchoconstriction and mucus worsen the underlying airflow obstruction and gas trapping and impair gas exchange; severe cases develop type 2 respiratory failure with CO2 retention and respiratory acidosis.", presentation: "Increased breathlessness, cough, wheeze and increased sputum volume and purulence; may show accessory muscle use, cyanosis, and signs of CO2 retention (drowsiness, confusion, flap, bounding pulse).", investigations: "Arterial blood gas (type 1 vs type 2 failure, pH), chest X-ray (exclude pneumonia/pneumothorax), ECG, FBC, U&E and CRP; sputum culture if purulent, blood cultures if febrile, and a theophylline level if on it.", treatment: "Increase nebulised bronchodilators (salbutamol and ipratropium), oral prednisolone 30 mg for 5 days, and antibiotics if the sputum is purulent (amoxicillin, doxycycline or clarithromycin); controlled oxygen targeting 88-92% via a Venturi mask, ABG-guided; NIV for persistent hypercapnic acidosis, and consider ICU." },
      { id: "resp_a1ad", cluster: "Airways disease", name: "Alpha-1 antitrypsin deficiency", keyFacts: "An inherited deficiency of a protease inhibitor causing early-onset emphysema and liver disease.", epidemiology: "Suspect it in COPD or emphysema in young patients who have never smoked or smoked little.", aetiology: "Autosomal co-dominant mutations (commonly the Z allele) reducing alpha-1 antitrypsin production.", pathophysiology: "Without alpha-1 antitrypsin to oppose neutrophil elastase, unchecked elastase destroys alveolar walls; abnormal protein accumulates in hepatocytes, causing liver disease.", presentation: "Breathlessness and basal panacinar emphysema in early adulthood, often with deranged liver function or cirrhosis.", investigations: "Serum alpha-1 antitrypsin level, genotyping, spirometry, CT chest and liver assessment.", treatment: "Stopping smoking is essential; standard COPD therapy and liver care; alpha-1 antitrypsin replacement in selected cases." },
      { id: "resp_bronchiectasis", cluster: "Airways disease", name: "Bronchiectasis", keyFacts: "Permanent abnormal dilatation of the bronchi with chronic productive cough and recurrent infection.", epidemiology: "Less common than asthma or COPD but an important cause of chronic cough.", aetiology: "Post-infective (whooping cough, TB), cystic fibrosis, immunodeficiency, ciliary dysfunction and allergic bronchopulmonary aspergillosis.", pathophysiology: "A vicious cycle of infection and inflammation damages and dilates airway walls, impairing mucociliary clearance and predisposing to further infection.", presentation: "Chronic cough with copious purulent sputum, recurrent infections, coarse crackles.", investigations: "High-resolution CT, sputum culture, immunoglobulins, CF screen if young.", treatment: "Airway clearance physiotherapy, treat exacerbations promptly, manage cause." },
      { id: "resp_uri", cluster: "Respiratory infection", name: "Upper respiratory tract infection", keyFacts: "A self-limiting viral infection of the upper airway; antibiotics are usually unnecessary.", epidemiology: "Extremely common, especially in children and during winter.", aetiology: "Rhinoviruses and other respiratory viruses, spread by droplets and direct contact.", pathophysiology: "Viral infection of the nasopharyngeal mucosa provokes inflammation and mucus, producing the familiar coryzal symptoms.", presentation: "Coryza, sore throat, cough, low-grade fever; usually self-limiting and viral.", investigations: "Clinical; FeverPAIN/Centor for sore throat.", treatment: "Reassure, safety-net, symptomatic care; antibiotics only when bacterial features." },
      { id: "resp_acute_bronchitis", management: {"def": "A[\"Acute cough with lower respiratory symptoms\"]:::start --> B[\"Assess: systemically unwell? focal chest signs?\"]:::process\nB --> C{\"Pneumonia suspected?\"}:::decision\nC -- \"yes\" --> D[\"CXR and treat as pneumonia (CRB65/CURB65)\"]:::danger\nC -- \"no\" --> E[\"Acute bronchitis: self-limiting, usually viral\"]:::good\nE --> F{\"Systemically very unwell or serious illness?\"}:::decision\nF -- \"yes\" --> G[\"Immediate antibiotic: doxycycline first-line in adults\"]:::warn\nF -- \"no\" --> H{\"Higher risk of complications?\"}:::decision\nH -- \"yes\" --> I[\"Back-up (delayed) prescription\"]:::good\nH -- \"no\" --> J[\"No antibiotic: self-care, honey, analgesia\"]:::good\nG --> K[\"Safety-net advice, review if worsening\"]:::good\nI --> K\nJ --> K", "tips": {"A": "Acute bronchitis presents as an acute cough (often following a coryzal illness) lasting up to 3-4 weeks, with chest soreness or wheeze but no consolidation - the main task is to separate it from pneumonia.", "B": "Assess for features of a more serious lower respiratory tract infection: high fever, tachypnoea, tachycardia, hypoxia, confusion, and focal chest signs (crackles, bronchial breathing, dullness to percussion).", "C": "Pneumonia is suggested by focal chest signs plus systemic illness; acute bronchitis typically has a well patient and a normal or near-normal chest examination.", "D": "If pneumonia is suspected, arrange a chest X-ray, score severity (CRB65 in the community, CURB65 in hospital) and treat via the pneumonia pathway rather than the acute-cough pathway.", "E": "NICE NG117: acute cough associated with an upper respiratory tract infection or acute bronchitis is usually viral and self-limiting, lasting around 3 weeks; antibiotics make little difference to symptoms or duration.", "F": "Offer an immediate antibiotic if the person is systemically very unwell, or has symptoms or signs of a more serious illness or complication.", "G": "NICE NG117 first-line for adults is doxycycline (200 mg on day 1, then 100 mg daily, 5 days total); alternatives are amoxicillin, clarithromycin or erythromycin (erythromycin in pregnancy). Doxycycline is contraindicated in pregnancy and in children under 12.", "H": "Consider a back-up prescription for people at higher risk of complications: significant heart, lung, liver, kidney or neuromuscular disease, immunosuppression, cystic fibrosis, frailty or advanced age, and young children born prematurely.", "I": "A back-up (delayed) prescription is issued with advice to use it only if symptoms worsen rapidly or significantly, or do not start to improve - this cuts antibiotic use without increasing complications.", "J": "For most people give no antibiotic: advise self-care with adequate fluids, simple analgesia or antipyretics, and honey (in those over 1 year), which NICE supports for symptom relief.", "K": "Always safety-net: explain the cough may last 3-4 weeks, and advise seeking review if they become systemically unwell, develop breathlessness or chest pain, cough up blood, or fail to improve."}, "source": "NICE"}, cluster: "Respiratory infection", name: "Acute bronchitis", keyFacts: "An acute, usually viral and self-limiting inflammation of the large airways causing a cough that can last 3-4 weeks; the key skill is distinguishing it from pneumonia, since most cases need no antibiotic.", epidemiology: "Very common and peaks in autumn and winter; a leading reason for primary-care consultation and one of the commonest sources of inappropriate antibiotic prescribing.", aetiology: "Viral in around 90% of cases (rhinovirus, influenza, parainfluenza, RSV, coronavirus, adenovirus); bacterial causes are uncommon (Mycoplasma pneumoniae, Chlamydophila pneumoniae, Bordetella pertussis). Smoking and air pollution are risk factors.", pathophysiology: "Infection of the tracheobronchial epithelium causes mucosal inflammation, oedema and increased mucus production with impaired ciliary clearance; the resulting transient bronchial hyper-responsiveness can prolong the cough for weeks after the infection itself has cleared.", presentation: "An acute cough, initially dry then productive of clear, yellow or green sputum (colour does not indicate bacterial infection), often after a coryzal illness, with chest soreness, wheeze and mild breathlessness; the patient is systemically well with a normal or near-normal chest examination and no focal consolidation signs.", investigations: "Usually a clinical diagnosis needing no investigation. Consider a chest X-ray if pneumonia is suspected (focal signs, high fever, tachypnoea, hypoxia or systemic illness); a point-of-care CRP can guide antibiotic decisions where the diagnosis is uncertain; consider pertussis testing for a paroxysmal cough with whoop or post-tussive vomiting.", treatment: "Reassurance and self-care - most resolve without antibiotics; fluids, simple analgesia or antipyretics and honey for symptom relief. Do not offer a routine antibiotic; consider a back-up (delayed) prescription for those at higher risk of complications, and an immediate antibiotic (doxycycline first-line in adults) if systemically very unwell. Give safety-net advice on when to seek review." },
      { id: "resp_cap", management: {"def": "A[\"Community-acquired pneumonia\"]:::start --> B[\"Assess severity: CRB65 / CURB65\"]:::process\nB --> C{\"Score\"}:::decision\nC -- \"0-1 (low)\" --> D[\"Home: oral amoxicillin\"]:::good\nC -- \"2 (moderate)\" --> E[\"Consider hospital: dual therapy\"]:::good\nC -- \"3+ (severe)\" --> F[\"Admit: IV antibiotics, consider ICU\"]:::danger\nD --> G[\"Review at 48-72 h; safety-net\"]:::process\nE --> G", "tips": {"A": "Fever, cough and breathlessness with focal chest signs and consolidation on chest X-ray; severity guides setting and antibiotics.", "B": "CRB65 in the community (confusion, respiratory rate 30+, BP 90/60 or less, age 65+); add urea for CURB65 in hospital.", "C": "The score maps to mortality risk and the setting of care.", "D": "Low risk: treat at home with oral amoxicillin (macrolide or doxycycline if penicillin-allergic), usually 5 days.", "E": "Moderate: consider hospital assessment; dual therapy with amoxicillin plus a macrolide.", "F": "Severe: admit, IV co-amoxiclav plus a macrolide, and assess for critical care.", "G": "Review response at 48–72 hours; reconsider diagnosis/complications (effusion, empyema) if not improving."}}, cluster: "Respiratory infection", name: "Community-acquired pneumonia", keyFacts: "Infection of the lung parenchyma acquired outside hospital; severity is graded by CURB-65.", epidemiology: "Common, with higher incidence and mortality at the extremes of age.", aetiology: "Streptococcus pneumoniae is commonest; also Haemophilus, Mycoplasma, Legionella and viruses; aspiration in frail patients.", pathophysiology: "Pathogens reach the alveoli and provoke an inflammatory exudate that consolidates lung tissue and impairs gas exchange.", presentation: "Fever, productive cough, pleuritic pain, focal crackles, bronchial breathing.", investigations: "CXR, CRP, U&E, CURB-65, sputum/blood cultures if severe.", treatment: "Amoxicillin for low severity; add macrolide or use co-amoxiclav for higher CURB-65; admit if score high." },
      { id: "resp_hap", management: {"def": "A[\"Hospital-acquired pneumonia (48h+ after admission)\"]:::start --> B[\"CXR, cultures, bloods, ABG\"]:::process\nB --> C[\"Start empirical antibiotics within 4 h\"]:::good\nC --> D{\"Severe or high resistance risk?\"}:::decision\nD -- \"no\" --> E[\"Co-amoxiclav (oral if able)\"]:::good\nD -- \"yes\" --> F[\"Piperacillin-tazobactam (broad-spectrum IV)\"]:::good\nE --> G{\"MRSA suspected?\"}:::decision\nF --> G\nG -- \"yes\" --> H[\"Add vancomycin or teicoplanin\"]:::good\nG -- \"no\" --> I[\"Continue, review at 48-72 h\"]:::process\nH --> I\nI --> J[\"De-escalate on cultures, 5-7 day course\"]:::good", "tips": {"A": "Pneumonia developing 48 hours or more after admission (and not incubating on arrival); includes ventilator-associated pneumonia. Hospital flora mean more resistant organisms than community-acquired pneumonia (NICE NG139).", "B": "Chest X-ray for new infiltrates, plus sputum (or endotracheal/BAL) and blood cultures, FBC, CRP, U&E and an ABG; grade severity and resistance risk.", "C": "Start empirical antibiotics promptly (within about 4 hours), guided by severity, local resistance patterns and recent microbiology.", "D": "Judge severity and the risk of resistant organisms (recent broad-spectrum antibiotics, prolonged admission, known colonisation, mechanical ventilation).", "E": "Non-severe, low resistance risk: co-amoxiclav (oral if able); alternatives include doxycycline, cefalexin, co-trimoxazole or levofloxacin.", "F": "Severe, or high risk of resistance: a broad-spectrum IV agent such as piperacillin-tazobactam (or ceftazidime, meropenem or levofloxacin) with anti-pseudomonal cover.", "G": "Consider MRSA if there is known carriage, recent MRSA infection or high local prevalence.", "H": "If MRSA is suspected or confirmed, add vancomycin, teicoplanin or linezolid.", "I": "Review the clinical response and cultures at 48-72 hours; look for complications (effusion, empyema) if not improving.", "J": "De-escalate to a narrower agent guided by cultures; a 5-7 day course is usually sufficient."}}, cluster: "Respiratory infection", name: "Hospital-acquired pneumonia (HAP)", keyFacts: "Pneumonia developing 48 hours or more after admission (not incubating on arrival); tends to involve more resistant organisms than community-acquired pneumonia and includes ventilator-associated pneumonia.", epidemiology: "One of the commonest hospital-acquired infections, with high morbidity and mortality - especially ventilator-associated pneumonia in intensive care.", aetiology: "Often Gram-negative bacilli (Pseudomonas aeruginosa, Klebsiella, E. coli, Enterobacter) and Staphylococcus aureus including MRSA; risk factors include mechanical ventilation, reduced consciousness, immobility, nasogastric tubes and recent surgery.", pathophysiology: "Micro-aspiration of colonised oropharyngeal and gastric secretions carrying virulent hospital flora into the lower airways overwhelms impaired host defences, producing an inflammatory consolidation.", presentation: "New fever, purulent sputum, cough, breathlessness and hypoxia with new chest X-ray infiltrates arising 48 hours or more into admission, often in a ventilated or debilitated patient.", investigations: "Chest X-ray, FBC, CRP, U&E and ABG; sputum (or endotracheal/BAL) and blood cultures with sensitivities to guide and de-escalate antibiotics.", treatment: "Prompt empirical antibiotics guided by severity and local resistance (NICE NG139): co-amoxiclav if non-severe, or piperacillin-tazobactam (broad-spectrum IV) if severe or resistance risk, adding MRSA cover (vancomycin/teicoplanin) if suspected; de-escalate on cultures, plus oxygen and supportive care." },
      { id: "resp_tb", cluster: "Respiratory infection", name: "Tuberculosis", keyFacts: "A chronic granulomatous infection by Mycobacterium tuberculosis; a notifiable disease, latent or active.", epidemiology: "Higher incidence with migration from endemic areas, HIV and social deprivation.", aetiology: "Spread by respiratory droplets; reactivation risk rises with immunosuppression, diabetes and malnutrition.", pathophysiology: "Inhaled bacilli are walled off in granulomas; failure of containment allows active disease, classically caseating necrosis in the lung apices.", presentation: "Chronic cough, weight loss, night sweats, haemoptysis; risk with immunosuppression/travel.", investigations: "CXR, sputum smear and culture, NAAT; interferon-gamma release assay for latent TB.", treatment: "RIPE for 2 months then rifampicin and isoniazid for 4; notify; directly observed therapy if needed." },
      { id: "resp_aspergilloma", cluster: "Respiratory infection", name: "Aspergilloma", keyFacts: "A fungal ball (mycetoma) of Aspergillus growing within a pre-existing lung cavity; the classic complication is haemoptysis, which can be massive.", epidemiology: "Occurs in people with old lung cavities - most often from previous tuberculosis, and also sarcoidosis, bronchiectasis, a healed lung abscess or emphysematous bullae.", aetiology: "Saprophytic colonisation of a pre-formed cavity by Aspergillus fumigatus without tissue invasion - unlike invasive aspergillosis (in the immunocompromised) and allergic bronchopulmonary aspergillosis (a hypersensitivity reaction in asthma or cystic fibrosis).", pathophysiology: "The fungus forms a tangled ball of hyphae, fibrin and mucus that lies free within the cavity; erosion of bronchial vessels in the cavity wall causes haemoptysis.", presentation: "Often asymptomatic and found incidentally; haemoptysis (in up to 90%, occasionally life-threatening), chronic cough, malaise and weight loss.", investigations: "Chest X-ray or CT showing a rounded mass within a cavity surrounded by a crescent of air (the 'air crescent sign') that characteristically moves when the patient changes position; positive serum Aspergillus precipitins (IgG); sputum culture.", treatment: "An asymptomatic aspergilloma is often just monitored; massive or recurrent haemoptysis is treated by bronchial artery embolisation or surgical resection; antifungal drugs have a limited role; optimise the underlying lung disease." },
      { id: "resp_ipf", cluster: "Interstitial & granulomatous disease", name: "Idiopathic pulmonary fibrosis", keyFacts: "A progressive fibrosing interstitial lung disease of unknown cause with a poor prognosis.", epidemiology: "Mainly older adults, commoner in men and ex-smokers.", aetiology: "Idiopathic, with risk from smoking, occupational dusts and genetic factors.", pathophysiology: "Repeated alveolar epithelial injury triggers aberrant fibroblast activation and progressive scarring (a usual interstitial pneumonia pattern).", presentation: "Progressive exertional breathlessness and a dry cough, with fine bibasal end-inspiratory crackles and finger clubbing.", investigations: "High-resolution CT (subpleural reticulation, honeycombing), restrictive spirometry with reduced gas transfer, and biopsy if uncertain.", treatment: "Antifibrotics (pirfenidone, nintedanib) slow decline; pulmonary rehabilitation, oxygen and lung transplantation in selected patients." },
      { id: "resp_drug_fibrosis", cluster: "Interstitial & granulomatous disease", name: "Drug-induced pulmonary fibrosis", keyFacts: "Interstitial lung fibrosis caused by certain drugs; key culprits include amiodarone, methotrexate, nitrofurantoin and bleomycin.", epidemiology: "An important and sometimes reversible cause of interstitial lung disease that is easily missed.", aetiology: "Drugs such as amiodarone, methotrexate, nitrofurantoin, bleomycin and some other chemotherapy agents.", pathophysiology: "Direct toxicity or an immune reaction provokes alveolar inflammation that progresses to interstitial fibrosis.", presentation: "Progressive exertional breathlessness and a dry cough in a patient on a culprit drug, with bibasal crackles.", investigations: "A careful drug history, high-resolution CT, and lung function (restrictive with reduced gas transfer), excluding other causes.", treatment: "Stop the offending drug; corticosteroids in some cases; supportive care." },
      { id: "resp_sarcoidosis", cluster: "Interstitial & granulomatous disease", name: "Sarcoidosis", keyFacts: "A multisystem granulomatous disease that most often affects the lungs and lymph nodes; many cases resolve spontaneously.", epidemiology: "Commoner in young adults and in people of African-Caribbean descent.", aetiology: "Unknown; an exaggerated immune response to an unidentified trigger in susceptible people.", pathophysiology: "Formation of non-caseating granulomas in affected organs disrupts their structure and function.", presentation: "Often incidental bilateral hilar lymphadenopathy; cough and breathlessness; or acute Lofgren syndrome (erythema nodosum, arthralgia, fever); plus eye and skin features.", investigations: "CXR (bilateral hilar lymphadenopathy), serum ACE, calcium, high-resolution CT, and biopsy showing non-caseating granulomas.", treatment: "Many cases need only observation; corticosteroids for significant pulmonary, cardiac, neurological or ocular involvement." },
      { id: "resp_asbestosis", cluster: "Pneumoconiosis", name: "Asbestosis", keyFacts: "Diffuse interstitial pulmonary fibrosis caused by inhaled asbestos fibres, developing after a long latency and characteristically affecting the lower zones.", epidemiology: "An occupational disease of past asbestos exposure (construction, shipbuilding, insulation and lagging); risk relates to cumulative exposure, with a latent period of decades.", aetiology: "Inhalation of asbestos fibres (amphibole types such as crocidolite are the most fibrogenic and carcinogenic); a prescribed industrial disease eligible for compensation in the UK.", pathophysiology: "Retained fibres provoke macrophage-driven inflammation and progressive interstitial fibrosis (a usual-interstitial-pneumonia pattern), with asbestos (ferruginous) bodies on histology; asbestos is also carcinogenic to the lung and pleura.", presentation: "Progressive exertional breathlessness, a dry cough, fine bibasal end-inspiratory crackles and finger clubbing.", investigations: "Chest X-ray/high-resolution CT (lower-zone reticulonodular fibrosis, sometimes with pleural plaques); spirometry showing a restrictive pattern with reduced gas transfer; occupational history.", treatment: "No treatment reverses the fibrosis - supportive care, smoking cessation (which greatly multiplies the lung-cancer risk), vaccination and oxygen as needed; monitor and counsel for lung cancer and mesothelioma; advise on compensation. See also the Asbestos-related lung disease and Mesothelioma topics." },
      { id: "resp_silicosis", cluster: "Pneumoconiosis", name: "Silicosis", keyFacts: "Nodular pulmonary fibrosis caused by inhaling crystalline silica dust; characteristically affects the upper zones and markedly increases the risk of tuberculosis.", epidemiology: "An occupational disease of mining, quarrying, stone-masonry, sandblasting, foundry work and (increasingly) engineered-stone worktop fabrication.", aetiology: "Inhalation of respirable crystalline silica (silicon dioxide); acute, accelerated and chronic forms depend on the intensity of exposure.", pathophysiology: "Silica is highly toxic to macrophages, which release enzymes and cytokines that drive fibrosis and form silicotic nodules; it impairs killing of mycobacteria (hence the tuberculosis risk) and can progress to progressive massive fibrosis.", presentation: "Cough and progressive breathlessness; often asymptomatic early; may present with features of complicating tuberculosis.", investigations: "Chest X-ray/CT (upper-zone nodular fibrosis; 'egg-shell' calcification of the hilar lymph nodes is characteristic); restrictive spirometry; screen for tuberculosis; occupational history.", treatment: "No curative treatment - avoid further exposure, supportive care and smoking cessation, with a low threshold for investigating and treating tuberculosis; a prescribed industrial disease eligible for compensation." },
      { id: "resp_cwp", cluster: "Pneumoconiosis", name: "Coal worker's pneumoconiosis", keyFacts: "Pulmonary fibrosis from inhaled coal dust, ranging from asymptomatic simple pneumoconiosis to disabling progressive massive fibrosis; the upper zones predominate.", epidemiology: "An occupational disease of coal miners, related to cumulative dust exposure over years underground.", aetiology: "Inhalation and retention of coal dust; coexisting rheumatoid arthritis produces Caplan syndrome (large pulmonary nodules).", pathophysiology: "Coal-dust-laden macrophages accumulate to form coal macules and nodules (simple pneumoconiosis); in some these coalesce into masses of progressive massive fibrosis with cavitation and architectural distortion.", presentation: "Simple disease is usually asymptomatic; progressive massive fibrosis causes breathlessness, cough and black sputum (melanoptysis), and can lead to respiratory failure and cor pulmonale.", investigations: "Chest X-ray/CT (upper-zone small nodules in simple disease; large fibrotic masses in progressive massive fibrosis); spirometry (mixed or restrictive); occupational history.", treatment: "No specific treatment - avoid further exposure, supportive care, smoking cessation and vaccination; a prescribed industrial disease eligible for compensation." },
      { id: "resp_lung_cancer", cluster: "Lung cancer & pleural disease", name: "Lung cancer", keyFacts: "A leading cause of cancer death, divided into non-small-cell and the more aggressive small-cell types.", epidemiology: "Strongly age- and smoking-related; one of the commonest cancers in the UK.", aetiology: "Smoking causes the great majority; also asbestos, radon and air pollution.", pathophysiology: "Accumulated carcinogen-induced mutations transform bronchial epithelium, with local invasion, paraneoplastic effects and metastasis.", presentation: "Haemoptysis, weight loss, persistent cough, finger clubbing; may cause SVC obstruction or hoarseness.", investigations: "Urgent CXR then contrast CT, biopsy/bronchoscopy, PET for staging.", treatment: "Surgery, radiotherapy, chemo or immunotherapy by type and stage; refer on 2-week-wait." },
      { id: "resp_mesothelioma", cluster: "Lung cancer & pleural disease", name: "Mesothelioma", keyFacts: "An aggressive malignancy of the pleura strongly linked to asbestos exposure, with long latency and poor prognosis.", epidemiology: "Occurs decades after asbestos exposure; commoner in men with a relevant occupational history.", aetiology: "Asbestos exposure, often occupational, with a latency of 20 to 40 years.", pathophysiology: "Asbestos fibres provoke chronic pleural inflammation and DNA damage, leading to malignant transformation of mesothelial cells.", presentation: "Breathlessness, chest pain and an often blood-stained pleural effusion with weight loss, on a background of asbestos exposure.", investigations: "CXR and CT (pleural thickening and effusion), pleural fluid cytology and pleural biopsy for diagnosis.", treatment: "Largely palliative (chemotherapy, pleurodesis, radiotherapy); industrial compensation and reporting given the occupational link." },
      { id: "resp_effusion", cluster: "Lung cancer & pleural disease", name: "Pleural effusion", keyFacts: "Fluid in the pleural space; Light's criteria separate transudates from exudates.", epidemiology: "Common, reflecting a wide range of cardiac, infective and malignant causes.", aetiology: "Transudates from heart failure, cirrhosis or low albumin; exudates from infection, malignancy or pulmonary embolism.", pathophysiology: "Imbalance of hydrostatic and oncotic pressures (transudate), or increased capillary permeability (exudate), lets fluid accumulate and compress the lung.", presentation: "Breathlessness, reduced expansion, stony dull percussion, reduced breath sounds.", investigations: "CXR, pleural ultrasound, diagnostic aspiration with Light's criteria.", treatment: "Treat cause; drain if symptomatic; transudate vs exudate guides workup." },
      { id: "resp_pneumothorax", management: {"source": "BTS", "def": "A[\"Spontaneous pneumothorax\"]:::start --> B{\"Tension pneumothorax?\"}:::decision\nB -- \"yes (deviated trachea, shock)\" --> C[\"Needle decompression, then chest drain\"]:::danger\nB -- \"no\" --> D{\"Breathless or large (2 cm+)?\"}:::decision\nD -- \"no, small primary\" --> E[\"Observe, discharge with review\"]:::good\nD -- \"yes\" --> F[\"Needle aspiration (primary)\"]:::good\nF -- \"fails / secondary\" --> G[\"Chest drain\"]:::good\nA --> H[\"Stop smoking, avoid diving after\"]:::process", "tips": {"A": "Air in the pleural space collapsing the lung - primary (no lung disease) or secondary (e.g. COPD). Assess for tension first.", "B": "A tension pneumothorax (tracheal deviation, hypotension, distended neck veins, severe distress) is a clinical emergency - do not wait for a chest X-ray.", "C": "Tension: immediate needle decompression (large cannula, 2nd intercostal space mid-clavicular line or 4th-5th anterior/mid-axillary), then a chest drain.", "D": "For non-tension, size (2 cm or more at the hilum on CXR) and breathlessness guide treatment.", "E": "Small primary pneumothorax with no breathlessness: consider discharge with outpatient review and safety-netting (high-flow oxygen if admitted).", "F": "Breathless or large primary pneumothorax: needle aspiration first-line.", "G": "If aspiration fails, or for a secondary pneumothorax (larger or breathless), insert a chest drain.", "H": "Advise smoking cessation; avoid air travel until resolved and never scuba dive again after a pneumothorax unless definitive surgery. (2023 BTS guidance favours symptom-directed and ambulatory options.)"}}, cluster: "Lung cancer & pleural disease", name: "Pneumothorax", keyFacts: "Air in the pleural space causing lung collapse; a tension pneumothorax is an immediately life-threatening emergency.", epidemiology: "Primary spontaneous type favours tall, thin young men; secondary type complicates lung disease.", aetiology: "Spontaneous (ruptured bleb), secondary to COPD or asthma, traumatic, or iatrogenic (lines, ventilation).", pathophysiology: "Air enters the pleural space and abolishes the negative pressure, so the lung collapses; a one-way valve causes tension and mediastinal shift.", presentation: "Sudden pleuritic chest pain and breathlessness; tension gives tracheal deviation and shock.", investigations: "CXR (avoid in suspected tension — treat clinically).", treatment: "Tension: immediate large-bore decompression. Otherwise observe, aspirate, or chest drain by size/symptoms." },
      { id: "resp_atelectasis", cluster: "Lung cancer & pleural disease", name: "Atelectasis", keyFacts: "Collapse or incomplete expansion of part or all of a lung, reducing the volume of aerated lung; a very common postoperative complication.", epidemiology: "Extremely common after general anaesthesia and thoraco-abdominal surgery; also seen with airway obstruction and pleural disease.", aetiology: "Obstructive (mucus plugging - the commonest, e.g. postoperative; tumour; inhaled foreign body); compressive (pleural effusion, pneumothorax, large bullae); and relaxation/adhesive (surfactant loss, shallow breathing, hypoventilation).", pathophysiology: "Loss of aeration lets alveoli collapse - gas is absorbed distal to an obstruction, or the lung is compressed from outside - producing ventilation-perfusion mismatch, shunt and hypoxaemia and predisposing to infection.", presentation: "Often asymptomatic if small; larger collapse causes breathlessness, reduced expansion, dullness to percussion and reduced breath sounds over the area, with the trachea and mediastinum pulled towards the collapse; postoperative fever.", investigations: "Chest X-ray (volume loss - a raised hemidiaphragm, crowded ribs, and tracheal/mediastinal shift towards the opacity); CT and bronchoscopy if an obstructing lesion or foreign body is suspected.", treatment: "Treat the cause; chest physiotherapy, deep-breathing exercises and incentive spirometry, good analgesia and early mobilisation after surgery; bronchoscopy to clear a mucus plug or foreign body; re-expand the lung by draining a compressing effusion or pneumothorax." },
      { id: "resp_osa", cluster: "Sleep-disordered breathing & critical care", name: "Obstructive sleep apnoea", keyFacts: "Repeated upper-airway collapse in sleep causing apnoeas, daytime sleepiness and a driving-safety risk.", epidemiology: "Common and underdiagnosed; strongly associated with obesity and middle age.", aetiology: "Obesity, large neck circumference, retrognathia, alcohol and sedatives.", pathophysiology: "Loss of pharyngeal muscle tone in sleep lets the airway collapse, causing intermittent hypoxia and arousals that fragment sleep and raise cardiovascular risk.", presentation: "Snoring, witnessed apnoeas, daytime sleepiness, morning headache; often obese.", investigations: "Epworth score, polysomnography/oximetry.", treatment: "Weight loss, avoid alcohol, CPAP; advise DVLA and driving rules." },
      { id: "resp_pulmonary_oedema", management: {"def": "A[\"Acute pulmonary oedema\"]:::start --> B[\"Sit up, high-flow oxygen if hypoxic\"]:::good\nB --> C[\"IV loop diuretic (furosemide)\"]:::good\nC --> D[\"IV nitrate if not hypotensive\"]:::good\nD --> E{\"Responding?\"}:::decision\nE -- \"yes\" --> F[\"Treat underlying cause, monitor\"]:::good\nE -- \"no\" --> G[\"CPAP / NIV for refractory hypoxia\"]:::warn\nG --> H{\"Cardiogenic shock?\"}:::decision\nH -- \"yes\" --> I[\"Inotropes/vasopressors, ITU, treat cause\"]:::danger\nH -- \"no\" --> J[\"Escalate diuretic/nitrate, senior review\"]:::warn", "tips": {"A": "Acute fluid accumulation in the alveoli and interstitium, most often acute cardiogenic (left ventricular failure); a medical emergency - assess ABCDE and start treatment immediately (NICE NG187 for acute heart failure).", "B": "Sit the patient upright and give high-flow oxygen if hypoxic (aim saturations 94-98%); attach monitoring and gain IV access.", "C": "Give an IV loop diuretic (furosemide) to offload fluid; monitor urine output, U&E and potassium.", "D": "Add an IV nitrate (GTN infusion) to reduce preload if the systolic blood pressure is adequate - do not use if hypotensive; avoid routine morphine.", "E": "Reassess breathlessness, saturations, blood pressure and urine output to judge the response.", "F": "If improving, treat the underlying cause (ischaemia, arrhythmia, valve disease, fluid overload) and continue monitoring and diuresis.", "G": "For refractory hypoxia or respiratory distress, start CPAP (or non-invasive ventilation) to improve oxygenation and reduce the work of breathing.", "H": "Check for cardiogenic shock - hypotension with poor perfusion despite adequate filling.", "I": "Cardiogenic shock: involve critical care, consider inotropes or vasopressors, and treat the cause (e.g. urgent revascularisation for MI).", "J": "Not responding without shock: escalate diuretic and nitrate therapy, get senior/cardiology review, and reconsider the underlying cause."}}, cluster: "Sleep-disordered breathing & critical care", name: "Pulmonary oedema", keyFacts: "Fluid accumulation in the lung interstitium and alveoli, most often acute cardiogenic (left ventricular failure); a medical emergency causing severe breathlessness and hypoxia.", epidemiology: "A common acute medical presentation, particularly in older patients with ischaemic or hypertensive heart disease.", aetiology: "Cardiogenic (acute left ventricular failure from MI, arrhythmia, severe hypertension, valve disease or fluid overload) or non-cardiogenic (ARDS, renal failure, neurogenic, high-altitude or negative-pressure).", pathophysiology: "Raised pulmonary capillary hydrostatic pressure (cardiogenic) or increased capillary permeability (non-cardiogenic) forces fluid into the interstitium and alveoli, impairing gas exchange and causing hypoxia.", presentation: "Acute severe breathlessness, orthopnoea and paroxysmal nocturnal dyspnoea with pink frothy sputum, distress, tachypnoea, bibasal crackles, a raised JVP and a gallop rhythm.", investigations: "ABG, chest X-ray (upper-lobe diversion, bat-wing shadowing, Kerley B lines, effusions), ECG, troponin, NT-proBNP, U&E and echocardiography to find the cause.", treatment: "Sit up and give high-flow oxygen, an IV loop diuretic (furosemide) and IV nitrates if not hypotensive; treat the underlying cause; CPAP or non-invasive ventilation for refractory hypoxia, and inotropes with critical care if cardiogenic shock. Avoid routine morphine." },
      { id: "resp_ards", cluster: "Sleep-disordered breathing & critical care", name: "Acute respiratory distress syndrome (ARDS)", keyFacts: "Acute, severe, non-cardiogenic pulmonary oedema causing refractory hypoxaemia; defined by the Berlin criteria.", epidemiology: "A common cause of respiratory failure in critically ill patients, with high mortality.", aetiology: "Sepsis and pneumonia are commonest; also aspiration, major trauma, pancreatitis, transfusion and burns.", pathophysiology: "Diffuse alveolar damage with increased capillary permeability floods the alveoli with protein-rich fluid, impairing gas exchange and lung compliance.", presentation: "Rapid-onset severe breathlessness and hypoxaemia within a week of an insult, with bilateral infiltrates not explained by heart failure.", investigations: "ABG (severe hypoxaemia, a low PaO2/FiO2 ratio), CXR (bilateral infiltrates), and echocardiography to exclude a cardiac cause.", treatment: "Treat the underlying cause; lung-protective ventilation (low tidal volume), proning and supportive intensive care." },
    ],
  },
  {
    id: "gastro",
    name: "Gastroenterology & Nutrition",
    icon: "🩻",
    conditions: [
      { id: "gi_gord", management: {"def": "A[\"GORD symptoms (heartburn, regurgitation)\"]:::start --> B{\"Red-flag features?\"}:::decision\nB -- \"yes\" --> C[\"Urgent upper GI endoscopy (2-week wait)\"]:::danger\nB -- \"no\" --> D[\"Lifestyle + full-dose PPI 4-8 weeks\"]:::good\nD --> E{\"Responded?\"}:::decision\nE -- \"yes\" --> F[\"Step down to lowest effective dose\"]:::good\nE -- \"no\" --> G[\"Test for H. pylori; endoscopy\"]:::good", "tips": {"A": "Reflux of acid causing heartburn/regurgitation; diagnosed clinically without endoscopy when there are no alarm features.", "B": "Alarm features: dysphagia, unintentional weight loss, GI bleeding/anaemia, persistent vomiting, or new dyspepsia over 55.", "C": "Refer on the suspected-cancer (2-week-wait) pathway for endoscopy if alarm features are present.", "D": "Lifestyle advice (weight, smaller meals, avoid triggers, raise the bed head) plus a full-dose proton-pump inhibitor for 4–8 weeks.", "E": "Review symptom response at the end of the course.", "F": "If controlled, step down to the lowest effective dose or on-demand use.", "G": "If not controlled: test-and-treat H. pylori, consider endoscopy, and trial a higher dose or an H2-receptor antagonist."}}, cluster: "Oesophagus & upper GI", name: "GORD", keyFacts: "Reflux of gastric acid into the oesophagus causing heartburn; alarm features warrant endoscopy.", epidemiology: "Very common, particularly with obesity.", aetiology: "Lower oesophageal sphincter dysfunction, hiatus hernia, obesity, pregnancy, smoking and certain foods.", pathophysiology: "Inappropriate sphincter relaxation lets acid reflux and inflame the oesophageal mucosa, which over time can cause Barrett's metaplasia.", presentation: "Retrosternal burning, acid regurgitation, worse lying down or after meals.", investigations: "Clinical; endoscopy if alarm features (dysphagia, weight loss, anaemia, age >55 persistent).", treatment: "Lifestyle, weight loss, PPI; test/treat H. pylori; fundoplication for refractory cases." },
      { id: "gi_barretts", management: {"def": "A[\"Chronic reflux symptoms, endoscopy performed\"]:::start --> B[\"Salmon-pink columnar mucosa 1 cm or more above the GOJ\"]:::process\nB --> C[\"Prague C and M classification, Seattle protocol biopsies\"]:::process\nC --> D{\"Histology: dysplasia?\"}:::decision\nD -- \"no dysplasia\" --> E{\"Segment length and intestinal metaplasia\"}:::decision\nE -- \"3 cm or longer\" --> F[\"Surveillance every 2 to 3 years\"]:::good\nE -- \"under 3 cm WITH intestinal metaplasia\" --> G[\"Surveillance every 3 to 5 years\"]:::good\nE -- \"under 3 cm, NO intestinal metaplasia\" --> H[\"Consider not offering routine surveillance\"]:::good\nD -- \"indefinite for dysplasia\" --> I[\"Optimise PPI, repeat endoscopy in 6 months\"]:::warn\nD -- \"dysplasia or stage 1 adenocarcinoma\" --> J[\"Refer to specialist oesophago-gastric MDT\"]:::danger\nJ --> K[\"Endoscopic resection of any visible lesion\"]:::good\nK --> L[\"Then radiofrequency ablation of residual Barrett's\"]:::good\nL --> M[\"Post-treatment endoscopic follow-up\"]:::good\nF --> N[\"PPI for symptoms, tailor interval by age, sex, family history, smoking\"]:::good\nG --> N\nH --> N", "tips": {"A": "Barrett's oesophagus is almost always an incidental finding at endoscopy done for reflux symptoms — it causes no symptoms of its own. Paradoxically, heartburn may IMPROVE as squamous epithelium is replaced, because the metaplastic columnar lining is less acid-sensitive.", "B": "The endoscopic diagnosis requires salmon-pink columnar mucosa extending at least 1 cm above the gastro-oesophageal junction. Anything under 1 cm is not called Barrett's, because the junction is irregular and short tongues are unreliable.", "C": "Describe the extent with the Prague classification: C is the circumferential length and M the maximal length of the segment. Take Seattle protocol biopsies — quadrantic biopsies every 2 cm (every 1 cm if dysplasia is suspected) plus targeted biopsies of any visible lesion. Histological confirmation is required, and any dysplasia should be confirmed by two gastrointestinal pathologists because of high inter-observer variability.", "D": "Everything downstream turns on the histology: no dysplasia, indefinite for dysplasia, or definite dysplasia (low or high grade) and early cancer.", "E": "Where there is no dysplasia, NICE NG231 sets the surveillance interval by segment length and whether intestinal metaplasia (goblet cells) is present. Length and intestinal metaplasia are the two strongest predictors of progression.", "F": "Long-segment Barrett's, 3 cm or longer: high-resolution white light endoscopy with Seattle protocol biopsies every 2 to 3 years.", "G": "Short-segment Barrett's, under 3 cm, WITH intestinal metaplasia: surveillance every 3 to 5 years.", "H": "Short-segment Barrett's WITHOUT intestinal metaplasia carries a very low risk of progression, and NICE advises considering not offering routine endoscopic surveillance at all, since the harms and cost may outweigh the benefit. Discuss this with the person.", "I": "Indefinite for dysplasia usually reflects inflammation obscuring the histology rather than true dysplasia. Optimise acid suppression with a proton pump inhibitor and repeat the endoscopy in about 6 months, so the biopsies can be read without active inflammation.", "J": "Confirmed low-grade or high-grade dysplasia, or stage 1 adenocarcinoma, should be managed by a specialist oesophago-gastric multidisciplinary team. Endoscopic treatment has largely replaced oesophagectomy for these early lesions.", "K": "Any visible lesion is removed first by endoscopic resection (endoscopic mucosal resection or endoscopic submucosal dissection). This is both therapeutic and the most accurate way to stage depth of invasion, which decides whether endoscopic cure is possible.", "L": "The residual flat Barrett's segment is then ablated, usually by radiofrequency ablation, to eradicate the remaining metaplastic epithelium and prevent metachronous lesions.", "M": "Continue endoscopic follow-up after successful eradication, since Barrett's can recur. Maintain proton pump inhibitor therapy.", "N": "All patients need a proton pump inhibitor for symptom control, plus weight loss and smoking cessation advice. NICE also advises assessing individual cancer risk from age, sex, family history of oesophageal cancer and smoking history, and tailoring the frequency of surveillance WITHIN the recommended intervals accordingly. Warn about red flags: new dysphagia, weight loss, vomiting or anaemia need urgent re-referral."}, "source": "NICE NG231"}, cluster: "Oesophagus & upper GI", name: "Barrett's oesophagus", keyFacts: "Metaplastic replacement of the normal squamous lining of the lower oesophagus by columnar epithelium, driven by chronic acid reflux. It is the only recognised precursor to oesophageal adenocarcinoma, which is why it is placed under endoscopic surveillance, although the absolute risk of progression is low at roughly 0.3% per year.", epidemiology: "Found in around 10% of people undergoing endoscopy for reflux symptoms. It is about twice as common in men, and commoner in white populations and with increasing age, central obesity and smoking.", aetiology: "Chronic gastro-oesophageal reflux is the dominant cause. Risk factors are long-standing reflux symptoms, male sex, age over 50, white ethnicity, central obesity, smoking, a hiatus hernia, and a family history of Barrett's or oesophageal adenocarcinoma. Helicobacter pylori infection is inversely associated and appears protective.", pathophysiology: "Repeated exposure to acid and bile injures the squamous epithelium, which is replaced by more acid-resistant columnar epithelium. Intestinal metaplasia, defined by the presence of goblet cells, carries the greatest risk. Accumulating genetic changes then drive the sequence of metaplasia to low-grade dysplasia to high-grade dysplasia to invasive adenocarcinoma, with segment length and dysplasia grade the main determinants of progression.", presentation: "Usually asymptomatic in itself and found incidentally at endoscopy for reflux. There is typically a long history of heartburn, regurgitation and an acid taste, and reflux symptoms may paradoxically improve as the less acid-sensitive columnar epithelium develops. New dysphagia, weight loss, vomiting or iron-deficiency anaemia suggest progression to carcinoma and warrant urgent referral.", investigations: "Upper gastrointestinal endoscopy showing salmon-pink columnar mucosa extending 1 cm or more above the gastro-oesophageal junction, described with the Prague C and M classification, and confirmed histologically. Biopsies follow the Seattle protocol: quadrantic every 2 cm, every 1 cm if dysplasia is suspected, plus targeted biopsies of visible lesions. Any dysplasia must be confirmed by two gastrointestinal pathologists because inter-observer variation is high.", treatment: "A proton pump inhibitor for symptom control, with weight loss and smoking cessation. Endoscopic surveillance follows NICE NG231: every 2 to 3 years for long-segment disease of 3 cm or more, every 3 to 5 years for short-segment disease under 3 cm with intestinal metaplasia, and consider not offering routine surveillance for short-segment disease without intestinal metaplasia; tailor within these intervals using age, sex, family history and smoking. Indefinite for dysplasia: optimise the proton pump inhibitor and repeat endoscopy at 6 months. Dysplasia or stage 1 adenocarcinoma: specialist multidisciplinary team, endoscopic resection of visible lesions followed by radiofrequency ablation of the residual segment." },
      { id: "gi_oesophageal_ca", management: {"def": "A[\"Progressive dysphagia or unexplained weight loss\"]:::start --> B{\"NICE suspected-cancer criteria met?\"}:::decision\nB -- \"no\" --> C[\"Manage as dyspepsia, review and re-refer if persistent\"]:::good\nB -- \"yes\" --> D[\"Urgent upper GI endoscopy within 2 weeks\"]:::danger\nD --> E[\"Biopsy confirms carcinoma\"]:::process\nE --> F[\"Stage: CT chest-abdomen-pelvis, PET-CT, endoscopic ultrasound\"]:::process\nF --> G[\"Specialist oesophago-gastric MDT\"]:::process\nG --> H{\"Extent and fitness for curative treatment\"}:::decision\nH -- \"high-grade dysplasia or very early\" --> I[\"Endoscopic resection or radiofrequency ablation\"]:::good\nH -- \"localised and fit\" --> J[\"Neoadjuvant chemo or chemoradiotherapy then oesophagectomy\"]:::good\nH -- \"advanced or unfit\" --> K[\"Palliative: stent for dysphagia, chemotherapy, palliative care\"]:::warn\nI --> L[\"Nutritional support and follow-up\"]:::good\nJ --> L\nK --> L", "tips": {"A": "Oesophageal cancer presents late, so the cardinal red flag is progressive dysphagia (initially for solids, later fluids) with unexplained weight loss. Treat new dysphagia at any age as a red flag.", "B": "NICE NG12 suspected-cancer criteria: refer urgently on the 2-week-wait pathway for upper gastrointestinal endoscopy if there is dysphagia at ANY age, or if aged 55 or over with weight loss plus upper abdominal pain, reflux or dyspepsia.", "C": "If the criteria are not met, manage as dyspepsia with lifestyle advice and a proton pump inhibitor, but review and re-refer promptly if symptoms persist or red flags appear.", "D": "Urgent upper gastrointestinal endoscopy with biopsy is the diagnostic test and should happen within 2 weeks. Barium swallow is no longer the investigation of choice.", "E": "Histology distinguishes adenocarcinoma (usually distal third, arising in Barrett's oesophagus) from squamous cell carcinoma (usually the upper two thirds), which differ in both risk factors and treatment.", "F": "Stage with CT of the chest, abdomen and pelvis, then PET-CT to exclude distant metastases, and endoscopic ultrasound to define T and N stage. Add staging laparoscopy for junctional tumours and bronchoscopy if airway invasion is suspected.", "G": "All patients should be discussed by a specialist oesophago-gastric multidisciplinary team, which decides between curative and palliative intent and coordinates nutritional support.", "H": "The decision turns on tumour stage and the patient's fitness for major surgery. Because the oesophagus has no serosa and a rich lymphatic network, spread is early and most patients are already incurable at diagnosis.", "I": "High-grade dysplasia and very early (T1a) disease can be cured endoscopically with endoscopic mucosal resection, often followed by radiofrequency ablation of the residual Barrett's segment.", "J": "For localised disease in a fit patient, neoadjuvant chemotherapy or chemoradiotherapy is given before oesophagectomy. Definitive chemoradiotherapy is an alternative to surgery for squamous cell carcinoma, particularly proximal tumours.", "K": "For advanced or metastatic disease, relieve dysphagia with a self-expanding metal stent (or laser therapy or brachytherapy), give palliative chemotherapy with trastuzumab added if the tumour is HER2 positive, and involve specialist palliative care early.", "L": "Nutrition is central throughout: dietitian input, and consider a feeding jejunostomy. Overall prognosis remains poor, with 5-year survival around 15 to 20%."}, "source": "NICE"}, cluster: "Oesophagus & upper GI", name: "Oesophageal cancer", keyFacts: "Malignancy of the oesophagus, either adenocarcinoma of the distal third arising from Barrett's oesophagus or squamous cell carcinoma of the upper two thirds. It presents late with progressive dysphagia and carries a poor prognosis, with 5-year survival around 15 to 20%.", epidemiology: "The UK has one of the highest incidences of oesophageal adenocarcinoma in the world, and adenocarcinoma has overtaken squamous cell carcinoma as the commoner type in Western countries. It usually presents over the age of 60 and is around 2 to 3 times commoner in men. Most patients have advanced disease at diagnosis.", aetiology: "Adenocarcinoma: gastro-oesophageal reflux disease, Barrett's oesophagus (the key premalignant lesion), obesity, smoking and male sex. Squamous cell carcinoma: smoking and alcohol, which act synergistically, plus achalasia, Plummer-Vinson syndrome, caustic strictures, nutritional deficiency, nitrosamines, very hot beverages, and human papillomavirus in high-incidence regions.", pathophysiology: "Adenocarcinoma follows the metaplasia to dysplasia to carcinoma sequence: chronic acid reflux drives intestinal metaplasia (Barrett's oesophagus), then dysplasia, then invasive carcinoma, usually in the distal third. Squamous cell carcinoma arises from the squamous epithelium of the upper two thirds after chronic irritant exposure. The oesophagus has no serosa and a rich submucosal lymphatic network, so tumours invade adjacent structures and spread to nodes early.", presentation: "Progressive dysphagia, initially for solids and later for fluids, with odynophagia, anorexia and marked weight loss. Later features reflect local spread: hoarseness from recurrent laryngeal nerve involvement, cough or recurrent aspiration from a tracheo-oesophageal fistula, regurgitation of undigested food, and a palpable supraclavicular node. Iron-deficiency anaemia from occult bleeding, retrosternal or epigastric pain and vomiting are also common.", investigations: "Urgent upper gastrointestinal endoscopy with biopsy within 2 weeks is diagnostic (NICE NG12: dysphagia at any age, or age 55 and over with weight loss plus upper abdominal pain, reflux or dyspepsia). Stage with CT of chest, abdomen and pelvis, PET-CT to exclude distant metastases and endoscopic ultrasound for T and N staging; add staging laparoscopy for junctional tumours and bronchoscopy if airway involvement is suspected. Also FBC, LFTs and formal nutritional assessment.", treatment: "Managed by a specialist oesophago-gastric multidisciplinary team. Curative intent for localised disease: neoadjuvant chemotherapy or chemoradiotherapy followed by oesophagectomy, or definitive chemoradiotherapy for squamous cell carcinoma (especially proximal tumours); endoscopic mucosal resection with radiofrequency ablation for high-grade dysplasia and T1a disease. Palliation for advanced disease: self-expanding metal stent, laser therapy or brachytherapy for dysphagia, palliative chemotherapy with trastuzumab if HER2 positive, dietitian-led nutritional support including a feeding jejunostomy, and early specialist palliative care." },
      { id: "gi_achalasia", management: { def: "A[\"Progressive dysphagia to solids AND liquids\"]:::start --> B[\"Upper GI endoscopy FIRST to exclude malignancy\"]:::process\nB --> C{\"Tumour at the gastro-oesophageal junction\"}:::decision\nC -- \"yes\" --> D[\"Pseudoachalasia - treat the underlying cancer\"]:::danger\nC -- \"no\" --> E[\"High-resolution manometry, the diagnostic gold standard\"]:::process\nE --> F[\"Absent peristalsis with a raised integrated relaxation pressure\"]:::process\nF --> G{\"Chicago classification subtype\"}:::decision\nG -- \"type III spastic\" --> H[\"POEM preferred - myotomy length tailored to the spasm\"]:::good\nG -- \"type I or II\" --> I{\"Fit for definitive intervention\"}:::decision\nI -- \"yes\" --> J[\"Pneumatic dilatation, laparoscopic Heller myotomy with fundoplication, or POEM\"]:::good\nI -- \"no\" --> K[\"Botulinum toxin into the lower oesophageal sphincter\"]:::warn\nK --> L[\"Nitrates or calcium channel blockers if injection unsuitable\"]:::warn\nH --> M[\"Long-term PPI - POEM has no antireflux wrap\"]:::good\nJ --> N[\"Review with the Eckardt score, success is 3 or less\"]:::good\nM --> N\nN --> O[\"Manage reflux and counsel on the small squamous carcinoma risk\"]:::good", tips: { A: "The hallmark is dysphagia to BOTH solids and liquids from the outset - mechanical obstruction such as a stricture or tumour causes dysphagia to solids first. Onset is insidious over years, with regurgitation of undigested food, chest pain, nocturnal cough and weight loss.", B: "Endoscopy comes first in every case, not to diagnose achalasia but to exclude the thing that mimics it. It is typically normal or shows a dilated oesophagus with retained food and a lower sphincter that still admits the scope with gentle pressure.", C: "Pseudoachalasia is malignancy at the gastro-oesophageal junction producing an identical picture. Suspect it with age over 55, symptoms for under 6 months, marked weight loss, or a sphincter that resists the endoscope - these patients need cross-sectional imaging and biopsy.", D: "Treat the cancer, not the sphincter. Dilating or myotomising a malignant stricture is both futile and hazardous - see the Oesophageal cancer entry.", E: "High-resolution manometry is the diagnostic gold standard and is required before any definitive treatment, because the subtype determines which treatment works best.", F: "The two diagnostic criteria are absent oesophageal peristalsis and failure of the lower oesophageal sphincter to relax, measured as a raised median integrated relaxation pressure. Barium swallow adds the classic dilated oesophagus tapering to a smooth bird's beak.", G: "Chicago classification: type I has no oesophageal pressurisation, type II has panoesophageal pressurisation and responds best to any treatment, type III is the spastic variant with premature contractions and responds worst to dilatation.", H: "Peroral endoscopic myotomy is preferred in type III because the myotomy can be extended proximally along the spastic segment - something pneumatic dilatation and a standard Heller myotomy cannot achieve.", I: "All definitive options work by disrupting the lower oesophageal sphincter. The choice rests on subtype, local expertise and fitness for anaesthesia - there is no UK national guideline, so practice follows the ASGE and SAGES recommendations.", J: "Pneumatic balloon dilatation is effective but often needs repeating and carries a perforation risk of roughly 2%. Laparoscopic Heller myotomy is usually combined with a partial (Dor or Toupet) fundoplication to limit reflux. POEM is increasingly offered first-line for all subtypes.", K: "Botulinum toxin blocks acetylcholine release at the sphincter. It is reserved for patients unfit for dilatation or surgery because the effect wears off within 6 to 12 months and repeated injections cause fibrosis that makes later myotomy harder.", L: "Nitrates and calcium channel blockers relax the sphincter but are poorly tolerated because of headache and hypotension, and give only modest, short-lived relief. They are a holding measure, not a definitive treatment.", M: "POEM creates no antireflux wrap, so postoperative reflux is common and many patients need long-term proton pump inhibitor therapy with endoscopic surveillance.", N: "The Eckardt score grades dysphagia, regurgitation, chest pain and weight loss out of 12. Treatment success is defined as a score of 3 or less without severe complications or the need for retreatment.", O: "Achalasia is never cured - treatment relieves outflow obstruction but peristalsis does not return. There is a small long-term increase in oesophageal squamous cell carcinoma risk from chronic food stasis, and reflux must be managed after any sphincter-disrupting procedure." }, source: "ASGE / SAGES" }, complications: "Aspiration pneumonia and nocturnal cough\nMalnutrition and weight loss\nProgressive megaoesophagus (sigmoid oesophagus) needing oesophagectomy\nOesophageal squamous cell carcinoma - a small long-term risk from chronic food stasis\nReflux oesophagitis after any sphincter-disrupting treatment, especially POEM", cluster: "Oesophagus & upper GI", name: "Achalasia", keyFacts: "Failure of the lower oesophageal sphincter to relax with loss of oesophageal peristalsis, causing progressive dysphagia to BOTH solids and liquids.", epidemiology: "Uncommon, around 1 per 100,000 per year; peaks between 30 and 60 years; affects men and women equally.", aetiology: "Usually idiopathic, from degeneration of inhibitory ganglion cells in the myenteric (Auerbach's) plexus, possibly autoimmune or post-viral; Chagas disease is the classic secondary cause; malignancy at the gastro-oesophageal junction causes pseudoachalasia.", pathophysiology: "Loss of the inhibitory neurones that release nitric oxide and vasoactive intestinal peptide leaves the lower oesophageal sphincter hypertonic and non-relaxing, and abolishes peristalsis, so the oesophagus dilates and food stagnates.", presentation: "Insidious dysphagia to solids AND liquids from the outset, regurgitation of undigested food, retrosternal chest pain, nocturnal cough and aspiration, weight loss.", investigations: "Upper GI endoscopy first to exclude malignancy; barium swallow shows a dilated oesophagus tapering to a smooth bird's beak; high-resolution manometry is the gold standard (absent peristalsis with raised integrated relaxation pressure) and gives the Chicago subtype.", treatment: "Definitive treatment disrupts the lower oesophageal sphincter: pneumatic dilatation, laparoscopic Heller myotomy with partial fundoplication, or peroral endoscopic myotomy (POEM, preferred in type III); botulinum toxin or nitrates/calcium channel blockers if unfit; lifelong reflux control after treatment." },
      { id: "gi_pharyngeal_pouch", cluster: "Oesophagus & upper GI", name: "Pharyngeal pouch", keyFacts: "A posterior pharyngeal (Zenker's) diverticulum through Killian's dehiscence causing dysphagia and regurgitation.", epidemiology: "Mainly affects older men.", aetiology: "Incoordinated swallowing with raised pressure herniating mucosa through a weak point above the cricopharyngeus.", pathophysiology: "A pulsion diverticulum forms between the thyropharyngeus and cricopharyngeus muscles and traps food.", presentation: "Dysphagia, regurgitation of undigested food, halitosis, aspiration, a gurgling neck lump.", investigations: "Barium swallow is diagnostic; avoid blind endoscopy due to perforation risk.", treatment: "Surgical or endoscopic stapling (diverticulotomy) with cricopharyngeal myotomy." },
      { id: "gi_mallory_weiss", cluster: "Oesophagus & upper GI", name: "Mallory-Weiss tear", keyFacts: "A mucosal tear at the gastro-oesophageal junction from forceful vomiting, causing usually self-limiting haematemesis.", epidemiology: "A common cause of upper GI bleeding, often in younger patients and with alcohol.", aetiology: "Repeated or forceful vomiting and retching (alcohol, bulimia, hyperemesis).", pathophysiology: "A sudden rise in intra-oesophageal pressure tears the mucosa (not full thickness) at the gastro-oesophageal junction.", presentation: "Haematemesis following a bout of vomiting or retching, usually small-volume and self-limiting.", investigations: "Upper GI endoscopy is diagnostic; FBC, group and save; Glasgow-Blatchford and Rockall scoring.", treatment: "Usually self-limiting with supportive care; endoscopic therapy if active bleeding; treat the precipitant." },
      { id: "gi_variceal_haemorrhage", management: {"def": "A[\"Known or suspected varices with haematemesis or melaena\"]:::start --> B[\"Resuscitate as for any major upper GI bleed: see Upper GI bleeding\"]:::danger\nB --> C[\"Terlipressin AND prophylactic antibiotics immediately\"]:::good\nC --> D[\"Urgent endoscopy within 24 h, sooner if unstable\"]:::good\nD --> E{\"Site of varices\"}:::decision\nE -- \"oesophageal\" --> F[\"Endoscopic band ligation\"]:::good\nE -- \"gastric\" --> G[\"Endoscopic injection of cyanoacrylate glue\"]:::good\nF --> H{\"Bleeding controlled?\"}:::decision\nG --> H\nH -- \"no\" --> I[\"Balloon tamponade as a BRIDGE, then urgent TIPSS\"]:::danger\nH -- \"yes\" --> J[\"Secondary prophylaxis: repeat banding to eradication + beta-blocker\"]:::good\nI --> J\nJ --> K[\"Treat the liver disease, alcohol support, surveillance endoscopy\"]:::good\nA --> L[\"PRIMARY prophylaxis in cirrhosis: screening endoscopy, then beta-blocker or banding\"]:::process", "tips": {"A": "Variceal haemorrhage is bleeding from porto-systemic collaterals that open when portal pressure rises in cirrhosis. It is the most lethal cause of upper gastrointestinal bleeding, with mortality of the order of 15 to 20% per episode, and should be assumed in any patient with known liver disease or stigmata of chronic liver disease who bleeds.", "B": "Resuscitation is the same as for any major upper gastrointestinal bleed and is covered under the Upper gastrointestinal bleeding entry: ABCDE, two large-bore cannulae, crossmatch, and a restrictive transfusion threshold of about 70 g/L, which is associated with better outcomes than liberal transfusion because over-transfusion raises portal pressure and can worsen bleeding. Correct clotting and platelets as indicated, and use the Glasgow-Blatchford score for risk stratification.", "C": "Two drugs are given BEFORE endoscopy and both improve survival. Terlipressin is a splanchnic vasoconstrictor that lowers portal pressure (use with care in ischaemic heart disease, and watch for hyponatraemia). Prophylactic broad-spectrum antibiotics are given to ALL patients with cirrhosis who bleed, because bacterial infection is common, precipitates rebleeding and independently increases mortality.", "D": "Offer endoscopy within 24 hours of admission, and immediately after resuscitation if the patient is unstable. Endoscopy both confirms the varices as the bleeding source and treats them.", "E": "Treatment depends on where the varices are, because band ligation is not effective for gastric varices.", "F": "Oesophageal varices are treated with endoscopic band ligation, which is superior to sclerotherapy for both haemostasis and complications.", "G": "Gastric varices are treated with endoscopic injection of N-butyl-2-cyanoacrylate glue. Consider TIPSS if bleeding from gastric varices is not controlled by glue.", "H": "Reassess for continued or early rebleeding, which occurs in a substantial minority and carries a high mortality.", "I": "If endoscopic therapy fails, balloon tamponade with a Sengstaken-Blakemore tube is a temporary BRIDGE only, for a maximum of about 24 hours, because of the risk of pressure necrosis, aspiration and oesophageal rupture. The definitive rescue is a transjugular intrahepatic portosystemic shunt (TIPSS), which decompresses the portal system. Its main complication is precipitating or worsening hepatic encephalopathy.", "J": "Secondary prophylaxis is essential, because rebleeding risk without it is very high. Combine a non-selective beta-blocker (propranolol or carvedilol) with a programme of repeat band ligation every few weeks until the varices are eradicated, then surveillance endoscopy.", "K": "Treat the underlying liver disease and address the cause, with alcohol cessation support where relevant. Consider TIPSS or transplant assessment in refractory or recurrent bleeding, and continue to screen for the other complications of cirrhosis.", "L": "Do not overlook primary prophylaxis: everyone diagnosed with cirrhosis should have a screening endoscopy for varices. If medium or large varices are found, offer a non-selective beta-blocker (propranolol or carvedilol), or endoscopic band ligation if a beta-blocker is contraindicated or not tolerated. Beta-blockers work by lowering cardiac output and causing splanchnic vasoconstriction, reducing portal pressure."}, "source": "NICE CG141"}, cluster: "Oesophagus & upper GI", name: "Variceal haemorrhage", keyFacts: "Bleeding from porto-systemic collateral veins that dilate when portal hypertension develops in cirrhosis. It is the most lethal cause of upper gastrointestinal bleeding, with a mortality of around 15 to 20% per episode, and needs terlipressin plus prophylactic antibiotics before endoscopy.", epidemiology: "Varices are present in around half of people with cirrhosis and develop at roughly 7% per year; about a third of those with varices will bleed. Risk rises with the size of the varices, red wale marks at endoscopy, and the severity of liver disease by Child-Pugh class.", aetiology: "Any cause of portal hypertension, overwhelmingly cirrhosis (alcohol-related liver disease, viral hepatitis, non-alcoholic fatty liver disease). Non-cirrhotic causes include portal or splenic vein thrombosis, Budd-Chiari syndrome and schistosomiasis. Isolated gastric varices should prompt a search for splenic vein thrombosis. Bleeding is often precipitated by infection, alcohol excess or a rise in portal pressure.", pathophysiology: "Distortion of hepatic architecture raises resistance to portal flow, so pressure rises in the portal system and blood is diverted through porto-systemic anastomoses. At the gastro-oesophageal junction these thin-walled submucosal veins dilate; once the hepatic venous pressure gradient exceeds about 12 mmHg they may rupture, and because the vessels are under high pressure and the patient is often coagulopathic and thrombocytopenic, blood loss is rapid and severe.", presentation: "Large-volume haematemesis, often of fresh red blood, with melaena and haemodynamic compromise. Look for stigmata of chronic liver disease: jaundice, spider naevi, palmar erythema, ascites, splenomegaly and caput medusae. Bleeding frequently precipitates hepatic encephalopathy, since blood in the gut is a large protein load.", investigations: "Urgent full blood count, clotting screen and fibrinogen, U and Es, LFTs and a crossmatch; venous blood gas with lactate. Calculate the Glasgow-Blatchford score at presentation and the Rockall score after endoscopy, and assess liver reserve with the Child-Pugh score. Upper GI endoscopy is both diagnostic and therapeutic. Take cultures and an ascitic tap if ascites is present, to look for spontaneous bacterial peritonitis.", treatment: "Resuscitate as for any major upper GI bleed, transfusing to a restrictive target of about 70 g/L since over-transfusion raises portal pressure. Give terlipressin AND prophylactic broad-spectrum antibiotics immediately, both of which improve survival. Endoscopy within 24 hours: band ligation for oesophageal varices, cyanoacrylate glue injection for gastric varices. If bleeding continues, use balloon tamponade (Sengstaken-Blakemore) as a bridge for up to 24 hours and proceed to TIPSS. Secondary prophylaxis is a non-selective beta-blocker plus repeat banding until eradication." },
      { id: "gi_boerhaave", cluster: "Oesophagus & upper GI", name: "Boerhaave syndrome", keyFacts: "Full-thickness spontaneous oesophageal rupture from forceful vomiting; a life-threatening surgical emergency.", epidemiology: "Rare; classically a middle-aged man after an alcohol binge.", aetiology: "A sudden rise in intra-oesophageal pressure against a closed glottis, usually from violent vomiting.", pathophysiology: "Transmural rupture (usually the left posterolateral distal oesophagus) leaks gastric contents into the mediastinum, causing mediastinitis and sepsis.", presentation: "Mackler's triad of vomiting, severe chest pain and subcutaneous emphysema; shock, surgical emphysema in the neck.", investigations: "CT chest with contrast (or contrast swallow), CXR (pneumomediastinum, effusion); contrast with Mallory-Weiss which is mucosal only.", treatment: "Resuscitation, nil by mouth, IV antibiotics and PPI; urgent surgical repair or stenting; high mortality if delayed." },
      { id: "gi_h_pylori", cluster: "Stomach & peptic disease", name: "H. pylori infection", keyFacts: "A Gram-negative bacterium colonising gastric mucosa; the leading cause of peptic ulcers and a gastric cancer risk.", epidemiology: "Infects around half the world's population, usually acquired in childhood.", aetiology: "Faecal-oral or oral-oral transmission of Helicobacter pylori.", pathophysiology: "Urease-producing bacteria neutralise acid and incite chronic gastritis, raising the risk of ulcers and, long-term, gastric adenocarcinoma and MALT lymphoma.", presentation: "Often asymptomatic; dyspepsia, epigastric pain, or complications of peptic ulcer disease.", investigations: "Urea breath test or stool antigen (stop PPI first); CLO test/biopsy at endoscopy.", treatment: "Triple therapy: PPI plus two antibiotics (amoxicillin with clarithromycin or metronidazole) for 7 days; confirm eradication." },
      { id: "gi_pud", management: {"def": "A[\"Peptic ulcer disease\"]:::start --> B[\"Stop NSAIDs, test for H. pylori\"]:::good\nB --> C{\"H. pylori positive?\"}:::decision\nC -- \"yes\" --> D[\"Eradication: PPI + 2 antibiotics (7 days)\"]:::good\nC -- \"no\" --> E[\"Full-dose PPI for 4-8 weeks\"]:::good\nD --> F[\"Confirm eradication (urea breath test)\"]:::process\nA --> G[\"Endoscopy if red flags or new dyspepsia over 55\"]:::warn\nE --> H[\"Gastric ulcer: rescope to confirm healing\"]:::process", "tips": {"A": "A break in the gastric or duodenal mucosa causing epigastric pain; the two main causes are H. pylori and NSAIDs.", "B": "Stop NSAIDs where possible and test for Helicobacter pylori (stool antigen or urea breath test - stop PPI 2 weeks beforehand).", "C": "Treatment depends on H. pylori status.", "D": "H. pylori positive: 7-day triple therapy - a PPI plus amoxicillin and either clarithromycin or metronidazole (non-penicillin regimen if allergic).", "E": "H. pylori negative (e.g. NSAID-related): a full-dose PPI for 4-8 weeks.", "F": "Confirm eradication with a urea breath test, especially with ongoing symptoms or a complicated ulcer.", "G": "Refer for urgent endoscopy with alarm features (bleeding, anaemia, weight loss, dysphagia, persistent vomiting) or new dyspepsia over 55.", "H": "Re-scope gastric ulcers after treatment to confirm healing and exclude malignancy; duodenal ulcers usually do not need re-scoping."}}, cluster: "Stomach & peptic disease", name: "Peptic ulcer disease", keyFacts: "Mucosal ulceration of the stomach or duodenum; the main causes are H. pylori and NSAIDs.", epidemiology: "Common, with duodenal ulcers outnumbering gastric ulcers.", aetiology: "Helicobacter pylori, NSAIDs and aspirin, smoking, and rarely Zollinger-Ellison syndrome.", pathophysiology: "An imbalance between mucosal protection and acid, driven by H. pylori inflammation or NSAID-induced prostaglandin loss, erodes the mucosa.", presentation: "Epigastric pain (duodenal eased by food, gastric worse with food), may bleed.", investigations: "H. pylori testing, endoscopy, FBC.", treatment: "PPI; eradicate H. pylori; stop NSAIDs; endoscopic therapy for bleeding." },
      { id: "gi_ugib", cluster: "Stomach & peptic disease", name: "Upper gastrointestinal bleeding", keyFacts: "Bleeding proximal to the duodenojejunal flexure, presenting with haematemesis (or coffee-ground vomit) and/or melaena; the commonest causes are peptic ulcers and oesophageal varices.", epidemiology: "A common medical emergency; mortality rises with age, comorbidity and variceal bleeding.", aetiology: "Peptic ulcer disease (commonest), oesophagogastric varices, Mallory-Weiss tear, oesophagitis or gastritis, malignancy and vascular lesions; NSAIDs, anticoagulants and alcohol are key contributors.", pathophysiology: "Mucosal or vascular disruption causes luminal blood loss; brisk bleeding leads to hypovolaemic shock, and variceal bleeding from portal hypertension can be torrential.", presentation: "Haematemesis or coffee-ground vomiting and melaena; may present with collapse, tachycardia and hypotension; stigmata of chronic liver disease suggest variceal bleeding.", investigations: "Glasgow-Blatchford score at presentation (predicts need for intervention), FBC, U and Es (raised urea), LFTs, clotting and crossmatch; upper GI endoscopy for diagnosis and treatment; Rockall score after endoscopy for rebleeding and mortality risk.", treatment: "ABCDE resuscitation with two large-bore cannulae and fluid/blood; restrictive transfusion (aim haemoglobin around 70 g/L); correct coagulopathy and reverse anticoagulation; upper GI endoscopy within 24 hours. For suspected varices give terlipressin and prophylactic antibiotics first, then band ligation; for non-variceal bleeds use endoscopic haemostasis then high-dose PPI, escalating to interventional radiology or surgery if it fails.", management: {"def": "A[\"Upper GI bleed (haematemesis/melaena)\"]:::start --> B[\"ABCDE, two large-bore cannulae, crossmatch\"]:::danger\nB --> C[\"Transfuse to Hb ~70, correct clotting\"]:::good\nC --> D[\"Glasgow-Blatchford score, risk-stratify\"]:::process\nD --> E{\"Suspected varices?\"}:::decision\nE -- \"yes\" --> F[\"Terlipressin + prophylactic antibiotics\"]:::good\nE -- \"no\" --> G[\"Withhold PPI until endoscopy\"]:::process\nF --> H[\"Endoscopy within 24 h (band ligation)\"]:::good\nG --> I[\"Endoscopy within 24 h (clip/adrenaline, then PPI)\"]:::good\nH --> J[\"Rebleeding: repeat endoscopy, then IR or surgery\"]:::warn\nI --> J", "tips": {"A": "Bleeding from the oesophagus, stomach or duodenum - haematemesis, coffee-ground vomit and/or melaena; the leading causes are peptic ulcers and oesophageal varices.", "B": "Resuscitate first: ABCDE, two large-bore cannulae, bloods including crossmatch, and fluids or blood for shock.", "C": "Use a restrictive transfusion strategy (aim haemoglobin around 70 g/L, or 80 with cardiovascular disease); correct clotting and reverse anticoagulation (platelets, prothrombin complex concentrate as indicated).", "D": "Calculate the Glasgow-Blatchford score at presentation to decide admission and urgency (a score of 0 may allow outpatient management).", "E": "Look for clues of variceal bleeding (known liver disease, stigmata of chronic liver disease) - it changes the pre-endoscopy treatment.", "F": "Suspected variceal bleed: give terlipressin and prophylactic antibiotics BEFORE endoscopy.", "G": "Do NOT give a PPI before endoscopy in non-variceal bleeding (NICE) - give it after endoscopic treatment.", "H": "Endoscopy within 24 hours (immediately after resuscitation if unstable); varices are treated with band ligation, or a Sengstaken-Blakemore tube if uncontrolled.", "I": "Non-variceal (e.g. ulcer): endoscopic haemostasis (clips, thermal coagulation, adrenaline injection) then high-dose IV PPI; test and treat H. pylori.", "J": "If bleeding continues or rebleeds: repeat endoscopy, then interventional radiology (embolisation) or surgery. Use the Rockall score after endoscopy to gauge rebleeding and mortality risk."}} },
      { id: "gi_gastric_ca", cluster: "Stomach & peptic disease", name: "Gastric cancer", keyFacts: "Usually adenocarcinoma; presents late with vague dyspepsia, so alarm features warrant urgent endoscopy.", epidemiology: "Commoner in older men and in East Asia; UK incidence is falling.", aetiology: "H. pylori (key), pernicious anaemia, smoking, salted/smoked diet, atrophic gastritis, family history (CDH1/E-cadherin).", pathophysiology: "Chronic inflammation drives the intestinal-type sequence (gastritis to atrophy to metaplasia to dysplasia to carcinoma); the diffuse type gives linitis plastica with signet-ring cells.", presentation: "Dyspepsia, weight loss, early satiety, dysphagia, vomiting, anaemia; Virchow's node, epigastric mass.", investigations: "Upper GI endoscopy with biopsy, CT staging, endoscopic ultrasound, staging laparoscopy.", treatment: "Gastrectomy with perioperative chemotherapy; palliative chemotherapy for advanced disease; eradicate H. pylori." },
      { id: "gi_dumping_syndrome", cluster: "Stomach & peptic disease", name: "Dumping syndrome", keyFacts: "Rapid gastric emptying after gastric surgery causing early vasomotor and late hypoglycaemic symptoms.", epidemiology: "A recognised complication after gastrectomy or bariatric and upper-GI surgery.", aetiology: "Loss of normal gastric reservoir and pyloric function following gastric or oesophageal surgery.", pathophysiology: "Early dumping: hyperosmolar food rushes into the small bowel drawing in fluid; late dumping: a rapid glucose load triggers excess insulin and reactive hypoglycaemia.", presentation: "Early (15-30 min): bloating, cramps, diarrhoea, flushing, palpitations; late (1-3 h): sweating, tremor, hypoglycaemia.", investigations: "Clinical diagnosis; oral glucose challenge; gastric emptying study if needed.", treatment: "Small frequent low-carbohydrate meals, separate fluids from solids, lie down after eating; octreotide or surgery if refractory." },
      { id: "gi_coeliac", cluster: "Small bowel & malabsorption", name: "Coeliac disease", keyFacts: "An autoimmune reaction to dietary gluten causing malabsorption; treated by lifelong gluten avoidance.", epidemiology: "Affects around 1% of the population and is often underdiagnosed.", aetiology: "Gluten (wheat, barley, rye) in genetically susceptible people (HLA-DQ2/DQ8); linked to type 1 diabetes and thyroid disease.", pathophysiology: "Gluten triggers a T-cell-mediated immune response causing villous atrophy of the small bowel, impairing nutrient absorption.", presentation: "Diarrhoea, bloating, weight loss, fatigue, iron/folate deficiency, dermatitis herpetiformis.", investigations: "Anti-tTG IgG with total IgA while on gluten; duodenal biopsy confirms.", treatment: "Lifelong gluten-free diet; replace deficiencies; pneumococcal vaccination." },
      { id: "gi_b12_folate", cluster: "Small bowel & malabsorption", name: "B12 & folate deficiency", keyFacts: "Deficiency of vitamin B12 or folate causing a macrocytic anaemia; B12 deficiency also damages nerves.", epidemiology: "Common, particularly in the elderly, vegans and those with malabsorption.", aetiology: "B12 from pernicious anaemia, gastrectomy or ileal disease; folate from poor diet, pregnancy, alcohol and certain drugs.", pathophysiology: "Both vitamins are needed for DNA synthesis, so deficiency impairs red-cell maturation; B12 also maintains myelin, hence the neuropathy.", presentation: "Fatigue, glossitis, macrocytic anaemia; B12 deficiency adds neurological signs.", investigations: "FBC and blood film, B12, folate, intrinsic factor antibodies.", treatment: "Replace B12 (IM hydroxocobalamin) before folate to avoid cord degeneration; treat cause." },
      { id: "gi_crohns", management: {"def": "A[\"Crohn disease flare\"]:::start --> B[\"Induce remission: corticosteroid\"]:::good\nB -- \"steroid-sparing / relapsing\" --> C[\"Add azathioprine or methotrexate\"]:::good\nC -- \"refractory\" --> D[\"Biologic (infliximab/adalimumab)\"]:::good\nA --> E[\"Stop smoking (essential)\"]:::warn\nA --> F[\"Maintenance: azathioprine, methotrexate or biologic\"]:::good\nD --> G[\"Surgery for strictures, fistulae or localised disease\"]:::process", "tips": {"A": "Transmural inflammation anywhere in the gut (often terminal ileum) with pain, diarrhoea and weight loss; induce then maintain remission.", "B": "Induce remission with a corticosteroid (prednisolone, or budesonide for ileocaecal disease); exclusive enteral nutrition is an option in children.", "C": "Add azathioprine/mercaptopurine (check TPMT first) or methotrexate as steroid-sparing agents, especially with frequent relapses.", "D": "Anti-TNF biologics (infliximab, adalimumab) for severe or refractory and fistulising Crohn disease.", "E": "Smoking cessation is one of the most important interventions - smoking worsens Crohn disease and relapse.", "F": "Maintain remission with azathioprine/mercaptopurine or methotrexate, or a biologic; aminosalicylates have limited benefit.", "G": "Surgery for complications (strictures, fistulae, abscess) or limited ileocaecal disease - it is not curative."}}, cluster: "Inflammatory bowel disease & functional", name: "Crohn's disease", keyFacts: "A transmural inflammatory bowel disease that can affect any part of the gut from mouth to anus.", epidemiology: "Typically presents in young adults; commoner in smokers and in Western populations.", aetiology: "Genetic susceptibility plus environmental triggers; smoking worsens it, unlike ulcerative colitis.", pathophysiology: "A dysregulated immune response to gut flora causes patchy, full-thickness inflammation with skip lesions, strictures and fistulae.", presentation: "Crampy pain, non-bloody diarrhoea, weight loss, mouth ulcers, perianal disease; any part of gut.", investigations: "Faecal calprotectin, colonoscopy with biopsy, MRI for fistulae.", treatment: "Induce with steroids; maintain with azathioprine or biologics; stop smoking; surgery for complications." },
      { id: "gi_uc", management: {"def": "A[\"Ulcerative colitis flare\"]:::start --> B{\"Severity and extent\"}:::decision\nB -- \"mild-moderate\" --> C[\"Topical +/- oral aminosalicylate\"]:::good\nC -- \"no remission in 4 weeks\" --> D[\"Add oral corticosteroid\"]:::good\nB -- \"acute severe\" --> E[\"Admit: IV hydrocortisone + VTE prophylaxis\"]:::danger\nE --> F{\"Response by day 3?\"}:::decision\nF -- \"no\" --> G[\"Rescue: ciclosporin or infliximab, or surgery\"]:::warn\nA --> H[\"Maintenance: aminosalicylate, azathioprine or biologic\"]:::good", "tips": {"A": "Relapsing-remitting colonic inflammation (bloody diarrhoea, urgency); manage by severity and extent.", "B": "Assess extent (proctitis, left-sided, extensive) and severity (Truelove and Witts criteria for acute severe).", "C": "Mild-moderate: an aminosalicylate - topical (suppository/enema) for proctitis, adding oral mesalazine for more extensive disease.", "D": "If no remission in about 4 weeks, add an oral corticosteroid (prednisolone) to induce; steroids are not for maintenance.", "E": "Acute severe UC is an emergency: admit for IV corticosteroids, fluids, VTE prophylaxis and monitoring; exclude infection including C. difficile.", "F": "Assess response around day 3 (stool frequency and CRP - the Travis criteria).", "G": "If not responding, give rescue therapy with IV ciclosporin or infliximab and involve surgeons; colectomy if medical rescue fails.", "H": "Maintain remission with an aminosalicylate; azathioprine/mercaptopurine or a biologic for frequent relapses or steroid dependence."}}, cluster: "Inflammatory bowel disease & functional", name: "Ulcerative colitis", keyFacts: "An inflammatory bowel disease of continuous mucosal inflammation from the rectum upwards; colectomy is curative.", epidemiology: "Presents in young adults; smoking is paradoxically protective.", aetiology: "Genetic and environmental factors driving a dysregulated mucosal immune response.", pathophysiology: "Continuous superficial inflammation limited to the colonic mucosa causes ulceration, bloody diarrhoea and a long-term cancer risk.", presentation: "Bloody diarrhoea, urgency, tenesmus, lower abdominal pain; continuous from rectum.", investigations: "Faecal calprotectin, colonoscopy, stool culture to exclude infection.", treatment: "Aminosalicylates for mild; steroids for flares; biologics; colectomy is curative." },
      { id: "gi_ibs", management: {"def": "A[\"Irritable bowel syndrome\"]:::start --> B[\"Positive diagnosis, exclude red flags and coeliac\"]:::process\nB --> C[\"Diet and lifestyle: regular meals, adjust fibre\"]:::good\nC --> D{\"Predominant symptom\"}:::decision\nD -- \"pain / bloating\" --> E[\"Antispasmodic (e.g. mebeverine)\"]:::good\nD -- \"constipation\" --> F[\"Soluble fibre, laxative (not lactulose)\"]:::good\nD -- \"diarrhoea\" --> G[\"Loperamide\"]:::good\nE -- \"persistent\" --> H[\"Low-dose tricyclic, then SSRI, consider CBT\"]:::good", "tips": {"A": "A functional bowel disorder: abdominal pain related to defecation with altered bowel habit and bloating; a positive diagnosis after excluding sinister causes.", "B": "Check FBC, CRP/ESR, coeliac serology and faecal calprotectin (to exclude IBD); investigate red flags (weight loss, bleeding, anaemia, over 50, family history).", "C": "First-line is diet and lifestyle: regular meals, adjust fibre (reduce insoluble fibre), limit caffeine/alcohol/fizzy drinks; consider a dietitian-led low-FODMAP diet.", "D": "Target drugs at the predominant symptom.", "E": "Pain, spasm or bloating: an antispasmodic such as mebeverine or hyoscine; peppermint oil helps bloating.", "F": "Constipation-predominant: soluble fibre (ispaghula) and a laxative - avoid lactulose (bloating); linaclotide if refractory.", "G": "Diarrhoea-predominant: loperamide first-line as an antimotility agent.", "H": "If symptoms persist, a low-dose tricyclic (e.g. amitriptyline) as second-line, then an SSRI; consider CBT for refractory IBS."}}, cluster: "Inflammatory bowel disease & functional", name: "Irritable bowel syndrome", keyFacts: "A functional bowel disorder of abdominal pain with altered bowel habit and no structural cause.", epidemiology: "Very common, especially in young women.", aetiology: "Multifactorial: gut-brain axis dysfunction, altered motility, visceral hypersensitivity, stress and post-infective triggers.", pathophysiology: "Disordered gut-brain signalling and visceral hypersensitivity produce pain and altered motility without inflammation or damage.", presentation: "Abdominal pain relieved by defaecation, bloating, altered bowel habit without alarm features.", investigations: "Exclude organic disease: FBC, CRP, coeliac serology, faecal calprotectin.", treatment: "Diet (low FODMAP), antispasmodics, laxatives/loperamide, low-dose tricyclic, reassurance." },
      { id: "gi_appendicitis", cluster: "Lower GI & colorectal", name: "Appendicitis", keyFacts: "Acute inflammation of the appendix and the commonest surgical abdominal emergency; treated by appendicectomy.", epidemiology: "Peak incidence in children and young adults.", aetiology: "Luminal obstruction by a faecolith, lymphoid hyperplasia or, rarely, a tumour.", pathophysiology: "Obstruction raises intraluminal pressure causing distension, ischaemia and bacterial invasion, progressing to gangrene and perforation if untreated.", presentation: "Central pain migrating to the right iliac fossa, anorexia, nausea, low-grade fever; tenderness at McBurney's point, Rovsing's sign.", investigations: "Clinical; FBC/CRP, urine and pregnancy test; ultrasound or CT; Alvarado score.", treatment: "Appendicectomy (usually laparoscopic) with antibiotics; IV fluids and analgesia." },
      { id: "gi_diverticular", cluster: "Lower GI & colorectal", name: "Diverticular disease", keyFacts: "Outpouchings of colonic mucosa; symptomatic disease and inflammation (diverticulitis) can occur.", epidemiology: "Very common in older Western adults, linked to low-fibre diets.", aetiology: "Low dietary fibre and raised intraluminal pressure in an ageing colonic wall.", pathophysiology: "High intraluminal pressure herniates mucosa through weak points in the muscle wall; faecal obstruction of a diverticulum causes inflammation.", presentation: "Left lower quadrant pain, altered bowel habit; diverticulitis adds fever and tenderness.", investigations: "CT abdomen for acute episodes, colonoscopy when settled.", treatment: "High-fibre diet; antibiotics and analgesia for diverticulitis; surgery for complications." },
      { id: "gi_acute_mesenteric_ischaemia", management: { def: "A[\"Severe abdominal pain OUT OF PROPORTION to the examination\"]:::start --> B[\"Assume acute mesenteric ischaemia until proved otherwise\"]:::danger\nB --> C[\"CT ANGIOGRAPHY without delay - do not wait for the lactate\"]:::process\nC --> D[\"Resuscitate alongside imaging - IV fluids, correct electrolytes, nasogastric decompression, broad-spectrum antibiotics\"]:::process\nD --> E{\"Overt peritonitis\"}:::decision\nE -- \"yes\" --> F[\"Prompt laparotomy - resect necrotic bowel and revascularise\"]:::danger\nE -- \"no\" --> G{\"Mechanism on CT angiography\"}:::decision\nG -- \"arterial occlusion\" --> H[\"ENDOVASCULAR revascularisation first-line where expertise exists\"]:::good\nG -- \"venous thrombosis\" --> I[\"Systemic anticoagulation, usually without surgery\"]:::good\nG -- \"non-occlusive low flow\" --> J[\"Optimise cardiac output, stop vasoconstrictors, treat the cause\"]:::warn\nF --> K[\"Planned second-look laparotomy at 24 to 48 hours\"]:::warn\nH --> K\nK --> L[\"Secondary prevention - short-term dual antiplatelet after revascularisation\"]:::good\nI --> L\nJ --> L\nL --> M[\"Treat the source - atrial fibrillation, atherosclerosis, thrombophilia\"]:::good", tips: { A: "This is the single most useful clinical sign in surgery: agonising, constant, diffuse pain in a patient whose abdomen is soft and almost normal to palpate. The mismatch exists because the ischaemia is visceral and the peritoneum is not yet involved - by the time there is guarding, the bowel is already infarcting.", B: "WSES states it plainly - severe pain out of proportion to the examination should be ASSUMED to be acute mesenteric ischaemia until proved otherwise. Mortality is 50 to 80% and rises with every hour of delay, so this is a diagnosis made by suspicion, not by waiting for confirmation.", C: "CT angiography is the diagnostic test and should be performed without delay. A NORMAL LACTATE DOES NOT EXCLUDE IT - lactate rises only once the bowel is already infarcting, so using it as a screening test is how the diagnosis gets missed. Do not let a normal white cell count reassure you either.", D: "Resuscitation runs alongside imaging, not after it: intravenous fluids, correction of electrolytes, nasogastric decompression and immediate broad-spectrum antibiotics (the ischaemic mucosa translocates gut bacteria). Avoid vasopressors if at all possible, since they worsen splanchnic perfusion.", E: "Peritonitis means bowel is already dead, and no amount of imaging or endovascular planning changes what happens next.", F: "Laparotomy to resect frankly necrotic bowel and revascularise. Bowel of doubtful viability is best left rather than over-resected, and reassessed at a second look.", G: "The mechanism determines the treatment, which is why the CT angiogram matters so much. Superior mesenteric artery EMBOLISM causes about half (classically from atrial fibrillation or mural thrombus after myocardial infarction), THROMBOSIS on pre-existing atherosclerosis about a quarter, mesenteric VENOUS thrombosis about a tenth (thrombophilia, malignancy, portal hypertension), and non-occlusive disease the remainder.", H: "This is the modern shift: for arterial occlusion WITHOUT peritonitis, endovascular revascularisation (aspiration thrombectomy, thrombolysis, angioplasty and stenting) is now the primary option where the expertise exists, rather than open embolectomy.", I: "Mesenteric venous thrombosis behaves quite differently - it is more indolent, often presents subacutely, and is usually managed with systemic anticoagulation alone. Look for an underlying thrombophilia or malignancy.", J: "Non-occlusive mesenteric ischaemia is a low-flow state, typically in a shocked, vasopressor-dependent or dialysis patient. There is no clot to remove; the treatment is to fix the perfusion - optimise cardiac output and withdraw vasoconstrictors where possible.", K: "A planned second-look laparotomy at 24 to 48 hours lets you reassess bowel of borderline viability once perfusion has been restored, rather than committing to a massive resection at the first operation.", L: "The European Society for Vascular Surgery supports short-term (1 to 6 months) dual antiplatelet therapy after mesenteric revascularisation where the bleeding risk is acceptable, then lifelong single antiplatelet.", M: "Whatever the mechanism, treat the source or it will recur: anticoagulate atrial fibrillation, manage atherosclerotic risk factors, and investigate for thrombophilia or occult malignancy in venous cases. Extensive resection leaves short bowel syndrome and lifelong nutritional consequences." }, source: "WSES / ESVS" }, complications: "Bowel infarction, perforation and faecal peritonitis\nShort bowel syndrome after extensive resection, with lifelong parenteral nutrition\nSepsis, lactic acidosis and multi-organ failure\nReperfusion injury after revascularisation\nVery high mortality - 50 to 80%, rising with every hour of delay", cluster: "Lower GI & colorectal", name: "Acute mesenteric ischaemia", keyFacts: "Sudden interruption of small bowel blood supply, usually the superior mesenteric artery - a surgical emergency defined clinically by pain out of proportion to the examination.", epidemiology: "Uncommon but lethal, with mortality of 50-80% that rises with every hour of delay. Typically elderly patients with cardiovascular disease or atrial fibrillation.", aetiology: "Superior mesenteric artery embolism (about 50%, from atrial fibrillation or mural thrombus after myocardial infarction), thrombosis on pre-existing atherosclerosis (about 25%), non-occlusive ischaemia from a low-flow state (shock, vasopressors, dialysis), and mesenteric venous thrombosis (about 10%, from thrombophilia, malignancy or portal hypertension).", pathophysiology: "The mucosa is the most oxygen-sensitive layer, so injury starts at the villous tip and progresses transmurally over hours. Necrotic bowel translocates bacteria and toxins, producing lactic acidosis, sepsis and multi-organ failure; revascularisation adds a further reperfusion injury.", presentation: "Severe, constant, diffuse abdominal pain OUT OF PROPORTION to a soft, unremarkable abdomen, with nausea, vomiting and diarrhoea. Guarding, distension and shock are late and mean infarction. Often in atrial fibrillation.", investigations: "CT ANGIOGRAPHY is the diagnostic test and must not be delayed. Bloods show a raised white cell count, with lactate and metabolic acidosis rising only late - a NORMAL LACTATE DOES NOT EXCLUDE IT. ECG for atrial fibrillation.", treatment: "Resuscitate, correct electrolytes, nasogastric decompression and immediate broad-spectrum antibiotics. Overt peritonitis means prompt laparotomy to resect necrotic bowel and revascularise. Without peritonitis, endovascular revascularisation is first-line for arterial occlusion where expertise exists; anticoagulation alone for venous thrombosis; optimise cardiac output and stop vasoconstrictors for non-occlusive disease. Plan a second-look laparotomy at 24-48 hours, then secondary prevention and treatment of the source." },
      { id: "gi_ischaemic_colitis", management: { def: "A[\"Crampy left-sided abdominal pain then bloody diarrhoea, usually over 60\"]:::start --> B[\"Contrast CT - segmental thickening in a watershed distribution, excludes other causes\"]:::process\nB --> C{\"Pneumatosis or porto-mesenteric venous gas\"}:::decision\nC -- \"yes\" --> D[\"Predicts TRANSMURAL INFARCTION - urgent laparotomy and resection\"]:::danger\nC -- \"no\" --> E{\"Isolated RIGHT colon, or severe pain WITHOUT bleeding\"}:::decision\nE -- \"yes\" --> F[\"Treat as possible acute mesenteric ischaemia - consider angiography\"]:::warn\nE -- \"no\" --> G[\"Colonoscopy within 48 hours to confirm and biopsy\"]:::process\nG --> H[\"Conservative care - bowel rest, IV fluids, antibiotics\"]:::good\nH --> I[\"Stop vasoconstrictors and correct the precipitating low-flow state\"]:::warn\nI --> J{\"Improving within 48 to 72 hours\"}:::decision\nJ -- \"yes\" --> K[\"Most resolve within 1 to 2 weeks\"]:::good\nJ -- \"no\" --> L[\"Reassess for gangrene, perforation or fulminant colitis - surgery\"]:::danger\nK --> M[\"Follow up for late stricture or chronic segmental colitis\"]:::warn", tips: { A: "The typical patient is over 60 with cardiovascular disease. Sudden crampy pain, classically LEFT-sided, is followed within 24 hours by bloody diarrhoea or rectal bleeding, with only mild tenderness. Compared with acute mesenteric ischaemia the patient is far less unwell - that contrast is the point.", B: "CT excludes the mimics (diverticulitis, malignancy, inflammatory bowel disease) and shows the distribution. The vulnerable WATERSHED zones are the SPLENIC FLEXURE (Griffiths' point, between the superior and inferior mesenteric territories) and the RECTOSIGMOID JUNCTION (Sudeck's point). The RECTUM IS USUALLY SPARED because of its dual supply from the internal iliac - rectal involvement should make you doubt the diagnosis. A plain film may show thumbprinting from submucosal oedema.", C: "These two findings are the red flags that change everything - they predict full-thickness infarction rather than the usual reversible mucosal injury.", D: "Transmural infarction needs urgent resection. Other markers of severe disease are peritonitis, shock, a rising lactate, and gangrene seen at endoscopy.", E: "This is the crucial safety check. Isolated RIGHT-sided colonic ischaemia is supplied by the superior mesenteric artery and behaves like small bowel ischaemia - it carries a much worse prognosis and a higher need for surgery. Severe pain WITHOUT bleeding, or atrial fibrillation, should also push you towards the mesenteric pathway.", F: "Where the picture suggests mesenteric arterial disease and the CT is not conclusive, proceed to angiography - see the Acute mesenteric ischaemia entry.", G: "Colonoscopy within 48 hours confirms the diagnosis and allows biopsy. Insufflate minimally, since the ischaemic colon perforates easily. Send stool cultures including Clostridioides difficile, because infective colitis is the main differential.", H: "Most cases are non-gangrenous and settle with supportive care alone: bowel rest, intravenous fluids to restore perfusion, and antibiotics. Optimise oxygenation and cardiac output.", I: "Finding and reversing the precipitant matters as much as the supportive care - hypotension, sepsis, heart failure, dehydration, recent aortic or cardiac surgery, and drugs (vasopressors, cocaine, digoxin, NSAIDs, oestrogens, constipating agents). In younger patients think long-distance running, cocaine and vasculitis.", J: "Reassess at 48 to 72 hours. Failure to improve, or deterioration, is what selects the minority who need surgery.", K: "The great majority recover completely within 1 to 2 weeks, which is the fundamental difference from acute mesenteric ischaemia.", L: "Operate for gangrene, perforation, peritonitis, fulminant colitis or massive bleeding, and for a segment that fails to recover.", M: "Two late complications to warn about and follow up for: an ischaemic STRICTURE, which can present with obstruction weeks to months later, and chronic segmental colitis that mimics inflammatory bowel disease." }, source: "ACG" }, complications: "Ischaemic stricture presenting with obstruction weeks to months later\nChronic segmental colitis mimicking inflammatory bowel disease\nGangrene and perforation - uncommon, but the reason for close reassessment\nMassive lower gastrointestinal bleeding\nIsolated right-sided disease carries a much worse prognosis and often signals superior mesenteric artery disease", cluster: "Lower GI & colorectal", name: "Ischaemic colitis", keyFacts: "Ischaemic injury to the colon at the watershed zones - the commonest form of intestinal ischaemia, and usually transient and self-limiting, unlike acute mesenteric ischaemia.", epidemiology: "The commonest intestinal ischaemia, mainly affecting people over 60 with cardiovascular disease. Most cases are non-gangrenous and resolve completely.", aetiology: "Usually a transient fall in colonic perfusion - hypotension, sepsis, heart failure, dehydration or hypovolaemia. Also after aortic or cardiac surgery, vasculitis and thrombophilia, and drugs (vasopressors, cocaine, digoxin, NSAIDs, oestrogens, constipating agents). In younger patients consider long-distance running and cocaine.", pathophysiology: "The watershed zones between arterial territories are most vulnerable: the SPLENIC FLEXURE (Griffiths' point, between the superior and inferior mesenteric arteries) and the RECTOSIGMOID JUNCTION (Sudeck's point). The rectum is usually spared by its dual internal iliac supply. Injury is typically mucosal and reversible; transmural infarction is uncommon.", presentation: "Sudden crampy, classically left-sided abdominal pain followed within 24 hours by bloody diarrhoea or rectal bleeding, with mild tenderness. The patient is usually far less unwell than in acute mesenteric ischaemia and is typically not shocked.", investigations: "Contrast CT shows segmental thickening in a watershed distribution and excludes other causes; pneumatosis or porto-mesenteric venous gas predict transmural infarction. Plain film may show thumbprinting. Colonoscopy within 48 hours confirms and biopsies, with minimal insufflation. Stool cultures including C. difficile to exclude infective colitis.", treatment: "Mostly conservative - bowel rest, IV fluids and antibiotics, with vasoconstrictors stopped and the precipitating low-flow state corrected. Most recover within 1-2 weeks. Surgery for gangrene, perforation, peritonitis, fulminant colitis or massive bleeding. Isolated right-sided disease, or severe pain without bleeding, should raise suspicion of acute mesenteric ischaemia. Follow up for late stricture." },
      { id: "gi_inguinal_hernia", management: {"source": "NICE CKS / British Hernia Society", "def": "A[\"Groin lump above and medial to pubic tubercle\"]:::start --> B{\"Irreducible, tender or obstructed?\"}:::decision\nB -- \"yes\" --> C[\"Strangulated or incarcerated hernia\"]:::danger\nC --> D[\"Resuscitate, NG tube, IV fluids, emergency repair\"]:::danger\nB -- \"no\" --> E[\"Clinical diagnosis, ultrasound only if uncertain\"]:::process\nE --> F{\"Female patient?\"}:::decision\nF -- \"yes\" --> G[\"Urgent referral - may be an occult femoral hernia\"]:::warn\nF -- \"no\" --> H{\"Symptomatic?\"}:::decision\nH -- \"no or minimal\" --> I[\"Watchful waiting is safe in men\"]:::good\nI --> J[\"Review - most cross over to surgery within 7 years\"]:::process\nH -- \"yes\" --> K[\"Elective mesh repair\"]:::good\nG --> K\nJ --> K\nK --> L{\"Primary unilateral hernia?\"}:::decision\nL -- \"yes\" --> M[\"Open mesh repair (Lichtenstein)\"]:::good\nL -- \"no - bilateral or recurrent\" --> N[\"Laparoscopic repair (TEP or TAPP)\"]:::good\nM --> O[\"Counsel on recurrence and chronic groin pain\"]:::warn\nN --> O", "tips": {"A": "An inguinal hernia emerges above and medial to the pubic tubercle, which is the single most useful bedside discriminator from a femoral hernia.", "B": "Assess reducibility first: a tender, irreducible, erythematous lump with vomiting, distension or absolute constipation means strangulation or obstruction.", "C": "Strangulation is compromise of the blood supply to the contents and is a surgical emergency - progression to infarction and perforation takes hours.", "D": "Resuscitate with intravenous fluids, decompress with a nasogastric tube, give analgesia and antibiotics, and take the patient to theatre without delay.", "E": "Diagnosis is clinical. Reserve ultrasound for a genuinely uncertain groin lump, and CT where obstruction or a complication is suspected.", "F": "Sex changes the pathway: femoral hernias are far commoner in women and are frequently only found at operation, so watchful waiting is not appropriate.", "G": "All women with a groin hernia should be referred urgently for assessment and repair, because an apparent inguinal hernia may in fact be femoral.", "H": "Ask specifically about dragging discomfort, pain on standing or straining, and limitation of work or activity rather than simply about the lump.", "I": "Watchful waiting is safe in men with an asymptomatic or minimally symptomatic inguinal hernia, because the risk of strangulation in this group is low.", "J": "About a third cross over to surgery within 1.5 to 3 years and roughly 70 per cent within about 7 years, usually because symptoms develop.", "K": "Symptomatic groin hernias are repaired surgically, and mesh is the first choice by either an open or a laparoscopic route.", "L": "The approach is chosen by whether the hernia is primary and one-sided, since laparoscopic repair reaches both sides and avoids scarred tissue.", "M": "Open mesh repair by the Lichtenstein technique is the standard for a primary unilateral hernia and can be done under local anaesthetic.", "N": "Laparoscopic repair - totally extraperitoneal or transabdominal preperitoneal - is preferred for bilateral or recurrent hernias and gives less early pain.", "O": "Warn about recurrence and about chronic post-operative groin pain, which affects roughly one in ten and is the commonest long-term complaint after repair."}}, complications: "Incarceration: the hernia becomes irreducible but the blood supply is intact.\nObstruction: bowel within the sac obstructs, causing colicky pain, vomiting, distension and absolute constipation.\nStrangulation: the blood supply is compromised, giving a tender, tense, irreducible lump with overlying erythema, progressing to infarction, perforation and peritonitis.\nRichter's hernia: only part of the bowel circumference is trapped, so strangulation occurs WITHOUT obstruction - a classic trap.\nPost-operative: chronic groin pain (about 10%), recurrence, seroma or haematoma, mesh infection, ischaemic orchitis and testicular atrophy, and injury to the ilioinguinal or genitofemoral nerve.", cluster: "Lower GI & colorectal", name: "Inguinal hernia", keyFacts: "Protrusion of abdominal contents through the inguinal canal, emerging ABOVE and MEDIAL to the pubic tubercle. The commonest hernia in both sexes. Indirect hernias pass through the deep ring lateral to the inferior epigastric vessels; direct hernias push through the posterior wall medial to them.", epidemiology: "The commonest abdominal wall hernia, accounting for about 75% of all hernias. Lifetime risk roughly 27% in men and 3% in women, with a male to female ratio of about 8 to 1. Indirect hernias make up about two thirds. Bimodal age distribution, with a peak in infancy and a second peak from middle age onwards.", aetiology: "Indirect hernias arise from a patent processus vaginalis, so are congenital in origin. Direct hernias are acquired, from weakness of the transversalis fascia in Hesselbach's triangle. Risk factors: male sex, increasing age, chronic cough (COPD, smoking), chronic constipation and straining, bladder outflow obstruction, heavy manual work, ascites, previous abdominal surgery and connective tissue disorders.", pathophysiology: "An INDIRECT hernia enters the deep inguinal ring LATERAL to the inferior epigastric vessels, travels along the inguinal canal and may descend through the superficial ring into the scrotum. A DIRECT hernia pushes forward through a weak posterior wall MEDIAL to the inferior epigastric vessels, within Hesselbach's triangle, and rarely reaches the scrotum. Both emerge above and medial to the pubic tubercle. The neck is relatively wide, which is why strangulation is much less frequent than in a femoral hernia.", presentation: "Groin lump above and medial to the pubic tubercle, with a cough impulse, usually reducible and often disappearing on lying flat. Dragging or aching discomfort worse on standing, coughing or lifting. May extend into the scrotum (indirect). Strangulation presents with a tender, tense, irreducible, erythematous lump with vomiting, distension and absolute constipation.", investigations: "Clinical diagnosis in most cases, examining the patient standing and lying. Ultrasound if the groin lump is uncertain; CT abdomen and pelvis if obstruction or a complication is suspected, or to find an occult hernia. Note the deep ring occlusion test is unreliable, so direct and indirect hernias are reliably distinguished only at operation.", treatment: "Emergency surgery for strangulation or obstruction. Otherwise mesh repair, open or laparoscopic. Watchful waiting is safe in MEN with an asymptomatic or minimally symptomatic hernia, though most eventually cross over to surgery; ALL WOMEN should be referred urgently, because the hernia may be femoral. Open mesh (Lichtenstein) for primary unilateral hernias; laparoscopic (TEP or TAPP) for bilateral or recurrent hernias. Address chronic cough, constipation and straining." },
      { id: "gi_femoral_hernia", management: {"source": "British Hernia Society", "def": "A[\"Groin lump below and lateral to pubic tubercle\"]:::start --> B{\"Signs of strangulation or obstruction?\"}:::decision\nB -- \"yes\" --> C[\"Resuscitate, NG tube, IV fluids, antibiotics\"]:::danger\nC --> D[\"Emergency repair, usually high (McEvedy) approach\"]:::danger\nD --> E[\"Assess bowel viability, resect if infarcted\"]:::danger\nB -- \"no\" --> F[\"Confirm clinically, ultrasound or CT if unclear\"]:::process\nF --> G[\"Exclude saphena varix, lymph node, femoral aneurysm\"]:::process\nG --> H[\"Repair EVERY femoral hernia - no watchful waiting\"]:::warn\nH --> I[\"Urgent elective repair even if asymptomatic\"]:::good\nI --> J{\"Bowel resection likely?\"}:::decision\nJ -- \"yes\" --> K[\"High approach (McEvedy) gives bowel access\"]:::good\nJ -- \"no\" --> L[\"Low approach (Lockwood) with mesh plug\"]:::good\nK --> M[\"Narrow rigid neck means high strangulation risk\"]:::warn\nL --> M", "tips": {"A": "A femoral hernia lies BELOW and LATERAL to the pubic tubercle and medial to the femoral pulse - the mirror image of an inguinal hernia.", "B": "Up to about a third present for the first time as an emergency, so always look for tenderness, irreducibility, vomiting and distension.", "C": "Resuscitate with intravenous fluids, pass a nasogastric tube, give analgesia and antibiotics, and take blood including lactate before theatre.", "D": "Emergency repair is usually by the high McEvedy approach, because it gives access to the abdomen if bowel needs to be inspected or resected.", "E": "Infarcted bowel must be resected. Remember Richter's hernia, where only part of the circumference is trapped, so the bowel strangulates without obstructing.", "F": "The diagnosis is clinical, but a small femoral hernia is easily missed - use ultrasound or CT where the groin lump is uncertain or the patient is obese.", "G": "The differential is a saphena varix (disappears on lying, has a cough thrill and a bluish tinge), an enlarged lymph node, a femoral aneurysm, a psoas abscess or a lipoma.", "H": "This is the key difference from an inguinal hernia: watchful waiting is NEVER appropriate, because the risk of strangulation is high and early.", "I": "Refer urgently for repair regardless of symptoms - a substantial proportion strangulate within two years if left alone.", "J": "Choose the approach on how likely bowel resection is, since the low approach gives poor access to the abdominal cavity.", "K": "The high (McEvedy) approach opens above the inguinal ligament through the rectus sheath, allowing the bowel to be delivered, inspected and resected.", "L": "The low (Lockwood) approach is a small incision below the inguinal ligament, ideal for an elective uncomplicated hernia, closed with a mesh plug or sutures.", "M": "The femoral ring is narrow and bounded by rigid ligaments, so the contents are easily constricted - this anatomy is why femoral hernias behave so badly."}}, complications: "Strangulation: the dominant risk, and far higher than for an inguinal hernia because the femoral ring is narrow and rigidly bounded - a substantial proportion strangulate within two years if not repaired.\nBowel obstruction: colicky pain, vomiting, distension and absolute constipation.\nRichter's hernia: only part of the bowel circumference is trapped, so the bowel strangulates and infarcts WITHOUT causing obstruction - the patient can be gravely ill with an open bowel habit.\nBowel infarction and perforation with peritonitis, requiring resection at laparotomy.\nMaydl's hernia: a W-shaped loop in which the strangulated segment lies back inside the abdomen and is missed unless the abdomen is opened.", cluster: "Lower GI & colorectal", name: "Femoral hernia", keyFacts: "Protrusion of abdominal contents through the femoral canal, emerging BELOW and LATERAL to the pubic tubercle. Much less common than an inguinal hernia but far more dangerous: the neck is narrow and rigid, so strangulation is frequent and early. Every femoral hernia should be repaired urgently, and watchful waiting is never appropriate.", epidemiology: "About 5% of all abdominal wall hernias. Commoner in women, with a female to male ratio of roughly 4 to 1 - although the commonest hernia in women is still the inguinal hernia. Typically middle-aged and elderly, and associated with multiparity and low body mass index. Up to a third present for the first time as an emergency with strangulation or obstruction.", aetiology: "A wide femoral canal, raised intra-abdominal pressure from chronic cough, constipation, straining or heavy lifting, multiparity (stretching of the pelvic ligaments), increasing age and low body mass index with loss of the fat that normally occupies the canal.", pathophysiology: "The hernia passes through the femoral ring into the femoral canal, the most medial compartment of the femoral sheath. The canal is bounded anteriorly by the inguinal ligament, posteriorly by the pectineal (Cooper's) ligament, medially by the lacunar ligament and laterally by the femoral vein. These borders are rigid, so once bowel enters it is easily constricted - this narrow unyielding neck is the reason strangulation is so common and why the hernia is often irreducible with no cough impulse.", presentation: "A small, firm, often irreducible lump in the groin below and lateral to the pubic tubercle and medial to the femoral pulse. A cough impulse is frequently absent. Many are asymptomatic until they present acutely with strangulation or small bowel obstruction - tender irreducible lump, colicky pain, vomiting, distension and absolute constipation.", investigations: "Clinical diagnosis based on the position relative to the pubic tubercle. Ultrasound or CT abdomen and pelvis where the diagnosis is unclear, the patient is obese, or obstruction is suspected. Bloods including lactate and a venous gas if strangulation is suspected. Distinguish from an inguinal hernia, saphena varix, enlarged lymph node, femoral aneurysm, psoas abscess and lipoma.", treatment: "URGENT surgical repair in all cases, symptomatic or not - watchful waiting is never appropriate. Emergency repair with resuscitation, nasogastric decompression and antibiotics if strangulated or obstructed, with bowel resection if infarcted. Elective approaches: LOW (Lockwood) below the inguinal ligament for uncomplicated hernias; HIGH (McEvedy) where bowel resection may be needed, as it gives abdominal access; or transinguinal (Lothiessen). The defect is closed with a mesh plug or sutures." },
      { id: "gi_peutz_jeghers", cluster: "Lower GI & colorectal", name: "Peutz-Jeghers syndrome", keyFacts: "An autosomal dominant syndrome of GI hamartomatous polyps with mucocutaneous pigmentation and raised cancer risk.", epidemiology: "Rare; presents in childhood or early adulthood.", aetiology: "Germline mutation in the STK11 (LKB1) tumour suppressor gene; autosomal dominant.", pathophysiology: "Hamartomatous polyps form throughout the gut (especially small bowel), causing bleeding and intussusception, with an elevated lifetime risk of GI and other cancers.", presentation: "Dark freckle-like pigmentation of the lips and oral mucosa; recurrent abdominal pain, intussusception, GI bleeding, anaemia.", investigations: "Endoscopy and colonoscopy, small-bowel imaging (capsule or MR enterography), genetic testing.", treatment: "Polyp surveillance and removal; manage intussusception; multi-site cancer screening." },
      { id: "gi_colorectal_ca", cluster: "Lower GI & colorectal", name: "Colorectal cancer", keyFacts: "A common cancer arising from adenomatous polyps; the UK screens with faecal immunochemical testing.", epidemiology: "One of the commonest cancers, with incidence rising from middle age.", aetiology: "Age, family history, inflammatory bowel disease, a low-fibre and high-red-meat diet, and syndromes such as FAP and Lynch.", pathophysiology: "Stepwise accumulation of mutations drives the adenoma-to-carcinoma sequence, with local invasion and metastasis, often to the liver.", presentation: "Change in bowel habit, rectal bleeding, weight loss, iron-deficiency anaemia, tenesmus.", investigations: "FIT testing, colonoscopy with biopsy, CT for staging, CEA.", treatment: "Surgical resection, chemo/radiotherapy; refer on 2-week-wait; participate in screening." },
      { id: "gi_haemorrhoids", cluster: "Lower GI & colorectal", name: "Haemorrhoids", keyFacts: "Engorged anal vascular cushions causing painless bright-red rectal bleeding; classified as internal or external.", epidemiology: "Very common, increasing with age and pregnancy.", aetiology: "Constipation and straining, low-fibre diet, pregnancy, raised intra-abdominal pressure, prolonged sitting.", pathophysiology: "Raised pressure engorges and prolapses the anal vascular cushions; external ones (below the dentate line) can thrombose and become painful.", presentation: "Bright-red blood coating stool or on paper, pruritus, prolapse, mucus; pain if thrombosed; internal usually painless.", investigations: "Proctoscopy; colonoscopy to exclude sinister causes if red flags or older age.", treatment: "Fibre, fluids and topical agents; rubber-band ligation or sclerotherapy; haemorrhoidectomy for large or refractory disease." },
      { id: "gi_anal_fissure", cluster: "Lower GI & colorectal", name: "Anal fissure", keyFacts: "A painful tear in the anal mucosa, usually posterior midline, classically following hard stool.", epidemiology: "Common in young adults; affects both sexes.", aetiology: "Hard stool and constipation, low-fibre diet, childbirth; atypical or lateral fissures suggest Crohn's, infection or malignancy.", pathophysiology: "A mucosal tear causes pain and reflex internal sphincter spasm, which reduces blood flow and impairs healing, perpetuating a chronic fissure.", presentation: "Severe pain on defaecation with fresh bright-red blood on the paper; a visible tear, usually posterior midline.", investigations: "Clinical diagnosis on inspection; look for secondary causes if atypical.", treatment: "Stool softeners, fibre and fluids; topical GTN or diltiazem; botulinum toxin or lateral sphincterotomy if chronic." },
      { id: "gi_anal_fistula", cluster: "Lower GI & colorectal", name: "Anal fistula", keyFacts: "An abnormal track between the anal canal and perianal skin, often after an anorectal abscess.", epidemiology: "Commoner in men; associated with Crohn's disease.", aetiology: "Usually follows a cryptoglandular anorectal abscess; also Crohn's, TB, malignancy and radiation.", pathophysiology: "Infection of an anal gland forms an abscess that drains, leaving an epithelialised track (described by Goodsall's rule and the Parks classification).", presentation: "Recurrent perianal discharge, pain and swelling, with an external opening that intermittently discharges or abscesses.", investigations: "Examination and proctoscopy; MRI pelvis for complex or Crohn's fistulae; examination under anaesthesia.", treatment: "Fistulotomy for simple low fistulae; seton for complex or high tracks; treat underlying Crohn's." },
      { id: "gi_hepatitis", cluster: "Liver disease", name: "Viral hepatitis", keyFacts: "Inflammation of the liver; the viral types differ in transmission and chronicity.", epidemiology: "Hepatitis A is faecal-oral; B and C are blood-borne and can become chronic.", aetiology: "Hepatitis A and E (faecal-oral), B, C and D (blood and body fluids); also alcohol, drugs and autoimmune causes.", pathophysiology: "Viral infection of hepatocytes provokes immune-mediated liver injury; persistence (B, C) drives chronic inflammation, fibrosis and cancer risk.", presentation: "Malaise, jaundice, RUQ discomfort, deranged LFTs; risk factors guide type.", investigations: "Hepatitis A/B/C serology, LFTs, clotting.", treatment: "Supportive for A; antivirals for chronic B/C; notify; vaccinate contacts for B." },
      { id: "gi_autoimmune_hepatitis", cluster: "Liver disease", name: "Autoimmune hepatitis", keyFacts: "Chronic immune-mediated hepatocyte inflammation that responds well to immunosuppression.", epidemiology: "Commoner in women, with peaks in young and middle age.", aetiology: "Autoimmune; associated with other autoimmune diseases and sometimes triggered by drugs or viral infection.", pathophysiology: "Loss of tolerance to hepatocyte antigens drives chronic interface hepatitis, progressing to fibrosis and cirrhosis if untreated.", presentation: "Ranges from asymptomatic deranged LFTs to fatigue, jaundice or acute hepatitis; signs of chronic liver disease.", investigations: "Raised transaminases and IgG, autoantibodies (ANA, anti-smooth muscle, anti-LKM1), liver biopsy showing interface hepatitis.", treatment: "Corticosteroids (prednisolone) with azathioprine; long-term immunosuppression; transplant for end-stage disease." },
      { id: "gi_alcoholic_liver", cluster: "Liver disease", name: "Alcoholic liver disease", keyFacts: "A spectrum from fatty liver through alcoholic hepatitis to cirrhosis caused by chronic excess alcohol.", epidemiology: "A major cause of liver disease and liver-related death in the UK.", aetiology: "Chronic excessive alcohol intake; risk modified by sex, genetics, obesity and co-existing viral hepatitis.", pathophysiology: "Alcohol metabolism generates toxic acetaldehyde and oxidative stress, causing steatosis, hepatocyte inflammation (Mallory bodies) and progressive fibrosis.", presentation: "Often silent; alcoholic hepatitis gives jaundice, tender hepatomegaly and fever; signs of chronic liver disease once cirrhotic.", investigations: "LFTs (AST:ALT ratio over 2), GGT, FBC (macrocytosis), clotting, ultrasound; Maddrey's score for hepatitis severity.", treatment: "Abstinence is key, with nutrition and thiamine and withdrawal management; steroids for severe alcoholic hepatitis; manage cirrhosis complications." },
      { id: "gi_masld", management: { def: "A[\"Fatty liver on imaging, raised ALT, or cardiometabolic risk factors\"]:::start --> B{\"At least one cardiometabolic criterion\"}:::decision\nB -- \"none\" --> C[\"Not MASLD - look for another cause of steatosis\"]:::good\nB -- \"one or more\" --> D{\"Alcohol intake\"}:::decision\nD -- \"high\" --> E[\"Alcohol-related liver disease - see that entry\"]:::warn\nD -- \"the MetALD band\" --> F[\"MetALD - metabolic AND alcohol drivers together\"]:::warn\nD -- \"low or none\" --> G[\"MASLD confirmed - steatosis plus metabolic dysfunction\"]:::danger\nF --> H[\"Exclude other liver disease - viral, autoimmune, haemochromatosis, Wilson, drugs\"]:::process\nG --> H\nH --> I[\"RISK-STRATIFY FOR FIBROSIS - stage, not steatosis, determines outcome\"]:::process\nI --> J{\"Which fibrosis pathway\"}:::decision\nJ -- \"NICE NG49\" --> K[\"ELF test - 10.51 or above means advanced fibrosis\"]:::warn\nJ -- \"EASL 2024\" --> L[\"FIB-4 first, then transient elastography if raised or indeterminate\"]:::warn\nK --> M{\"Advanced fibrosis\"}:::decision\nL --> M\nM -- \"yes\" --> N[\"Refer to hepatology - HCC and varices surveillance once cirrhotic\"]:::danger\nM -- \"no\" --> O[\"Manage in primary care, retest in 3 years\"]:::good\nN --> P[\"Weight loss 7 to 10%, Mediterranean diet, exercise, treat cardiometabolic risk - STATINS ARE SAFE\"]:::good\nO --> P\nP --> Q[\"MASH with F2-F3 fibrosis - resmetirom or semaglutide, MHRA-approved 2026, awaiting NICE appraisal\"]:::good", tips: { A: "MASLD is usually found by accident - a bright liver on an ultrasound done for something else, or a mildly raised ALT. Note that TRANSAMINASES ARE OFTEN NORMAL and a normal ALT does NOT exclude advanced fibrosis, which is why risk-stratification is driven by risk factors rather than by liver enzymes.", B: "This is the change that came with the 2023 renaming and it is the most examinable point: MASLD requires POSITIVE evidence of metabolic dysfunction, whereas the old NAFLD was a diagnosis of exclusion. At least one of five cardiometabolic criteria is needed - raised BMI or waist circumference, hyperglycaemia or type 2 diabetes, raised blood pressure, raised triglycerides, or low HDL cholesterol (or being on treatment for any of them).", C: "Steatosis without metabolic dysfunction is not MASLD. Think about drugs (methotrexate, amiodarone, tamoxifen, steroids, sodium valproate), coeliac disease, hypothyroidism, hepatitis C, parenteral nutrition, and the rarer inherited and cryptogenic causes.", D: "Alcohol is no longer a simple yes/no exclusion - the 2023 framework recognises that the two drivers coexist, and grades them.", E: "Above the MetALD band, this is alcohol-related liver disease. See the Alcohol-related liver disease entry for the spectrum and management.", F: "MetALD is the genuinely new category, for people who meet MASLD criteria AND drink at an intermediate level: 140 to 350 g per week in women and 210 to 420 g per week in men (roughly 20 to 50 and 30 to 60 g per day). It is not a diagnostic fudge - it recognises that both drivers contribute and both have to be addressed. All of this sits under the umbrella term STEATOTIC LIVER DISEASE (SLD).", G: "MASLD replaces NAFLD, and MASH (metabolic dysfunction-associated steatohepatitis) replaces NASH. Both old names will remain in circulation for years, so recognise them.", H: "MASLD is common enough to coexist with anything, so exclude concurrent liver disease: hepatitis B and C serology, autoantibodies and immunoglobulins, ferritin and transferrin saturation, caeruloplasmin in the young, alpha-1 antitrypsin, and a drug history.", I: "This is the whole point of the assessment. The degree of steatosis barely matters; FIBROSIS STAGE is what predicts liver-related outcomes and death, so every patient with MASLD needs risk-stratifying rather than simply being labelled and discharged.", J: "Be aware the UK and international pathways differ, because NICE has not yet been updated to the new framework.", K: "NICE NG49 is still current, still uses the NAFLD name, and recommends the Enhanced Liver Fibrosis (ELF) blood test: a score of 10.51 or above indicates advanced fibrosis and warrants referral. Below that, retest every 3 years in adults and every 2 years in children and young people.", L: "The EASL-EASD-EASO 2024 guideline uses a stepwise approach: FIB-4 (calculated from age, AST, ALT and platelets) as the first-line rule-out, then transient elastography (FibroScan) for those who are indeterminate or high risk. FIB-4 is free and calculable from routine bloods, which is why it has largely become the practical first step.", M: "Advanced fibrosis (F3) and cirrhosis (F4) are what change management and prognosis.", N: "Refer for specialist assessment. Once cirrhotic, enrol in 6-monthly ultrasound surveillance for hepatocellular carcinoma and endoscopic screening for varices. Note that MASLD-related HCC can occasionally arise WITHOUT cirrhosis, which is unusual among the chronic liver diseases.", O: "Most patients have no advanced fibrosis and are managed in primary care with lifestyle change and cardiometabolic risk reduction, with periodic re-assessment.", P: "Weight loss is the mainstay and is dose-dependent: around 5% improves steatosis, 7 to 10% achieves MASH resolution, and 10% or more can regress fibrosis. Mediterranean diet, exercise and reduced alcohol. Treat the cardiometabolic risk factors aggressively - and note that STATINS ARE SAFE IN MASLD and must not be withheld for mildly deranged liver enzymes, because CARDIOVASCULAR DISEASE, NOT LIVER DISEASE, IS THE LEADING CAUSE OF DEATH in this population. GLP-1 receptor agonists and bariatric surgery where obesity or type 2 diabetes coexist; pioglitazone or vitamin E in selected patients.", Q: "Drug treatment specifically for MASH arrived in the UK in 2026. The MHRA authorised RESMETIROM (Rezdiffra), a liver-directed thyroid hormone receptor-beta agonist, on 3 June 2026 for MASH with stage F2-F3 fibrosis - the first medicine licensed in the UK for MASH - and also authorised SEMAGLUTIDE for MASH with moderate to advanced fibrosis on the strength of the ESSENCE trial. Both are awaiting NICE technology appraisal, so neither is routinely available on the NHS yet." }, source: "NICE NG49 / EASL-EASD-EASO" }, complications: "MASH - the inflammatory subset that drives fibrosis\nCirrhosis and its decompensation\nHepatocellular carcinoma - which in MASLD can arise WITHOUT cirrhosis\nCARDIOVASCULAR DISEASE - the leading cause of death in MASLD, ahead of liver disease\nType 2 diabetes and chronic kidney disease\nAn increasingly common indication for liver transplantation", cluster: "Liver disease", name: "MASLD (metabolic dysfunction-associated steatotic liver disease)", keyFacts: "Fat accumulation in the liver driven by metabolic dysfunction, and the commonest liver disease worldwide. Renamed from NAFLD in 2023 and now requires POSITIVE metabolic criteria rather than being a diagnosis of exclusion.", epidemiology: "Affects roughly 25-30% of adults and rising with obesity and type 2 diabetes; the commonest cause of abnormal liver enzymes and an increasingly common indication for liver transplantation.", aetiology: "Obesity (especially central), type 2 diabetes and insulin resistance, hypertension, dyslipidaemia and the metabolic syndrome; also polycystic ovary syndrome and obstructive sleep apnoea. At least one of five cardiometabolic criteria is required for the diagnosis.", pathophysiology: "Insulin resistance increases free fatty acid delivery and de novo lipogenesis, so triglyceride accumulates in hepatocytes. In a subset, lipotoxicity, oxidative stress and inflammation produce hepatocyte ballooning and steatohepatitis (MASH), driving progressive fibrosis to cirrhosis and hepatocellular carcinoma. FIBROSIS STAGE, not the degree of steatosis, determines outcome.", presentation: "Usually asymptomatic and incidental. May cause fatigue and right upper quadrant discomfort, with hepatomegaly; otherwise presents late with decompensated cirrhosis. Transaminases are often NORMAL and a normal ALT does not exclude advanced fibrosis.", investigations: "Ultrasound shows a bright, echogenic liver. Diagnosis requires steatosis PLUS at least one cardiometabolic criterion PLUS exclusion of harmful alcohol and other liver disease (viral serology, autoantibodies, ferritin and transferrin saturation, caeruloplasmin, alpha-1 antitrypsin). Then stage fibrosis: NICE NG49 uses the ELF test (10.51 or above indicates advanced fibrosis, retest at 3 years if below); EASL-EASD-EASO 2024 uses FIB-4 first then transient elastography. Biopsy only where the diagnosis stays uncertain.", treatment: "Weight loss is the mainstay and is dose-dependent - about 5% improves steatosis, 7-10% achieves MASH resolution, 10% or more can regress fibrosis - with a Mediterranean diet, exercise and reduced alcohol. Treat cardiometabolic risk aggressively: STATINS ARE SAFE and must not be withheld, since cardiovascular disease is the leading cause of death. GLP-1 receptor agonists and bariatric surgery where obesity or type 2 diabetes coexist; pioglitazone or vitamin E in selected patients. Resmetirom and semaglutide were MHRA-approved in 2026 for MASH with F2-F3 fibrosis and await NICE appraisal. Surveillance for HCC and varices once cirrhotic." },
      { id: "gi_cirrhosis", cluster: "Liver disease", name: "Liver cirrhosis", keyFacts: "Irreversible liver fibrosis with nodular regeneration, leading to portal hypertension and liver failure.", epidemiology: "Rising incidence, largely driven by alcohol and fatty liver disease.", aetiology: "Alcohol, non-alcoholic fatty liver disease, chronic hepatitis B and C, and autoimmune or genetic liver disease.", pathophysiology: "Chronic injury drives progressive fibrosis that distorts liver architecture, raising portal pressure and reducing synthetic and detoxifying function.", presentation: "Jaundice, ascites, spider naevi, encephalopathy, variceal bleeding.", investigations: "LFTs, clotting, albumin, ultrasound, fibroscan, ascitic tap.", treatment: "Treat cause, alcohol abstinence; manage complications; surveillance for HCC; transplant assessment." },
      { id: "gi_hepatic_encephalopathy", management: { def: "A[\"Confusion or altered consciousness in known or suspected liver disease\"]:::start --> B[\"Grade with West Haven - I sleep reversal, II asterixis and disorientation, III somnolent but rousable, IV coma\"]:::process\nB --> C{\"Exclude the mimics - hypoglycaemia, sepsis, intracranial bleed, alcohol withdrawal, Wernicke encephalopathy\"}:::decision\nC -- \"another cause\" --> D[\"Treat that cause instead\"]:::good\nC -- \"consistent with HE\" --> E[\"FIND AND TREAT THE PRECIPITANT - septic screen with ascitic tap for SBP, GI bleed, constipation, dehydration, electrolytes, sedatives\"]:::process\nE --> F[\"Lactulose titrated to 2 to 3 soft stools daily, phosphate enema if not passing stool\"]:::good\nF --> G[\"Stop sedatives and opiates, correct hypokalaemia and hyponatraemia\"]:::warn\nG --> H[\"Feed normally - do NOT protein restrict, target 1.2 to 1.5 g/kg/day\"]:::good\nH --> I{\"Grade III or IV, or airway at risk\"}:::decision\nI -- \"yes\" --> J[\"Critical care, protect the airway\"]:::danger\nI -- \"no\" --> K{\"Improving on lactulose\"}:::decision\nJ --> K\nK -- \"no\" --> L[\"Add rifaximin, re-hunt the precipitant, seek hepatology input\"]:::warn\nK -- \"yes\" --> M{\"Second or further overt episode\"}:::decision\nM -- \"yes\" --> N[\"Rifaximin 550 mg twice daily for secondary prevention\"]:::good\nM -- \"no\" --> O[\"Continue lactulose, keep the bowels open, avoid sedatives\"]:::good\nN --> P[\"Assess for liver transplantation\"]:::good\nO --> P", tips: { A: "Hepatic encephalopathy is a reversible neuropsychiatric syndrome complicating liver failure. Suspect it in anyone with cirrhosis who becomes confused, drowsy or behaviourally altered - but it remains a diagnosis of exclusion, because the differential in a decompensating cirrhotic is wide.", B: "The West Haven criteria grade severity: I - altered mood, sleep reversal and mild inattention; II - lethargy, disorientation in time, obvious personality change, ASTERIXIS; III - gross disorientation, marked confusion, somnolent but rousable; IV - coma. Grade II or above counts as OVERT hepatic encephalopathy. Look for asterixis (the flapping tremor), constructional apraxia and fetor hepaticus.", C: "This is the step that gets missed. Always exclude hypoglycaemia (check a glucose in every confused cirrhotic), sepsis, intracranial haemorrhage (these patients are coagulopathic and fall), alcohol withdrawal and Wernicke's encephalopathy - the last two are common in exactly this population and are treated completely differently. CT head if there are focal signs, a fall, or no response to treatment.", D: "If another cause explains the picture, treat that - and remember more than one can be present at once.", E: "Hepatic encephalopathy is almost never spontaneous, so FINDING THE PRECIPITANT IS THE TREATMENT. The common ones are infection (do an ascitic tap for spontaneous bacterial peritonitis in anyone with ascites), gastrointestinal bleeding (a protein meal in the gut), constipation, dehydration and over-diuresis, electrolyte disturbance especially hypokalaemia and hyponatraemia, sedatives and opiates, renal impairment, and a recent TIPSS.", F: "Lactulose is first-line. It acidifies the colon, converting ammonia to non-absorbable ammonium and acting as an osmotic laxative. Titrate the DOSE TO THE STOOLS - 2 to 3 soft stools daily - not to a fixed prescription. If the patient is not passing stool, give a phosphate enema; lactulose can also be given by nasogastric tube.", G: "Stop or avoid anything sedating, since these patients are exquisitely sensitive to benzodiazepines and opiates. Correct hypokalaemia in particular - it increases renal ammonia production and directly worsens encephalopathy.", H: "DO NOT PROTEIN RESTRICT. This is the classic outdated teaching and it is now explicitly advised against, because these patients are catabolic and sarcopenic and restriction worsens outcomes. Target 1.2 to 1.5 g/kg/day of protein, with small frequent meals and a late evening carbohydrate snack.", I: "Grade III and IV disease is an airway emergency - the patient cannot protect their airway and is at high risk of aspiration.", J: "Escalate to critical care for airway protection and supportive management. Nurse with the head up, and consider intubation for grade IV.", K: "Most episodes improve within 24 to 48 hours once the precipitant is treated and the bowels are open. Failure to improve should send you back to look for a missed precipitant - most often an undiagnosed infection or ongoing bleeding - rather than simply escalating the lactulose.", L: "Rifaximin is a non-absorbed antibiotic that reduces ammonia-producing gut flora. It is added to lactulose rather than replacing it.", M: "Secondary prevention is decided by whether this is a recurrence.", N: "NICE TA337 recommends rifaximin, added to lactulose, to reduce the recurrence of overt hepatic encephalopathy in adults who have had two or more episodes. It roughly halves recurrence and hospital admissions.", O: "After a first episode, continue lactulose titrated to stool frequency, keep the bowels open, and counsel the patient and family to seek help early - and about DRIVING, since overt encephalopathy affects fitness to drive and must be declared.", P: "An episode of overt hepatic encephalopathy is a marker of decompensated cirrhosis and a poor prognosis, so it should trigger assessment for liver transplantation in anyone potentially eligible." }, source: "EASL-AASLD / NICE TA337" }, complications: "Aspiration pneumonia - the airway is unprotected at grade III and IV\nCerebral oedema and raised intracranial pressure, mainly in ACUTE liver failure rather than cirrhosis\nRecurrence - common, and the reason for rifaximin secondary prevention\nFalls and injury from confusion in a coagulopathic patient\nMarks decompensated cirrhosis and a poor prognosis - a trigger for transplant assessment\nImpaired fitness to drive, which must be declared", cluster: "Liver disease", name: "Hepatic encephalopathy", keyFacts: "A reversible neuropsychiatric syndrome complicating liver failure, caused by failure to clear gut-derived nitrogenous toxins - chiefly ammonia - from the circulation.", epidemiology: "Affects up to 40% of people with cirrhosis at some point; an overt episode defines decompensation and carries a poor prognosis.", aetiology: "Cirrhosis with portosystemic shunting, or acute liver failure. Precipitants: infection (especially spontaneous bacterial peritonitis), GI bleeding, constipation, dehydration and over-diuresis, hypokalaemia and hyponatraemia, sedatives and opiates, renal impairment, and TIPSS.", pathophysiology: "Failing hepatocytes and portosystemic shunts let gut-derived ammonia reach the brain, where astrocytes convert it to glutamine; the resulting osmotic swelling causes astrocyte dysfunction and cerebral oedema, compounded by systemic inflammation and altered GABAergic tone.", presentation: "Graded by West Haven: I sleep reversal and altered mood, II lethargy, disorientation and ASTERIXIS, III marked confusion but rousable, IV coma. Also constructional apraxia and fetor hepaticus, on a background of chronic liver disease stigmata.", investigations: "Largely clinical and a diagnosis of EXCLUSION - check glucose, septic screen with ascitic tap for SBP, U&E, LFTs, clotting, and CT head if focal signs or no response. Serum ammonia is often raised but correlates poorly with grade and should not be used to diagnose or monitor.", treatment: "FIND AND TREAT THE PRECIPITANT - this is the mainstay. Lactulose titrated to 2-3 soft stools daily (phosphate enema if not passing stool). Stop sedatives and opiates, correct hypokalaemia and hyponatraemia. Do NOT protein restrict - target 1.2-1.5 g/kg/day. Rifaximin 550 mg twice daily added to lactulose for secondary prevention after a second overt episode (NICE TA337). Airway protection and critical care at grade III-IV; assess for transplantation." },
      { id: "haem_wilson", cluster: "Liver disease", name: "Wilson's disease", keyFacts: "An inherited disorder of copper accumulation affecting the liver and brain; treatable, so do not miss it in young people.", epidemiology: "Rare; presents with liver disease in childhood or neuropsychiatric disease in young adults.", aetiology: "Autosomal recessive mutation in the ATP7B copper-transporting gene.", pathophysiology: "Impaired biliary copper excretion deposits copper in the liver, brain (basal ganglia), eyes and red cells.", presentation: "Liver disease (hepatitis, cirrhosis), neuropsychiatric features (tremor, dystonia, parkinsonism, mood change), Kayser-Fleischer rings and a Coombs-negative haemolytic anaemia.", investigations: "Low serum caeruloplasmin and copper, high 24-hour urinary copper, slit-lamp for Kayser-Fleischer rings, raised hepatic copper; genetic testing.", treatment: "Copper chelation (penicillamine or trientine) and zinc; avoid copper-rich foods; liver transplant for fulminant disease." },
      { id: "gi_budd_chiari", cluster: "Liver disease", name: "Budd-Chiari syndrome", keyFacts: "Hepatic venous outflow obstruction causing the triad of abdominal pain, ascites and hepatomegaly.", epidemiology: "Rare; often a young adult with a prothrombotic tendency.", aetiology: "Hepatic vein thrombosis from prothrombotic states (myeloproliferative disease and JAK2, pregnancy, the combined pill, antiphospholipid syndrome, Factor V Leiden).", pathophysiology: "Obstruction of hepatic venous outflow causes congestion, raised sinusoidal pressure, ischaemia and, over time, cirrhosis.", presentation: "Triad of abdominal pain, tender hepatomegaly and ascites; may be acute or chronic.", investigations: "Doppler ultrasound of the hepatic veins (first-line), CT/MRI venography, LFTs, thrombophilia screen.", treatment: "Anticoagulation and treat the underlying cause; TIPS or angioplasty; transplant for fulminant disease." },
      { id: "gi_liver_abscess", cluster: "Liver disease", name: "Liver abscess", keyFacts: "A pus-filled liver collection, most commonly pyogenic (bacterial) or amoebic.", epidemiology: "Pyogenic abscesses predominate in the UK; amoebic in travellers and endemic areas.", aetiology: "Pyogenic from biliary sepsis or portal spread (diverticulitis, appendicitis); amoebic from Entamoeba histolytica.", pathophysiology: "Bacteria or amoebae seed the liver and form a localised pus collection, often in the right lobe.", presentation: "Swinging fever, rigors, right upper quadrant pain, tender hepatomegaly, weight loss, night sweats.", investigations: "Ultrasound/CT, FBC (leucocytosis), blood cultures, LFTs; amoebic serology and stool; aspirate (anchovy-sauce pus in amoebic).", treatment: "Image-guided drainage plus broad-spectrum antibiotics for pyogenic; metronidazole for amoebic." },
      { id: "gi_hcc", cluster: "Liver disease", name: "Hepatocellular carcinoma", keyFacts: "The commonest primary liver cancer, usually arising in a cirrhotic liver; alpha-fetoprotein is a tumour marker.", epidemiology: "Rising incidence; commoner in men.", aetiology: "Cirrhosis of any cause, chronic hepatitis B and C, alcohol, non-alcoholic fatty liver disease, aflatoxin, haemochromatosis.", pathophysiology: "Chronic injury and cirrhosis drive hepatocyte regeneration and accumulating mutations, producing a tumour prone to vascular invasion.", presentation: "Decompensation of known cirrhosis, weight loss, right upper quadrant pain, hepatomegaly; often found on surveillance.", investigations: "Ultrasound surveillance, AFP, multiphase CT/MRI (arterial enhancement with washout), biopsy if uncertain.", treatment: "Resection or transplant for early disease; ablation or TACE; systemic therapy (e.g. atezolizumab with bevacizumab) for advanced." },
      { id: "gi_gallstones", cluster: "Biliary tract & gallbladder", name: "Gallstones & biliary colic", keyFacts: "Stones in the gallbladder causing biliary colic; complications include cholecystitis, cholangitis and pancreatitis.", epidemiology: "Common; the classic risk profile is fair, fat, female, forty and fertile.", aetiology: "Cholesterol or pigment stones favoured by obesity, female sex, age, rapid weight loss and haemolysis.", pathophysiology: "Supersaturated bile forms stones that intermittently obstruct the cystic or common bile duct, causing pain and, if infected, inflammation.", presentation: "Right upper quadrant pain after fatty food; fever and jaundice suggest cholangitis/cholecystitis.", investigations: "Abdominal ultrasound, LFTs, amylase; MRCP for duct stones.", treatment: "Analgesia, laparoscopic cholecystectomy; ERCP for ductal stones; antibiotics for infection." },
      { id: "gi_cholecystitis", cluster: "Biliary tract & gallbladder", name: "Acute cholecystitis", keyFacts: "Inflammation of the gallbladder, almost always from a stone obstructing the cystic duct; presents with persistent right upper quadrant pain, fever and a positive Murphy's sign.", epidemiology: "Common, especially in the classic fat, female, forty and fertile group; a frequent complication of gallstones, which affect roughly 10-15% of adults.", aetiology: "Over 90% are calculous (a stone impacted in the cystic duct or Hartmann's pouch); acalculous cholecystitis occurs in critically ill, fasting or diabetic patients.", pathophysiology: "Cystic duct obstruction causes gallbladder distension, mucosal inflammation and wall oedema; secondary bacterial infection and, if unrelieved, empyema, gangrene or perforation can follow.", presentation: "Constant right upper quadrant or epigastric pain (lasting longer than biliary colic) radiating to the right shoulder, with fever, nausea and a positive Murphy's sign (arrest of inspiration on right upper quadrant palpation). Jaundice is usually absent - if present, suspect a common bile duct stone or cholangitis.", investigations: "Bloods (raised white cells and CRP, usually normal or only mildly deranged LFTs); abdominal ultrasound first-line (gallstones, a thick-walled distended gallbladder, pericholecystic fluid, sonographic Murphy's sign); MRCP if a common bile duct stone is suspected.", treatment: "Admit for IV fluids, analgesia, antiemetics and IV antibiotics; NICE recommends early laparoscopic cholecystectomy (within 1 week of diagnosis, ideally the same admission); percutaneous cholecystostomy if unfit for surgery.", management: {"def": "A[\"Acute cholecystitis\"]:::start --> B[\"Confirm: RUQ pain, fever, positive Murphy sign\"]:::process\nB --> C[\"Ultrasound: stones, thick-walled gallbladder\"]:::process\nC --> D[\"Admit: IV fluids, analgesia, antiemetics, IV antibiotics\"]:::good\nD --> E{\"Fit for surgery?\"}:::decision\nE -- \"yes\" --> F[\"Early laparoscopic cholecystectomy (within 1 week)\"]:::good\nE -- \"high surgical risk\" --> G[\"Percutaneous cholecystostomy\"]:::warn\nB -- \"jaundice or dilated CBD\" --> H[\"Suspect CBD stone: MRCP / ERCP\"]:::process", "tips": {"A": "Inflammation of the gallbladder, almost always from a gallstone impacted in the cystic duct; distinguished from biliary colic by persistent pain, fever and raised inflammatory markers.", "B": "Murphy's sign is arrest of inspiration during palpation of the right upper quadrant (specific for cholecystitis). Jaundice is usually absent - if present, suspect a common bile duct stone or cholangitis.", "C": "Abdominal ultrasound is first-line: gallstones, a thick-walled (over 3 mm) distended gallbladder, pericholecystic fluid and a sonographic Murphy's sign.", "D": "Admit for supportive care (IV fluids, analgesia, antiemetics) and IV antibiotics such as co-amoxiclav per local policy.", "E": "Assess fitness for surgery, which determines definitive management.", "F": "NICE recommends early laparoscopic cholecystectomy, ideally within 1 week of diagnosis (same admission), rather than delayed interval surgery.", "G": "If too high-risk for surgery (unfit, severe sepsis), a percutaneous cholecystostomy drains the gallbladder, with interval cholecystectomy later.", "H": "Jaundice, a dilated common bile duct or deranged LFTs suggest a common bile duct stone (choledocholithiasis) or cholangitis - image with MRCP and consider ERCP."}} },
      { id: "gi_cholangitis", cluster: "Biliary tract & gallbladder", name: "Ascending cholangitis", keyFacts: "A bacterial infection of the biliary tree behind an obstructed bile duct (usually a gallstone) - also called acute cholangitis; produces Charcot's triad of fever, right upper quadrant pain and jaundice, and is a life-threatening emergency needing both antibiotics and biliary drainage.", epidemiology: "Most often in older adults; the commonest cause is choledocholithiasis (a stone in the common bile duct), followed by benign strictures, blocked stents and malignant obstruction.", aetiology: "Biliary obstruction (common bile duct stones, strictures, tumours, blocked stents) with infection by enteric organisms ascending from the gut - typically Gram-negatives (E. coli, Klebsiella), enterococci and anaerobes.", pathophysiology: "Obstruction raises intrabiliary pressure, letting enteric bacteria proliferate and translocate into the bloodstream to cause biliary sepsis; without decompression it progresses to septic shock and multi-organ failure.", presentation: "Charcot's triad - fever with rigors, right upper quadrant pain and jaundice; the addition of hypotension and confusion (Reynolds' pentad) indicates severe suppurative cholangitis.", investigations: "Bloods (FBC, raised inflammatory markers, a cholestatic picture with high ALP/GGT and bilirubin, U&Es and blood cultures); abdominal ultrasound first-line for a dilated common bile duct and stones, then MRCP (or endoscopic ultrasound) to define the obstruction.", treatment: "Resuscitate as sepsis (Sepsis Six, IV fluids); broad-spectrum IV antibiotics covering Gram-negatives and anaerobes; urgent biliary decompression, usually ERCP with sphincterotomy and stone removal or stenting (percutaneous transhepatic drainage if ERCP fails); interval cholecystectomy for gallstone disease.", management: {"source": "Tokyo Guidelines", "def": "A[\"Ascending cholangitis\"]:::start --> B[\"Suspect: Charcot triad (fever, RUQ pain, jaundice)\"]:::process\nB --> C[\"Resuscitate: sepsis six, IV fluids, blood cultures\"]:::danger\nC --> D[\"Broad-spectrum IV antibiotics (Gram-neg + anaerobes)\"]:::good\nD --> E[\"Confirm obstruction: USS then MRCP\"]:::process\nE --> F{\"Response to antibiotics?\"}:::decision\nF -- \"improving (mild)\" --> G[\"Biliary drainage (ERCP) semi-electively\"]:::good\nF -- \"severe or not improving\" --> H[\"Urgent biliary decompression (ERCP within 24h)\"]:::danger\nH -- \"ERCP fails\" --> I[\"Percutaneous or surgical drainage\"]:::warn\nG --> J[\"Interval cholecystectomy for gallstones\"]:::process", "tips": {"A": "Infection of the biliary tree behind an obstruction (usually a common bile duct stone); a life-threatening emergency needing antibiotics AND biliary drainage.", "B": "Charcot's triad is fever/rigors, right upper quadrant pain and jaundice; adding hypotension and confusion (Reynolds' pentad) signals severe suppurative cholangitis.", "C": "Treat as sepsis: the Sepsis Six, IV fluid resuscitation, and blood cultures before antibiotics.", "D": "Start broad-spectrum IV antibiotics covering Gram-negatives and anaerobes (e.g. co-amoxiclav plus metronidazole, or piperacillin-tazobactam) per local policy.", "E": "Confirm the level and cause of obstruction: ultrasound first-line (dilated CBD, stones), then MRCP or endoscopic ultrasound to plan intervention.", "F": "Grade severity (Tokyo Guidelines): the response to resuscitation and antibiotics guides the timing of drainage.", "G": "Mild disease responding to antibiotics: biliary drainage can be semi-elective (ERCP with sphincterotomy and stone extraction or stenting).", "H": "Moderate-to-severe cholangitis, or failure to improve, needs urgent biliary decompression - ERCP (ideally within 24 hours) is first-line.", "I": "If ERCP is unsuccessful or not possible: percutaneous transhepatic biliary drainage, or surgical decompression.", "J": "After recovery, arrange definitive treatment of the cause - cholecystectomy for gallstone disease to prevent recurrence."}} },
      { id: "gi_pbc", cluster: "Biliary tract & gallbladder", name: "Primary biliary cholangitis", keyFacts: "Autoimmune destruction of small intrahepatic bile ducts; presents with itch and fatigue and is AMA-positive.", epidemiology: "Predominantly middle-aged women.", aetiology: "Autoimmune; associated with other autoimmune conditions (Sjogren's, thyroid disease, coeliac).", pathophysiology: "Immune-mediated granulomatous destruction of small intrahepatic bile ducts causes chronic cholestasis, fibrosis and cirrhosis.", presentation: "Fatigue and pruritus, later jaundice; xanthelasma, hepatomegaly and signs of cirrhosis over time.", investigations: "Cholestatic LFTs (raised ALP), anti-mitochondrial antibodies (AMA), raised IgM, ultrasound to exclude obstruction.", treatment: "Ursodeoxycholic acid (first-line), obeticholic acid; cholestyramine for itch; fat-soluble vitamins; transplant for end-stage." },
      { id: "gi_psc", cluster: "Biliary tract & gallbladder", name: "Primary sclerosing cholangitis", keyFacts: "Progressive fibrosing inflammation of intra- and extrahepatic bile ducts; strongly linked to ulcerative colitis.", epidemiology: "Commoner in men aged 30-50; the majority have inflammatory bowel disease.", aetiology: "Unknown and immune-mediated; strong association with ulcerative colitis.", pathophysiology: "Concentric fibrosis and strictures of the biliary tree (beaded ducts) cause chronic cholestasis, cirrhosis and a high risk of cholangiocarcinoma.", presentation: "Fatigue, pruritus, intermittent jaundice and right upper quadrant pain; recurrent cholangitis.", investigations: "Cholestatic LFTs, MRCP (multifocal strictures and beading), pANCA, IgG4 to exclude mimics; colonoscopy for IBD.", treatment: "Supportive care, ursodeoxycholic acid for symptoms, ERCP for dominant strictures; transplant for end-stage; cancer surveillance." },
      { id: "gi_cholangiocarcinoma", cluster: "Biliary tract & gallbladder", name: "Cholangiocarcinoma", keyFacts: "Adenocarcinoma of the bile ducts presenting with painless obstructive jaundice; prognosis is poor.", epidemiology: "Uncommon; incidence rises with age.", aetiology: "Primary sclerosing cholangitis, liver flukes, choledochal cysts, chronic biliary inflammation, hepatitis.", pathophysiology: "Malignant transformation of biliary epithelium obstructs bile flow, causing cholestasis and, when intrahepatic, a liver mass.", presentation: "Painless jaundice, pruritus, pale stools and dark urine, weight loss; Courvoisier's sign.", investigations: "Cholestatic LFTs, ultrasound, MRCP, CT, CA 19-9, ERCP with brushings or biopsy.", treatment: "Surgical resection if operable; biliary stenting for relief; palliative chemotherapy; generally poor outcome." },
      { id: "gi_gallbladder_ca", cluster: "Biliary tract & gallbladder", name: "Gallbladder carcinoma", keyFacts: "A rare aggressive adenocarcinoma usually found late; strongly associated with gallstones.", epidemiology: "Rare; commoner in older women.", aetiology: "Gallstones and chronic cholecystitis, a porcelain (calcified) gallbladder, gallbladder polyps, chronic infection.", pathophysiology: "Chronic inflammation drives mucosal dysplasia and adenocarcinoma that invades the liver bed and spreads early.", presentation: "Non-specific right upper quadrant pain mimicking biliary disease; jaundice, weight loss, a mass; often incidental at cholecystectomy.", investigations: "Ultrasound, CT/MRI staging, CA 19-9; frequently diagnosed on cholecystectomy histology.", treatment: "Radical cholecystectomy with liver resection if early; usually palliative as it presents late." },
      { id: "gi_pancreatitis", management: {"def": "A[\"Acute pancreatitis\"]:::start --> B[\"Diagnose: amylase/lipase 3x upper limit\"]:::process\nB --> C[\"Assess severity (Glasgow score, CRP)\"]:::process\nC --> D[\"Supportive: IV fluids, analgesia, oxygen, nutrition\"]:::good\nD --> E{\"Severe or gallstone cause?\"}:::decision\nE -- \"gallstone with obstruction/cholangitis\" --> F[\"Urgent ERCP, cholecystectomy later\"]:::good\nE -- \"severe / necrotising\" --> G[\"HDU/ICU, treat complications\"]:::danger\nA --> H[\"Identify cause (gallstones, alcohol)\"]:::process", "tips": {"A": "Acute inflammation of the pancreas, most often from gallstones or alcohol (GET SMASHED causes): severe epigastric pain radiating to the back, vomiting and tenderness.", "B": "Diagnose with a serum amylase or lipase at least 3 times the upper limit of normal (lipase is more specific) in a compatible picture; CT if the diagnosis is uncertain.", "C": "Assess severity early (modified Glasgow/Imrie score, APACHE II, CRP at 48 hours) - it guides the level of care.", "D": "Management is supportive: aggressive IV fluid resuscitation, analgesia, oxygen, antiemetics and early enteral nutrition; antibiotics only for proven infection.", "E": "Two things change management - the cause (gallstones) and the severity.", "F": "Gallstone pancreatitis with biliary obstruction or cholangitis: urgent ERCP; perform cholecystectomy (ideally during the same admission for mild disease) to prevent recurrence.", "G": "Severe or necrotising pancreatitis: HDU/ICU care and manage complications (necrosis, pseudocyst, organ failure, ARDS) - infected necrosis may need drainage or necrosectomy.", "H": "Establish the cause - ultrasound for gallstones, an alcohol history, and check calcium and triglycerides."}}, cluster: "Pancreas", name: "Acute pancreatitis", keyFacts: "Acute inflammation of the pancreas; gallstones and alcohol cause most cases, graded by the Glasgow score.", epidemiology: "A common surgical emergency with significant mortality in severe disease.", aetiology: "Gallstones and alcohol predominate (mnemonic GET SMASHED); also high triglycerides, ERCP and drugs.", pathophysiology: "Premature activation of pancreatic enzymes causes autodigestion and inflammation and, when severe, necrosis and a systemic inflammatory response.", presentation: "Severe epigastric pain radiating to the back, vomiting; gallstones and alcohol are commonest.", investigations: "Amylase/lipase, U&E, calcium, glucose, LFTs; CT; Glasgow score.", treatment: "IV fluids, analgesia, oxygen, treat cause; manage in HDU if severe." },
      { id: "gi_chronic_pancreatitis", cluster: "Pancreas", name: "Chronic pancreatitis", keyFacts: "Progressive irreversible pancreatic inflammation and fibrosis causing pain and exocrine/endocrine failure; mostly alcohol-related.", epidemiology: "Commoner in middle-aged men, largely driven by alcohol.", aetiology: "Chronic alcohol excess predominates; also cystic fibrosis, hereditary, autoimmune, hypercalcaemia, hypertriglyceridaemia and obstruction.", pathophysiology: "Repeated inflammation causes fibrosis, ductal strictures and calcification, destroying acinar and islet tissue, hence malabsorption and diabetes.", presentation: "Recurrent epigastric pain radiating to the back, eased by leaning forward; weight loss, steatorrhoea, diabetes.", investigations: "CT/MRCP (calcification, ductal change), faecal elastase (low), glucose/HbA1c; amylase often normal.", treatment: "Alcohol and smoking cessation, analgesia, pancreatic enzyme replacement, fat-soluble vitamins, diabetes care; coeliac plexus block or surgery for pain." },
      { id: "gi_pancreatic_ca", cluster: "Pancreas", name: "Pancreatic cancer", keyFacts: "Usually ductal adenocarcinoma of the pancreatic head; presents late with painless obstructive jaundice and poor prognosis.", epidemiology: "Commoner with age; one of the deadliest cancers.", aetiology: "Smoking, chronic pancreatitis, diabetes, obesity, family history and hereditary syndromes (BRCA2, Peutz-Jeghers).", pathophysiology: "Adenocarcinoma, usually of the head, obstructs the common bile duct and invades locally, metastasising early.", presentation: "Painless obstructive jaundice, weight loss, epigastric/back pain, new-onset diabetes; Courvoisier's law, Trousseau's migratory thrombophlebitis.", investigations: "CT pancreas, CA 19-9, endoscopic ultrasound with biopsy, MRCP/ERCP.", treatment: "Whipple's resection if operable (a minority); chemotherapy; biliary stenting and palliative care for most." },
      { id: "gi_carcinoid_tumour", management: { def: "A[\"Suspected neuroendocrine tumour\"]:::start --> B[\"Chromogranin A and 24-hour urinary 5-HIAA\"]:::process\nB --> C[\"Contrast CT or MRI to locate and stage\"]:::process\nC --> D[\"68Ga-DOTATATE PET-CT for somatostatin receptor status\"]:::process\nD --> E[\"Histology with Ki-67 and mitotic count - grade G1, G2 or G3\"]:::process\nE --> F[\"Discuss at the neuroendocrine tumour MDT\"]:::process\nF --> G{\"Localised and resectable\"}:::decision\nG -- \"yes\" --> H[\"Surgical resection - the only curative treatment\"]:::good\nH --> I[\"Extent by site and size - appendicectomy alone under 1 cm, right hemicolectomy over 2 cm\"]:::good\nG -- \"no - metastatic or unresectable\" --> J[\"Somatostatin analogue - octreotide LAR or lanreotide\"]:::good\nJ --> K{\"Progressive disease\"}:::decision\nK -- \"yes\" --> L[\"PRRT with lutetium-177 DOTATATE if receptor-positive\"]:::good\nL --> M[\"Everolimus or liver-directed therapy on further progression\"]:::warn\nK -- \"no\" --> N[\"Continue, with interval imaging and markers\"]:::good\nI --> O[\"Lifelong surveillance - chromogranin A, 5-HIAA and imaging\"]:::good\nM --> O\nN --> O", tips: { A: "Carcinoid tumours are well-differentiated neuroendocrine tumours of enterochromaffin cell origin. Most are found incidentally - at appendicectomy, at endoscopy, or on imaging done for something else. Others present late with vague abdominal pain or intermittent obstruction.", B: "Chromogranin A is the general neuroendocrine marker and is used for follow-up rather than diagnosis - it is falsely raised by proton pump inhibitors, renal impairment and atrophic gastritis, so stop PPIs before testing. Urinary 5-HIAA is the serotonin metabolite and is most useful in midgut tumours.", C: "Cross-sectional imaging locates the primary, defines the mesenteric mass and desmoplastic reaction, and looks for liver metastases. Small bowel primaries are often tiny and hard to see - the mesenteric nodal mass is frequently more obvious than the tumour itself.", D: "68Ga-DOTATATE PET-CT is the current somatostatin receptor imaging standard and has REPLACED octreotide (Octreoscan) scintigraphy. It both stages the disease and establishes receptor positivity, which is what determines eligibility for somatostatin analogues and for radionuclide therapy.", E: "Grade drives everything. WHO grading uses the Ki-67 proliferation index and mitotic count: G1 under 3%, G2 3 to 20%, G3 above 20%. Well-differentiated G1 and G2 tumours behave indolently; poorly differentiated neuroendocrine CARCINOMA is a different disease treated like small cell carcinoma with platinum-based chemotherapy.", F: "These are rare tumours with complex management, and outcomes are better in specialist centres - every case should go to a neuroendocrine tumour MDT.", G: "Resectability is the pivot. Even with limited metastatic disease, resecting the primary is often still worthwhile to prevent obstruction from the mesenteric desmoplastic reaction.", H: "Surgery is the only curative option. For midgut tumours this means segmental small bowel resection with mesenteric lymphadenectomy.", I: "The appendiceal size rule is heavily examined: under 1 cm, appendicectomy alone is sufficient; over 2 cm, or with mesoappendiceal invasion or positive margins, proceed to right hemicolectomy. Between 1 and 2 cm the decision is individualised. Rectal NETs under 1 cm are usually removed endoscopically.", J: "Somatostatin analogues are not only for symptom control - they have a proven ANTIPROLIFERATIVE effect that slows tumour progression (the PROMID and CLARINET trials), so they are used even in non-functioning tumours.", K: "Reassess with interval imaging and markers; progression is what triggers escalation.", L: "Peptide receptor radionuclide therapy delivers lutetium-177 bound to a somatostatin analogue directly to receptor-positive tumour cells. It is the standard second-line option for progressive receptor-positive disease, and the NETTER-2 trial supports using it earlier in higher-grade tumours.", M: "Later lines include everolimus (an mTOR inhibitor), and liver-directed treatment such as hepatic artery embolisation or radiofrequency ablation where disease is liver-dominant.", N: "Stable disease on a somatostatin analogue is a good outcome - these tumours are often indolent and are managed over years.", O: "Recurrence can occur very late, so surveillance is lifelong, with chromogranin A, urinary 5-HIAA and cross-sectional imaging, escalating to 68Ga-DOTATATE PET-CT when the markers rise." }, source: "ENETS / UKINETS" }, complications: "Small bowel obstruction and ischaemia from the mesenteric desmoplastic reaction\nLiver metastases - and with them, carcinoid syndrome\nCarcinoid crisis, classically precipitated by surgery or tumour handling\nLate recurrence, which is why surveillance is lifelong", cluster: "Neuroendocrine tumours", name: "Carcinoid tumours", keyFacts: "Well-differentiated neuroendocrine tumours of enterochromaffin cell origin, most often in the appendix, small bowel or rectum; usually indolent but malignant.", epidemiology: "Incidence around 5 per 100,000 per year and rising, largely through incidental detection. The appendix is the commonest site overall (usually found at appendicectomy); the terminal ileum is the commonest site to metastasise and cause carcinoid syndrome.", aetiology: "Mostly sporadic. Associated with MEN1 (gastric and pancreatic neuroendocrine tumours) and neurofibromatosis type 1 (duodenal); chronic atrophic gastritis predisposes to type 1 gastric tumours.", pathophysiology: "Arise from enterochromaffin (Kulchitsky) cells of the diffuse neuroendocrine system and secrete serotonin and other vasoactive amines. Graded by Ki-67 and mitotic count into G1, G2 and G3. Midgut tumours provoke an intense desmoplastic mesenteric reaction that tethers bowel and causes obstruction or ischaemia.", presentation: "Often asymptomatic and found incidentally. Otherwise vague abdominal pain, intermittent or subacute obstruction from mesenteric fibrosis, bowel ischaemia, or a small-bowel mass. Flushing and diarrhoea appear only once there are liver metastases.", investigations: "Chromogranin A (stop PPIs first) and 24-hour urinary 5-HIAA; contrast CT or MRI; 68Ga-DOTATATE PET-CT for somatostatin receptor status, which has replaced octreotide scintigraphy; endoscopy and EUS for gastric, duodenal and rectal lesions; histology with Ki-67 for grade.", treatment: "Surgical resection is the only cure - appendicectomy alone if under 1 cm, right hemicolectomy if over 2 cm or with adverse features. Somatostatin analogues (octreotide LAR, lanreotide) for symptom and antiproliferative control. Peptide receptor radionuclide therapy with lutetium-177 DOTATATE for progressive receptor-positive disease; then everolimus or liver-directed therapy. Manage through a neuroendocrine tumour MDT with lifelong surveillance." },
      { id: "gi_carcinoid_syndrome", management: { def: "A[\"Episodic flushing, secretory diarrhoea and wheeze\"]:::start --> B[\"24-hour urinary 5-HIAA and chromogranin A\"]:::process\nB --> C{\"Markers raised\"}:::decision\nC -- \"no\" --> D[\"Consider other causes of flushing - menopause, mastocytosis, phaeochromocytoma, medullary thyroid cancer\"]:::good\nC -- \"yes\" --> E[\"Locate the tumour - CT or MRI plus 68Ga-DOTATATE PET-CT\"]:::process\nE --> F[\"LOOK FOR LIVER METASTASES - the syndrome means mediators are bypassing the liver\"]:::process\nF --> G[\"Echocardiogram and NT-proBNP for carcinoid heart disease\"]:::process\nG --> H[\"Somatostatin analogue - octreotide LAR or lanreotide, first-line for symptoms\"]:::good\nH --> I[\"Avoid triggers - alcohol, stress, tyramine-rich foods\"]:::warn\nI --> J{\"Diarrhoea still uncontrolled\"}:::decision\nJ -- \"yes\" --> K[\"Add telotristat ethyl - inhibits tryptophan hydroxylase\"]:::good\nJ -- \"no\" --> L[\"Continue, and treat the underlying tumour\"]:::good\nK --> L\nL --> M[\"Niacin supplementation - tryptophan diverted to serotonin causes pellagra\"]:::warn\nM --> N{\"Carcinoid heart disease on echo\"}:::decision\nN -- \"yes\" --> O[\"Cardiology referral for valve surgery - usually tricuspid and pulmonary\"]:::danger\nN -- \"no\" --> P[\"Interval echocardiographic surveillance\"]:::good", tips: { A: "The triad is dry FLUSHING of the face and neck (dry, unlike the sweating of menopause), SECRETORY DIARRHOEA and BRONCHOSPASM. Attacks are paroxysmal and provoked by alcohol, stress, exercise and tyramine-rich foods.", B: "24-hour urinary 5-HIAA is the serotonin metabolite and is the key test. Warn the patient to avoid serotonin-rich foods (bananas, avocado, walnuts, pineapple, aubergine) and certain drugs for 24 to 48 hours beforehand, or the result is falsely raised.", C: "Raised markers with the right clinical picture make the diagnosis - but the syndrome is rare and the differential for flushing is much commoner.", D: "Work through the alternatives: the menopause, mastocytosis, phaeochromocytoma, medullary thyroid carcinoma, VIPoma, alcohol and drug causes, and anxiety.", E: "The primary is usually a midgut (terminal ileal) neuroendocrine tumour - see the Carcinoid tumours entry for the full staging and treatment pathway.", F: "THIS IS THE KEY CONCEPT. Mediators from a gut tumour drain into the portal vein and are inactivated by the liver, so a gut primary alone does NOT cause the syndrome. Carcinoid syndrome therefore implies either LIVER METASTASES or a primary that drains systemically instead - bronchial or ovarian.", G: "Carcinoid heart disease affects around half of those with the syndrome and is a major cause of death. Chronic serotonin exposure causes fibrous endocardial plaques on the RIGHT side of the heart, giving TRICUSPID REGURGITATION and PULMONARY STENOSIS - the left side is spared because the lungs inactivate the mediators. NT-proBNP is the screening test, with echocardiography to confirm.", H: "Somatostatin analogues are first-line and control flushing and diarrhoea in most patients. They also treat the tumour (see the Carcinoid tumours entry). CARCINOID CRISIS is the emergency to know - profound flushing, bronchospasm and haemodynamic collapse, classically precipitated by anaesthesia, surgery or tumour handling. Treat with INTRAVENOUS OCTREOTIDE, and AVOID catecholamines such as adrenaline, which worsen it by stimulating further mediator release. Give prophylactic octreotide before any procedure.", I: "Trigger avoidance is a genuinely useful non-drug measure and worth spending time on with the patient.", J: "Diarrhoea is often the most disabling symptom and the one most likely to persist on a somatostatin analogue. Exclude other contributors first - bile acid malabsorption after ileal resection, bacterial overgrowth, and pancreatic exocrine insufficiency caused by the somatostatin analogue itself.", K: "Telotristat ethyl inhibits tryptophan hydroxylase, the rate-limiting enzyme in serotonin synthesis, so it reduces serotonin production at source. It is ADDED to a somatostatin analogue rather than replacing it, for diarrhoea that remains inadequately controlled.", L: "Symptom control and antitumour treatment run together - shrinking or debulking the tumour, including liver-directed therapy, often improves the syndrome.", M: "Tryptophan is diverted into serotonin synthesis, leaving too little for niacin production. The result is PELLAGRA - dermatitis, diarrhoea and dementia - which is easily missed and easily prevented with supplementation.", N: "Echocardiography drives the cardiac decision. Deterioration is often insidious, so surveillance matters even when the syndrome is well controlled.", O: "Valve replacement is the only effective treatment for established carcinoid heart disease and should be considered before right ventricular function deteriorates. It needs careful perioperative octreotide cover to prevent carcinoid crisis.", P: "Repeat echocardiography periodically, guided by symptoms and NT-proBNP." }, source: "ENETS / UKINETS" }, complications: "Carcinoid heart disease - right-sided fibrosis giving TRICUSPID REGURGITATION and PULMONARY STENOSIS; the left heart is spared\nCarcinoid crisis - flushing, bronchospasm and cardiovascular collapse, precipitated by anaesthesia, surgery or tumour handling\nPellagra from tryptophan diversion - dermatitis, diarrhoea, dementia\nMalnutrition and weight loss from chronic secretory diarrhoea\nMesenteric and retroperitoneal fibrosis", cluster: "Neuroendocrine tumours", name: "Carcinoid syndrome", keyFacts: "Flushing, diarrhoea and bronchospasm caused by vasoactive mediators from a neuroendocrine tumour escaping hepatic first-pass metabolism - which in practice means liver metastases.", epidemiology: "Develops in roughly 20 to 30% of people with midgut neuroendocrine tumours, essentially always once liver metastases are present.", aetiology: "Serotonin, histamine, tachykinins and prostaglandins reaching the systemic circulation - from liver metastases of a midgut tumour, or from a primary that drains systemically rather than portally (bronchial, ovarian).", pathophysiology: "Mediators from a gut tumour normally drain via the portal vein and are inactivated by the liver, so a gut primary alone causes no syndrome. Liver metastases or a non-portal primary bypass that. Chronic serotonin exposure causes right-sided endocardial fibrosis, and tryptophan diversion into serotonin synthesis leaves too little for niacin, causing pellagra.", presentation: "Paroxysmal DRY flushing of the face and neck, secretory DIARRHOEA with cramps, and BRONCHOSPASM; later right-sided heart failure. Provoked by alcohol, stress, exercise and tyramine-rich foods.", investigations: "24-hour urinary 5-HIAA (avoid serotonin-rich foods and interfering drugs beforehand) and chromogranin A; CT or MRI with 68Ga-DOTATATE PET-CT to find the primary and liver metastases; NT-proBNP and echocardiogram for carcinoid heart disease.", treatment: "Somatostatin analogues (octreotide, lanreotide) first-line for symptom control; telotristat ethyl added for diarrhoea that remains uncontrolled; loperamide; trigger avoidance; niacin supplementation to prevent pellagra; treat the underlying tumour. Valve surgery for carcinoid heart disease. CARCINOID CRISIS: IV octreotide and AVOID catecholamines; give prophylactic octreotide before surgery or anaesthesia." },
      { id: "gi_hyperlipidaemia", management: {"def": "A[\"Raised cholesterol / CVD risk assessment\"]:::start --> B{\"Established atherosclerotic CVD?\"}:::decision\nB -- \"yes (secondary prevention)\" --> C[\"Atorvastatin 80 mg\"]:::good\nB -- \"no\" --> D[\"Estimate 10-year risk with QRISK3\"]:::process\nD --> E{\"QRISK 10%+ or T1DM/CKD/FH?\"}:::decision\nE -- \"yes\" --> F[\"Offer atorvastatin 20 mg + lifestyle\"]:::good\nE -- \"no\" --> G[\"Lifestyle advice, reassess risk\"]:::good\nC --> H[\"Recheck lipids at 2-3 months\"]:::process\nF --> H\nH --> I{\"Non-HDL cholesterol fallen 40%+?\"}:::decision\nI -- \"yes\" --> J[\"Continue, annual review\"]:::good\nI -- \"no\" --> K[\"Check adherence, uptitrate, add ezetimibe\"]:::warn\nK --> L{\"Still not at target?\"}:::decision\nL -- \"no\" --> J\nL -- \"yes\" --> M[\"Add PCSK9 inhibitor / inclisiran / bempedoic acid\"]:::warn", "tips": {"A": "Hypercholesterolaemia is usually found on cardiovascular risk screening or a routine lipid profile; the pathway depends on whether the person needs primary or secondary prevention (NICE NG238).", "B": "Anyone with established atherosclerotic cardiovascular disease - angina, myocardial infarction, stroke or TIA, or peripheral arterial disease - needs secondary prevention regardless of the baseline cholesterol.", "C": "Secondary prevention: offer high-intensity atorvastatin 80 mg daily (use a lower dose if there are drug interactions, a high risk of adverse effects, or patient preference).", "D": "For primary prevention, estimate the 10-year cardiovascular risk with QRISK3 (validated up to and including age 84).", "E": "Offer a statin if QRISK3 is 10% or more; also treat type 1 diabetes, chronic kidney disease and suspected familial hypercholesterolaemia on their own criteria, irrespective of QRISK.", "F": "Primary prevention: offer atorvastatin 20 mg daily alongside lifestyle change (diet, physical activity, weight, alcohol and smoking).", "G": "Below the treatment threshold: give lifestyle advice and reassess cardiovascular risk periodically.", "H": "Recheck a full lipid profile (including non-HDL cholesterol) at 2 to 3 months.", "I": "Aim for a greater than 40% reduction in non-HDL cholesterol; if it is not achieved, address adherence, diet and lifestyle first.", "J": "Once at target, continue the statin with an annual medication review and lipid check.", "K": "If the response is inadequate despite good adherence, uptitrate the statin and add ezetimibe.", "L": "Reassess whether non-HDL cholesterol is now adequately controlled.", "M": "For persistent inadequate control or statin intolerance, NICE options include a PCSK9 inhibitor (alirocumab or evolocumab), inclisiran, or bempedoic acid, usually with specialist input."}, "source": "NICE"}, cluster: "Nutrition & metabolic", name: "Hypercholesterolaemia", keyFacts: "Raised low-density lipoprotein (LDL) cholesterol, the principal modifiable driver of atherosclerotic cardiovascular disease; managed with lifestyle and statins to lower cardiovascular risk.", epidemiology: "Very common; usually detected on routine cardiovascular risk screening or after a vascular event. Familial hypercholesterolaemia affects about 1 in 250 people and is greatly underdiagnosed.", aetiology: "Primary - polygenic, or monogenic familial hypercholesterolaemia (autosomal dominant LDL-receptor, APOB or PCSK9 mutations). Secondary - diet, obesity, type 2 diabetes, hypothyroidism, cholestasis, nephrotic syndrome and drugs (thiazides, corticosteroids).", pathophysiology: "Excess LDL cholesterol enters the arterial wall and is oxidised, driving foam-cell formation and atherosclerotic plaque; plaque progression and rupture cause angina, myocardial infarction, stroke and peripheral arterial disease.", presentation: "Usually asymptomatic. Signs pointing to familial hypercholesterolaemia are tendon xanthomata (Achilles and finger extensors), xanthelasma and premature corneal arcus (under 45 years), with a personal or family history of premature coronary disease.", investigations: "Full lipid profile (total, LDL, HDL and non-HDL cholesterol; a non-fasting sample is acceptable); QRISK3 for primary prevention; HbA1c, thyroid function, LFTs, renal function and baseline creatine kinase before starting a statin; assess for familial hypercholesterolaemia (Simon Broome or Dutch criteria) if LDL is very high or disease is premature.", treatment: "Lifestyle and diet; atorvastatin 20 mg for primary prevention (QRISK3 of 10% or more) and atorvastatin 80 mg for secondary prevention, aiming for a greater than 40% fall in non-HDL cholesterol; add ezetimibe, then a PCSK9 inhibitor, inclisiran or bempedoic acid if targets are not met; refer suspected familial hypercholesterolaemia to a lipid specialist." },
      { id: "gi_hypertriglyceridaemia", management: {"def": "A[\"Raised triglycerides on fasting sample\"]:::start --> B{\"Fasting triglyceride level\"}:::decision\nB -- \"above 20 mmol/L\" --> C[\"Urgent specialist referral: pancreatitis risk\"]:::danger\nB -- \"10-20 mmol/L\" --> D[\"Repeat in 5-14 days, seek secondary causes\"]:::warn\nB -- \"under 10 mmol/L\" --> E[\"Assess within overall cardiovascular risk\"]:::process\nC --> F[\"Treat secondary causes, lifestyle, fibrate + omega-3\"]:::good\nD --> F\nE --> G[\"Manage secondary causes and lifestyle\"]:::good\nG --> H{\"Persistent raised TG with high CVD risk?\"}:::decision\nH -- \"yes\" --> I[\"Statin, add fibrate/omega-3 if very high\"]:::good\nH -- \"no\" --> J[\"Lifestyle, periodic review\"]:::good", "tips": {"A": "Measure triglycerides fasting where possible, as they rise after food and alcohol; confirm a raised result on a repeat fasting sample.", "B": "The triglyceride level guides urgency, because very high values carry a risk of acute pancreatitis rather than only cardiovascular disease.", "C": "A triglyceride concentration above 20 mmol/L (not explained by excess alcohol or poor glycaemic control) warrants urgent specialist referral because of the high risk of acute pancreatitis.", "D": "For triglycerides of 10 to 20 mmol/L, repeat the measurement within 5 to 14 days, actively seek and treat secondary causes, and consider specialist referral - a pancreatitis risk remains.", "E": "Triglycerides below 10 mmol/L are managed as part of overall cardiovascular risk rather than as an isolated problem.", "F": "Reduce pancreatitis risk by aggressively treating secondary causes (alcohol, glycaemic control, weight and offending drugs), dietary change, and a fibrate such as fenofibrate, often with omega-3 fatty acids.", "G": "Address secondary causes - obesity, diabetes, alcohol, a high refined-carbohydrate diet, hypothyroidism and culprit drugs - and give lifestyle advice.", "H": "Reassess: persistently raised triglycerides in someone at high cardiovascular risk need drug treatment.", "I": "A statin is first-line for cardiovascular risk in mixed dyslipidaemia; a fibrate (fenofibrate is preferred with a statin) or high-dose omega-3 fatty acids are added mainly to lower pancreatitis risk when triglycerides stay very high.", "J": "Where cardiovascular risk is low and triglycerides are only modestly raised, continue lifestyle measures with periodic review."}, "source": "NICE CKS"}, cluster: "Nutrition & metabolic", name: "Hypertriglyceridaemia", keyFacts: "Raised serum triglycerides; a contributor to atherosclerotic cardiovascular risk and, when very high, the leading metabolic cause of acute pancreatitis.", epidemiology: "Common, usually as part of a mixed dyslipidaemia with the metabolic syndrome; severe hypertriglyceridaemia is much rarer and often has a genetic basis.", aetiology: "Mostly secondary - obesity, type 2 diabetes and insulin resistance, excess alcohol, a high refined-carbohydrate diet, hypothyroidism, chronic kidney or liver disease, pregnancy and drugs (thiazides, corticosteroids, oestrogens, some antiretrovirals). Primary causes include familial hypertriglyceridaemia and familial chylomicronaemia.", pathophysiology: "Overproduction or reduced clearance of triglyceride-rich lipoproteins (VLDL and chylomicrons); grossly raised triglycerides (usually above 10 mmol/L) can precipitate acute pancreatitis, and the pattern is linked to atherogenic small dense LDL and a low HDL.", presentation: "Usually asymptomatic. Very high levels cause eruptive xanthomata, lipaemia retinalis, hepatosplenomegaly and episodes of acute pancreatitis (severe epigastric pain and vomiting); the fasting serum may look milky (lipaemic).", investigations: "Fasting lipid profile (triglycerides rise after food and alcohol, so confirm on a fasting sample); screen for secondary causes with HbA1c, thyroid and renal function, LFTs and an alcohol history; check amylase or lipase if pancreatitis is suspected.", treatment: "Treat secondary causes and intensify lifestyle (weight loss, alcohol reduction, less refined carbohydrate, oily fish) and optimise diabetes. A statin for accompanying cardiovascular risk; for very high triglycerides (pancreatitis risk) a fibrate such as fenofibrate first-line, with omega-3 fatty acids; refer to a lipid specialist if above 20 mmol/L or refractory." },
    ],
  },
  {
    id: "endocrinology",
    name: "Endocrinology & Metabolic",
    icon: "🦋",
    conditions: [
      { id: "endo_t1dm", management: {"def": "A[\"Type 1 diabetes diagnosed\"]:::start --> B[\"Basal-bolus insulin: multiple daily injections or an insulin pump\"]:::good\nB --> C[\"Structured education (DAFNE) and carbohydrate counting\"]:::process\nC --> D[\"Offer CGM to ALL adults: rtCGM or isCGM by preference\"]:::good\nD --> E{\"HbA1c 58 or above, or disabling hypoglycaemia, despite pump or CGM?\"}:::decision\nE -- \"yes\" --> F[\"Offer a hybrid closed loop system\"]:::good\nE -- \"no\" --> G[\"Individualised target: aim HbA1c 48 or below, fasting 5 to 7\"]:::good\nF --> G\nG --> H[\"Annual screening: eyes, feet, kidneys, CVD risk\"]:::process\nB --> I[\"Sick-day rules: NEVER omit insulin, check ketones\"]:::warn", "tips": {"A": "Type 1 diabetes is confirmed clinically; measure C-peptide and islet autoantibodies only if the diagnosis is uncertain. Treatment is lifelong insulin plus structured self-management support (NICE NG17).", "B": "Offer a basal-bolus regimen as first choice: twice-daily insulin detemir, or once-daily degludec or glargine, plus a rapid-acting analogue with meals. Continuous subcutaneous insulin infusion (a pump) is an option where multiple daily injections are not tolerated or targets are not met. NOTE (NICE amendment, February 2026): Levemir (insulin detemir) Penfill and FlexPen are being discontinued, with supply expected to end around December 2026, so people on detemir need a planned switch.", "C": "Offer a structured education programme such as DAFNE about 6 to 12 months after diagnosis, with carbohydrate counting from the outset. Education is as important as the insulin regimen itself.", "D": "Since the 2022 update, NICE recommends offering continuous glucose monitoring to ALL adults with type 1 diabetes — either real-time (rtCGM) or intermittently scanned (isCGM), chosen on the person's preferences and needs. CGM is now the default rather than an add-on; capillary blood glucose testing continues alongside it as a backup and for calibration or confirmation.", "E": "Reassess after optimising insulin, education and monitoring. The threshold for escalating technology is an HbA1c of 58 mmol/mol or above, OR disabling hypoglycaemia, despite best possible management with a pump, rtCGM or isCGM.", "F": "Hybrid closed loop systems (an insulin pump algorithmically driven by CGM, sometimes called the artificial pancreas) are NICE-recommended for those meeting the threshold above. They must be started by a specialist team with expertise in their use.", "G": "Aim for an HbA1c of 48 mmol/mol (6.5%) or lower to minimise vascular complications, but agree an INDIVIDUALISED target considering daily activities, hypoglycaemia history, comorbidities and occupation. Advise a fasting or on-waking glucose of 5 to 7 mmol/L, 4 to 7 mmol/L before meals at other times, and at least 5 mmol/L when driving.", "H": "Arrange annual review with retinal screening, foot assessment, urinary albumin-to-creatinine ratio with eGFR, blood pressure and lipids, plus thyroid function at diagnosis and screening for coeliac disease.", "I": "Give explicit sick-day rules: NEVER stop insulin during illness, increase glucose and ketone monitoring, and seek urgent help if ketones rise — omitting insulin is the commonest precipitant of diabetic ketoacidosis. Ensure the person has ketone testing strips at home."}, "source": "NICE NG17"}, cluster: "Diabetes", name: "Type 1 diabetes", keyFacts: "Autoimmune destruction of pancreatic beta cells causing absolute insulin deficiency; needs lifelong insulin.", epidemiology: "Usually presents in childhood or early adulthood, with rising incidence.", aetiology: "Autoimmune (anti-GAD, islet-cell antibodies) in genetically susceptible people, possibly triggered by viral infection.", pathophysiology: "T-cell-mediated destruction of beta cells abolishes insulin production, causing hyperglycaemia and, untreated, ketoacidosis.", presentation: "Young patient with polyuria, polydipsia, weight loss, may present in DKA.", investigations: "Glucose, ketones, HbA1c, autoantibodies, C-peptide.", treatment: "Basal-bolus insulin, carbohydrate counting, structured education, screen for complications." },
      { id: "endo_t2dm", management: {"def": "A[\"Type 2 diabetes: reinforce diet and lifestyle at every stage\"]:::start --> B[\"Assess CV status and risk, renal function, frailty and obesity\"]:::process\nB --> C{\"Which comorbidity track? If several, agree the priority\"}:::decision\nB --> T[\"Symptomatic hyperglycaemia at any stage: consider insulin or sulfonylurea\"]:::danger\nC -- \"ASCVD\" --> D[\"Offer TRIPLE first-line: metformin M/R + SGLT2i + s/c semaglutide\"]:::danger\nC -- \"early-onset under 40\" --> E[\"Consider TRIPLE: metformin M/R + SGLT2i + GLP-1 RA or tirzepatide\"]:::warn\nC -- \"chronic kidney disease\" --> F{\"eGFR level?\"}:::decision\nC -- \"frailty\" --> G[\"Metformin M/R, add SGLT2i only if no risk of harm\"]:::warn\nC -- \"none, obesity or heart failure\" --> H[\"Offer metformin M/R + SGLT2 inhibitor\"]:::good\nF -- \"above 30\" --> H\nF -- \"20 to 30\" --> I[\"Dapagliflozin or empagliflozin plus DPP-4 inhibitor\"]:::good\nF -- \"under 20\" --> J[\"Consider DPP-4 inhibitor\"]:::good\nD --> K{\"HbA1c above individualised target?\"}:::decision\nE --> K\nG --> K\nH --> K\nI --> K\nJ --> K\nK -- \"no\" --> L[\"Continue and review: keep SGLT2i for CV and renal benefit\"]:::good\nK -- \"yes\" --> M{\"SECOND-LINE: choose by comorbidity\"}:::decision\nM -- \"obesity\" --> N[\"Add GLP-1 RA or tirzepatide\"]:::good\nM -- \"early-onset under 40\" --> N\nM -- \"now has ASCVD\" --> O[\"Add s/c semaglutide up to 1 mg weekly\"]:::good\nM -- \"no relevant comorbidity\" --> P[\"Add DPP-4 inhibitor\"]:::good\nM -- \"frailty\" --> Q[\"Prefer DPP-4 inhibitor: avoid hypos and falls\"]:::warn\nN --> R{\"Individualised target now met?\"}:::decision\nO --> R\nP --> R\nQ --> R\nR -- \"yes\" --> L\nR -- \"no\" --> S[\"Add sulfonylurea or pioglitazone or insulin\"]:::warn\nS --> U[\"Insulin: basal once or twice daily, add prandial if HbA1c 75 or above\"]:::good", "tips": {"A": "Type 2 diabetes is diagnosed on an HbA1c of 48 mmol/mol (6.5%) or above. NICE NG28 was substantially rewritten in February 2026: the emphasis moved from glucose-lowering alone to early cardio-renal protection, with individualised glycaemic targets and shared decision-making. Reinforce diet, behaviour change and weight optimisation at every stage.", "B": "Before choosing drugs, assess four things: cardiovascular status and future risk (including heart failure), renal function, clinically significant frailty, and obesity. These determine which of the seven treatment tracks the person follows. Give clear sick day rules, and follow MHRA advice on ketone monitoring with SGLT2 inhibitors.", "C": "The 2026 algorithm has SEVEN tracks: no relevant comorbidities, obesity, chronic kidney disease, early-onset type 2 diabetes, heart failure, atherosclerotic cardiovascular disease (ASCVD), and frailty. If more than one comorbidity is present, discuss with the person which to prioritise.", "T": "At any stage, if the person is symptomatically hyperglycaemic, consider insulin or a sulfonylurea to gain rapid control, then review once blood glucose is back in the target range.", "D": "Established ASCVD is the one group offered TRIPLE therapy from the outset: metformin M/R, an SGLT2 inhibitor, and subcutaneous semaglutide titrated up to 1 mg weekly. Start drugs sequentially, checking tolerability before adding the next. This has the best cost-effectiveness evidence of the GLP-1-based options in ASCVD.", "E": "For early-onset disease (onset under 40 years), CONSIDER triple therapy first-line: metformin M/R, an SGLT2 inhibitor, plus either a GLP-1 receptor agonist or tirzepatide. There is no trial evidence specific to this group, but they are treated aggressively because of their very high lifetime cardiovascular risk.", "F": "In chronic kidney disease the entry point depends on eGFR, because SGLT2 inhibitors lose their glucose-lowering effect below about 45 mL/min/1.73m2 even though their renal and cardiovascular benefits persist.", "G": "In clinically significant frailty, offer metformin M/R and add an SGLT2 inhibitor ONLY if the degree of frailty does not place the person at risk of adverse events such as hypotension. If they are at risk, use a DPP-4 inhibitor instead. Aim for the smallest number of drugs at the lowest effective dose.", "H": "This is the biggest change of 2026: metformin M/R plus an SGLT2 inhibitor is now offered as DUAL first-line therapy to everyone, even with no other comorbidity. Titrate metformin to the maximum tolerated dose first, then add the SGLT2 inhibitor. If metformin is contraindicated or not tolerated, give the SGLT2 inhibitor alone. Modified-release metformin is now preferred over standard-release (equally effective, fewer gastrointestinal effects, better adherence); use standard-release if tablets need crushing or a liquid is needed. Reduce metformin to 1 g daily if eGFR is under 45 and do not initiate it below 30.", "I": "With an eGFR of 20 to 30, offer dapagliflozin or empagliflozin (the two with evidence at this level of function) together with a DPP-4 inhibitor, since the SGLT2 inhibitor is being used for renal and cardiovascular protection rather than glucose lowering.", "J": "Below an eGFR of 20, consider a DPP-4 inhibitor. If that is contraindicated, not tolerated or ineffective, consider pioglitazone or insulin instead.", "K": "Targets are individualised in the 2026 guidance rather than fixed. Review against the agreed target, and remember that glucose is no longer the only driver of treatment decisions.", "L": "If the target is met, consider continuing the medicines that helped achieve it. Crucially, CONTINUE the SGLT2 inhibitor for its cardiovascular and renal benefits even if it is not contributing to glycaemic control. Stop a GLP-1 RA or tirzepatide if the person becomes underweight (BMI under 18.5) or if it is neither helping reach targets nor being given for cardiovascular benefit.", "M": "This is the step that changed most: the SECOND agent is now chosen by comorbidity rather than by default. GLP-1-based therapy comes earlier and with fewer restrictions than in the old guidance, and DPP-4 inhibitors are deprioritised wherever semaglutide, a GLP-1 RA or tirzepatide is recommended.", "N": "For obesity, CONSIDER a GLP-1 receptor agonist or tirzepatide as the FIRST additional therapy once initial treatment has run for at least 3 months without reaching target. The same applies in early-onset disease if not already on one. Recommended GLP-1 RAs as of February 2026 are liraglutide, dulaglutide, oral semaglutide at any licensed dose, and subcutaneous semaglutide up to 1 mg. NEVER combine a GLP-1 RA or tirzepatide with a DPP-4 inhibitor. If GLP-1-based therapy is contraindicated or not tolerated, use a DPP-4 inhibitor instead.", "O": "If ASCVD develops after treatment has started, move to triple therapy by adding subcutaneous semaglutide up to 1 mg weekly. If further treatment is then needed, add a sulfonylurea, pioglitazone or insulin.", "P": "With no relevant comorbidity, the second agent is a DPP-4 inhibitor. Do NOT add one if the person is already taking a GLP-1 RA or tirzepatide. If the DPP-4 inhibitor is contraindicated or not tolerated, use a sulfonylurea (only if eGFR is above 30) or pioglitazone (never in heart failure) or insulin.", "Q": "In frailty a DPP-4 inhibitor is generally preferred, because sulfonylureas and insulin carry a risk of hypoglycaemia and falls, and pioglitazone increases fracture risk. Review the whole treatment plan and aim for the fewest drugs at the lowest effective doses.", "R": "Reassess against the individualised target after each addition, allowing enough time for the drug to work.", "S": "Further escalation is a sulfonylurea (only if eGFR is above 30), or pioglitazone (contraindicated in heart failure, and note the fracture risk), or insulin, chosen according to circumstances. In heart failure the SGLT2 inhibitor is continued and pioglitazone must be avoided.", "U": "Start insulin as once-daily or twice-daily basal insulin, with support from a professional trained in insulin therapy. Consider combining basal with short- or rapid-acting (or pre-mixed) insulin if HbA1c is 75 mmol/mol or above. Continue the medicines that give cardiorenal benefit and weight loss. Where several basal insulins are equally suitable, use the least expensive, and consider a biosimilar for new starts."}, "source": "NICE NG28 (Feb 2026)"}, cluster: "Diabetes", name: "Type 2 diabetes", keyFacts: "Insulin resistance with relative deficiency causing hyperglycaemia; strongly linked to obesity.", epidemiology: "Very common and increasing; commoner with age, obesity and South Asian ethnicity.", aetiology: "Obesity, inactivity, genetics and ethnicity, as part of the metabolic syndrome.", pathophysiology: "Peripheral insulin resistance with progressive beta-cell failure raises blood glucose and drives micro- and macrovascular complications.", presentation: "Often asymptomatic; thirst, fatigue, recurrent infections, found on screening.", investigations: "HbA1c (≥48 mmol/mol), fasting glucose; annual retinal, foot and renal checks.", treatment: "Individualise targets and reinforce diet, weight and lifestyle at every stage. NICE NG28 (updated February 2026): offer metformin modified-release plus an SGLT2 inhibitor as dual therapy first-line to everyone, and triple therapy with subcutaneous semaglutide if established atherosclerotic cardiovascular disease. Second-line choice is driven by comorbidity: a GLP-1 receptor agonist or tirzepatide for obesity or early-onset disease, a DPP-4 inhibitor if no relevant comorbidity (never alongside a GLP-1 agent), then a sulfonylurea, pioglitazone (avoid in heart failure) or insulin." },
      { id: "endo_dka", complications: "Hypokalaemia - the commonest and most dangerous, driven by insulin\nHypoglycaemia - the reason insulin drops to 0.05 units/kg/h once glucose is below 14\nCerebral oedema - rare but often fatal, highest risk in young adults and children; suspect with headache, irritability or a falling GCS\nVenous thromboembolism - hence routine thromboprophylaxis\nAspiration pneumonia in the drowsy, vomiting patient\nHyperchloraemic metabolic acidosis from large-volume 0.9% sodium chloride, which keeps bicarbonate low and can mimic unresolved DKA", management: { def: "A[\"Suspected diabetic ketoacidosis\"]:::start --> B[\"Confirm the triad - glucose over 11 or known diabetes, ketones 3 or more, venous pH under 7.3 or bicarbonate under 15\"]:::process\nB -- \"main pathway\" --> C{\"Shocked - systolic BP under 90 mmHg\"}:::decision\nB -- \"in parallel\" --> O[\"IN PARALLEL from the outset - treat the precipitant, thromboprophylaxis, hourly monitoring, diabetes team referral\"]:::process\nC -- \"yes\" --> D[\"500 mL 0.9 percent sodium chloride over 15 min, repeat if systolic still under 100\"]:::danger\nC -- \"no\" --> E[\"1 L 0.9 percent sodium chloride over 1 hour, then the JBDS fluid schedule\"]:::good\nD --> E\nE --> F[\"Fixed-rate insulin infusion 0.1 units/kg/h, maximum about 15 units/h\"]:::good\nF --> G[\"Potassium in the bag - 40 mmol/L if 3.5 to 5.5, none if over 5.5, senior advice if under 3.5\"]:::warn\nG --> H[\"CONTINUE the usual long-acting insulin, monitor glucose and ketones hourly\"]:::good\nH --> I{\"Hourly targets met - ketones falling 0.5, bicarbonate rising 3, glucose falling 3\"}:::decision\nI -- \"no\" --> J[\"Check the pump and lines FIRST, then increase insulin by 1 unit/h\"]:::warn\nJ --> H\nI -- \"yes\" --> K{\"Glucose fallen below 14 mmol/L\"}:::decision\nK -- \"yes\" --> L[\"Add 10 percent glucose at 125 mL/h AND reduce insulin to 0.05 units/kg/h\"]:::warn\nK -- \"no\" --> M{\"Resolved - ketones under 0.6 AND venous pH over 7.3\"}:::decision\nL --> M\nM -- \"not yet\" --> H\nM -- \"yes and eating\" --> N[\"Subcutaneous fast-acting with a meal, stop the infusion 30 to 60 min later\"]:::good\nO --> P[\"Call critical care if severe - ketones over 6, pH under 7.0, bicarbonate under 5, potassium under 3.5, GCS under 12\"]:::danger", tips: { A: "Diabetic ketoacidosis is a medical emergency defined by the triad of hyperglycaemia, ketonaemia and metabolic acidosis. The commonest precipitants are infection, omitted insulin and new-onset type 1 diabetes. Watch for EUGLYCAEMIC DKA in people taking SGLT2 inhibitors, where glucose may be normal or only mildly raised - the 2023 guideline added this specifically.", B: "JBDS diagnostic criteria: capillary glucose above 11 mmol/L (or known diabetes), capillary ketones 3.0 mmol/L or more (or urine ketones 2+ or more), and venous pH below 7.3 or bicarbonate below 15 mmol/L. A VENOUS gas is sufficient - an arterial sample is not needed.", C: "This is the branch point that decides how fast the first fluid goes in, so assess the circulation immediately. A systolic blood pressure below 90 mmHg means shock. It is usually from volume depletion, but consider sepsis and heart failure as well.", D: "Shocked: give 500 mL of 0.9 percent sodium chloride over 15 minutes, and repeat the bolus if the systolic pressure is still below 100 mmHg. These patients also meet the severe-DKA threshold, so involve critical care early.", E: "Not shocked: give 1 litre of 0.9 percent sodium chloride over 1 hour, then follow the JBDS schedule with progressively longer bags. FLUID, NOT INSULIN, IS THE FIRST PRIORITY - it restores circulating volume, lowers glucose by dilution and improves renal perfusion. Give it more cautiously in young adults aged 18 to 25, the elderly, pregnancy, and heart or kidney failure, because of the risks of cerebral oedema and fluid overload.", F: "Prescribe 50 units of soluble insulin in 49.5 mL of 0.9 percent sodium chloride (1 unit/mL) and run a FIXED-rate infusion at 0.1 units/kg/h by actual body weight, capped at around 15 units/h. Fixed rate, not a sliding scale - the target is clearing ketones, not normalising glucose.", G: "Potassium falls fast once insulin starts, because insulin drives it into cells. JBDS thresholds: above 5.5 mmol/L give none, 3.5 to 5.5 give 40 mmol/L in the bag, below 3.5 needs senior advice and more potassium than a standard bag provides. DO NOT give potassium if the patient is anuric, and any rate above 20 mmol/h needs cardiac monitoring.", H: "CONTINUE the person's usual long-acting basal insulin (glargine, degludec, detemir, Humulin I and the like) throughout - stopping it is a common and avoidable error that causes rebound ketosis when the infusion comes down. Monitor glucose and ketones hourly, with venous gas and potassium at 1 and 2 hours and then 2-hourly.", I: "The three hourly treatment targets: ketones falling by at least 0.5 mmol/L/h, venous bicarbonate rising by at least 3 mmol/L/h, and glucose falling by at least 3 mmol/L/h. These are what tell you the insulin dose is adequate.", J: "If the targets are not being met, FIRST check that the pump is working, the lines are connected and the residual volume is correct - a disconnected or malfunctioning pump is the commonest reason. Only then increase the fixed-rate infusion, in 1 unit/h increments, rechecking hourly.", K: "Glucose falling below 14 mmol/L is the trigger for two simultaneous changes. It is a trigger to CHANGE treatment, not to stop it.", L: "Start 10 percent glucose at 125 mL/h alongside the saline AND reduce the fixed-rate insulin from 0.1 to 0.05 units/kg/h. The insulin reduction is the headline 2023 change - audit of the previous guideline found hypoglycaemia and hypokalaemia were common when the rate was held at 0.1 even with glucose running. The insulin must NOT be stopped, because it is the ketosis being treated, not the glucose. Run the insulin and glucose through a Y connector.", M: "Resolution is ketones below 0.6 mmol/L AND venous pH above 7.3. Do NOT use bicarbonate as the marker at this stage - the large volume of 0.9 percent sodium chloride causes a hyperchloraemic acidosis that keeps bicarbonate low even once the ketosis has cleared. Failure to resolve by 24 hours is unusual and needs senior specialist input.", N: "Convert only once ketosis has resolved AND the person is eating and drinking. Give the subcutaneous fast-acting insulin WITH a meal and continue the infusion for 30 to 60 minutes afterwards, so there is never a gap in insulin cover. Refer to the diabetes specialist team before discharge.", O: "These run ALONGSIDE the fluid and insulin from the moment DKA is confirmed - they are not a later step, which is why this branch leaves the pathway at the top. Find and treat the precipitant (infection, myocardial infarction, missed insulin, steroids, alcohol, pregnancy, pump failure), give thromboprophylaxis, catheterise if not passing urine within an hour, consider a nasogastric tube if vomiting with reduced consciousness, and refer to the diabetes team.", P: "Markers of severe DKA that warrant critical care or level 2 care: blood ketones above 6 mmol/L, venous pH below 7.0, bicarbonate below 5 mmol/L, potassium below 3.5 on admission, GCS below 12, oxygen saturation below 92 percent on air, systolic BP below 90 mmHg, or pulse above 100 or below 60." }, source: "JBDS-IP (March 2023)" }, cluster: "Diabetes", name: "Diabetic ketoacidosis", keyFacts: "A life-threatening emergency of hyperglycaemia, ketosis and acidosis, usually in type 1 diabetes.", epidemiology: "A common presentation of type 1 diabetes and a major cause of diabetic admissions.", aetiology: "Insulin omission, infection or new-onset type 1 diabetes.", pathophysiology: "Insulin deficiency drives unchecked lipolysis and ketogenesis, producing ketoacidosis, osmotic diuresis, dehydration and electrolyte loss.", presentation: "Vomiting, abdominal pain, Kussmaul breathing, ketotic breath, dehydration, drowsiness.", investigations: "Capillary/blood ketones, glucose, venous gas, U&E.", treatment: "Fluid FIRST: 0.9% sodium chloride - 500 mL over 15 min if systolic BP under 90 (repeat if still under 100), otherwise 1 L over 1 hour, then the JBDS schedule. Fixed-rate insulin infusion 0.1 units/kg/h (max ~15 units/h). Potassium 40 mmol/L in the bag if K+ 3.5-5.5, none if above 5.5 or anuric, senior advice if below 3.5. CONTINUE the usual long-acting insulin. Once glucose falls below 14 mmol/L add 10% glucose at 125 mL/h AND reduce insulin to 0.05 units/kg/h. Treat the precipitant, thromboprophylaxis. Resolution = ketones below 0.6 and venous pH above 7.3; convert to subcutaneous insulin with a meal, overlapping the infusion by 30-60 min." },
      { id: "endo_hhs", cluster: "Diabetes", name: "Hyperosmolar hyperglycaemic state (HHS)", keyFacts: "A life-threatening emergency of type 2 diabetes: profound hyperglycaemia and hyperosmolality with marked dehydration but WITHOUT significant ketosis or acidosis; it develops over days.", epidemiology: "Typically older people with type 2 diabetes, often as the first presentation; carries a higher mortality than diabetic ketoacidosis.", aetiology: "Precipitated by infection, myocardial infarction, stroke, dehydration, poor diabetic control or drugs (e.g. steroids, thiazides); enough insulin remains to suppress ketogenesis.", pathophysiology: "Relative insulin deficiency allows severe hyperglycaemia without ketosis; the osmotic diuresis causes profound water and electrolyte loss, rising osmolality, and a high risk of venous thromboembolism.", presentation: "Days of polyuria, polydipsia, weakness and dehydration progressing to confusion and reduced consciousness; glucose often over 30 mmol/L with signs of severe volume depletion.", investigations: "Glucose (usually 30 mmol/L or more), calculated osmolality (usually 320 mosmol/kg or more), U and Es, blood or urine ketones (low), venous blood gas (pH over 7.3, bicarbonate over 15), and a search for the precipitant.", treatment: "IV 0.9% sodium chloride to replace the large fluid deficit, more slowly and cautiously than in DKA; careful potassium replacement; start low-rate fixed-rate insulin only once glucose stops falling with fluids alone (or from the outset if ketones are raised); VTE prophylaxis; treat the precipitant and monitor osmolality.", management: {"def": "A[\"Hyperosmolar hyperglycaemic state\"]:::start --> B[\"Confirm: glucose 30+, osmolality 320+, no significant ketosis or acidosis\"]:::process\nB --> C[\"IV 0.9 percent sodium chloride: cautious rehydration\"]:::good\nC --> D[\"Aim osmolality to fall only 3 to 8 mOsm/kg/h\"]:::warn\nD --> E[\"Monitor and replace potassium\"]:::warn\nE --> F{\"Glucose falling on fluids alone?\"}:::decision\nF -- \"yes\" --> G[\"Continue fluids, no insulin yet\"]:::good\nF -- \"no, or ketones raised\" --> H[\"Start insulin at 0.05 units/kg/h\"]:::good\nC --> I[\"VTE prophylaxis, treat the precipitant, foot protection\"]:::process\nG --> J[\"Aim to normalise osmolality over 24 to 72 hours\"]:::good\nH --> J", "tips": {"A": "Hyperosmolar hyperglycaemic state is the type 2 diabetes counterpart of DKA, developing over days with profound dehydration and marked hyperosmolality but WITHOUT significant ketosis, because residual insulin suppresses ketogenesis. Mortality is considerably higher than in DKA.", "B": "JBDS characterise HHS by marked hypovolaemia, glucose 30 mmol/L or above, serum osmolality 320 mOsm/kg or above, and no significant ketonaemia (under 3 mmol/L) or acidosis (pH above 7.3, bicarbonate above 15). Calculate osmolality as 2 times sodium plus glucose plus urea. Mixed DKA and HHS pictures occur and are treated on their merits.", "C": "Fluid replacement with 0.9% sodium chloride is the mainstay and alone will lower the glucose. Rehydrate CAUTIOUSLY: these patients are typically older with cardiac and renal comorbidity, and the fluid deficit (often 100 to 220 mL/kg) accumulated over days should be replaced over days, not hours.", "D": "This is the safety-critical number: aim for a fall in osmolality of only 3 to 8 mOsm/kg/h. Correcting too fast risks cerebral oedema and central pontine myelinolysis. Note that JBDS deliberately permits a slightly faster fall than the American guidance, which caps it at 3 mOsm/kg/h. Monitor osmolality hourly at first, and expect the sodium to RISE initially as glucose falls, which is not itself a reason to change fluid.", "E": "Insulin and rehydration both drive potassium into cells, so measure it early and replace as in DKA, guided by the level. Assess and correct magnesium and phosphate too.", "F": "Unlike DKA, insulin is NOT started routinely at the outset. Give fluid alone first and reassess, because fluid alone usually lowers glucose adequately.", "G": "If glucose is falling appropriately on fluid alone, do not add insulin — adding it early accelerates the osmotic shift and increases the risk of neurological injury.", "H": "Start insulin only if there is significant ketonaemia (suggesting a mixed picture) or if glucose stops falling despite adequate fluid. The JBDS rate is a low fixed rate of 0.05 units/kg/h, half the DKA rate, increased as required.", "I": "These patients are at very high thromboembolic risk, so give prophylactic low-molecular-weight heparin unless contraindicated. Actively seek and treat the precipitant (infection, myocardial infarction, stroke, or drugs such as steroids and thiazides), and protect the heels and feet, which are highly vulnerable.", "J": "Aim to normalise osmolality gradually over 24 to 72 hours, replacing the estimated fluid deficit over the same period, with careful attention to fluid balance and conscious level. Involve the diabetes specialist team, and plan longer-term diabetes management before discharge."}, "source": "JBDS"} },
      { id: "endo_acromegaly", cluster: "Pituitary & hypothalamic", name: "Acromegaly", keyFacts: "Growth hormone excess in adults, almost always from a pituitary adenoma, causing acral and soft-tissue overgrowth.", epidemiology: "Rare; usually diagnosed in middle age after years of insidious change.", aetiology: "A growth hormone-secreting pituitary adenoma in nearly all cases; rarely ectopic growth hormone-releasing hormone.", pathophysiology: "Excess growth hormone raises insulin-like growth factor 1 (IGF-1), driving bone, cartilage and soft-tissue growth and insulin resistance.", presentation: "Coarse features, large hands and feet, prognathism, sweating, headache, bitemporal hemianopia, carpal tunnel syndrome.", investigations: "IGF-1 (raised), oral glucose tolerance test (failure to suppress growth hormone), pituitary MRI, visual fields.", treatment: "Trans-sphenoidal surgery first-line; somatostatin analogues (octreotide), pegvisomant, cabergoline; radiotherapy." },
      { id: "endo_prolactinoma", cluster: "Pituitary & hypothalamic", name: "Prolactinoma", keyFacts: "The commonest functioning pituitary tumour; hyperprolactinaemia causes galactorrhoea and hypogonadism and is treated medically.", epidemiology: "The most common pituitary adenoma; microprolactinomas are commoner in young women.", aetiology: "A prolactin-secreting pituitary adenoma; distinguish from drugs, pregnancy, hypothyroidism and stalk-effect causes of raised prolactin.", pathophysiology: "Excess prolactin suppresses gonadotrophin-releasing hormone, causing hypogonadism, while stimulating breast milk production.", presentation: "Women: amenorrhoea, galactorrhoea, infertility; men: low libido, erectile dysfunction; mass effects (headache, bitemporal hemianopia).", investigations: "Serum prolactin: a very high level (e.g. >6000 mU/L) indicates a prolactinoma, whereas a modest rise (1000-5000 mU/L) suggests stalk effect from a non-functioning adenoma; pituitary MRI, visual fields, and check the other anterior pituitary axes (GH, cortisol, thyroid); exclude pregnancy, drugs and hypothyroidism.", treatment: "Dopamine agonist (cabergoline or bromocriptine) first-line, even for macroadenomas; replace any deficient pituitary hormones (hydrocortisone, thyroxine, sex steroids); trans-sphenoidal surgery if visual or pressure symptoms fail to respond to medical therapy." },
      { id: "endo_kallmann", management: { def: "A[\"Delayed or absent puberty\"]:::start --> B[\"LH, FSH and testosterone or oestradiol\"]:::process\nB --> C{\"Gonadotrophin pattern\"}:::decision\nC -- \"LH and FSH HIGH\" --> D[\"Hypergonadotropic - primary gonadal failure, send karyotype for Klinefelter or Turner\"]:::good\nC -- \"LH and FSH LOW or inappropriately normal\" --> E[\"Hypogonadotropic - the defect is hypothalamic or pituitary\"]:::process\nE --> F[\"Exclude acquired causes - pituitary tumour, hyperprolactinaemia, iron overload, chronic illness, low weight or overtraining\"]:::process\nF --> G{\"Sense of smell\"}:::decision\nG -- \"anosmia or hyposmia\" --> H[\"KALLMANN SYNDROME\"]:::danger\nG -- \"normal smell\" --> I[\"Normosmic congenital hypogonadotropic hypogonadism\"]:::warn\nH --> J[\"MRI - absent or hypoplastic olfactory bulbs with a normal pituitary\"]:::process\nI --> J\nJ --> K[\"Genetic testing and counselling - ANOS1 X-linked, FGFR1, PROKR2, CHD7\"]:::process\nK --> L{\"Fertility wanted now\"}:::decision\nL -- \"no\" --> M[\"Sex steroid replacement - testosterone in males, oestrogen with progestogen in females\"]:::good\nL -- \"yes\" --> N[\"Gonadotrophins - hCG, then add FSH for spermatogenesis - or pulsatile GnRH\"]:::good\nM --> O[\"Monitor bone density, offer psychological support\"]:::good\nN --> O\nO --> P[\"Retest off treatment periodically - reversal occurs in around 10 to 15%\"]:::warn", tips: { A: "Delayed puberty means no testicular enlargement by 14 in boys or no breast development by 13 in girls. The commonest cause by far is CONSTITUTIONAL DELAY of growth and puberty, which is a normal variant with a family history and delayed bone age - the job is to separate that from true hypogonadism, and the two can look identical at first.", B: "The gonadotrophins are what split the differential, so measure LH and FSH alongside the sex steroid. Also check prolactin, thyroid function and the rest of the pituitary profile.", C: "This single result divides the whole differential in two, and getting it the wrong way round is a classic exam trap.", D: "HIGH gonadotrophins with low sex steroids means the gonad has failed and the pituitary is shouting at it - primary (hypergonadotropic) hypogonadism. Send a karyotype: Klinefelter syndrome (47,XXY) in males, Turner syndrome (45,X) in females.", E: "LOW or inappropriately normal gonadotrophins with low sex steroids means the pituitary is not being driven - secondary (hypogonadotropic) hypogonadism. Kallmann syndrome sits here.", F: "Congenital hypogonadotropic hypogonadism is a diagnosis of exclusion, so rule out the acquired causes first - a pituitary or hypothalamic tumour, hyperprolactinaemia, haemochromatosis, chronic systemic illness, anorexia nervosa, excessive exercise, and opioid or anabolic steroid use.", G: "Smell is the pivot, and it is easily missed because patients often do not volunteer it and may not realise they have never smelled anything. Test it formally rather than asking.", H: "Kallmann syndrome is congenital hypogonadotropic hypogonadism WITH anosmia or hyposmia. GnRH-secreting neurones normally migrate alongside the olfactory axons from the olfactory placode to the hypothalamus - when that shared migration fails, the patient ends up with neither a GnRH pulse generator nor olfactory bulbs. Anosmia is present in roughly half of all congenital hypogonadotropic hypogonadism.", I: "Around half of congenital cases have a normal sense of smell. The endocrine management is identical - only the genetics and the associated features differ.", J: "MRI shows absent or hypoplastic olfactory bulbs and sulci with a structurally normal pituitary, and simultaneously excludes a hypothalamic or pituitary mass.", K: "Over 30 genes are implicated. ANOS1 (formerly KAL1) is X-linked recessive and is the one associated with UNILATERAL RENAL AGENESIS and mirror movements (synkinesia); FGFR1 is autosomal dominant and linked to cleft lip and palate; CHD7 overlaps CHARGE syndrome. Arrange a renal ultrasound, and counsel about inheritance.", L: "This is the practical fork, because the treatment differs completely. Sex steroids alone will never restore fertility - they suppress what little gonadotrophin drive there is.", M: "Replace to induce and then maintain secondary sexual characteristics, and to protect bone. Start at a low dose and titrate up over 2 to 3 years to mimic normal puberty, which matters for final height and for psychological adjustment.", N: "Fertility is achievable in most patients - congenital hypogonadotropic hypogonadism is one of the few genuinely treatable causes of male infertility. Use hCG (acting as LH) to raise intratesticular testosterone, then add FSH if sperm do not appear. Pulsatile GnRH via a pump is the alternative where the pituitary is intact.", O: "Untreated hypogonadism causes osteoporosis, so check bone density and give calcium and vitamin D. The psychological burden of delayed puberty and infertility is substantial and under-treated.", P: "Around 10 to 15% of patients undergo REVERSAL, with the axis recovering spontaneously - so treatment should be interrupted periodically to retest rather than assumed lifelong." }, source: "European Consensus (CHH)" }, complications: "Infertility - though treatable with gonadotrophins or pulsatile GnRH\nOsteoporosis and fracture from untreated sex steroid deficiency\nPsychological impact of delayed puberty, body image and infertility\nUnilateral renal agenesis with the ANOS1 genotype\nMissed diagnosis - anosmia is rarely volunteered and must be tested for", cluster: "Pituitary & hypothalamic", name: "Kallmann syndrome", keyFacts: "Congenital hypogonadotropic hypogonadism WITH anosmia, caused by failed embryonic migration of GnRH-secreting neurones from the olfactory placode to the hypothalamus.", epidemiology: "Around 1 in 30,000 males and 1 in 120,000 females, with a male predominance. Anosmia or hyposmia is present in about half of all congenital hypogonadotropic hypogonadism, and that half is Kallmann syndrome.", aetiology: "Genetically heterogeneous, with over 30 genes implicated: ANOS1 (formerly KAL1, X-linked recessive), FGFR1 (autosomal dominant), PROKR2, PROK2 and CHD7 (overlapping CHARGE syndrome). Many cases are sporadic.", pathophysiology: "GnRH neurones migrate with the olfactory axons from the olfactory placode to the hypothalamus in fetal life. Failure of that shared migration leaves no GnRH pulse generator and no olfactory bulbs, so the pituitary is never stimulated and LH, FSH and sex steroids all remain low.", presentation: "Delayed or absent puberty with anosmia or hyposmia; cryptorchidism and micropenis in boys, primary amenorrhoea in girls; eunuchoid body proportions and reduced bone density. Associations include unilateral renal agenesis, mirror movements (synkinesia), cleft lip or palate and sensorineural deafness.", investigations: "LOW LH and FSH with low testosterone or oestradiol - the hypogonadotropic pattern is the key discriminator from primary gonadal failure. Formal smell testing; MRI showing absent or hypoplastic olfactory bulbs with a normal pituitary; prolactin, iron studies and full pituitary profile to exclude acquired causes; karyotype, bone age, renal ultrasound, DEXA and genetic testing.", treatment: "Sex steroid replacement to induce and maintain secondary sexual characteristics and protect bone - testosterone in males, oestrogen with progestogen in females, titrated up over 2-3 years to mimic normal puberty. For fertility, switch to gonadotrophins (hCG, adding FSH for spermatogenesis) or pulsatile GnRH. Genetic counselling, psychological support and bone density monitoring. Reversal occurs in around 10-15%, so interrupt treatment periodically to retest." },
      { id: "endo_di", management: {"def": "A[\"Polyuria and polydipsia\"]:::start --> B[\"Confirm urine output above 3 L per day\"]:::process\nB --> C[\"Exclude mimics: glucose, calcium, potassium, U and Es\"]:::process\nC --> D{\"Diabetes mellitus or electrolyte cause found?\"}:::decision\nD -- \"yes\" --> E[\"Treat that cause instead\"]:::good\nD -- \"no\" --> F[\"Paired serum and urine osmolality\"]:::process\nF --> G[\"Water deprivation test, then give desmopressin\"]:::process\nG --> H{\"Does urine concentrate after desmopressin?\"}:::decision\nH -- \"yes: cranial DI\" --> I[\"Start desmopressin, titrate to symptoms\"]:::good\nH -- \"no: nephrogenic DI\" --> J[\"Nephrogenic pathway: treat cause, thiazide\"]:::warn\nI --> K[\"MRI pituitary and full anterior pituitary profile\"]:::good\nK --> L[\"Monitor sodium for dilutional hyponatraemia\"]:::warn", "tips": {"A": "Cranial (central) diabetes insipidus presents with large volumes of dilute urine and intense thirst, classically of abrupt onset with a craving for cold water.", "B": "Confirm genuine polyuria, conventionally more than 3 litres of urine in 24 hours in an adult, before embarking on water deprivation testing.", "C": "Exclude the common mimics first: uncontrolled diabetes mellitus (osmotic diuresis), hypercalcaemia and hypokalaemia (both cause nephrogenic resistance), and check renal function.", "D": "If glucose, calcium or potassium explains the polyuria, treat that instead - it is far commoner than true cranial diabetes insipidus.", "E": "Uncontrolled diabetes mellitus, hypercalcaemia and hypokalaemia all cause polyuria and are treated on their own merits; recheck the urine output once they are corrected before pursuing diabetes insipidus.", "F": "Measure serum and urine osmolality on paired samples. The diagnostic combination is a high or normal serum osmolality with inappropriately dilute urine (under 300 mOsm/kg).", "G": "The water deprivation test is followed by desmopressin, and separates the two forms of diabetes insipidus. Plasma copeptin (a surrogate for vasopressin) is increasingly used as a simpler alternative.", "H": "This is the pivotal step: in cranial disease the kidney is normal and responds to exogenous hormone, so urine concentrates. If it stays dilute, the defect is renal resistance.", "I": "Treat with desmopressin by intranasal, oral or sublingual route, titrated against symptoms, and ensure free access to water.", "J": "Failure to concentrate after desmopressin means nephrogenic diabetes insipidus - see that entry, where treatment is directed at the cause plus a thiazide.", "K": "Once cranial disease is confirmed, image the pituitary and hypothalamus with magnetic resonance imaging and screen the whole anterior pituitary, since other hormone deficits and an underlying lesion are common.", "L": "The main hazard of treatment is dilutional hyponatraemia from too much desmopressin, so monitor serum sodium, especially after dose changes. Post-neurosurgical diabetes insipidus may be transient or follow a triphasic pattern."}, "source": "Society for Endocrinology"}, cluster: "Pituitary & hypothalamic", name: "Cranial (central) diabetes insipidus", keyFacts: "Deficiency of antidiuretic hormone (ADH, arginine vasopressin) from the hypothalamus or posterior pituitary, causing large volumes of dilute urine and intense thirst. It responds to desmopressin, which distinguishes it from the nephrogenic form. Recent international consensus renames it arginine vasopressin deficiency (AVP-D).", epidemiology: "Uncommon, but the commoner of the two forms of diabetes insipidus. It follows the distribution of pituitary and hypothalamic disease, and post-surgical cases are the commonest identifiable cause.", aetiology: "Idiopathic in a large minority, often autoimmune. Pituitary or hypothalamic surgery and head trauma. Tumours including craniopharyngioma, pituitary macroadenoma, germinoma and metastases. Infiltrative and granulomatous disease such as sarcoidosis, Langerhans cell histiocytosis and tuberculosis. Vascular causes including Sheehan syndrome and pituitary apoplexy. Infection such as meningitis and encephalitis. Congenital forms including Wolfram (DIDMOAD) syndrome and autosomal dominant AVP gene mutations.", pathophysiology: "Reduced synthesis or release of ADH means the collecting ducts fail to insert aquaporin-2 water channels, so free water is not reabsorbed. Dilute urine is lost, plasma osmolality and sodium rise, and thirst is stimulated. While thirst is intact and water is freely available, serum sodium stays near normal, which is why hypernatraemia signals restricted intake rather than mild disease.", presentation: "Polyuria, often more than 3 litres daily, with nocturia and marked polydipsia and a characteristic craving for cold water. Onset is typically abrupt. Hypernatraemia, dehydration, confusion and ultimately coma occur if water intake is restricted, so the elderly, post-operative and unconscious are most at risk. Look for features of the underlying lesion such as visual field loss or other pituitary hormone deficiencies.", investigations: "Paired serum and urine osmolality showing a high or normal serum osmolality with inappropriately dilute urine; U&Es, glucose, calcium and potassium to exclude mimics; a water deprivation test followed by desmopressin, after which the urine concentrates; plasma copeptin as a newer alternative; MRI of the pituitary and hypothalamus with a full anterior pituitary profile.", treatment: "Desmopressin given intranasally, orally or sublingually and titrated against symptoms, with serum sodium monitored for dilutional hyponatraemia. Ensure free access to water. Treat the underlying cause and replace any other deficient pituitary hormones. After pituitary surgery, monitor fluid balance and sodium closely because the picture may be transient or triphasic." },
      { id: "endo_nephrogenic_di", management: {"def": "A[\"Diabetes insipidus not responding to desmopressin\"]:::start --> B[\"Confirms nephrogenic DI: renal ADH resistance\"]:::process\nB --> C[\"Identify the cause: drug chart, calcium, potassium, renal function\"]:::process\nC --> D{\"Reversible cause found?\"}:::decision\nD -- \"lithium\" --> E[\"Discuss with psychiatry before any change: never stop abruptly\"]:::warn\nD -- \"hypercalcaemia or hypokalaemia\" --> F[\"Correct the electrolyte abnormality\"]:::good\nD -- \"none, or hereditary\" --> G[\"Consider AVPR2 or AQP2 genetic testing\"]:::process\nE --> H[\"Ensure free access to water\"]:::good\nF --> H\nG --> H\nH --> I[\"Thiazide diuretic, often with amiloride\"]:::good\nI --> J[\"Low-salt and low-protein diet to cut solute load\"]:::good\nJ --> K{\"Still symptomatic?\"}:::decision\nK -- \"no\" --> L[\"Monitor sodium, urine output and renal function\"]:::good\nK -- \"yes\" --> M[\"Add indomethacin under specialist supervision\"]:::warn", "tips": {"A": "Nephrogenic diabetes insipidus is diagnosed when the urine fails to concentrate after desmopressin during a water deprivation test - the diagnostic pathway is set out under Cranial diabetes insipidus.", "B": "The hormone is present but the kidney cannot respond, because the V2 receptor is defective or downregulated or because aquaporin-2 channels fail to reach the apical membrane. Desmopressin is therefore ineffective.", "C": "Hunt the cause: review every drug (especially lithium), and check calcium, potassium and renal function. Acquired causes greatly outnumber hereditary ones in adults.", "D": "Most acquired disease is reversible or at least improvable once the cause is addressed, so this step matters more than drug treatment.", "E": "Lithium is the single commonest cause. Never stop it abruptly or unilaterally - discuss with the prescribing psychiatrist, since relapse of bipolar disorder may be more dangerous than the diabetes insipidus. Amiloride is particularly useful here because it blocks lithium entry into the collecting duct.", "F": "Correct hypercalcaemia and hypokalaemia, both of which impair the concentrating mechanism and are readily reversible.", "G": "Where no acquired cause is found, especially in a male infant with failure to thrive and recurrent hypernatraemia, test for X-linked AVPR2 receptor mutations (about 90% of congenital cases) or autosomal aquaporin-2 (AQP2) mutations.", "H": "Unrestricted access to water is the single most important protective measure, because these patients cannot be rescued with desmopressin and will become hypernatraemic if deprived.", "I": "A thiazide diuretic paradoxically reduces urine volume by causing mild volume depletion and increasing proximal reabsorption. It is often combined with amiloride, which also offsets the hypokalaemia.", "J": "Reducing dietary salt and protein lowers the obligatory solute load the kidney must excrete, and so lowers the obligatory water loss.", "K": "Reassess symptoms and urine output once the cause is addressed and a thiazide is established.", "L": "Once controlled, monitor serum sodium, urine output and renal function long term, and keep the causative drug under review.", "M": "For refractory symptoms a prostaglandin synthetase inhibitor such as indomethacin can be added under specialist supervision, with renal function monitored."}, "source": "Society for Endocrinology"}, cluster: "Pituitary & hypothalamic", name: "Nephrogenic diabetes insipidus", keyFacts: "Renal resistance to antidiuretic hormone (ADH), so the kidney cannot concentrate urine despite adequate or raised circulating hormone. It does NOT respond to desmopressin, which is what separates it from the cranial form. Recent international consensus renames it arginine vasopressin resistance (AVP-R).", epidemiology: "Less common than cranial diabetes insipidus. Acquired forms dominate in adults, with lithium the single commonest cause; the hereditary X-linked form presents in male infants.", aetiology: "Drugs, above all lithium, and also demeclocycline, amphotericin B, foscarnet and cidofovir. Electrolyte disturbance, namely hypercalcaemia and hypokalaemia. Renal disease including chronic kidney disease, post-obstructive uropathy, sickle cell nephropathy, amyloidosis and Sjogren syndrome. Hereditary disease from X-linked AVPR2 receptor mutations (around 90% of congenital cases) or autosomal aquaporin-2 (AQP2) mutations. Pregnancy can cause a gestational form through placental vasopressinase.", pathophysiology: "ADH reaches the collecting duct but cannot act, because the V2 receptor is defective or downregulated or because aquaporin-2 water channels fail to traffic to the apical membrane. Lithium enters the collecting duct cell through the epithelial sodium channel and disrupts V2 signalling. The end result is the same free-water loss as in cranial disease, but it cannot be corrected with exogenous hormone.", presentation: "Polyuria, nocturia and polydipsia, usually of more insidious onset than the cranial form. Hereditary disease presents in male infants with failure to thrive, vomiting, fever, irritability and recurrent hypernatraemic dehydration. Hypernatraemia is more likely than in cranial disease because it cannot be bypassed by giving desmopressin.", investigations: "Paired serum and urine osmolality; U&Es with calcium, potassium, glucose and a lithium level; a water deprivation test with desmopressin, after which the urine remains dilute (the key contrast with cranial disease); renal imaging; and genetic testing for AVPR2 or AQP2 mutations where hereditary disease is suspected.", treatment: "Treat or remove the cause: review lithium with the prescribing psychiatrist rather than stopping it abruptly, and correct hypercalcaemia and hypokalaemia. Guarantee free access to water. A thiazide diuretic paradoxically reduces urine volume and is often combined with amiloride, which is especially useful in lithium-induced disease. A low-salt, low-protein diet reduces the solute load, and indomethacin may be added under specialist supervision. Desmopressin is ineffective." },
      { id: "endo_siadh", cluster: "Pituitary & hypothalamic", name: "SIADH", keyFacts: "Syndrome of inappropriate antidiuretic hormone: euvolaemic hyponatraemia from excess ADH; a diagnosis of exclusion.", epidemiology: "A common cause of hyponatraemia in hospital.", aetiology: "Malignancy (especially small-cell lung cancer), chest disease (pneumonia), CNS disorders, and drugs (SSRIs, carbamazepine).", pathophysiology: "Excess ADH causes renal water retention that dilutes serum sodium while the urine stays inappropriately concentrated; the patient is euvolaemic.", presentation: "Often asymptomatic; nausea, confusion, seizures if severe or rapid; clinically euvolaemic.", investigations: "Low serum osmolality with inappropriately high urine osmolality and urine sodium; normal thyroid and cortisol.", treatment: "Treat the cause; fluid restriction first-line; tolvaptan or cautious hypertonic saline if severe; avoid over-rapid correction." },
      { id: "endo_hypothyroid", management: {"def": "A[\"Primary hypothyroidism\"]:::start --> B[\"Levothyroxine once daily\"]:::good\nB --> C{\"Age and cardiac disease?\"}:::decision\nC -- \"young, fit\" --> D[\"Start about 1.6 micrograms/kg/day\"]:::good\nC -- \"over 65 or cardiac\" --> E[\"Start low: 25 micrograms\"]:::warn\nD --> F[\"Recheck TSH at 6-8 weeks\"]:::process\nE --> F\nF --> G{\"TSH normalised?\"}:::decision\nG -- \"yes\" --> H[\"Annual TSH monitoring\"]:::good\nG -- \"no\" --> I[\"Adjust in 25 microgram steps\"]:::good\nI --> F", "tips": {"A": "Underactive thyroid (raised TSH, low free T4); commonest cause is autoimmune (Hashimoto).", "B": "Levothyroxine is first-line, taken on an empty stomach and separated from calcium/iron.", "C": "Starting dose depends on age and cardiac status.", "D": "Young and otherwise well: start near full replacement (about 1.6 micrograms/kg/day).", "E": "Over 65 or ischaemic heart disease: start low (25 micrograms) and titrate slowly to avoid precipitating angina or arrhythmia.", "F": "Recheck TSH 6-8 weeks after any dose change (TSH responds slowly).", "G": "Titrate to a normal TSH with resolved symptoms.", "H": "Once stable, monitor TSH annually. Requirements rise in pregnancy - increase the dose and check early.", "I": "Adjust in 25-microgram steps and recheck in 6-8 weeks."}}, cluster: "Thyroid", name: "Hypothyroidism", keyFacts: "An underactive thyroid causing a slowed metabolism; the commonest cause is autoimmune (Hashimoto's).", epidemiology: "Common, particularly in older women.", aetiology: "Autoimmune thyroiditis, post-thyroidectomy or radioiodine, drugs (amiodarone, lithium), and iodine deficiency worldwide.", pathophysiology: "Reduced thyroid hormone slows metabolic processes throughout the body; low T4 releases negative feedback, so TSH rises.", presentation: "Fatigue, weight gain, cold intolerance, constipation, dry skin, bradycardia.", investigations: "TSH (high) and free T4 (low); thyroid peroxidase antibodies.", treatment: "Levothyroxine titrated to TSH; start low in elderly/cardiac patients." },
      { id: "endo_hashimotos", management: {"source": "NICE NG145", "def": "A[\"Painless goitre or suspected hypothyroidism\"]:::start --> B[\"TSH and free T4\"]:::process\nB --> C[\"Anti-TPO antibodies confirm the autoimmune cause\"]:::good\nC --> D{\"Thyroid function pattern\"}:::decision\nD -- \"high TSH, low T4\" --> E[\"Overt hypothyroidism - start levothyroxine\"]:::good\nD -- \"high TSH, normal T4\" --> F{\"TSH above 10?\"}:::decision\nD -- \"normal TSH\" --> G[\"Euthyroid but antibody-positive - monitor annually\"]:::process\nF -- \"yes\" --> E\nF -- \"no, 4 to 10\" --> H{\"Symptomatic and under 65?\"}:::decision\nH -- \"yes\" --> I[\"6-month levothyroxine trial, then review\"]:::good\nH -- \"no\" --> G\nE --> J[\"Titrate against TSH: see the Hypothyroidism entry\"]:::good\nI --> J\nG --> K[\"Rapid painless enlargement - urgent referral for lymphoma\"]:::danger\nJ --> K", "tips": {"A": "Hashimoto's classically presents as a painless, firm, diffusely enlarged goitre, or is found when hypothyroidism is investigated.", "B": "Thyroid function comes first: it decides whether anything needs treating, while the antibodies only explain why.", "C": "Anti-thyroid peroxidase antibodies are positive in around 90%. Anti-thyroglobulin adds little and is not routinely needed.", "D": "The three patterns that matter are overt hypothyroidism, subclinical hypothyroidism, and a euthyroid antibody-positive patient.", "E": "Overt primary hypothyroidism, a raised TSH with a low free T4, is treated with levothyroxine regardless of symptoms.", "F": "In subclinical disease the TSH level is the discriminator, because the risk of progression and of cardiovascular harm rises above 10.", "G": "Antibody-positive euthyroid patients need only annual thyroid function, since a positive anti-TPO markedly raises the chance of future hypothyroidism.", "H": "Below a TSH of 10, treat only younger symptomatic patients, and as a time-limited trial rather than an open-ended prescription.", "I": "Offer a 6-month trial and review it honestly - if symptoms have not improved, stop the levothyroxine rather than continue it indefinitely.", "J": "Dosing, the 6 to 8 week recheck and the lower starting dose in older or cardiac patients are all covered in the Hypothyroidism entry.", "K": "Hashimoto's is the strongest risk factor for primary thyroid lymphoma, so a rapidly enlarging painless goitre needs urgent referral, not reassurance."}}, complications: "Progression to overt hypothyroidism: the usual course, and much more likely when anti-TPO antibodies are positive.\nMyxoedema coma: the decompensated extreme, covered in its own entry.\nGoitre with compressive symptoms: dysphagia, dyspnoea or hoarseness from a large gland.\nPrimary thyroid lymphoma (MALT type): rare, but Hashimoto's is by far its strongest risk factor - suspect it if the goitre enlarges rapidly and painlessly.\nOther autoimmune disease: pernicious anaemia, vitiligo, coeliac disease, type 1 diabetes and Addison's, as part of the autoimmune polyglandular syndromes.\nIn pregnancy: increased risk of miscarriage and preterm birth, and the levothyroxine requirement rises by roughly a quarter to a half.", cluster: "Thyroid", name: "Hashimoto's thyroiditis", keyFacts: "Autoimmune lymphocytic destruction of the thyroid and the commonest cause of hypothyroidism in iodine-replete countries such as the UK. The signature is a PAINLESS goitre with positive anti-thyroid peroxidase antibodies — contrast the painful goitre of De Quervain's thyroiditis.", epidemiology: "The commonest cause of hypothyroidism where iodine intake is adequate. Female to male ratio around 10 to 1, with a peak between 45 and 65 years. Strong family history, and clear associations with other autoimmune disease and with Down and Turner syndromes.", aetiology: "Autoimmune, with HLA associations and a strong genetic component. Recognised triggers include high iodine intake, neck irradiation, the postpartum period, and drugs — amiodarone, lithium, interferon and the immune checkpoint inhibitors.", pathophysiology: "Autoreactive T cells and autoantibodies against thyroid peroxidase and thyroglobulin drive a dense lymphocytic infiltrate with germinal centre formation and Hurthle (Askanazy) cell change, progressively destroying follicles. The infiltrate itself produces the goitre; late disease may become atrophic instead. Early on, release of preformed hormone from damaged follicles can cause a transient thyrotoxic phase known as Hashitoxicosis.", presentation: "A painless, firm, diffusely enlarged goitre, with the features of hypothyroidism — fatigue, weight gain, cold intolerance, constipation, dry skin, hoarseness, menorrhagia, slow-relaxing reflexes and low mood. The patient may be euthyroid, or transiently thyrotoxic early in the disease.", investigations: "TSH and free T4 first. Anti-thyroid peroxidase antibodies are positive in about 90% and confirm the cause; anti-thyroglobulin adds little. Ultrasound only for a dominant nodule or rapid growth. Radionuclide uptake scanning is not needed. Check lipids and full blood count, as hypercholesterolaemia and macrocytic anaemia often accompany it.", treatment: "Levothyroxine for overt hypothyroidism, titrated against TSH (see the Hypothyroidism entry). In subclinical disease treat if TSH is above 10 mU/L on two occasions; between the upper limit of normal and 10, offer a 6-month trial to symptomatic people under 65 and review. Euthyroid antibody-positive patients need only annual monitoring. There is no role for corticosteroids or antibody-directed treatment. Refer urgently for rapid painless enlargement, compression or suspected lymphoma." },
      { id: "endo_myxoedema_coma", management: {"def": "A[\"Suspected myxoedema coma: hypothermia, reduced consciousness, hypothyroidism\"]:::start --> B[\"ABCDE, critical care, bloods: TFTs, cortisol, U and Es, glucose, ABG, cultures\"]:::process\nB --> C[\"IV hydrocortisone 100 mg FIRST, before any thyroid hormone\"]:::danger\nC --> D[\"Then IV levothyroxine or liothyronine, discuss with endocrinology\"]:::good\nD --> E[\"PASSIVE rewarming only: avoid active rewarming\"]:::warn\nE --> F{\"Type 2 respiratory failure or CO2 retention?\"}:::decision\nF -- \"yes\" --> G[\"Ventilatory support, avoid all sedatives\"]:::danger\nF -- \"no\" --> H[\"Cautious IV fluids, correct glucose, correct sodium slowly\"]:::good\nG --> H\nH --> I[\"Treat the precipitant: antibiotics for infection, review drug chart\"]:::good\nI --> J[\"Critical care monitoring: arrhythmia, fluid overload, repeat TFTs\"]:::good", "tips": {"A": "Myxoedema coma is the decompensated extreme of severe hypothyroidism and a true endocrine emergency, with a mortality of roughly 20 to 50% even when treated. The name is a misnomer: frank coma is uncommon, and most present with hypothermia, confusion or drowsiness. Classically an elderly woman in winter with long-standing untreated or under-treated hypothyroidism.", "B": "Manage in a critical care setting. Take thyroid function tests, a cortisol (ideally BEFORE steroids), U and Es, glucose, full blood count, CRP and cultures, an arterial blood gas and an ECG. Very high TSH with a very low free T4 indicates primary disease; a low or normal TSH suggests a secondary (pituitary) cause. Expect hyponatraemia and hypoglycaemia.", "C": "Give IV hydrocortisone 100 mg BEFORE thyroid hormone replacement. This is the single most important sequencing point: coexisting adrenal insufficiency is common, and giving thyroid hormone first accelerates cortisol metabolism and can precipitate an adrenal crisis.", "D": "Then replace thyroid hormone intravenously, discussed with endocrinology: typically IV levothyroxine with a loading dose (around 300 to 500 micrograms) followed by 50 to 100 micrograms daily, or liothyronine (T3) which acts faster but carries more cardiac risk. Absorption from the gut is unreliable in myxoedema, hence the intravenous route.", "E": "Rewarm PASSIVELY with blankets in a warm room. Active external rewarming causes peripheral vasodilatation in a patient who cannot increase cardiac output, and can precipitate circulatory collapse.", "F": "Assess ventilation carefully. Thyroid hormone deficiency depresses the hypoxic and hypercapnic respiratory drive, so type 2 respiratory failure with carbon dioxide narcosis is a major cause of death.", "G": "Support ventilation, with intubation if needed, and avoid ALL sedatives and opioids: hepatic drug metabolism is markedly slowed, so normal doses become dangerous and sedation is a common precipitant in the first place.", "H": "Give intravenous fluids cautiously because cardiac output is low and fluid overload is easily provoked. Correct hypoglycaemia, and correct the hyponatraemia SLOWLY to avoid osmotic demyelination.", "I": "Always look for the precipitant: infection (commonest, especially pneumonia or urinary sepsis), cold exposure, myocardial infarction, stroke, trauma or surgery, gastrointestinal bleeding, and sedating drugs. Abrupt withdrawal of levothyroxine is another cause. Treat infection empirically, as fever may be absent because of the hypothermia.", "J": "Monitor in critical care for arrhythmia, fluid overload and cardiac ischaemia as the metabolic rate rises, and repeat thyroid function to confirm the response. Once stable, convert to oral levothyroxine and address the reason replacement was inadequate."}, "source": "Endocrine emergency"}, cluster: "Thyroid", name: "Myxoedema coma", keyFacts: "The decompensated extreme of severe hypothyroidism, presenting with hypothermia, reduced consciousness and hypoventilation. It is a rare endocrine emergency with a mortality of about 20 to 50% even when treated, and the name is a misnomer because frank coma is uncommon.", epidemiology: "Rare. Classically affects elderly women during winter, almost always on a background of long-standing untreated or inadequately treated hypothyroidism, and is nearly always triggered by an identifiable precipitant.", aetiology: "Severe hypothyroidism decompensated by a stressor: infection (the commonest, especially pneumonia and urinary sepsis), cold exposure, myocardial infarction, stroke, trauma or surgery, gastrointestinal bleeding, and sedating drugs such as opioids, benzodiazepines and anaesthetic agents. Amiodarone and lithium can cause the underlying hypothyroidism, and abrupt withdrawal of levothyroxine is a further trigger.", pathophysiology: "Profound thyroid hormone deficiency slows every metabolic process. Reduced thermogenesis causes hypothermia; depression of the hypoxic and hypercapnic respiratory drive causes type 2 respiratory failure and carbon dioxide narcosis; cardiac output and heart rate fall; impaired free water excretion produces dilutional hyponatraemia; and slowed hepatic metabolism makes normal drug doses toxic. Coexisting adrenal insufficiency is common, which is why steroids precede thyroid hormone.", presentation: "Hypothermia, which may be profound and which masks the fever of an underlying infection; confusion, drowsiness, seizures or reduced consciousness; bradycardia, hypotension and hypoventilation. Signs of severe hypothyroidism are usually evident: dry coarse skin, non-pitting periorbital and peripheral oedema, macroglossia, a hoarse voice, slow-relaxing reflexes, hair thinning and ileus or constipation.", investigations: "Thyroid function (markedly raised TSH with very low free T4 in primary disease; low or normal TSH points to a pituitary cause); random cortisol taken before steroids where possible; U and Es showing hyponatraemia; glucose for hypoglycaemia; FBC, CRP, blood and urine cultures and a chest X-ray as a septic screen; arterial blood gas for type 2 respiratory failure; ECG showing bradycardia, low-voltage complexes and a prolonged QT; and creatine kinase.", treatment: "Critical care management. Give IV hydrocortisone 100 mg BEFORE any thyroid hormone, because unrecognised adrenal insufficiency can be precipitated. Then replace thyroid hormone intravenously (levothyroxine with a loading dose, or liothyronine) after discussion with endocrinology. Rewarm PASSIVELY only, since active rewarming can cause circulatory collapse. Support ventilation, avoid all sedatives, give cautious IV fluids, correct hypoglycaemia and correct sodium slowly. Treat the precipitant with empirical antibiotics, and monitor for arrhythmia and fluid overload." },
      { id: "endo_hyperthyroid", management: {"def": "A[\"Suspected hyperthyroidism\"]:::start --> B[\"Confirm: suppressed TSH with raised free T4 or T3\"]:::process\nB --> C[\"Beta-blocker for symptom relief whatever the cause\"]:::good\nC --> D{\"TSH receptor antibodies (TRAb)\"}:::decision\nD -- \"positive\" --> E[\"Graves disease\"]:::good\nD -- \"negative or equivocal\" --> F[\"Radionuclide uptake scan\"]:::process\nF --> G{\"Uptake pattern\"}:::decision\nG -- \"diffuse high\" --> E\nG -- \"focal or patchy high\" --> H[\"Toxic nodular goitre or toxic adenoma\"]:::good\nG -- \"globally low\" --> I[\"Thyroiditis or exogenous thyroid hormone\"]:::good\nE --> J[\"Treat per NICE NG145: see the Graves disease entry\"]:::good\nH --> K[\"Radioiodine first-line: antithyroid drugs do NOT cure nodular disease\"]:::good\nI --> L[\"Supportive only: NSAIDs and beta-blocker, NO antithyroid drugs\"]:::danger\nK --> M[\"Thyroidectomy if compression, suspected cancer or radioiodine unsuitable\"]:::warn\nJ --> N[\"Lifelong levothyroxine and TFT monitoring after definitive treatment\"]:::good\nK --> N\nM --> N", "tips": {"A": "Hyperthyroidism means the thyroid is overproducing hormone. Thyrotoxicosis is the broader clinical state of excess circulating thyroid hormone from ANY source, including thyroiditis and exogenous levothyroxine where the gland is not overactive at all. That distinction drives this whole pathway.", "B": "Confirm biochemically: a suppressed TSH with a raised free T4 and/or free T3. If TSH is suppressed but T4 and T3 are normal, this is SUBCLINICAL hyperthyroidism, which is monitored and treated selectively (for example with atrial fibrillation or osteoporosis).", "C": "A beta-blocker such as propranolol relieves tremor, palpitations, anxiety and heat intolerance in every cause, and can be started immediately while the cause is being established. It does not treat the underlying disease.", "D": "Establishing the CAUSE is the key step, because treatment differs completely between the three groups. TSH receptor antibodies are the first-line discriminator: they are positive in around 95% of Graves disease and effectively confirm it without further imaging.", "E": "Graves disease is the commonest cause, accounting for roughly 70 to 80% of hyperthyroidism. Look for the extrathyroidal features that occur in no other cause: thyroid eye disease, pretibial myxoedema and thyroid acropachy.", "F": "If antibodies are negative or equivocal, a technetium or radioiodine uptake scan separates the remaining causes by the pattern of tracer uptake. Avoid in pregnancy and breastfeeding.", "G": "The uptake pattern is diagnostic and splits the causes into three: diffusely high (Graves), focal or patchy (nodular disease), or globally low (the gland is not making hormone at all).", "H": "Focal or patchy uptake indicates a toxic adenoma or toxic multinodular goitre, where one or more autonomous nodules produce hormone independently of TSH. This is commoner in older patients and in iodine-deficient areas.", "I": "Globally LOW uptake means the thyrotoxicosis is not from overproduction but from hormone leaking out of a damaged gland, or from an exogenous source. Causes include De Quervain subacute thyroiditis (painful), postpartum thyroiditis, amiodarone-induced type 2, and taking too much levothyroxine.", "J": "Follow the Graves disease entry for the full pathway. In brief, NICE NG145 offers RADIOACTIVE IODINE as first-line definitive treatment where antithyroid drugs are unlikely to achieve remission, and a choice between carbimazole for 12 to 18 months and radioiodine where remission is likely. Use propylthiouracil in pregnancy or if conceiving within 6 months, and warn every patient on carbimazole about agranulocytosis: an urgent full blood count if they develop a sore throat, mouth ulcers or fever.", "K": "This is the crucial contrast with Graves disease: nodular disease does NOT remit, so a course of antithyroid drugs will never cure it and the thyrotoxicosis simply returns when the drug is stopped. Radioiodine is therefore the first-line definitive treatment, with antithyroid drugs used only to render the patient euthyroid beforehand or where definitive treatment is unsuitable.", "L": "Thyroiditis is self-limiting and antithyroid drugs are INEFFECTIVE, because there is no excess synthesis to block. Treat supportively with NSAIDs for pain and a beta-blocker for symptoms, and monitor thyroid function through the characteristic thyrotoxic then hypothyroid phases. See the De Quervain thyroiditis entry.", "M": "Total thyroidectomy is used where there is compression or suspected malignancy, or where radioiodine is unsuitable, for example pregnancy or planned conception within 4 to 6 months, or active thyroid eye disease. Its specific risks are recurrent laryngeal nerve palsy and hypoparathyroidism with hypocalcaemia.", "N": "After radioiodine or surgery, hypothyroidism is expected and usually permanent, so arrange lifelong levothyroxine with thyroid function monitoring. Thyroid storm is the life-threatening extreme of thyrotoxicosis and is a separate emergency."}, "source": "NICE NG145"}, cluster: "Thyroid", name: "Hyperthyroidism", keyFacts: "An overactive thyroid causing a fast metabolism; Graves' disease is the commonest cause.", epidemiology: "Common, more so in women; Graves' typically affects younger adults.", aetiology: "Graves' disease (TSH-receptor antibodies), toxic nodular goitre, thyroiditis, and excess iodine or thyroxine.", pathophysiology: "Excess thyroid hormone accelerates metabolism and sympathetic activity; in Graves', antibodies stimulate the TSH receptor.", presentation: "Weight loss, heat intolerance, tremor, palpitations; Graves adds eye signs and goitre.", investigations: "TSH (low), free T4/T3 (high), TSH-receptor antibodies, isotope scan.", treatment: "Beta-blocker for symptom relief whatever the cause, then treat according to the cause. Graves disease per NICE NG145: radioiodine is first-line definitive treatment where antithyroid drugs are unlikely to achieve remission, otherwise a choice of carbimazole for 12 to 18 months or radioiodine. Toxic nodular goitre and toxic adenoma: radioiodine first-line, because antithyroid drugs do not induce remission in nodular disease. Thyroiditis: supportive only, since antithyroid drugs are ineffective. Thyroidectomy for compression, suspected malignancy or where radioiodine is unsuitable. Propylthiouracil in pregnancy; treat thyroid storm as an emergency. Lifelong levothyroxine after definitive treatment." },
      { id: "endo_graves", management: {"def": "A[\"Graves disease: thyrotoxicosis with TSH receptor antibodies\"]:::start --> B[\"Beta-blocker for symptom relief\"]:::good\nB --> C{\"Is remission on antithyroid drugs likely?\"}:::decision\nC -- \"unlikely\" --> D[\"Radioactive iodine: NICE first-line definitive treatment\"]:::good\nC -- \"likely: mild and uncomplicated\" --> E{\"Shared decision: antithyroid drug or radioiodine\"}:::decision\nE -- \"radioiodine\" --> D\nE -- \"antithyroid drug\" --> F[\"Carbimazole 12 to 18 months: block-and-replace or titration\"]:::good\nF --> G{\"Remission after 12 to 18 months?\"}:::decision\nG -- \"yes\" --> H[\"Stop and monitor TFTs for relapse\"]:::good\nG -- \"no or relapse\" --> I{\"Is radioiodine suitable?\"}:::decision\nI -- \"yes\" --> D\nI -- \"no: pregnancy, active eye disease, compression, suspected cancer\" --> K[\"Total thyroidectomy\"]:::warn\nD --> J[\"Lifelong levothyroxine, monitor TFTs\"]:::good\nK --> J\nA --> L[\"Pregnant or conceiving within 6 months: propylthiouracil\"]:::warn", "tips": {"A": "Graves disease is the commonest cause of hyperthyroidism, driven by IgG antibodies that stimulate the TSH receptor. It is the only cause of thyrotoxicosis with extrathyroidal features: thyroid eye disease, pretibial myxoedema and thyroid acropachy. TSH receptor antibodies are positive in around 95%.", "B": "Give a beta-blocker such as propranolol for symptomatic relief of tremor, palpitations and anxiety while definitive treatment is arranged. It does not alter the underlying disease.", "C": "This is the branch point in NICE NG145, and it differs from the classical teaching that antithyroid drugs always come first. The decision turns on whether a course of antithyroid drugs is likely to achieve lasting remission.", "D": "NICE NG145 offers RADIOACTIVE IODINE as first-line definitive treatment where antithyroid drugs are unlikely to achieve remission. It is simple and effective, but most patients become permanently hypothyroid. Avoid pregnancy for the recommended interval afterwards, and observe the local radiation-protection precautions.", "E": "Where remission IS likely, for example mild uncomplicated disease with a small goitre, NICE offers a choice between a 12 to 18 month course of an antithyroid drug and radioiodine, made with the patient.", "F": "Carbimazole is given for 12 to 18 months, using either a block-and-replace regimen (high-dose carbimazole plus levothyroxine) or a titration regimen (dose adjusted to thyroid function). Warn every patient about AGRANULOCYTOSIS: they must seek an urgent full blood count if they develop a sore throat, mouth ulcers or fever. Note the MHRA advice on effective contraception and on the risk of acute pancreatitis with carbimazole.", "G": "Review at the end of the course. Roughly half of patients relapse after a course of antithyroid drugs, most within the first year.", "H": "If remission is achieved, stop the drug and monitor thyroid function, since relapse is common and may occur years later.", "I": "If there is no remission or the disease relapses, move to definitive treatment, and decide whether radioiodine is appropriate.", "K": "Total thyroidectomy is offered where radioiodine is unsuitable: concern about compression, suspected malignancy, pregnancy or planned conception within 4 to 6 months, or active thyroid eye disease (radioiodine can worsen it, and steroid cover is used if it is given). Surgical risks are recurrent laryngeal nerve palsy and hypoparathyroidism with hypocalcaemia.", "J": "After radioiodine or surgery, hypothyroidism is expected and usually permanent, so patients need lifelong levothyroxine with thyroid function monitoring. Smoking cessation is critical throughout, because smoking markedly worsens thyroid eye disease.", "L": "In pregnancy, or if conception is planned within 6 months, use PROPYLTHIOURACIL rather than carbimazole, because carbimazole is associated with congenital malformations. Radioiodine is absolutely contraindicated in pregnancy."}, "source": "NICE NG145"}, cluster: "Thyroid", name: "Graves' disease", keyFacts: "The commonest cause of hyperthyroidism, an autoimmune disease in which TSH receptor stimulating antibodies drive unregulated thyroid hormone production. It is the only cause of thyrotoxicosis that also produces extrathyroidal features: eye disease, pretibial myxoedema and thyroid acropachy.", epidemiology: "Accounts for roughly 70 to 80% of hyperthyroidism. It peaks between 30 and 50 years and is around 5 to 10 times commoner in women. It clusters with other autoimmune disease, and smoking is a major risk factor that particularly worsens the eye disease.", aetiology: "Autoimmune, caused by IgG autoantibodies directed against the TSH receptor which stimulate rather than block it. There is a genetic predisposition (HLA-DR3, CTLA-4 and PTPN22 associations), with triggers including smoking, stress, high iodine intake, the postpartum period and drugs such as amiodarone.", pathophysiology: "TSH receptor stimulating antibodies mimic TSH, producing continuous unregulated hormone synthesis and diffuse hyperplasia of the gland, hence a smooth goitre with high diffuse tracer uptake. The same antibodies cross-react with orbital and dermal fibroblasts, which deposit glycosaminoglycans and cause the orbitopathy and pretibial myxoedema unique to Graves disease.", presentation: "Thyrotoxic features: weight loss with preserved or increased appetite, heat intolerance and sweating, fine tremor, palpitations and atrial fibrillation, anxiety and irritability, diarrhoea, oligomenorrhoea and proximal myopathy. Graves-specific signs are a diffuse smooth non-tender goitre, often with a bruit; thyroid eye disease with exophthalmos, lid lag, chemosis and diplopia; pretibial myxoedema; and thyroid acropachy.", investigations: "Suppressed TSH with raised free T4 and/or free T3. TSH receptor antibodies (TRAb) are diagnostic and positive in around 95%, and anti-thyroid peroxidase antibodies are often present. Where antibodies are equivocal or unavailable, a technetium or radioiodine uptake scan shows DIFFUSE increased uptake, contrasting with the low uptake of thyroiditis and the focal hot nodule of toxic adenoma. Check full blood count and liver function before starting an antithyroid drug.", treatment: "Beta-blocker such as propranolol for symptom relief. NICE NG145 offers radioactive iodine as FIRST-LINE definitive treatment where antithyroid drugs are unlikely to achieve remission; where remission is likely, offer a choice between carbimazole for 12 to 18 months (block-and-replace or titration) and radioiodine. Radioiodine is unsuitable in pregnancy or planned conception within 4 to 6 months, active thyroid eye disease, compression or suspected malignancy, when total thyroidectomy is offered instead. Use propylthiouracil if pregnant or conceiving within 6 months. Warn about carbimazole agranulocytosis and note the MHRA advice on contraception and acute pancreatitis. Lifelong levothyroxine after definitive treatment, and smoking cessation throughout." },
      { id: "endo_toxic_mng", management: {"source": "NICE NG145", "def": "A[\"Thyrotoxicosis with a nodular goitre\"]:::start --> B[\"TRAb negative with patchy uptake: see the Hyperthyroidism entry\"]:::process\nB --> C[\"Beta-blocker for symptom control\"]:::good\nC --> D[\"Ultrasound the goitre, FNA any dominant or cold nodule\"]:::process\nD --> E{\"Compression or retrosternal extension?\"}:::decision\nE -- \"yes\" --> F[\"CT or MRI neck and flow-volume loop\"]:::process\nF --> G[\"Total thyroidectomy\"]:::good\nE -- \"no\" --> H{\"Radioiodine suitable?\"}:::decision\nH -- \"yes\" --> I[\"Radioiodine is FIRST-LINE - nodular disease never remits\"]:::good\nH -- \"no\" --> G\nI --> J[\"Antithyroid drugs only to prepare, or in the very frail\"]:::warn\nG --> K[\"Lifelong levothyroxine and TFT monitoring\"]:::good\nJ --> K\nK --> L[\"Avoid iodinated contrast and amiodarone - Jod-Basedow\"]:::danger", "tips": {"A": "Suspect it in an older patient with a long-standing lumpy goitre who becomes thyrotoxic, particularly if the only sign is new atrial fibrillation.", "B": "The cause-finding pathway belongs to the Hyperthyroidism entry: negative TSH receptor antibodies with focal or patchy uptake is what identifies nodular disease.", "C": "A beta-blocker controls tremor, tachycardia and anxiety within hours while the definitive plan is arranged.", "D": "Image the gland itself, because a dominant or cold nodule within a toxic multinodular goitre still needs malignancy excluded.", "E": "Compressive features - dysphagia, dyspnoea, stridor, hoarseness or a positive Pemberton's sign - change the answer from radioiodine to surgery.", "F": "Cross-sectional imaging defines retrosternal extension, and a flow-volume loop demonstrates functional tracheal compression.", "G": "Total thyroidectomy is indicated for a large or retrosternal goitre, compressive symptoms, suspected malignancy, or where radioiodine is unsuitable.", "H": "Radioiodine is unsuitable in pregnancy or planned conception, in breastfeeding, and where compression or malignancy is suspected.", "I": "This is the key difference from Graves': autonomy is fixed, so antithyroid drugs suppress but never cure - stopping them simply returns the thyrotoxicosis.", "J": "Antithyroid drugs have a role only in rendering the patient euthyroid before definitive treatment, or as long-term suppression in someone too frail for either.", "K": "Hypothyroidism is the expected outcome of both radioiodine and total thyroidectomy, so lifelong replacement and monitoring follow.", "L": "An iodine load from contrast or amiodarone can tip an autonomous nodular goitre into severe thyrotoxicosis or storm - the Jod-Basedow effect."}}, complications: "Atrial fibrillation with thromboembolic stroke: often the presenting feature in an older patient, and the reason to treat even mild thyrotoxicosis.\nOsteoporosis and fracture: from long-standing thyroid hormone excess.\nCompressive symptoms: dysphagia, dyspnoea, stridor and hoarseness, especially with retrosternal extension.\nThyroid storm: particularly after an iodine load, surgery in a non-euthyroid patient, or radioiodine.\nPost-treatment hypothyroidism: the expected outcome rather than a complication.\nSurgical: recurrent laryngeal nerve injury causing hoarseness, and hypoparathyroidism causing hypocalcaemia.", cluster: "Thyroid", name: "Toxic multinodular goitre", keyFacts: "Also called Plummer's disease. Multiple autonomously functioning nodules produce thyroid hormone independently of TSH, making it the second commonest cause of hyperthyroidism after Graves'. The defining practical point: it NEVER remits, so antithyroid drugs cannot cure it and radioiodine is first-line. There are no eye signs.", epidemiology: "The second commonest cause of hyperthyroidism in the UK, and the commonest in iodine-deficient regions. Typically older women with a long-standing goitre, so incidence rises steeply with age.", aetiology: "Arises within a long-standing simple multinodular goitre. Somatic activating mutations of the TSH receptor or the Gs-alpha subunit make individual nodules autonomous. Iodine deficiency followed by repletion is a classic sequence, and an iodine load from contrast or amiodarone can unmask or precipitate it.", pathophysiology: "Activating somatic mutations allow nodules to synthesise hormone without TSH stimulation. Because autonomy accumulates slowly nodule by nodule, the patient passes through a euthyroid multinodular phase, then subclinical, then overt thyrotoxicosis. Surrounding normal thyroid tissue is suppressed, which is what produces the patchy hot-and-cold pattern on isotope scanning. Crucially the autonomy is structural and fixed, which is why the condition does not remit.", presentation: "An older patient with a long-standing lumpy goitre who becomes thyrotoxic, often oligosymptomatic — new atrial fibrillation, weight loss, heat intolerance or unexplained fatigue may be the only clue. There is NO thyroid eye disease and no pretibial myxoedema, which separates it from Graves'. Retrosternal extension causes dysphagia, dyspnoea, stridor or hoarseness, with a positive Pemberton's sign.", investigations: "Suppressed TSH with a raised free T4 or T3. TSH receptor antibodies are NEGATIVE. Radionuclide uptake scanning shows multiple patchy hot nodules with suppression of the intervening tissue. Ultrasound assesses the gland and identifies dominant or cold nodules for fine-needle aspiration. CT or MRI and a flow-volume loop where retrosternal extension or tracheal compression is suspected.", treatment: "Beta-blocker for symptoms. RADIOIODINE is first-line definitive treatment (NICE NG145), because antithyroid drugs suppress but never cure autonomous nodular disease. Total thyroidectomy for a large or retrosternal goitre, compressive symptoms, suspected malignancy, or where radioiodine is unsuitable — the patient must be euthyroid first. Antithyroid drugs are used only to prepare for definitive treatment or in the very frail. Lifelong levothyroxine and monitoring afterwards. Avoid iodinated contrast and amiodarone." },
      { id: "endo_de_quervain_thyroiditis", management: {"def": "A[\"Painful tender goitre after a viral illness\"]:::start --> B[\"Raised ESR and CRP, thyrotoxic thyroid function\"]:::process\nB --> C[\"Uptake scan shows GLOBALLY LOW uptake\"]:::process\nC --> D[\"Confirms subacute thyroiditis, NOT Graves disease\"]:::good\nD --> E[\"NSAIDs first-line for pain\"]:::good\nE --> F{\"Severe pain or marked systemic symptoms?\"}:::decision\nF -- \"yes\" --> G[\"Prednisolone, tapered over several weeks\"]:::warn\nF -- \"no\" --> H[\"Beta-blocker for thyrotoxic symptoms\"]:::good\nG --> H\nH --> I[\"Do NOT give antithyroid drugs\"]:::danger\nI --> J[\"Expect the triphasic course: thyrotoxic, euthyroid, then hypothyroid\"]:::process\nJ --> K[\"Monitor TFTs, levothyroxine if the hypothyroid phase is symptomatic\"]:::good\nK --> L[\"Around 90% recover fully, a small minority stay hypothyroid\"]:::good", "tips": {"A": "De Quervain thyroiditis (subacute granulomatous thyroiditis) is the classic cause of a PAINFUL thyroid. Almost every other thyroid disorder is painless, so a tender goitre with pain radiating to the jaw or ear, following a viral upper respiratory illness with fever and malaise, is close to diagnostic.", "B": "Inflammatory markers are strikingly raised, with an ESR often above 50, which is unusual in thyroid disease. Thyroid function is initially thyrotoxic, with suppressed TSH and raised free T4.", "C": "The single most useful discriminator: a technetium or radioiodine uptake scan shows GLOBALLY REDUCED uptake, because the gland is not making hormone. This is the exact opposite of the high diffuse uptake of Graves disease and the focal hot nodule of a toxic adenoma.", "D": "The low uptake confirms that this is a RELEASE phenomenon from a damaged gland rather than overproduction, which determines the entire management approach.", "E": "Treatment is symptomatic because the condition is self-limiting. Non-steroidal anti-inflammatory drugs are first-line for the pain.", "F": "Assess the severity of pain and systemic upset, which determines whether steroids are needed.", "G": "For severe pain or marked systemic symptoms, prednisolone gives rapid relief and is tapered over several weeks. Pain may recur if it is withdrawn too quickly.", "H": "A beta-blocker such as propranolol controls the thyrotoxic symptoms of the first phase. It does not shorten the illness.", "I": "This is the key management point: antithyroid drugs such as carbimazole are INEFFECTIVE and not indicated. The thyrotoxicosis comes from preformed hormone leaking out of a damaged gland, not from excess synthesis, so blocking synthesis achieves nothing.", "J": "Counsel the patient on the classic triphasic course: thyrotoxicosis for about 2 to 6 weeks as stored hormone is released, then a euthyroid period, then a hypothyroid phase lasting weeks to months while the follicles regenerate, then recovery.", "K": "Monitor thyroid function through the phases. Give levothyroxine temporarily if the hypothyroid phase is symptomatic, then withdraw it and re-check to confirm recovery.", "L": "Around 90% recover completely with normal thyroid function. A small minority are left permanently hypothyroid and need lifelong replacement, so arrange follow-up thyroid function testing."}, "source": "NICE CKS"}, cluster: "Thyroid", name: "De Quervain's thyroiditis (subacute)", keyFacts: "A self-limiting subacute granulomatous thyroiditis, typically following a viral illness, causing a PAINFUL tender goitre and a characteristic triphasic course of thyrotoxicosis, then hypothyroidism, then recovery. Radioiodine uptake is LOW, which distinguishes it from Graves disease. Note this is entirely unrelated to De Quervain tenosynovitis of the wrist.", epidemiology: "Uncommon. It most often affects women between 20 and 50 years, with a peak in summer and autumn that mirrors the seasonality of the preceding viral infections.", aetiology: "Believed to be post-viral, following upper respiratory infection with coxsackievirus, mumps, adenovirus, echovirus or influenza. There is a strong association with HLA-B35.", pathophysiology: "Virus-triggered granulomatous inflammation destroys thyroid follicular cells, releasing PREFORMED thyroid hormone into the circulation. This is a release phenomenon rather than overproduction, which explains both the low tracer uptake and why drugs that block hormone synthesis are useless. Once the stored hormone is exhausted the patient becomes transiently hypothyroid until the follicles regenerate.", presentation: "A painful, tender, firm goitre with pain radiating to the jaw or ear, preceded by a viral prodrome with fever and malaise. Thyrotoxic symptoms last around 2 to 6 weeks, followed by a euthyroid phase, then a hypothyroid phase lasting weeks to months, then recovery in about 90%.", investigations: "Markedly raised ESR and CRP alongside suppressed TSH and raised free T4 in the early phase. The decisive test is a technetium or radioiodine uptake scan showing globally REDUCED uptake, the opposite of Graves disease. Thyroid autoantibodies are usually negative or present only in low titre, and there may be a mild normocytic anaemia.", treatment: "Symptomatic, because the illness is self-limiting. NSAIDs are first-line for pain, with prednisolone tapered over several weeks for severe pain or marked systemic upset. A beta-blocker controls thyrotoxic symptoms. ANTITHYROID DRUGS ARE NOT INDICATED, since there is no excess hormone synthesis to block. Monitor thyroid function through the phases and give levothyroxine temporarily if the hypothyroid phase is symptomatic, with follow-up to identify the small minority left permanently hypothyroid." },
      { id: "endo_thyrotoxicosis", cluster: "Thyroid", name: "Thyrotoxicosis", keyFacts: "The clinical state of excess circulating thyroid hormone from any cause; thyroid storm is the life-threatening extreme.", epidemiology: "Common; Graves' disease is the leading cause, then toxic nodular disease.", aetiology: "Graves' disease, toxic multinodular goitre, toxic adenoma, thyroiditis (transient), and exogenous or amiodarone-induced causes.", pathophysiology: "Excess T3 and T4 raise the metabolic rate and sympathetic tone; a radioiodine uptake scan separates high-uptake (Graves, nodular) from low-uptake (thyroiditis, exogenous) causes.", presentation: "Weight loss, heat intolerance, tremor, palpitations, anxiety, diarrhoea; storm adds fever, agitation and atrial fibrillation.", investigations: "TSH (suppressed), free T4/T3 (raised), TSH-receptor antibodies, radioiodine uptake scan.", treatment: "Beta-blocker plus carbimazole (or propylthiouracil); radioiodine or surgery; thyroid storm needs urgent propylthiouracil, beta-blocker, steroids and iodine." },
      { id: "endo_thyroid_storm", management: {"source": "Endocrine emergency", "def": "A[\"Suspected thyroid storm\"]:::start --> B[\"Treat on clinical suspicion - do NOT wait for TFTs\"]:::danger\nB --> C[\"ABCDE, HDU or ICU, continuous cardiac monitoring\"]:::danger\nC --> D[\"Bloods, cultures, ECG - score with Burch-Wartofsky\"]:::process\nD --> E[\"1. Thionamide FIRST - propylthiouracil\"]:::good\nE --> F[\"2. Iodine (Lugols) at least 1 hour AFTER the thionamide\"]:::warn\nF --> G[\"3. Propranolol for the adrenergic state\"]:::good\nG --> H[\"4. Hydrocortisone 300 mg then 100 mg 8-hourly\"]:::good\nH --> I[\"5. Active cooling and paracetamol, NOT aspirin\"]:::warn\nI --> J[\"6. Find and treat the precipitant\"]:::good\nJ --> K[\"Supportive: fluids, rate control, thromboprophylaxis\"]:::good\nK --> L{\"Improving?\"}:::decision\nL -- \"yes\" --> M[\"Wean, then plan definitive treatment\"]:::good\nL -- \"no\" --> N[\"Consider plasma exchange or emergency thyroidectomy\"]:::danger", "tips": {"A": "Fever, tachycardia out of proportion to the fever, and altered consciousness in a thyrotoxic patient - most have a clear precipitant.", "B": "Hormone levels overlap with uncompensated thyrotoxicosis, so the diagnosis is clinical and treatment must not wait for the assay.", "C": "Mortality is 10 to 30%, so this belongs in a high-dependency or intensive care setting from the outset.", "D": "Send thyroid function, full blood count, urea and electrolytes, liver function, glucose, calcium and cultures. A Burch-Wartofsky score of 45 or more is highly suggestive.", "E": "Propylthiouracil is traditionally preferred because it also blocks peripheral conversion of T4 to T3, though carbimazole is an acceptable alternative.", "F": "THE SEQUENCING TRAP: iodine blocks hormone release, but given first it also supplies substrate and INCREASES hormone stores - always at least an hour after the thionamide.", "G": "Propranolol controls tachycardia, tremor and agitation, and at high dose also inhibits peripheral T4 to T3 conversion. Use with care in cardiac failure.", "H": "Hydrocortisone blocks peripheral conversion and covers the relative adrenal insufficiency that accompanies the hypermetabolic state.", "I": "Cool actively and use paracetamol. AVOID aspirin, which displaces thyroid hormone from thyroid-binding globulin and raises the free level.", "J": "Infection is the commonest precipitant. Also consider surgery, trauma, myocardial infarction, diabetic ketoacidosis, labour, iodinated contrast and abrupt withdrawal of antithyroid drugs.", "K": "Rehydrate generously, treat atrial fibrillation and high-output failure, and give thromboprophylaxis, as the risk of embolism is high.", "L": "Most improve within 24 to 48 hours. Failure to improve should prompt a search for a missed precipitant as well as escalation.", "M": "Once stable, arrange definitive treatment of the underlying thyrotoxicosis - radioiodine or surgery - because recurrence is otherwise likely.", "N": "Refractory cases may need therapeutic plasma exchange to remove circulating hormone, or emergency thyroidectomy after medical stabilisation."}}, complications: "High-output cardiac failure and cardiovascular collapse.\nAtrial fibrillation with thromboembolism and stroke.\nHyperthermia with rhabdomyolysis and acute kidney injury.\nEncephalopathy progressing from agitation and delirium to seizures and coma.\nHepatic dysfunction with jaundice, which carries a particularly poor prognosis.\nDeath in 10 to 30% even with treatment, which is why it is treated on suspicion alone.", cluster: "Thyroid", name: "Thyroid storm", keyFacts: "Decompensated, life-threatening thyrotoxicosis — the hyperthyroid counterpart to myxoedema coma. Mortality is 10 to 30%, and the diagnosis is CLINICAL: treat on suspicion without waiting for thyroid function tests. The examinable trap is the drug order — the thionamide must be given BEFORE iodine.", epidemiology: "Rare, complicating fewer than 10% of thyrotoxic hospital admissions, but with high mortality. It usually occurs in undiagnosed or undertreated Graves' disease or toxic nodular goitre, and in most cases a precipitant can be identified.", aetiology: "Almost always precipitated. Infection is the commonest trigger; others are surgery (especially thyroid surgery in a patient who is not euthyroid), trauma, myocardial infarction, diabetic ketoacidosis, labour and delivery, an iodine load from contrast or amiodarone, radioiodine treatment, and abrupt withdrawal of antithyroid drugs.", pathophysiology: "Not simply a higher hormone level — measured hormone concentrations overlap with those of uncompensated thyrotoxicosis. A sudden rise in FREE hormone, together with increased sensitivity of adrenergic receptors and reduced binding-protein affinity during acute illness, produces a hypermetabolic and hyperadrenergic state that overwhelms compensation, causing hyperthermia, high-output cardiac failure, arrhythmia and encephalopathy.", presentation: "Fever, often above 38.5 degrees, with tachycardia disproportionate to the fever, atrial fibrillation, agitation, delirium or coma, nausea, vomiting and diarrhoea, jaundice, heart failure and shock. A Burch-Wartofsky score of 45 or more makes the diagnosis highly likely.", investigations: "Clinical diagnosis — do NOT delay treatment for results. Thyroid function shows a suppressed TSH with raised free T4 or T3. Send full blood count, urea and electrolytes, liver function, glucose, calcium, CRP and cultures; do an ECG and chest X-ray; and actively search for the precipitant. Score with the Burch-Wartofsky criteria.", treatment: "Resuscitate (ABCDE) in HDU or ICU, then follow the sequence: THIONAMIDE FIRST (propylthiouracil, which also blocks peripheral T4 to T3 conversion; carbimazole is an alternative); IODINE (Lugol's solution) AT LEAST ONE HOUR LATER — never before, as iodine alone increases hormone stores; propranolol for the adrenergic state; hydrocortisone 300 mg loading then 100 mg 8-hourly; active cooling with paracetamol and NOT aspirin; treat the precipitant; and supportive care with fluids, rate control and thromboprophylaxis. Plasma exchange or emergency thyroidectomy for refractory cases. Arrange definitive treatment once stable." },
      { id: "endo_thyroid_eye", cluster: "Thyroid", name: "Thyroid eye disease", keyFacts: "Autoimmune orbital inflammation associated with Graves' disease that can threaten sight.", epidemiology: "Affects a substantial minority of Graves' patients and is worse in smokers.", aetiology: "Autoimmune (TSH-receptor antibody) inflammation of orbital tissues; smoking is a major risk factor.", pathophysiology: "Antibody-driven inflammation and glycosaminoglycan deposition expand the extraocular muscles and orbital fat, pushing the eye forward.", presentation: "Proptosis, lid retraction, gritty eyes, diplopia, periorbital oedema; optic nerve compression threatens vision.", investigations: "Clinical assessment, TFTs and TSH-receptor antibodies, orbital CT/MRI; assess for optic neuropathy.", treatment: "Stop smoking, lubricants, control thyroid; selenium in mild disease; steroids, orbital radiotherapy or decompression if active or sight-threatening." },
      { id: "endo_cushings", cluster: "Adrenal", name: "Cushing's syndrome", keyFacts: "Chronic cortisol excess; the commonest cause overall is exogenous steroid treatment.", epidemiology: "The iatrogenic (steroid) cause is common, whereas endogenous Cushing's is rare.", aetiology: "Exogenous steroids; endogenous disease from a pituitary adenoma (Cushing's disease), an adrenal tumour or ectopic ACTH.", pathophysiology: "Excess glucocorticoid drives central obesity, protein catabolism (thin skin, myopathy), hypertension and glucose intolerance.", presentation: "Central obesity, moon face, striae, proximal myopathy, easy bruising, hypertension.", investigations: "Overnight dexamethasone suppression, 24h urinary cortisol, late-night salivary cortisol; ACTH.", treatment: "Treat cause (stop steroids, remove tumour); manage hypertension and glucose." },
      { id: "endo_addisons", cluster: "Adrenal", name: "Addison's disease", keyFacts: "Primary adrenal insufficiency causing low cortisol and aldosterone; an adrenal crisis is life-threatening.", epidemiology: "Uncommon, with the autoimmune cause predominating in the UK.", aetiology: "Autoimmune adrenalitis (commonest in the UK); also tuberculosis worldwide, metastases and adrenal haemorrhage.", pathophysiology: "Destruction of the adrenal cortex reduces cortisol and aldosterone; loss of negative feedback raises ACTH, causing the characteristic hyperpigmentation.", presentation: "Fatigue, weight loss, hyperpigmentation, postural hypotension; crisis gives shock.", investigations: "Short Synacthen test, 9am cortisol, U&E (low Na, high K), adrenal antibodies.", treatment: "Hydrocortisone and fludrocortisone; sick-day rules; emergency IV steroids for crisis." },
      { id: "endo_adrenal_insufficiency", cluster: "Adrenal", name: "Adrenal insufficiency", keyFacts: "Inadequate cortisol (with or without aldosterone) production; may be primary, secondary or tertiary.", epidemiology: "Secondary (steroid-related) insufficiency is far commoner than primary Addison's disease.", aetiology: "Primary (Addison's: adrenal disease), secondary (pituitary ACTH deficiency), or tertiary (suppression by exogenous steroids, the commonest).", pathophysiology: "Cortisol deficiency impairs the stress response and blood pressure; in primary disease aldosterone is also lost and high ACTH drives pigmentation.", presentation: "Fatigue, weight loss, anorexia, dizziness, postural hypotension; pigmentation only in primary disease.", investigations: "Short Synacthen test, 9am cortisol and ACTH (high in primary, low in secondary), U&E.", treatment: "Hydrocortisone replacement (plus fludrocortisone in primary); sick-day rules; steroid emergency card." },
      { id: "endo_addisonian_crisis", management: {"source": "Endocrine emergency", "def": "A[\"Addisonian (adrenal) crisis\"]:::start --> B[\"Immediate IV hydrocortisone 100 mg\"]:::danger\nB --> C[\"Rapid IV 0.9 percent saline\"]:::good\nC --> D[\"Correct hypoglycaemia (IV glucose)\"]:::good\nD --> E[\"Treat precipitant (e.g. infection)\"]:::good\nE --> F[\"Continue hydrocortisone 100 mg 6-hourly\"]:::good\nF --> G[\"Once stable: oral steroids, add fludrocortisone\"]:::process\nA --> H[\"Take cortisol/ACTH but do not delay treatment\"]:::warn", "tips": {"A": "Life-threatening adrenal insufficiency (hypotension, collapse, low sodium, high potassium, hypoglycaemia), often triggered by infection, surgery or steroid withdrawal. Treat first, investigate later.", "B": "Give IV (or IM) hydrocortisone 100 mg immediately - do not wait for confirmation.", "C": "Rapid IV 0.9% sodium chloride to restore circulating volume (often several litres).", "D": "Treat and monitor for hypoglycaemia with IV glucose.", "E": "Identify and treat the precipitant (commonly infection).", "F": "Continue hydrocortisone 100 mg every 6 hours (IV/IM or as an infusion) until stable.", "G": "Once recovered, switch to oral hydrocortisone (double the usual dose in illness) and add fludrocortisone; issue a steroid emergency card and IM kit.", "H": "Take paired cortisol and ACTH (short Synacthen test later) - but never delay steroids for tests."}}, cluster: "Adrenal", name: "Addisonian crisis", keyFacts: "Acute adrenal crisis: a life-threatening emergency of profound cortisol deficiency causing shock.", epidemiology: "Occurs in known or undiagnosed adrenal insufficiency, often precipitated by physiological stress.", aetiology: "Intercurrent illness, infection, surgery or abrupt steroid withdrawal in adrenal insufficiency; adrenal haemorrhage (Waterhouse-Friderichsen).", pathophysiology: "An acute lack of cortisol (and aldosterone) causes vasodilatation, hypovolaemia and an impaired stress response, leading to shock.", presentation: "Hypotension and shock, vomiting, abdominal pain, confusion, fever; hyponatraemia, hyperkalaemia, hypoglycaemia.", investigations: "Do not delay treatment; take cortisol and ACTH, U&E and glucose, then treat empirically.", treatment: "Immediate IV hydrocortisone 100 mg and rapid 0.9% saline; treat the precipitant; glucose for hypoglycaemia." },
      { id: "endo_cah", cluster: "Adrenal", name: "Congenital adrenal hyperplasia (CAH)", keyFacts: "An inherited enzyme defect of cortisol synthesis, usually 21-hydroxylase deficiency, causing androgen excess.", epidemiology: "The commonest inherited adrenal disorder; the severe salt-losing form presents in neonates.", aetiology: "Autosomal recessive 21-hydroxylase deficiency in over 90%; the rarer 11-beta-hydroxylase deficiency causes hypertension.", pathophysiology: "Blocked cortisol (and aldosterone) synthesis shunts precursors into androgens and removes feedback, so ACTH drives adrenal hyperplasia and virilisation.", presentation: "Ambiguous genitalia in girls, salt-losing crisis in neonates; later precocious puberty or virilisation.", investigations: "Raised 17-hydroxyprogesterone, U&E (salt-losing: low Na, high K), androgens, genetic testing.", treatment: "Glucocorticoid (and mineralocorticoid) replacement; manage salt-losing crisis as adrenal crisis; surgical and psychological support." },
      { id: "endo_conns", cluster: "Adrenal", name: "Conn syndrome", keyFacts: "Primary hyperaldosteronism due to an aldosterone-producing adrenal adenoma, causing hypertension with hypokalaemia.", epidemiology: "A recognised and probably under-diagnosed cause of secondary hypertension.", aetiology: "A benign aldosterone-secreting adrenal adenoma (Conn's tumour).", pathophysiology: "Autonomous aldosterone secretion causes sodium and water retention (hypertension) and renal potassium and hydrogen loss (hypokalaemia, alkalosis).", presentation: "Hypertension, often resistant; muscle weakness, cramps and polyuria from hypokalaemia; frequently asymptomatic.", investigations: "Raised aldosterone:renin ratio, confirmatory saline suppression, adrenal CT, adrenal vein sampling.", treatment: "Laparoscopic adrenalectomy for a unilateral adenoma; spironolactone if not operable." },
      { id: "endo_hyperaldosteronism", cluster: "Adrenal", name: "Hyperaldosteronism", keyFacts: "Aldosterone excess causing hypertension and hypokalaemia; an important treatable cause of secondary hypertension.", epidemiology: "Found in a meaningful proportion of resistant hypertension.", aetiology: "Primary: bilateral adrenal hyperplasia (commonest) or an adenoma (Conn's), rarely carcinoma; secondary: high renin from renal artery stenosis, heart failure or cirrhosis.", pathophysiology: "Excess aldosterone drives renal sodium retention and potassium/hydrogen loss, raising blood pressure; renin is suppressed in primary and high in secondary disease.", presentation: "Hypertension (often resistant), hypokalaemia (weakness, cramps, polyuria); often asymptomatic.", investigations: "Aldosterone:renin ratio (high aldosterone with low renin in primary), confirmatory testing, adrenal CT, adrenal vein sampling.", treatment: "Mineralocorticoid receptor antagonist (spironolactone or eplerenone) for hyperplasia; adrenalectomy for a unilateral adenoma; treat any secondary cause." },
      { id: "endo_phaeochromocytoma", cluster: "Adrenal", name: "Phaeochromocytoma", keyFacts: "A catecholamine-secreting tumour of the adrenal medulla causing episodic hypertension; the rule of 10s is classic.", epidemiology: "Rare; about 10% are bilateral, 10% extra-adrenal and 10% malignant, with a notable proportion familial.", aetiology: "Sporadic, or familial as part of MEN2, von Hippel-Lindau disease or neurofibromatosis type 1.", pathophysiology: "Tumour chromaffin cells secrete adrenaline and noradrenaline, causing paroxysmal sympathetic surges.", presentation: "Episodic headache, sweating, palpitations and severe hypertension; pallor, anxiety, tremor.", investigations: "Plasma or 24-hour urinary metanephrines, adrenal CT/MRI, MIBG scan; genetic testing.", treatment: "Alpha-blockade (phenoxybenzamine) before beta-blockade, then surgical excision; never beta-block first." },
      { id: "endo_hyperparathyroid", cluster: "Parathyroid & bone", name: "Hyperparathyroidism", keyFacts: "Excess parathyroid hormone causing hypercalcaemia; often found incidentally.", epidemiology: "Common, especially in postmenopausal women.", aetiology: "Primary disease from a parathyroid adenoma; secondary disease from chronic kidney disease or vitamin D deficiency.", pathophysiology: "Excess parathyroid hormone raises calcium by mobilising bone, increasing renal reabsorption and activating vitamin D.", presentation: "Bones, stones, abdominal moans and psychic groans of hypercalcaemia; often incidental.", investigations: "Calcium (high), PTH (high or inappropriately normal), phosphate, vitamin D, renal imaging.", treatment: "Hydration; parathyroidectomy for symptomatic or significant primary disease." },
      { id: "endo_hypoparathyroid", cluster: "Parathyroid & bone", name: "Hypoparathyroidism", keyFacts: "Deficient parathyroid hormone causing hypocalcaemia; most often follows neck surgery.", epidemiology: "Most commonly iatrogenic after thyroid or parathyroid surgery.", aetiology: "Surgical removal or damage, autoimmune disease, congenital (DiGeorge) and magnesium deficiency; pseudohypoparathyroidism is PTH resistance.", pathophysiology: "Low parathyroid hormone reduces calcium mobilisation and vitamin D activation, causing hypocalcaemia and hyperphosphataemia.", presentation: "Perioral and digital paraesthesia, cramps, tetany, Chvostek's and Trousseau's signs, seizures; prolonged QT.", investigations: "Calcium (low), PTH (low or inappropriately normal), phosphate (high), magnesium, ECG.", treatment: "Calcium and active vitamin D (alfacalcidol); IV calcium gluconate for acute severe hypocalcaemia; correct magnesium." },
      { id: "endo_vit_d_deficiency", cluster: "Parathyroid & bone", name: "Vitamin D deficiency (osteomalacia & rickets)", keyFacts: "Lack of vitamin D impairs bone mineralisation, causing osteomalacia in adults and rickets in children.", epidemiology: "Common, especially with reduced sun exposure, darker skin and malabsorption.", aetiology: "Low sunlight or dietary intake, malabsorption (coeliac), chronic kidney or liver disease, and certain drugs.", pathophysiology: "Vitamin D deficiency lowers calcium and phosphate, causing secondary hyperparathyroidism and defective mineralisation of osteoid.", presentation: "Bone pain, proximal myopathy, fractures; children show bowed legs, growth failure and costochondral swelling.", investigations: "Low vitamin D, low or normal calcium and phosphate, raised ALP and PTH; Looser's zones on X-ray.", treatment: "Vitamin D replacement (colecalciferol) with calcium; treat the underlying cause." },
      { id: "endo_pagets", cluster: "Parathyroid & bone", name: "Paget's disease of bone", keyFacts: "Disordered bone remodelling producing enlarged, weak bone; often an incidental isolated raised alkaline phosphatase.", epidemiology: "Common in older people of European descent and often asymptomatic.", aetiology: "Unknown, with genetic and possibly viral contributions.", pathophysiology: "Excessive, disorganised osteoclastic resorption with compensatory osteoblastic formation produces structurally weak, enlarged bone.", presentation: "Often asymptomatic; bone pain, deformity (bowed tibia, skull enlargement), warmth, deafness; rarely osteosarcoma.", investigations: "Isolated raised ALP with normal calcium and phosphate, characteristic X-ray changes, isotope bone scan.", treatment: "Bisphosphonates (e.g. IV zoledronate) for pain or active disease; analgesia; monitor ALP." },
      { id: "endo_men1", cluster: "Multiple endocrine neoplasia", name: "Multiple endocrine neoplasia type 1 (MEN1)", keyFacts: "An autosomal dominant syndrome of the 3 Ps: parathyroid, pancreatic and pituitary tumours.", epidemiology: "A rare inherited cancer syndrome.", aetiology: "Germline mutation in the MEN1 tumour suppressor gene (menin); autosomal dominant.", pathophysiology: "Loss of the menin tumour suppressor predisposes to synchronous tumours across several endocrine glands.", presentation: "Primary hyperparathyroidism (commonest, hypercalcaemia), pancreatic tumours (gastrinoma, insulinoma), pituitary adenoma (often prolactinoma).", investigations: "Calcium and PTH, gut hormones, prolactin and IGF-1, imaging; genetic testing and family screening.", treatment: "Treat individual tumours surgically or medically; lifelong biochemical surveillance and family screening." },
      { id: "endo_men2a", cluster: "Multiple endocrine neoplasia", name: "Multiple endocrine neoplasia type 2A (MEN2A)", keyFacts: "An autosomal dominant RET syndrome of medullary thyroid cancer, phaeochromocytoma and hyperparathyroidism.", epidemiology: "Rare; caused by germline RET mutations.", aetiology: "Germline activating mutation of the RET proto-oncogene; autosomal dominant.", pathophysiology: "RET activation drives proliferation of thyroid C cells, adrenal medulla and parathyroid glands.", presentation: "Medullary thyroid carcinoma (almost all), phaeochromocytoma, primary hyperparathyroidism.", investigations: "Calcitonin, RET genetic testing, plasma metanephrines, calcium and PTH; family screening.", treatment: "Prophylactic thyroidectomy guided by the RET mutation; always exclude and treat phaeochromocytoma before any surgery." },
      { id: "endo_men2b", cluster: "Multiple endocrine neoplasia", name: "Multiple endocrine neoplasia type 2B (MEN2B)", keyFacts: "The rarest, most aggressive MEN: medullary thyroid cancer and phaeochromocytoma with a marfanoid, mucosal-neuroma phenotype.", epidemiology: "The rarest MEN subtype; medullary cancer presents early and aggressively.", aetiology: "Germline RET proto-oncogene mutation at a different codon from MEN2A; autosomal dominant.", pathophysiology: "RET activation causes aggressive medullary thyroid carcinoma, phaeochromocytoma and mucosal ganglioneuromas, but not hyperparathyroidism.", presentation: "Early aggressive medullary thyroid carcinoma, phaeochromocytoma, mucosal neuromas, marfanoid habitus, intestinal ganglioneuromatosis.", investigations: "Calcitonin, RET genetic testing, plasma metanephrines; early family screening.", treatment: "Prophylactic thyroidectomy in infancy; exclude phaeochromocytoma before surgery." },
      { id: "endo_hyperkalaemia", management: {"def": "A[\"Hyperkalaemia (K+ over 5.5)\"]:::start --> B[\"Urgent ECG\"]:::process\nB --> C{\"ECG changes or K+ 6.5+?\"}:::decision\nC -- \"yes (emergency)\" --> D[\"IV calcium gluconate\"]:::danger\nD --> E[\"Insulin + dextrose infusion\"]:::good\nE --> F[\"Nebulised salbutamol\"]:::good\nF --> G[\"Treat cause; dialysis if refractory\"]:::good\nC -- \"mild, no ECG change\" --> H[\"Stop K+ drugs, treat cause, recheck\"]:::good", "tips": {"A": "Serum potassium above 5.5 mmol/L; causes include acute kidney injury, drugs (ACE inhibitors, ARBs, potassium-sparing diuretics, NSAIDs), Addison disease and acidosis.", "B": "Do an immediate 12-lead ECG - it decides urgency.", "C": "Emergency if there are ECG changes (tall tented T waves, flat P waves, broad QRS, sine wave) or potassium 6.5 mmol/L or more.", "D": "IV calcium gluconate stabilises the myocardium; it does not lower potassium - repeat if ECG changes persist.", "E": "Insulin (with dextrose to prevent hypoglycaemia) shifts potassium into cells; monitor glucose.", "F": "Nebulised salbutamol adds further intracellular shift.", "G": "Treat the cause, stop offending drugs, and remove potassium from the body (loop diuretic, potassium binder, or dialysis if refractory).", "H": "Mild hyperkalaemia with a normal ECG: stop contributing drugs and potassium intake, treat the cause, and recheck (exclude a haemolysed sample)."}}, cluster: "Electrolyte disturbance", name: "Hyperkalaemia", keyFacts: "A raised serum potassium that can precipitate fatal arrhythmia; it needs urgent ECG and treatment.", epidemiology: "Common in hospital, especially with renal impairment and certain drugs.", aetiology: "Renal failure, ACE inhibitors and ARBs, potassium-sparing diuretics, Addison's, acidosis and tissue breakdown.", pathophysiology: "Excess extracellular potassium lowers the cardiac resting membrane potential, causing the ECG changes and the risk of arrhythmia.", presentation: "Often asymptomatic; weakness, palpitations; ECG changes risk arrhythmia.", investigations: "U&E, venous gas, ECG (tall T waves, wide QRS), review drugs.", treatment: "IV calcium gluconate to protect heart, insulin-dextrose and salbutamol to shift; treat cause." },
      { id: "endo_hyponatraemia", management: {"def": "A[\"Hyponatraemia (Na under 135)\"]:::start --> B{\"Severe symptoms? (seizures, coma)\"}:::decision\nB -- \"yes\" --> C[\"Hypertonic 3 percent saline (senior-led)\"]:::danger\nB -- \"no\" --> D{\"Volume status?\"}:::decision\nD -- \"hypovolaemic\" --> E[\"IV 0.9 percent saline, treat losses\"]:::good\nD -- \"euvolaemic (e.g. SIADH)\" --> F[\"Fluid restriction, treat cause\"]:::good\nD -- \"hypervolaemic (HF, cirrhosis)\" --> G[\"Fluid and salt restriction, treat cause\"]:::good\nA --> H[\"Correct slowly: avoid osmotic demyelination\"]:::warn", "tips": {"A": "A low serum sodium (under 135 mmol/L), the commonest electrolyte abnormality; symptoms depend on severity and speed of onset (nausea, confusion, seizures).", "B": "Severe symptoms (seizures, reduced consciousness) indicate acute or severe hyponatraemia needing urgent treatment.", "C": "Severe symptomatic hyponatraemia: cautious boluses of hypertonic (3%) saline under senior or critical-care guidance to raise sodium just enough to stop symptoms.", "D": "For non-severe cases, classify by fluid (volume) status - this points to the cause and treatment.", "E": "Hypovolaemic (diuretics, vomiting/diarrhoea, Addison's): replace volume with IV 0.9% saline and treat the losses.", "F": "Euvolaemic (commonly SIADH, also hypothyroidism, adrenal insufficiency): fluid restriction and treat the cause; consider tolvaptan in resistant SIADH.", "G": "Hypervolaemic (heart failure, cirrhosis, nephrotic, renal failure): fluid and salt restriction and treat the underlying condition (diuretics).", "H": "Correct sodium SLOWLY (no more than about 10 mmol/L in 24 hours) - over-rapid correction causes central pontine myelinolysis (osmotic demyelination syndrome)."}}, cluster: "Electrolyte disturbance", name: "Hyponatraemia", keyFacts: "A low serum sodium classified by fluid status; over-rapid correction risks osmotic demyelination.", epidemiology: "The commonest electrolyte abnormality in hospital.", aetiology: "Hypovolaemic (fluid losses), euvolaemic (SIADH, hypothyroidism) or hypervolaemic (heart failure, cirrhosis).", pathophysiology: "Relative water excess dilutes serum sodium; the brain adapts, so rapid correction can cause central pontine myelinolysis.", presentation: "Nausea, confusion, seizures when severe; assess fluid status.", investigations: "Serum and urine osmolality, urine sodium, TFTs, cortisol; classify by volume status.", treatment: "Treat cause; fluid restrict in SIADH; cautious correction to avoid osmotic demyelination." },
      { id: "endo_hypocalcaemia", management: {"def": "A[\"Hypocalcaemia: albumin-corrected calcium below 2.20\"]:::start --> B{\"Severe or symptomatic? tetany, seizures, long QT, or calcium below 1.9\"}:::decision\nB -- \"yes\" --> C[\"IV 10 percent calcium gluconate 10 to 20 mL over 10 min, cardiac monitor\"]:::danger\nC --> D[\"Repeat until symptoms settle, then a calcium gluconate infusion\"]:::warn\nB -- \"no\" --> E[\"Oral calcium plus vitamin D\"]:::good\nD --> F[\"Check and correct MAGNESIUM\"]:::warn\nE --> F\nF --> G[\"Measure PTH to identify the cause\"]:::process\nG --> H{\"PTH level\"}:::decision\nH -- \"low or inappropriately normal\" --> I[\"Hypoparathyroidism: alfacalcidol, aim for low-normal calcium\"]:::good\nH -- \"raised\" --> J[\"Vitamin D deficiency or CKD: colecalciferol, or alfacalcidol if CKD\"]:::good\nI --> K[\"Monitor calcium, phosphate and urinary calcium\"]:::good\nJ --> K", "tips": {"A": "Hypocalcaemia is an albumin-corrected serum calcium below 2.20 mmol/L. Because roughly half of circulating calcium is protein-bound, ALWAYS use the adjusted (corrected) calcium or measure ionised calcium: a low albumin gives a low total calcium with a normal ionised fraction and needs no treatment. Symptoms depend on the rate of fall as much as the absolute level.", "B": "Decide severity immediately. Treat as an emergency if there is tetany, carpopedal spasm, laryngospasm, seizures, or ECG changes (prolonged QT with risk of arrhythmia), or if the adjusted calcium is below about 1.9 mmol/L even without symptoms. Look for Trousseau's sign (carpal spasm on inflating a blood pressure cuff) and Chvostek's sign (facial twitch on tapping over the facial nerve).", "C": "Give 10 to 20 mL of 10% calcium gluconate (10 mL contains about 2.26 mmol of calcium) diluted in 50 to 100 mL of 5% glucose intravenously over 10 minutes, with cardiac monitoring. Calcium chloride is more irritant and is generally avoided. Extravasation causes tissue necrosis, so use a secure large vein.", "D": "Repeat boluses until symptoms settle, then set up a continuous calcium gluconate infusion, since a single bolus raises calcium for only 2 to 3 hours. Recheck calcium regularly, and use extreme caution in anyone taking digoxin because calcium potentiates digoxin toxicity.", "E": "Mild asymptomatic hypocalcaemia is treated orally with a calcium salt plus vitamin D, alongside treating the underlying cause.", "F": "This is the classic trap: hypocalcaemia is REFRACTORY to calcium replacement until magnesium is corrected, because hypomagnesaemia both impairs PTH secretion and causes end-organ PTH resistance. Always check and replace magnesium.", "G": "Parathyroid hormone measured at the same time as a low calcium is the key discriminator, and separates the causes into two clean groups.", "H": "A low or inappropriately normal PTH in the face of hypocalcaemia means the parathyroids are failing; a raised PTH means they are responding appropriately and the problem lies elsewhere.", "I": "Low or inappropriately normal PTH indicates hypoparathyroidism, most often after thyroid, parathyroid or other neck surgery, but also autoimmune or congenital (DiGeorge syndrome). Treat with an activated vitamin D analogue such as alfacalcidol, because 1-alpha-hydroxylation is PTH-dependent. Aim for a calcium at the LOW end of normal, since normalising it fully causes hypercalciuria, nephrolithiasis and nephrocalcinosis. Pseudohypoparathyroidism (PTH resistance) gives a raised PTH with the same clinical picture.", "J": "A raised PTH is an appropriate secondary response. The usual causes are vitamin D deficiency (treat with colecalciferol) and chronic kidney disease, where impaired 1-alpha-hydroxylation and phosphate retention mean an activated analogue such as alfacalcidol is needed. Other causes of hypocalcaemia with a raised PTH include acute pancreatitis (calcium soaps in fat necrosis), rhabdomyolysis and tumour lysis (phosphate binding), massive transfusion (citrate chelation) and drugs such as bisphosphonates and denosumab.", "K": "Monitor calcium, phosphate, magnesium and renal function, and check urinary calcium in anyone on long-term activated vitamin D. After thyroid or parathyroid surgery, calcium must be checked closely because hypocalcaemia may be transient or permanent."}, "source": "Society for Endocrinology"}, cluster: "Electrolyte disturbance", name: "Hypocalcaemia", keyFacts: "An albumin-corrected serum calcium below 2.20 mmol/L. Symptoms reflect increased neuromuscular excitability and depend on the rate of fall as much as the level; severe or symptomatic hypocalcaemia is an emergency requiring intravenous calcium.", epidemiology: "Common among hospital inpatients. The commonest surgical cause is thyroid or parathyroid surgery, and the commonest medical causes are vitamin D deficiency and chronic kidney disease.", aetiology: "Grouped by PTH. With a LOW or inappropriately normal PTH: hypoparathyroidism, most often post-surgical (thyroid, parathyroid or neck), and also autoimmune or congenital (DiGeorge syndrome); hypomagnesaemia, which impairs both PTH secretion and its action. With a RAISED PTH: vitamin D deficiency, chronic kidney disease, pseudohypoparathyroidism (PTH resistance), acute pancreatitis, rhabdomyolysis and tumour lysis syndrome, massive transfusion (citrate chelation), and drugs including bisphosphonates, denosumab, calcimimetics and foscarnet. Respiratory alkalosis lowers ionised calcium while total calcium stays normal.", pathophysiology: "About half of serum calcium is bound to albumin, so total calcium must be corrected for albumin or the ionised fraction measured. A fall in ionised calcium lowers the threshold for nerve and muscle depolarisation, producing paraesthesiae, tetany, laryngospasm and seizures, and prolongs myocardial repolarisation, producing a long QT interval and a risk of ventricular arrhythmia.", presentation: "Perioral and digital paraesthesiae, muscle cramps, carpopedal spasm and tetany, with Trousseau's sign (carpal spasm on inflating a blood pressure cuff) and Chvostek's sign (facial twitching on tapping over the facial nerve). Severe cases cause laryngospasm and stridor, bronchospasm, seizures, a prolonged QT with arrhythmia, and impaired cardiac contractility. Chronic hypocalcaemia causes cataracts, basal ganglia calcification, papilloedema, dry skin and brittle nails. Mild or slowly developing hypocalcaemia is often asymptomatic.", investigations: "Albumin-corrected calcium (or ionised calcium), magnesium, phosphate and PTH taken together, since PTH is the key discriminator; U and Es with eGFR; vitamin D and alkaline phosphatase; and an ECG looking for a prolonged QT. Consider amylase or lipase for pancreatitis and creatine kinase for rhabdomyolysis, and check calcium closely after neck surgery.", treatment: "Severe or symptomatic hypocalcaemia: IV 10% calcium gluconate 10 to 20 mL diluted in 50 to 100 mL of 5% glucose over 10 minutes with cardiac monitoring, repeated until symptoms settle, then a continuous infusion; use great caution in patients on digoxin. ALWAYS check and correct magnesium, as hypocalcaemia is refractory until this is done. Mild cases: oral calcium with colecalciferol, or an activated analogue such as alfacalcidol where 1-alpha-hydroxylation is impaired (hypoparathyroidism, chronic kidney disease). Treat the cause, and in hypoparathyroidism aim for a low-normal calcium to avoid hypercalciuria and nephrocalcinosis." },
      { id: "endo_hypercalcaemia", management: { def: "A[\"Raised calcium - always use the ALBUMIN-ADJUSTED value\"]:::start --> B[\"Send adjusted calcium, phosphate, PTH and U and E together, plus an ECG for a short QT\"]:::process\nB --> C{\"Adjusted calcium\"}:::decision\nC -- \"under 3.0\" --> D[\"Often asymptomatic - no urgent correction needed\"]:::good\nC -- \"3.0 to 3.5\" --> E[\"Often symptomatic - prompt treatment usually indicated\"]:::warn\nC -- \"over 3.5\" --> F[\"URGENT correction - risk of dysrhythmia and coma\"]:::danger\nE --> G[\"IV 0.9 percent saline 4 to 6 L over 24 hours - rehydration is first and most important\"]:::good\nF --> G\nG --> H[\"Loop diuretics ONLY if fluid overload develops - they do NOT lower calcium\"]:::warn\nH --> I{\"Still hypercalcaemic after rehydration\"}:::decision\nI -- \"yes\" --> J[\"IV bisphosphonate - zoledronic acid 4 mg over 15 min, nadir at 2 to 4 days\"]:::good\nI -- \"no\" --> K[\"Continue fluids, stop culprit drugs - thiazides, lithium, calcium and vitamin D\"]:::good\nJ --> L[\"Reduce the dose and infuse more slowly in renal impairment - watch for rebound hypocalcaemia\"]:::warn\nD --> M{\"PTH level\"}:::decision\nK --> M\nL --> M\nM -- \"raised or inappropriately normal\" --> N[\"PTH-DRIVEN - primary or tertiary hyperparathyroidism\"]:::warn\nM -- \"suppressed\" --> O[\"PTH-INDEPENDENT - MALIGNANCY until proved otherwise\"]:::danger\nN --> P[\"Exclude familial hypocalciuric hypercalcaemia, then see the Hyperparathyroidism entry\"]:::good\nO --> Q[\"Myeloma screen and imaging - prednisolone 40 mg daily if lymphoma, granulomatous disease or vitamin D toxicity\"]:::good", tips: { A: "Always act on the ALBUMIN-ADJUSTED calcium, never the total. Roughly half of serum calcium is albumin-bound, so a low albumin - common in malignancy, sepsis and liver disease, which is exactly this population - will mask a genuinely high ionised calcium. The correction adds about 0.02 mmol/L for every 1 g/L the albumin sits below 40.", B: "Send the whole panel at once rather than sequentially, because PTH taken at the time of the hypercalcaemia is what interprets everything else - a PTH sent after treatment has started is much harder to read. The ECG change to look for is a SHORTENED QT interval, the mirror image of hypocalcaemia.", C: "The Society for Endocrinology grades urgency by the adjusted calcium, and this is the practical triage.", D: "Below 3.0 mmol/L hypercalcaemia is often asymptomatic and does not usually need urgent correction - but it still needs a cause, and this is where most primary hyperparathyroidism is picked up incidentally.", E: "Between 3.0 and 3.5 mmol/L may be surprisingly well tolerated if it has risen slowly, but is often symptomatic and prompt treatment is usually indicated. Rate of rise matters as much as the absolute number.", F: "Above 3.5 mmol/L requires urgent correction because of the risk of dysrhythmia and coma. A rapidly rising calcium in an unwell patient is usually malignancy.", G: "REHYDRATION IS THE TREATMENT. Hypercalcaemia causes a nephrogenic diabetes insipidus, so these patients are profoundly volume deplete - and volume depletion reduces renal calcium excretion, which drives the calcium higher still. Breaking that cycle with 4 to 6 litres of 0.9% sodium chloride over 24 hours does most of the work. Monitor closely for fluid overload in the elderly and in renal impairment, and consider dialysis if there is severe renal failure.", H: "This is the classic outdated teaching to unlearn. Furosemide was historically given routinely to promote calciuresis - the Society for Endocrinology is explicit that loop diuretics are RARELY used, only if fluid overload develops, and are NOT effective at reducing serum calcium. Giving them to a volume-deplete patient makes things worse.", I: "Reassess after rehydration rather than giving a bisphosphonate reflexively - saline alone corrects a significant proportion, and a bisphosphonate given to a still-dehydrated patient risks nephrotoxicity.", J: "Zoledronic acid 4 mg over 15 minutes is first choice and is superior to pamidronate for hypercalcaemia of malignancy. Alternatives are pamidronate 30 to 90 mg infused at 20 mg/h, or ibandronic acid 2 to 4 mg. The effect is NOT immediate - the calcium reaches its nadir at 2 to 4 days, so do not judge failure too early.", K: "Review the drug chart in every case: thiazide diuretics, lithium, and calcium or vitamin D supplements are common and reversible contributors.", L: "Bisphosphonates are renally cleared, so reduce the dose and infuse more slowly in renal impairment. They can precipitate symptomatic HYPOcalcaemia where vitamin D is deficient or PTH is suppressed - check and replace vitamin D.", M: "PTH is the single test that splits the differential, and 90% of all hypercalcaemia is either primary hyperparathyroidism or malignancy.", N: "A raised or even inappropriately NORMAL PTH in the face of hypercalcaemia is abnormal - a healthy parathyroid would be fully suppressed. This means primary hyperparathyroidism (or tertiary, in long-standing kidney disease).", O: "A suppressed PTH means the drive is coming from somewhere else, and in an unwell patient that is malignancy until proved otherwise. The mechanisms are PTH-related peptide from squamous tumours, osteolytic bone metastases, and 1,25-dihydroxyvitamin D produced by lymphoma. Rarely, ectopic PTH.", P: "FAMILIAL HYPOCALCIURIC HYPERCALCAEMIA is the mimic that matters, because it produces hypercalcaemia with an inappropriately normal or raised PTH and is easily mislabelled as primary hyperparathyroidism - but it is benign and must NOT be operated on. Distinguish it with a urinary calcium to creatinine clearance ratio below 0.01. It is rarely severe and rarely presents as an emergency. Acute parathyroidectomy can be considered for severe primary hyperparathyroidism that fails to respond.", Q: "Hunt the tumour: myeloma screen, chest imaging, examination of breasts, lymph nodes and abdomen. Where the cause is excess 1,25-dihydroxyvitamin D - lymphoma, sarcoidosis and other granulomatous disease, or vitamin D poisoning - GLUCOCORTICOIDS work by inhibiting its production: prednisolone 40 mg daily, usually effective within 2 to 4 days. Calcimimetics, denosumab and calcitonin are specialist second-line options where the response is poor." }, source: "Society for Endocrinology" }, complications: "Acute: cardiac dysrhythmia from a shortened QT interval, and coma\nAcute kidney injury from the volume depletion of nephrogenic diabetes insipidus\nChronic: nephrolithiasis, nephrocalcinosis and chronic kidney disease\nOsteoporosis and fragility fracture, pancreatitis and peptic ulceration\nBand keratopathy in long-standing disease\nTreatment-related: rebound HYPOcalcaemia after a bisphosphonate (especially if vitamin D deficient or PTH suppressed), and fluid overload from aggressive rehydration in the elderly or renally impaired", cluster: "Electrolyte disturbance", name: "Hypercalcaemia", keyFacts: "A raised albumin-adjusted serum calcium. Ninety percent is either primary hyperparathyroidism or malignancy, and PTH is the single test that separates them.", epidemiology: "Common. Primary hyperparathyroidism predominates in the community, typically found incidentally in a post-menopausal woman; malignancy predominates in hospital inpatients and causes the more severe, rapidly rising cases.", aetiology: "Ninety percent is primary hyperparathyroidism or malignancy (via PTH-related peptide from squamous tumours, osteolytic bone metastases, or 1,25-dihydroxyvitamin D from lymphoma). Less common: thiazide diuretics, lithium, familial hypocalciuric hypercalcaemia, granulomatous disease (sarcoidosis, tuberculosis), thyrotoxicosis, tertiary hyperparathyroidism, vitamin D or vitamin A excess, immobilisation, rhabdomyolysis, adrenal insufficiency, milk-alkali syndrome, theophylline toxicity and phaeochromocytoma.", pathophysiology: "Calcium rises when PTH-driven bone resorption and renal reabsorption are excessive, when tumour products mimic them, or when bone is destroyed directly by metastases. Hypercalcaemia then causes a nephrogenic diabetes insipidus, so polyuria produces volume depletion, which itself reduces renal calcium excretion and drives the calcium higher - the vicious cycle that makes rehydration the priority.", presentation: "The classic 'bones, stones, abdominal moans and psychic groans'. Polyuria and thirst; anorexia, nausea, vomiting and constipation; mood disturbance, cognitive impairment, confusion and coma; muscle weakness; renal impairment. Also nephrolithiasis and nephrocalcinosis, pancreatitis, peptic ulceration, hypertension and cardiomyopathy, and band keratopathy in chronic disease.", investigations: "ALBUMIN-ADJUSTED calcium (a low albumin masks a high calcium), with phosphate, PTH and U&E sent together, plus an ECG for a SHORTENED QT interval. PTH is the discriminator: raised or inappropriately normal indicates primary or tertiary hyperparathyroidism, or familial hypocalciuric hypercalcaemia (urinary calcium:creatinine clearance ratio below 0.01); suppressed PTH indicates malignancy or another PTH-independent cause, so proceed to myeloma screen, imaging, vitamin D metabolites and ACE.", treatment: "Severity sets the urgency: below 3.0 mmol/L rarely needs urgent correction, 3.0-3.5 usually does, above 3.5 is urgent because of dysrhythmia and coma. IV 0.9% sodium chloride 4-6 L over 24 hours is the first and most important step, monitoring for overload in the elderly or renally impaired. LOOP DIURETICS ARE NOT ROUTINE - only if fluid overload develops, since they do not lower calcium. If still hypercalcaemic, give an IV bisphosphonate: zoledronic acid 4 mg over 15 minutes (or pamidronate 30-90 mg at 20 mg/h), dose-reduced and slowed in renal impairment, with the nadir at 2-4 days. Second-line under specialist advice: prednisolone 40 mg daily for lymphoma, granulomatous disease or vitamin D toxicity; calcimimetics, denosumab or calcitonin; dialysis in severe renal failure; acute parathyroidectomy for refractory primary hyperparathyroidism. Stop thiazides, lithium and calcium or vitamin D supplements." },
      { id: "endo_obesity", cluster: "Metabolic & general", name: "Obesity", keyFacts: "Excess body fat (a raised body mass index) that drives metabolic, cardiovascular and joint disease.", epidemiology: "Highly prevalent and rising across all ages in the UK.", aetiology: "A chronic energy imbalance from diet and inactivity, with genetic, endocrine and socioeconomic contributors.", pathophysiology: "Positive energy balance expands adipose tissue, promoting insulin resistance, inflammation and mechanical and metabolic complications.", presentation: "Raised BMI with associated metabolic, joint and psychological complications.", investigations: "BMI, waist circumference, HbA1c, lipids, blood pressure, liver screen.", treatment: "Diet, activity, behavioural support; orlistat; GLP-1 agonists; bariatric surgery in selected patients." },
      { id: "endo_amenorrhoea", cluster: "Metabolic & general", name: "Amenorrhoea", keyFacts: "Absence of menstruation, primary (never started) or secondary (stopped for 6 months or more); always exclude pregnancy first.", epidemiology: "Common; secondary amenorrhoea has many endocrine causes.", aetiology: "Pregnancy, hypothalamic (weight loss, stress, exercise), PCOS, hyperprolactinaemia, thyroid disease, premature ovarian insufficiency; primary causes include Turner's syndrome and outflow obstruction.", pathophysiology: "Disruption anywhere along the hypothalamic-pituitary-ovarian axis, or an anatomical outflow obstruction, stops cyclical menstruation.", presentation: "No periods, with features of the underlying cause (galactorrhoea, hirsutism, hot flushes, weight change).", investigations: "Pregnancy test first; FSH/LH, oestradiol, prolactin, TFTs, testosterone; pelvic ultrasound.", treatment: "Treat the cause; restore energy balance; hormone replacement where appropriate; refer for fertility if needed." },
      { id: "endo_cfs", cluster: "Metabolic & general", name: "Chronic fatigue syndrome", keyFacts: "Also called myalgic encephalomyelitis: persistent disabling fatigue with post-exertional malaise and no alternative cause.", epidemiology: "Commoner in women and often follows a viral illness.", aetiology: "Unknown and frequently post-infective, with no consistent biochemical abnormality.", pathophysiology: "Poorly understood, with proposed immune, neuroendocrine and autonomic dysregulation; it remains a clinical diagnosis of exclusion.", presentation: "Disabling fatigue beyond 3 months, post-exertional malaise, unrefreshing sleep, cognitive difficulty (brain fog), myalgia.", investigations: "No diagnostic test; targeted bloods (FBC, TFTs, coeliac serology, glucose, inflammatory markers) to exclude other causes.", treatment: "Individualised activity management and energy pacing, sleep and symptom support; avoid prescriptive graded exercise; manage comorbid mood." },
    ],
  },
  {
    id: "renal",
    name: "Renal & Urology",
    icon: "🫘",
    conditions: [
      { id: "renal_aki", management: {"def": "A[\"Acute kidney injury\"]:::start --> B{\"Cause?\"}:::decision\nB -- \"pre-renal\" --> C[\"Optimise fluids and blood pressure\"]:::good\nB -- \"post-renal (obstruction)\" --> D[\"Relieve obstruction (catheter/nephrostomy)\"]:::good\nB -- \"intrinsic renal\" --> E[\"Treat the cause (nephritis, drugs)\"]:::good\nA --> F[\"STOP nephrotoxins, review drugs, treat hyperkalaemia\"]:::warn\nC --> G[\"Monitor bloods and fluid balance\"]:::process\nG --> H[\"Renal replacement if refractory\"]:::danger", "tips": {"A": "An abrupt fall in kidney function (rising creatinine or falling urine output). Classify the cause to direct treatment.", "B": "Determine whether it is pre-renal, intrinsic renal or post-renal (obstructive).", "C": "Pre-renal (commonest - hypovolaemia, sepsis, low output): restore circulating volume with IV fluids and treat the cause; avoid over-filling if oliguric.", "D": "Post-renal: image (ultrasound) for obstruction and relieve it (urinary catheter, or nephrostomy/stent for the upper tract).", "E": "Intrinsic renal (acute tubular necrosis, glomerulonephritis, interstitial nephritis): treat the underlying cause and stop the insult.", "F": "Stop nephrotoxic drugs (NSAIDs, ACE inhibitors/ARBs, aminoglycosides, contrast) and review dosing; urgently treat hyperkalaemia and acidosis.", "G": "Monitor renal function, fluid balance and urine output; watch for complications.", "H": "Refer for renal replacement therapy (dialysis) if refractory hyperkalaemia, severe acidosis, fluid overload (pulmonary oedema) or uraemic complications (pericarditis, encephalopathy)."}}, cluster: "Acute & chronic kidney disease", name: "Acute kidney injury", keyFacts: "An abrupt fall in kidney function over hours to days, defined by a rising creatinine or falling urine output.", epidemiology: "Common in acutely unwell and hospitalised patients.", aetiology: "Pre-renal (hypoperfusion), renal (drugs, glomerulonephritis, acute tubular necrosis) or post-renal (obstruction).", pathophysiology: "Reduced perfusion, intrinsic damage or obstruction lowers the glomerular filtration rate, causing retention of waste, fluid and potassium.", presentation: "Reduced urine output, rising creatinine; oliguria, fluid overload or uraemia.", investigations: "U&E, urinalysis, fluid assessment, ultrasound, review nephrotoxic drugs.", treatment: "Treat cause, optimise fluids, stop nephrotoxics; dialysis for refractory hyperkalaemia, acidosis or overload." },
      { id: "renal_ckd", management: {"def": "A[\"Chronic kidney disease\"]:::start --> B[\"Assess: eGFR, urine ACR, blood pressure, cause\"]:::process\nB --> C[\"ACE inhibitor or ARB if ACR raised, titrate to highest tolerated dose\"]:::good\nC --> D[\"Add an SGLT2 inhibitor if eligible\"]:::good\nD --> E{\"Type 2 diabetes with ACR 3 or above, eGFR 25 or above, still progressing?\"}:::decision\nE -- \"yes\" --> F[\"Add finerenone on top of optimised ACEi/ARB and SGLT2i\"]:::good\nE -- \"no\" --> G[\"Atorvastatin 20 mg, BP and lifestyle optimisation\"]:::good\nF --> G\nA --> H{\"Complications or progression?\"}:::decision\nH -- \"anaemia\" --> I[\"Iron, then an erythropoiesis-stimulating agent\"]:::good\nH -- \"renal bone disease\" --> J[\"Phosphate binders and activated vitamin D\"]:::good\nH -- \"eGFR under 30 or rapid decline\" --> K[\"Refer to nephrology\"]:::warn", "tips": {"A": "Chronic kidney disease is abnormal kidney function or structure present for more than 3 months. Classify by BOTH eGFR (G1 to G5) and albuminuria (A1 to A3), because albuminuria drives risk and treatment independently of eGFR (NICE NG203).", "B": "Assess eGFR (confirm a first abnormal result within 2 weeks), urine albumin-to-creatinine ratio on an early morning sample, blood pressure, and the underlying cause. Use the eGFR and ACR together to estimate the risk of progression, and check for a rapidly declining eGFR.", "C": "Offer an ACE inhibitor or angiotensin receptor blocker where ACR is raised — from 3 mg/mmol or more with diabetes, 30 or more with hypertension, and 70 or more regardless. Titrate to the highest licensed tolerated dose. Check potassium and eGFR before starting and after each titration, accept an eGFR fall of up to 25%, and do not combine an ACE inhibitor with an ARB.", "D": "Add an SGLT2 inhibitor (dapagliflozin or empagliflozin) for its renal and cardiovascular protection. In type 2 diabetes with CKD this is now standard, and NICE NG28 (updated February 2026) offers metformin plus an SGLT2 inhibitor as first-line dual therapy. SGLT2 inhibitors keep their cardio-renal benefit below an eGFR of 45 even though their glucose-lowering effect fades.", "E": "The newest addition to diabetic kidney disease care: assess whether a non-steroidal mineralocorticoid receptor antagonist is indicated on top of the first two pillars.", "F": "NICE TA877 recommends FINERENONE for stage 3 to 4 CKD with albuminuria (ACR persistently 3 mg/mmol or more) in type 2 diabetes, as an add-on to optimised standard care — which should already include the highest tolerated doses of an ACE inhibitor or ARB AND an SGLT2 inhibitor — provided eGFR is 25 mL/min/1.73m2 or above. It reduces CKD progression and cardiovascular events. Monitor potassium closely, since hyperkalaemia is the main adverse effect, and avoid starting if potassium is above 5.0 mmol/L.", "G": "Offer atorvastatin 20 mg for primary or secondary prevention of cardiovascular disease in CKD, and increase the dose if a greater than 40% reduction in non-HDL cholesterol is not achieved. Optimise blood pressure to below 130/80 mmHg where ACR is 70 or above, and support smoking cessation, weight, exercise and dietary sodium reduction.", "H": "Alongside slowing progression, actively look for the metabolic complications of CKD and the features that warrant specialist referral.", "I": "Investigate and treat anaemia of CKD: check haematinics and correct iron deficiency first (usually intravenous iron), then consider an erythropoiesis-stimulating agent, aiming for a haemoglobin of 100 to 120 g/L rather than normalising it.", "J": "Manage renal bone disease (CKD-mineral and bone disorder) with dietary phosphate restriction and phosphate binders, and activated vitamin D such as alfacalcidol for secondary hyperparathyroidism. Do not offer bisphosphonates if eGFR is below 30 without specialist advice.", "K": "Refer to nephrology for an eGFR below 30, an ACR of 70 or more (unless known to be due to diabetes and already treated), a sustained decrease in eGFR of 25% or more with a change in category, rapid progression, suspected genetic or rare cause, uncontrolled hypertension on four agents, or suspected renal artery stenosis. Discuss dialysis and transplantation planning well before end-stage disease."}, "source": "NICE NG203 / TA877"}, cluster: "Acute & chronic kidney disease", name: "Chronic kidney disease", keyFacts: "A long-standing, usually progressive reduction in kidney function, staged by eGFR and albuminuria.", epidemiology: "Common, particularly in the elderly, diabetics and hypertensives.", aetiology: "Diabetes and hypertension are the leading causes; also glomerular, polycystic and obstructive disease.", pathophysiology: "Progressive nephron loss reduces filtration, causing fluid and waste retention, anaemia, renal bone disease and cardiovascular risk.", presentation: "Often asymptomatic; fatigue, oedema, anaemia, bone disease in advanced disease.", investigations: "eGFR and ACR over time, U&E, renal ultrasound, urinalysis.", treatment: "Control BP with ACE-i/ARB, SGLT2 inhibitor, treat anaemia/bone disease; plan dialysis/transplant if progressive." },
      { id: "renal_nephrotic", cluster: "Glomerular disease", name: "Nephrotic syndrome", keyFacts: "Heavy proteinuria with hypoalbuminaemia and oedema; it raises thrombosis and infection risk.", epidemiology: "Minimal change disease is the commonest cause in children, with varied causes in adults.", aetiology: "Primary glomerular disease (minimal change, membranous, FSGS) or secondary to diabetes, lupus or amyloid.", pathophysiology: "Damage to the glomerular basement membrane lets protein leak into the urine; low albumin reduces oncotic pressure, causing oedema.", presentation: "Heavy proteinuria, oedema, hypoalbuminaemia, hyperlipidaemia.", investigations: "Urine ACR/PCR, albumin, lipids, renal biopsy, autoimmune screen.", treatment: "Treat cause, steroids (e.g. minimal change), ACE-i/ARB, manage oedema and thrombosis risk." },
      { id: "renal_iga", cluster: "Glomerular disease", name: "IgA nephropathy", keyFacts: "The commonest primary glomerulonephritis; classically visible haematuria a day or two after an upper respiratory infection.", epidemiology: "Commonest in young adults, particularly men.", aetiology: "Deposition of IgA immune complexes in the glomerular mesangium; related to IgA vasculitis (Henoch-Schonlein purpura).", pathophysiology: "Mesangial IgA deposits trigger inflammation and mesangial proliferation, causing haematuria and, over time, progressive damage.", presentation: "Visible haematuria within 1-2 days of an upper respiratory infection (synpharyngitic), or asymptomatic microscopic haematuria and proteinuria.", investigations: "Urinalysis, U&E, IgA level, renal biopsy (mesangial IgA deposits).", treatment: "ACE inhibitor or ARB with blood pressure control; corticosteroids for progressive disease; variable prognosis." },
      { id: "renal_membranous", cluster: "Glomerular disease", name: "Membranous nephropathy", keyFacts: "A leading cause of nephrotic syndrome in adults; often linked to anti-phospholipase A2 receptor antibodies.", epidemiology: "A common cause of adult nephrotic syndrome, especially in middle age.", aetiology: "Primary (anti-PLA2R antibodies) or secondary to malignancy, infections (hepatitis B), lupus or drugs.", pathophysiology: "Subepithelial immune-complex deposits thicken the glomerular basement membrane, causing heavy proteinuria, with a high venous thromboembolism risk (including renal vein thrombosis).", presentation: "Nephrotic syndrome (heavy proteinuria, oedema, hypoalbuminaemia); may present with a thrombotic complication.", investigations: "Urine protein quantification, albumin, lipids, anti-PLA2R antibody, renal biopsy; screen for secondary causes.", treatment: "ACE-i/ARB and supportive care; immunosuppression for high-risk disease; anticoagulation for thrombosis risk; treat any secondary cause." },
      { id: "renal_gpa", cluster: "Glomerular disease", name: "Granulomatosis with polyangiitis (GPA)", keyFacts: "A multisystem small-vessel ANCA-associated vasculitis (formerly Wegener's) with the classic triad of upper-airway, lung and kidney disease; c-ANCA (anti-PR3) positive in most.", epidemiology: "Rare; affects adults across both sexes, commoner in white populations.", aetiology: "An ANCA-associated small-vessel vasculitis of unknown trigger; cytoplasmic ANCA against proteinase-3 (c-ANCA/anti-PR3) is positive in around 90% and supports the diagnosis.", pathophysiology: "Necrotising granulomatous inflammation of small and medium vessels injures many organs; ANCA activate neutrophils that damage vessel walls, and in the kidney this produces a pauci-immune crescentic glomerulonephritis.", presentation: "Constitutional: fever, weight loss, malaise and night sweats. ENT (often the first clue): chronic sinusitis, nasal crusting and epistaxis, septal perforation with a saddle-nose deformity, otitis media with hearing loss, and subglottic stenosis causing stridor or hoarseness. Respiratory: cough, haemoptysis, pulmonary nodules that may cavitate, and life-threatening diffuse alveolar haemorrhage. Renal: a rapidly progressive (crescentic) glomerulonephritis with haematuria, proteinuria and rising creatinine. Eyes: scleritis, episcleritis and an orbital granuloma causing proptosis. Skin: palpable purpura, nodules and ulcers. Nerves: mononeuritis multiplex. Joints: arthralgia.", investigations: "c-ANCA (anti-PR3), urinalysis and renal function, CXR/CT chest (nodules, cavitation, haemorrhage), ENT and ophthalmic assessment, and biopsy (necrotising granulomatous vasculitis); CRP/ESR for activity.", treatment: "Induction with high-dose corticosteroids plus cyclophosphamide or rituximab; plasma exchange for severe renal disease or pulmonary haemorrhage; maintenance immunosuppression (azathioprine or rituximab) with monitoring for relapse." },
      { id: "renal_egpa", cluster: "Glomerular disease", name: "Eosinophilic granulomatosis with polyangiitis (EGPA)", keyFacts: "A multisystem small-vessel ANCA-associated vasculitis (formerly Churg-Strauss) defined by asthma and eosinophilia, with the heart and nerves at greatest risk.", epidemiology: "Rare; arises in adults with established asthma and allergic disease.", aetiology: "An ANCA-associated eosinophilic vasculitis; perinuclear ANCA against myeloperoxidase (p-ANCA/anti-MPO) is positive in a minority (about 40%), more often when there is renal or vasculitic disease.", pathophysiology: "Evolves through three phases: an allergic prodrome (asthma, rhinitis), then blood and tissue eosinophilia, then a systemic eosinophil-rich granulomatous small-vessel vasculitis that injures multiple organs.", presentation: "Respiratory (the hallmark): late-onset, often difficult asthma with allergic rhinitis and nasal polyps, plus eosinophilic pulmonary infiltrates. Blood: marked peripheral eosinophilia. Nerves: mononeuritis multiplex (for example foot or wrist drop) and peripheral neuropathy. Cardiac (the leading cause of death): eosinophilic myocarditis, cardiomyopathy, pericarditis, heart failure and arrhythmia. Skin: palpable purpura and nodules. Gastrointestinal: eosinophilic gastroenteritis with abdominal pain and bleeding. Renal: glomerulonephritis, though less prominent than in the other ANCA vasculitides. Constitutional: fever and weight loss.", investigations: "Eosinophil count (markedly raised), ANCA (p-ANCA/MPO in a minority), IgE, urinalysis and renal function, CXR/CT chest, ECG and echocardiography for cardiac involvement, nerve conduction studies, and biopsy.", treatment: "Corticosteroids are the mainstay; add immunosuppression (cyclophosphamide or rituximab) for organ-threatening cardiac, renal or neurological disease, and mepolizumab (anti-IL-5) for relapsing or refractory disease." },
      { id: "renal_interstitial_nephritis", cluster: "Tubulointerstitial & vascular", name: "Interstitial nephritis", keyFacts: "Inflammation of the renal interstitium, most often an acute allergic reaction to a drug.", epidemiology: "A common cause of drug-induced acute kidney injury.", aetiology: "Acute: drugs (NSAIDs, penicillins, proton pump inhibitors), infections, autoimmune disease. Chronic: long-term toxins (analgesics, lithium).", pathophysiology: "An immune-mediated inflammatory infiltrate of the tubulointerstitium impairs tubular and overall renal function.", presentation: "Acute kidney injury days to weeks after a drug, classically with fever, rash, arthralgia and eosinophilia (the allergic triad, often incomplete).", investigations: "U&E, urinalysis (sterile pyuria, white-cell casts, eosinophiluria), eosinophil count; renal biopsy confirms.", treatment: "Stop the causative drug; corticosteroids for severe or non-resolving disease; supportive renal care." },
      { id: "renal_rta", management: { def: "A[\"Normal anion gap (hyperchloraemic) metabolic acidosis\"]:::start --> B{\"Urinary anion gap\"}:::decision\nB -- \"negative\" --> C[\"Gastrointestinal bicarbonate loss - diarrhoea, ileostomy, fistula\"]:::good\nB -- \"positive\" --> D[\"Renal tubular acidosis - the kidney is not excreting acid\"]:::danger\nD --> E{\"Serum potassium\"}:::decision\nE -- \"HIGH\" --> F[\"TYPE 4 - hypoaldosteronism or aldosterone resistance\"]:::warn\nE -- \"LOW\" --> G{\"Urine pH during acidosis\"}:::decision\nG -- \"above 5.5\" --> H[\"TYPE 1 distal - cannot acidify the urine\"]:::warn\nG -- \"below 5.5\" --> I[\"TYPE 2 proximal - wastes filtered bicarbonate\"]:::warn\nF --> J[\"Check renin, aldosterone, cortisol and the drug chart - diabetic nephropathy is commonest\"]:::process\nH --> K[\"Look for Sjogren syndrome and other autoimmune disease, hypercalciuria - ultrasound for nephrocalcinosis\"]:::process\nI --> L[\"Screen for FANCONI - urine glucose, amino acids, phosphate, urate - and for myeloma\"]:::process\nJ --> M[\"Stop the culprit drug, restrict dietary potassium, loop diuretic, sodium bicarbonate\"]:::good\nK --> N[\"Oral alkali as POTASSIUM citrate, about 1 mmol/kg/day, lifelong\"]:::good\nL --> O[\"High-dose alkali plus potassium, consider a thiazide, replace phosphate and vitamin D\"]:::good\nM --> P[\"Treat the underlying cause and review the drug chart in every type\"]:::good\nN --> P\nO --> P", tips: { A: "Renal tubular acidosis is a group of tubular defects causing a NORMAL anion gap (hyperchloraemic) metabolic acidosis with normal or near-normal glomerular function. The anion gap is normal because chloride is reabsorbed in place of the lost bicarbonate. Contrast this with the RAISED anion gap acidoses - ketoacidosis, lactate, toxins, urate in renal failure.", B: "The urinary anion gap is the step most people skip, and it answers the only question that matters first: is the kidney or the gut losing the bicarbonate? It is calculated as urinary sodium plus potassium minus chloride, and works as an indirect measure of ammonium excretion.", C: "A NEGATIVE urinary anion gap means the kidney is excreting ammonium normally, so the bicarbonate is being lost somewhere else - almost always the gut. Diarrhoea is by far the commonest cause of a normal anion gap acidosis overall, well ahead of renal tubular acidosis.", D: "A POSITIVE urinary anion gap means the kidney is failing to excrete ammonium, and therefore failing to excrete acid. That is renal tubular acidosis.", E: "Potassium is the single most useful discriminator, because it splits the three relevant types immediately - and it is the one that gets tested.", F: "TYPE 4 is the ONLY type that causes HYPERkalaemia, which makes it the easiest to spot. It is also the commonest in adult practice. The acidosis is mild (bicarbonate usually 15 to 20) because the mechanism is indirect: aldosterone deficiency or resistance reduces distal sodium reabsorption and potassium secretion, and the resulting hyperkalaemia then suppresses renal ammoniagenesis.", G: "With a LOW potassium you are choosing between type 1 and type 2, and urine pH separates them.", H: "TYPE 1 (distal) is a failure of the alpha-intercalated cells to secrete acid, so the urine CANNOT be acidified - the pH stays ABOVE 5.5 even when the patient is systemically acidotic. This is the most severe type biochemically (bicarbonate often 10 to 14), and the one that causes nephrocalcinosis and stones.", I: "TYPE 2 (proximal) is a failure to reabsorb filtered bicarbonate. Bicarbonate is wasted until the serum level falls far enough for the remaining reabsorptive capacity to cope, at which point the urine CAN be acidified below 5.5 - which is why the acidosis is self-limiting at a lower bicarbonate, and why alkali therapy is largely wasted in the urine.", J: "Diabetic nephropathy causing hyporeninaemic hypoaldosteronism is the commonest cause. Then look at the drug chart, which is the other big contributor: ACE inhibitors, angiotensin receptor blockers, spironolactone, NSAIDs, trimethoprim, heparin and calcineurin inhibitors. Also consider Addison's disease, obstructive uropathy and sickle cell disease.", K: "Type 1 has the strongest autoimmune association of the three - SJOGREN SYNDROME is the classic, with rheumatoid arthritis and lupus also recognised. Also consider hypercalciuria and primary hyperparathyroidism, sickle cell disease, and drugs (amphotericin B, lithium). Image the kidneys: nephrocalcinosis and calcium phosphate stones form because alkaline urine, hypercalciuria and low urinary citrate all favour precipitation.", L: "Type 2 rarely occurs alone - it is usually part of a generalised proximal tubular defect, FANCONI SYNDROME, so look for glycosuria with a normal blood glucose, aminoaciduria, phosphaturia and uricosuria. In adults the cause is often MULTIPLE MYELOMA or a drug (tenofovir, acetazolamide, ifosfamide); in children, cystinosis or Wilson's disease.", M: "Type 4 is managed by removing the cause and controlling the potassium: stop the offending drug, restrict dietary potassium, and use a loop diuretic to promote kaliuresis, with sodium bicarbonate for the acidosis. FLUDROCORTISONE corrects the underlying deficiency and works, but it is second-line rather than the default, because it worsens hypertension, oedema and heart failure in exactly the patients who tend to have this.", N: "Give the alkali as a POTASSIUM salt (potassium citrate), which corrects the acidosis and the hypokalaemia together - roughly 1 mmol/kg/day, titrated to normalise the bicarbonate. Treatment is lifelong and genuinely disease-modifying: it prevents nephrocalcinosis, stones and bone disease, and restores growth in children.", O: "Type 2 needs much higher alkali doses because most of what you give is simply wasted in the urine, and the potassium falls further as bicarbonate is excreted - so potassium supplements are needed alongside. A THIAZIDE can help paradoxically, by inducing mild volume depletion that enhances proximal reabsorption. Replace phosphate and vitamin D where there is Fanconi syndrome.", P: "In every type the priority is the underlying cause - the drug chart in particular, since drug-induced renal tubular acidosis is common and reversible." }, source: "AJKD Core Curriculum" }, complications: "Type 1 (distal): NEPHROCALCINOSIS and calcium phosphate stones - the classic complication; rickets and osteomalacia; growth failure in children; hypokalaemic muscle weakness and even paralysis\nType 2 (proximal): hypophosphataemic rickets and osteomalacia from the accompanying Fanconi syndrome; growth failure; hypokalaemia\nType 4 (hyperkalaemic): hyperkalaemia severe enough to cause arrhythmia, especially alongside ACE inhibitors or potassium-sparing diuretics\nAll types: chronic acidosis causes bone demineralisation and, in children, impaired growth", cluster: "Tubulointerstitial & vascular", name: "Renal tubular acidosis", keyFacts: "A group of tubular defects causing a NORMAL anion gap (hyperchloraemic) metabolic acidosis with normal or near-normal kidney function. Serum potassium and urine pH separate the types: type 4 is hyperkalaemic, types 1 and 2 are hypokalaemic.", epidemiology: "Uncommon overall. Type 4 is the commonest in adult practice, mostly from diabetic nephropathy and drugs. Type 1 is the classic autoimmune association. Type 2 usually appears as part of Fanconi syndrome. Type 3 is vanishingly rare.", aetiology: "Type 1 (distal): idiopathic or inherited; autoimmune disease, especially SJOGREN SYNDROME, also rheumatoid arthritis and lupus; hypercalciuria and primary hyperparathyroidism; drugs (amphotericin B, lithium); sickle cell disease.\nType 2 (proximal): usually part of FANCONI SYNDROME - multiple myeloma, Wilson's disease, cystinosis; drugs (tenofovir, acetazolamide, ifosfamide); heavy metals such as lead.\nType 4 (hyperkalaemic): hypoaldosteronism or aldosterone resistance - DIABETIC NEPHROPATHY is the commonest cause; also Addison's disease, obstructive uropathy, sickle cell, and drugs (ACE inhibitors, ARBs, spironolactone, NSAIDs, trimethoprim, heparin, calcineurin inhibitors).\nType 3: a rare mixed proximal and distal defect from carbonic anhydrase II deficiency - not exam-relevant.", pathophysiology: "All types produce a normal anion gap hyperchloraemic acidosis, because chloride is reabsorbed in place of the bicarbonate that is lost or the acid that is retained.\nType 1 (distal): the alpha-intercalated cells of the distal tubule cannot secrete hydrogen ions, so the urine cannot be acidified and the daily acid load is retained.\nType 2 (proximal): the proximal tubule cannot reabsorb filtered bicarbonate, which is wasted until the serum level falls low enough for the remaining capacity to cope - so the acidosis is self-limiting at a lower bicarbonate.\nType 4 (hyperkalaemic): aldosterone deficiency or resistance reduces distal sodium reabsorption and potassium secretion; the resulting hyperkalaemia then suppresses renal ammoniagenesis, which is the main driver of the acidosis.", presentation: "Often asymptomatic and picked up on routine bloods.\nType 1 (distal): failure to thrive and growth failure in children, rickets or osteomalacia, and recurrent stones or nephrocalcinosis; profound hypokalaemia can cause muscle weakness or paralysis.\nType 2 (proximal): usually the features of Fanconi syndrome - polyuria, dehydration, hypophosphataemic rickets or osteomalacia and growth failure - with hypokalaemia.\nType 4 (hyperkalaemic): usually asymptomatic, found as unexplained hyperkalaemia with a mild acidosis in a patient with diabetes or on an ACE inhibitor.", investigations: "Common to all: normal anion gap hyperchloraemic acidosis on venous gas with U&E. A POSITIVE urinary anion gap (urinary sodium + potassium - chloride) confirms a renal cause and distinguishes it from gastrointestinal bicarbonate loss such as diarrhoea, where it is negative.\nType 1 (distal): LOW potassium with urine pH persistently ABOVE 5.5 despite acidosis; the most severe acidosis (bicarbonate often 10-14); renal ultrasound for nephrocalcinosis; autoantibodies and calcium studies.\nType 2 (proximal): LOW potassium with urine pH usually BELOW 5.5 once the bicarbonate has fallen; screen for Fanconi syndrome with urine glucose, amino acids, phosphate and urate; myeloma screen in adults.\nType 4 (hyperkalaemic): HIGH potassium - the only type that is - with a mild acidosis (bicarbonate 15-20) and urine pH usually below 5.5; renin, aldosterone, cortisol and a drug review.", treatment: "Treat the underlying cause and review the drug chart in every type - drug-induced disease is common and reversible.\nType 1 (distal): oral alkali given as POTASSIUM citrate, roughly 1 mmol/kg/day, correcting the acidosis and hypokalaemia together; lifelong, and prevents stones, nephrocalcinosis and bone disease.\nType 2 (proximal): high-dose alkali, though much is wasted in the urine, plus potassium supplements; a THIAZIDE can help by inducing mild volume depletion; replace phosphate and vitamin D if there is Fanconi syndrome.\nType 4 (hyperkalaemic): stop the offending drug, restrict dietary potassium, add a loop diuretic to promote kaliuresis, and give sodium bicarbonate for the acidosis. Fludrocortisone is effective but second-line, as it worsens hypertension, oedema and heart failure." },
      { id: "renal_analgesic_nephropathy", cluster: "Tubulointerstitial & vascular", name: "Analgesic nephropathy", keyFacts: "Chronic kidney damage from long-term heavy use of analgesics, classically NSAIDs and combination painkillers.", epidemiology: "Linked to years of regular analgesic use, often for chronic pain or headaches.", aetiology: "Prolonged use of NSAIDs and phenacetin-containing combination analgesics.", pathophysiology: "Chronic tubulointerstitial injury and papillary necrosis from reduced medullary blood flow and direct toxicity.", presentation: "Insidious chronic kidney disease, sterile pyuria, and papillary necrosis (haematuria or colic if a papilla sloughs).", investigations: "U&E, urinalysis, imaging (small kidneys, papillary necrosis); careful drug history.", treatment: "Stop the offending analgesics and give supportive renal care; remain vigilant for the raised long-term risk of urothelial cancer." },
      { id: "renal_ras", cluster: "Tubulointerstitial & vascular", name: "Renal artery stenosis", keyFacts: "Narrowing of a renal artery causing secondary hypertension and, when bilateral, renal impairment.", epidemiology: "Atherosclerotic disease in older patients; fibromuscular dysplasia in younger women.", aetiology: "Atherosclerosis (commonest) or fibromuscular dysplasia.", pathophysiology: "Reduced renal perfusion activates the renin-angiotensin-aldosterone system, raising blood pressure; ACE inhibitors can precipitate renal failure in bilateral disease.", presentation: "Resistant or young-onset hypertension, flash pulmonary oedema, an abdominal bruit, and a fall in renal function after starting an ACE inhibitor or ARB.", investigations: "Renal Doppler ultrasound, CT or MR angiography, U&E.", treatment: "Optimise medical therapy (cautious ACE-i/ARB, statin, antiplatelet, BP control); angioplasty with stenting for selected cases, especially fibromuscular dysplasia." },
      { id: "renal_adpkd", cluster: "Cystic kidney disease", name: "Autosomal dominant polycystic kidney disease (ADPKD)", keyFacts: "The commonest inherited kidney disease; progressive bilateral renal cysts leading to kidney failure in adulthood.", epidemiology: "A common inherited cause of end-stage renal disease, usually presenting in adulthood.", aetiology: "Autosomal dominant mutation in PKD1 (chromosome 16, commoner and more severe) or PKD2.", pathophysiology: "Progressive cyst formation enlarges the kidneys and destroys functioning parenchyma, with associated extrarenal cysts and aneurysms.", presentation: "Hypertension, loin pain, haematuria, recurrent UTIs and renal failure; extrarenal liver cysts, berry aneurysms (subarachnoid haemorrhage) and mitral valve prolapse.", investigations: "Renal ultrasound (cyst count by age criteria), U&E, BP, family history; genetic testing; MR angiography if aneurysm risk.", treatment: "Blood pressure control, tolvaptan to slow progression in selected patients, treat complications; dialysis or transplant for end-stage disease." },
      { id: "renal_arpkd", cluster: "Cystic kidney disease", name: "Autosomal recessive polycystic kidney disease (ARPKD)", keyFacts: "A rare inherited cystic kidney disease presenting in infancy with large kidneys and hepatic fibrosis.", epidemiology: "Rare; presents in neonates and infants.", aetiology: "Autosomal recessive mutation in the PKHD1 gene.", pathophysiology: "Dilatation of the renal collecting ducts produces large cystic kidneys, with congenital hepatic fibrosis.", presentation: "Antenatal oligohydramnios with Potter sequence (pulmonary hypoplasia); neonatal large palpable kidneys and respiratory difficulty; later hypertension, renal failure and portal hypertension from liver fibrosis.", investigations: "Antenatal and postnatal ultrasound (large echogenic kidneys), U&E, liver assessment, genetic testing.", treatment: "Supportive neonatal respiratory care, blood pressure control, manage renal and liver complications; dialysis or transplant." },
      { id: "renal_uti", management: {"def": "A[\"Urinary tract infection\"]:::start --> B{\"Who?\"}:::decision\nB -- \"non-pregnant woman\" --> C[\"Nitrofurantoin (or trimethoprim) 3 days\"]:::good\nB -- \"man\" --> D[\"Nitrofurantoin or trimethoprim 7 days\"]:::good\nB -- \"pregnant\" --> E[\"Nitrofurantoin (not near term), avoid trimethoprim early\"]:::warn\nB -- \"catheter / unwell\" --> F[\"Treat as complicated, consider pyelonephritis\"]:::danger\nC --> G[\"Culture if pregnant, male, recurrent or fails\"]:::process", "tips": {"A": "Dysuria, frequency, urgency and suprapubic discomfort; management depends on who the patient is.", "B": "The patient group changes drug choice and duration.", "C": "Non-pregnant women with lower UTI: nitrofurantoin first-line (if eGFR adequate) or trimethoprim, for 3 days.", "D": "Men: nitrofurantoin or trimethoprim for 7 days (consider prostatitis).", "E": "Pregnant women: treat all UTIs including asymptomatic bacteriuria; nitrofurantoin (avoid at term), amoxicillin or cefalexin. Avoid trimethoprim in the first trimester (folate antagonist).", "F": "Catheter-associated, systemically unwell, or upper-tract features suggest complicated infection or pyelonephritis - broaden antibiotics and reassess.", "G": "Send a urine culture if pregnant, male, recurrent, catheterised or if empirical treatment fails, then narrow to sensitivities."}}, cluster: "Infection, stones & haematuria", name: "Urinary tract infection", keyFacts: "Infection of the urinary tract; uncomplicated cystitis in women is common, while pyelonephritis is more serious.", epidemiology: "Very common in women; in men and children it warrants more thought.", aetiology: "Usually ascending Escherichia coli; risk rises with catheters, obstruction, pregnancy and diabetes.", pathophysiology: "Bacteria ascend the urethra to colonise the bladder, and sometimes the kidney, provoking inflammation and the typical symptoms.", presentation: "Dysuria, frequency, urgency, suprapubic pain; pyelonephritis adds fever and loin pain.", investigations: "Urine dipstick, MSU culture; imaging for recurrent/atypical disease.", treatment: "Nitrofurantoin or trimethoprim for simple cystitis; longer course and broader cover for pyelonephritis." },
      { id: "renal_stones", management: {"def": "A[\"Renal or ureteric stone (colic)\"]:::start --> B[\"Analgesia: NSAID first-line (IM/PR diclofenac)\"]:::good\nB --> C[\"Non-contrast CT KUB within 24 h\"]:::process\nC --> D{\"Infected obstruction, AKI or single kidney?\"}:::decision\nD -- \"yes\" --> E[\"Emergency decompression (nephrostomy/stent)\"]:::danger\nD -- \"no, stone under 5 mm\" --> F[\"Watchful waiting, most pass\"]:::good\nD -- \"no, larger\" --> G[\"Lithotripsy or ureteroscopy\"]:::good\nA --> H[\"Prevention: hydration, dietary advice\"]:::process", "tips": {"A": "Severe loin-to-groin colicky pain with haematuria from a stone in the renal tract; treat pain and image promptly.", "B": "First-line analgesia is an NSAID (e.g. IM or PR diclofenac); IV paracetamol if NSAIDs contraindicated. Opioids are less effective.", "C": "Non-contrast CT of the kidneys, ureters and bladder within 24 hours confirms and sizes the stone (ultrasound first in pregnancy and children).", "D": "Check for an infected obstructed system or renal impairment - a urological emergency.", "E": "Obstruction with infection (or AKI, or a single/transplant kidney) needs urgent decompression (nephrostomy or ureteric stent) plus antibiotics.", "F": "Stones under 5 mm usually pass spontaneously - watchful waiting with analgesia; an alpha-blocker (tamsulosin) may aid passage of distal ureteric stones.", "G": "Larger stones or those failing to pass: extracorporeal shockwave lithotripsy or ureteroscopy (percutaneous nephrolithotomy for large or staghorn stones).", "H": "Prevent recurrence with good fluid intake and dietary/metabolic advice."}}, cluster: "Infection, stones & haematuria", name: "Renal & ureteric stones", keyFacts: "Crystalline stones in the urinary tract causing severe loin-to-groin colic; an obstructed infected kidney is an emergency.", epidemiology: "Common, more so in men, and recurring in many.", aetiology: "Dehydration and hypercalciuria; calcium oxalate stones are commonest, with urate and struvite less so.", pathophysiology: "Supersaturated urine precipitates crystals that aggregate into stones; obstruction raises pressure, causing pain and hydronephrosis.", presentation: "Severe loin-to-groin colic, haematuria, vomiting, restlessness.", investigations: "Non-contrast CT KUB, urinalysis, U&E, calcium, urate.", treatment: "Analgesia (NSAID), fluids; medical expulsive therapy; lithotripsy/ureteroscopy; urgent decompression if infected and obstructed." },
      { id: "renal_haematuria", cluster: "Infection, stones & haematuria", name: "Haematuria", keyFacts: "Blood in the urine; painless visible haematuria is bladder cancer until proven otherwise.", epidemiology: "A common presentation that always needs a cause to be sought.", aetiology: "Urinary tract cancer, stones, infection, glomerular disease, trauma and anticoagulation.", pathophysiology: "Bleeding anywhere from the glomerulus to the urethra enters the urine; the pattern helps localise the source.", presentation: "Visible or non-visible blood in urine; painless visible haematuria is cancer until excluded.", investigations: "Urinalysis, cytology, cystoscopy, CT urogram, U&E.", treatment: "2-week-wait referral for visible haematuria over 45; treat identified cause." },
      { id: "renal_kidney_ca", cluster: "Urological cancers", name: "Kidney tumours", keyFacts: "Most are renal cell carcinoma; the classic triad is haematuria, loin pain and a mass, though many are found incidentally.", epidemiology: "Renal cell carcinoma mainly affects older adults; Wilms tumour is the childhood renal cancer.", aetiology: "Smoking, obesity, hypertension and dialysis-acquired cysts; hereditary (von Hippel-Lindau); Wilms tumour in children.", pathophysiology: "Renal cell carcinoma arises from proximal tubular epithelium and can invade the renal vein; benign tumours include oncocytoma and angiomyolipoma.", presentation: "Often incidental; haematuria, loin pain and a mass; a left varicocele, paraneoplastic syndromes (polycythaemia, hypercalcaemia) and cannonball lung metastases.", investigations: "Contrast CT abdomen and pelvis for staging, ultrasound, bloods; biopsy selectively.", treatment: "Partial or radical nephrectomy; ablation for small tumours; targeted therapy or immunotherapy for advanced disease." },
      { id: "renal_urinary_tract_ca", cluster: "Urological cancers", name: "Urinary tract tumours", keyFacts: "Urothelial (transitional cell) carcinoma of the upper tract — the renal pelvis and ureter — presenting with painless haematuria.", epidemiology: "Less common than bladder cancer but shares its urothelial origin and risk factors.", aetiology: "Smoking and occupational aromatic amines (dye and rubber industries); chronic inflammation; schistosomiasis predisposes to squamous cell carcinoma.", pathophysiology: "Malignant transformation of the urothelium lining the renal pelvis and ureter; field change makes tumours often multifocal and recurrent.", presentation: "Painless visible haematuria; flank pain or obstruction if the ureter is involved.", investigations: "CT urogram, urine cytology, ureteroscopy with biopsy.", treatment: "Nephroureterectomy for upper-tract disease; surveillance for recurrence given the field-change risk." },
      { id: "renal_bladder_ca", cluster: "Urological cancers", name: "Bladder cancer", keyFacts: "Usually urothelial (transitional cell) carcinoma presenting with painless visible haematuria; smoking is the key risk factor.", epidemiology: "Commoner in older men and smokers.", aetiology: "Smoking and occupational aromatic amines; schistosomiasis causes squamous cell carcinoma in endemic areas.", pathophysiology: "Urothelial malignancy, often multifocal and recurrent, ranging from non-muscle-invasive to muscle-invasive disease.", presentation: "Painless visible haematuria; recurrent urinary infections or storage symptoms.", investigations: "Flexible cystoscopy (gold standard), CT urogram, urine cytology; 2-week-wait referral.", treatment: "Transurethral resection (TURBT) with intravesical BCG or chemotherapy for non-muscle-invasive disease; cystectomy or chemoradiotherapy for muscle-invasive disease." },
      { id: "renal_prostate_ca", cluster: "Urological cancers", name: "Prostate cancer", keyFacts: "The commonest male cancer; behaviour ranges from indolent to aggressive, graded by the Gleason score.", epidemiology: "Incidence rises sharply with age; commoner in Black men and with a family history.", aetiology: "Age, ethnicity and family history (BRCA), with androgen-dependent growth.", pathophysiology: "Malignant transformation of usually peripheral prostatic glandular cells; many are slow-growing, but some metastasise to bone.", presentation: "Often asymptomatic; lower urinary tract symptoms, bone pain in advanced disease.", investigations: "PSA, multiparametric MRI, transrectal biopsy, bone scan; Gleason grading.", treatment: "Active surveillance, radical prostatectomy, radiotherapy, hormone therapy by risk and stage." },
      { id: "renal_testicular_ca", cluster: "Urological cancers", name: "Testicular tumours", keyFacts: "The commonest solid cancer in young men; a painless testicular lump, with an excellent cure rate.", epidemiology: "Peaks at 20 to 40 years and is commoner with a history of undescended testis.", aetiology: "Cryptorchidism, family history and infertility; germ-cell tumours predominate (seminoma and non-seminoma).", pathophysiology: "Most arise from germ cells; seminomas and non-seminomatous tumours (teratoma, yolk sac) differ in markers and spread.", presentation: "A painless, firm, irregular testicular lump that does not transilluminate; rarely gynaecomastia or metastatic symptoms.", investigations: "Scrotal ultrasound, tumour markers (alpha-fetoprotein, beta-hCG, LDH), staging CT.", treatment: "Radical inguinal orchidectomy; chemotherapy or radiotherapy by type and stage; sperm banking; generally highly curable." },
      { id: "renal_bph", management: {"def": "A[\"Benign prostatic hyperplasia (LUTS)\"]:::start --> B[\"Assess: IPSS, DRE, PSA discussion, urinalysis\"]:::process\nB --> C{\"Bothersome symptoms?\"}:::decision\nC -- \"mild\" --> D[\"Watchful waiting + lifestyle advice\"]:::good\nC -- \"moderate-severe\" --> E[\"Alpha-blocker (tamsulosin)\"]:::good\nE -- \"large prostate / progression risk\" --> F[\"Add 5-alpha reductase inhibitor (finasteride)\"]:::good\nF --> G[\"Add antimuscarinic if storage symptoms persist\"]:::good\nG --> H[\"Surgery (TURP) if refractory or complications\"]:::warn", "tips": {"A": "Prostatic enlargement causing lower urinary tract symptoms: hesitancy, weak stream, frequency and nocturia.", "B": "Assess with a symptom score (IPSS), digital rectal examination, urinalysis and a PSA discussion; exclude other causes.", "C": "Treatment depends on how bothersome the symptoms are.", "D": "Mild or not bothersome: reassurance, watchful waiting and lifestyle measures (fluid timing, less caffeine/alcohol, bladder training).", "E": "Moderate-severe: an alpha-blocker (tamsulosin) relaxes prostatic smooth muscle for rapid relief; watch for postural hypotension.", "F": "Add a 5-alpha reductase inhibitor (finasteride) for a large prostate or high progression risk; it shrinks the prostate over months and halves PSA.", "G": "Add an antimuscarinic if overactive-bladder (storage) symptoms persist.", "H": "Surgery (transurethral resection of the prostate) for refractory symptoms, retention or complications."}}, cluster: "Prostate & lower urinary tract", name: "Benign prostatic hyperplasia", keyFacts: "Benign enlargement of the prostate causing lower urinary tract symptoms in older men.", epidemiology: "Very common, increasing steadily with age.", aetiology: "Age-related hormonal change (dihydrotestosterone) driving prostatic stromal and glandular growth.", pathophysiology: "The enlarging prostate obstructs bladder outflow, causing voiding and storage symptoms and, if severe, urinary retention.", presentation: "Hesitancy, weak stream, nocturia, incomplete emptying in older men.", investigations: "IPSS, examination, PSA after counselling, urinalysis, flow studies.", treatment: "Alpha-blocker (tamsulosin); 5-alpha-reductase inhibitor for large glands; TURP for refractory cases." },
      { id: "renal_prostatitis", cluster: "Prostate & lower urinary tract", name: "Prostatitis", keyFacts: "Inflammation of the prostate, acute (bacterial) or chronic, causing pelvic pain and urinary symptoms.", epidemiology: "Common; the chronic pelvic pain form is the most frequent.", aetiology: "Acute bacterial prostatitis from urinary organisms (E. coli); also chronic bacterial prostatitis and chronic pelvic pain syndrome.", pathophysiology: "Bacterial infection or inflammation of the prostate causes pain, voiding symptoms and, when acute, systemic sepsis.", presentation: "Acute: fever, perineal and lower urinary tract pain, an exquisitely tender prostate on examination. Chronic: persistent pelvic pain and urinary symptoms.", investigations: "Urinalysis and culture, bloods if septic; avoid vigorous prostate massage in acute disease.", treatment: "Prolonged antibiotics (quinolone or trimethoprim, longer for chronic disease), analgesia and alpha-blockers; drain a prostatic abscess." },
      { id: "renal_incontinence", cluster: "Prostate & lower urinary tract", name: "Urinary incontinence", keyFacts: "Involuntary urine leakage; stress, urge and mixed types are distinguished from the history.", epidemiology: "Very common, especially in older women, and underreported.", aetiology: "Stress from pelvic floor weakness (childbirth); urge from detrusor overactivity; also neurological and prostatic causes.", pathophysiology: "Stress leakage results from poor urethral support, while urge incontinence reflects uninhibited detrusor contractions overcoming sphincter control.", presentation: "Stress leakage on coughing, urge with urgency, or mixed; impacts quality of life.", investigations: "Bladder diary, urinalysis, post-void residual, urodynamics if unclear.", treatment: "Pelvic floor exercises and bladder training; antimuscarinics/mirabegron for urge; surgery for stress." },
      { id: "renal_torsion", management: {"def": "A[\"Testicular torsion\"]:::start --> B[\"Acute severe scrotal pain (a surgical emergency)\"]:::danger\nB --> C[\"Do NOT delay for imaging\"]:::warn\nC --> D[\"Urgent surgical exploration within 6 hours\"]:::danger\nD --> E{\"Testis viable?\"}:::decision\nE -- \"yes\" --> F[\"Detorse and fix both testes (orchidopexy)\"]:::good\nE -- \"no\" --> G[\"Orchidectomy, fix the other testis\"]:::good", "tips": {"A": "Twisting of the spermatic cord cutting off the testicular blood supply, commonest in adolescents: sudden severe testicular pain, nausea, a high-riding tender testis and an absent cremasteric reflex.", "B": "It is a clinical diagnosis and a surgical emergency - the testis infarcts within hours.", "C": "Do NOT delay for ultrasound if torsion is suspected clinically - time is testis.", "D": "Explore surgically as soon as possible (ideally within 6 hours of onset for the best salvage rate).", "E": "At operation, assess whether the testis is viable after detorsion.", "F": "If viable: detorse and fix it (orchidopexy) - and fix the other testis too, as the predisposing anatomy (bell-clapper deformity) is usually bilateral.", "G": "If non-viable: orchidectomy, and fix the contralateral testis to prevent future torsion."}}, cluster: "Scrotal & testicular", name: "Testicular torsion", keyFacts: "Twisting of the testis on its cord cutting off blood supply; a surgical emergency salvageable within about 6 hours.", epidemiology: "Mainly affects adolescents and young men.", aetiology: "A 'bell-clapper' anatomical predisposition; it may follow activity or trauma.", pathophysiology: "Rotation of the spermatic cord occludes venous then arterial flow, causing ischaemia and, if untreated, infarction.", presentation: "Sudden severe testicular pain, swelling, high-riding testis, absent cremasteric reflex; teenagers.", investigations: "Clinical diagnosis — do not delay; Doppler only if it will not cause delay.", treatment: "Emergency surgical exploration and bilateral fixation within 6 hours." },
      { id: "renal_epididymo", cluster: "Scrotal & testicular", name: "Epididymo-orchitis", keyFacts: "Inflammation of the epididymis and testis causing gradual scrotal pain; it must be distinguished from torsion.", epidemiology: "Common in sexually active young men and in older men with urinary infection.", aetiology: "Sexually transmitted organisms (chlamydia, gonorrhoea) in the young; enteric bacteria in older men.", pathophysiology: "Ascending infection from the urethra or bladder inflames the epididymis, causing swelling and pain that eases on elevation.", presentation: "Gradual unilateral testicular pain and swelling, dysuria, fever; relieved by elevation.", investigations: "Urinalysis, STI screen if young, ultrasound to exclude torsion/abscess.", treatment: "Antibiotics targeting likely organism (STI vs enteric), analgesia, scrotal support." },
      { id: "renal_hydrocele", cluster: "Scrotal & testicular", name: "Hydrocele", keyFacts: "A fluid collection within the tunica vaginalis causing a painless scrotal swelling that transilluminates.", epidemiology: "Common; congenital in infants (often resolving) and acquired in adults.", aetiology: "Congenital (a patent processus vaginalis) or acquired (idiopathic, or secondary to infection, trauma or tumour).", pathophysiology: "Excess serous fluid accumulates between the layers of the tunica vaginalis around the testis.", presentation: "A painless, soft scrotal swelling that transilluminates and that you can get above; the testis may be impalpable within it.", investigations: "Clinical with transillumination; ultrasound to exclude an underlying tumour, especially in a new adult hydrocele.", treatment: "Reassurance for the infantile type (usually resolves by 2 years); surgical repair or aspiration if large, symptomatic or persistent; treat any underlying cause." },
    ],
  },
  {
    id: "neurology",
    name: "Neurology",
    icon: "🧠",
    conditions: [
      { id: "neuro_migraine", management: {"def": "A[\"Migraine attack\"]:::start --> B[\"Acute: triptan + NSAID\"]:::good\nB --> C[\"Add antiemetic if nausea\"]:::good\nB -- \"limit acute drugs\" --> G[\"Avoid medication-overuse headache\"]:::warn\nA --> D{\"Frequent or disabling attacks?\"}:::decision\nD -- \"yes\" --> E[\"Prophylaxis: propranolol or topiramate\"]:::good\nE --> F[\"Consider acupuncture / menstrual options\"]:::good", "tips": {"A": "Recurrent moderate–severe headache, often unilateral and throbbing, with nausea and photophobia, with or without aura.", "B": "Treat attacks early with a triptan (e.g. sumatriptan) plus an NSAID or paracetamol.", "C": "Add an antiemetic (metoclopramide or prochlorperazine) even without vomiting; it improves absorption and symptoms.", "D": "Offer prophylaxis when attacks are frequent or disabling.", "E": "First-line prophylaxis: propranolol, topiramate or amitriptyline. Topiramate and valproate must be avoided in women of childbearing potential without strict contraception (valproate is contraindicated).", "F": "Consider acupuncture; for predictable menstrual migraine consider frovatriptan around menses. Anti-CGRP agents are a specialist option.", "G": "Restrict triptans/analgesics to no more than 10–15 days per month to avoid medication-overuse headache."}}, cluster: "Headache & facial pain", name: "Migraine", keyFacts: "A recurrent primary headache, often unilateral and throbbing with nausea and photophobia, sometimes with aura.", epidemiology: "Very common, particularly in women of reproductive age.", aetiology: "Genetic predisposition with triggers such as stress, hormones, sleep change, certain foods and dehydration.", pathophysiology: "Cortical spreading depression (aura) and trigeminovascular activation with neuropeptide release cause the pain and associated symptoms.", presentation: "Unilateral throbbing headache with nausea, photophobia, phonophobia, sometimes aura.", investigations: "Clinical; exclude red flags; headache diary.", treatment: "Triptan plus NSAID for attacks; propranolol or topiramate for prophylaxis; avoid medication overuse." },
      { id: "neuro_tension", cluster: "Headache & facial pain", name: "Tension-type headache", keyFacts: "The commonest primary headache; a bilateral, tight, band-like pressure without nausea.", epidemiology: "Extremely common, affecting most people at some point.", aetiology: "Stress, poor posture, fatigue and missed meals.", pathophysiology: "Thought to involve pericranial muscle tension and altered central pain processing, without the vascular features of migraine.", presentation: "Bilateral tight band-like pressure, no nausea, not aggravated by activity.", investigations: "Clinical diagnosis.", treatment: "Reassurance, simple analgesia, stress and posture management; avoid overuse." },
      { id: "neuro_cluster", cluster: "Headache & facial pain", name: "Cluster headache", keyFacts: "Severe unilateral periorbital pain in clusters with autonomic features; among the most painful conditions known.", epidemiology: "Uncommon; commoner in men, often smokers.", aetiology: "Largely idiopathic, though alcohol can trigger attacks during a cluster.", pathophysiology: "Hypothalamic activation and a trigeminal-autonomic reflex produce severe pain with ipsilateral lacrimation, ptosis and nasal congestion.", presentation: "Severe unilateral periorbital pain in clusters with lacrimation, ptosis, nasal congestion.", investigations: "Clinical; MRI to exclude secondary causes.", treatment: "High-flow oxygen and subcutaneous sumatriptan for attacks; verapamil for prevention." },
      { id: "neuro_trigeminal", cluster: "Headache & facial pain", name: "Trigeminal neuralgia", keyFacts: "Sudden, severe, electric-shock-like unilateral facial pain in the trigeminal distribution, triggered by light touch.", epidemiology: "Commoner in women and over 50; younger onset suggests multiple sclerosis.", aetiology: "Usually neurovascular compression of the trigeminal root; secondary causes include MS and posterior fossa tumours.", pathophysiology: "Compression and demyelination of the trigeminal nerve cause paroxysmal ectopic firing.", presentation: "Brief paroxysms of severe stabbing pain in the cheek or jaw, triggered by chewing, talking, touch or cold, with pain-free intervals.", investigations: "Clinical diagnosis; MRI to identify vascular compression and exclude secondary causes (MS, tumour).", treatment: "Carbamazepine first-line; alternatives (oxcarbazepine, lamotrigine, gabapentin); microvascular decompression or ablative surgery if refractory." },      { id: "neuro_iih", cluster: "Headache & facial pain", name: "Idiopathic intracranial hypertension", keyFacts: "Raised intracranial pressure without a mass lesion, classically in young obese women; it threatens vision.", epidemiology: "Typically young, obese women of childbearing age.", aetiology: "Idiopathic; associated with obesity and drugs (tetracyclines, vitamin A and retinoids, steroids).", pathophysiology: "Impaired CSF absorption raises intracranial pressure, transmitted to the optic nerves as papilloedema.", presentation: "Headache (worse lying down and on waking), papilloedema, transient visual obscurations, diplopia (sixth nerve palsy), pulsatile tinnitus.", investigations: "MRI/MRV to exclude a mass and venous sinus thrombosis; lumbar puncture shows a raised opening pressure with normal CSF; formal visual fields.", treatment: "Weight loss, stop causative drugs, acetazolamide; serial visual fields; CSF shunt or optic nerve sheath fenestration if vision is threatened." },
      { id: "neuro_stroke", management: {"def": "A[\"Suspected acute stroke (FAST positive)\"]:::start --> B[\"Immediate CT head\"]:::process\nB --> C{\"Haemorrhage excluded?\"}:::decision\nC -- \"ischaemic, within 4.5 h\" --> D[\"Thrombolysis (alteplase)\"]:::danger\nC -- \"large-vessel, within 6-24 h\" --> E[\"Thrombectomy\"]:::danger\nC -- \"haemorrhagic\" --> F[\"Neurosurgery referral, reverse anticoagulation\"]:::danger\nD --> G[\"Aspirin 300 mg for 2 weeks (after 24 h)\"]:::good\nE --> G\nG --> H[\"Secondary prevention\"]:::process\nH --> I[\"Clopidogrel, statin, BP control, treat AF\"]:::good", "tips": {"A": "Sudden focal neurological deficit; use FAST (face, arm, speech, time). A time-critical emergency needing urgent brain imaging.", "B": "Immediate non-contrast CT to separate ischaemic from haemorrhagic stroke and guide reperfusion.", "C": "Management diverges on whether there is haemorrhage and on the time window.", "D": "IV thrombolysis (alteplase or tenecteplase) if ischaemic and within 4.5 hours of onset, once haemorrhage is excluded and no contraindications.", "E": "Mechanical thrombectomy for proximal large-vessel occlusion up to 6 hours (up to 24 h with favourable imaging), often with thrombolysis.", "F": "Haemorrhagic stroke: urgent neurosurgical/stroke review, reverse any anticoagulation, and control blood pressure.", "G": "After ischaemic stroke give aspirin 300 mg for 2 weeks (start 24 h after thrombolysis), then switch to long-term antiplatelet.", "H": "Start secondary prevention once stable.", "I": "Long-term clopidogrel (or aspirin plus dipyridamole), high-intensity statin, blood-pressure control, and anticoagulation if AF; carotid endarterectomy for significant symptomatic stenosis."}}, cluster: "Cerebrovascular disease", name: "Stroke", keyFacts: "A sudden focal neurological deficit of vascular origin; the ischaemic and haemorrhagic types need opposite treatments, so image first.", epidemiology: "A leading cause of death and disability, rising sharply with age.", aetiology: "Ischaemic (about 85%) from thrombosis or embolism (atrial fibrillation, carotid disease); haemorrhagic (about 15%) from hypertension, aneurysm or anticoagulation.", pathophysiology: "Interruption of cerebral blood flow, or bleeding, causes neuronal injury in the affected territory, with a potentially salvageable ischaemic penumbra.", presentation: "Sudden focal deficit: unilateral weakness, facial droop, speech disturbance, visual field loss; FAST positive.", investigations: "Immediate non-contrast CT head to distinguish ischaemic from haemorrhagic; ECG, glucose, carotid imaging, bloods.", treatment: "Ischaemic: thrombolysis (alteplase) within 4.5 hours and/or thrombectomy, then aspirin 300mg; haemorrhagic: reverse anticoagulation, control BP, neurosurgery; stroke-unit care and secondary prevention." },
      { id: "neuro_tia", management: {"def": "A[\"Transient ischaemic attack\"]:::start --> B[\"Aspirin 300 mg immediately\"]:::good\nB --> C[\"Specialist assessment within 24 h\"]:::process\nC --> D[\"MRI (diffusion-weighted)\"]:::process\nD --> E[\"Carotid imaging, ECG for AF\"]:::process\nE --> F[\"Secondary prevention: clopidogrel, statin, BP\"]:::good\nA -- \"on anticoagulant / bleeding risk\" --> G[\"Discuss urgently before aspirin\"]:::warn", "tips": {"A": "Transient focal neurological symptoms from ischaemia that fully resolve without infarction. ABCD2 is no longer used to decide urgency.", "B": "Give aspirin 300 mg immediately unless contraindicated, and continue until specialist review.", "C": "Refer for specialist assessment within 24 hours of symptom onset.", "D": "MRI with diffusion-weighted imaging is preferred to confirm and localise; done at specialist assessment.", "E": "Find a cause: carotid Doppler (for endarterectomy), ECG/monitoring for AF, echocardiography if indicated.", "F": "Long-term clopidogrel, high-intensity statin and blood-pressure control; anticoagulate if AF; carotid endarterectomy for symptomatic 50-99% stenosis. Advise not to drive (DVLA rules).", "G": "If already anticoagulated or a bleeding disorder, discuss before aspirin; crescendo TIAs need emergency assessment."}}, cluster: "Cerebrovascular disease", name: "Transient ischaemic attack (TIA)", keyFacts: "A transient, fully-reversible focal neurological deficit from ischaemia without infarction; a warning of imminent stroke.", epidemiology: "Common, and carries a high short-term risk of a completed stroke.", aetiology: "Embolism from atrial fibrillation or carotid atheroma, or small-vessel disease; the same risk factors as ischaemic stroke.", pathophysiology: "Temporary focal cerebral ischaemia produces symptoms that resolve; now defined by the absence of infarction rather than a 24-hour time limit.", presentation: "Sudden focal deficit that fully resolves (often within an hour): unilateral weakness, dysphasia, or amaurosis fugax.", investigations: "NICE: do not use the ABCD2 score to risk-stratify; specialist assessment within 24 hours, with MRI (diffusion-weighted) preferred over CT; carotid Doppler, ECG, bloods.", treatment: "NICE: aspirin 300mg immediately (unless bleeding risk) and specialist review within 24 hours; then clopidogrel 75mg and a high-intensity statin; treat atrial fibrillation and symptomatic carotid stenosis; no driving for 1 month." },
      { id: "neuro_sah", management: {"def": "A[\"Subarachnoid haemorrhage\"]:::start --> B[\"Urgent non-contrast CT head\"]:::process\nB --> C{\"CT positive?\"}:::decision\nC -- \"yes\" --> D[\"Refer to neurosurgery\"]:::good\nC -- \"negative but suspicious\" --> E[\"Lumbar puncture at 12 h (xanthochromia)\"]:::good\nD --> F[\"Nimodipine to prevent vasospasm\"]:::good\nF --> G[\"Secure aneurysm: coiling or clipping\"]:::good\nA --> H[\"Control BP, bed rest, analgesia\"]:::process", "tips": {"A": "Bleeding into the subarachnoid space, usually from a ruptured berry aneurysm: sudden thunderclap headache (worst ever, occipital), neck stiffness, photophobia, vomiting and reduced consciousness.", "B": "Do an urgent non-contrast CT head - highly sensitive within 6 hours of onset.", "C": "A negative CT does not fully exclude SAH later after onset.", "D": "CT-confirmed SAH: refer immediately to neurosurgery for aneurysm assessment (CT angiography).", "E": "If CT is negative but suspicion remains, do a lumbar puncture at least 12 hours after onset to look for xanthochromia (bilirubin from breakdown of red cells).", "F": "Give oral nimodipine (a calcium-channel blocker) to reduce cerebral vasospasm and delayed ischaemia.", "G": "Secure the aneurysm early by endovascular coiling (preferred) or surgical clipping to prevent rebleeding.", "H": "Supportive care: blood-pressure control, bed rest, analgesia, and monitor for rebleeding, hydrocephalus, vasospasm and hyponatraemia."}}, cluster: "Cerebrovascular disease", name: "Subarachnoid haemorrhage", keyFacts: "Spontaneous bleeding into the subarachnoid space, classically a thunderclap headache; a neurosurgical emergency.", epidemiology: "Less common than other strokes but with high mortality, often in middle age.", aetiology: "Most commonly a ruptured berry aneurysm; also arteriovenous malformations, with risk from hypertension and polycystic kidney disease.", pathophysiology: "Arterial blood under pressure floods the subarachnoid space, raising intracranial pressure and causing vasospasm and secondary ischaemia.", presentation: "Sudden thunderclap occipital headache, neck stiffness, photophobia, reduced consciousness.", investigations: "Urgent CT head; lumbar puncture for xanthochromia if CT negative after 12h.", treatment: "Neurosurgical referral, nimodipine, coiling/clipping of aneurysm." },
      { id: "neuro_subdural", cluster: "Cerebrovascular disease", name: "Subdural haematoma", keyFacts: "Bleeding between the dura and arachnoid from torn bridging veins; a crescent-shaped collection on CT.", epidemiology: "Commoner in the elderly, in alcohol misuse and on anticoagulants, often after minor or forgotten trauma.", aetiology: "Rupture of bridging veins (brain atrophy stretches them); trauma, falls, anticoagulation.", pathophysiology: "Venous blood collects slowly in the subdural space; the haematoma may be acute or chronic and crosses suture lines.", presentation: "Fluctuating consciousness, headache, confusion and focal signs, days to weeks after a fall (chronic) or acutely after major trauma.", investigations: "CT head: a crescent-shaped (concave) collection crossing suture lines, hyperdense if acute and hypodense if chronic.", treatment: "Reverse anticoagulation; surgical evacuation (burr-hole drainage for chronic, craniotomy for acute); conservative if small and asymptomatic." },
      { id: "neuro_epilepsy", management: {"def": "A[\"Epilepsy (usually after 2nd seizure)\"]:::start --> B{\"Seizure type\"}:::decision\nB -- \"focal\" --> C[\"Lamotrigine or levetiracetam\"]:::good\nB -- \"generalised tonic-clonic\" --> D[\"Sodium valproate\"]:::good\nB -- \"absence\" --> E[\"Ethosuximide\"]:::good\nB -- \"myoclonic\" --> F[\"Levetiracetam\"]:::good\nD -- \"childbearing potential\" --> G[\"Use lamotrigine/levetiracetam\"]:::warn\nC --> H{\"Seizures uncontrolled?\"}:::decision\nH -- \"yes\" --> I[\"Switch or add drug; refer if resistant\"]:::good", "tips": {"A": "Usually start treatment after a second unprovoked seizure (or after a first with clear risk); the drug depends on the seizure/epilepsy type.", "B": "Match the drug to the seizure type; the wrong drug can worsen some generalised epilepsies.", "C": "Focal seizures: first-line lamotrigine or levetiracetam.", "D": "Generalised tonic-clonic: sodium valproate is most effective, but must NOT be used in anyone able to become pregnant unless the Pregnancy Prevention Programme conditions are met.", "E": "Absence seizures: ethosuximide first-line (or valproate); avoid carbamazepine, which worsens absences.", "F": "Myoclonic seizures: levetiracetam or valproate; avoid carbamazepine and lamotrigine, which can worsen them.", "G": "For women and girls of childbearing potential, use lamotrigine or levetiracetam instead of valproate.", "H": "Review control; poorly controlled epilepsy needs dose optimisation or a change of drug.", "I": "Switch to another first-line drug as monotherapy, then consider combination therapy; refer for specialist/surgical assessment if drug-resistant."}}, cluster: "Epilepsy & seizures", name: "Epilepsy & seizures", keyFacts: "A tendency to recurrent unprovoked seizures, which may be focal or generalised.", epidemiology: "Common, beginning at any age, with peaks in childhood and old age.", aetiology: "Often idiopathic; also structural lesions, genetic syndromes, trauma, stroke and metabolic disturbance.", pathophysiology: "Abnormal, synchronous neuronal discharges spread through the cortex, producing seizures whose features reflect the area involved.", presentation: "Recurrent seizures, focal or generalised; tongue-biting, incontinence, post-ictal confusion.", investigations: "EEG, MRI brain, ECG, bloods; first seizure clinic referral.", treatment: "Lamotrigine/levetiracetam for focal; sodium valproate avoided in those who can become pregnant; advise on driving and safety." },
      { id: "neuro_status_epilepticus", cluster: "Epilepsy & seizures", name: "Status epilepticus", keyFacts: "A single seizure lasting 5 minutes or more, or repeated seizures without recovery of consciousness between them; a neurological emergency with time-dependent morbidity and mortality.", epidemiology: "Occurs in people with and without known epilepsy; common precipitants are poor antiepileptic adherence, alcohol, infection, metabolic disturbance and stroke.", aetiology: "Precipitants include antiepileptic withdrawal or non-adherence, alcohol, CNS infection, stroke, hypoglycaemia and other metabolic derangement, drug toxicity and eclampsia.", pathophysiology: "Failure of the mechanisms that normally terminate seizures leads to continuous electrical activity; prolonged seizures cause excitotoxic neuronal injury, hyperthermia, rhabdomyolysis and cardiorespiratory compromise.", presentation: "Continuous convulsive activity, or repeated seizures without recovery, beyond 5 minutes; non-convulsive status presents as prolonged altered consciousness confirmed on EEG.", investigations: "Immediate capillary glucose; bloods including U and Es, calcium, magnesium, antiepileptic drug levels, toxicology and a blood gas; consider CT head, lumbar puncture and EEG once stabilised.", treatment: "ABC with high-flow oxygen and IV access; check and correct glucose; IV lorazepam (repeat once after 5-10 minutes); if ongoing, IV levetiracetam, phenytoin or sodium valproate; if refractory (around 30 minutes), rapid-sequence induction with general anaesthesia and intensive care; treat the underlying cause throughout.", management: {"def": "A[\"Convulsive status epilepticus (seizure 5 min+)\"]:::start --> B[\"ABC, high-flow oxygen, check glucose\"]:::danger\nB --> C[\"IV lorazepam 4 mg (buccal midazolam if no access)\"]:::good\nC --> D{\"Seizure continues after 5-10 min?\"}:::decision\nD -- \"yes\" --> E[\"Second dose of IV lorazepam\"]:::good\nE --> F{\"Still seizing?\"}:::decision\nF -- \"yes\" --> G[\"IV levetiracetam, phenytoin or valproate\"]:::good\nG --> H{\"Refractory (over 30 min)?\"}:::decision\nH -- \"yes\" --> I[\"RSI general anaesthesia (propofol), ICU\"]:::danger\nB --> J[\"Treat the cause, correct glucose/electrolytes\"]:::process", "tips": {"A": "A convulsive seizure lasting 5 minutes or more, or recurrent seizures without recovery between them - a neurological emergency; start the timed treatment ladder immediately.", "B": "Secure the airway, give high-flow oxygen, gain IV access and check capillary glucose (give glucose if low, and thiamine if alcohol-related or malnourished).", "C": "First-line: IV lorazepam 4 mg. If no IV access, buccal midazolam or rectal diazepam.", "D": "Reassess after 5-10 minutes.", "E": "Give a second and final dose of a benzodiazepine (watch for respiratory depression).", "F": "If seizures continue after two benzodiazepine doses, this is established status - move to a second-line agent.", "G": "Second-line: IV levetiracetam, phenytoin (with cardiac monitoring) or sodium valproate (avoid valproate in women of childbearing potential).", "H": "Refractory status is seizure activity continuing despite first- and second-line treatment (around 30 minutes).", "I": "Refractory status: rapid-sequence induction and general anaesthesia (propofol, midazolam or thiopental) with intubation and transfer to intensive care, with EEG monitoring.", "J": "Throughout, identify and treat the precipitant - hypoglycaemia, electrolyte disturbance, infection, low drug levels, alcohol or eclampsia."}} },      { id: "neuro_parkinsons", management: {"def": "A[\"Parkinson disease\"]:::start --> B{\"Motor symptoms affecting quality of life?\"}:::decision\nB -- \"yes\" --> C[\"Levodopa (with decarboxylase inhibitor)\"]:::good\nB -- \"not yet limiting\" --> D[\"Dopamine agonist or MAO-B inhibitor\"]:::good\nC --> E[\"Advancing: add agonist, MAO-B or COMT inhibitor\"]:::good\nE --> F[\"Advanced: apomorphine, DBS, intestinal gel\"]:::warn\nA --> G[\"MDT: physiotherapy, OT, SALT; treat non-motor symptoms\"]:::process", "tips": {"A": "Loss of nigrostriatal dopamine causing bradykinesia with rest tremor and rigidity; a clinical diagnosis.", "B": "NICE bases the first drug on whether motor symptoms impair quality of life.", "C": "Symptoms affecting quality of life: levodopa (co-beneldopa/co-careldopa) gives the best motor control but earlier motor complications.", "D": "Symptoms not yet limiting: a dopamine agonist, levodopa or MAO-B inhibitor; agonists cause more impulse-control disorders and daytime somnolence.", "E": "As it advances, add an adjunct (dopamine agonist, MAO-B or COMT inhibitor) to levodopa for motor fluctuations.", "F": "Advanced disease: apomorphine, deep brain stimulation, or intrajejunal levodopa gel in specialist centres.", "G": "Never stop Parkinson drugs abruptly (risk of acute akinesia). Involve the multidisciplinary team and treat non-motor symptoms (constipation, depression, sleep, postural hypotension)."}}, cluster: "Movement disorders & neurodegeneration", name: "Parkinson's disease", keyFacts: "A neurodegenerative movement disorder with bradykinesia, resting tremor and rigidity.", epidemiology: "Common in older people, with incidence rising with age.", aetiology: "Mostly idiopathic with genetic and environmental contributions; exclude drug-induced parkinsonism.", pathophysiology: "Loss of dopaminergic neurons in the substantia nigra disrupts basal ganglia motor control, producing the cardinal features.", presentation: "Resting tremor, bradykinesia, rigidity, postural instability, hypomimia.", investigations: "Clinical diagnosis; DaTscan if uncertain.", treatment: "Levodopa with a dopa-decarboxylase inhibitor; dopamine agonists; MDT support; do not abruptly stop medication." },
      { id: "neuro_psp", cluster: "Movement disorders & neurodegeneration", name: "Progressive supranuclear palsy", keyFacts: "A Parkinson-plus syndrome with early falls and a vertical gaze palsy; responds poorly to levodopa.", epidemiology: "The commonest atypical parkinsonian syndrome, presenting in later life.", aetiology: "A sporadic tauopathy (4-repeat tau).", pathophysiology: "Tau deposition and neuronal loss in the brainstem and basal ganglia impair vertical gaze, balance and axial tone.", presentation: "Early postural instability with backward falls, vertical (especially downward) gaze palsy, axial rigidity, dysarthria, frontal cognitive change.", investigations: "Clinical diagnosis; MRI may show midbrain atrophy (the hummingbird sign).", treatment: "Largely supportive (physiotherapy, falls prevention, MDT); a limited or absent levodopa response." },
      { id: "neuro_msa", cluster: "Movement disorders & neurodegeneration", name: "Multiple system atrophy", keyFacts: "A Parkinson-plus syndrome combining parkinsonism with prominent early autonomic failure and cerebellar signs.", epidemiology: "A rare atypical parkinsonian syndrome of later life.", aetiology: "A sporadic alpha-synucleinopathy (glial cytoplasmic inclusions).", pathophysiology: "Alpha-synuclein deposition degenerates the basal ganglia, cerebellum and autonomic nuclei.", presentation: "Parkinsonism poorly responsive to levodopa, early autonomic failure (postural hypotension, bladder, erectile dysfunction), cerebellar ataxia.", investigations: "Clinical diagnosis; MRI changes; autonomic function testing.", treatment: "Supportive: manage postural hypotension (fludrocortisone, midodrine) and bladder symptoms; limited levodopa response; MDT." },
      { id: "neuro_mnd", cluster: "Movement disorders & neurodegeneration", name: "Motor neurone disease", keyFacts: "Progressive degeneration of motor neurons with mixed upper and lower motor neurone signs and no sensory loss.", epidemiology: "Usually presents after 50; amyotrophic lateral sclerosis is the commonest form.", aetiology: "Mostly sporadic; about 10% familial (e.g. SOD1, C9orf72), overlapping with frontotemporal dementia.", pathophysiology: "Degeneration of upper and lower motor neurons in the cortex, brainstem and cord, sparing sensory and oculomotor neurons.", presentation: "Progressive painless weakness with wasting and fasciculations plus brisk reflexes; bulbar (speech, swallow) onset; no sensory signs.", investigations: "Clinical diagnosis supported by EMG (denervation and fasciculation); MRI and bloods to exclude mimics.", treatment: "Riluzole modestly prolongs survival; non-invasive ventilation; MDT with PEG feeding and palliative care; prognosis is poor." },
      { id: "neuro_friedreich", cluster: "Movement disorders & neurodegeneration", name: "Friedreich's ataxia", keyFacts: "The commonest inherited ataxia; an autosomal recessive trinucleotide-repeat disorder presenting in childhood.", epidemiology: "Rare; onset usually between 5 and 15 years.", aetiology: "Autosomal recessive GAA trinucleotide repeat expansion in the frataxin (FXN) gene.", pathophysiology: "Frataxin deficiency impairs mitochondrial iron handling, degenerating the spinocerebellar tracts, dorsal columns and pyramidal tracts.", presentation: "Progressive ataxia and dysarthria, absent reflexes with upgoing plantars, loss of proprioception, pes cavus and scoliosis.", investigations: "Genetic testing (FXN repeat), MRI, ECG and echocardiography (hypertrophic cardiomyopathy), glucose (diabetes).", treatment: "No cure; MDT support; surveillance and treatment of cardiomyopathy and diabetes (the main causes of death)." },
      { id: "neuro_dementia", management: {"def": "A[\"Alzheimer disease\"]:::start --> B[\"Confirm diagnosis, MDT, treat reversible factors\"]:::process\nB --> C{\"Severity\"}:::decision\nC -- \"mild-moderate\" --> D[\"Acetylcholinesterase inhibitor (donepezil)\"]:::good\nC -- \"moderate-severe or intolerant\" --> E[\"Memantine\"]:::good\nD -- \"progresses to severe\" --> F[\"Add or switch to memantine\"]:::good\nA --> G[\"Cognitive stimulation, carer support, planning\"]:::good\nA --> H[\"BPSD: non-drug first, antipsychotics only if severe risk\"]:::warn", "tips": {"A": "The commonest cause of dementia; progressive neurodegeneration diagnosed clinically with cognitive testing and imaging.", "B": "Confirm the subtype, involve a memory service/specialist, and treat contributors (depression, thyroid, B12, drugs, sensory impairment).", "C": "Drug choice depends on severity.", "D": "Mild-to-moderate Alzheimer disease: an acetylcholinesterase inhibitor (donepezil, rivastigmine or galantamine).", "E": "Memantine (an NMDA antagonist) for moderate disease if AChE inhibitors are unsuitable, or for severe disease.", "F": "As it progresses to severe, memantine can be added to or replace the AChE inhibitor.", "G": "Offer cognitive stimulation, structured carer support and early advance care planning. AChE inhibitors also help Lewy body and Parkinson disease dementia.", "H": "Manage behavioural and psychological symptoms non-drug first; use antipsychotics only for severe distress or risk (avoid in Lewy body dementia - severe sensitivity)."}}, cluster: "Dementias", name: "Alzheimer's disease", keyFacts: "The commonest dementia; an insidious, progressive decline led by episodic (short-term) memory loss.", epidemiology: "The leading cause of dementia, with prevalence rising steeply with age.", aetiology: "Mostly sporadic with age and genetic risk (APOE e4 allele); rare early-onset familial forms (amyloid precursor protein, presenilin).", pathophysiology: "Extracellular beta-amyloid plaques and intracellular tau neurofibrillary tangles cause neuronal loss and cortical atrophy, especially of the hippocampus.", presentation: "Gradual short-term memory loss, then language, visuospatial and executive decline; alertness preserved until late.", investigations: "Cognitive testing (e.g. MoCA), bloods to exclude reversible causes, MRI (medial temporal lobe atrophy).", treatment: "Cholinesterase inhibitors (donepezil, rivastigmine, galantamine); memantine in moderate-to-severe disease; structured support and advance care planning." },
      { id: "neuro_vascular_dementia", cluster: "Dementias", name: "Vascular dementia", keyFacts: "The second commonest dementia; cognitive decline from cerebrovascular disease, classically in a stepwise pattern.", epidemiology: "Common, and often coexists with Alzheimer's disease (mixed dementia).", aetiology: "Cerebrovascular disease: multiple infarcts, small-vessel disease, or a single strategic stroke; shares vascular risk factors.", pathophysiology: "Cumulative ischaemic damage to brain tissue impairs cognition in a pattern reflecting the vessels involved.", presentation: "Stepwise decline with focal neurological signs; attention and executive problems more prominent than early memory loss.", investigations: "Cognitive testing, vascular risk assessment, MRI showing infarcts and small-vessel change.", treatment: "Optimise vascular risk factors (BP, antiplatelet, statin, diabetes); supportive care; cholinesterase inhibitors only if mixed or Lewy body type." },
      { id: "neuro_ftd", cluster: "Dementias", name: "Frontotemporal dementia", keyFacts: "An early-onset dementia of personality, behaviour and language change, with memory relatively spared at first.", epidemiology: "A leading cause of dementia under 65; includes Pick's disease.", aetiology: "Often familial, with tau or TDP-43 pathology; overlaps with motor neurone disease.", pathophysiology: "Focal degeneration of the frontal and temporal lobes (tau or TDP-43 inclusions) drives behavioural and language variants.", presentation: "Behavioural variant: disinhibition, apathy, loss of empathy; language variants: progressive aphasia; early memory relatively preserved.", investigations: "Cognitive and behavioural assessment, MRI (frontotemporal atrophy), exclude reversible causes.", treatment: "No disease-modifying drugs; cholinesterase inhibitors are not used; behavioural management and carer support." },
      { id: "neuro_lewy_body", cluster: "Dementias", name: "Dementia with Lewy bodies", keyFacts: "Dementia with fluctuating cognition, visual hallucinations and parkinsonism; antipsychotics can be dangerous.", epidemiology: "A common neurodegenerative dementia, overlapping with Parkinson's disease dementia.", aetiology: "Alpha-synuclein (Lewy body) pathology, part of the Lewy body disease spectrum.", pathophysiology: "Cortical and brainstem Lewy bodies (alpha-synuclein) disrupt cognition, perception and movement.", presentation: "Fluctuating cognition, recurrent visual hallucinations, spontaneous parkinsonism, REM sleep behaviour disorder, falls.", investigations: "Clinical criteria; a DaTscan (reduced striatal dopamine uptake) supports the diagnosis.", treatment: "Cholinesterase inhibitors help cognition; AVOID antipsychotics (severe neuroleptic sensitivity); cautious levodopa for motor symptoms." },
      { id: "neuro_ms", cluster: "Demyelinating & neuromuscular disease", name: "Multiple sclerosis", keyFacts: "An autoimmune demyelinating disease of the central nervous system, disseminated in time and space.", epidemiology: "Typically affects young adults, commoner in women and at higher latitudes.", aetiology: "Autoimmune, with genetic susceptibility plus environmental factors (low vitamin D, Epstein-Barr virus).", pathophysiology: "Immune-mediated demyelination and axonal damage disrupt central nerve conduction, causing relapsing and later progressive deficits.", presentation: "Relapsing neurological symptoms separated in time and space: optic neuritis, sensory, motor, bladder.", investigations: "MRI brain and cord, lumbar puncture (oligoclonal bands), visual evoked potentials.", treatment: "Steroids for relapses; disease-modifying therapy; symptom control and MDT input." },
      { id: "neuro_myasthenia", management: {"def": "A[\"Myasthenia gravis\"]:::start --> B[\"Symptomatic: pyridostigmine (anticholinesterase)\"]:::good\nB -- \"inadequate control\" --> C[\"Immunosuppression: prednisolone + azathioprine\"]:::good\nC --> D[\"Consider thymectomy (esp. thymoma or young)\"]:::process\nA --> E{\"Myasthenic crisis? (respiratory/bulbar failure)\"}:::decision\nE -- \"yes\" --> F[\"ICU, monitor FVC, ventilate if needed\"]:::danger\nF --> G[\"IVIG or plasma exchange, treat trigger\"]:::good", "tips": {"A": "An autoimmune disease (anti-acetylcholine receptor antibodies) causing fatigable weakness - worse with activity and towards the end of the day, with ptosis, diplopia and bulbar or limb weakness.", "B": "First-line symptomatic treatment is the acetylcholinesterase inhibitor pyridostigmine, which prolongs acetylcholine action at the neuromuscular junction.", "C": "For inadequate control, add immunosuppression - corticosteroids (introduced carefully, as they can transiently worsen weakness) with a steroid-sparing agent such as azathioprine.", "D": "Thymectomy benefits patients with a thymoma (present in about 15%) and can help younger patients with generalised AChR-positive disease; image the mediastinum with CT.", "E": "Watch for myasthenic crisis - severe weakness with respiratory or bulbar failure, often triggered by infection, surgery or certain drugs.", "F": "Crisis: ICU admission with FVC monitoring and ventilatory support if needed; avoid precipitating drugs (aminoglycosides, beta-blockers).", "G": "Treat crisis with IV immunoglobulin or plasma exchange, and treat the precipitant."}}, cluster: "Demyelinating & neuromuscular disease", name: "Myasthenia gravis", keyFacts: "An autoimmune disorder of the neuromuscular junction causing fatigable weakness that worsens with use.", epidemiology: "Bimodal: younger women and older men; associated with thymic disease.", aetiology: "Antibodies to the acetylcholine receptor (or to MuSK); associated with thymoma and thymic hyperplasia.", pathophysiology: "Antibodies block and destroy postsynaptic acetylcholine receptors, so repeated stimulation fatigues the muscle.", presentation: "Fatigable weakness worse through the day: ptosis, diplopia, bulbar (chewing, swallow, speech) and proximal limb weakness.", investigations: "Anti-acetylcholine receptor (and anti-MuSK) antibodies, repetitive nerve stimulation or single-fibre EMG, CT thymus.", treatment: "Pyridostigmine and immunosuppression (steroids, azathioprine), thymectomy; myasthenic crisis (respiratory failure) needs FVC monitoring and IVIG or plasma exchange." },
      { id: "neuro_gbs", management: {"def": "A[\"Guillain-Barre syndrome\"]:::start --> B[\"Supportive care, monitor FVC and swallow\"]:::warn\nB --> C{\"Respiratory failure or bulbar weakness?\"}:::decision\nC -- \"yes (FVC falling)\" --> D[\"ICU, consider ventilation\"]:::danger\nC -- \"no\" --> E[\"Ward monitoring\"]:::good\nA --> F[\"IV immunoglobulin or plasma exchange\"]:::good\nF --> G[\"VTE prophylaxis, physiotherapy, autonomic monitoring\"]:::process", "tips": {"A": "An acute, usually ascending, symmetrical flaccid paralysis with areflexia, often 1-3 weeks after infection (e.g. Campylobacter); an immune-mediated demyelinating polyneuropathy.", "B": "The priority is monitoring for respiratory and bulbar failure - serial forced vital capacity (FVC), swallow and autonomic observations; nerve conduction studies and CSF (raised protein, normal cells) support the diagnosis.", "C": "Watch for deterioration needing airway or ventilatory support.", "D": "A falling FVC (below about 15-20 mL/kg or 1.5 L), or bulbar weakness with aspiration risk, needs ICU and consideration of intubation and ventilation.", "E": "Milder, stable disease: close monitoring on the ward.", "F": "Disease-modifying treatment is IV immunoglobulin or plasma exchange (equally effective) - corticosteroids do NOT help.", "G": "Add VTE prophylaxis and physiotherapy, and monitor for autonomic instability (arrhythmias, blood-pressure swings), pain and nutrition."}}, cluster: "Demyelinating & neuromuscular disease", name: "Guillain-Barré syndrome", keyFacts: "An acute, usually post-infective, immune-mediated polyneuropathy causing ascending weakness; watch the breathing.", epidemiology: "The commonest cause of acute flaccid paralysis; affects any age.", aetiology: "Post-infective (classically Campylobacter jejuni, also CMV and EBV) through molecular mimicry.", pathophysiology: "Antibody-mediated attack on peripheral nerve myelin (and axons) causes an acute demyelinating polyradiculoneuropathy.", presentation: "Progressive symmetrical ascending limb weakness with areflexia over days; sensory and autonomic features; respiratory and bulbar involvement.", investigations: "Lumbar puncture (albuminocytological dissociation: high protein, normal cells), nerve conduction studies, serial spirometry (FVC).", treatment: "IV immunoglobulin or plasma exchange; supportive care with FVC monitoring and ventilation if needed; VTE prophylaxis." },
      { id: "neuro_cord_compression", management: {"def": "A[\"Suspected cord compression: back pain + neurology\"]:::start --> B[\"Urgent whole-spine MRI within 24 h\"]:::process\nB --> C[\"Immediate dexamethasone 16 mg + PPI (unless contraindicated)\"]:::good\nC --> D[\"Flat bed rest + spinal precautions until stability known\"]:::warn\nD --> E[\"Contact MSCC coordinator, refer surgery + oncology\"]:::good\nE --> F{\"Definitive treatment\"}:::decision\nF -- \"fit, unstable or single level\" --> G[\"Surgical decompression + stabilisation\"]:::good\nF -- \"radiosensitive or unfit for surgery\" --> H[\"Radiotherapy\"]:::good\nG --> I[\"Rehabilitation, analgesia, VTE prophylaxis, treat primary\"]:::good\nH --> I", "tips": {"A": "Suspect spinal cord compression in any patient - especially with known cancer - who has new or progressive back pain with neurological symptoms (limb weakness, sensory change, bladder or bowel disturbance). Malignant spinal cord compression (MSCC) is the commonest cause.", "B": "NICE CG75: arrange an MRI of the whole spine within 24 hours of suspecting MSCC (sooner if rapidly progressing), because compression at multiple levels is common and plain films are inadequate.", "C": "Give immediate high-dose corticosteroid - dexamethasone 16 mg daily - with proton pump inhibitor cover and glucose monitoring, unless contraindicated (e.g. suspected lymphoma before biopsy), to reduce cord oedema while awaiting definitive treatment.", "D": "Nurse the patient flat with neutral spine alignment (log-roll) and spinal precautions until bony and neurological stability is established, to avoid worsening the injury.", "E": "Contact the MSCC coordinator and refer urgently to spinal surgery and clinical oncology; definitive treatment should ideally start within 24 hours of the MRI diagnosis.", "F": "Definitive treatment depends on tumour type, spinal stability, prognosis and fitness for surgery.", "G": "Surgical decompression with stabilisation is preferred for spinal instability, a single area of compression, or an uncertain diagnosis, in patients fit enough and with a reasonable prognosis.", "H": "Radiotherapy is used for radiosensitive tumours, multiple levels, or patients unfit for or not requiring surgery, and often as postoperative treatment.", "I": "Ongoing care: rehabilitation, analgesia, thromboprophylaxis, pressure-area and bladder/bowel care, and treatment of the underlying malignancy."}, "source": "NICE"}, cluster: "Spinal cord & autonomic disorders", name: "Spinal cord compression (incl. MSCC)", keyFacts: "Compression of the spinal cord is a neurosurgical and oncological emergency; malignant spinal cord compression (MSCC) - compression of the cord or cauda equina by tumour - is the commonest cause and needs treatment within 24 hours to preserve function.", epidemiology: "MSCC affects around 5-10% of cancer patients, most often from prostate, breast, lung, myeloma and renal cancers, and is the first presentation of malignancy in about 20% of cases.", aetiology: "Vertebral metastasis or direct tumour (MSCC) is the leading cause; also trauma (fracture or dislocation), disc prolapse, epidural abscess or haematoma, and degenerative canal stenosis. Compression is at the thoracic level in most MSCC cases.", pathophysiology: "A mass in or around the vertebral column compresses the cord (above L1/L2) or the cauda equina below it; venous congestion and oedema followed by arterial compromise cause progressive, potentially irreversible ischaemic injury - hence the urgency.", presentation: "Progressive back pain (often worse on lying flat, coughing or straining, and preceding neurology by weeks), then limb weakness, a sensory level, and bladder or bowel dysfunction; upper motor neurone signs (brisk reflexes, upgoing plantars) if above the conus, lower motor neurone signs at the cauda equina.", investigations: "Urgent whole-spine MRI is the investigation of choice (within 24 hours of suspicion, as compression at multiple levels is common); examine for a sensory level and assess anal tone; staging and biopsy if the primary is unknown.", treatment: "Immediate high-dose dexamethasone (16 mg daily with PPI cover and glucose monitoring) unless contraindicated; flat bed rest with spinal precautions until stability is confirmed; urgent referral to the MSCC coordinator and to spinal surgery and oncology for definitive treatment - surgical decompression and stabilisation, or radiotherapy; analgesia and VTE prophylaxis." },
      { id: "neuro_cauda_equina", management: {"def": "A[\"Suspected cauda equina: red flags\"]:::start --> B[\"Assess: bilateral sciatica, saddle anaesthesia, bladder/bowel, anal tone\"]:::process\nB --> C[\"Emergency whole-spine MRI (do not delay)\"]:::warn\nC --> D{\"MRI confirms cauda equina compression?\"}:::decision\nD -- \"yes\" --> E[\"Immediate referral to spinal surgery\"]:::danger\nD -- \"no\" --> F[\"Seek alternative cause, senior review\"]:::good\nE --> G[\"Urgent surgical decompression, ideally within 48 h\"]:::good\nG --> H[\"Catheterise, treat cause, rehab and follow-up\"]:::good", "tips": {"A": "Cauda equina syndrome is a surgical emergency - suspect it with the red-flag combination of severe low back pain, bilateral sciatica, saddle (perianal) numbness, and bladder, bowel or sexual dysfunction.", "B": "Examine specifically for saddle sensory loss, reduced anal tone and voluntary squeeze on PR, bilateral leg weakness with reduced reflexes, and ask about urinary symptoms - painless retention with overflow incontinence is a late, ominous sign.", "C": "Arrange an emergency MRI of the whole spine (out of hours if needed) - it is the definitive investigation and must not be delayed; a post-void bladder scan supports but does not replace it.", "D": "MRI confirms the level and cause of compression and guides surgery; if it does not show cauda equina compression, look for an alternative explanation with senior input.", "E": "Refer immediately to spinal surgery (neurosurgery or orthopaedic spinal) - the priority is emergency decompression to prevent permanent deficit.", "F": "If imaging is negative, reassess for other causes (e.g. a conus lesion, peripheral neuropathy or non-compressive causes) and involve seniors.", "G": "Surgical decompression (urgent discectomy or laminectomy) should be done as soon as possible - outcomes are better the earlier it is performed, ideally within 48 hours of symptom onset and without avoidable delay.", "H": "After surgery: catheterise for retention, treat the underlying cause, and provide rehabilitation with bladder, bowel and sexual function follow-up."}, "source": "Spinal emergency"}, cluster: "Spinal cord & autonomic disorders", name: "Cauda equina syndrome", keyFacts: "Compression of the cauda equina (the lumbosacral nerve roots below the conus at around L1/L2), a surgical emergency; delayed decompression risks permanent bladder, bowel and sexual dysfunction and leg weakness.", epidemiology: "Uncommon but a critical not-to-miss diagnosis; most often from a large central lumbar disc herniation (L4/5 or L5/S1) in adults aged 30-50.", aetiology: "Large central lumbar disc prolapse is the commonest cause; also tumour (including metastasis), trauma, epidural abscess or haematoma, spinal stenosis and post-surgical causes.", pathophysiology: "Compression of the lumbosacral nerve roots produces a lower motor neurone pattern of injury; the sacral roots (S2-S4) supplying the bladder, bowel and perineum are especially vulnerable, causing sphincter dysfunction.", presentation: "Red flags - bilateral sciatica, saddle (perianal) anaesthesia, bladder dysfunction (retention then overflow incontinence), bowel incontinence or reduced anal tone, and lower limb weakness with reduced reflexes; reduced sexual sensation. Painless urinary retention with overflow is an ominous late sign.", investigations: "Emergency whole-spine MRI is the definitive investigation; assess perianal sensation, anal tone on PR and a post-void bladder scan for residual volume; do not delay imaging for other tests.", treatment: "Emergency referral to spinal surgery for urgent decompression (discectomy or laminectomy), as soon as possible and ideally within 48 hours of onset - earlier surgery gives better outcomes; catheterise for retention; treat the underlying cause; analgesia and supportive care." },
      { id: "neuro_neurogenic_shock", management: {"def": "A[\"Hypotension after acute spinal cord injury\"]:::start --> B[\"ABCDE + full spinal immobilisation\"]:::good\nB --> C[\"Secure airway: high cord lesions impair breathing\"]:::warn\nC --> D{\"Exclude haemorrhagic shock\"}:::decision\nD -- \"bleeding present\" --> E[\"Treat haemorrhage first: control + transfuse\"]:::danger\nD -- \"warm peripheries + bradycardia\" --> F[\"Neurogenic shock likely\"]:::process\nF --> G[\"Cautious IV fluids to target MAP\"]:::good\nG --> H{\"Still hypotensive?\"}:::decision\nH -- \"no\" --> K[\"Maintain MAP, prevent secondary cord injury, ICU\"]:::good\nH -- \"yes\" --> I[\"Vasopressor (noradrenaline): keep MAP 85-90\"]:::warn\nI --> J{\"Symptomatic bradycardia?\"}:::decision\nJ -- \"no\" --> K\nJ -- \"yes\" --> L[\"Atropine +/- temporary pacing\"]:::warn\nL --> K\nK --> M[\"Whole-spine imaging + urgent spinal surgery referral\"]:::good", "tips": {"A": "Suspect neurogenic shock when a patient with an acute spinal cord injury (usually cervical or upper thoracic, at or above T6) is hypotensive - especially with a paradoxically normal or slow heart rate and warm peripheries.", "B": "Manage as major trauma: ABCDE with full in-line spinal immobilisation (collar and blocks) to prevent further cord injury while you assess.", "C": "High cervical lesions (C3-C5 supply the diaphragm) can cause respiratory failure - watch airway and breathing closely and be ready to intubate and ventilate.", "D": "Neurogenic shock is a diagnosis of exclusion in trauma - always assume and actively exclude haemorrhage first, as occult bleeding (chest, abdomen, pelvis, long bones) is far more immediately life-threatening.", "E": "If there is haemorrhage, control the bleeding and resuscitate with blood; do not attribute hypotension to the cord until blood loss is excluded and treated.", "F": "Neurogenic shock is suggested by hypotension with bradycardia (not the tachycardia of hypovolaemia) and warm, well-perfused, flushed skin below the lesion, reflecting lost sympathetic tone.", "G": "Give judicious IV fluids to restore perfusion but avoid over-transfusion - the problem is vasodilatation, not volume loss - guided by a target mean arterial pressure.", "H": "Reassess after fluids; hypotension persisting despite adequate filling needs vasoactive support.", "I": "Start a vasopressor - noradrenaline is commonly used as it restores vascular tone and gives some chronotropic support; aim to maintain a MAP of about 85-90 mmHg for the first days to optimise spinal cord perfusion and limit secondary injury.", "J": "Assess for symptomatic bradycardia, common with high lesions from unopposed vagal tone.", "L": "Treat symptomatic bradycardia with atropine; refractory or severe cases may need a temporary pacing wire.", "K": "Maintain the target MAP, prevent secondary cord injury (oxygenation, perfusion, temperature control) and monitor in a critical care or spinal injuries unit.", "M": "Arrange whole-spine imaging (CT and MRI) and urgent referral to spinal surgery; definitive care is in an ICU or specialist spinal injuries unit."}, "source": "Spinal injury emergency"}, cluster: "Spinal cord & autonomic disorders", name: "Neurogenic shock", keyFacts: "A distributive shock following acute spinal cord injury at or above T6, from loss of sympathetic tone; the classic triad is hypotension, bradycardia and warm, well-perfused peripheries. Distinct from spinal shock (the transient flaccidity and areflexia below the injury).", epidemiology: "Follows high cervical or upper thoracic cord injury and is more likely and more severe the higher and more complete the lesion; usually seen in major trauma (road traffic collisions, falls, sports and diving injuries).", aetiology: "Acute traumatic spinal cord injury above T6 is the classic cause; also high spinal or epidural anaesthesia and, rarely, other cord insults. The lesion interrupts sympathetic outflow (T1-L2) while leaving cardiac vagal (parasympathetic) tone unopposed.", pathophysiology: "Loss of descending sympathetic tone abolishes vasomotor control, causing widespread vasodilatation, venous pooling and a fall in systemic vascular resistance; unopposed vagal tone to the heart produces bradycardia - the hallmark that separates it from hypovolaemic shock, which causes tachycardia.", presentation: "Hypotension with paradoxical bradycardia and warm, dry, flushed skin below the lesion; features of the underlying cord injury (flaccid paralysis, a sensory level, priapism, loss of anal tone); hypothermia may develop from impaired thermoregulation.", investigations: "A clinical diagnosis of exclusion in trauma - actively exclude and treat haemorrhage first. Full trauma work-up with whole-spine imaging (CT and MRI), ECG, and continuous haemodynamic monitoring.", treatment: "ABCDE with full spinal immobilisation; secure the airway (high lesions threaten the diaphragm); cautious IV fluids guided by a target mean arterial pressure (aim MAP around 85-90 mmHg to perfuse the injured cord); vasopressors (noradrenaline) for persistent hypotension; atropine or temporary pacing for symptomatic bradycardia; urgent spinal surgery referral and critical care." },
      { id: "neuro_autonomic_dysreflexia", management: {"def": "A[\"Autonomic dysreflexia: severe headache + high BP, cord injury at/above T6\"]:::start --> B[\"Sit patient upright, loosen tight clothing\"]:::good\nB --> C[\"Check BP and monitor closely\"]:::process\nC --> D[\"Check bladder: unblock or insert catheter\"]:::warn\nD --> E{\"BP settled?\"}:::decision\nE -- \"yes\" --> I[\"Trigger removed: keep monitoring, prevent recurrence\"]:::good\nE -- \"no\" --> F[\"Check bowel loading and skin for triggers\"]:::warn\nF --> G{\"BP still high?\"}:::decision\nG -- \"no\" --> I\nG -- \"yes\" --> H[\"Short-acting antihypertensive (GTN or nifedipine)\"]:::danger\nH --> I", "tips": {"A": "Autonomic dysreflexia is a hypertensive emergency in a person with a spinal cord injury at or above T6, with a sudden pounding headache and a sharp rise in blood pressure triggered by a noxious stimulus below the lesion; untreated it can cause seizures, stroke and death.", "B": "First action: sit the patient fully upright and loosen any tight clothing or constricting devices - the upright posture lowers blood pressure by orthostatic pooling.", "C": "Measure blood pressure frequently (every few minutes); cord-injured patients have a low baseline, so a systolic rise of 20-40 mmHg above their normal is significant.", "D": "Search for the trigger, starting with the bladder (the commonest cause): check the catheter for kinks or blockage and flush or replace it, or catheterise if not already done, using local anaesthetic gel to avoid adding stimulation.", "E": "Reassess blood pressure after relieving the bladder; if it settles, the trigger has been removed.", "F": "If blood pressure remains high, check the bowel for faecal impaction (gently, with anaesthetic gel) and examine the skin for pressure sores, ingrown toenails or other noxious stimuli.", "G": "Reassess again; persistent hypertension despite removing obvious triggers needs pharmacological control.", "H": "Give a rapid-acting, short-duration antihypertensive such as GTN or nifedipine, titrating carefully to avoid overshoot hypotension, while continuing to search for the cause.", "I": "Once the trigger is removed and blood pressure controlled, continue monitoring (it can recur) and put preventive measures in place - a good bladder and bowel regimen, skin care and patient education."}, "source": "Spinal injury emergency"}, cluster: "Spinal cord & autonomic disorders", name: "Autonomic dysreflexia", keyFacts: "A sudden, potentially life-threatening hypertensive crisis in people with a spinal cord injury at or above T6, triggered by a noxious stimulus below the level of the lesion; it can cause seizures, haemorrhagic stroke and death if untreated.", epidemiology: "Occurs in around half or more of people with chronic cord injury at or above T6, usually developing after the acute spinal-shock phase has resolved (weeks or more after injury).", aetiology: "A noxious stimulus below the lesion - most commonly a distended or blocked bladder (blocked catheter) or a loaded rectum; also UTI, pressure sores, ingrown toenails, tight clothing, fractures and labour.", pathophysiology: "The stimulus triggers a massive reflex sympathetic discharge below the lesion causing vasoconstriction and severe hypertension; descending inhibitory signals cannot cross the cord injury, so the compensatory response (vagal bradycardia, flushing and sweating) is limited to above the lesion and the hypertension goes unopposed below it.", presentation: "Sudden severe pounding headache with a sharp rise in blood pressure; flushing and sweating above the lesion with pallor and piloerection below; bradycardia, nasal congestion, anxiety and visual disturbance. Untreated it can cause seizures, intracranial haemorrhage and death.", investigations: "A clinical diagnosis - measure blood pressure (a systolic rise of 20-40 mmHg above the patient's low baseline is significant) and then systematically search for the trigger (bladder, bowel, skin); ECG for bradyarrhythmia.", treatment: "Sit the patient upright and loosen tight clothing to lower the blood pressure; find and remove the trigger - check and unblock or insert a urinary catheter first, then check for faecal loading and skin causes; if BP remains high give a short-acting antihypertensive (e.g. GTN or nifedipine); monitor closely and prevent recurrence with good bladder and bowel care." },
      { id: "neuro_bells", management: {"def": "A[\"Bell palsy (LMN facial weakness)\"]:::start --> B[\"Exclude stroke and mimics (forehead spared in UMN)\"]:::process\nB --> C{\"Within 72 hours of onset?\"}:::decision\nC -- \"yes\" --> D[\"Prednisolone (e.g. 50 mg for 10 days)\"]:::good\nC -- \"no\" --> E[\"Steroids less likely to help\"]:::warn\nD --> F[\"Eye care: lubricants, tape eye shut at night\"]:::good\nF --> G[\"Most recover in weeks, refer if none by 3 weeks\"]:::process\nA --> H[\"Antivirals only in severe cases (specialist)\"]:::process", "tips": {"A": "Acute unilateral lower motor neurone facial nerve palsy (the forehead IS affected), idiopathic; a diagnosis of exclusion.", "B": "Distinguish from an upper motor neurone lesion (stroke - forehead spared) and from other causes (Ramsay Hunt/zoster, otitis media, parotid tumour, Lyme).", "C": "Steroid benefit is greatest when started early.", "D": "Offer prednisolone within 72 hours of onset (e.g. 50 mg daily for 10 days, or a reducing course) to improve recovery.", "E": "If presenting after 72 hours, steroid benefit is less clear - individualise.", "F": "Protect the eye: artificial tears by day, ointment and taping the eye closed at night (risk of exposure keratopathy).", "G": "Most recover within 2-3 weeks and fully by 3-4 months; review and refer to ENT/neurology if no improvement by 3 weeks or atypical features.", "H": "Antivirals are not routine; consider adding them in severe palsy under specialist advice (treat Ramsay Hunt with aciclovir plus a steroid)."}}, cluster: "Peripheral nerve disorders", name: "Bell's palsy", keyFacts: "An acute, idiopathic, lower motor neurone facial palsy that involves the forehead.", epidemiology: "Common, affecting all ages, with higher risk in pregnancy and diabetes.", aetiology: "Idiopathic, probably from viral (herpes simplex) inflammation of the facial nerve.", pathophysiology: "Inflammatory oedema compresses the facial nerve in its bony canal, causing unilateral weakness of all the facial muscles.", presentation: "Sudden unilateral lower motor neurone facial weakness including forehead.", investigations: "Clinical; consider causes if atypical (Lyme, zoster).", treatment: "Prednisolone within 72 hours; eye protection with lubricants and taping at night." },
      { id: "neuro_carpal", cluster: "Peripheral nerve disorders", name: "Carpal tunnel syndrome", keyFacts: "Compression of the median nerve at the wrist causing tingling in the radial three-and-a-half digits.", epidemiology: "Common, more so in women and in middle age.", aetiology: "Often idiopathic; also pregnancy, hypothyroidism, diabetes, rheumatoid arthritis and repetitive use.", pathophysiology: "Raised pressure within the carpal tunnel compresses the median nerve, impairing its sensory and motor function.", presentation: "Tingling and pain in the thumb, index and middle fingers, worse at night.", investigations: "Tinel/Phalen tests, nerve conduction studies.", treatment: "Wrist splints, corticosteroid injection, surgical decompression for severe disease." },
      { id: "neuro_horner", cluster: "Peripheral nerve disorders", name: "Horner syndrome", keyFacts: "The triad of partial ptosis, miosis and anhidrosis from interruption of the sympathetic supply to the eye.", epidemiology: "Uncommon; the likely cause depends on the level of the lesion.", aetiology: "By level: central (stroke, MS, syringomyelia), preganglionic (Pancoast tumour, neck or thyroid surgery), postganglionic (carotid dissection, cluster headache).", pathophysiology: "A lesion anywhere along the three-neuron sympathetic pathway reduces sympathetic tone to the eye and face.", presentation: "Partial ptosis, a constricted pupil (miosis) and reduced sweating (anhidrosis) on the same side; mild enophthalmos.", investigations: "Localise the level clinically (anhidrosis pattern); imaging per suspected cause (CT/MRI, carotid imaging, CT chest apex).", treatment: "Treat the underlying cause; a painful Horner's with neck pain needs urgent exclusion of carotid dissection." },
      { id: "neuro_cns_tumour", cluster: "CNS tumours & infection", name: "CNS tumours", keyFacts: "Brain tumours, most commonly metastases in adults; present with raised intracranial pressure, focal deficits or seizures.", epidemiology: "Metastases are the commonest brain tumour overall; gliomas and meningiomas are the commonest primaries.", aetiology: "Primary (gliomas, meningiomas, pituitary adenomas, schwannomas) or secondary (metastases from lung, breast, melanoma, renal, bowel).", pathophysiology: "An expanding intracranial mass and surrounding oedema raise intracranial pressure and disrupt local brain function.", presentation: "Progressive headache (worse on waking and coughing), vomiting, papilloedema, focal deficits, new seizures, personality change.", investigations: "MRI with contrast (first-line); biopsy for tissue diagnosis; CT body to find a primary if metastatic.", treatment: "Dexamethasone for oedema; surgery, radiotherapy and chemotherapy as appropriate; seizure control; MDT and palliative input." },
      { id: "neuro_encephalitis", cluster: "CNS tumours & infection", name: "Encephalitis", keyFacts: "Inflammation of the brain parenchyma, usually viral; herpes simplex is the key treatable cause.", epidemiology: "Uncommon but serious; herpes simplex virus is the commonest sporadic cause in the UK.", aetiology: "Viral (herpes simplex virus, varicella-zoster, enteroviruses) and autoimmune (e.g. anti-NMDA receptor) causes.", pathophysiology: "Viral invasion (herpes simplex has a temporal-lobe predilection) causes inflammation, oedema and neuronal injury.", presentation: "Fever, headache, altered consciousness and behaviour, seizures and focal deficits (more than the meningism of meningitis).", investigations: "MRI (temporal lobe changes), lumbar puncture with viral PCR, EEG, bloods; CT before LP if raised-ICP signs.", treatment: "Start empirical IV aciclovir immediately on suspicion; supportive care; do not wait for confirmation." },
      { id: "neuro_cerebral_palsy", cluster: "Developmental & nutritional disorders", name: "Cerebral palsy", keyFacts: "A non-progressive disorder of movement and posture from injury to the developing brain.", epidemiology: "The commonest cause of physical disability in childhood.", aetiology: "Antenatal (most, e.g. infection, malformation), perinatal (hypoxic-ischaemic injury, prematurity) or postnatal (meningitis, trauma) brain injury.", pathophysiology: "A static injury to the immature brain produces evolving motor signs as the child develops, though the lesion itself does not progress.", presentation: "Delayed motor milestones, abnormal tone and posture, persistent primitive reflexes; spastic, dyskinetic or ataxic types; associated learning, vision and epilepsy problems.", investigations: "Clinical diagnosis; MRI to identify the cause; assess associated impairments.", treatment: "MDT support (physiotherapy, occupational and speech therapy), spasticity management (baclofen, botulinum toxin), orthopaedic care." },
      { id: "neuro_wernicke", cluster: "Developmental & nutritional disorders", name: "Wernicke's encephalopathy", keyFacts: "An acute, reversible thiamine (vitamin B1) deficiency emergency; untreated it progresses to irreversible Korsakoff syndrome.", epidemiology: "Most often in chronic alcohol misuse; also hyperemesis, malnutrition and after bariatric surgery.", aetiology: "Thiamine deficiency, classically from alcohol dependence.", pathophysiology: "Thiamine is a cofactor for glucose metabolism; deficiency damages the mammillary bodies and thalamus.", presentation: "Classic triad of confusion, ophthalmoplegia or nystagmus, and ataxia (often incomplete).", investigations: "Clinical diagnosis; do not delay treatment; check glucose and give thiamine before any glucose.", treatment: "Immediate IV thiamine (Pabrinex) before glucose; treat the cause; this prevents progression to Korsakoff amnesia." },
    ],
  },
  {
    id: "psychiatry",
    name: "Psychiatry & Mental Health",
    icon: "🧩",
    conditions: [
      { id: "psych_depression", management: {"def": "A[\"Depression\"]:::start --> B{\"Severity\"}:::decision\nB -- \"less severe\" --> C[\"Self-help / CBT / exercise\"]:::good\nB -- \"more severe\" --> D[\"SSRI + high-intensity CBT\"]:::good\nC --> E{\"Adequate response?\"}:::decision\nD --> E\nE -- \"no\" --> F[\"Switch antidepressant or add therapy\"]:::good\nF --> G[\"Augment; refer to specialist\"]:::warn\nD -- \"risk / psychosis / refractory\" --> H[\"Urgent specialist; ECT if severe\"]:::danger", "tips": {"A": "Persistent low mood or anhedonia with somatic and cognitive symptoms; assess severity and suicide risk (NICE stepped care).", "B": "NICE (2022) categorises as 'less severe' (subthreshold/mild) or 'more severe' (moderate/severe) rather than by a single score.", "C": "Less severe: least-intrusive options first — guided self-help, group CBT, behavioural activation or exercise; offer an antidepressant only if preferred, not routinely first.", "D": "More severe: an antidepressant (usually an SSRI such as sertraline) with a high-intensity psychological therapy like CBT.", "E": "Review at 2–4 weeks (1–2 weeks if under 25 or higher risk) for response and side effects.", "F": "If inadequate: check adherence and dose, then switch antidepressant or add psychological therapy.", "G": "Augment (e.g. add a second agent) or refer to mental health services for treatment-resistant depression.", "H": "Urgent specialist care for high suicide risk, psychotic depression or severe/refractory illness; ECT for life-threatening or treatment-resistant severe depression."}}, cluster: "Mood disorders", name: "Depression", keyFacts: "A common mood disorder of persistent low mood and anhedonia; always assess suicide risk.", epidemiology: "One of the commonest mental health conditions, roughly twice as common in women.", aetiology: "Biopsychosocial: genetic vulnerability, adverse life events, chronic illness and social stressors.", pathophysiology: "Thought to involve dysregulation of monoamine neurotransmitters (serotonin, noradrenaline) and the stress (HPA) axis.", presentation: "Low mood, anhedonia, low energy with sleep, appetite and concentration change for over two weeks.", investigations: "PHQ-9, risk assessment, exclude organic causes (TFTs, FBC).", treatment: "Guided self-help/CBT for mild; SSRI plus therapy for moderate-severe; safety-net and follow up early." },
      { id: "psych_bipolar", management: {"def": "A[\"Bipolar affective disorder\"]:::start --> B{\"Current episode\"}:::decision\nB -- \"acute mania\" --> C[\"Antipsychotic, stop antidepressant\"]:::good\nB -- \"bipolar depression\" --> D[\"Quetiapine or lamotrigine\"]:::good\nC --> E[\"Long-term: lithium first-line\"]:::good\nD --> E\nE -- \"insufficient / not tolerated\" --> F[\"Add or switch to valproate\"]:::good\nE --> G[\"Monitor lithium level, renal and thyroid function\"]:::warn", "tips": {"A": "Recurrent episodes of mania/hypomania and depression; treat the acute episode then prevent relapse.", "B": "Management depends on the current mood state.", "C": "Acute mania: an antipsychotic (olanzapine, quetiapine, risperidone or haloperidol); stop any antidepressant, which can worsen mania.", "D": "Bipolar depression: an atypical antipsychotic (quetiapine) or lamotrigine; avoid antidepressant monotherapy (switch risk).", "E": "Lithium is the first-line long-term mood stabiliser.", "F": "If lithium is insufficient or not tolerated, use valproate - but never in women of childbearing potential (teratogenic).", "G": "Lithium has a narrow therapeutic index: monitor levels (12 h post-dose), and renal, thyroid and calcium function; watch for toxicity (tremor, ataxia, confusion)."}}, cluster: "Mood disorders", name: "Bipolar affective disorder", keyFacts: "A mood disorder of episodes of mania or hypomania alternating with depression.", epidemiology: "Affects around 1-2% of people, with onset typically in late adolescence or early adulthood.", aetiology: "Strongly genetic, with stress and disrupted sleep acting as triggers.", pathophysiology: "Dysregulation of monoamine and circadian systems produces cyclical extremes of mood, energy and activity.", presentation: "Episodes of mania (elevated mood, grandiosity, reduced sleep) alternating with depression.", investigations: "Mood history, collateral, risk assessment, exclude organic/drug causes.", treatment: "Mood stabiliser (lithium) or antipsychotic; specialist care; monitor lithium levels and avoid antidepressant monotherapy." },
      { id: "psych_postnatal", cluster: "Mood disorders", name: "Postnatal depression", keyFacts: "A depressive episode within a year of childbirth, distinct from the transient baby blues.", epidemiology: "Affects roughly 1 in 10 mothers.", aetiology: "Hormonal change, sleep deprivation, psychosocial stress and a history of depression.", pathophysiology: "Interacting hormonal, biological and psychosocial changes around birth precipitate a depressive episode in vulnerable women.", presentation: "Persistent low mood, tearfulness, guilt within a year of birth; distinct from transient baby blues.", investigations: "Edinburgh Postnatal Depression Scale, risk assessment including to infant.", treatment: "Psychological therapy; SSRI considering breastfeeding; health visitor and perinatal mental health support." },
      { id: "psych_gad", management: {"def": "A[\"Generalised anxiety disorder\"]:::start --> B[\"Step 1: education + active monitoring\"]:::good\nB --> C[\"Step 2: low-intensity self-help\"]:::good\nC --> D{\"Marked impairment or no improvement?\"}:::decision\nD -- \"yes\" --> E[\"Step 3: SSRI or high-intensity CBT\"]:::good\nE --> F[\"Try SNRI, then pregabalin\"]:::good\nF --> G[\"Step 4: specialist referral\"]:::warn", "tips": {"A": "Excessive, hard-to-control worry on most days for 6+ months with somatic symptoms; managed by NICE stepped care.", "B": "Step 1 (all): identify, educate and actively monitor.", "C": "Step 2: low-intensity psychological interventions — guided self-help or psychoeducational groups.", "D": "Step up if there is marked functional impairment or no improvement.", "E": "Step 3: an SSRI (sertraline first-line, off-label) OR a high-intensity psychological intervention (CBT or applied relaxation).", "F": "If the first SSRI fails or isn't tolerated: try another SSRI or an SNRI, then consider pregabalin. Avoid benzodiazepines except short-term in crises.", "G": "Step 4: refer to specialist mental health services for complex, refractory or high-risk cases."}}, cluster: "Anxiety & stress-related disorders", name: "Generalised anxiety disorder", keyFacts: "Excessive, uncontrollable worry about everyday matters with physical symptoms of arousal.", epidemiology: "Common, and frequently coexisting with depression.", aetiology: "Genetic predisposition, personality, chronic stress and substance use.", pathophysiology: "Heightened limbic (amygdala) reactivity with impaired top-down regulation produces persistent anxiety and autonomic arousal.", presentation: "Excessive uncontrollable worry with restlessness, fatigue, poor concentration, muscle tension.", investigations: "GAD-7, exclude hyperthyroidism and substance use.", treatment: "Stepped care: psychoeducation, CBT, SSRI; avoid long-term benzodiazepines." },
      { id: "psych_panic", cluster: "Anxiety & stress-related disorders", name: "Panic disorder", keyFacts: "Recurrent unexpected panic attacks with intense fear and somatic symptoms, plus fear of further attacks.", epidemiology: "Common, often beginning in early adulthood and commoner in women.", aetiology: "Genetic and temperamental vulnerability, with triggers including stress and stimulants.", pathophysiology: "A false alarm in the brain's fear circuitry triggers a surge of autonomic symptoms that catastrophic misinterpretation amplifies.", presentation: "Recurrent unexpected panic attacks with palpitations, breathlessness, fear of dying.", investigations: "Clinical; exclude cardiac and endocrine causes.", treatment: "CBT first line; SSRI; breathing techniques; reduce caffeine." },
      { id: "psych_ocd", management: {"def": "A[\"Obsessive-compulsive disorder\"]:::start --> B{\"Functional impairment\"}:::decision\nB -- \"mild\" --> C[\"Low-intensity CBT with ERP\"]:::good\nB -- \"moderate\" --> D[\"SSRI or more intensive CBT (ERP)\"]:::good\nB -- \"severe\" --> E[\"SSRI + high-intensity CBT (ERP)\"]:::good\nC -- \"inadequate\" --> D\nD -- \"inadequate\" --> F[\"Switch SSRI, or clomipramine\"]:::good\nF --> G[\"Specialist referral, consider augmentation\"]:::warn", "tips": {"A": "Intrusive obsessions with compulsive rituals that are time-consuming or distressing; NICE stepped care by impairment.", "B": "Match treatment intensity to functional impairment.", "C": "Mild: a low-intensity psychological intervention - CBT including exposure and response prevention (ERP), or guided self-help.", "D": "Moderate: offer either an SSRI or more intensive CBT with ERP.", "E": "Severe: combine an SSRI with high-intensity CBT (ERP).", "F": "If an SSRI fails (often a higher dose and longer trial than in depression), switch to another SSRI or to clomipramine.", "G": "Refer to specialist services for treatment-resistant OCD; consider augmentation (e.g. adding an antipsychotic)."}}, cluster: "Anxiety & stress-related disorders", name: "Obsessive-compulsive disorder", keyFacts: "Intrusive obsessional thoughts that drive compulsive rituals and impair daily function.", epidemiology: "Common, usually starting in adolescence or early adulthood.", aetiology: "Genetic predisposition and altered cortico-striatal circuitry; it can follow streptococcal infection in children.", pathophysiology: "Dysfunction of cortico-striato-thalamic circuits and serotonin signalling sustains the obsession-compulsion cycle.", presentation: "Intrusive obsessional thoughts driving compulsive rituals that impair function.", investigations: "Clinical; assess severity and impact.", treatment: "CBT with exposure and response prevention; SSRI (often higher dose)." },
      { id: "psych_ptsd", management: {"def": "A[\"Post-traumatic stress disorder\"]:::start --> B{\"Within 1 month of trauma?\"}:::decision\nB -- \"yes, mild\" --> C[\"Active monitoring (watchful waiting)\"]:::good\nB -- \"established PTSD\" --> D[\"Trauma-focused CBT or EMDR\"]:::good\nD -- \"no response / preference\" --> E[\"SSRI or venlafaxine\"]:::good\nE -- \"inadequate\" --> F[\"Specialist, consider augmentation\"]:::warn\nA --> G[\"Avoid routine debriefing and benzodiazepines\"]:::warn", "tips": {"A": "Re-experiencing (flashbacks, nightmares), avoidance, hyperarousal and negative mood after trauma; NICE stepped care.", "B": "Timing and severity guide the first step.", "C": "Mild symptoms within a month of trauma: active monitoring with follow-up within a month (many resolve spontaneously).", "D": "Established PTSD: first-line is a trauma-focused psychological therapy - trauma-focused CBT or eye movement desensitisation and reprocessing (EMDR).", "E": "Drug treatment (an SSRI such as sertraline, or venlafaxine) if preferred, or if the person does not engage with or respond to therapy.", "F": "For treatment-resistant PTSD refer to specialist services; consider an antipsychotic as augmentation.", "G": "Do NOT offer single-session psychological debriefing; avoid benzodiazepines and routine drug treatment for the core disorder."}}, cluster: "Anxiety & stress-related disorders", name: "Post-traumatic stress disorder", keyFacts: "Re-experiencing, avoidance and hyperarousal following exposure to a traumatic event.", epidemiology: "Common after major trauma, with higher risk after interpersonal violence.", aetiology: "Exposure to a traumatic event, with risk modified by prior trauma, support and coping style.", pathophysiology: "Inadequate processing of the traumatic memory with an overactive fear response keeps the memory vivid and intrusive.", presentation: "Re-experiencing, avoidance, hyperarousal and negative mood after trauma.", investigations: "Clinical history, screening tools.", treatment: "Trauma-focused CBT or EMDR; SSRI/venlafaxine if therapy declined or insufficient." },
      { id: "psych_schizophrenia", management: {"def": "A[\"First-episode psychosis / schizophrenia\"]:::start --> B[\"Oral antipsychotic + CBT and family therapy\"]:::good\nB --> C{\"Adequate response after 4-6 weeks?\"}:::decision\nC -- \"no (adherent)\" --> D[\"Switch to a different antipsychotic\"]:::good\nD --> E{\"Two adequate trials failed?\"}:::decision\nE -- \"yes (treatment-resistant)\" --> F[\"Clozapine\"]:::warn\nC -- \"yes\" --> G[\"Continue and monitor metabolic health\"]:::good\nA --> H[\"Refer to early intervention in psychosis\"]:::process", "tips": {"A": "Psychosis with positive symptoms (delusions, hallucinations), negative symptoms and disorganisation; offer an oral antipsychotic with psychological therapy (CBT and family intervention).", "B": "Choose the antipsychotic together with the person, weighing side effects (metabolic, extrapyramidal, prolactin).", "C": "Give an adequate trial - an optimised dose for 4-6 weeks - before judging response.", "D": "If ineffective despite adherence, switch to another antipsychotic.", "E": "Treatment resistance means an inadequate response to two different antipsychotics, each an adequate trial.", "F": "Clozapine is the drug of choice for treatment-resistant schizophrenia; it needs registration and regular full blood counts (agranulocytosis).", "G": "Once effective, continue and monitor weight, lipids, glucose, ECG and prolactin.", "H": "Refer first-episode psychosis to an early-intervention service."}}, cluster: "Psychotic disorders", name: "Schizophrenia", keyFacts: "A psychotic disorder with positive symptoms (delusions, hallucinations) and negative symptoms (apathy, flat affect).", epidemiology: "Affects around 1% of people, typically presenting in young adulthood.", aetiology: "Genetic predisposition with environmental factors such as cannabis use, urban birth and obstetric complications.", pathophysiology: "Excess mesolimbic dopamine underlies the positive symptoms, with wider network and structural brain changes contributing.", presentation: "Delusions, hallucinations, thought disorder (positive) and apathy, blunted affect (negative).", investigations: "Mental state exam, risk assessment, exclude substances and organic causes.", treatment: "Antipsychotics, psychological therapy, early intervention service; monitor metabolic side effects." },
      { id: "psych_delusional_parasitosis", cluster: "Psychotic disorders", name: "Delusional parasitosis", keyFacts: "A fixed false belief of being infested with parasites despite no evidence; it may be primary or secondary.", epidemiology: "Uncommon; commoner in middle-aged and older women.", aetiology: "Primary: an isolated monosymptomatic delusional disorder (Ekbom syndrome). Secondary: to psychiatric illness (schizophrenia, depression), organic disease (B12 deficiency, dementia) or substances (cocaine, amphetamines).", pathophysiology: "An encapsulated delusional belief of infestation; in secondary cases it reflects the underlying psychiatric, organic or drug cause.", presentation: "Unshakeable conviction of skin infestation with itch and excoriation; the matchbox sign (bringing in self-collected skin or debris as 'specimens').", investigations: "Exclude real infestation and organic or drug causes (FBC, B12, TFTs, glucose, drug history); collateral history.", treatment: "Treat any secondary cause; build rapport; an antipsychotic (e.g. risperidone) for primary disease; dermatology and psychiatry liaison." },
      { id: "psych_anorexia", cluster: "Eating disorders", name: "Anorexia nervosa", keyFacts: "Restriction of intake with a low body weight, an intense fear of weight gain and a distorted body image; it has the highest mortality of any psychiatric illness.", epidemiology: "Predominantly young women, though increasingly recognised in men.", aetiology: "Genetic, psychological (perfectionism, a need for control) and sociocultural factors.", pathophysiology: "Sustained energy restriction causes profound multisystem physiological disturbance; rapid refeeding risks refeeding syndrome (falling phosphate, potassium and magnesium).", presentation: "Low body mass index, fear of weight gain and body-image distortion; amenorrhoea, lanugo hair, bradycardia, hypotension and cold intolerance.", investigations: "BMI, U&E and phosphate, ECG (bradycardia, long QT), FBC, glucose; SCOFF screen; formal medical-risk assessment (MEED/MARSIPAN).", treatment: "Specialist eating-disorder service, psychological therapy, and careful refeeding with electrolyte monitoring; admit if at high medical risk." },
      { id: "psych_bulimia", cluster: "Eating disorders", name: "Bulimia nervosa", keyFacts: "Recurrent binge eating with compensatory purging, usually at a normal weight; look for the signs of vomiting.", epidemiology: "Commoner than anorexia, typically in young women.", aetiology: "Genetic, psychological and sociocultural factors, often with low self-esteem and impulsivity.", pathophysiology: "Binge-purge cycles cause electrolyte disturbance (hypokalaemia from vomiting or laxatives) and a metabolic alkalosis, risking arrhythmia.", presentation: "Binge eating with self-induced vomiting or laxative misuse at a normal or raised weight; Russell's sign (knuckle calluses), dental erosion, parotid swelling and hypokalaemia.", investigations: "U&E (hypokalaemia), ECG, bicarbonate (alkalosis); SCOFF screen; assess risk.", treatment: "Guided self-help and eating-disorder-focused CBT; high-dose fluoxetine can help; correct electrolyte disturbance; specialist service." },
      { id: "psych_alcohol", management: {"def": "A[\"Alcohol dependence\"]:::start --> B{\"Withdrawal risk / wants to stop?\"}:::decision\nB -- \"assisted withdrawal\" --> C[\"Chlordiazepoxide reducing regimen\"]:::good\nC --> D[\"Pabrinex (thiamine) to prevent Wernicke\"]:::warn\nD --> E{\"Delirium tremens or seizures?\"}:::decision\nE -- \"yes\" --> F[\"Admit, benzodiazepines, treat DTs\"]:::danger\nC --> G[\"Relapse prevention: acamprosate or naltrexone\"]:::good\nB -- \"not ready\" --> H[\"Brief intervention, motivational support\"]:::process", "tips": {"A": "Craving, tolerance, withdrawal and prioritising alcohol; assess dependence severity (e.g. SADQ) and withdrawal risk.", "B": "Choose between medically-assisted withdrawal and harm-reduction/motivational work.", "C": "Assisted withdrawal: a benzodiazepine (chlordiazepoxide) in a fixed or symptom-triggered reducing regimen, community or inpatient by severity.", "D": "Give parenteral thiamine (Pabrinex) to prevent Wernicke encephalopathy - always before or with any glucose.", "E": "Watch for complicated withdrawal.", "F": "Delirium tremens (48-72 h: confusion, hallucinations, autonomic instability) or withdrawal seizures need admission and generous benzodiazepines (lorazepam first-line).", "G": "After withdrawal, offer relapse-prevention medication - acamprosate or oral naltrexone (or disulfiram) - plus psychosocial support.", "H": "If not ready to stop, give a brief intervention and motivational support, and treat comorbidities."}}, cluster: "Substance misuse", name: "Alcohol dependence", keyFacts: "A chronic pattern of compulsive drinking with tolerance and withdrawal; withdrawal can be life-threatening.", epidemiology: "Common, with a large burden of physical, psychological and social harm.", aetiology: "Genetic vulnerability interacting with social, psychological and environmental factors.", pathophysiology: "Chronic alcohol enhances inhibitory GABA and suppresses excitatory glutamate, so abrupt cessation causes rebound excitation, seizures and delirium tremens.", presentation: "Craving, tolerance, withdrawal, loss of control; withdrawal risks seizures and delirium tremens.", investigations: "AUDIT, LFTs, GGT, MCV; assess withdrawal with CIWA.", treatment: "Chlordiazepoxide-assisted withdrawal with thiamine; brief interventions, relapse-prevention support." },
      { id: "psych_adhd", cluster: "Neurodevelopmental & childhood disorders", name: "ADHD", keyFacts: "A neurodevelopmental disorder of inattention, hyperactivity and impulsivity present from childhood.", epidemiology: "Common in children, persisting into adulthood in many.", aetiology: "Strongly heritable, with prematurity and prenatal exposures contributing.", pathophysiology: "Altered dopaminergic and noradrenergic signalling in fronto-striatal networks impairs attention and impulse control.", presentation: "Persistent inattention, hyperactivity and impulsivity across settings since childhood.", investigations: "Structured assessment, collateral from school/home, rule out differentials.", treatment: "Behavioural strategies; stimulants (methylphenidate) under specialist care; monitor growth and cardiovascular status." },
      { id: "psych_conduct", cluster: "Neurodevelopmental & childhood disorders", name: "Conduct disorder", keyFacts: "A persistent childhood pattern of antisocial behaviour that violates the rights of others or major social norms.", epidemiology: "One of the commonest childhood psychiatric disorders, commoner in boys.", aetiology: "Genetic and temperamental factors with environmental adversity (family dysfunction, abuse, deprivation); overlaps with ADHD.", pathophysiology: "Interacting biological vulnerability and environmental adversity drive persistent rule-breaking and aggression; it may progress to antisocial personality disorder.", presentation: "Aggression to people or animals, destruction of property, deceitfulness or theft, and serious rule violations beyond ordinary mischief.", investigations: "Clinical assessment with collateral from home and school; screen for ADHD, mood and substance use; safeguarding assessment.", treatment: "Parent-training and family interventions and child psychological therapy; treat comorbid ADHD; multi-agency support." },
      { id: "psych_delirium", management: {"def": "A[\"Delirium\"]:::start --> B[\"Recognise: acute fluctuating confusion (4AT)\"]:::process\nB --> C[\"Identify and treat the cause (PINCH ME)\"]:::good\nC --> D[\"Non-drug: reorientate, sleep, hydration, mobilise\"]:::good\nD --> E{\"Severe distress or risk to self/others?\"}:::decision\nE -- \"yes, and non-drug failed\" --> F[\"Short-term low-dose haloperidol\"]:::warn\nE -- \"no\" --> G[\"Continue supportive care, review\"]:::good\nA --> H[\"Avoid antipsychotics in Parkinson/Lewy body\"]:::warn", "tips": {"A": "An acute, fluctuating disturbance of attention and cognition, often in older or hospitalised patients; hyperactive (agitated) or hypoactive (drowsy, withdrawn, easily missed).", "B": "Screen those at risk (e.g. the 4AT); it differs from dementia by its acute onset, fluctuating course and inattention.", "C": "The mainstay is finding and treating the cause - PINCH ME: Pain, Infection, Nutrition, Constipation, Hydration, Medication, Environment (plus urinary retention, hypoxia, metabolic).", "D": "Non-pharmacological measures first: reorientation, familiar faces, good lighting, sleep hygiene, hydration, early mobilisation, glasses and hearing aids, and avoiding unnecessary catheters or lines.", "E": "Reserve medication for when the patient is severely distressed or a risk to themselves or others and non-drug measures have failed.", "F": "Short-term, low-dose haloperidol (or an atypical antipsychotic) at the lowest effective dose for the shortest time; use lorazepam if antipsychotics are contraindicated.", "G": "Otherwise continue supportive care, review regularly and involve family; most delirium resolves once the cause is treated.", "H": "Avoid antipsychotics in Parkinson's disease and Lewy body dementia (severe sensitivity) - use a benzodiazepine cautiously instead."}}, cluster: "Organic disorders", name: "Delirium", keyFacts: "An acute, fluctuating disturbance of attention and cognition from an underlying physical cause; common and often missed.", epidemiology: "Very common in hospital, especially in the elderly and those with dementia.", aetiology: "Many precipitants (PINCH ME: pain, infection, nutrition, constipation, hydration, medication, environment); also urinary retention, hypoxia and drug or alcohol withdrawal.", pathophysiology: "An acute physiological insult disrupts cerebral neurotransmission (cholinergic deficit, relative dopamine excess), causing global cognitive dysfunction.", presentation: "Acute onset and fluctuating course with inattention and altered consciousness; hyperactive (agitated), hypoactive (drowsy, withdrawn) or mixed.", investigations: "4AT or CAM screen; find the cause with bloods, cultures, urinalysis, ECG and imaging; review medications.", treatment: "Treat the underlying cause; reorientation and a calm environment; rationalise medications; short-term antipsychotics only for severe distress or risk (avoid in Parkinson's and Lewy body dementia)." },
      { id: "psych_risk", cluster: "Risk & emergency", name: "Self-harm & suicide risk", fields: [ { label: "💡 Key facts", value: "Assessment of thoughts, plans and acts of self-harm; every act warrants a psychosocial assessment." }, { label: "📊 Scale & significance", value: "Self-harm is common, particularly in young people, and is the strongest predictor of later suicide." }, { label: "⚠️ Risk factors", value: "Mental illness, substance misuse, social adversity, hopelessness, impaired problem-solving and previous self-harm all raise the risk." }, { label: "🔍 Assessment", value: "Assess intent, means and protective factors; full risk assessment, collateral history and capacity assessment." }, { label: "🚑 Management", value: "Ensure safety, treat injuries, mental-health referral; a psychosocial assessment for every presentation." } ] },
    ],
  },
  {
    id: "rheumatology",
    name: "MSK & Rheumatology",
    icon: "🦴",
    conditions: [
      { id: "rheum_oa", management: {"def": "A[\"Osteoarthritis\"]:::start --> B[\"Core: education, exercise, weight loss\"]:::good\nB --> C[\"Topical NSAID (knee/hand)\"]:::good\nC -- \"inadequate\" --> D[\"Oral NSAID lowest dose + PPI (weigh risks)\"]:::good\nD --> E[\"Intra-articular steroid for flares\"]:::good\nE -- \"quality of life limited\" --> F[\"Refer for joint replacement\"]:::warn\nA --> G[\"Avoid routine paracetamol/opioids alone\"]:::process", "tips": {"A": "Degenerative joint disease with activity-related pain and stiffness; a clinical diagnosis over 45 with typical symptoms and no red flags.", "B": "The foundation for everyone: information, therapeutic exercise (strengthening and aerobic) and weight loss if overweight.", "C": "Offer a topical NSAID first for knee (and consider for hand) osteoarthritis.", "D": "If inadequate, add an oral NSAID at the lowest effective dose for the shortest time with gastroprotection (PPI); weigh cardiovascular, renal and GI risk.", "E": "Intra-articular corticosteroid injections give short-term relief of flares.", "F": "Refer for joint replacement when symptoms substantially affect quality of life and resist non-surgical care - do not wait for prolonged failure.", "G": "NICE (2022) advises against routinely offering paracetamol or weak opioids alone (limited benefit, opioid harms)."}}, cluster: "Degenerative joint disease", name: "Osteoarthritis", keyFacts: "Age-related degeneration of synovial joints; the commonest form of arthritis.", epidemiology: "Very common, increasing with age and obesity, especially in weight-bearing joints.", aetiology: "Age, obesity, prior joint injury, occupation and genetics.", pathophysiology: "Progressive loss of articular cartilage with subchondral bone change and osteophyte formation causes pain and stiffness.", presentation: "Activity-related joint pain, short morning stiffness, bony swelling, reduced range.", investigations: "Clinical; X-ray shows loss of joint space, osteophytes, sclerosis, cysts.", treatment: "Exercise, weight loss, topical/oral NSAIDs, paracetamol; joint replacement for severe disease." },
      { id: "rheum_ra", management: {"def": "A[\"Rheumatoid arthritis\"]:::start --> B[\"Refer urgently, start DMARD early\"]:::process\nB --> C[\"First-line: methotrexate\"]:::good\nC --> D[\"Short-term steroid to bridge\"]:::good\nC -- \"not at target\" --> E[\"Add a second conventional DMARD\"]:::good\nE -- \"still active despite 2 DMARDs\" --> F[\"Biologic or JAK inhibitor + methotrexate\"]:::warn\nA --> G[\"NSAID + PPI for symptoms; treat-to-target\"]:::good", "tips": {"A": "Symmetrical inflammatory polyarthritis of small joints with early-morning stiffness; anti-CCP/rheumatoid factor and raised inflammatory markers.", "B": "Refer urgently (do not wait for antibody results) and start a disease-modifying drug within 3 months of persistent symptoms to prevent joint damage.", "C": "First-line is conventional DMARD monotherapy - usually oral methotrexate with folic acid (alternatives leflunomide or sulfasalazine).", "D": "Use short-term bridging corticosteroids while the DMARD takes effect.", "E": "Treat-to-target: if not controlled, step up to a combination of conventional DMARDs.", "F": "For severe active RA (e.g. DAS28 above 5.1) inadequately controlled by two conventional DMARDs, add a biologic (anti-TNF etc.) or a JAK inhibitor, usually with methotrexate.", "G": "NSAIDs with a PPI for symptom relief; regular treat-to-target reviews using inflammatory markers and joint counts."}}, cluster: "Inflammatory arthritis", name: "Rheumatoid arthritis", keyFacts: "A chronic autoimmune symmetrical polyarthritis; early DMARD treatment limits joint damage.", epidemiology: "Affects around 1% of people, commoner in women and peaking in middle age.", aetiology: "Autoimmune, with genetic (HLA-DR4) and environmental (smoking) contributions; anti-CCP antibodies are specific.", pathophysiology: "Autoimmune synovial inflammation (pannus) erodes cartilage and bone, producing the deformities of established disease.", presentation: "Symmetrical small-joint pain and prolonged morning stiffness, swelling, fatigue.", investigations: "Rheumatoid factor, anti-CCP, ESR/CRP, X-rays, ultrasound.", treatment: "Early DMARD (methotrexate), steroid bridge, biologics; refer to rheumatology promptly." },
      { id: "rheum_psoriatic", cluster: "Inflammatory arthritis", name: "Psoriatic arthritis", keyFacts: "An inflammatory arthritis associated with psoriasis, with several patterns including spinal disease.", epidemiology: "Affects a notable minority of people with psoriasis.", aetiology: "Genetic predisposition; a seronegative spondyloarthropathy linked to psoriasis.", pathophysiology: "Immune-mediated joint and enthesis inflammation, related to the skin disease, causes dactylitis and erosive change.", presentation: "Joint pain with psoriasis, dactylitis, nail pitting; varied patterns including spinal.", investigations: "Clinical, X-rays (pencil-in-cup), inflammatory markers, skin assessment.", treatment: "NSAIDs, DMARDs, biologics; coordinate skin and joint care." },
      { id: "rheum_as", cluster: "Inflammatory arthritis", name: "Ankylosing spondylitis", keyFacts: "A chronic inflammatory spondyloarthropathy causing inflammatory back pain and reduced spinal mobility.", epidemiology: "Typically affects young men and is strongly linked to HLA-B27.", aetiology: "Genetic (HLA-B27) susceptibility driving a seronegative spondyloarthropathy.", pathophysiology: "Inflammation at the entheses and sacroiliac joints leads to new bone formation and progressive spinal fusion (bamboo spine).", presentation: "Inflammatory back pain in young adults, worse at night, improves with exercise, reduced spinal mobility.", investigations: "MRI sacroiliac joints, X-ray, HLA-B27, ESR/CRP.", treatment: "Physiotherapy and NSAIDs; anti-TNF/IL-17 biologics for active disease." },
      { id: "rheum_reactive", cluster: "Inflammatory arthritis", name: "Reactive arthritis", keyFacts: "A sterile inflammatory arthritis triggered by a distant infection; a seronegative spondyloarthropathy (can't see, can't pee, can't climb a tree).", epidemiology: "Typically young adults; associated with HLA-B27.", aetiology: "Follows gastrointestinal (Salmonella, Shigella, Campylobacter, Yersinia) or genitourinary (Chlamydia trachomatis) infection.", pathophysiology: "A post-infective immune-mediated synovitis; the joint itself is sterile.", presentation: "Asymmetrical lower-limb oligoarthritis 1-4 weeks after infection, with the triad of arthritis, urethritis and conjunctivitis; enthesitis, dactylitis, keratoderma blennorrhagica, circinate balanitis.", investigations: "ESR/CRP raised, HLA-B27, sterile joint aspirate, screen for the triggering infection (stool/STI screen), X-rays.", treatment: "NSAIDs and intra-articular steroids; treat persisting infection; sulfasalazine or methotrexate for chronic disease; usually self-limiting." },
      { id: "rheum_gout", management: {"def": "A[\"Acute gout flare\"]:::start --> B[\"Acute: NSAID / colchicine / steroid\"]:::good\nB --> C[\"Continue existing urate-lowering therapy\"]:::good\nA --> D{\"Recurrent, tophi or CKD/urate stones?\"}:::decision\nD -- \"yes\" --> E[\"Urate-lowering: allopurinol\"]:::good\nE --> F[\"Titrate to target urate\"]:::good\nF --> G[\"Cover with NSAID/colchicine while titrating\"]:::warn\nE -- \"not tolerated\" --> H[\"Febuxostat\"]:::good", "tips": {"A": "Acute monoarthritis (often first MTP joint) from monosodium urate crystals; aspirate if uncertain (negatively birefringent crystals).", "B": "Treat the flare early with a high-dose NSAID (plus a PPI), or colchicine (500 micrograms 2–3 times daily), or a short oral steroid if these are unsuitable.", "C": "Supportive care; do NOT stop established allopurinol during a flare.", "D": "Offer urate-lowering therapy after flares settle if there are recurrent attacks, tophi, joint damage, or renal disease/urate stones.", "E": "Allopurinol is first-line urate-lowering therapy.", "F": "Start 2–4 weeks after the flare settles; titrate to a serum urate below 360 micromol/L (below 300 if tophi or severe disease).", "G": "Co-prescribe an NSAID or colchicine for up to 6 months while titrating to avoid triggering flares.", "H": "Use febuxostat if allopurinol is not tolerated or is contraindicated."}}, cluster: "Crystal & infective arthritis", name: "Gout", keyFacts: "An acute crystal arthritis caused by hyperuricaemia, classically of the first big-toe joint.", epidemiology: "Common, especially in men, and rising with age and obesity.", aetiology: "Hyperuricaemia from reduced excretion or increased production; triggers include alcohol, purine-rich food and diuretics.", pathophysiology: "Monosodium urate crystals deposit in the joint and provoke an intense inflammatory response.", presentation: "Acute hot, red, exquisitely tender joint, often first MTP; tophi in chronic disease.", investigations: "Joint aspiration (negatively birefringent crystals), urate (after attack), renal function.", treatment: "NSAID, colchicine or steroid for attack; allopurinol urate-lowering after, with cover." },
      { id: "rheum_septic", management: {"def": "A[\"Septic arthritis\"]:::start --> B[\"Urgent joint aspiration BEFORE antibiotics\"]:::danger\nB --> C[\"Send fluid: Gram stain, culture, crystals, cell count\"]:::process\nC --> D[\"IV empirical antibiotics (e.g. flucloxacillin)\"]:::good\nD --> E[\"Joint washout or drainage\"]:::good\nE --> F[\"Continue antibiotics 4-6 weeks, physiotherapy\"]:::process", "tips": {"A": "Infection within a joint (commonly Staph aureus, or gonococcus in young adults): a hot, swollen, extremely painful joint the patient will not move, often with fever. A joint-destroying emergency.", "B": "Aspirate the joint urgently and send fluid BEFORE starting antibiotics (unless the patient is septic and unstable).", "C": "Send synovial fluid for urgent Gram stain, culture, polarised-light microscopy (to exclude crystals) and white cell count; also take blood cultures.", "D": "Start empirical IV antibiotics (e.g. flucloxacillin, or vancomycin if MRSA risk; add cover for gonococcus or Gram-negatives as indicated) per local policy.", "E": "Arrange joint drainage - arthroscopic or open washout, or repeated aspiration - to remove pus.", "F": "Continue antibiotics for around 4-6 weeks (IV then oral) with physiotherapy to preserve joint function."}}, cluster: "Crystal & infective arthritis", name: "Septic arthritis", keyFacts: "Infection within a joint; a rheumatological emergency that destroys cartilage rapidly.", epidemiology: "Uncommon but serious, with higher risk in prosthetic joints, diabetes and immunosuppression.", aetiology: "Usually Staphylococcus aureus, reaching the joint by haematogenous spread or direct inoculation.", pathophysiology: "Bacterial infection and the inflammatory response rapidly damage articular cartilage, hence the need for urgent washout.", presentation: "Acutely hot, swollen, painful joint with fever and inability to weight-bear.", investigations: "Urgent joint aspiration for microscopy and culture, blood cultures, inflammatory markers.", treatment: "Joint washout and prolonged IV antibiotics; orthopaedic emergency." },
      { id: "rheum_gono", cluster: "Crystal & infective arthritis", name: "Gonococcal arthritis", keyFacts: "The commonest cause of septic arthritis in young, sexually active adults; a form of disseminated gonococcal infection.", epidemiology: "Young, sexually active adults; commoner in women.", aetiology: "Disseminated infection with Neisseria gonorrhoeae.", pathophysiology: "Haematogenous spread of the gonococcus produces either a purulent monoarthritis or an arthritis-dermatitis syndrome.", presentation: "Either a hot, swollen single joint, or the triad of migratory polyarthralgia, tenosynovitis and pustular skin lesions; often with genitourinary symptoms.", investigations: "Joint aspiration (microscopy and culture), blood cultures, and NAAT or cultures from genital, rectal and pharyngeal sites.", treatment: "IV ceftriaxone and joint drainage; treat co-existing chlamydia; partner notification and full STI screen." },
      { id: "rheum_osteomyelitis", cluster: "Crystal & infective arthritis", name: "Osteomyelitis", keyFacts: "Infection of bone; may be acute or chronic and requires prolonged antibiotics.", epidemiology: "Children (haematogenous, long-bone metaphysis) and adults with diabetes, vascular disease or prostheses.", aetiology: "Usually Staphylococcus aureus; Salmonella in sickle cell disease; spread is haematogenous, contiguous or by direct inoculation.", pathophysiology: "Infection of bone causes inflammation, ischaemia and necrosis, forming a sequestrum (dead bone) and involucrum.", presentation: "Localised bone pain, fever, tenderness and reduced function; a non-healing ulcer or discharging sinus in chronic disease (diabetic foot).", investigations: "ESR/CRP, blood cultures, X-ray (changes are late), MRI (most sensitive), bone biopsy and culture.", treatment: "Prolonged targeted antibiotics (often weeks), surgical debridement of dead bone or abscess, and diabetic control." },
      { id: "rheum_sle", cluster: "Connective tissue disease & vasculitis", name: "Systemic lupus erythematosus", keyFacts: "A multisystem autoimmune disease with a relapsing-remitting course and varied presentations.", epidemiology: "Commoner in women of childbearing age and in people of African or Asian descent.", aetiology: "Autoimmune, with genetic, hormonal and environmental (ultraviolet light, drugs) triggers.", pathophysiology: "Loss of self-tolerance generates autoantibodies and immune complexes that deposit and cause multi-organ inflammation.", presentation: "Fatigue, arthralgia, malar rash, photosensitivity, multi-system involvement.", investigations: "ANA, anti-dsDNA, complement, urinalysis for nephritis, FBC.", treatment: "Hydroxychloroquine, steroids and immunosuppression for flares; sun protection; monitor organs." },
      { id: "rheum_sjogren", cluster: "Connective tissue disease & vasculitis", name: "Sjögren syndrome", keyFacts: "An autoimmune exocrinopathy causing dry eyes and dry mouth; primary or secondary to another connective tissue disease.", epidemiology: "Predominantly middle-aged women.", aetiology: "Autoimmune; primary, or secondary to rheumatoid arthritis, SLE or systemic sclerosis.", pathophysiology: "Lymphocytic infiltration and destruction of the lacrimal and salivary glands reduce secretions.", presentation: "Dry eyes (keratoconjunctivitis sicca) and dry mouth (xerostomia), parotid swelling, fatigue, arthralgia; increased risk of non-Hodgkin (MALT) lymphoma.", investigations: "Anti-Ro (SSA) and anti-La (SSB), ANA, rheumatoid factor; Schirmer's test; salivary gland biopsy.", treatment: "Artificial tears and saliva, pilocarpine; hydroxychloroquine for systemic features; monitor for lymphoma." },
      { id: "rheum_polymyositis", cluster: "Connective tissue disease & vasculitis", name: "Polymyositis", keyFacts: "An idiopathic inflammatory myopathy causing symmetrical proximal muscle weakness, without the rash of dermatomyositis.", epidemiology: "Adults, commoner in women.", aetiology: "Autoimmune; may be associated with malignancy and other connective tissue diseases.", pathophysiology: "T-cell-mediated inflammation of skeletal muscle fibres causes weakness.", presentation: "Progressive symmetrical proximal muscle weakness (difficulty rising from a chair or combing hair), muscle pain, dysphagia, and interstitial lung disease.", investigations: "Raised creatine kinase, EMG, muscle biopsy, autoantibodies (anti-Jo-1); screen for malignancy.", treatment: "High-dose corticosteroids with a steroid-sparing agent (azathioprine or methotrexate)." },
      { id: "rheum_dermatomyositis", cluster: "Connective tissue disease & vasculitis", name: "Dermatomyositis", keyFacts: "An inflammatory myopathy like polymyositis but with characteristic skin signs; a marker of underlying malignancy.", epidemiology: "Bimodal (children and adults); commoner in women.", aetiology: "Autoimmune; a recognised paraneoplastic association (lung, ovary, breast, GI), especially in older adults.", pathophysiology: "Humoral, complement-mediated microangiopathy of muscle and skin, distinct from the T-cell process of polymyositis.", presentation: "Proximal muscle weakness plus a heliotrope (lilac) periorbital rash, Gottron's papules over the knuckles, shawl sign and photosensitivity.", investigations: "Raised creatine kinase, EMG, muscle biopsy, autoantibodies (anti-Jo-1, anti-Mi-2); thorough malignancy screen.", treatment: "Corticosteroids and immunosuppression; treat any underlying malignancy; sun protection." },
      { id: "rheum_behcet", cluster: "Connective tissue disease & vasculitis", name: "Behçet syndrome", keyFacts: "A variable-vessel vasculitis defined by recurrent oral and genital ulceration.", epidemiology: "Commonest along the old Silk Road (Turkey, Middle East, East Asia); young adults; linked to HLA-B51.", aetiology: "Unknown; genetic susceptibility (HLA-B51) with environmental triggers.", pathophysiology: "Inflammation of vessels of all sizes (a variable-vessel vasculitis) causes mucocutaneous, ocular and systemic lesions.", presentation: "Recurrent painful oral and genital ulcers, uveitis, skin lesions (erythema nodosum, pathergy), arthritis, and venous or arterial thrombosis or neurological involvement.", investigations: "Clinical diagnosis (international criteria); pathergy test; inflammatory markers; exclude mimics.", treatment: "Topical and systemic steroids, colchicine for mucocutaneous disease; immunosuppression (azathioprine) and anti-TNF for major organ involvement." },
      { id: "neuro_gca", management: {"def": "A[\"Giant cell arteritis\"]:::start --> B[\"Start high-dose steroids IMMEDIATELY\"]:::danger\nB --> C{\"Visual symptoms?\"}:::decision\nC -- \"yes\" --> D[\"IV methylprednisolone\"]:::danger\nC -- \"no\" --> E[\"Oral prednisolone 40-60 mg\"]:::good\nD --> F[\"Temporal artery biopsy within 1-2 weeks\"]:::process\nE --> F\nF --> G[\"Slow steroid taper, add PPI and bone protection\"]:::good", "tips": {"A": "A large-vessel vasculitis in people over 50: new temporal headache, scalp tenderness, jaw claudication and raised ESR/CRP; the feared complication is irreversible sight loss (anterior ischaemic optic neuropathy).", "B": "Start high-dose corticosteroids immediately on clinical suspicion - do NOT wait for biopsy or specialist review, because sight loss can be sudden and permanent.", "C": "Visual involvement dictates the steroid route and urgency.", "D": "With visual symptoms or visual loss: IV methylprednisolone and same-day ophthalmology review.", "E": "Without visual symptoms: high-dose oral prednisolone (40-60 mg daily).", "F": "Confirm with temporal artery biopsy (may show skip lesions) within 1-2 weeks of starting steroids, and/or vascular ultrasound (halo sign) - do not delay treatment for it.", "G": "Taper steroids slowly over 12-24 months guided by symptoms and inflammatory markers; give a PPI, bone protection (bisphosphonate, calcium and vitamin D) and consider low-dose aspirin. Tocilizumab is steroid-sparing."}}, cluster: "Connective tissue disease & vasculitis", name: "Giant cell arteritis", keyFacts: "A large-vessel vasculitis of the over-50s that threatens sight; treat with steroids before the biopsy.", epidemiology: "Affects older adults, commoner in women, and associated with polymyalgia rheumatica.", aetiology: "An idiopathic granulomatous vasculitis of medium and large arteries.", pathophysiology: "Inflammation of the temporal and ophthalmic arteries narrows the lumen, risking ischaemic optic neuropathy and irreversible blindness.", presentation: "New temporal headache, jaw claudication, scalp tenderness, visual loss in over-50s.", investigations: "ESR/CRP raised, temporal artery biopsy/ultrasound.", treatment: "Immediate high-dose steroids before biopsy to protect sight; refer urgently." },
      { id: "rheum_pmr", cluster: "Connective tissue disease & vasculitis", name: "Polymyalgia rheumatica", keyFacts: "Bilateral shoulder and hip girdle pain and stiffness in the over-50s, with a dramatic steroid response.", epidemiology: "Common in older adults, commoner in women, and linked to giant cell arteritis.", aetiology: "An idiopathic inflammatory condition closely associated with giant cell arteritis.", pathophysiology: "Inflammation of the proximal joints and bursae causes the girdle pain and marked morning stiffness.", presentation: "Bilateral shoulder and hip girdle pain and stiffness in over-50s, marked morning stiffness.", investigations: "ESR/CRP raised, exclude mimics; consider coexisting giant cell arteritis.", treatment: "Low-dose prednisolone with rapid response; slow taper; bone protection." },
      { id: "rheum_osteoporosis", management: {"def": "A[\"Fragility fracture or osteoporosis risk\"]:::start --> B[\"Assess 10-year risk: FRAX / QFracture\"]:::process\nB --> C{\"Above intervention threshold?\"}:::decision\nC -- \"yes\" --> D[\"DEXA scan\"]:::good\nD --> E[\"Oral bisphosphonate + calcium/vitamin D\"]:::good\nE --> F{\"Intolerant or unsuitable?\"}:::decision\nF -- \"yes\" --> G[\"IV zoledronate / denosumab / teriparatide\"]:::good\nE --> H[\"Exercise, stop smoking, limit alcohol\"]:::process", "tips": {"A": "Reduced bone mass with microarchitectural deterioration causing fragility fractures (fall from standing height). Assess after such a fracture or with risk factors.", "B": "Estimate 10-year fracture risk with FRAX or QFracture (age, prior fracture, steroids, smoking, alcohol, etc.).", "C": "Compare risk to the intervention threshold (NOGG guidance).", "D": "Measure bone mineral density by DEXA (T-score of −2.5 or lower defines osteoporosis).", "E": "First-line: an oral bisphosphonate (alendronate/risedronate) with calcium and vitamin D if needed. Take on an empty stomach, sitting upright, to avoid oesophagitis.", "F": "Reassess if not tolerated or contraindicated (e.g. oesophageal disease, poor adherence, low eGFR).", "G": "Alternatives: IV zoledronate, subcutaneous denosumab, or teriparatide (severe/specialist).", "H": "Non-drug: weight-bearing and muscle-strengthening exercise, smoking cessation, reduced alcohol, and falls prevention."}}, cluster: "Metabolic bone, tumours & fractures", name: "Osteoporosis", keyFacts: "Reduced bone density and quality predisposing to fragility fractures; usually silent until a fracture.", epidemiology: "Very common, particularly in postmenopausal women and the elderly.", aetiology: "Oestrogen loss, age, corticosteroids, smoking, alcohol and endocrine disease.", pathophysiology: "An imbalance favouring bone resorption over formation reduces bone mass and microarchitecture, weakening the skeleton.", presentation: "Asymptomatic until fragility fracture (wrist, hip, vertebra).", investigations: "FRAX, DEXA scan, calcium, vitamin D, exclude secondary causes.", treatment: "Calcium and vitamin D, bisphosphonates; lifestyle and falls prevention." },
      { id: "rheum_bone_tumours", cluster: "Metabolic bone, tumours & fractures", name: "Bone tumours (benign & malignant)", keyFacts: "Primary bone tumours range from benign to aggressive malignant; bone is also a common site for metastases. Persistent or night-time bone pain or a mass needs imaging.", epidemiology: "Primary bone cancers are rare and often affect children and young adults (osteosarcoma, Ewing's); metastases and myeloma are far commoner in older adults.", aetiology: "Benign: osteochondroma, osteoid osteoma, enchondroma, giant cell tumour. Malignant: osteosarcoma, Ewing sarcoma, chondrosarcoma; secondary deposits (breast, prostate, lung, kidney, thyroid) and myeloma.", pathophysiology: "Neoplastic proliferation of bone, cartilage or marrow elements; malignant tumours destroy bone and may metastasise (osteosarcoma to lung).", presentation: "Persistent or night-time bone pain, swelling or mass, or a pathological fracture; osteosarcoma around the knee in adolescents; Ewing's with systemic features.", investigations: "X-ray (sunburst and Codman's triangle in osteosarcoma, onion-skin in Ewing's), MRI, bone biopsy, staging CT; myeloma screen.", treatment: "Refer to a specialist sarcoma centre; surgery with neoadjuvant and adjuvant chemotherapy or radiotherapy; treat metastatic disease and myeloma by cause." },
      { id: "rheum_hip_fracture", cluster: "Metabolic bone, tumours & fractures", name: "Hip fracture", keyFacts: "A fragility fracture of the proximal femur in older people; a major cause of morbidity and mortality needing prompt surgery.", epidemiology: "Mainly elderly women with osteoporosis; very common and costly.", aetiology: "Low-energy fall on a background of osteoporosis; high-energy trauma in the young.", pathophysiology: "Intracapsular (femoral neck) fractures risk avascular necrosis of the head; extracapsular (intertrochanteric) fractures spare the blood supply.", presentation: "After a fall: pain, inability to weight-bear, and a shortened, externally rotated leg.", investigations: "X-ray (AP pelvis and lateral); MRI if occult; bloods, ECG and group-and-save for surgery.", treatment: "Analgesia and prompt surgery within 36 hours: displaced intracapsular - hemiarthroplasty or total hip replacement; undisplaced or extracapsular - internal fixation (dynamic hip screw); orthogeriatric care and bone protection." },
      { id: "rheum_spinal_fracture", cluster: "Metabolic bone, tumours & fractures", name: "Spinal fractures", keyFacts: "Vertebral fractures range from osteoporotic wedge collapse to unstable traumatic fractures; always assess for cord compression.", epidemiology: "Osteoporotic vertebral fractures are common in the elderly; traumatic fractures follow high-energy injury.", aetiology: "Osteoporosis (often minimal trauma), high-energy trauma, or pathological (metastasis, myeloma).", pathophysiology: "Compression of the vertebral body (wedge or crush) or burst and unstable fractures that may compromise the spinal canal and cord.", presentation: "Acute back pain, loss of height and kyphosis (osteoporotic); red flags of cord or cauda equina compression (weakness, sensory level, bladder or bowel dysfunction) in unstable fractures.", investigations: "X-ray; CT for bony detail; MRI if neurological signs or a suspected pathological fracture; bone profile and myeloma screen.", treatment: "Analgesia, mobilisation and bone protection for stable osteoporotic fractures; immobilise and refer urgently for unstable or neurological cases; vertebroplasty in selected patients." },
      { id: "rheum_back_pain", cluster: "Spine & back", name: "Mechanical low back pain", keyFacts: "Activity-related back pain without red flags; usually self-limiting and best managed by staying active.", epidemiology: "Extremely common, and a leading cause of disability and time off work.", aetiology: "Mechanical strain of muscles, ligaments and discs; psychosocial 'yellow flags' predict chronicity.", pathophysiology: "Strain or degenerative change in spinal structures produces nociceptive pain, often amplified by psychosocial factors.", presentation: "Activity-related back pain without red flags; usually self-limiting.", investigations: "Clinical; assess red and yellow flags; imaging only if indicated.", treatment: "Keep active, analgesia, physiotherapy; address psychosocial factors; safety-net for red flags." },
      { id: "rheum_disc_prolapse", cluster: "Spine & back", name: "Disc prolapse", keyFacts: "Herniation of an intervertebral disc compressing a nerve root, causing radicular pain (sciatica); usually settles without surgery.", epidemiology: "Common, typically aged 30-50; lumbar (L4/5, L5/S1) most often.", aetiology: "Degeneration of the annulus fibrosus with herniation of the nucleus pulposus; heavy lifting and bending.", pathophysiology: "Displaced disc material compresses and inflames a nerve root, producing dermatomal pain and neurological signs.", presentation: "Radicular leg pain in a dermatomal distribution, worse on coughing or straining, with a positive straight-leg raise and sensory, motor or reflex change; watch for cauda equina (bilateral pain, saddle anaesthesia, urinary retention).", investigations: "Clinical; MRI if severe, persistent or red flags; urgent MRI for suspected cauda equina syndrome.", treatment: "Analgesia, stay active, physiotherapy; most settle in 6-12 weeks; epidural steroids or discectomy for persistent or severe deficits; cauda equina is a surgical emergency." },
      { id: "rheum_bursitis", cluster: "Soft-tissue & tendinopathy", name: "Bursitis", keyFacts: "Inflammation of a bursa causing localised pain and swelling; common at the elbow, knee, hip and shoulder.", epidemiology: "Common; related to repetitive pressure, kneeling or leaning.", aetiology: "Repetitive trauma or pressure, inflammatory arthritis, gout, or infection (septic bursitis).", pathophysiology: "Inflammation and excess fluid within the bursa, the sac that cushions tendons and bones.", presentation: "Localised swelling, tenderness and pain over a bursa: olecranon (elbow), prepatellar (housemaid's knee), trochanteric (hip) or subacromial (shoulder).", investigations: "Clinical; aspirate if infection is suspected (microscopy, culture, crystals); inflammatory markers.", treatment: "Rest, ice, NSAIDs and avoiding the trigger; aspiration and steroid injection if persistent; antibiotics and drainage for septic bursitis." },
      { id: "rheum_dequervain", cluster: "Soft-tissue & tendinopathy", name: "De Quervain tenosynovitis", keyFacts: "Inflammation of the thumb tendon sheath at the radial wrist; pain on gripping and lifting.", epidemiology: "Commoner in women, especially new mothers (lifting infants), and after repetitive thumb use.", aetiology: "Repetitive thumb and wrist movements; pregnancy and the postpartum period.", pathophysiology: "Thickening and inflammation of the sheath of abductor pollicis longus and extensor pollicis brevis in the first dorsal compartment.", presentation: "Pain and swelling over the radial styloid, worse on thumb movement; positive Finkelstein's test.", investigations: "Clinical (Finkelstein's test); imaging rarely needed.", treatment: "Thumb spica splint, NSAIDs and activity modification; corticosteroid injection; surgical decompression if refractory." },
      { id: "rheum_lateral_epicondylitis", cluster: "Soft-tissue & tendinopathy", name: "Lateral epicondylitis", keyFacts: "Tennis elbow: an overuse tendinopathy of the common extensor origin at the lateral epicondyle.", epidemiology: "Common in middle age; from repetitive gripping or wrist extension.", aetiology: "Repetitive wrist extension and gripping (manual work, racquet sports).", pathophysiology: "Degenerative microtears (tendinosis) of the extensor carpi radialis brevis origin rather than true inflammation.", presentation: "Lateral elbow pain and tenderness over the epicondyle, worse on resisted wrist extension and gripping (the medial equivalent is golfer's elbow).", investigations: "Clinical; imaging only if the diagnosis is uncertain.", treatment: "Activity modification, NSAIDs, physiotherapy (eccentric exercises) and a counterforce brace; steroid injection for short-term relief; usually self-limiting." },
      { id: "rheum_fibromyalgia", cluster: "Pain & muscle disorders", name: "Fibromyalgia", keyFacts: "Chronic widespread pain with fatigue and unrefreshing sleep, and normal investigations.", epidemiology: "Common, predominantly in women.", aetiology: "Multifactorial, with stress, mood disorder and poor sleep as contributors.", pathophysiology: "Central sensitisation amplifies pain processing in the absence of tissue inflammation or damage.", presentation: "Chronic widespread pain, fatigue, unrefreshing sleep, cognitive fog with normal investigations.", investigations: "Clinical; minimal bloods to exclude alternatives.", treatment: "Education, graded exercise, CBT; amitriptyline or duloxetine; avoid opioids." },
      { id: "rheum_crps", cluster: "Pain & muscle disorders", name: "Complex regional pain syndrome", keyFacts: "Disabling regional pain out of proportion to the initial injury, with autonomic and trophic changes; usually affects a limb.", epidemiology: "Often follows a fracture, surgery or minor trauma; commoner in women.", aetiology: "Triggered by trauma or surgery (sometimes none); type 1 without nerve injury, type 2 with a defined nerve injury.", pathophysiology: "Maladaptive peripheral and central sensitisation with autonomic dysregulation and neurogenic inflammation.", presentation: "Severe burning pain and allodynia, with swelling and changes in skin colour, temperature, sweating, hair and nails; later stiffness and contractures.", investigations: "Clinical diagnosis (Budapest criteria); X-ray may show patchy osteopenia; exclude other causes.", treatment: "Early mobilisation and physiotherapy, neuropathic analgesia (amitriptyline, gabapentin) and pain-team referral; bisphosphonates in selected cases." },
      { id: "rheum_rhabdo", cluster: "Pain & muscle disorders", name: "Rhabdomyolysis", keyFacts: "Breakdown of skeletal muscle releasing myoglobin, potassium and creatine kinase, risking acute kidney injury and hyperkalaemia.", epidemiology: "Seen after trauma or crush, prolonged immobility (a long lie), seizures, extreme exertion, and with statins or other drugs.", aetiology: "Crush injury, prolonged immobilisation, seizures, exertion, ischaemia, drugs and toxins (statins, alcohol), and inherited myopathies.", pathophysiology: "Damaged myocytes release intracellular contents; myoglobin is nephrotoxic and obstructs tubules (acute kidney injury), and potassium release causes hyperkalaemia.", presentation: "Muscle pain, weakness and swelling with dark (tea-coloured) urine; may be complicated by arrhythmia or acute kidney injury.", investigations: "Markedly raised creatine kinase, myoglobinuria (dipstick positive for blood with no red cells), U&E (high potassium, AKI), ECG.", treatment: "Aggressive IV fluids to maintain urine output, treat hyperkalaemia, monitor renal function and treat the cause; dialysis if severe acute kidney injury." },
    ],
  },
  {
    id: "dermatology",
    name: "Dermatology",
    icon: "🧴",
    conditions: [
      { id: "derm_eczema", management: {"def": "A[\"Atopic eczema\"]:::start --> B[\"Liberal emollients (all severities)\"]:::good\nB --> C{\"Severity\"}:::decision\nC -- \"mild\" --> D[\"Mild topical steroid (hydrocortisone)\"]:::good\nC -- \"moderate\" --> E[\"Moderate steroid (clobetasone)\"]:::good\nC -- \"severe\" --> F[\"Potent steroid, consider calcineurin inhibitor\"]:::good\nF -- \"uncontrolled / recurrent\" --> G[\"Referral: phototherapy or systemic therapy\"]:::warn\nA -- \"weeping, unwell\" --> H[\"Treat infection (flucloxacillin or aciclovir)\"]:::danger", "tips": {"A": "Chronic, itchy, relapsing inflammation with a flexural distribution; use a stepped approach matched to severity.", "B": "Emollients are the mainstay at every step - apply generously and frequently, and use as soap substitutes.", "C": "Step topical corticosteroid potency up and down with severity.", "D": "Mild eczema: a mild topical steroid such as hydrocortisone 1%.", "E": "Moderate eczema: a moderate-potency steroid (clobetasone butyrate) in short bursts to flares.", "F": "Severe eczema: a potent steroid; topical calcineurin inhibitors (tacrolimus/pimecrolimus) for the face and flexures or to spare steroids.", "G": "Refer for phototherapy or systemic treatment (ciclosporin, methotrexate, dupilumab) if severe and uncontrolled.", "H": "Infected eczema: oral flucloxacillin for bacterial infection; eczema herpeticum (painful monomorphic punched-out erosions, unwell) needs urgent aciclovir and same-day review."}}, cluster: "Eczema & papulosquamous", name: "Atopic eczema", keyFacts: "A chronic, itchy, relapsing inflammatory skin condition, typically in the flexures and part of atopy.", epidemiology: "Very common in children, often improving with age.", aetiology: "Genetic skin-barrier dysfunction (filaggrin) with atopy and triggers such as irritants, allergens and heat.", pathophysiology: "An impaired skin barrier and a type 2 immune response cause dry, inflamed, itchy skin that is prone to infection.", presentation: "Itchy, dry, erythematous flexural rash; relapsing; often atopic history.", investigations: "Clinical; swab if infected.", treatment: "Emollients liberally, topical steroids by potency, treat infection, avoid triggers." },
      { id: "derm_psoriasis", management: {"def": "A[\"Chronic plaque psoriasis\"]:::start --> B[\"Potent steroid + vitamin D analogue\"]:::good\nB -- \"inadequate after 8 weeks\" --> C[\"Vitamin D analogue, then other topicals\"]:::good\nC -- \"extensive / uncontrolled\" --> D[\"Phototherapy (narrowband UVB)\"]:::good\nD -- \"inadequate\" --> E[\"Systemic: methotrexate or ciclosporin\"]:::good\nE -- \"inadequate / severe\" --> F[\"Biologic (anti-TNF, anti-IL17/23)\"]:::warn\nA --> G[\"Emollients; screen for psoriatic arthritis\"]:::process", "tips": {"A": "Well-demarcated scaly plaques on extensor surfaces and scalp; treat topically first, stepping up by response and severity.", "B": "First-line: a potent corticosteroid plus a vitamin D analogue (calcipotriol) once daily, applied separately (e.g. steroid morning, vitamin D evening), for up to 8 weeks.", "C": "If inadequate, try a vitamin D analogue alone, then a different topical regimen; give steroid breaks to limit atrophy and tachyphylaxis.", "D": "For extensive or resistant disease, refer for phototherapy with narrowband UVB.", "E": "Systemic therapy (specialist): methotrexate first-line, or ciclosporin for rapid control; acitretin in some.", "F": "Biologics (anti-TNF, anti-IL-17 or anti-IL-23) for severe psoriasis that fails standard systemic therapy.", "G": "Use emollients generally, and screen for psoriatic arthritis and cardiovascular risk factors."}}, cluster: "Eczema & papulosquamous", name: "Psoriasis", keyFacts: "A chronic immune-mediated disease of well-demarcated scaly plaques on extensor surfaces.", epidemiology: "Common, affecting around 2% of people, with peaks in early and later adulthood.", aetiology: "Genetic predisposition with triggers including infection, stress, skin trauma (Koebner), alcohol and certain drugs.", pathophysiology: "Immune-driven keratinocyte hyperproliferation produces thickened plaques with silvery scale, and an associated arthritis can occur.", presentation: "Well-demarcated scaly erythematous plaques on extensor surfaces and scalp; nail changes.", investigations: "Clinical; assess severity and joint involvement.", treatment: "Emollients, topical steroid plus vitamin D analogue; phototherapy; systemic/biologic for severe disease." },
      { id: "derm_lichen_planus", cluster: "Eczema & papulosquamous", name: "Lichen planus", keyFacts: "An itchy inflammatory dermatosis remembered by the 6 Ps: purple, pruritic, polygonal, planar (flat-topped) papules.", epidemiology: "Adults, commoner in middle age.", aetiology: "Idiopathic and T-cell-mediated; associated with hepatitis C and with lichenoid drug eruptions.", pathophysiology: "A T-lymphocyte-mediated attack on basal keratinocytes produces the papules and Wickham's striae.", presentation: "Itchy violaceous flat-topped papules on the flexor wrists and ankles with lacy white Wickham's striae; oral white lacy patches; nail and scalp (scarring) involvement.", investigations: "Clinical; biopsy if uncertain; consider hepatitis C testing.", treatment: "Potent topical steroids; usually self-limiting over months; oral steroids or phototherapy for severe disease." },
      { id: "derm_lichen_simplex", cluster: "Eczema & papulosquamous", name: "Lichen simplex", keyFacts: "Localised skin thickening (lichenification) driven by a chronic itch-scratch cycle.", epidemiology: "Adults; linked to stress and atopy.", aetiology: "Repeated rubbing and scratching, often triggered by an underlying itch (atopy, stress).", pathophysiology: "Chronic scratching thickens the epidermis and perpetuates the itch-scratch cycle.", presentation: "Well-defined thickened, leathery, hyperpigmented plaques with accentuated skin markings at accessible sites (nape, shins, genitals).", investigations: "Clinical.", treatment: "Break the itch-scratch cycle: potent topical steroids, emollients, habit reversal; treat the underlying itch and stress." },
      { id: "derm_pityriasis_rosea", cluster: "Eczema & papulosquamous", name: "Pityriasis rosea", keyFacts: "A self-limiting rash starting with a herald patch, then a Christmas-tree truncal eruption.", epidemiology: "Children and young adults.", aetiology: "Probably viral (human herpesvirus 6 and 7 implicated).", pathophysiology: "A presumed viral trigger produces a self-limiting inflammatory eruption.", presentation: "A single larger herald patch, then crops of smaller oval scaly pink macules along skin lines on the trunk (Christmas-tree pattern).", investigations: "Clinical; consider syphilis serology if atypical.", treatment: "Reassurance; emollients and antihistamines for itch; resolves spontaneously over 6-12 weeks." },
      { id: "derm_acne", management: {"def": "A[\"Acne vulgaris\"]:::start --> B{\"Severity\"}:::decision\nB -- \"mild-moderate\" --> C[\"Topical combination (12 weeks)\"]:::good\nB -- \"moderate-severe\" --> D[\"Add oral antibiotic (up to 6 months)\"]:::good\nC --> E{\"Adequate response?\"}:::decision\nD --> E\nE -- \"no\" --> F[\"Change regimen; COCP in women\"]:::good\nF --> G[\"Refer for oral isotretinoin\"]:::danger", "tips": {"A": "Comedones, papules, pustules and nodules from follicular hyperkeratinisation, Cutibacterium acnes and sebum; grade severity and scarring (NICE NG198).", "B": "Choose the first regimen by severity and scarring risk.", "C": "Mild–moderate: a 12-week fixed topical combination — benzoyl peroxide with a topical retinoid (adapalene), or with a topical antibiotic, or azelaic acid. Avoid topical antibiotic alone.", "D": "Moderate–severe: add an oral antibiotic (lymecycline or doxycycline) to a topical retinoid/benzoyl peroxide for up to 6 months; never as monotherapy (resistance).", "E": "Review at 12 weeks.", "F": "If inadequate, change the combination; in women a combined oral contraceptive (or co-cyprindiol) is an option alongside topical therapy.", "G": "Refer for oral isotretinoin (specialist only) in severe/nodulocystic acne, scarring or treatment failure; it is teratogenic and needs pregnancy prevention."}}, cluster: "Acne & rosacea", name: "Acne vulgaris", keyFacts: "A common disorder of the pilosebaceous unit with comedones, papules, pustules and scarring.", epidemiology: "Very common in adolescents, often persisting into adulthood.", aetiology: "Androgen-driven sebum, follicular hyperkeratinisation, Cutibacterium acnes and inflammation.", pathophysiology: "Sebum and keratin plug the follicle and bacterial colonisation drives inflammation, producing the range of lesions.", presentation: "Comedones, papules, pustules and nodules on face, chest and back; scarring.", investigations: "Clinical; consider hormonal assessment if features.", treatment: "Topical retinoid plus benzoyl peroxide/antibiotic; oral antibiotics or COCP; isotretinoin for severe disease." },
      { id: "derm_rosacea", cluster: "Acne & rosacea", name: "Rosacea", keyFacts: "A chronic facial dermatosis of central flushing, erythema, papules and pustules, without comedones.", epidemiology: "Adults, especially fair-skinned, peaking in middle age.", aetiology: "Multifactorial; triggers include sun, heat, alcohol, spicy food and the Demodex mite.", pathophysiology: "Vascular dysregulation and inflammation of the central face cause flushing, persistent erythema and inflammatory lesions.", presentation: "Central facial flushing and erythema with telangiectasia, papules and pustules; no comedones; ocular involvement and rhinophyma in some.", investigations: "Clinical.", treatment: "Trigger avoidance and sun protection; topical metronidazole, ivermectin or azelaic acid; oral doxycycline; laser for telangiectasia." },
      { id: "derm_urticaria", management: {"def": "A[\"Urticaria (hives)\"]:::start --> B[\"Identify and avoid triggers\"]:::process\nB --> C[\"Non-sedating antihistamine (e.g. cetirizine)\"]:::good\nC -- \"inadequate at 2-4 weeks\" --> D[\"Up-titrate antihistamine (up to 4x)\"]:::good\nD -- \"still uncontrolled\" --> E[\"Short oral steroid for severe flares\"]:::warn\nE -- \"chronic, refractory\" --> F[\"Refer: omalizumab or ciclosporin\"]:::good\nA -- \"airway angioedema / anaphylaxis\" --> G[\"Emergency: IM adrenaline\"]:::danger", "tips": {"A": "Itchy transient wheals from mast-cell histamine release; acute (under 6 weeks, often infection or allergy) or chronic. Most is managed in primary care.", "B": "Identify and avoid triggers (drugs such as NSAIDs/opiates, infections, foods, physical stimuli).", "C": "First-line is a regular non-sedating (second-generation) oral antihistamine such as cetirizine or loratadine.", "D": "If not controlled after 2-4 weeks, increase the antihistamine dose (up to four times the standard dose, off-label).", "E": "A short course of oral corticosteroid can settle a severe acute flare (not for long-term use).", "F": "Refer chronic refractory urticaria to dermatology/immunology for options such as omalizumab or ciclosporin.", "G": "If there is airway angioedema or anaphylaxis (breathing or circulation compromise), treat as an emergency with IM adrenaline."}}, cluster: "Urticaria & reactive erythema", name: "Urticaria", keyFacts: "Transient itchy wheals from mast-cell histamine release, which may accompany angioedema.", epidemiology: "Common, and most acute cases are self-limiting.", aetiology: "Allergic, infective, drug-induced or idiopathic; chronic forms may be autoimmune.", pathophysiology: "Mast-cell degranulation releases histamine, causing dermal oedema (wheals) and itch.", presentation: "Transient itchy wheals; angioedema may accompany; often allergic or idiopathic.", investigations: "Clinical; identify triggers; investigate if chronic.", treatment: "Non-sedating antihistamines; avoid triggers; adrenaline for anaphylaxis." },
      { id: "derm_erythema_nodosum", cluster: "Urticaria & reactive erythema", name: "Erythema nodosum", keyFacts: "Tender red nodules on the shins from a panniculitis; a reactive sign of an underlying trigger.", epidemiology: "Commoner in young women.", aetiology: "Reactive to infection (streptococcus, TB), sarcoidosis, inflammatory bowel disease, drugs (sulfonamides, COCP) and pregnancy; often idiopathic.", pathophysiology: "A delayed hypersensitivity panniculitis (inflammation of subcutaneous fat) causes the tender nodules.", presentation: "Crops of tender, red, raised nodules on the shins that fade like bruises without ulcerating or scarring.", investigations: "Seek the cause: ESR/CRP, ASO titre, chest X-ray (sarcoid, TB), inflammatory bowel screen.", treatment: "Treat the underlying cause; rest, NSAIDs and leg elevation; usually self-limiting." },
      { id: "derm_erythroderma", cluster: "Dermatological emergencies", name: "Erythroderma", keyFacts: "Generalised erythema affecting over 90% of the skin; a dermatological emergency with fluid, heat and protein loss and infection risk.", epidemiology: "Uncommon; more often in older adults.", aetiology: "Pre-existing dermatoses (psoriasis, eczema), drug reactions, cutaneous lymphoma (Sezary syndrome), and idiopathic.", pathophysiology: "Widespread skin inflammation impairs the barrier, thermoregulation and fluid balance, and can cause high-output cardiac failure.", presentation: "Widespread erythema and scaling over most of the body with itch, shivering, lymphadenopathy and systemic upset.", investigations: "Identify the cause (skin biopsy, drug history, bloods); monitor temperature, fluids and electrolytes.", treatment: "Admit; warm environment, fluid and electrolyte support, emollients; treat the cause and stop any culprit drug." },
      { id: "derm_sjs_ten", management: {"source": "Dermatology emergency", "def": "A[\"SJS / TEN\"]:::start --> B[\"STOP the causative drug immediately\"]:::danger\nB --> C[\"Assess extent (SCORTEN), admit to burns/ICU\"]:::warn\nC --> D[\"Supportive: fluids, nutrition, wound care, analgesia\"]:::good\nD --> E[\"Ophthalmology and specialist review\"]:::good\nE --> F[\"Consider immunomodulation (steroids, IVIG, ciclosporin)\"]:::good", "tips": {"A": "Severe mucocutaneous drug reactions (SJS under 10% body surface, TEN over 30%, overlap between) with widespread epidermal detachment, usually from allopurinol, anticonvulsants, sulfonamides or NSAIDs. A dermatological emergency.", "B": "The single most important step is to identify and stop the causative drug at once.", "C": "Assess severity and prognosis with SCORTEN, and admit to a burns unit or intensive care.", "D": "Supportive care is the mainstay: fluid and electrolyte replacement, temperature control, nutrition, meticulous wound care and strong analgesia (managed like a major burn).", "E": "Involve ophthalmology early (to prevent scarring and sight loss) and other specialties for mucosal involvement.", "F": "Immunomodulatory treatment (systemic corticosteroids, IVIG or ciclosporin) is used under specialist guidance, though evidence is limited."}}, cluster: "Dermatological emergencies", name: "SJS & TEN", keyFacts: "A spectrum of severe drug-induced mucocutaneous reactions with skin detachment: Stevens-Johnson syndrome below 10% body surface, toxic epidermal necrolysis above 30%.", epidemiology: "Rare; higher risk with certain drugs and in HIV.", aetiology: "Usually drugs: anticonvulsants (lamotrigine, carbamazepine, phenytoin), allopurinol, sulfonamides, NSAIDs; occasionally infection.", pathophysiology: "A severe T-cell-mediated reaction causes widespread keratinocyte apoptosis and full-thickness epidermal detachment.", presentation: "Prodrome then painful erythema, blistering and sheet-like skin loss with a positive Nikolsky sign, plus erosions of two or more mucosal surfaces (eyes, mouth, genitals).", investigations: "Clinical; assess body-surface area detached and the SCORTEN severity score; skin biopsy.", treatment: "Stop the culprit drug; supportive care in a burns or intensive-care unit (fluids, skin and eye care, analgesia); specialist immunomodulation." },
      { id: "derm_bullous_pemphigoid", cluster: "Autoimmune blistering", name: "Bullous pemphigoid", keyFacts: "A subepidermal autoimmune blistering disease of the elderly with tense bullae; the mouth is usually spared.", epidemiology: "Mainly the elderly.", aetiology: "Autoantibodies to hemidesmosomal proteins (BP180 and BP230) at the dermo-epidermal junction.", pathophysiology: "Antibodies against the basement membrane split the skin below the epidermis, producing tense, fluid-filled blisters.", presentation: "Tense, intact bullae on an erythematous base on the flexures and limbs, with itch; mouth usually spared; Nikolsky sign negative.", investigations: "Skin biopsy with direct immunofluorescence (linear IgG and C3 along the basement membrane); BP180/BP230 serology.", treatment: "Potent topical or oral corticosteroids and steroid-sparing immunosuppression; better prognosis than pemphigus." },
      { id: "derm_pemphigus_vulgaris", cluster: "Autoimmune blistering", name: "Pemphigus vulgaris", keyFacts: "An intraepidermal autoimmune blistering disease with flaccid blisters and painful mucosal erosions; potentially fatal.", epidemiology: "Middle-aged adults; commoner in Ashkenazi Jewish and Mediterranean people.", aetiology: "Autoantibodies to desmoglein 1 and 3 (desmosomal proteins).", pathophysiology: "Loss of keratinocyte adhesion (acantholysis) within the epidermis produces flaccid, easily-ruptured blisters.", presentation: "Flaccid blisters and painful erosions, often starting in the mouth; superficial and easily denuded; Nikolsky sign positive.", investigations: "Skin biopsy with direct immunofluorescence (intercellular IgG, chicken-wire pattern); anti-desmoglein antibodies.", treatment: "Systemic corticosteroids and immunosuppression (e.g. rituximab); supportive skin and oral care; can be life-threatening." },
      { id: "derm_dermatitis_herpetiformis", cluster: "Autoimmune blistering", name: "Dermatitis herpetiformis", keyFacts: "An intensely itchy blistering rash on extensor surfaces; the skin manifestation of coeliac disease.", epidemiology: "Young and middle-aged adults; associated with coeliac disease.", aetiology: "Gluten sensitivity with IgA antibodies (against tissue and epidermal transglutaminase).", pathophysiology: "IgA deposition in the dermal papillae triggers a neutrophilic response and subepidermal blistering.", presentation: "Symmetrical, intensely itchy grouped vesicles and papules on the extensor surfaces (elbows, knees, buttocks, scalp).", investigations: "Skin biopsy with direct immunofluorescence (granular IgA in dermal papillae); coeliac serology and duodenal biopsy.", treatment: "Gluten-free diet (the mainstay); dapsone for rapid symptom control." },
      { id: "derm_cellulitis", management: {"def": "A[\"Cellulitis\"]:::start --> B[\"Mark the area, check for source\"]:::process\nB --> C{\"Eron class / severity\"}:::decision\nC -- \"class I (no systemic illness)\" --> D[\"Oral flucloxacillin (clarithromycin if allergic)\"]:::good\nC -- \"class III-IV (systemic, unstable)\" --> E[\"Admit for IV antibiotics\"]:::danger\nD --> F[\"Review, elevate limb, treat entry point\"]:::process\nA -- \"rapidly spreading, severe pain, crepitus\" --> G[\"Exclude necrotising fasciitis (surgical emergency)\"]:::danger", "tips": {"A": "An acute bacterial infection of the dermis and subcutaneous tissue (usually Streptococcus or Staph aureus): a hot, red, swollen, tender area with poorly demarcated edges, often on the lower leg.", "B": "Mark the extent of erythema to track progress, look for a portal of entry (tinea, ulcer, bite) and assess for systemic illness or sepsis.", "C": "Grade severity with the Eron classification to decide oral versus IV and whether to admit.", "D": "Class I (no systemic illness or uncontrolled comorbidity): oral flucloxacillin first-line (clarithromycin or doxycycline if penicillin-allergic).", "E": "Class III-IV (systemically unwell, unstable comorbidity or limb-threatening): admit for IV antibiotics; class II may need short-term IV or OPAT.", "F": "Review response, elevate the affected limb, and treat the entry point (e.g. athlete's foot or a leg ulcer).", "G": "Red flags - rapidly spreading erythema, pain out of proportion, crepitus, skin necrosis or systemic toxicity - suggest necrotising fasciitis, a surgical emergency needing urgent debridement."}}, cluster: "Infections & infestations", name: "Cellulitis", keyFacts: "An acute bacterial infection of the deep dermis and subcutaneous tissue, usually of the lower leg.", epidemiology: "Common, with higher risk in oedema, diabetes and breaks in the skin.", aetiology: "Streptococcus pyogenes and Staphylococcus aureus entering through a breach in the skin.", pathophysiology: "Bacteria invade and spread through the dermis and subcutaneous tissue, producing a spreading area of inflammation.", presentation: "Spreading hot, red, tender, swollen skin with poorly defined edge, often the lower leg.", investigations: "Clinical; mark border; bloods/cultures if systemically unwell.", treatment: "Flucloxacillin first line; elevate limb; admit for IV antibiotics if severe." },
      { id: "derm_impetigo", cluster: "Infections & infestations", name: "Impetigo", keyFacts: "A superficial, highly contagious bacterial skin infection with golden crusting, common in children.", epidemiology: "Common in young children and spreads easily in close contact.", aetiology: "Staphylococcus aureus and Streptococcus pyogenes, often on already-broken skin (eczema, bites).", pathophysiology: "Superficial epidermal infection produces vesicles that rupture to leave the characteristic honey-coloured crust.", presentation: "Golden-crusted superficial lesions, contagious, common in children.", investigations: "Clinical; swab if extensive or recurrent.", treatment: "Topical hydrogen peroxide or fusidic acid; oral flucloxacillin if widespread; hygiene and exclusion advice." },
      { id: "derm_fungal", cluster: "Infections & infestations", name: "Fungal skin infections", keyFacts: "Superficial dermatophyte (tinea) and yeast infections of skin, nails and scalp.", epidemiology: "Very common, favoured by warmth, moisture and occlusion.", aetiology: "Dermatophytes and Candida, spread by contact and thriving in moist areas.", pathophysiology: "Fungi infect the keratin of the stratum corneum, nails or hair, provoking a scaly, itchy and often annular rash.", presentation: "Itchy annular scaly rash (tinea), or macerated interdigital/intertriginous areas.", investigations: "Clinical; skin scrapings for microscopy and culture.", treatment: "Topical antifungal; oral terbinafine for nail or scalp infection." },
      { id: "derm_pityriasis_versicolor", cluster: "Infections & infestations", name: "Pityriasis versicolor", keyFacts: "A common superficial yeast infection causing scaly patches of altered pigmentation on the trunk.", epidemiology: "Common in young adults, favoured by heat and humidity.", aetiology: "Overgrowth of the commensal yeast Malassezia.", pathophysiology: "Malassezia converts to its pathogenic hyphal form and produces acids that interfere with melanocytes, so the patches fail to tan.", presentation: "Well-defined scaly macules on the trunk, hypo- or hyperpigmented and more obvious after sun exposure.", investigations: "Clinical; skin scrapings show a spaghetti-and-meatballs appearance on microscopy; Wood's lamp.", treatment: "Topical antifungal (ketoconazole shampoo) first line; oral itraconazole if extensive; warn that repigmentation is slow and recurrence common." },
      { id: "derm_hsv", cluster: "Infections & infestations", name: "Herpes simplex virus", keyFacts: "A common recurrent vesicular infection; HSV-1 is typically orolabial (cold sores) and HSV-2 typically genital, though overlap occurs.", epidemiology: "Very common; most adults are HSV-1 seropositive.", aetiology: "Herpes simplex virus types 1 and 2, spread by direct contact; reactivated by stress, illness, sunlight and immunosuppression.", pathophysiology: "After primary infection the virus lies latent in sensory ganglia and periodically reactivates, travelling down the nerve to cause recurrent vesicles.", presentation: "Painful grouped vesicles on an erythematous base that crust over; cold sores at the lip; primary gingivostomatitis or genital herpes; herpetic whitlow; eczema herpeticum in those with eczema.", investigations: "Clinical; viral swab for PCR if uncertain; recognise eczema herpeticum as an emergency.", treatment: "Oral or topical aciclovir, most effective started early; treat eczema herpeticum urgently with systemic aciclovir." },
      { id: "derm_scabies", cluster: "Infections & infestations", name: "Scabies", keyFacts: "An intensely itchy infestation by the Sarcoptes scabiei mite, worse at night; treat close contacts too.", epidemiology: "Common, spreading in households and institutions by skin contact.", aetiology: "The mite Sarcoptes scabiei, transmitted by prolonged skin-to-skin contact.", pathophysiology: "The mite burrows into the stratum corneum and a delayed hypersensitivity reaction to it causes the intense itch.", presentation: "Widespread intensely itchy rash (worse at night) with burrows in the finger webs and wrists; crusted (Norwegian) scabies in the immunosuppressed is highly contagious.", investigations: "Clinical; dermoscopy or microscopy of a burrow shows the mite.", treatment: "Topical permethrin to the whole body, repeated after a week; treat all close contacts at the same time; hot-wash clothing and bedding; antihistamine for itch." },
      { id: "derm_actinic_keratosis", cluster: "Premalignant, benign & skin cancers", name: "Actinic keratosis", keyFacts: "A common premalignant lesion of sun-damaged skin that can progress to squamous cell carcinoma.", epidemiology: "Common in older, fair-skinned, sun-exposed people.", aetiology: "Cumulative ultraviolet exposure; higher risk in the immunosuppressed.", pathophysiology: "Ultraviolet-induced keratinocyte dysplasia, a small proportion of which progress to invasive squamous cell carcinoma.", presentation: "Rough, scaly, erythematous patches on sun-exposed sites (face, scalp, dorsa of hands); often better felt than seen.", investigations: "Clinical; biopsy if thickened, tender or growing to exclude squamous cell carcinoma.", treatment: "Sun protection; cryotherapy, topical 5-fluorouracil, imiquimod or diclofenac; field treatment and monitoring. (Seborrhoeic keratoses, by contrast, are benign and listed under benign skin lesions.)" },
      { id: "derm_bcc", cluster: "Premalignant, benign & skin cancers", name: "Basal cell carcinoma", keyFacts: "The commonest skin cancer; a slow-growing, locally invasive lesion that rarely metastasises.", epidemiology: "Very common in older, fair-skinned people with chronic sun exposure.", aetiology: "Cumulative ultraviolet exposure in fair skin; also radiation and immunosuppression.", pathophysiology: "Ultraviolet damage to basal keratinocytes causes a slowly enlarging tumour that invades locally.", presentation: "Slow-growing pearly nodule with telangiectasia, may ulcerate; sun-exposed skin.", investigations: "Clinical, dermoscopy, biopsy.", treatment: "Excision; topical/curettage for low-risk; rarely metastasises." },
      { id: "derm_scc", cluster: "Premalignant, benign & skin cancers", name: "Squamous cell carcinoma", keyFacts: "A keratinocyte malignancy that can metastasise, arising on sun-damaged skin.", epidemiology: "Common in older, fair-skinned, sun-exposed people and higher in immunosuppressed patients.", aetiology: "Chronic ultraviolet exposure, immunosuppression, and precursors such as actinic keratoses.", pathophysiology: "Ultraviolet-induced mutations transform epidermal keratinocytes into an invasive tumour with metastatic potential.", presentation: "Rapidly growing keratotic or ulcerated nodule on sun-exposed skin; can metastasise.", investigations: "Biopsy; assess nodes.", treatment: "Surgical excision; radiotherapy; urgent referral." },
      { id: "derm_melanoma", cluster: "Premalignant, benign & skin cancers", name: "Melanoma", keyFacts: "An aggressive malignancy of melanocytes; prognosis depends on Breslow depth, so early excision is vital.", epidemiology: "Incidence is rising and is linked to sun exposure and fair skin.", aetiology: "Ultraviolet exposure, especially intermittent intense burning, plus fair skin, many moles and family history.", pathophysiology: "Ultraviolet-induced mutations transform melanocytes into a malignancy that invades vertically and metastasises early.", presentation: "Changing pigmented lesion: asymmetry, irregular border, colour variation, diameter, evolution.", investigations: "Dermoscopy, urgent excision biopsy with Breslow thickness.", treatment: "Wide local excision; sentinel node and oncology for advanced disease; 2-week-wait referral." },
      { id: "derm_benign_lesions", cluster: "Premalignant, benign & skin cancers", name: "Benign skin lesions", keyFacts: "Common harmless lesions whose main importance is being recognised and distinguished from malignancy.", epidemiology: "Extremely common, increasing with age.", aetiology: "Various: seborrhoeic keratoses and skin tags with age, cherry angiomas (vascular), dermatofibromas (often after minor trauma), epidermoid cysts and melanocytic naevi.", pathophysiology: "Benign proliferations of skin components (keratinocytes, blood vessels, fibrous tissue or melanocytes).", presentation: "Seborrhoeic keratosis: a stuck-on warty pigmented plaque. Skin tag: a soft pedunculated papule in flexures. Cherry angioma: a small red papule. Dermatofibroma: a firm nodule with a positive dimple sign. Epidermoid cyst: a mobile nodule with a central punctum.", investigations: "Clinical and dermoscopy; biopsy only if the diagnosis is uncertain or to exclude malignancy.", treatment: "Reassurance; removal (cryotherapy, curettage or excision) only for symptoms or diagnostic doubt." },
      { id: "derm_vitiligo", cluster: "Pigment, hair & structural", name: "Vitiligo", keyFacts: "Acquired autoimmune loss of melanocytes causing well-demarcated depigmented white patches.", epidemiology: "Affects around 1% of people, at any age.", aetiology: "Autoimmune destruction of melanocytes; associated with thyroid disease, type 1 diabetes and pernicious anaemia.", pathophysiology: "Autoimmune loss of epidermal melanocytes removes pigment from affected areas.", presentation: "Symmetrical, well-demarcated depigmented macules and patches, often on the hands, face and around orifices; Koebner phenomenon.", investigations: "Clinical (Wood's lamp accentuates the patches); screen for associated autoimmune disease (thyroid).", treatment: "Sun protection and camouflage; topical steroids or calcineurin inhibitors; phototherapy; psychological support." },
      { id: "derm_alopecia", cluster: "Pigment, hair & structural", name: "Alopecia", keyFacts: "Hair loss, classified as scarring (irreversible) or non-scarring (potentially reversible).", epidemiology: "Common; androgenetic alopecia is the commonest pattern.", aetiology: "Non-scarring: androgenetic, alopecia areata (autoimmune), telogen effluvium, traction, tinea. Scarring: lichen planopilaris, discoid lupus, folliculitis decalvans.", pathophysiology: "Non-scarring forms spare the follicle so hair can regrow; scarring forms destroy follicles and replace them with fibrosis (permanent).", presentation: "Alopecia areata: smooth well-defined patches with exclamation-mark hairs. Androgenetic: patterned thinning. Scarring: loss of follicular openings.", investigations: "Clinical; pull test and dermoscopy; scalp biopsy if scarring; check iron, thyroid and autoimmune screen.", treatment: "Treat the cause; topical or intralesional steroids or minoxidil for alopecia areata; minoxidil or finasteride for androgenetic; treat scarring early to limit loss." },
      { id: "derm_acanthosis", cluster: "Pigment, hair & structural", name: "Acanthosis nigricans", keyFacts: "Symmetrical velvety hyperpigmented thickening of the flexures; a marker of insulin resistance or, rarely, internal malignancy.", epidemiology: "Common with obesity and insulin resistance.", aetiology: "Insulin resistance (obesity, type 2 diabetes, PCOS) and some drugs; rarely paraneoplastic (gastric adenocarcinoma), especially if rapid-onset in a thin adult.", pathophysiology: "Insulin and growth-factor stimulation of keratinocytes and fibroblasts thickens the epidermis.", presentation: "Symmetrical velvety, hyperpigmented thickened skin in the axillae, neck and groin, often with skin tags.", investigations: "Assess for insulin resistance (glucose, HbA1c, lipids); investigate for malignancy if sudden or extensive in a non-obese patient.", treatment: "Treat the underlying cause (weight loss, manage diabetes); topical retinoids or keratolytics for cosmesis." },
      { id: "derm_ichthyosis", cluster: "Pigment, hair & structural", name: "Ichthyosis", keyFacts: "Persistently dry, scaly skin resembling fish scales; usually inherited.", epidemiology: "Ichthyosis vulgaris is the commonest (about 1 in 250), often with atopy.", aetiology: "Mostly inherited (ichthyosis vulgaris from filaggrin mutations, autosomal dominant; also X-linked recessive forms); rarely acquired (malignancy, drugs).", pathophysiology: "Impaired skin-barrier formation and abnormal desquamation cause retention of scale.", presentation: "Generalised dry, rough, scaly skin (fish-scale appearance) sparing the flexures, with palmar hyperlinearity; often atopic.", investigations: "Clinical and family history; consider an underlying cause if acquired in adulthood.", treatment: "Liberal emollients and keratolytics (urea, lactic acid); manage associated atopy; topical retinoids for severe forms." },      { id: "derm_neuropathic_ulcer", cluster: "Wounds & ulcers", name: "Neuropathic ulcers", keyFacts: "Painless ulcers at pressure points from loss of protective sensation, classically in the diabetic foot.", epidemiology: "Common in diabetes and other peripheral neuropathies.", aetiology: "Peripheral neuropathy (most often diabetes) with repetitive unnoticed trauma, often with co-existing ischaemia.", pathophysiology: "Loss of protective sensation allows repeated pressure and trauma at weight-bearing sites to break down the skin.", presentation: "A painless, punched-out ulcer with a callused rim over pressure points (metatarsal heads, heel); a warm foot with reduced sensation and present pulses (unlike an ischaemic ulcer).", investigations: "Assess sensation (monofilament), pulses and ABPI; probe to bone with X-ray or MRI for osteomyelitis; review glycaemic control.", treatment: "Offloading (footwear, total-contact cast), debridement and wound care, treat infection; optimise diabetes; multidisciplinary foot team." },
      { id: "derm_pressure_sore", cluster: "Wounds & ulcers", name: "Pressure sores", keyFacts: "Localised skin and tissue damage over a bony prominence from sustained pressure; largely preventable.", epidemiology: "Common in immobile, elderly and bed-bound patients.", aetiology: "Sustained pressure, shear and friction, worsened by immobility, malnutrition, incontinence and reduced sensation.", pathophysiology: "Pressure over a bony prominence occludes capillaries, causing ischaemia and tissue necrosis.", presentation: "Graded I to IV: non-blanching erythema, partial-thickness loss, full-thickness into subcutaneous fat, then extension to muscle or bone; sacrum, heels and hips.", investigations: "Clinical staging and a risk score (Waterlow); swab and bloods if infected; consider osteomyelitis in deep ulcers.", treatment: "Prevention is key: repositioning, pressure-redistributing mattresses, skin care and nutrition; wound care and debridement; treat infection." },
      { id: "derm_burns", cluster: "Wounds & ulcers", name: "Burns", keyFacts: "Thermal, chemical or electrical skin injury; assess depth and the percentage body-surface area, and resuscitate major burns.", epidemiology: "Common; scalds in children and flame burns in adults.", aetiology: "Heat (flame, scald, contact), chemicals, electricity and radiation.", pathophysiology: "A central zone of coagulation with surrounding zones of stasis and hyperaemia; large burns cause fluid shifts, hypovolaemia and a systemic inflammatory response.", presentation: "Superficial (erythema, painful), partial-thickness (blisters, painful), and full-thickness (white or leathery, painless); assess depth, area (rule of nines) and the airway.", investigations: "Estimate total body-surface area; assess for inhalation injury; bloods and carboxyhaemoglobin if smoke exposure.", treatment: "First aid is cool running water for 20 minutes and removing constricting items; fluid resuscitation (Parkland formula) for major burns; analgesia and dressings; refer large, deep or special-site burns to a burns unit." },
      { id: "cvs_gangrene", cluster: "Wounds & ulcers", name: "Gangrene", keyFacts: "Tissue death from an inadequate blood supply or infection; dry, wet or gas gangrene, and a limb- and life-threatening problem.", epidemiology: "Seen with peripheral arterial disease, diabetes and severe infection.", aetiology: "Ischaemia (peripheral arterial disease, acute limb ischaemia), infection (wet gangrene, and gas gangrene from Clostridium perfringens), and diabetic foot disease.", pathophysiology: "Loss of perfusion causes tissue necrosis; dry gangrene mummifies, whereas wet gangrene is infected and can progress rapidly to sepsis.", presentation: "Black, dead tissue; dry gangrene is dry and demarcated, wet gangrene is swollen, malodorous and infected, and gas gangrene has crepitus and rapid systemic toxicity.", investigations: "Assess perfusion (pulses, ABPI, imaging), bloods and cultures; X-ray for gas.", treatment: "Revascularise where possible; antibiotics and urgent surgical debridement or amputation for wet or gas gangrene; treat the underlying cause; diabetic foot care." },
      { id: "derm_dry_gangrene", cluster: "Wounds & ulcers", name: "Dry gangrene", keyFacts: "Tissue necrosis from chronic arterial insufficiency without infection; the tissue mummifies and self-demarcates.", epidemiology: "Seen with peripheral arterial disease, diabetes and atherosclerosis, typically in the toes and feet.", aetiology: "Chronic ischaemia from peripheral arterial disease, diabetes or vasculitis, without significant infection.", pathophysiology: "Gradual loss of arterial perfusion causes coagulative necrosis, and with no infection the tissue dries out, shrinks and blackens.", presentation: "A dry, shrivelled, black area (usually a toe or foot) with a clear line of demarcation from healthy tissue; cold and painless once necrotic, with minimal odour.", investigations: "Assess perfusion (pulses, ankle-brachial pressure index, duplex, angiography); glucose and vascular risk factors.", treatment: "Revascularise where possible and control risk factors; allow auto-amputation or perform elective amputation of the demarcated area; keep it clean and dry to prevent secondary infection." },
      { id: "derm_wet_gangrene", cluster: "Wounds & ulcers", name: "Wet gangrene", keyFacts: "Infected tissue necrosis that spreads rapidly and can cause sepsis; a surgical emergency.", epidemiology: "Commoner in diabetes and with critical limb ischaemia or after trauma.", aetiology: "Necrotic tissue infected by bacteria (often mixed, including anaerobes), usually on a background of diabetes or arterial disease.", pathophysiology: "Bacterial infection and liquefactive necrosis in poorly perfused tissue spread quickly, releasing toxins and threatening life through sepsis.", presentation: "A swollen, blistered, malodorous, discolouring wound with pus and surrounding cellulitis and systemic features of sepsis; ill-defined margins (unlike dry gangrene).", investigations: "Bloods and cultures, imaging for extent and for gas; assess perfusion and glycaemic control.", treatment: "Urgent broad-spectrum IV antibiotics and prompt surgical debridement or amputation; resuscitate for sepsis; revascularise and control diabetes." },
      { id: "derm_gingival_hyperplasia", cluster: "Other", name: "Gingival hyperplasia", keyFacts: "Overgrowth of the gums, most often drug-induced; the three classic culprits are phenytoin, ciclosporin and calcium-channel blockers.", epidemiology: "Seen with the causative drugs and with poor oral hygiene.", aetiology: "Drugs (phenytoin, ciclosporin, nifedipine and other calcium-channel blockers); also pregnancy, leukaemia and scurvy.", pathophysiology: "Drug-induced fibroblast proliferation and matrix accumulation enlarge the gingiva, worsened by dental plaque.", presentation: "Painless, firm overgrowth of the gums that can grow to cover the teeth, with bleeding and difficulty eating.", investigations: "Clinical with a drug history; full blood count if leukaemia is suspected.", treatment: "Good oral hygiene and dental care; withdraw or switch the causative drug; surgical gingivectomy if severe." },
      { id: "derm_artefacta", cluster: "Other", name: "Dermatitis artefacta", keyFacts: "Self-inflicted skin lesions produced, often not consciously, to meet a psychological need, which the patient denies causing.", epidemiology: "Commoner in young women; associated with psychological distress.", aetiology: "A psychocutaneous disorder linked to stress and to personality or psychiatric factors.", pathophysiology: "Lesions are self-produced (scratching, burning, chemicals) but driven by psychological need; it differs from malingering, which has external gain.", presentation: "Bizarre, geometric or linear lesions with sharp borders at accessible sites, not fitting any recognised dermatosis, with a curiously detached history.", investigations: "Clinical; exclude genuine dermatoses; sensitive psychological assessment.", treatment: "A non-confrontational, supportive approach; occlusive dressings (lesions heal when covered); treat the underlying psychological issues with dermatology-psychiatry liaison." },
    ],
  },
  {
    id: "ent",
    name: "ENT",
    icon: "👂",
    conditions: [
      { id: "ent_oe", cluster: "External & middle ear", name: "Otitis externa", keyFacts: "Inflammation of the external ear canal causing itch, pain and discharge.", epidemiology: "Common, especially in swimmers and humid climates.", aetiology: "Bacterial (Pseudomonas, Staphylococcus) or fungal infection, often with moisture or trauma.", pathophysiology: "Loss of the protective wax barrier with moisture or trauma allows infection and inflammation of the canal skin.", presentation: "Itchy painful ear with discharge; tender tragus; canal swelling.", investigations: "Otoscopy; swab if resistant.", treatment: "Aural toilet, topical antibiotic/steroid drops; keep ear dry; consider fungal cause." },
      { id: "ent_om", management: {"def": "A[\"Acute otitis media\"]:::start --> B[\"Analgesia (paracetamol/ibuprofen)\"]:::good\nB --> C{\"Antibiotic needed?\"}:::decision\nC -- \"most cases\" --> D[\"No or delayed antibiotic\"]:::good\nC -- \"unwell / under 2 bilateral / otorrhoea\" --> E[\"Immediate amoxicillin (5-7 days)\"]:::good\nE -- \"penicillin allergy\" --> F[\"Clarithromycin (erythromycin in pregnancy)\"]:::good\nA --> G[\"Safety-net: review if worse or not better in 3 days\"]:::warn", "tips": {"A": "Middle-ear infection with ear pain, fever and a bulging red tympanic membrane; usually viral and self-limiting.", "B": "Regular paracetamol or ibuprofen is the mainstay for pain and fever.", "C": "Most cases do not need antibiotics; decide by severity and risk.", "D": "Offer no antibiotic or a back-up (delayed) prescription to start if not improving in 3 days - most resolve within a few days.", "E": "Immediate amoxicillin if systemically very unwell, high risk of complications, symptoms 4+ days and not improving, under 2 with bilateral infection, or with otorrhoea/perforation.", "F": "In penicillin allergy use clarithromycin (or erythromycin in pregnancy).", "G": "Safety-net: review if symptoms worsen rapidly, do not improve in 3 days, or complications develop (mastoiditis, meningitis)."}}, cluster: "External & middle ear", name: "Acute otitis media", keyFacts: "Acute middle-ear infection causing ear pain and fever in children; usually self-limiting.", epidemiology: "Very common in young children.", aetiology: "Viral or bacterial (Streptococcus pneumoniae, Haemophilus) infection, often after a cold.", pathophysiology: "Eustachian tube dysfunction lets infection and fluid accumulate behind the tympanic membrane, which bulges and may perforate.", presentation: "Ear pain, fever, reduced hearing in a child; bulging red tympanic membrane.", investigations: "Otoscopy.", treatment: "Usually self-limiting analgesia; delayed or immediate amoxicillin if severe, bilateral in young, or perforation." },
      { id: "ent_ome", cluster: "External & middle ear", name: "Otitis media with effusion (glue ear)", keyFacts: "Fluid in the middle ear without acute infection; the commonest cause of hearing loss in children.", epidemiology: "Very common in young children, peaking around age 2, and often resolving spontaneously.", aetiology: "Eustachian tube dysfunction, often after upper respiratory infections; commoner in Down syndrome and cleft palate.", pathophysiology: "Poor middle-ear ventilation lets a sterile effusion collect behind an intact eardrum, impairing sound conduction.", presentation: "Reduced hearing, or speech and behavioural problems, in a child; a dull, retracted tympanic membrane with fluid; usually painless.", investigations: "Otoscopy, tympanometry (flat trace), audiometry; watchful waiting over 3 months.", treatment: "Active observation as most resolve; grommets (ventilation tubes) and/or hearing aids if persistent and affecting hearing or development." },
      { id: "ent_csom", cluster: "External & middle ear", name: "Chronic suppurative otitis media", keyFacts: "Persistent middle-ear infection with a perforated eardrum and chronic discharge; exclude cholesteatoma.", epidemiology: "Commoner after recurrent acute otitis media, with grommets, and in lower-income settings.", aetiology: "Persistent infection (often Pseudomonas or Staphylococcus) through a chronic tympanic membrane perforation.", pathophysiology: "A non-healing perforation allows ongoing middle-ear infection and inflammation; an associated cholesteatoma can erode local structures.", presentation: "Chronic or recurrent painless ear discharge with a perforation and conductive hearing loss; foul-smelling discharge suggests cholesteatoma.", investigations: "Otoscopy (perforation, discharge, look for cholesteatoma), swab, audiometry; CT if cholesteatoma or complications are suspected.", treatment: "Aural toilet and topical antibiotic/steroid drops; treat or exclude cholesteatoma; surgery (myringoplasty, mastoidectomy) as needed." },
      { id: "ent_otosclerosis", cluster: "External & middle ear", name: "Otosclerosis", keyFacts: "Abnormal bone remodelling fixing the stapes, causing progressive conductive hearing loss in young adults.", epidemiology: "Typically presents in early-to-middle adulthood, commoner in women and often familial; worsens in pregnancy.", aetiology: "Autosomal dominant with variable penetrance; abnormal remodelling of the otic capsule.", pathophysiology: "New bone fixes the stapes footplate at the oval window, impairing sound transmission; cochlear involvement can add sensorineural loss.", presentation: "Progressive bilateral conductive hearing loss with tinnitus in a young adult; speech may be unusually soft; a normal eardrum (sometimes a pink flush, the Schwartze sign).", investigations: "Audiometry (conductive loss, Carhart's notch), tympanometry; CT for surgical planning.", treatment: "Hearing aids; stapedectomy or stapedotomy; sodium fluoride in selected cases." },
      { id: "ent_hearing_loss", cluster: "Hearing, balance & inner ear", name: "Hearing loss", keyFacts: "Loss of hearing, conductive or sensorineural; sudden sensorineural loss is a red flag for urgent referral.", epidemiology: "Very common, especially age-related (presbycusis) in the elderly.", aetiology: "Conductive from wax, effusion or otosclerosis; sensorineural from ageing, noise, drugs or infection.", pathophysiology: "Conductive loss reflects impaired sound transmission through the outer or middle ear; sensorineural loss reflects cochlear or nerve damage.", presentation: "Conductive (wax, effusion) or sensorineural (presbycusis, noise); sudden loss is a red flag.", investigations: "Otoscopy, tuning fork tests, audiometry.", treatment: "Treat cause; urgent ENT for sudden sensorineural loss; hearing aids for presbycusis." },
      { id: "ent_tinnitus", cluster: "Hearing, balance & inner ear", name: "Tinnitus", keyFacts: "Perception of sound without an external source; usually benign, but unilateral or pulsatile tinnitus needs investigation.", epidemiology: "Very common, increasing with age and noise exposure.", aetiology: "Often with hearing loss (presbycusis, noise); also wax, Ménière's, ototoxic drugs, and red flags such as acoustic neuroma or a vascular cause for pulsatile tinnitus.", pathophysiology: "Usually aberrant neural activity in the auditory pathway associated with cochlear damage; pulsatile tinnitus reflects turbulent blood flow.", presentation: "Ringing, buzzing or hissing in the ears; bilateral and non-pulsatile is usually benign, whereas unilateral or pulsatile is a red flag.", investigations: "Otoscopy and audiometry; MRI for unilateral tinnitus (exclude acoustic neuroma); imaging for pulsatile tinnitus.", treatment: "Treat any cause; reassurance, sound therapy and cognitive behavioural therapy; hearing aids if there is associated hearing loss." },
      { id: "ent_bppv", cluster: "Hearing, balance & inner ear", name: "Benign paroxysmal positional vertigo", keyFacts: "Brief rotational vertigo triggered by head movement without hearing loss; diagnosed by Dix-Hallpike.", epidemiology: "Common, increasing with age.", aetiology: "Displaced otoconia (calcium crystals) in the semicircular canals, often idiopathic or post-trauma.", pathophysiology: "Free-floating otoconia disturb endolymph flow during head movement, sending the brain false signals of rotation.", presentation: "Brief rotational vertigo triggered by head movement, no hearing loss.", investigations: "Dix-Hallpike manoeuvre.", treatment: "Epley manoeuvre; reassurance; usually self-limiting." },
      { id: "ent_menieres", cluster: "Hearing, balance & inner ear", name: "Ménière's disease", keyFacts: "Episodic vertigo with fluctuating sensorineural hearing loss, tinnitus and aural fullness.", epidemiology: "Uncommon, typically presenting in middle age.", aetiology: "Idiopathic endolymphatic hydrops, an excess of inner-ear fluid.", pathophysiology: "Raised endolymph pressure in the inner ear distorts the hearing and balance organs, causing the episodic symptoms.", presentation: "Episodic vertigo, fluctuating sensorineural hearing loss, tinnitus and aural fullness.", investigations: "Audiometry; ENT referral.", treatment: "Acute prochlorperazine; betahistine and low-salt diet for prevention; DVLA advice." },
      { id: "ent_acoustic_neuroma", cluster: "Hearing, balance & inner ear", name: "Acoustic neuroma", keyFacts: "A benign vestibular schwannoma of the vestibulocochlear nerve, classically causing unilateral hearing loss and tinnitus.", epidemiology: "Uncommon; usually presents in middle age; bilateral tumours suggest neurofibromatosis type 2.", aetiology: "A Schwann cell tumour of the eighth cranial nerve, usually sporadic; bilateral in neurofibromatosis type 2.", pathophysiology: "The tumour grows in the cerebellopontine angle, compressing the vestibulocochlear nerve and later the trigeminal and facial nerves.", presentation: "Unilateral sensorineural hearing loss, tinnitus and imbalance; large tumours give an absent corneal reflex and facial numbness or weakness.", investigations: "Audiometry and MRI of the internal auditory meati (the investigation of choice).", treatment: "Observation with serial imaging for small tumours; surgery or stereotactic radiosurgery for larger or growing tumours; ENT and neurosurgery MDT." },
      { id: "ent_rhinitis", cluster: "Nose & sinuses", name: "Allergic rhinitis", keyFacts: "An IgE-mediated allergic inflammation of the nasal mucosa with sneezing, itch and congestion.", epidemiology: "Very common, often with coexisting asthma and eczema (atopy).", aetiology: "Inhaled allergens such as pollen, house-dust mite and animal dander in atopic people.", pathophysiology: "Allergen cross-linking of IgE on mast cells releases histamine, producing the nasal and ocular symptoms.", presentation: "Sneezing, itch, nasal congestion and watery rhinorrhoea, often with conjunctivitis.", investigations: "Clinical; allergy testing if needed.", treatment: "Allergen avoidance, antihistamines, intranasal steroids." },
      { id: "ent_sinusitis", cluster: "Nose & sinuses", name: "Acute sinusitis", keyFacts: "Inflammation of the paranasal sinuses for under 12 weeks, with facial pain and congestion; usually viral.", epidemiology: "Common, usually following a viral upper respiratory infection.", aetiology: "Viral infection, sometimes with secondary bacterial infection (Streptococcus pneumoniae, Haemophilus); allergy and obstruction predispose.", pathophysiology: "Mucosal inflammation obstructs sinus drainage, so secretions accumulate and may become secondarily infected.", presentation: "Facial pain or pressure, nasal congestion, purulent discharge and reduced smell for under 12 weeks.", investigations: "Clinical; imaging only for suspected complications.", treatment: "Usually viral and self-limiting; analgesia and intranasal steroid; antibiotics only if severe or symptoms persist beyond about 10 days." },
      { id: "ent_sinusitis_chronic", cluster: "Nose & sinuses", name: "Chronic sinusitis", keyFacts: "Sinonasal inflammation lasting 12 weeks or more; often associated with nasal polyps and allergy.", epidemiology: "Common; frequently with allergy, asthma or nasal polyps.", aetiology: "Persistent mucosal inflammation, with allergy, nasal polyps, anatomical obstruction, smoking and rarely fungal or immune causes.", pathophysiology: "Ongoing inflammation and impaired mucociliary clearance perpetuate sinus obstruction and infection.", presentation: "Nasal blockage, facial pressure, discharge and reduced smell for 12 or more weeks, with or without polyps.", investigations: "Nasal endoscopy; CT sinuses if refractory or surgery is planned; allergy assessment.", treatment: "Saline irrigation and intranasal (then short oral) steroids; treat allergy; functional endoscopic sinus surgery (FESS) for refractory disease." },
      { id: "ent_nasal_polyps", cluster: "Nose & sinuses", name: "Nasal polyps", keyFacts: "Benign oedematous swellings of the nasal and sinus mucosa causing obstruction and reduced smell; a unilateral polyp needs urgent referral.", epidemiology: "Commoner in adults and in men; associated with asthma, chronic rhinosinusitis and aspirin sensitivity.", aetiology: "Chronic mucosal inflammation; associations include asthma and aspirin sensitivity (Samter's triad), chronic rhinosinusitis and, in children, cystic fibrosis.", pathophysiology: "Chronic inflammation produces oedematous mucosal outgrowths (polyps) that obstruct the nose and sinuses.", presentation: "Nasal obstruction, reduced smell (anosmia), rhinorrhoea and post-nasal drip; pale grey mobile masses on examination.", investigations: "Nasal examination and endoscopy; CT for extent; urgent referral for a unilateral polyp to exclude malignancy.", treatment: "Intranasal then short-course oral corticosteroids; functional endoscopic sinus surgery if refractory; treat associated asthma and allergy." },
      { id: "ent_epistaxis", management: {"def": "A[\"Epistaxis\"]:::start --> B[\"First aid: lean forward, pinch soft nose 10-15 min\"]:::good\nB --> C{\"Bleeding stopped?\"}:::decision\nC -- \"yes, source seen\" --> D[\"Nasal cautery (silver nitrate) + cream\"]:::good\nC -- \"no\" --> E[\"Anterior nasal packing\"]:::warn\nE -- \"still bleeding / posterior\" --> F[\"Posterior pack, admit, ENT referral\"]:::danger\nA --> G[\"Check cause: anticoagulants, hypertension, trauma\"]:::process", "tips": {"A": "Nosebleed, usually from Little's area on the anterior septum; most are self-limiting and settle with first aid.", "B": "Sit up and lean forward, breathe through the mouth, and firmly pinch the soft cartilaginous part of the nose for 10-15 minutes; apply an ice pack.", "C": "Reassess after first aid.", "D": "If bleeding stops and the point is seen, cauterise with silver nitrate and apply a topical antiseptic (e.g. Naseptin); do not cauterise both sides of the septum.", "E": "If first aid fails, insert an anterior nasal pack (nasal tampon or inflatable device).", "F": "Persistent or posterior bleeding needs a posterior pack, admission and ENT review; consider examination under anaesthesia or arterial ligation/embolisation.", "G": "Look for and address causes: anticoagulants/antiplatelets, coagulopathy, hypertension, trauma or nasal disease."}}, cluster: "Nose & sinuses", name: "Epistaxis", keyFacts: "A nosebleed, usually from the anterior septum (Little's area); posterior bleeds are heavier.", epidemiology: "Very common, with peaks in children and older adults.", aetiology: "Trauma (nose-picking), dry air, hypertension, anticoagulants and clotting disorders.", pathophysiology: "Rupture of the rich septal vascular plexus causes bleeding, controlled by pressure, cautery or packing.", presentation: "Nosebleed, usually anterior from Little's area; posterior bleeds are heavier.", investigations: "Assess for bleeding disorders/anticoagulants if recurrent.", treatment: "First aid pinch and lean forward; cautery or packing; treat cause." },
      { id: "ent_tonsillitis", management: {"def": "A[\"Acute sore throat / tonsillitis\"]:::start --> B[\"Score: FeverPAIN or Centor\"]:::process\nB --> C{\"Score\"}:::decision\nC -- \"low (FeverPAIN 0-1)\" --> D[\"No antibiotic, analgesia and safety-net\"]:::good\nC -- \"intermediate (2-3)\" --> E[\"Delayed (back-up) antibiotic\"]:::good\nC -- \"high (FeverPAIN 4-5)\" --> F[\"Immediate phenoxymethylpenicillin\"]:::good\nA -- \"trismus, drooling, unilateral swelling\" --> G[\"Quinsy or airway risk: urgent ENT\"]:::danger", "tips": {"A": "Most sore throats and acute tonsillitis are viral and self-limiting; scores identify who may benefit from antibiotics (NICE NG84).", "B": "Use FeverPAIN (Fever, Purulence, Attend rapidly under 3 days, severely Inflamed tonsils, No cough or coryza) or Centor (tonsillar exudate, tender anterior cervical nodes, fever, absence of cough).", "C": "The score guides the antibiotic decision.", "D": "Low score (FeverPAIN 0-1, Centor 0-2): no antibiotic - analgesia (paracetamol or ibuprofen), fluids and safety-netting.", "E": "Intermediate (FeverPAIN 2-3): consider a back-up (delayed) antibiotic prescription.", "F": "High score (FeverPAIN 4-5, Centor 3-4): offer immediate phenoxymethylpenicillin (clarithromycin or erythromycin if penicillin-allergic) for 5-10 days. Avoid amoxicillin (causes a rash in glandular fever).", "G": "Red flags - severe unilateral pain, trismus, a muffled hot-potato voice, drooling or a displaced uvula - suggest quinsy (peritonsillar abscess) or airway compromise needing urgent ENT."}}, cluster: "Throat", name: "Tonsillitis", keyFacts: "Acute inflammation of the tonsils; the Centor or FeverPAIN score guides antibiotic use.", epidemiology: "Very common, particularly in children and young adults.", aetiology: "Mostly viral; bacterial cases are usually group A streptococcus.", pathophysiology: "Infection inflames the tonsillar tissue, causing sore throat, exudate and tender cervical nodes.", presentation: "Sore throat, fever, dysphagia, tonsillar exudate, tender cervical nodes.", investigations: "FeverPAIN or Centor score.", treatment: "Analgesia; phenoxymethylpenicillin if high score; avoid amoxicillin if glandular fever possible." },
      { id: "ent_glandular", cluster: "Throat", name: "Glandular fever", keyFacts: "Infectious mononucleosis from Epstein-Barr virus, with sore throat, fatigue and lymphadenopathy.", epidemiology: "Common in adolescents and young adults.", aetiology: "Epstein-Barr virus, transmitted in saliva.", pathophysiology: "The virus infects B-lymphocytes and provokes a vigorous T-cell response that causes the systemic features and splenomegaly.", presentation: "Sore throat, fatigue, fever, lymphadenopathy, splenomegaly in young adults.", investigations: "Monospot/EBV serology, FBC (atypical lymphocytes), LFTs.", treatment: "Supportive; avoid contact sport for splenic rupture risk; avoid amoxicillin (rash)." },
      { id: "ent_sialadenitis", cluster: "Salivary glands", name: "Sialadenitis", keyFacts: "Inflammation or infection of a salivary gland (often parotid or submandibular); may be acute and infective or chronic.", epidemiology: "Acute bacterial sialadenitis is commoner in the dehydrated, elderly or post-operative.", aetiology: "Bacterial (Staphylococcus aureus) with reduced salivary flow or duct obstruction; viral (mumps); autoimmune (Sjögren's).", pathophysiology: "Salivary stasis or obstruction allows ascending infection and gland inflammation.", presentation: "A painful, swollen gland that is worse on eating, with possible pus at the duct opening, fever and trismus; bilateral parotid swelling suggests mumps.", investigations: "Clinical; ultrasound for stones or abscess; pus swab; autoimmune screen if indicated.", treatment: "Hydration, warm compresses, sialogogues, massage and antibiotics for bacterial infection; drain an abscess; treat the underlying cause." },
      { id: "ent_sialolithiasis", cluster: "Salivary glands", name: "Sialolithiasis", keyFacts: "A salivary duct stone, most often in the submandibular (Wharton's) duct, causing mealtime pain and swelling.", epidemiology: "The commonest salivary gland disease, mainly in adults.", aetiology: "Calcium-rich stone formation favoured by salivary stasis and dehydration; the submandibular gland is most affected (thicker, alkaline saliva and an upward-draining duct).", pathophysiology: "A stone obstructs salivary outflow, so the gland swells painfully on salivary stimulation and may become infected.", presentation: "Recurrent pain and swelling of the gland on eating (mealtime syndrome); a stone may be palpable in the floor of the mouth.", investigations: "Bimanual palpation, X-ray or ultrasound (most stones are radio-opaque); sialography or CT if needed.", treatment: "Hydration, sialogogues, massage and warm compresses; stone removal (intraoral or sialendoscopy) or gland excision for recurrent disease." },
    ],
  },
  {
    id: "ophthalmology",
    name: "Ophthalmology",
    icon: "👁️",
    conditions: [
      { id: "eye_blepharitis", cluster: "Eyelid & ocular surface", name: "Blepharitis", keyFacts: "Chronic inflammation of the eyelid margins causing sore, gritty, crusted lids; common and recurrent.", epidemiology: "Common, especially in older adults and those with rosacea or seborrhoeic dermatitis.", aetiology: "Anterior (staphylococcal or seborrhoeic) or posterior (meibomian gland dysfunction); associated with rosacea.", pathophysiology: "Inflammation and altered secretions of the lid margin and meibomian glands destabilise the tear film.", presentation: "Bilateral sore, itchy, gritty eyelids with crusting and red margins, worse in the mornings, with dry-eye symptoms.", investigations: "Clinical.", treatment: "Lid hygiene (warm compresses, massage and cleaning) is the mainstay; artificial tears; topical antibiotic or oral doxycycline if severe; chronic and relapsing." },
      { id: "eye_stye", cluster: "Eyelid & ocular surface", name: "Stye (hordeolum)", keyFacts: "An acute, painful, localised infection of an eyelid gland; usually self-limiting.", epidemiology: "Common at all ages.", aetiology: "Staphylococcal infection of an eyelash follicle (external) or a meibomian gland (internal).", pathophysiology: "Acute bacterial infection of a lid gland produces a tender, red, pus-filled swelling at the lid margin.", presentation: "A painful red lump on the eyelid margin, sometimes pointing with pus; external styes point outward, internal ones inward.", investigations: "Clinical.", treatment: "Warm compresses and hygiene; most resolve spontaneously; incision and drainage or topical antibiotic if needed; remove the associated eyelash." },
      { id: "eye_chalazion", cluster: "Eyelid & ocular surface", name: "Meibomian cyst (chalazion)", keyFacts: "A painless granulomatous cyst from a blocked meibomian gland; distinct from the painful stye.", epidemiology: "Common; associated with blepharitis and rosacea.", aetiology: "Obstruction of a meibomian gland with retained secretion and a granulomatous reaction.", pathophysiology: "A blocked meibomian gland forms a firm, painless lipogranuloma within the tarsal plate.", presentation: "A firm, painless lump in the body of the eyelid (away from the margin), developing over weeks; may follow a stye.", investigations: "Clinical; consider biopsy if atypical or recurrent to exclude sebaceous carcinoma.", treatment: "Warm compresses and massage; most resolve; incision and curettage or steroid injection if persistent." },
      { id: "eye_conjunctivitis", cluster: "Eyelid & ocular surface", name: "Conjunctivitis", keyFacts: "Inflammation of the conjunctiva causing a red, gritty eye; usually benign and self-limiting.", epidemiology: "Very common, in all ages.", aetiology: "Viral (commonest), bacterial or allergic; neonatal cases may be gonococcal or chlamydial.", pathophysiology: "Inflammation of the conjunctival surface causes redness, discharge and irritation while sparing vision.", presentation: "Red gritty eye with discharge; bilateral itch suggests allergy, purulent suggests bacterial.", investigations: "Clinical; swab if severe/neonatal.", treatment: "Bacterial often self-limiting or chloramphenicol; antihistamine for allergic; hygiene advice." },
      { id: "eye_subconj_haem", cluster: "Eyelid & ocular surface", name: "Subconjunctival haemorrhage", keyFacts: "A flat, painless red patch of blood under the conjunctiva; alarming but harmless and self-limiting.", epidemiology: "Common at all ages, commoner in older people and on anticoagulants.", aetiology: "Spontaneous (cough, sneeze, straining, Valsalva), trauma, hypertension or a bleeding tendency/anticoagulation.", pathophysiology: "Rupture of a small subconjunctival vessel leaks blood into the potential space, which resolves as the blood is reabsorbed.", presentation: "A painless, well-demarcated bright-red patch on the white of the eye with normal vision and no discharge.", investigations: "Clinical; check blood pressure; consider clotting if recurrent or spontaneous; exclude a ruptured globe if traumatic.", treatment: "Reassurance; it resolves over 1-2 weeks; lubricants for irritation; review anticoagulation and blood pressure if relevant." },
      { id: "eye_episcleritis", cluster: "Cornea, sclera & uvea", name: "Episcleritis", keyFacts: "Benign, self-limiting inflammation of the episclera causing a mildly red but comfortable eye.", epidemiology: "Common in young to middle-aged adults, commoner in women.", aetiology: "Usually idiopathic; a minority have an associated systemic inflammatory disease.", pathophysiology: "Inflammation of the thin episcleral layer causes localised or diffuse redness with little or no pain.", presentation: "A mildly red, comfortable or slightly gritty eye with no discharge and normal vision; the redness blanches with topical phenylephrine.", investigations: "Clinical; the phenylephrine test distinguishes it from scleritis.", treatment: "Self-limiting; lubricants and reassurance; topical or oral NSAIDs for symptoms." },
      { id: "eye_scleritis", cluster: "Cornea, sclera & uvea", name: "Scleritis", keyFacts: "Serious, painful inflammation of the sclera that can threaten the eye; often linked to systemic autoimmune disease.", epidemiology: "Uncommon; peaks in middle age, commoner in women.", aetiology: "Often associated with systemic autoimmune disease (rheumatoid arthritis, GPA, SLE); can be infective.", pathophysiology: "Inflammation of the deep scleral layer causes severe boring pain and can lead to scleral thinning and perforation.", presentation: "A severely painful red eye (deep boring pain, worse at night and on eye movement), photophobia, watering and reduced vision; the redness does not blanch with phenylephrine.", investigations: "Slit-lamp; phenylephrine test (no blanching); screen for systemic autoimmune disease.", treatment: "Urgent ophthalmology; systemic NSAIDs, steroids and immunosuppression; treat any underlying disease." },
      { id: "eye_keratitis", cluster: "Cornea, sclera & uvea", name: "Corneal ulcers & keratitis", keyFacts: "Inflammation or ulceration of the cornea; a sight-threatening emergency, especially in contact-lens wearers.", epidemiology: "Higher risk with contact lenses, trauma, dry eyes and immunosuppression.", aetiology: "Bacterial (Pseudomonas in lens wearers), viral (herpes simplex, a dendritic ulcer), fungal, or Acanthamoeba (lens wearers exposed to water).", pathophysiology: "Infection or inflammation breaches the corneal epithelium, and an ulcer can scar or perforate the cornea, threatening sight.", presentation: "A painful red eye with photophobia, watering, blurred vision and a corneal opacity or ulcer; herpes simplex gives a dendritic ulcer on fluorescein staining.", investigations: "Slit-lamp with fluorescein staining; corneal scrape for microscopy and culture.", treatment: "Urgent ophthalmology; intensive topical antibiotics (or antivirals for herpes, avoiding steroids in herpes); stop contact-lens wear." },
      { id: "eye_uveitis", cluster: "Cornea, sclera & uvea", name: "Anterior uveitis", keyFacts: "Inflammation of the uveal tract causing a painful red eye with photophobia; linked to HLA-B27 disease.", epidemiology: "Anterior uveitis is the commonest form, often in young to middle-aged adults.", aetiology: "Idiopathic, or associated with HLA-B27 conditions, sarcoidosis, infection and inflammatory bowel disease.", pathophysiology: "Inflammation of the iris and ciliary body releases cells and protein into the anterior chamber, causing pain and blurring.", presentation: "Painful red eye, photophobia, blurred vision, small irregular pupil; linked to HLA-B27 disease.", investigations: "Slit-lamp (cells/flare); look for systemic associations.", treatment: "Topical steroids and cycloplegics under ophthalmology; treat underlying disease." },
      { id: "eye_preseptal_cellulitis", cluster: "Orbital infection", name: "Preseptal cellulitis", keyFacts: "Infection of the eyelid and skin anterior to the orbital septum; less serious than orbital cellulitis but can progress to it.", epidemiology: "Commoner in children; often follows local skin infection or sinusitis.", aetiology: "Spread from local skin (trauma, insect bite, stye) or sinus infection; Staphylococcus, Streptococcus, Haemophilus.", pathophysiology: "Infection confined anterior to the orbital septum, sparing the orbital contents.", presentation: "A red, swollen, tender eyelid WITHOUT proptosis, painful or restricted eye movements, or reduced vision (which would indicate orbital cellulitis).", investigations: "Clinical; CT orbits if orbital cellulitis cannot be excluded.", treatment: "Oral antibiotics (e.g. co-amoxiclav) with close review; admit and image if there is any concern about progression." },
      { id: "eye_orbital_cellulitis", management: {"source": "Ophthalmic emergency", "def": "A[\"Orbital cellulitis\"]:::start --> B[\"Distinguish from preseptal (eye movements, proptosis)\"]:::process\nB --> C[\"Emergency admission, IV antibiotics\"]:::danger\nC --> D[\"Urgent CT orbits and sinuses\"]:::process\nD --> E[\"Ophthalmology and ENT review\"]:::good\nE -- \"abscess or no improvement\" --> F[\"Surgical drainage\"]:::warn\nA --> G[\"Monitor vision for complications\"]:::warn", "tips": {"A": "Infection behind the orbital septum (usually spreading from the ethmoid sinuses): painful red eye with proptosis, painful or restricted eye movements, reduced acuity and systemic upset. Sight- and life-threatening.", "B": "Differentiate from preseptal (periorbital) cellulitis - orbital cellulitis has proptosis, painful or limited eye movements and reduced vision/colour vision; preseptal does not.", "C": "Admit as an emergency for IV broad-spectrum antibiotics per local policy.", "D": "Arrange an urgent CT of the orbits, sinuses and brain to assess extent and detect an abscess.", "E": "Involve ophthalmology and ENT urgently.", "F": "Surgical drainage of an orbital or subperiosteal abscess (or the sinuses) if there is an abscess or no response to antibiotics.", "G": "Monitor visual acuity and colour vision closely, and watch for cavernous sinus thrombosis, meningitis or intracranial abscess."}}, cluster: "Orbital infection", name: "Orbital cellulitis", keyFacts: "A sight- and life-threatening infection of the orbital tissues behind the septum; an emergency.", epidemiology: "Commoner in children; usually arises from the ethmoid sinuses.", aetiology: "Most often spread from sinusitis (especially ethmoidal); Streptococcus, Staphylococcus, Haemophilus.", pathophysiology: "Infection behind the orbital septum involves the orbital fat and muscles, raising orbital pressure and risking optic-nerve damage and intracranial spread (cavernous sinus thrombosis, abscess).", presentation: "A painful red swollen eye with PROPTOSIS, painful and restricted eye movements (ophthalmoplegia), reduced vision or colour vision, and systemic upset.", investigations: "Urgent CT of the orbits and sinuses; bloods and blood cultures; ophthalmology and ENT review.", treatment: "Emergency admission and IV antibiotics; surgical drainage of any abscess; monitor the optic nerve closely." },
      { id: "eye_acute_glaucoma", management: {"source": "Ophthalmic emergency", "def": "A[\"Acute angle-closure glaucoma\"]:::start --> B[\"Emergency same-day ophthalmology referral\"]:::danger\nB --> C[\"Lie flat, analgesia and antiemetic\"]:::good\nC --> D[\"Lower pressure: pilocarpine + acetazolamide + topical\"]:::good\nD --> E[\"Reassess intraocular pressure\"]:::process\nE --> F[\"Definitive: laser peripheral iridotomy (both eyes)\"]:::good\nA --> G[\"Avoid mydriatics / dilating drops\"]:::warn", "tips": {"A": "A sudden rise in intraocular pressure from a blocked drainage angle: a painful red eye, blurred vision, haloes, a fixed mid-dilated oval pupil, nausea and vomiting. Sight-threatening.", "B": "Refer for same-day ophthalmology assessment immediately - vision loss can be rapid.", "C": "Lie the patient flat (helps the lens fall back) and give analgesia and an antiemetic.", "D": "Start pressure-lowering treatment as directed by ophthalmology: pilocarpine drops (constrict the pupil to open the angle), IV/oral acetazolamide, and topical agents (beta-blocker, alpha-agonist, steroid).", "E": "Monitor the intraocular pressure response.", "F": "Definitive treatment is laser peripheral iridotomy to relieve the block; treat the fellow eye prophylactically.", "G": "Avoid pupil-dilating drugs (mydriatics/anticholinergics), which can precipitate or worsen the attack."}}, cluster: "Glaucoma", name: "Acute angle-closure glaucoma", keyFacts: "A sudden rise in intraocular pressure from a blocked drainage angle; an emergency that threatens sight.", epidemiology: "Commoner in older, long-sighted (hypermetropic) people and in East Asians.", aetiology: "A shallow anterior chamber that closes the drainage angle, sometimes precipitated by dim light or dilating drops.", pathophysiology: "Closure of the iridocorneal angle blocks aqueous drainage, so pressure rises rapidly and threatens the optic nerve.", presentation: "Sudden painful red eye, haloes, reduced vision, fixed mid-dilated pupil, hard eye, vomiting.", investigations: "Intraocular pressure, urgent ophthalmology assessment.", treatment: "Emergency: lower pressure (acetazolamide, pilocarpine, beta-blocker) then laser iridotomy." },
      { id: "eye_chronic_glaucoma", management: {"def": "A[\"Chronic open-angle glaucoma\"]:::start --> B[\"Confirm: raised IOP, disc cupping, field loss\"]:::process\nB --> C[\"First-line: prostaglandin analogue drops (latanoprost)\"]:::good\nC -- \"target IOP not reached\" --> D[\"Add beta-blocker, alpha-agonist or CAI drops\"]:::good\nD -- \"inadequate or intolerant\" --> E[\"Laser trabeculoplasty\"]:::good\nE -- \"still uncontrolled\" --> F[\"Trabeculectomy (surgery)\"]:::warn\nA --> G[\"Lifelong monitoring of pressure, discs and fields\"]:::process", "tips": {"A": "A chronic optic neuropathy with an open drainage angle, usually with raised intraocular pressure: painless, gradual peripheral then tunnel vision loss, often found on screening; irreversible.", "B": "Diagnosis rests on raised intraocular pressure (though it can be normal-tension), optic disc cupping (increased cup-to-disc ratio) and characteristic visual field loss.", "C": "NICE first-line: a topical prostaglandin analogue (latanoprost) once daily - or offer 360-degree selective laser trabeculoplasty first in many patients.", "D": "If the target pressure is not reached, add or switch to a beta-blocker, alpha-agonist or carbonic anhydrase inhibitor drops, or combinations.", "E": "Selective laser trabeculoplasty is an option when drops are inadequate or not tolerated.", "F": "Surgery (trabeculectomy, often with an antimetabolite) for pressure uncontrolled despite drops and laser.", "G": "Glaucoma needs lifelong monitoring of intraocular pressure, optic discs and visual fields; adherence to drops is crucial."}}, cluster: "Glaucoma", name: "Chronic open-angle glaucoma", keyFacts: "A chronic optic neuropathy with insidious peripheral field loss, often symptomless until advanced.", epidemiology: "Common, with risk from age, family history and African ethnicity.", aetiology: "Raised intraocular pressure (though not always) damaging the optic nerve over time.", pathophysiology: "Impaired aqueous drainage through the trabecular meshwork raises pressure, causing progressive optic-nerve cupping and field loss.", presentation: "Insidious peripheral visual field loss, often asymptomatic until advanced.", investigations: "Tonometry, fundoscopy (cupping), visual fields, OCT.", treatment: "Prostaglandin analogue drops; laser or surgery; lifelong monitoring." },
      { id: "eye_cataract", cluster: "Lens", name: "Cataracts", keyFacts: "Clouding of the lens causing gradual painless blurring; the commonest cause of reversible blindness worldwide.", epidemiology: "Very common with age and the leading global cause of blindness.", aetiology: "Ageing predominantly; also diabetes, steroids, trauma and congenital causes.", pathophysiology: "Progressive opacification of the lens proteins scatters light, reducing visual clarity and contrast.", presentation: "Gradual painless blurring, glare, reduced colour, loss of red reflex.", investigations: "Slit-lamp examination, visual acuity.", treatment: "Phacoemulsification with intraocular lens when symptoms affect life." },
      { id: "eye_diabetic_retino", cluster: "Retina, macula & vitreous", name: "Diabetic retinopathy", keyFacts: "Diabetic microvascular damage to the retina; a leading cause of blindness in working-age adults.", epidemiology: "Common in long-standing diabetes; the UK runs a retinal screening programme.", aetiology: "Chronic hyperglycaemia, worsened by hypertension and the duration of diabetes.", pathophysiology: "Hyperglycaemia damages retinal capillaries, causing leakage and ischaemia that drives sight-threatening neovascularisation.", presentation: "Often asymptomatic; microaneurysms, haemorrhages, exudates; neovascularisation in proliferative disease.", investigations: "Retinal screening photography, OCT.", treatment: "Optimise glucose and BP; laser photocoagulation, anti-VEGF for maculopathy/proliferative disease." },
      { id: "eye_amd", cluster: "Retina, macula & vitreous", name: "Age-related macular degeneration", keyFacts: "Degeneration of the central retina (macula) causing central vision loss, in dry and wet forms.", epidemiology: "The leading cause of blindness in the elderly in the developed world.", aetiology: "Age, smoking, genetics and cardiovascular risk factors.", pathophysiology: "Drusen and macular degeneration (dry), or abnormal leaky neovascularisation (wet), progressively destroy central vision.", presentation: "Central vision loss and distortion; dry (gradual) or wet (rapid with metamorphopsia).", investigations: "Amsler grid, OCT, fundoscopy (drusen).", treatment: "Anti-VEGF injections for wet AMD; supplements and lifestyle for dry; urgent referral for wet." },
      { id: "eye_pvd", cluster: "Retina, macula & vitreous", name: "Posterior vitreous detachment", keyFacts: "Age-related separation of the vitreous gel from the retina causing floaters and flashes; usually benign but can cause a retinal tear.", epidemiology: "Very common with age and in myopia.", aetiology: "Age-related liquefaction and shrinkage of the vitreous; earlier in myopia and after cataract surgery or trauma.", pathophysiology: "The vitreous gel separates from the retina, and traction at points of adhesion can tear the retina, risking detachment.", presentation: "Sudden floaters and flashes (photopsia) with otherwise preserved vision and no field defect (unlike retinal detachment); a Weiss ring may be seen.", investigations: "Dilated fundoscopy to exclude a retinal tear or detachment.", treatment: "Reassurance once a tear is excluded; symptoms settle; safety-net to return urgently if a curtain, a shower of floaters or worsening flashes develop." },
      { id: "eye_retinal_detach", cluster: "Retina, macula & vitreous", name: "Retinal detachment", keyFacts: "Separation of the retina from its underlying layer causing painless flashes, floaters and a visual curtain.", epidemiology: "Uncommon but more frequent with myopia, age and after cataract surgery.", aetiology: "A retinal tear (often with posterior vitreous detachment), trauma, or traction in diabetic disease.", pathophysiology: "Fluid passes through a retinal break and lifts the retina off the pigment epithelium, depriving it of nutrition.", presentation: "Sudden floaters, flashes and a curtain over the vision; painless.", investigations: "Urgent fundoscopy/ophthalmology.", treatment: "Urgent surgical reattachment; time-critical to preserve vision." },
      { id: "eye_crao", cluster: "Retinal vascular occlusions", name: "Central retinal artery occlusion (CRAO)", keyFacts: "Sudden painless monocular blindness from occlusion of the central retinal artery; an emergency.", epidemiology: "Uncommon, mainly in older people with vascular disease.", aetiology: "Embolism from the carotid or heart, or, importantly, giant cell arteritis.", pathophysiology: "Arterial occlusion causes acute retinal ischaemia, seen as a pale retina with a cherry-red spot at the fovea.", presentation: "Sudden painless monocular vision loss; pale retina with cherry-red spot, RAPD.", investigations: "Urgent assessment; investigate emboli and giant cell arteritis.", treatment: "Emergency referral; ocular massage and pressure-lowering; treat vascular cause." },
      { id: "eye_brao", cluster: "Retinal vascular occlusions", name: "Branch retinal artery occlusion (BRAO)", keyFacts: "Occlusion of a branch retinal artery causing sudden, painless, sectoral visual field loss; like CRAO but localised.", epidemiology: "Uncommon, mainly in older people with vascular disease.", aetiology: "Embolism (carotid or cardiac) or giant cell arteritis; the same risk factors as central retinal artery occlusion.", pathophysiology: "Occlusion of a retinal arterial branch causes localised retinal ischaemia in that branch's territory.", presentation: "Sudden painless loss of part of the visual field in one eye; fundoscopy shows a wedge of retinal pallor along the affected branch, sometimes with a visible embolus.", investigations: "Fundoscopy; investigate the embolic source (carotid Doppler, ECG, echocardiogram) and exclude giant cell arteritis (ESR/CRP).", treatment: "Treat the cause and vascular risk factors; exclude and treat giant cell arteritis urgently; ophthalmology referral." },
      { id: "eye_crvo", cluster: "Retinal vascular occlusions", name: "Central retinal vein occlusion (CRVO)", keyFacts: "Blockage of the central retinal vein causing sudden, painless, usually moderate visual loss with widespread retinal haemorrhages.", epidemiology: "Commoner in older people with hypertension, diabetes, glaucoma and hyperviscosity.", aetiology: "Thrombosis of the central retinal vein; risk from hypertension, diabetes, raised intraocular pressure and hyperviscosity.", pathophysiology: "Venous occlusion raises retinal capillary pressure, causing haemorrhage, oedema and ischaemia that can drive neovascularisation.", presentation: "Sudden painless visual loss; fundoscopy shows widespread flame haemorrhages, dilated tortuous veins, cotton-wool spots and disc swelling (a stormy-sunset fundus).", investigations: "Fundoscopy and OCT; check blood pressure, glucose and intraocular pressure; bloods for risk factors.", treatment: "Manage risk factors; anti-VEGF (or steroid) injections for macular oedema; laser for neovascular complications; monitor for neovascular glaucoma." },
      { id: "eye_brvo", cluster: "Retinal vascular occlusions", name: "Branch retinal vein occlusion (BRVO)", keyFacts: "Occlusion of a branch retinal vein, usually at an arteriovenous crossing, causing sectoral haemorrhages and variable visual loss.", epidemiology: "Commoner than CRVO; associated with hypertension and atherosclerosis.", aetiology: "Thrombosis where a thickened artery compresses the vein at an arteriovenous crossing; hypertension is the key risk factor.", pathophysiology: "Occlusion of a venous branch causes haemorrhage and oedema confined to that branch's drainage area.", presentation: "Painless blurring or a partial field defect; fundoscopy shows haemorrhages and dilated veins in a sector of the retina, respecting the horizontal midline.", investigations: "Fundoscopy and OCT; check blood pressure and cardiovascular risk factors.", treatment: "Control blood pressure and risk factors; anti-VEGF for macular oedema; laser for neovascularisation; monitor." },
      { id: "eye_optic_neuritis", cluster: "Neuro-ophthalmology", name: "Optic neuritis", keyFacts: "Inflammation of the optic nerve causing subacute painful visual loss with reduced colour vision.", epidemiology: "Typically affects young adults and is an important association of multiple sclerosis.", aetiology: "Often demyelinating (multiple sclerosis); also infective and other inflammatory causes.", pathophysiology: "Inflammatory demyelination of the optic nerve impairs conduction, causing visual loss and a relative afferent pupillary defect.", presentation: "Subacute painful monocular vision loss with reduced colour vision and RAPD; MS association.", investigations: "Visual acuity, fundoscopy, MRI.", treatment: "Often recovers; steroids may speed recovery; assess for MS." },
      { id: "eye_holmes_adie", cluster: "Neuro-ophthalmology", name: "Holmes-Adie syndrome", keyFacts: "A benign cause of a dilated, poorly reactive (tonic) pupil, classically in a young woman; with absent reflexes it is the Holmes-Adie syndrome.", epidemiology: "Uncommon; typically young women.", aetiology: "Damage to the postganglionic parasympathetic supply (ciliary ganglion), often post-viral; the cause is usually unknown.", pathophysiology: "Denervation of the iris sphincter and ciliary muscle gives a tonically dilated pupil that constricts slowly, with denervation supersensitivity.", presentation: "A unilateral dilated pupil that reacts poorly to light but slowly to accommodation (light-near dissociation); with absent ankle and knee reflexes it is Holmes-Adie syndrome.", investigations: "Clinical; the pupil constricts to dilute (0.1%) pilocarpine, showing denervation supersensitivity.", treatment: "Reassurance, as it is benign; no specific treatment is needed; pilocarpine for cosmesis if desired." },
    ],
  },
  {
    id: "infectious",
    name: "Infectious Diseases",
    icon: "🦠",
    conditions: [
      { id: "id_sepsis", management: {"def": "A[\"Suspected sepsis\"]:::start --> B[\"Screen: NEWS2 and risk criteria\"]:::process\nB --> C{\"High-risk / red-flag features?\"}:::decision\nC -- \"yes\" --> D[\"Sepsis Six within 1 hour\"]:::danger\nD --> E[\"Give 3: oxygen, IV antibiotics, IV fluids\"]:::good\nD --> F[\"Take 3: cultures, lactate, urine output\"]:::good\nE --> G[\"Reassess; senior review; escalate\"]:::warn\nF --> G", "tips": {"A": "Life-threatening organ dysfunction from a dysregulated response to infection; treat as a time-critical emergency.", "B": "Use a structured screen (e.g. NEWS2) and stratify with the NICE high/moderate/low-risk criteria.", "C": "Red-flag features (new confusion, high NEWS2, hypotension, marked tachypnoea, mottling, lactate 2+) trigger immediate action.", "D": "Deliver the Sepsis Six within one hour.", "E": "Give three: high-flow oxygen (target saturations), IV broad-spectrum antibiotics, and an IV balanced-crystalloid fluid bolus.", "F": "Take three: blood cultures (before antibiotics if no delay), serum lactate, and monitor urine output/fluid balance.", "G": "Reassess after the fluid bolus, get senior/critical-care review, and escalate (vasopressors, source control) if not responding."}}, cluster: "Sepsis & bacteraemia", name: "Sepsis", keyFacts: "Life-threatening organ dysfunction from a dysregulated response to infection; treat with the Sepsis Six within the hour.", epidemiology: "Common and a major cause of hospital death; higher risk at the extremes of age and with immunosuppression.", aetiology: "Any infection (commonly respiratory, urinary, abdominal or skin) by bacteria, viruses or fungi.", pathophysiology: "An overwhelming inflammatory response causes vasodilation, capillary leak and microvascular thrombosis, leading to hypoperfusion and organ failure.", presentation: "Life-threatening organ dysfunction from infection: fever, tachycardia, hypotension, confusion.", investigations: "Sepsis screen, lactate, cultures, NEWS2.", treatment: "Sepsis Six within the hour: oxygen, cultures, IV antibiotics, fluids, lactate, urine output." },
      { id: "id_gas", cluster: "Sepsis & bacteraemia", name: "Group A Streptococcus", keyFacts: "Streptococcus pyogenes causes disease from sore throat to invasive sepsis and toxic shock.", epidemiology: "Very common; invasive disease (iGAS) has risen recently.", aetiology: "Streptococcus pyogenes, a beta-haemolytic Lancefield group A Gram-positive coccus.", pathophysiology: "Surface proteins and exotoxins drive local infection and, via superantigens, toxic shock; antibody cross-reactivity causes rheumatic fever and glomerulonephritis.", presentation: "Pharyngitis, scarlet fever, impetigo, erysipelas, cellulitis, necrotising fasciitis and toxic shock; later rheumatic fever or post-streptococcal glomerulonephritis.", investigations: "Throat swab and culture, rapid antigen, ASO titre; cultures and lactate if invasive.", treatment: "Penicillin (add clindamycin to suppress toxin in invasive disease); supportive care for sepsis." },
      { id: "id_staph_aureus", cluster: "Sepsis & bacteraemia", name: "Staphylococcus aureus", keyFacts: "A versatile Gram-positive pathogen causing skin, bone, lung and bloodstream infection; MRSA is resistant.", epidemiology: "A common coloniser of skin and nose; MRSA is an important hospital and community pathogen.", aetiology: "Staphylococcus aureus, a coagulase-positive Gram-positive coccus in clusters.", pathophysiology: "Toxins and enzymes cause abscesses and toxin-mediated syndromes, while bacteraemia seeds heart valves, bone and joints.", presentation: "Boils and abscesses, cellulitis, wound infection, osteomyelitis, septic arthritis, endocarditis and pneumonia; toxin syndromes (toxic shock, scalded skin).", investigations: "Cultures (wound, blood) with sensitivities and MRSA screen; echocardiography if bacteraemic.", treatment: "Flucloxacillin for sensitive strains, vancomycin for MRSA; drain abscesses; prolonged IV antibiotics for endocarditis." },
      { id: "id_pseudomonas", cluster: "Sepsis & bacteraemia", name: "Pseudomonas aeruginosa", keyFacts: "An opportunistic Gram-negative pathogen of the immunocompromised, burns and cystic fibrosis; often multi-resistant.", epidemiology: "A common cause of hospital-acquired and device-related infection.", aetiology: "Pseudomonas aeruginosa, a Gram-negative aerobic rod that thrives in moist environments.", pathophysiology: "Biofilm formation and multiple resistance mechanisms let it colonise and infect compromised hosts.", presentation: "Hospital pneumonia, infected burns and ulcers, otitis externa, urinary infection and chronic colonisation in cystic fibrosis; green pus.", investigations: "Culture and sensitivities (often resistant); identify the source.", treatment: "Anti-pseudomonal antibiotics (piperacillin-tazobactam, ceftazidime, ciprofloxacin), sometimes dual therapy; remove infected devices." },
      { id: "id_meningitis", management: {"def": "A[\"Suspected bacterial meningitis\"]:::start --> B{\"Non-blanching rash or shock?\"}:::decision\nB -- \"meningococcal septicaemia\" --> C[\"Immediate benzylpenicillin, urgent transfer\"]:::danger\nB -- \"stable\" --> D[\"Blood cultures, then IV ceftriaxone\"]:::danger\nD --> E[\"Lumbar puncture if no contraindication\"]:::good\nE --> F[\"Dexamethasone (+ amoxicillin if Listeria risk)\"]:::good\nF --> G[\"Notify public health, contact prophylaxis\"]:::process\nD -- \"reduced GCS / focal signs\" --> H[\"CT head before LP; do not delay antibiotics\"]:::warn", "tips": {"A": "Fever, headache, neck stiffness, photophobia and altered consciousness (non-specific in infants); a medical emergency - do not delay antibiotics.", "B": "Assess for meningococcal septicaemia/shock, which changes the first step.", "C": "In the community with a non-blanching rash/suspected meningococcal disease, give immediate IM or IV benzylpenicillin and arrange emergency transfer.", "D": "In hospital: take blood cultures then give IV ceftriaxone (or cefotaxime) without waiting for the lumbar puncture.", "E": "Lumbar puncture for CSF cell count, protein, glucose, culture and PCR, unless contraindicated.", "F": "Give dexamethasone with or just before antibiotics (reduces complications); add amoxicillin to cover Listeria if over 60, immunocompromised, pregnant or neonatal.", "G": "Bacterial meningitis is notifiable - inform public health and offer ciprofloxacin prophylaxis to close contacts.", "H": "If reduced GCS, focal neurology or papilloedema, get a CT head before LP - but never delay antibiotics for imaging."}}, cluster: "CNS infection", name: "Bacterial meningitis", keyFacts: "Bacterial infection of the meninges; a notifiable medical emergency with high mortality.", epidemiology: "Peaks in infants and young adults; vaccination (Men B/C, pneumococcal, Hib) has cut incidence.", aetiology: "Neisseria meningitidis and Streptococcus pneumoniae; Hib in the unvaccinated; Listeria and group B Strep at the extremes of age.", pathophysiology: "Bacteria invade the subarachnoid space and provoke intense inflammation, raising intracranial pressure; meningococcal sepsis causes the non-blanching rash.", presentation: "Fever, severe headache, neck stiffness, photophobia, Kernig's sign; non-blanching purpuric rash in meningococcal sepsis.", investigations: "Blood cultures and PCR, lumbar puncture (turbid CSF: high neutrophils, high protein, low glucose); CT first if focal signs or reduced GCS.", treatment: "Community: IM benzylpenicillin then transfer; hospital: IV ceftriaxone (add amoxicillin for Listeria) plus dexamethasone; notify UKHSA and give contact prophylaxis." },
      { id: "id_meningitis_viral", cluster: "CNS infection", name: "Viral meningitis", keyFacts: "The commonest and usually self-limiting meningitis; far milder than the bacterial form.", epidemiology: "More common than bacterial meningitis, with summer peaks.", aetiology: "Enteroviruses (coxsackie, echovirus) most often; also herpes simplex and mumps.", pathophysiology: "Viral infection inflames the meninges without the severe vascular injury of bacterial disease.", presentation: "Headache, fever, photophobia and neck stiffness, but usually well and without a rash.", investigations: "Lumbar puncture (clear CSF: lymphocytes, normal glucose, mildly raised protein), viral PCR.", treatment: "Supportive and usually self-limiting; aciclovir if herpes simplex is suspected." },
      { id: "id_meningitis_tb", cluster: "CNS infection", name: "Tuberculous meningitis", keyFacts: "A subacute meningitis from Mycobacterium tuberculosis with high morbidity if treatment is delayed.", epidemiology: "Commoner in endemic areas, the immunosuppressed and the very young.", aetiology: "Mycobacterium tuberculosis, usually by haematogenous spread.", pathophysiology: "A basal granulomatous meningitis can entrap cranial nerves and obstruct CSF flow, causing hydrocephalus.", presentation: "Insidious headache, fever and malaise over weeks, with cranial nerve palsies and confusion.", investigations: "Lumbar puncture (clear or turbid CSF: lymphocytes, very high protein, low glucose), TB PCR and culture, imaging.", treatment: "Prolonged anti-tuberculous therapy (RIPE) with corticosteroids; manage hydrocephalus." },
      { id: "id_meningitis_crypto", cluster: "CNS infection", name: "Cryptococcal meningitis", keyFacts: "A fungal meningitis, classically in advanced HIV, that raises intracranial pressure.", epidemiology: "Mainly in HIV with a low CD4 count and other immunosuppression.", aetiology: "Cryptococcus neoformans, an encapsulated yeast acquired by inhalation.", pathophysiology: "The yeast disseminates to the meninges, where its capsule blunts the immune response and raises intracranial pressure.", presentation: "Subacute headache, fever and confusion, often with markedly raised intracranial pressure.", investigations: "Lumbar puncture with a high opening pressure, India ink stain and cryptococcal antigen (CrAg); CD4 count.", treatment: "Amphotericin B with flucytosine then fluconazole; repeated LPs to control pressure; start or optimise antiretrovirals." },
      { id: "id_influenza", cluster: "Respiratory infection", name: "Influenza", keyFacts: "An acute viral respiratory illness with abrupt fever and myalgia; vaccination protects at-risk groups.", epidemiology: "Causes seasonal winter epidemics, with periodic pandemics.", aetiology: "Influenza A and B viruses, spread by respiratory droplets; antigenic change drives epidemics.", pathophysiology: "The virus infects the respiratory epithelium, provoking a systemic inflammatory response and risking secondary bacterial pneumonia.", presentation: "Abrupt fever, myalgia, headache, dry cough, fatigue during winter season.", investigations: "Clinical; PCR if needed; assess complications.", treatment: "Supportive; antivirals (oseltamivir) for at-risk groups; annual vaccination." },
      { id: "id_covid", cluster: "Respiratory infection", name: "COVID-19", keyFacts: "A respiratory illness from SARS-CoV-2 ranging from mild coryza to severe pneumonia.", epidemiology: "Caused a global pandemic; severe disease is commoner with age and comorbidity.", aetiology: "The SARS-CoV-2 coronavirus, spread by respiratory droplets and aerosols.", pathophysiology: "The virus enters cells via the ACE2 receptor; in severe cases an excessive immune response causes pneumonitis and thrombosis.", presentation: "Fever, cough, loss of smell/taste, breathlessness; range from mild to severe.", investigations: "PCR/lateral flow, oxygen saturations, CXR if severe.", treatment: "Supportive; antivirals/steroids for at-risk or hospitalised; vaccination and isolation advice." },
      { id: "id_legionella", cluster: "Respiratory infection", name: "Legionnaires' disease", keyFacts: "An atypical pneumonia from contaminated water systems, with hyponatraemia and confusion.", epidemiology: "Outbreaks linked to air conditioning, cooling towers and hotels or travel.", aetiology: "Legionella pneumophila, inhaled from aerosolised contaminated water.", pathophysiology: "The intracellular bacterium infects alveolar macrophages, causing pneumonia and a systemic illness.", presentation: "Pneumonia with high fever, dry cough, confusion and diarrhoea; hyponatraemia and deranged liver enzymes.", investigations: "Urinary Legionella antigen, CXR, U&E (low sodium), LFTs.", treatment: "Macrolide (clarithromycin) or a fluoroquinolone; supportive care; notify." },
      { id: "id_epiglottitis", cluster: "Respiratory infection", name: "Epiglottitis", keyFacts: "Life-threatening inflammation of the epiglottis that can obstruct the airway; do not examine the throat.", epidemiology: "Now rare in children since Hib vaccination; seen in the unvaccinated and in adults.", aetiology: "Classically Haemophilus influenzae type b; also other bacteria.", pathophysiology: "Bacterial infection causes rapid swelling of the epiglottis and supraglottis, threatening airway obstruction.", presentation: "Rapid high fever, sore throat, drooling, muffled (hot-potato) voice, stridor and a child sitting forward (tripod); do NOT examine the throat or lie the child down.", investigations: "Clinical; secure the airway first; lateral neck X-ray (thumb sign) only if stable.", treatment: "Urgent senior anaesthetic and ENT airway management, then IV ceftriaxone; keep the child calm; Hib vaccination prevents it." },
      { id: "id_tb", cluster: "Respiratory infection", name: "Tuberculosis", keyFacts: "A chronic mycobacterial infection, usually pulmonary, treated with prolonged combination therapy.", epidemiology: "A leading global infectious killer; higher risk with HIV, deprivation and migration from endemic areas.", aetiology: "Mycobacterium tuberculosis, spread by respiratory droplets; latent infection can reactivate.", pathophysiology: "Inhaled bacilli form granulomas; reactivation or progression causes caseating tissue destruction, classically in the lung apices.", presentation: "Chronic cough, haemoptysis, fever, night sweats and weight loss; extrapulmonary disease (lymph node, spine, meninges).", investigations: "CXR, sputum smear, culture and PCR (acid-fast bacilli); interferon-gamma release assay or Mantoux for latent disease.", treatment: "Six months of RIPE (rifampicin, isoniazid, pyrazinamide, ethambutol), ideally directly observed; notify and screen contacts." },
      { id: "id_gastroenteritis", cluster: "Gastrointestinal infection", name: "Gastroenteritis", keyFacts: "Acute diarrhoea and vomiting, usually viral and self-limiting; the priority is hydration.", epidemiology: "Extremely common worldwide, with norovirus and rotavirus frequent culprits.", aetiology: "Viruses (norovirus, rotavirus), bacteria (Campylobacter, Salmonella, E. coli) and preformed toxins.", pathophysiology: "Pathogens or their toxins disrupt the intestinal mucosa and secretion, causing fluid loss through diarrhoea and vomiting.", presentation: "Acute diarrhoea and vomiting, cramps; usually viral and self-limiting.", investigations: "Usually clinical; stool culture if blood, travel, or prolonged.", treatment: "Oral rehydration; safety-net for dehydration; hygiene and exclusion advice; antibiotics rarely needed." },
      { id: "id_salmonella", cluster: "Gastrointestinal infection", name: "Salmonella (non-typhoidal)", keyFacts: "A common cause of food-borne gastroenteritis; usually self-limiting but can become invasive.", epidemiology: "Common, from contaminated poultry, eggs and meat.", aetiology: "Non-typhoidal Salmonella species, Gram-negative bacilli.", pathophysiology: "The organism invades the intestinal mucosa causing inflammation and, occasionally, bacteraemia.", presentation: "Diarrhoea (sometimes bloody), fever, vomiting and cramps a day or so after exposure.", investigations: "Stool culture; blood cultures if systemically unwell.", treatment: "Rehydration; antibiotics only for severe or invasive disease or the vulnerable; notify as food poisoning." },
      { id: "id_typhoid", cluster: "Gastrointestinal infection", name: "Typhoid (enteric) fever", keyFacts: "A systemic infection from Salmonella Typhi presenting with fever and abdominal symptoms after travel.", epidemiology: "Acquired in endemic areas (especially South Asia); presents in returning travellers.", aetiology: "Salmonella enterica serovar Typhi (and Paratyphi), spread faecal-oral.", pathophysiology: "The organism is taken up by gut lymphoid tissue and disseminates, causing prolonged bacteraemia and a systemic illness.", presentation: "Stepwise fever, headache, relative bradycardia, rose spots, abdominal pain, constipation then diarrhoea; risk of bowel perforation.", investigations: "Blood cultures (best early), stool and urine culture, FBC.", treatment: "Antibiotics guided by sensitivities (azithromycin or ceftriaxone; resistance common); vaccination for travel." },
      { id: "id_cdiff", management: {"def": "A[\"Clostridioides difficile infection\"]:::start --> B[\"Stop the causative antibiotic and PPI if possible\"]:::good\nB --> C[\"Isolate, hand hygiene with soap and water\"]:::warn\nC --> D[\"First-line: oral vancomycin (10 days)\"]:::good\nD -- \"recurrence\" --> E[\"Oral fidaxomicin\"]:::good\nE -- \"further recurrence\" --> F[\"Consider faecal microbiota transplant\"]:::good\nA -- \"toxic megacolon, perforation, ileus\" --> G[\"Life-threatening: add IV metronidazole, surgery review\"]:::danger", "tips": {"A": "Antibiotic-associated colitis from C. difficile toxin (classically after clindamycin, cephalosporins, co-amoxiclav or quinolones): watery diarrhoea, abdominal pain and a raised white cell count.", "B": "Stop the precipitating antibiotic (and, where possible, PPIs) - this alone may resolve mild cases.", "C": "Isolate the patient in a side room with barrier nursing; use soap and water for hand hygiene (alcohol gel does not kill spores) and chlorine-based cleaning.", "D": "First-line treatment (NICE) is oral vancomycin for 10 days.", "E": "For a first recurrence, use oral fidaxomicin (or vancomycin).", "F": "For multiple recurrences, consider a faecal microbiota transplant.", "G": "Life-threatening disease (toxic megacolon, ileus, perforation, sepsis): oral vancomycin plus IV metronidazole and urgent surgical review (colectomy)."}}, cluster: "Gastrointestinal infection", name: "Clostridioides difficile", keyFacts: "Antibiotic-associated colitis from toxin-producing C. difficile; can progress to toxic megacolon.", epidemiology: "A major healthcare-associated infection, especially in the elderly on antibiotics.", aetiology: "C. difficile overgrowth after antibiotics (classically clindamycin, cephalosporins, ciprofloxacin, co-amoxiclav) disrupt gut flora.", pathophysiology: "Toxins A and B damage the colonic mucosa, producing inflammation and pseudomembranes.", presentation: "Watery diarrhoea, fever, abdominal pain and raised white cells after antibiotics; severe disease causes toxic megacolon.", investigations: "Stool toxin and PCR, FBC, lactate; abdominal imaging if severe.", treatment: "Stop the causative antibiotic and isolate; oral vancomycin (or fidaxomicin); faecal transplant for recurrence; surgery for toxic megacolon." },
      { id: "id_giardiasis", cluster: "Gastrointestinal infection", name: "Giardiasis", keyFacts: "A protozoal cause of persistent, malabsorptive diarrhoea after travel or contaminated water.", epidemiology: "Common worldwide; linked to travel, contaminated water and nurseries.", aetiology: "Giardia lamblia, ingested as cysts from contaminated water or food.", pathophysiology: "The protozoan coats the small-bowel mucosa, impairing absorption and causing fatty, foul-smelling stool.", presentation: "Prolonged watery then greasy diarrhoea, bloating, flatulence, cramps and weight loss; usually non-bloody.", investigations: "Stool microscopy for cysts (or antigen and PCR); duodenal aspirate if needed.", treatment: "Metronidazole or tinidazole; hygiene and water precautions." },
      { id: "id_sbp", management: { def: "A[\"Cirrhosis with ascites - fever, abdominal pain, encephalopathy or unexplained deterioration\"]:::start --> B[\"Diagnostic paracentesis BEFORE antibiotics\"]:::process\nB --> C[\"Ascitic neutrophil count, culture into blood culture bottles at the bedside, protein and albumin\"]:::process\nC --> D{\"Ascitic neutrophil count 250 cells per cubic mm or more\"}:::decision\nD -- \"no\" --> E[\"SBP excluded - seek another source of deterioration\"]:::good\nE --> F[\"Consider PRIMARY prophylaxis only if high risk\"]:::warn\nD -- \"yes\" --> G[\"Diagnose SBP and start treatment immediately - do not wait for culture\"]:::danger\nG --> H{\"Features suggesting SECONDARY peritonitis\"}:::decision\nH -- \"multiple organisms or no response\" --> I[\"Urgent CT abdomen and surgical review\"]:::danger\nH -- \"no\" --> J[\"IV cefotaxime or ceftriaxone for 5 days\"]:::good\nJ --> K[\"IV albumin 1.5 g per kg on day 1 and 1 g per kg on day 3\"]:::good\nK --> L[\"Withhold non-selective beta-blockers and nephrotoxic drugs\"]:::warn\nL --> M[\"Repeat paracentesis at 48 hours if not improving\"]:::warn\nM --> N[\"On recovery, secondary prophylaxis with ciprofloxacin\"]:::good\nN --> O[\"Assess for liver transplantation\"]:::good", tips: { A: "SBP is infection of ascitic fluid with no surgically treatable intra-abdominal source. The presentation is often SUBTLE - up to a third have no fever or abdominal pain, and the only clue may be new encephalopathy, worsening renal function or unexplained decline. Suspect it in any decompensating patient with ascites.", B: "Perform a diagnostic tap in every patient admitted with ascites and in anyone with ascites who deteriorates. Taking it before antibiotics matters because a single dose sharply reduces culture yield. Coagulopathy is not a contraindication and routine fresh frozen plasma is not required.", C: "Inoculate at least 10 mL into blood culture bottles at the bedside - this raises the yield from about 50% to 80%. Ascitic protein identifies who needs prophylaxis later, and the serum-ascites albumin gradient (11 g per litre or more) confirms portal hypertension as the cause.", D: "The neutrophil count is the diagnosis - not the culture, which is negative in roughly 40% of true cases (culture-negative neutrocytic ascites, treated identically). If the tap is bloody, subtract 1 neutrophil for every 250 red cells.", E: "If the count is below the threshold, look elsewhere - urinary tract infection, chest sepsis, gastrointestinal bleeding and hepatocellular carcinoma all decompensate cirrhosis.", F: "NICE NG50 was UPDATED and no longer recommends routine prophylaxis. Do not routinely offer antibiotics to prevent SBP - reserve them for those at high risk from severe liver disease, for example ascitic protein 15 g per litre or less, a Child-Pugh score above 9 or a MELD score above 16. Norfloxacin has been withdrawn in the UK, so ciprofloxacin is the agent used.", G: "Start antibiotics on the neutrophil count alone. Mortality rises with every hour of delay, and waiting for culture adds 48 hours. Usual organisms are gut-derived Gram-negatives (E. coli, Klebsiella) and streptococci, with resistant and Gram-positive organisms increasingly common after prophylaxis or hospital exposure.", H: "Secondary bacterial peritonitis is perforation or an abscess and needs surgery, not antibiotics alone. Suspect it with multiple organisms on culture, a very high ascitic protein, low ascitic glucose, a high LDH, or failure of the neutrophil count to fall on repeat tap.", I: "Do not delay imaging when the picture does not fit - treating a perforated viscus as SBP is fatal.", J: "A third-generation cephalosporin is standard, for 5 days (no better outcome from 10). Follow local microbiology policy, since many UK units use piperacillin-tazobactam where resistance or recent prophylaxis is a concern, and narrow the antibiotic once sensitivities return.", K: "Albumin is not optional - it is the intervention that changes mortality. Adding albumin to cefotaxime cut hepatorenal syndrome from 30% to 10% and mortality from 29% to 10%. The benefit is clearest with creatinine 88 micromol per litre or more, or bilirubin 68 micromol per litre or more.", L: "Non-selective beta-blockers worsen outcomes in SBP with hypotension by blunting cardiac output when systemic vasodilatation is already extreme. Stop NSAIDs, aminoglycosides and ACE inhibitors, and avoid large-volume paracentesis while the infection is active.", M: "A repeat tap at 48 hours should show the neutrophil count falling by at least 25%. If it has not, the antibiotic is wrong, the organism is resistant, or this is secondary peritonitis.", N: "Recurrence reaches about 70% within a year without prophylaxis, so everyone who survives an episode needs secondary prophylaxis - ciprofloxacin, continued until the ascites resolves or transplantation.", O: "An episode of SBP marks a decisive fall in prognosis - roughly 30 to 40% one-year survival - so it should trigger transplant assessment in anyone potentially eligible." }, source: "EASL / NICE NG50" }, complications: "Acute kidney injury and hepatorenal syndrome\nHepatic encephalopathy\nSepsis and septic shock\nRecurrence in around 70% within a year without prophylaxis\nMarks a decisive fall in prognosis - roughly 30 to 40% one-year survival", cluster: "Gastrointestinal infection", name: "Spontaneous bacterial peritonitis", keyFacts: "Infection of ascitic fluid in cirrhosis with no surgically treatable source, diagnosed on an ascitic neutrophil count of 250 cells per cubic mm or more.", epidemiology: "Affects around 10 to 30% of patients hospitalised with cirrhotic ascites; high mortality and a high recurrence rate.", aetiology: "Bacterial translocation from the gut in portal hypertension; usually a single organism, most often E. coli, Klebsiella or streptococci, with resistant and Gram-positive organisms increasingly common after prophylaxis.", pathophysiology: "Portal hypertension causes bowel wall oedema, bacterial overgrowth and translocation to mesenteric nodes and ascites; low ascitic protein means poor opsonic activity, so translocated bacteria are not cleared.", presentation: "Often subtle - fever, abdominal pain and tenderness, but up to a third have neither, and it may show only as new encephalopathy, worsening renal function or unexplained deterioration in a patient with ascites.", investigations: "Diagnostic paracentesis before antibiotics in every patient admitted with ascites; ascitic neutrophil count 250 cells per cubic mm or more is diagnostic; culture into blood culture bottles at the bedside (negative in about 40%); serum-ascites albumin gradient 11 g/L or more confirms portal hypertension.", treatment: "IV cefotaxime or ceftriaxone for 5 days per local policy, started on the neutrophil count alone; IV albumin 1.5 g/kg on day 1 and 1 g/kg on day 3 to prevent hepatorenal syndrome; withhold non-selective beta-blockers and nephrotoxics; secondary prophylaxis with ciprofloxacin on recovery; assess for transplantation." },
      { id: "id_hiv", cluster: "Sexually transmitted infection", name: "HIV", keyFacts: "A retroviral infection that destroys CD4 T-cells, causing progressive immunodeficiency and, untreated, AIDS.", epidemiology: "A global epidemic; in the UK higher in men who have sex with men and in migrants from endemic areas.", aetiology: "The human immunodeficiency virus, transmitted sexually, through blood and vertically.", pathophysiology: "The virus infects and depletes CD4 T-cells, progressively crippling cell-mediated immunity and allowing opportunistic infections and tumours.", presentation: "Seroconversion flu-like illness; later opportunistic infections; many asymptomatic for years.", investigations: "Fourth-generation antigen/antibody test, CD4 count, viral load.", treatment: "Lifelong antiretroviral therapy; partner notification; pre-/post-exposure prophylaxis for prevention." },
      { id: "id_syphilis", cluster: "Sexually transmitted infection", name: "Syphilis", keyFacts: "A sexually transmitted spirochaete infection progressing through primary, secondary, latent and tertiary stages.", epidemiology: "Rising incidence, especially in men who have sex with men; congenital syphilis is preventable.", aetiology: "Treponema pallidum, transmitted sexually or vertically.", pathophysiology: "The spirochaete disseminates early; an endarteritis underlies the gummas and the cardiovascular and neurological damage of late disease.", presentation: "Primary: painless chancre; secondary: rash (including palms and soles), condylomata lata; tertiary: gummas, aortitis and neurosyphilis (tabes dorsalis, Argyll Robertson pupil).", investigations: "Treponemal serology (EIA, TPPA) and non-treponemal titres (RPR/VDRL) for activity; dark-ground microscopy.", treatment: "Intramuscular benzylpenicillin; partner notification; screen for other STIs; warn of the Jarisch-Herxheimer reaction." },
      { id: "id_gonorrhoea", cluster: "Sexually transmitted infection", name: "Gonorrhoea", keyFacts: "A common STI causing urethral and cervical infection; antibiotic resistance is a growing problem.", epidemiology: "Common in young, sexually active people, with rising resistance.", aetiology: "Neisseria gonorrhoeae, a Gram-negative diplococcus.", pathophysiology: "The organism infects the columnar epithelium of the urethra, cervix, rectum, pharynx and conjunctiva.", presentation: "Purulent urethral or vaginal discharge and dysuria; often asymptomatic in women; can cause PID, epididymitis, disseminated infection and neonatal conjunctivitis.", investigations: "NAAT from the relevant site, plus culture for sensitivities before treatment.", treatment: "Intramuscular ceftriaxone; test of cure; partner notification; screen for other STIs." },
      { id: "id_measles", cluster: "Viral exanthems & herpesviruses", name: "Measles", keyFacts: "A highly contagious viral illness with fever, coryza and a rash; vaccine-preventable and notifiable.", epidemiology: "Resurging where MMR uptake has fallen; very high attack rate in the unvaccinated.", aetiology: "Measles virus (a morbillivirus), spread by respiratory droplets.", pathophysiology: "The virus infects respiratory epithelium and lymphoid tissue, causing a systemic illness and transient immunosuppression.", presentation: "Fever, cough, coryza, conjunctivitis and Koplik spots, then a descending maculopapular rash.", investigations: "Clinical; salivary or serum measles IgM and PCR; notify.", treatment: "Supportive, with vitamin A in children; isolate; manage complications (otitis media, pneumonia, rare encephalitis); MMR for prevention." },
      { id: "id_rubella", cluster: "Viral exanthems & herpesviruses", name: "Rubella", keyFacts: "A mild viral exanthem whose importance lies in devastating congenital infection in early pregnancy.", epidemiology: "Uncommon where MMR uptake is high.", aetiology: "Rubella virus (a togavirus), spread by respiratory droplets.", pathophysiology: "Maternal infection in the first trimester crosses the placenta and disrupts organogenesis.", presentation: "Mild fever with a fine maculopapular rash and tender suboccipital and postauricular lymphadenopathy; congenital rubella causes deafness, cataracts and cardiac defects.", investigations: "Rubella IgM and IgG and PCR; notify; check pregnant contacts.", treatment: "Supportive; prevent with MMR; keep away from pregnant women." },
      { id: "id_coxsackie", cluster: "Viral exanthems & herpesviruses", name: "Coxsackievirus", keyFacts: "An enterovirus causing hand, foot and mouth disease and herpangina, usually mild in children.", epidemiology: "Common in young children, with summer and autumn peaks.", aetiology: "Coxsackieviruses and other enteroviruses, spread faecal-oral and by droplets.", pathophysiology: "Enteroviral infection produces a vesicular enanthem and exanthem and, less often, myocarditis or meningitis.", presentation: "Fever with oral ulcers and vesicles on the hands and feet (hand, foot and mouth disease); herpangina; rarely myocarditis or pericarditis.", investigations: "Clinical; PCR if needed.", treatment: "Supportive (fluids, analgesia); self-limiting; hygiene advice." },
      { id: "id_molluscum", cluster: "Viral exanthems & herpesviruses", name: "Molluscum contagiosum", keyFacts: "A common poxvirus skin infection causing umbilicated papules; self-limiting in children.", epidemiology: "Common in children; in adults it can be sexually transmitted, and is extensive in HIV.", aetiology: "Molluscum contagiosum virus, a poxvirus spread by skin contact and fomites.", pathophysiology: "The virus infects keratinocytes, producing the characteristic dome-shaped umbilicated papules.", presentation: "Clusters of small, firm, pearly, umbilicated papules; widespread disease suggests immunosuppression.", investigations: "Clinical diagnosis.", treatment: "Usually none needed (resolves over months); avoid scratching and sharing; consider treatment if troublesome or sexually transmitted." },
      { id: "id_cmv", cluster: "Viral exanthems & herpesviruses", name: "Cytomegalovirus (CMV)", keyFacts: "A herpesvirus that is mild in the healthy but serious in the immunocompromised and the fetus.", epidemiology: "Very common; most people are infected by adulthood and carry it latently.", aetiology: "Human cytomegalovirus, transmitted by body fluids, transplant and vertically.", pathophysiology: "Latent virus reactivates when cell-mediated immunity wanes, causing end-organ disease; 'owl's eye' inclusion cells on histology.", presentation: "Healthy: a mild glandular-fever-like illness; immunocompromised: retinitis, colitis, pneumonitis, encephalitis; congenital: deafness and disability.", investigations: "CMV serology, PCR (viral load), tissue biopsy for inclusions.", treatment: "Ganciclovir or valganciclovir (foscarnet second line) for serious disease; reduce immunosuppression; the healthy need only supportive care." },
      { id: "id_ebv", cluster: "Viral exanthems & herpesviruses", name: "Epstein-Barr virus (EBV)", keyFacts: "The cause of infectious mononucleosis (glandular fever) and a driver of certain lymphomas.", epidemiology: "Extremely common; most people are infected by early adulthood.", aetiology: "Epstein-Barr virus, a herpesvirus spread in saliva (the 'kissing disease').", pathophysiology: "The virus infects B cells and lies latent, predisposing to Burkitt and other lymphomas and to nasopharyngeal carcinoma.", presentation: "Fever, exudative pharyngitis, posterior cervical lymphadenopathy, splenomegaly and fatigue; a rash if given amoxicillin.", investigations: "Monospot or heterophile antibody, EBV serology, FBC and film (atypical lymphocytes), LFTs.", treatment: "Supportive (rest, analgesia); avoid contact sport for several weeks (splenic rupture risk); avoid amoxicillin." },
      { id: "derm_shingles", cluster: "Viral exanthems & herpesviruses", name: "Herpes zoster (shingles)", keyFacts: "Reactivation of latent varicella-zoster virus causing a painful dermatomal rash; complications span the skin, nerves, eye and ear.", epidemiology: "Risk rises with age and immunosuppression; the shingles vaccine reduces incidence and post-herpetic neuralgia in older adults.", aetiology: "Reactivation of varicella-zoster virus dormant in a dorsal root or cranial nerve ganglion since chickenpox; triggered by ageing, stress and immunosuppression.", pathophysiology: "The virus reactivates and travels down a sensory nerve to the skin, producing prodromal pain then a vesicular rash confined to one dermatome, with nerve inflammation causing neuralgia.", presentation: "Dermatological: a painful unilateral vesicular rash in one dermatome that does not cross the midline. Neurological: prodromal and post-herpetic neuralgia, and rarely segmental motor weakness, myelitis or encephalitis. Ophthalmic (herpes zoster ophthalmicus): V1 involvement with a vesicle on the nose tip (Hutchinson's sign) threatening sight. Otic (Ramsay Hunt syndrome): facial nerve palsy with vesicles in the ear and loss of taste. Disseminated zoster in the immunocompromised.", investigations: "Usually clinical; viral PCR of vesicle fluid if uncertain; assess for eye and ear involvement and for immunosuppression.", treatment: "Oral antiviral (aciclovir, valaciclovir) within 72 hours, with analgesia and amitriptyline or gabapentin for neuralgia; urgent ophthalmology for ophthalmic zoster; specialist care and IV aciclovir for Ramsay Hunt, disseminated or immunocompromised disease." },
      { id: "id_malaria", management: {"def": "A[\"Malaria (fever in a returning traveller)\"]:::start --> B[\"Urgent blood films x3 (thick and thin) or RDT\"]:::process\nB --> C{\"Species and severity\"}:::decision\nC -- \"severe / falciparum red flags\" --> D[\"IV artesunate, admit to HDU/ICU\"]:::danger\nC -- \"uncomplicated falciparum\" --> E[\"Oral artemisinin combination therapy (ACT)\"]:::good\nC -- \"non-falciparum (vivax/ovale)\" --> F[\"Chloroquine, then primaquine for hypnozoites\"]:::good\nA --> G[\"Notify, check G6PD before primaquine\"]:::process", "tips": {"A": "Consider malaria in anyone with a fever who has returned from an endemic area (falciparum usually within 3 months); it can be rapidly fatal.", "B": "Diagnose with urgent thick and thin blood films (three negatives 12-24 hours apart to exclude) or a rapid diagnostic test; assess parasitaemia and species.", "C": "Management depends on the species and whether there are severe or complicated features.", "D": "Severe or complicated falciparum (impaired consciousness, parasitaemia over 2%, acidosis, renal failure, ARDS, hypoglycaemia): IV artesunate and admission to HDU/ICU.", "E": "Uncomplicated falciparum: an oral artemisinin-based combination therapy (e.g. artemether-lumefantrine), or quinine plus doxycycline.", "F": "Non-falciparum (vivax, ovale, malariae): chloroquine (or ACT), then primaquine to clear liver hypnozoites (vivax and ovale) and prevent relapse.", "G": "Malaria is a notifiable disease; check G6PD status before primaquine (haemolysis risk) and avoid primaquine in pregnancy."}}, cluster: "Tropical, zoonotic & other infection", name: "Malaria", keyFacts: "A protozoal infection from the Anopheles mosquito; falciparum malaria can be rapidly fatal.", epidemiology: "Endemic across the tropics; in the UK it presents in returning travellers.", aetiology: "Plasmodium species (falciparum the most dangerous), transmitted by the female Anopheles mosquito.", pathophysiology: "Parasites infect and rupture red cells in cycles, causing fever and haemolysis and, in falciparum, microvascular sequestration and organ damage.", presentation: "Fever, rigors, headache, myalgia after travel to an endemic area; can be rapidly fatal (falciparum).", investigations: "Thick and thin blood films (three), rapid antigen test.", treatment: "Species-specific antimalarials; admit falciparum; emphasise prophylaxis and bite avoidance." },
      { id: "id_lyme", cluster: "Tropical, zoonotic & other infection", name: "Lyme disease", keyFacts: "A tick-borne spirochaete infection; the early erythema migrans rash is diagnostic.", epidemiology: "Acquired from tick bites in grassland and woodland, with summer peaks.", aetiology: "Borrelia burgdorferi, transmitted by Ixodes tick bites.", pathophysiology: "The spirochaete spreads from the bite site (erythema migrans) and can later disseminate to the joints, heart and nervous system.", presentation: "Erythema migrans target rash after tick bite; later neurological, cardiac or joint features.", investigations: "Clinical for erythema migrans; serology for later disease.", treatment: "Doxycycline; longer courses for disseminated disease." },
      { id: "id_leptospirosis", cluster: "Tropical, zoonotic & other infection", name: "Leptospirosis", keyFacts: "A zoonotic spirochaete infection from animal urine; severe disease (Weil's) causes jaundice and renal failure.", epidemiology: "Linked to fresh-water sports, farming and sewage work; rats are a key reservoir.", aetiology: "Leptospira interrogans, entering through broken skin or mucosa from water contaminated with rat or dog urine.", pathophysiology: "The spirochaete disseminates and causes a vasculitis affecting the liver, kidneys and meninges.", presentation: "A flu-like illness with conjunctival suffusion; severe (Weil's) disease adds jaundice, acute kidney injury and bleeding.", investigations: "Serology and PCR; LFTs, U&E, clotting.", treatment: "Doxycycline or penicillin; supportive care including dialysis for renal failure." },
      { id: "id_leishmaniasis", cluster: "Tropical, zoonotic & other infection", name: "Leishmaniasis", keyFacts: "A protozoal infection from sandfly bites with cutaneous, mucocutaneous and visceral forms.", epidemiology: "Endemic in the tropics, Middle East and Mediterranean; presents in travellers.", aetiology: "Leishmania species, transmitted by the bite of the sandfly.", pathophysiology: "The protozoa multiply within macrophages, producing a skin ulcer or, in the visceral form, infiltration of the reticuloendothelial system.", presentation: "Cutaneous: a chronic painless skin ulcer; visceral (Kala-azar): fever, weight loss, massive hepatosplenomegaly and pancytopenia.", investigations: "Tissue smear or biopsy (Giemsa, amastigotes), splenic or bone marrow aspirate, serology.", treatment: "Liposomal amphotericin B for visceral disease; cutaneous disease often self-heals or is treated topically or systemically." },
      { id: "id_schistosomiasis", cluster: "Tropical, zoonotic & other infection", name: "Schistosomiasis", keyFacts: "A trematode (fluke) infection from fresh water; chronic disease damages the bladder or bowel and liver.", epidemiology: "Common in sub-Saharan Africa; acquired by swimming or wading in infested fresh water.", aetiology: "Schistosoma species (haematobium, mansoni, japonicum) with a fresh-water snail intermediate host.", pathophysiology: "Cercariae penetrate the skin and mature; eggs lodge in tissues, provoking granulomatous inflammation and fibrosis.", presentation: "Swimmer's itch then Katayama fever; chronic S. haematobium causes haematuria and bladder disease (and squamous bladder cancer), S. mansoni causes bowel disease and hepatic fibrosis.", investigations: "Eggs in urine (haematobium) or stool (mansoni), serology, eosinophilia.", treatment: "Praziquantel; avoid fresh-water contact in endemic areas." },
      { id: "id_rabies", cluster: "Tropical, zoonotic & other infection", name: "Rabies", keyFacts: "A near-universally fatal viral encephalitis once symptomatic; post-exposure prophylaxis is life-saving.", epidemiology: "Endemic in parts of Asia and Africa; UK risk is from animal bites abroad (dogs) and from bats.", aetiology: "Rabies virus (a rhabdovirus), from the bite or scratch of an infected animal.", pathophysiology: "The virus travels up peripheral nerves to the CNS over weeks to months, causing a fatal encephalitis; Negri bodies are pathognomonic.", presentation: "Prodrome at the bite site, then hydrophobia, hypersalivation, agitation and encephalitis (furious form) or ascending paralysis (dumb form).", investigations: "Clinical; PCR and serology; Negri bodies on histology.", treatment: "Post-exposure prophylaxis (wound washing, rabies immunoglobulin and vaccine) before symptoms; once symptomatic, care is supportive as it is almost always fatal." },
      { id: "id_tetanus", cluster: "Tropical, zoonotic & other infection", name: "Tetanus", keyFacts: "A toxin-mediated disease causing muscle spasms and rigidity; prevented by vaccination.", epidemiology: "Rare where vaccination is routine; risk with contaminated wounds and in the unvaccinated.", aetiology: "Clostridium tetani spores entering a wound, classically a deep, dirty puncture.", pathophysiology: "Tetanospasmin travels up nerves and blocks inhibitory neurotransmitters, causing unopposed muscle contraction.", presentation: "Trismus (lockjaw), risus sardonicus, neck and back rigidity (opisthotonus), and painful generalised spasms.", investigations: "Clinical diagnosis; assess the wound and vaccination history.", treatment: "Wound care, human tetanus immunoglobulin, metronidazole, spasm control with benzodiazepines, and supportive care; vaccinate." },
      { id: "id_fungal", cluster: "Tropical, zoonotic & other infection", name: "Fungal infections (invasive)", keyFacts: "Invasive fungal infections mainly affect the immunocompromised and can be life-threatening.", epidemiology: "Increasing with immunosuppression, intensive care, broad-spectrum antibiotics and indwelling lines.", aetiology: "Candida (lines, gut), Aspergillus (lungs), Cryptococcus (meninges in HIV) and Pneumocystis jirovecii (HIV).", pathophysiology: "Loss of immune defences lets commensal or environmental fungi invade tissue and the bloodstream.", presentation: "Candidaemia in the unwell or line patient; invasive aspergillosis with haemoptysis; cryptococcal meningitis and pneumocystis pneumonia (PCP) in HIV.", investigations: "Cultures, beta-D-glucan and galactomannan, CT chest, cryptococcal antigen; bronchoscopy for PCP.", treatment: "Antifungals by type (fluconazole or an echinocandin for Candida, voriconazole for Aspergillus, co-trimoxazole for PCP); remove lines; restore immunity." },
      { id: "id_notifiable", cluster: "Principles & stewardship", name: "Notifiable diseases", fieldLabels: ["📋 What it is", "⏱️ When to notify", "📢 How to act"], presentation: "Statutory duty to report suspected cases to protect public health.", investigations: "Clinical suspicion is enough to notify; confirm with appropriate tests.", treatment: "Notify UKHSA promptly (e.g. measles, TB, meningococcal, food poisoning); arrange control measures." },
      { id: "id_abx_choice", cluster: "Principles & stewardship", name: "Antibiotic stewardship", fieldLabels: ["📋 What it is", "🔍 In practice", "✅ Key principles"], presentation: "Choosing the right drug, dose and duration while minimising resistance.", investigations: "Cultures before antibiotics where possible; review local guidelines.", treatment: "Use narrowest effective agent, review at 48–72h, document indication and duration, de-escalate." },
    ],
  },
  {
    id: "haematology",
    name: "Haematology",
    icon: "🩸",
    conditions: [
      { id: "haem_ida", management: {"def": "A[\"Iron deficiency anaemia\"]:::start --> B[\"Confirm: microcytic anaemia, low ferritin\"]:::process\nB --> C{\"Likely source of loss?\"}:::decision\nC -- \"GI (men, postmenopausal, red flags)\" --> D[\"Upper and lower GI endoscopy\"]:::warn\nC -- \"menstruating woman\" --> E[\"Assess menstrual loss, coeliac screen\"]:::good\nD --> F[\"Oral iron: ferrous sulfate once daily\"]:::good\nE --> F\nF --> G[\"Recheck FBC, continue 3 months after normal\"]:::good\nF -- \"intolerant / malabsorption\" --> H[\"IV iron\"]:::good", "tips": {"A": "Reduced iron stores causing a microcytic, hypochromic anaemia; the priority is to find WHY, not just replace iron.", "B": "Low haemoglobin with low mean cell volume and low ferritin confirms it (ferritin can be falsely normal in inflammation - check CRP and transferrin saturation).", "C": "Always investigate the underlying cause.", "D": "In men and postmenopausal women (or anyone with GI symptoms/red flags), investigate for GI blood loss with upper and lower GI endoscopy; use the 2-week-wait pathway for alarm features.", "E": "In menstruating women, assess menstrual loss and diet and screen for coeliac disease (anti-tTG).", "F": "Replace with oral ferrous sulfate (or fumarate/gluconate) taken with vitamin C; warn about GI upset (alternate-day dosing may improve tolerance and absorption).", "G": "Recheck haemoglobin; continue iron for about 3 months after it normalises to replenish stores.", "H": "Use intravenous iron if oral iron is not tolerated, is ineffective, or in malabsorption."}}, cluster: "Anaemias", name: "Iron deficiency anaemia", keyFacts: "The commonest anaemia, from depleted iron stores; in men and older women, exclude gastrointestinal bleeding.", epidemiology: "Very common worldwide, especially in menstruating and pregnant women.", aetiology: "Blood loss (menstrual, gastrointestinal), poor intake, malabsorption (coeliac) and increased demand.", pathophysiology: "Insufficient iron limits haemoglobin synthesis, producing small (microcytic) and pale (hypochromic) red cells.", presentation: "Fatigue, pallor, breathlessness, koilonychia; commonest anaemia.", investigations: "FBC (microcytic), ferritin (low), blood film; investigate GI loss in at-risk groups.", treatment: "Oral iron; treat cause; refer for endoscopy if unexplained in older adults." },
      { id: "haem_thalassaemia", cluster: "Anaemias", name: "Beta thalassaemia", keyFacts: "Reduced beta-globin chain synthesis; ranges from a symptomless trait to transfusion-dependent major.", epidemiology: "Common in Mediterranean, Middle Eastern and South Asian populations.", aetiology: "Autosomal recessive beta-globin (HBB) gene mutations that reduce or abolish beta-chain production.", pathophysiology: "Excess unpaired alpha chains precipitate in red cells, causing ineffective erythropoiesis, haemolysis and marrow expansion.", presentation: "Trait: mild microcytic anaemia. Major: severe anaemia from a few months old, failure to thrive, hepatosplenomegaly and skull bossing from extramedullary haematopoiesis.", investigations: "Microcytic hypochromic film, haemoglobin electrophoresis (raised HbA2 and HbF), genetic testing.", treatment: "Trait needs none; major needs regular transfusion with iron chelation (desferrioxamine); allogeneic stem cell transplant can be curative in children." },
      { id: "haem_thal_alpha", cluster: "Anaemias", name: "Alpha thalassaemia", keyFacts: "Reduced alpha-globin synthesis; severity depends on how many of the four alpha genes are deleted.", epidemiology: "Common in Southeast Asian, African and Mediterranean populations.", aetiology: "Deletion of one to four alpha-globin genes on chromosome 16.", pathophysiology: "Loss of alpha chains leaves excess beta chains (HbH) or gamma chains (Hb Barts); severity scales with the number of genes lost.", presentation: "One or two genes: silent carrier or mild trait. Three genes: HbH disease (moderate haemolytic anaemia). Four genes: Hb Barts, causing fatal hydrops fetalis in utero.", investigations: "Microcytic anaemia with a normal HbA2 (unlike beta trait), HbH bodies on film, genetic testing.", treatment: "Trait needs none; HbH disease may need transfusion; four-gene deletion is incompatible with life without intrauterine transfusion." },
      { id: "haem_b12_anaemia", cluster: "Anaemias", name: "Pernicious anaemia", keyFacts: "A macrocytic anaemia from autoimmune B12 deficiency, which can also damage the nervous system.", epidemiology: "Commoner in older people and with other autoimmune disease.", aetiology: "Autoimmune destruction of gastric parietal cells with loss of intrinsic factor, impairing B12 absorption.", pathophysiology: "Lack of intrinsic factor prevents ileal B12 absorption, impairing DNA synthesis (large red cells) and myelin maintenance (neuropathy).", presentation: "Macrocytic anaemia with glossitis and neurological signs; autoimmune.", investigations: "B12 low, intrinsic factor antibodies, blood film (hypersegmented neutrophils).", treatment: "IM hydroxocobalamin; lifelong if pernicious; replace before folate." },
      { id: "haem_acd", cluster: "Anaemias", name: "Anaemia of chronic disease", keyFacts: "Anaemia accompanying chronic inflammation, infection or malignancy.", epidemiology: "One of the commonest anaemias among hospital patients.", aetiology: "Chronic inflammatory, infective, malignant or autoimmune disease.", pathophysiology: "Inflammatory cytokines raise hepcidin, trapping iron in stores and blunting erythropoiesis despite adequate total iron.", presentation: "Normocytic or mildly microcytic anaemia in chronic inflammation or malignancy.", investigations: "Ferritin normal/high, low transferrin saturation, raised inflammatory markers.", treatment: "Treat the underlying condition; iron only if coexisting deficiency." },
      { id: "haem_sickle", management: {"def": "A[\"Sickle cell acute painful crisis\"]:::start --> B[\"Prompt strong analgesia (often IV opioid)\"]:::good\nB --> C[\"Oxygen, IV fluids, keep warm\"]:::good\nC --> D[\"Screen and treat any trigger (e.g. infection)\"]:::good\nD --> E{\"Severe complication?\"}:::decision\nE -- \"acute chest, stroke, sequestration\" --> F[\"Urgent exchange transfusion, haematology\"]:::danger\nE -- \"uncomplicated\" --> G[\"Continue supportive care, monitor\"]:::good", "tips": {"A": "A vaso-occlusive crisis from sickled red cells: severe bony pain, often triggered by infection, dehydration, cold, hypoxia or stress.", "B": "Give prompt, adequate analgesia within 30 minutes - often strong opioids such as morphine; avoid pethidine. Do NOT undertreat the pain.", "C": "Give oxygen if hypoxic, IV fluids for hydration, and keep the patient warm.", "D": "Actively look for and treat precipitants, especially infection (cultures, antibiotics); check FBC and reticulocytes.", "E": "Identify life-threatening complications.", "F": "Acute chest syndrome, stroke, splenic sequestration or aplastic crisis need urgent senior and haematology input, and often exchange (or top-up) transfusion.", "G": "Uncomplicated crisis: continue analgesia, hydration and supportive care, give VTE prophylaxis, and monitor; hydroxycarbamide reduces future crises."}}, cluster: "Haemolytic & bone marrow failure", name: "Sickle cell disease", keyFacts: "An inherited haemoglobinopathy causing painful vaso-occlusive crises; autosomal recessive.", epidemiology: "Commonest in people of African, Caribbean and Mediterranean descent; detected on newborn screening.", aetiology: "A point mutation in the beta-globin gene producing haemoglobin S, inherited recessively.", pathophysiology: "Deoxygenated haemoglobin S polymerises and distorts red cells into sickle shapes that occlude vessels and haemolyse.", presentation: "Painful vaso-occlusive crises, anaemia, infections; autosomal recessive.", investigations: "Blood film, haemoglobin electrophoresis, newborn screening.", treatment: "Hydration, analgesia, oxygen and treat infection in crisis; hydroxycarbamide; vaccination and penicillin prophylaxis." },
      { id: "haem_spherocytosis", cluster: "Haemolytic & bone marrow failure", name: "Hereditary spherocytosis", keyFacts: "The commonest inherited haemolytic anaemia in northern Europeans; red cells become spherical and fragile.", epidemiology: "The commonest inherited haemolytic anaemia in people of northern European descent.", aetiology: "Usually autosomal dominant defects of red-cell membrane proteins (spectrin, ankyrin, band 3).", pathophysiology: "Membrane defects make red cells spherical and rigid, so the spleen destroys them (extravascular haemolysis).", presentation: "Anaemia, jaundice, splenomegaly and pigment gallstones; an aplastic crisis can follow parvovirus B19.", investigations: "Spherocytes on film, raised reticulocytes, negative direct antiglobulin test, raised MCHC; EMA binding or osmotic fragility.", treatment: "Folic acid and transfusion if needed; splenectomy for severe disease (vaccinate first); cholecystectomy for gallstones." },
      { id: "haem_aplastic", cluster: "Haemolytic & bone marrow failure", name: "Aplastic anaemia", keyFacts: "Bone marrow failure causing pancytopenia with a hypocellular marrow.", epidemiology: "Rare, with a bimodal peak in young adults and the elderly.", aetiology: "Idiopathic autoimmune most often; also drugs (chloramphenicol, carbimazole, chemotherapy), viruses, radiation and inherited Fanconi anaemia.", pathophysiology: "Immune-mediated failure of haematopoietic stem cells leaves an empty marrow and peripheral pancytopenia.", presentation: "Anaemia (fatigue), thrombocytopenia (bruising, bleeding) and neutropenia (infection); no splenomegaly.", investigations: "FBC (pancytopenia), low reticulocytes, bone marrow biopsy (hypocellular with fat spaces); exclude leukaemia.", treatment: "Remove the cause; supportive transfusion and antibiotics; immunosuppression (antithymocyte globulin, ciclosporin); stem cell transplant in the young." },
      { id: "haem_leukaemia", cluster: "Leukaemias & myeloproliferative disorders", name: "Acute lymphoblastic leukaemia (ALL)", keyFacts: "The commonest childhood cancer; a rapidly progressive proliferation of lymphoblasts.", epidemiology: "Peaks in children aged 2 to 5; associated with Down syndrome.", aetiology: "Mostly idiopathic; risk with ionising radiation, Down syndrome and certain genetic changes.", pathophysiology: "Clonal lymphoid blasts crowd the marrow, causing anaemia, neutropenia and thrombocytopenia; blasts can infiltrate the CNS and testes.", presentation: "Fatigue, pallor, infections, bruising and bleeding, bone pain, lymphadenopathy and hepatosplenomegaly over days to weeks.", investigations: "FBC, blood film (lymphoblasts), bone marrow biopsy, immunophenotyping and cytogenetics; lumbar puncture for CNS disease.", treatment: "Urgent referral; intensive chemotherapy with CNS prophylaxis; a tyrosine kinase inhibitor if Philadelphia-positive; stem cell transplant in high-risk disease." },
      { id: "haem_aml", cluster: "Leukaemias & myeloproliferative disorders", name: "Acute myeloid leukaemia (AML)", keyFacts: "The commonest acute leukaemia in adults; a rapid proliferation of myeloblasts.", epidemiology: "Mainly older adults, with incidence rising with age.", aetiology: "Usually de novo; also from prior chemotherapy or radiation, myelodysplasia or a myeloproliferative neoplasm.", pathophysiology: "Clonal myeloblasts replace normal marrow, causing marrow failure; Auer rods are characteristic.", presentation: "Rapid onset of anaemia, infection and bleeding; gum infiltration; disseminated intravascular coagulation in acute promyelocytic leukaemia.", investigations: "FBC, blood film (myeloblasts with Auer rods), marrow biopsy, cytogenetics.", treatment: "Intensive chemotherapy and supportive care; all-trans retinoic acid for acute promyelocytic leukaemia; stem cell transplant in fit patients; poor prognosis in the elderly." },
      { id: "haem_cll", cluster: "Leukaemias & myeloproliferative disorders", name: "Chronic lymphocytic leukaemia (CLL)", keyFacts: "The commonest leukaemia in adults; an indolent proliferation of mature B-lymphocytes, often found incidentally.", epidemiology: "Mainly older adults, often as an incidental lymphocytosis.", aetiology: "Clonal proliferation of mature B cells; cause unknown.", pathophysiology: "Accumulation of incompetent mature B cells causes immune dysfunction and can transform (Richter's) to an aggressive lymphoma.", presentation: "Often asymptomatic; lymphadenopathy, splenomegaly, recurrent infection, anaemia and autoimmune haemolysis; smudge cells on film.", investigations: "FBC (lymphocytosis), blood film (smudge cells), immunophenotyping, direct antiglobulin test.", treatment: "Watch and wait if asymptomatic; chemo-immunotherapy or targeted agents (BTK inhibitors) when progressive." },
      { id: "haem_cml", cluster: "Leukaemias & myeloproliferative disorders", name: "Chronic myeloid leukaemia (CML)", keyFacts: "A myeloproliferative neoplasm driven by the Philadelphia chromosome (BCR-ABL); treated with imatinib.", epidemiology: "Middle-aged and older adults.", aetiology: "The Philadelphia chromosome, a t(9;22) translocation creating the BCR-ABL fusion gene.", pathophysiology: "BCR-ABL is a constitutively active tyrosine kinase driving granulocyte proliferation; an untreated chronic phase can transform to blast crisis.", presentation: "Fatigue, weight loss, sweats and massive splenomegaly, with a very high white cell count often found on routine bloods.", investigations: "FBC (raised white cells across the whole granulocyte spectrum), marrow, cytogenetics or PCR for BCR-ABL.", treatment: "A tyrosine kinase inhibitor (imatinib) gives excellent control; stem cell transplant is rarely needed." },
      { id: "haem_pv", cluster: "Leukaemias & myeloproliferative disorders", name: "Polycythaemia vera", keyFacts: "A myeloproliferative neoplasm of excess red cells, usually from a JAK2 mutation; the main risk is thrombosis.", epidemiology: "Older adults; the commonest myeloproliferative neoplasm.", aetiology: "An acquired JAK2 V617F mutation in nearly all cases.", pathophysiology: "Autonomous erythroid (and often platelet and granulocyte) proliferation raises blood viscosity and thrombotic risk; distinguish from secondary polycythaemia.", presentation: "Headache, plethora, aquagenic pruritus (itch after a hot bath), erythromelalgia, splenomegaly, and thrombosis or bleeding.", investigations: "Raised haemoglobin and haematocrit, JAK2 mutation, low erythropoietin; exclude secondary causes.", treatment: "Venesection to target the haematocrit, low-dose aspirin, and hydroxycarbamide for high-risk disease; monitor for transformation to myelofibrosis or AML." },
      { id: "haem_lymphoma", cluster: "Lymphoma & myeloma", name: "Hodgkin lymphoma", keyFacts: "A lymphoma defined by Reed-Sternberg cells, with a bimodal age peak and a generally good prognosis.", epidemiology: "Bimodal: a peak in young adults and another in older age; associated with Epstein-Barr virus.", aetiology: "Often idiopathic, with associations to Epstein-Barr virus and immunosuppression.", pathophysiology: "Malignant Reed-Sternberg cells (of B-cell origin) sit in a reactive inflammatory background and spread contiguously between node groups.", presentation: "Painless cervical or supraclavicular lymphadenopathy, B symptoms (fever, night sweats, weight loss), and alcohol-induced node pain.", investigations: "Lymph node biopsy (Reed-Sternberg cells), CT/PET staging (Ann Arbor), LDH, FBC.", treatment: "Combination chemotherapy (ABVD) with or without radiotherapy; generally curable; specialist care." },
      { id: "haem_nhl", cluster: "Lymphoma & myeloma", name: "Non-Hodgkin lymphoma", keyFacts: "A diverse group of lymphocyte malignancies (mostly B-cell); commoner than Hodgkin and far more variable.", epidemiology: "Incidence rises with age; it makes up the great majority of lymphomas.", aetiology: "Often idiopathic; associations include immunosuppression, HIV, Epstein-Barr virus, Helicobacter pylori (gastric MALT) and autoimmune disease.", pathophysiology: "Clonal proliferation of B (or less often T) lymphocytes, ranging from indolent (follicular) to aggressive (diffuse large B-cell, Burkitt).", presentation: "Painless widespread lymphadenopathy, B symptoms and extranodal disease (gut, skin, marrow); may present acutely if high-grade.", investigations: "Excisional lymph node biopsy, immunophenotyping, CT/PET staging, LDH, marrow biopsy, HIV test.", treatment: "By subtype and grade: watch and wait for indolent disease; R-CHOP chemo-immunotherapy for aggressive B-cell disease." },
      { id: "haem_myeloma", cluster: "Lymphoma & myeloma", name: "Multiple myeloma", keyFacts: "A malignancy of plasma cells, remembered by CRAB: hyperCalcaemia, Renal failure, Anaemia and Bone lesions.", epidemiology: "A disease of older adults, commoner in Black populations.", aetiology: "Clonal plasma-cell proliferation of unknown cause, often preceded by MGUS.", pathophysiology: "Malignant plasma cells produce monoclonal paraprotein and activate osteoclasts, causing bone lesions, hypercalcaemia, renal failure and anaemia.", presentation: "Bone pain, anaemia, renal impairment, hypercalcaemia, recurrent infection.", investigations: "Serum/urine electrophoresis, free light chains, marrow biopsy, skeletal survey (CRAB).", treatment: "Chemotherapy, bisphosphonates, supportive care; transplant in fit patients." },
      { id: "haem_itp", cluster: "Bleeding & platelet disorders", name: "Immune thrombocytopenia", keyFacts: "Immune-mediated platelet destruction causing isolated thrombocytopenia with bruising and bleeding.", epidemiology: "Acute form in children (often post-viral); chronic form in adults, commoner in women.", aetiology: "Autoantibodies against platelets, idiopathic or triggered by infection, drugs or autoimmune disease.", pathophysiology: "Antiplatelet antibodies tag platelets for splenic destruction, lowering the count and impairing haemostasis.", presentation: "Bruising, petechiae, mucosal bleeding with isolated low platelets.", investigations: "FBC, blood film, exclude secondary causes.", treatment: "Observe if mild; steroids/IVIG for bleeding or very low counts; treat causes." },
      { id: "haem_haemophilia", cluster: "Bleeding & platelet disorders", name: "Haemophilia", keyFacts: "An inherited deficiency of clotting factor VIII (A) or IX (B) causing a bleeding tendency; X-linked recessive.", epidemiology: "Affects males; haemophilia A is about four times commoner than B.", aetiology: "X-linked recessive deficiency of factor VIII (haemophilia A) or factor IX (haemophilia B, Christmas disease).", pathophysiology: "Loss of an intrinsic-pathway factor impairs clot formation, prolonging the APTT and causing deep bleeding.", presentation: "Spontaneous and post-traumatic bleeding into joints (haemarthrosis) and muscles, and prolonged bleeding after procedures; severity tracks the factor level.", investigations: "Prolonged APTT with normal PT and platelets; reduced factor VIII or IX on assay; genetic testing.", treatment: "Factor replacement (recombinant VIII or IX), desmopressin for mild haemophilia A; avoid NSAIDs and IM injections; manage at a specialist haemophilia centre." },
      { id: "haem_aps", cluster: "Thrombosis & anticoagulation", name: "Antiphospholipid syndrome", keyFacts: "An autoimmune prothrombotic disorder causing arterial and venous thrombosis and recurrent miscarriage.", epidemiology: "Commoner in women; may be primary or secondary to SLE.", aetiology: "Antiphospholipid antibodies (lupus anticoagulant, anticardiolipin, anti-beta2-glycoprotein I), either primary or with SLE.", pathophysiology: "The antibodies promote a procoagulant state on cell membranes, causing thrombosis despite a paradoxically prolonged APTT in vitro.", presentation: "Venous and arterial thrombosis, recurrent miscarriage, thrombocytopenia and livedo reticularis (the CLOT features).", investigations: "Persistently positive antiphospholipid antibodies (repeated at 12 weeks), prolonged APTT, thrombocytopenia.", treatment: "Long-term warfarin after thrombosis (not DOACs); aspirin and LMWH in pregnancy; treat any underlying SLE." },
      { id: "haem_anticoag", management: {"source": "BSH", "def": "A[\"Warfarin: high INR or bleeding\"]:::start --> B{\"Bleeding?\"}:::decision\nB -- \"major bleeding\" --> C[\"Stop warfarin, IV vitamin K + PCC\"]:::danger\nB -- \"no bleeding, INR over 8\" --> D[\"Stop warfarin, oral vitamin K\"]:::good\nB -- \"no bleeding, INR 5-8\" --> E[\"Withhold 1-2 doses, reduce dose\"]:::good\nC --> F[\"Recheck INR, find bleeding source\"]:::process\nA --> G[\"DOAC bleeding: idarucizumab or andexanet\"]:::warn", "tips": {"A": "Managing a raised INR or bleeding on warfarin depends on whether there is bleeding and how high the INR is (BSH/BNF guidance).", "B": "The presence and severity of bleeding drives management.", "C": "Major (life-threatening) bleeding: stop warfarin and give IV vitamin K 5 mg AND prothrombin complex concentrate (PCC, e.g. Beriplex) for immediate reversal - fresh frozen plasma only if PCC is unavailable.", "D": "INR above 8 with no or minor bleeding: withhold warfarin and give oral vitamin K (1-5 mg); restart when the INR is under 5.", "E": "INR 5-8 with no bleeding: withhold 1-2 doses and reduce the maintenance dose; look for the cause of the rise.", "F": "Recheck the INR after reversal (repeat vitamin K if still high) and identify and treat the bleeding source.", "G": "For DOAC-associated major bleeding: idarucizumab reverses dabigatran; andexanet alfa (or PCC) for factor Xa inhibitors such as apixaban and rivaroxaban."}}, cluster: "Thrombosis & anticoagulation", name: "Anticoagulation", presentation: "Balancing thrombosis prevention against bleeding risk.", investigations: "Renal function, weight, indication, bleeding risk; INR for warfarin.", treatment: "DOAC for most AF/VTE; warfarin for mechanical valves/antiphospholipid; counsel on adherence and reversal." },
    ],
  },
  {
    id: "immunology",
    name: "Immunology & Allergy",
    icon: "🛡️",
    conditions: [
      { id: "immuno_allergic_disease", cluster: "Allergy & atopy", name: "Allergy & atopy", keyFacts: "The atopic tendency to IgE-mediated disease, often clustering as eczema, asthma and rhinitis.", epidemiology: "Very common and rising, particularly in developed countries.", aetiology: "Genetic atopy with environmental allergen exposure; the hygiene hypothesis is implicated.", pathophysiology: "A type 2 immune bias produces allergen-specific IgE, so re-exposure triggers mast-cell mediator release.", presentation: "IgE-mediated atopic conditions (eczema, asthma, allergic rhinitis, food allergy) that often coexist; the atopic march from infancy.", investigations: "History of triggers and timing; skin prick testing and specific IgE blood tests.", treatment: "Allergen avoidance, antihistamines, intranasal or inhaled corticosteroids; adrenaline auto-injector for those at risk of anaphylaxis." },
      { id: "immuno_allergic_rhinitis", cluster: "Allergy & atopy", name: "Allergic rhinitis", keyFacts: "IgE-mediated inflammation of the nasal mucosa causing sneezing, itch, congestion and rhinorrhoea; seasonal (hay fever) or perennial.", epidemiology: "Very common and part of atopy, often coexisting with asthma and eczema.", aetiology: "Inhaled allergens — pollen (seasonal hay fever), house dust mite, animal dander and moulds (perennial).", pathophysiology: "Allergen cross-links mucosal mast-cell IgE, releasing histamine and other mediators that drive the early and late nasal symptoms.", presentation: "Sneezing, nasal itch, watery rhinorrhoea and congestion, with itchy watery eyes; a nasal crease and allergic shiners in children.", investigations: "Clinical diagnosis from the history; skin prick or specific IgE testing to identify the allergen if needed.", treatment: "Allergen avoidance; intranasal corticosteroids (most effective) and non-sedating antihistamines; add a leukotriene antagonist or saline rinses; allergen immunotherapy for severe refractory disease." },
      { id: "immuno_food_allergy", cluster: "Allergy & atopy", name: "Food allergy", keyFacts: "An immune reaction to food, ranging from mild urticaria to anaphylaxis.", epidemiology: "Commoner in children, with egg, milk and peanut frequent triggers.", aetiology: "IgE-mediated (rapid) or non-IgE-mediated (delayed) responses to food proteins.", pathophysiology: "Allergen-specific IgE on mast cells triggers rapid mediator release on re-exposure, causing the allergic response.", presentation: "IgE-mediated: rapid urticaria, angioedema, vomiting, wheeze or anaphylaxis after a trigger food (egg, milk, peanut, shellfish). Non-IgE: delayed gut symptoms.", investigations: "Focused allergy history; skin prick or specific IgE testing; supervised oral food challenge where needed.", treatment: "Strict avoidance with a written allergy action plan, antihistamine for mild reactions, adrenaline auto-injector for anaphylaxis risk; dietitian input." },
      { id: "immuno_drug_allergy", cluster: "Allergy & atopy", name: "Drug allergy", keyFacts: "An immune-mediated adverse reaction to a drug; penicillin is the commonest cause.", epidemiology: "Common and frequently over-reported, with true anaphylaxis much rarer than the labelled allergy.", aetiology: "Immune sensitisation to a drug or its metabolites by various hypersensitivity mechanisms.", pathophysiology: "Depending on the mechanism, drug-specific IgE or T-cells drive reactions from immediate anaphylaxis to delayed rashes.", presentation: "Ranges from a delayed maculopapular rash to immediate urticaria, angioedema and anaphylaxis; penicillin is the commonest cause.", investigations: "Clarify the nature and timing of the reaction; specialist allergy testing for unclear or severe cases.", treatment: "Avoid the drug and document the allergy clearly, offer alternatives, and manage anaphylaxis with adrenaline." },
      { id: "haem_anaphylaxis", management: {"def": "A[\"Anaphylaxis\"]:::start --> B[\"ABCDE, remove trigger, call for help\"]:::danger\nB --> C[\"IM adrenaline 500 micrograms (1:1000)\"]:::danger\nC --> D[\"High-flow oxygen, lie flat, raise legs\"]:::good\nD --> E[\"IV fluid bolus (crystalloid)\"]:::good\nE --> F{\"Improved?\"}:::decision\nF -- \"no, after 5 min\" --> G[\"Repeat IM adrenaline\"]:::warn\nG --> H[\"Refractory: IV adrenaline infusion (specialist)\"]:::danger\nF -- \"yes\" --> I[\"Observe, tryptase, auto-injector + allergy referral\"]:::good", "tips": {"A": "Acute life-threatening systemic hypersensitivity - a sudden airway, breathing or circulation problem, usually with skin changes, after an allergen.", "B": "Use an ABCDE approach, remove the trigger if possible, and call for help early.", "C": "Intramuscular adrenaline 500 micrograms (0.5 mL of 1:1000) into the anterolateral thigh is the immediate priority. Paediatric doses: 300 micrograms age 6-12, 150 micrograms under 6.", "D": "High-flow oxygen; lie flat with legs raised (sit up if breathing is the main problem, left lateral if pregnant).", "E": "Give a rapid IV crystalloid bolus for hypotension.", "F": "Reassess after each step.", "G": "Repeat IM adrenaline every 5 minutes if there is no improvement.", "H": "Refractory anaphylaxis (no response to two doses): IV adrenaline infusion by an experienced specialist. Steroids and antihistamines are no longer routine first-line.", "I": "After stabilising: timed serum tryptase, observe for a biphasic reaction, prescribe two adrenaline auto-injectors with training, and refer to allergy services."}}, cluster: "Anaphylaxis & angioedema", name: "Anaphylaxis", keyFacts: "A severe, rapid, life-threatening systemic hypersensitivity reaction; the immediate treatment is intramuscular adrenaline.", epidemiology: "Increasingly common, with food, drugs and insect stings frequent triggers.", aetiology: "An IgE-mediated reaction to allergens such as foods (nuts), drugs (penicillin) and venom.", pathophysiology: "Allergen cross-links mast-cell IgE, causing massive mediator release with vasodilation, bronchospasm and capillary leak.", presentation: "Rapid airway, breathing or circulation compromise with skin changes (urticaria, angioedema) after an allergen.", investigations: "Clinical diagnosis; serum mast cell tryptase, ideally timed soon after and again later; subsequent allergy testing.", treatment: "IM adrenaline into the anterolateral thigh (repeat after 5 minutes if needed), high-flow oxygen, IV fluids, lie flat; observe for a biphasic reaction; adrenaline auto-injector and allergy clinic referral." },
      { id: "immuno_angioedema", cluster: "Anaphylaxis & angioedema", name: "Angioedema", keyFacts: "Deep dermal and submucosal swelling; importantly, the hereditary type does not respond to adrenaline.", epidemiology: "Allergic and ACE-inhibitor types are commonest, whereas hereditary angioedema is rare.", aetiology: "Allergic (with urticaria), drug-induced (ACE inhibitors), or hereditary C1 esterase inhibitor deficiency.", pathophysiology: "Mast-cell mediators (allergic) or excess bradykinin (ACE-inhibitor and hereditary) increase vascular permeability, causing deep swelling.", presentation: "Deep swelling of the lips, face, tongue or airway. Allergic (with urticaria), drug-induced (ACE inhibitors), or hereditary (C1 esterase inhibitor deficiency, without urticaria).", investigations: "History and triggers; C4 and C1 esterase inhibitor levels if hereditary angioedema is suspected.", treatment: "Protect the airway; the allergic type responds to adrenaline, antihistamine and steroid; stop any ACE inhibitor; the hereditary type needs C1 inhibitor concentrate and does not respond to adrenaline." },
      { id: "immuno_hypersensitivity", cluster: "Hypersensitivity & allergy testing", name: "Hypersensitivity reactions", presentation: "Gell and Coombs types: I (immediate IgE, anaphylaxis), II (antibody-mediated), III (immune complex), IV (delayed T-cell, e.g. contact dermatitis).", investigations: "Recognise the clinical pattern; type-specific tests (specific IgE, autoantibodies, patch testing).", treatment: "Avoid the trigger; treatment depends on the underlying mechanism and severity." },
      { id: "immuno_allergy_testing", cluster: "Hypersensitivity & allergy testing", name: "Allergy testing & immunotherapy", presentation: "Confirming a suspected allergy and identifying triggers to guide avoidance and treatment.", investigations: "Skin prick testing and specific IgE blood tests; supervised challenge in selected cases; total IgE alone is rarely helpful.", treatment: "Allergen avoidance and pharmacotherapy; allergen immunotherapy (desensitisation) for selected cases such as severe rhinitis or venom allergy." },
      { id: "immuno_primary_immunodeficiency", cluster: "Immunodeficiency & immune dysfunction", name: "Primary immunodeficiency", keyFacts: "An inherited defect of the immune system causing recurrent, severe or unusual infections.", epidemiology: "Individually rare; selective IgA deficiency is the commonest.", aetiology: "Genetic defects affecting antibody, cellular, phagocyte or complement function.", pathophysiology: "A defect in one or more arms of the immune system impairs defence against specific classes of pathogen.", presentation: "Recurrent, severe, persistent or unusual infections, failure to thrive, or a positive family history; selective IgA deficiency is the commonest.", investigations: "FBC, immunoglobulin levels, lymphocyte subsets and vaccine responses; specialist immunology referral.", treatment: "Prompt treatment of infection, prophylactic antibiotics, immunoglobulin replacement for antibody deficiency; avoid live vaccines in severe cases." },
      { id: "immuno_asplenia", cluster: "Immunodeficiency & immune dysfunction", name: "Asplenia & hyposplenism", keyFacts: "An absent or non-functioning spleen, raising the risk of overwhelming infection with encapsulated bacteria.", epidemiology: "Follows splenectomy, sickle cell disease and coeliac disease, among others.", aetiology: "Surgical removal, infarction (sickle cell), or functional hyposplenism (coeliac disease).", pathophysiology: "Loss of splenic filtering and antibody responses impairs clearance of encapsulated organisms, hence the sepsis risk.", presentation: "An absent or non-functioning spleen (surgical, sickle cell disease, coeliac disease) raises the risk of overwhelming infection with encapsulated bacteria.", investigations: "Blood film (Howell-Jolly bodies); identify the underlying cause.", treatment: "Pneumococcal, meningococcal and Haemophilus influenzae type b vaccination, lifelong prophylactic antibiotics, prompt treatment of fever, and a medical alert card." },
      { id: "immuno_allograft", cluster: "Immunodeficiency & immune dysfunction", name: "Allograft reactions", keyFacts: "Immune rejection of transplanted tissue, governed by histocompatibility (HLA matching) and classified by timing into hyperacute, acute and chronic.", epidemiology: "Relevant to every solid-organ and stem-cell transplant; risk falls with closer HLA matching and immunosuppression.", aetiology: "Recipient immune recognition of donor human leukocyte antigens (HLA, the major histocompatibility complex); driven by pre-formed antibodies, T-cell responses or chronic injury depending on the type.", pathophysiology: "Donor HLA molecules that differ from the recipient's are seen as foreign; the degree of HLA mismatch and any pre-formed anti-HLA or ABO antibodies set the speed and severity of rejection.", presentation: "Hyperacute (minutes to hours): pre-formed antibodies cause immediate graft thrombosis. Acute (days to weeks): cell-mediated and antibody rejection with graft dysfunction. Chronic (months to years): progressive fibrosis and vascular narrowing causing slow graft failure. Graft-versus-host disease in stem-cell transplants (rash, diarrhoea, deranged liver function).", investigations: "HLA tissue typing and crossmatch before transplant; graft biopsy and donor-specific antibody testing to diagnose and grade rejection; monitor graft function.", treatment: "Prevent with HLA matching and lifelong immunosuppression (calcineurin inhibitors, antiproliferatives, steroids); treat acute rejection with high-dose steroids and antibody therapy; hyperacute rejection needs graft removal." },
    ],
  },
  {
    id: "genetics",
    name: "Genetics",
    icon: "🧬",
    itemNoun: "topics",
    conditions: [
      { id: "genetics_inheritance", cluster: "Principles of inheritance", name: "Patterns of inheritance", fieldLabels: ["📋 The patterns", "🔬 Testing", "🧬 Counselling & options"], presentation: "Autosomal dominant (vertical transmission, 50% offspring risk), autosomal recessive (carrier parents, consanguinity), X-linked recessive (males affected, no male-to-male transmission), mitochondrial (maternal).", investigations: "Three-generation family pedigree, karyotype, chromosomal microarray, targeted gene or panel testing.", treatment: "Genetic counselling, cascade testing of at-risk relatives, reproductive options including prenatal and preimplantation testing." },
      { id: "genetics_downs", cluster: "Autosomal trisomies", name: "Down syndrome (trisomy 21)", keyFacts: "The commonest autosomal trisomy and chromosomal cause of learning disability.", epidemiology: "Incidence rises markedly with maternal age.", aetiology: "Trisomy 21, usually from meiotic non-disjunction; occasionally translocation or mosaicism.", pathophysiology: "An extra copy of chromosome 21 over-expresses its genes, producing the physical features, learning disability and associated conditions.", presentation: "Hypotonia, flat facial profile, upslanting palpebral fissures, single palmar crease, learning disability; associated congenital heart disease.", investigations: "Antenatal combined or quadruple screening and NIPT; diagnostic CVS or amniocentesis with karyotype.", treatment: "MDT support; screen for cardiac, thyroid, hearing and visual problems; developmental and educational support." },
      { id: "genetics_edwards_patau", cluster: "Autosomal trisomies", name: "Edwards syndrome (trisomy 18)", keyFacts: "The second commonest autosomal trisomy; multiple malformations with very high early mortality.", epidemiology: "Less common than trisomy 21, commoner in girls; incidence rises with maternal age.", aetiology: "Trisomy 18, usually from meiotic non-disjunction.", pathophysiology: "An extra chromosome 18 severely disrupts development, causing multi-system malformations that few survive beyond infancy.", presentation: "Low birthweight, micrognathia (small chin), clenched hands with overlapping fingers, rocker-bottom feet, and cardiac and renal defects.", investigations: "Antenatal combined/quadruple screening and NIPT, anomaly ultrasound, diagnostic karyotype (CVS or amniocentesis).", treatment: "Largely supportive and palliative; most die in the first year; specialist neonatal and family support." },
      { id: "genetics_patau", cluster: "Autosomal trisomies", name: "Patau syndrome (trisomy 13)", keyFacts: "Trisomy 13; severe midline and multi-system malformations with very high early mortality.", epidemiology: "Rarer than trisomies 21 and 18; incidence rises with maternal age.", aetiology: "Trisomy 13, usually from meiotic non-disjunction.", pathophysiology: "An extra chromosome 13 disrupts midline development, causing the characteristic anomalies; most affected babies do not survive infancy.", presentation: "Cleft lip and palate, microcephaly, holoprosencephaly, polydactyly, microphthalmia and cardiac defects.", investigations: "Antenatal screening and NIPT, anomaly ultrasound, diagnostic karyotype.", treatment: "Largely supportive and palliative; specialist neonatal and family support." },
      { id: "genetics_turner", cluster: "Sex-chromosome disorders", name: "Turner syndrome (45,X0)", keyFacts: "A female with a single X chromosome, causing short stature and ovarian failure.", epidemiology: "Affects roughly 1 in 2500 live female births.", aetiology: "Loss of all or part of one X chromosome (45,X), arising sporadically.", pathophysiology: "Haploinsufficiency of X-chromosome genes impairs ovarian, skeletal and cardiovascular development.", presentation: "Short stature, webbed neck, widely spaced nipples, primary amenorrhoea, coarctation of the aorta; intelligence usually normal.", investigations: "Karyotype (45,X), raised FSH and LH, echocardiogram, renal ultrasound.", treatment: "Growth hormone, oestrogen replacement to induce puberty, surveillance of cardiac and renal anomalies." },
      { id: "genetics_klinefelter", cluster: "Sex-chromosome disorders", name: "Klinefelter syndrome (47,XXY)", keyFacts: "A male with an extra X chromosome, causing hypogonadism and infertility.", epidemiology: "A common sex-chromosome disorder, often found during infertility work-up.", aetiology: "An additional X chromosome (47,XXY) from non-disjunction.", pathophysiology: "The extra X impairs testicular development, reducing testosterone and sperm production.", presentation: "Tall stature, small firm testes, gynaecomastia, reduced secondary sexual characteristics and infertility.", investigations: "Karyotype (47,XXY); low testosterone with raised LH and FSH.", treatment: "Testosterone replacement, fertility counselling, psychological and educational support." },
      { id: "genetics_digeorge", cluster: "Microdeletion & imprinting", name: "DiGeorge syndrome (22q11 deletion)", keyFacts: "A 22q11.2 microdeletion causing the CATCH-22 features; the commonest microdeletion syndrome.", epidemiology: "Affects about 1 in 4000; usually a sporadic de novo deletion.", aetiology: "Microdeletion of chromosome 22q11.2, disrupting third and fourth pharyngeal pouch development.", pathophysiology: "Defective pharyngeal pouch development causes thymic and parathyroid hypoplasia and cardiac outflow defects, hence T-cell immunodeficiency and hypocalcaemia.", presentation: "CATCH-22: Cardiac defects (e.g. tetralogy of Fallot), Abnormal facies, Thymic hypoplasia (T-cell immunodeficiency), Cleft palate, Hypocalcaemia (hypoparathyroidism); learning and psychiatric difficulties.", investigations: "FISH or microarray for the 22q11.2 deletion; calcium, lymphocyte subsets, echocardiogram.", treatment: "MDT: correct cardiac defects, manage hypocalcaemia, immunology follow-up (avoid live vaccines if significant immunodeficiency); developmental support." },
      { id: "genetics_silver_russell", cluster: "Microdeletion & imprinting", name: "Silver-Russell syndrome", keyFacts: "An imprinting disorder causing severe intrauterine and postnatal growth restriction with a relatively large head.", epidemiology: "Rare; usually sporadic.", aetiology: "An imprinting disorder, most often loss of methylation at chromosome 11p15 or maternal uniparental disomy of chromosome 7.", pathophysiology: "Disrupted imprinting of growth-regulating genes impairs growth, producing the characteristic small size and body asymmetry.", presentation: "Intrauterine and postnatal growth restriction, a relatively large head (pseudohydrocephaly), a triangular face, body asymmetry and feeding difficulties.", investigations: "Clinical scoring (Netchine-Harbison); molecular testing for 11p15 methylation and chromosome 7 uniparental disomy.", treatment: "MDT: nutritional support, growth hormone therapy, and monitoring of growth and development." },
      { id: "genetics_huntingtons", cluster: "Single-gene disorders", name: "Huntington's disease", keyFacts: "A progressive autosomal dominant neurodegenerative disease with chorea and dementia.", epidemiology: "Uncommon, usually presenting in mid-adulthood.", aetiology: "An expanded CAG trinucleotide repeat in the huntingtin gene, showing anticipation.", pathophysiology: "The mutant protein causes progressive loss of striatal neurons, producing movement, cognitive and psychiatric decline.", presentation: "Autosomal dominant CAG trinucleotide repeat; mid-adult onset chorea, behavioural change and dementia; shows anticipation.", investigations: "Genetic testing for the CAG repeat expansion, with counselling; family history.", treatment: "No cure; symptomatic management and MDT support; predictive testing only with careful pre- and post-test counselling." },
      { id: "genetics_marfan", cluster: "Single-gene disorders", name: "Marfan syndrome", keyFacts: "An autosomal dominant connective-tissue disorder whose major danger is aortic dissection.", epidemiology: "Uncommon, often with a positive family history.", aetiology: "Mutations in the fibrillin-1 (FBN1) gene, inherited dominantly.", pathophysiology: "Defective fibrillin weakens connective tissue, causing tall stature, lens dislocation and a dilatation-prone aorta.", presentation: "Autosomal dominant fibrillin-1 defect; tall with long limbs, arachnodactyly, lens dislocation, aortic root dilatation and dissection risk.", investigations: "Clinical (Ghent) criteria, echocardiogram, ophthalmology review, genetic testing.", treatment: "Beta-blocker or ARB to slow aortic dilatation, activity advice, lifelong aortic surveillance, surgery for the aortic root." },
      { id: "genetics_nf1", cluster: "Single-gene disorders", name: "Neurofibromatosis type 1", keyFacts: "An autosomal dominant neurocutaneous disorder with cafe-au-lait spots and neurofibromas.", epidemiology: "One of the commoner single-gene disorders.", aetiology: "Mutations in the NF1 tumour-suppressor gene, inherited dominantly with a high new-mutation rate.", pathophysiology: "Loss of neurofibromin, a tumour suppressor, predisposes to nerve-sheath tumours and the other features.", presentation: "Autosomal dominant; cafe-au-lait macules, cutaneous neurofibromas, axillary freckling, Lisch nodules; tumour and learning risk.", investigations: "Clinical diagnostic criteria, ophthalmology, imaging for complications.", treatment: "Surveillance for hypertension, tumours and scoliosis; MDT care and genetic counselling." },
      { id: "genetics_cf", cluster: "Single-gene disorders", name: "Cystic fibrosis", keyFacts: "The commonest serious autosomal recessive disease in white populations, affecting multiple organs.", epidemiology: "Carrier frequency is around 1 in 25 in white Europeans; detected on newborn screening.", aetiology: "Mutations in the CFTR gene (commonly delta-F508), inherited recessively.", pathophysiology: "Defective CFTR chloride channels produce thick secretions that obstruct the lungs, pancreas and gut, with recurrent infection.", presentation: "Autosomal recessive CFTR defect; recurrent chest infections, steatorrhoea, failure to thrive, meconium ileus, male infertility.", investigations: "Newborn bloodspot screening, sweat test (high chloride), CFTR genetic testing.", treatment: "Airway clearance physiotherapy, pancreatic enzyme replacement, CFTR modulators, prompt treatment of infection; specialist MDT." },
      { id: "genetics_haemochromatosis", cluster: "Single-gene disorders", name: "Hereditary haemochromatosis", keyFacts: "An autosomal recessive iron-overload disorder, treated effectively by venesection.", epidemiology: "Common in people of northern European descent, though many carriers never develop disease.", aetiology: "Mutations in the HFE gene (commonly C282Y), inherited recessively.", pathophysiology: "Excessive intestinal iron absorption deposits iron in the liver, pancreas, heart and joints, causing organ damage.", presentation: "Autosomal recessive HFE defect causing iron overload; fatigue, arthralgia, bronze skin, diabetes and hepatomegaly.", investigations: "Raised ferritin and transferrin saturation, HFE genotyping, LFTs.", treatment: "Regular venesection; avoid iron and vitamin C supplements and alcohol; screen relatives." },
      { id: "genetics_fragile_x", cluster: "Single-gene disorders", name: "Fragile X syndrome", keyFacts: "The commonest inherited cause of learning disability, more severe in males.", epidemiology: "Affects roughly 1 in 4000 males.", aetiology: "An expanded CGG repeat silencing the FMR1 gene on the X chromosome.", pathophysiology: "Loss of the FMR1 protein, needed for synaptic development, impairs cognition and causes the physical features.", presentation: "Commonest inherited cause of learning disability; long face, large ears, macro-orchidism, autistic features; FMR1 CGG repeat.", investigations: "Molecular genetic testing for the FMR1 CGG repeat expansion.", treatment: "Educational and behavioural support, MDT input, family genetic counselling and cascade testing." },
      { id: "genetics_dmd", cluster: "Single-gene disorders", name: "Duchenne muscular dystrophy", keyFacts: "A severe X-linked recessive muscular dystrophy causing progressive weakness in boys.", epidemiology: "The commonest childhood muscular dystrophy, affecting boys.", aetiology: "Frameshift mutations in the dystrophin gene, inherited X-linked recessively.", pathophysiology: "Absent dystrophin leaves muscle fibres fragile, so they degenerate progressively and are replaced by fat and fibrosis.", presentation: "X-linked recessive dystrophin defect; boys with delayed walking, Gower's sign, calf pseudohypertrophy and progressive proximal weakness.", investigations: "Markedly raised creatine kinase, genetic testing, occasionally muscle biopsy.", treatment: "Corticosteroids, physiotherapy, cardiac and respiratory surveillance, MDT; carrier testing for female relatives." },
      { id: "genetics_colour_blindness", cluster: "Single-gene disorders", name: "Colour blindness", keyFacts: "The commonest inherited visual defect; usually X-linked recessive red-green colour blindness, so mainly affects males.", epidemiology: "Affects about 8% of males and under 1% of females.", aetiology: "Usually X-linked recessive mutations in the red (OPN1LW) or green (OPN1MW) cone opsin genes; rarer autosomal forms exist.", pathophysiology: "Absent or abnormal cone photopigment impairs colour discrimination, most often of red from green.", presentation: "Difficulty distinguishing red and green (rarely blue-yellow), often noticed in childhood or on occupational testing; female carriers are usually unaffected.", investigations: "Ishihara pseudoisochromatic plates; formal colour-vision testing (e.g. Farnsworth) where needed.", treatment: "No cure; advice and occupational support; tinted lenses help some; exclude acquired causes if of new onset." },
      { id: "genetics_hereditary_cancer", cluster: "Hereditary cancer syndromes", name: "Hereditary cancer syndromes", keyFacts: "Inherited mutations that strongly raise cancer risk, warranting genetic referral and surveillance.", epidemiology: "Account for a minority of cancers but a high lifetime risk in carriers.", aetiology: "Germline mutations such as BRCA1/2, Lynch (mismatch repair) and FAP (APC).", pathophysiology: "A germline mutation in a tumour-suppressor or repair gene means only one further hit is needed, so cancers arise early and often.", presentation: "BRCA1/BRCA2 (breast and ovarian), Lynch syndrome (colorectal and endometrial), familial adenomatous polyposis (hundreds of colonic polyps).", investigations: "Detailed family history, referral to clinical genetics, gene panel testing.", treatment: "Enhanced surveillance, risk-reducing surgery or medication, cascade testing of relatives." },
      { id: "genetics_lynch", cluster: "Hereditary cancer syndromes", name: "Lynch syndrome", keyFacts: "Hereditary non-polyposis colorectal cancer: the commonest inherited bowel-cancer syndrome, with a high colorectal and endometrial cancer risk.", epidemiology: "Accounts for a few percent of colorectal cancers; autosomal dominant.", aetiology: "Autosomal dominant germline mutation in a DNA mismatch-repair gene (MLH1, MSH2, MSH6 or PMS2).", pathophysiology: "Defective mismatch repair causes microsatellite instability, so cancers (especially right-sided colorectal and endometrial) arise early without the many polyps of FAP.", presentation: "Early-onset colorectal cancer (often right-sided) and endometrial cancer with a strong family history; also ovarian, gastric and other cancers (Amsterdam criteria).", investigations: "Tumour testing for mismatch-repair deficiency or microsatellite instability; germline genetic testing; detailed family history.", treatment: "Regular colonoscopic surveillance, consider aspirin, risk-reducing surgery (e.g. hysterectomy); cascade testing of relatives." },
      { id: "genetics_counselling", cluster: "Genetic counselling & testing", name: "Genetic counselling & testing", presentation: "Supporting informed choices about inherited risk through predictive, diagnostic and carrier testing.", investigations: "Detailed pedigree, appropriate consent, and choice of test (single gene, panel, karyotype or microarray).", treatment: "Non-directive counselling, cascade testing, reproductive options (prenatal and preimplantation), psychological support." },
    ],
  },
  {
    id: "reproductive",
    name: "Reproductive & Sexual Health",
    icon: "⚕️",
    itemNoun: "topics",
    conditions: [
      { id: "repro_menorrhagia", management: {"def": "A[\"Heavy menstrual bleeding\"]:::start --> H[\"Check FBC; USS/biopsy if indicated\"]:::process\nA --> B[\"First-line: LNG-IUS\"]:::good\nB --> C{\"IUS declined or unsuitable?\"}:::decision\nC -- \"non-hormonal / wants to conceive\" --> D[\"Tranexamic acid +/- NSAID\"]:::good\nC -- \"hormonal acceptable\" --> E[\"COCP or cyclical progestogen\"]:::good\nD --> F{\"Medical treatment failed?\"}:::decision\nE --> F\nF -- \"yes\" --> G[\"Refer: ablation or hysterectomy\"]:::warn", "tips": {"A": "Excessive menstrual blood loss affecting quality of life; this pathway is for no or small (<3 cm) fibroids without uterine distortion (NICE NG88).", "B": "First-line is the levonorgestrel-releasing intrauterine system, if long-term use is acceptable.", "C": "If the IUS is declined or unsuitable, choose by whether hormonal treatment is acceptable and by fertility wishes.", "D": "Non-hormonal (or trying to conceive): tranexamic acid (antifibrinolytic) and/or an NSAID such as mefenamic acid during menses; NSAIDs also ease pain.", "E": "Hormonal alternatives: a combined oral contraceptive pill or cyclical oral progestogen.", "F": "Reassess if medical treatment fails to control bleeding.", "G": "Refer for surgery: endometrial ablation (completed family) or hysterectomy; myomectomy/uterine artery embolisation if large fibroids.", "H": "Check a full blood count (iron-deficiency anaemia); arrange ultrasound and/or endometrial biopsy if fibroids/polyps or risk factors for endometrial cancer (persistent intermenstrual bleeding, age 45+ with treatment failure)."}}, cluster: "Menstrual disorders", name: "Heavy menstrual bleeding", keyFacts: "Excessive menstrual blood loss that affects quality of life and can cause anaemia.", epidemiology: "A very common gynaecological complaint.", aetiology: "Often no structural cause; also fibroids, polyps, adenomyosis, coagulopathy and copper coils.", pathophysiology: "Disordered endometrial haemostasis, or structural lesions, increase menstrual blood loss.", presentation: "Excessive menstrual loss affecting quality of life, possible anaemia.", investigations: "FBC, pelvic exam, ultrasound; biopsy if risk factors.", treatment: "LNG-IUS first line; tranexamic/mefenamic acid; hormonal options; treat cause." },
      { id: "repro_dysmenorrhoea", cluster: "Menstrual disorders", name: "Dysmenorrhoea", keyFacts: "Painful periods; primary (no pathology) or secondary (to an underlying gynaecological condition).", epidemiology: "Very common, especially in younger women (primary).", aetiology: "Primary: prostaglandin-mediated with no pathology. Secondary: endometriosis, adenomyosis, fibroids, pelvic inflammatory disease, copper coil.", pathophysiology: "Excess endometrial prostaglandins cause painful uterine contractions and ischaemia in primary disease; secondary pain reflects the underlying condition.", presentation: "Cramping lower abdominal pain with periods; primary starts soon after menarche, secondary starts later with other features.", investigations: "Primary is clinical; investigate secondary causes with pelvic exam, ultrasound, swabs and laparoscopy.", treatment: "NSAIDs (mefenamic acid) first line; hormonal contraception; treat any underlying secondary cause." },
      { id: "repro_endometriosis", cluster: "Benign gynaecology", name: "Endometriosis", keyFacts: "Endometrial-like tissue outside the uterus causing cyclical pain and subfertility.", epidemiology: "Common in women of reproductive age and a frequent cause of subfertility.", aetiology: "Uncertain; retrograde menstruation with implantation is the leading theory.", pathophysiology: "Ectopic endometrial tissue responds to cyclical hormones, bleeding and provoking inflammation, adhesions and pain.", presentation: "Cyclical pelvic pain, dysmenorrhoea, dyspareunia, subfertility.", investigations: "Pelvic exam, ultrasound; laparoscopy is definitive.", treatment: "Analgesia, hormonal suppression (COCP, progestogen); surgical excision; fertility support." },
      { id: "repro_fibroids", cluster: "Benign gynaecology", name: "Uterine fibroids", keyFacts: "Benign smooth-muscle (leiomyoma) tumours of the uterus; common and oestrogen-dependent.", epidemiology: "Very common, especially in women of African descent and around the 40s; regress after menopause.", aetiology: "Oestrogen- and progesterone-dependent benign tumours, with genetic and ethnic factors.", pathophysiology: "Benign monoclonal smooth-muscle proliferation whose growth is hormone-driven, so fibroids shrink after the menopause.", presentation: "Often asymptomatic; heavy or prolonged periods, bulk symptoms (pressure, urinary frequency) and subfertility; an enlarged, irregular uterus.", investigations: "Pelvic exam and ultrasound; FBC for anaemia; MRI before intervention.", treatment: "Tranexamic acid/NSAIDs or LNG-IUS for bleeding; GnRH analogues to shrink; myomectomy, uterine artery embolisation or hysterectomy." },
      { id: "repro_pcos", cluster: "Benign gynaecology", name: "Polycystic ovary syndrome", keyFacts: "A common endocrine disorder with irregular cycles, hyperandrogenism and metabolic risk.", epidemiology: "Affects up to 1 in 10 women of reproductive age.", aetiology: "Multifactorial, with insulin resistance and a genetic predisposition.", pathophysiology: "Insulin resistance and raised androgens disrupt follicular development, causing anovulation, hirsutism and metabolic features.", presentation: "Irregular periods, hirsutism, acne, weight gain, subfertility.", investigations: "Rotterdam criteria; testosterone, LH/FSH, ultrasound; screen metabolic risk.", treatment: "Weight management, COCP for cycle/hirsutism, metformin; ovulation induction for fertility." },
      { id: "repro_candidiasis", cluster: "Vaginitis & sexually transmitted infection", name: "Vaginal candidiasis", keyFacts: "Vaginal thrush: a common fungal infection causing itch and a thick white discharge; not sexually transmitted.", epidemiology: "Very common; most women have at least one episode.", aetiology: "Overgrowth of Candida albicans, favoured by pregnancy, diabetes, antibiotics and immunosuppression.", pathophysiology: "Disruption of the normal vaginal flora lets Candida overgrow and inflame the mucosa.", presentation: "Vulval itch and soreness with a thick, white, non-offensive cottage-cheese discharge and vulval erythema.", investigations: "Usually clinical; high vaginal swab if recurrent or uncertain; check glucose if recurrent.", treatment: "Topical or oral antifungal (clotrimazole pessary or oral fluconazole); treat the cause of recurrence; use topical agents in pregnancy (avoid oral fluconazole)." },
      { id: "repro_bv", cluster: "Vaginitis & sexually transmitted infection", name: "Bacterial vaginosis", keyFacts: "An overgrowth of anaerobes causing a thin, fishy-smelling discharge; not a sexually transmitted infection and usually not itchy.", epidemiology: "The commonest cause of abnormal vaginal discharge in women of reproductive age.", aetiology: "Loss of lactobacilli and overgrowth of anaerobes (Gardnerella vaginalis); associated with douching and new partners.", pathophysiology: "A rise in vaginal pH as lactobacilli are replaced by anaerobes; it raises the risk of preterm birth in pregnancy.", presentation: "Thin, grey-white, offensive fishy-smelling discharge without itch or soreness.", investigations: "High vaginal swab; Amsel criteria; clue cells on microscopy; raised vaginal pH (over 4.5).", treatment: "Oral or vaginal metronidazole; avoid douching; treat in pregnancy because of the preterm-birth risk." },
      { id: "repro_trichomoniasis", cluster: "Vaginitis & sexually transmitted infection", name: "Trichomoniasis", keyFacts: "A sexually transmitted protozoal infection causing an offensive frothy discharge and a strawberry cervix.", epidemiology: "A common sexually transmitted infection.", aetiology: "The flagellated protozoan Trichomonas vaginalis, sexually transmitted.", pathophysiology: "The protozoan infects the vaginal and urethral epithelium, provoking inflammation.", presentation: "Offensive yellow-green frothy discharge, vulval itch and soreness, and dysuria; a punctate strawberry cervix.", investigations: "High vaginal swab (posterior fornix) for microscopy (motile trophozoites) or NAAT; full STI screen.", treatment: "Oral metronidazole; partner notification and treatment; screen for other sexually transmitted infections." },
      { id: "repro_chlamydia", cluster: "Vaginitis & sexually transmitted infection", name: "Chlamydia", keyFacts: "The commonest bacterial sexually transmitted infection, often asymptomatic and a cause of subfertility.", epidemiology: "Most common in sexually active people under 25.", aetiology: "Chlamydia trachomatis, transmitted sexually.", pathophysiology: "The organism infects the genital mucosa; untreated, it can ascend to cause pelvic inflammatory disease and tubal damage.", presentation: "Often asymptomatic; discharge, dysuria, pelvic pain; commonest bacterial STI.", investigations: "Nucleic acid amplification test (vulvovaginal swab or first-void urine).", treatment: "Doxycycline; partner notification and treatment; test for other STIs; retest if indicated." },
      { id: "repro_pid", management: {"source": "BASHH", "def": "A[\"Pelvic inflammatory disease\"]:::start --> B[\"Low threshold to treat, do not wait for swabs\"]:::process\nB --> C[\"Empirical: ceftriaxone + doxycycline + metronidazole\"]:::good\nC --> D[\"Remove IUD only if no improvement (consider)\"]:::process\nD --> E[\"Test and treat partners, screen for STIs\"]:::good\nA -- \"severe / abscess / pregnant / unsure\" --> F[\"Admit for IV antibiotics, image for abscess\"]:::danger", "tips": {"A": "Ascending infection of the upper female genital tract (endometritis, salpingitis), usually from STIs (chlamydia, gonorrhoea): pelvic pain, deep dyspareunia, discharge and cervical motion tenderness.", "B": "Have a low threshold to start treatment (BASHH) - delay risks infertility, chronic pain and ectopic pregnancy; take endocervical or vaginal swabs and a pregnancy test but do not wait for results.", "C": "Empirical outpatient antibiotics: a single IM ceftriaxone plus oral doxycycline and metronidazole for 14 days.", "D": "Do not routinely remove an intrauterine device; consider removal if there is no improvement after a few days (weighing contraceptive needs).", "E": "Advise no sex until treated, test and treat sexual partners, and offer a full STI screen.", "F": "Admit for IV antibiotics if severe (fever, pelvic peritonitis), a tubo-ovarian abscess, pregnancy, no response to oral treatment, or diagnostic uncertainty (may need laparoscopy)."}}, cluster: "Vaginitis & sexually transmitted infection", name: "Pelvic inflammatory disease", keyFacts: "Infection of the upper female genital tract; a key cause of subfertility and ectopic pregnancy.", epidemiology: "Commonest in young, sexually active women.", aetiology: "Usually ascending sexually transmitted organisms (chlamydia, gonorrhoea).", pathophysiology: "Ascending infection inflames the uterus, tubes and ovaries, and the resulting scarring damages the tubes.", presentation: "Lower abdominal pain, deep dyspareunia, abnormal bleeding/discharge, cervical motion tenderness.", investigations: "STI screen, pregnancy test, pelvic exam.", treatment: "Low threshold for empirical antibiotics; partner treatment; counsel on fertility risk." },
      { id: "repro_endometrial_cancer", cluster: "Gynaecological cancers", name: "Endometrial cancer", keyFacts: "The commonest gynaecological cancer; postmenopausal bleeding is endometrial cancer until proven otherwise.", epidemiology: "Mainly postmenopausal women, with incidence rising alongside obesity.", aetiology: "Unopposed oestrogen: obesity, nulliparity, late menopause, PCOS, tamoxifen, oestrogen-only HRT; and Lynch syndrome.", pathophysiology: "Oestrogen unopposed by progesterone drives endometrial hyperplasia, which can progress to adenocarcinoma.", presentation: "Postmenopausal bleeding, or abnormal and intermenstrual bleeding in younger women.", investigations: "Transvaginal ultrasound (endometrial thickness), endometrial (pipelle) biopsy or hysteroscopy, staging MRI.", treatment: "Total hysterectomy with bilateral salpingo-oophorectomy; radiotherapy or chemotherapy by stage; 2-week-wait referral." },
      { id: "repro_ovarian_cancer", cluster: "Gynaecological cancers", name: "Ovarian cancer", keyFacts: "Often presents late with vague symptoms, hence its high mortality; suspect it in a woman with persistent bloating.", epidemiology: "Commoner in postmenopausal women and the leading cause of gynaecological cancer death.", aetiology: "Risk rises with more lifetime ovulations (nulliparity, early menarche, late menopause) and with BRCA1/2 and Lynch syndrome; reduced by the COCP and pregnancy.", pathophysiology: "Most are epithelial carcinomas (often high-grade serous), spreading transcoelomically across the peritoneum.", presentation: "Persistent bloating, early satiety, abdominal or pelvic pain, urinary urgency, a pelvic mass or ascites; often late.", investigations: "CA-125 then ultrasound; Risk of Malignancy Index; CT for staging; refer to gynae-oncology if high risk.", treatment: "Surgical debulking (hysterectomy, bilateral salpingo-oophorectomy, omentectomy) and platinum-based chemotherapy; 2-week-wait referral." },
      { id: "repro_vulval_cancer", cluster: "Gynaecological cancers", name: "Vulval cancer", keyFacts: "An uncommon cancer of the vulva, usually squamous; presents with a lump, ulcer or persistent itch.", epidemiology: "Mainly elderly women, with a minority (HPV-related) in younger women.", aetiology: "Lichen sclerosus and differentiated VIN in older women; HPV-related usual-type VIN in younger women; smoking.", pathophysiology: "Most are squamous cell carcinomas arising from a precursor (vulval intraepithelial neoplasia) or chronic inflammation.", presentation: "A vulval lump, ulcer or plaque with persistent itch, pain or bleeding, often on the labia.", investigations: "Examination and biopsy; assess the groin nodes; imaging for staging.", treatment: "Wide local excision or vulvectomy with groin node assessment; radiotherapy; 2-week-wait referral." },
      { id: "repro_contraception", cluster: "Contraception & menopause", name: "Contraception", fieldLabels: ["📋 Overview", "🔍 Assessment", "💊 Methods & options"], presentation: "Choosing a method by efficacy, medical eligibility and preference.", investigations: "History, BP, BMI, UKMEC eligibility; exclude pregnancy.", treatment: "LARC (implant, IUD/IUS) most effective; COCP cautions (migraine with aura, VTE risk); counsel on use." },
      { id: "repro_emergency_contra", cluster: "Contraception & menopause", name: "Emergency contraception", fieldLabels: ["📋 Indication", "🔍 Assessment", "💊 Options"], presentation: "Requested after unprotected sex or method failure.", investigations: "Timing since intercourse, cycle, medical history.", treatment: "Copper IUD most effective (up to 5 days); ulipristal or levonorgestrel; advise ongoing contraception." },
      { id: "repro_menopause", cluster: "Contraception & menopause", name: "Menopause & HRT", keyFacts: "The permanent cessation of menstruation from ovarian failure, with vasomotor and genitourinary symptoms.", epidemiology: "Occurs at an average age of around 51.", aetiology: "Natural ovarian follicular depletion; also surgical, chemotherapy or radiotherapy-induced.", pathophysiology: "Falling oestrogen from ovarian failure causes hot flushes, genitourinary atrophy and accelerated bone loss.", presentation: "Vasomotor symptoms, mood and genitourinary change around 51 with amenorrhoea.", investigations: "Clinical; FSH only in selected cases.", treatment: "HRT (oestrogen plus progestogen if uterus present); vaginal oestrogen; lifestyle; discuss risks/benefits." },
      { id: "repro_ectopic", management: {"def": "A[\"Ectopic pregnancy\"]:::start --> B{\"Haemodynamically unstable?\"}:::decision\nB -- \"yes (rupture, shock)\" --> C[\"Resuscitate, emergency surgery (salpingectomy)\"]:::danger\nB -- \"no\" --> D[\"TV ultrasound and serial serum hCG\"]:::process\nD --> E{\"Suitable for medical or expectant?\"}:::decision\nE -- \"small, low hCG, minimal symptoms\" --> F[\"Methotrexate or expectant management\"]:::good\nE -- \"larger, higher hCG, pain\" --> G[\"Laparoscopic salpingectomy (or salpingotomy)\"]:::good\nA --> H[\"Anti-D if rhesus negative and surgical\"]:::process", "tips": {"A": "Implantation outside the uterine cavity (usually a fallopian tube): amenorrhoea then pelvic pain and bleeding at 6-8 weeks; the danger is rupture and haemorrhage.", "B": "First assess haemodynamic stability - a ruptured ectopic with shock is a surgical emergency.", "C": "Unstable or ruptured: resuscitate (ABC, IV access, crossmatch) and proceed to emergency laparoscopy or laparotomy (usually salpingectomy).", "D": "Stable: transvaginal ultrasound (empty uterus with an adnexal mass) and serial serum beta-hCG (a suboptimal rise or plateau suggests ectopic).", "E": "Choose management by size, hCG level, symptoms and patient factors (NICE NG126).", "F": "Expectant management or single-dose methotrexate for a small, unruptured ectopic with low and falling or plateauing hCG (typically under 1500), minimal pain and no fetal heartbeat, with hCG follow-up.", "G": "Surgery (laparoscopic salpingectomy, or salpingotomy if the other tube is damaged) for larger ectopics, higher hCG, significant pain or a fetal heartbeat.", "H": "Give anti-D immunoglobulin to rhesus-negative women having surgical management."}}, cluster: "Early pregnancy", name: "Ectopic pregnancy", keyFacts: "A pregnancy implanted outside the uterine cavity, usually tubal; rupture is life-threatening.", epidemiology: "Occurs in around 1 in 90 pregnancies.", aetiology: "Anything that damages the tube: previous pelvic inflammatory disease, surgery, coils and assisted conception.", pathophysiology: "The embryo implants in the tube or elsewhere; as it grows it can rupture, causing major intraperitoneal haemorrhage.", presentation: "Lower abdominal pain and bleeding 6–8 weeks after a missed period; shoulder tip pain if ruptured.", investigations: "Urine and serum hCG, transvaginal ultrasound.", treatment: "Expectant, methotrexate or surgery by stability and size; emergency surgery if ruptured." },
      { id: "repro_miscarriage", management: {"def": "A[\"Miscarriage (bleeding in early pregnancy)\"]:::start --> B{\"Haemodynamically stable?\"}:::decision\nB -- \"no (heavy bleeding, shock)\" --> C[\"Resuscitate, urgent surgical evacuation\"]:::danger\nB -- \"yes\" --> D[\"TV ultrasound to confirm and classify\"]:::process\nD --> E{\"Management choice\"}:::decision\nE -- \"expectant\" --> F[\"Wait 7-14 days, repeat scan\"]:::good\nE -- \"medical\" --> G[\"Misoprostol (with mifepristone if missed)\"]:::good\nE -- \"surgical\" --> H[\"Manual or surgical evacuation\"]:::good\nA --> I[\"Anti-D if rhesus negative and surgical\"]:::process", "tips": {"A": "Loss of a pregnancy before 24 weeks; presents with bleeding and/or pain in early pregnancy (threatened, inevitable, incomplete, complete or missed).", "B": "Assess stability first - heavy bleeding with cervical shock or haemodynamic compromise needs urgent resuscitation and evacuation.", "C": "Unstable: resuscitate and arrange urgent surgical management; remove any products sitting in the cervical os (which can cause vagal shock).", "D": "Stable: transvaginal ultrasound confirms viability and type (e.g. no fetal heartbeat, empty sac); serum hCG if a pregnancy of unknown location.", "E": "For a confirmed miscarriage, offer a choice of management (NICE NG126).", "F": "Expectant management first-line for 7-14 days (let it complete naturally) with a repeat scan or pregnancy test - avoid if bleeding heavily, infection or high risk.", "G": "Medical management: vaginal or oral misoprostol (add mifepristone for a missed miscarriage), with analgesia and antiemetics.", "H": "Surgical management: manual vacuum aspiration (under local) or surgical evacuation (under general) - preferred if bleeding heavily, unstable, or by choice.", "I": "Give anti-D immunoglobulin to rhesus-negative women having surgical management."}}, cluster: "Early pregnancy", name: "Miscarriage", keyFacts: "Loss of a pregnancy before 24 weeks, presenting with bleeding and pain.", epidemiology: "Common, occurring in around 1 in 5 recognised pregnancies.", aetiology: "Most often a chromosomal abnormality; also infection, anatomical and endocrine factors.", pathophysiology: "A non-viable pregnancy is expelled, with bleeding and cramping accompanying the process.", presentation: "Vaginal bleeding and pain in early pregnancy; assess viability.", investigations: "Transvaginal ultrasound, serial hCG.", treatment: "Expectant, medical (misoprostol) or surgical management; anti-D if rhesus negative; emotional support." },
      { id: "repro_hyperemesis", management: {"source": "RCOG", "def": "A[\"Hyperemesis gravidarum\"]:::start --> B[\"Assess: PUQE score, ketones, weight loss\"]:::process\nB --> C{\"Tolerating oral intake?\"}:::decision\nC -- \"yes, mild\" --> D[\"Oral antiemetic: cyclizine or promethazine\"]:::good\nC -- \"no / dehydrated / ketotic\" --> E[\"Admit: IV fluids + IV antiemetic\"]:::warn\nE --> F[\"Thiamine, VTE prophylaxis, 2nd-line antiemetics\"]:::good\nA --> G[\"Exclude other causes, USS for molar or multiple\"]:::process", "tips": {"A": "Severe, persistent nausea and vomiting of pregnancy causing dehydration, ketosis, weight loss (over 5%) and electrolyte disturbance - beyond ordinary morning sickness.", "B": "Quantify with the PUQE score and check urinary ketones, weight and electrolytes.", "C": "Whether oral intake stays down decides the setting.", "D": "Mild cases: first-line oral antiemetics - cyclizine, promethazine or prochlorperazine.", "E": "Admit if unable to tolerate oral intake, dehydrated or ketotic: IV rehydration (normal saline with potassium) and IV antiemetics.", "F": "Give thiamine to prevent Wernicke encephalopathy, VTE prophylaxis while admitted, and second-line antiemetics (metoclopramide short-term, or ondansetron with counselling) if needed.", "G": "Exclude other causes and consider a molar or multiple pregnancy (ultrasound); check thyroid function."}}, cluster: "Early pregnancy", name: "Hyperemesis gravidarum", keyFacts: "Severe, persistent vomiting in pregnancy causing dehydration, weight loss and electrolyte disturbance, beyond ordinary morning sickness.", epidemiology: "Affects around 1% of pregnancies, in the first trimester.", aetiology: "Driven by high beta-hCG; commoner in multiple and molar pregnancies.", pathophysiology: "High human chorionic gonadotrophin (hCG) and oestrogen stimulate nausea and vomiting, leading to dehydration and ketosis.", presentation: "Protracted vomiting with over 5% weight loss, dehydration and ketosis in early pregnancy (the classic triad).", investigations: "Weight, urine ketones, U&E (hypokalaemia, hyponatraemia), FBC, ultrasound (multiple or molar); PUQE score.", treatment: "IV fluids with potassium, antiemetics (cyclizine or promethazine, then ondansetron or metoclopramide) and thiamine; VTE prophylaxis; admit if severe." },
      { id: "repro_antenatal", cluster: "Antenatal & obstetric", name: "Antenatal care", fieldLabels: ["📋 Overview", "🔍 Checks & screening", "✅ Care & advice"], presentation: "Routine schedule of checks to optimise maternal and fetal health.", investigations: "Booking bloods, BP, urine, growth, screening (Down's, anomaly scan).", treatment: "Folic acid and vitamin D, lifestyle advice, vaccinations, monitor for complications." },
      { id: "repro_gestational_htn", cluster: "Antenatal & obstetric", name: "Gestational hypertension", keyFacts: "New hypertension after 20 weeks WITHOUT proteinuria or end-organ features; monitor closely as it can progress to pre-eclampsia.", epidemiology: "Common in pregnancy, especially first pregnancies.", aetiology: "Risk factors as for pre-eclampsia: first pregnancy, obesity, extremes of age, diabetes, chronic hypertension and multiple pregnancy.", pathophysiology: "A pregnancy-related rise in blood pressure without the multisystem features of pre-eclampsia, though a proportion progress to it.", presentation: "New hypertension (over 140/90) after 20 weeks with no proteinuria and no end-organ involvement, in a previously normotensive woman.", investigations: "Serial blood pressure, urine protein (PCR) to exclude pre-eclampsia, bloods (FBC, LFT, U&E), fetal growth monitoring.", treatment: "Labetalol (or nifedipine or methyldopa); monitor for progression to pre-eclampsia; usually resolves after delivery." },
      { id: "repro_preeclampsia", management: {"def": "A[\"Pre-eclampsia\"]:::start --> B[\"Confirm: BP 140/90+ and proteinuria after 20 wks\"]:::process\nB --> C[\"Antihypertensive: labetalol first-line\"]:::good\nC --> D[\"Monitor BP, bloods, fetal growth\"]:::process\nD --> E{\"Severe features or term?\"}:::decision\nE -- \"severe / eclampsia\" --> F[\"IV magnesium sulfate, stabilise\"]:::danger\nF --> G[\"Deliver the baby (definitive)\"]:::good\nE -- \"stable, preterm\" --> H[\"Expectant care, close monitoring\"]:::good\nA --> I[\"Prevention: aspirin from 12 wks if high risk\"]:::process", "tips": {"A": "New hypertension with proteinuria (or organ dysfunction) after 20 weeks; delivery is the only cure. Watch for headache, visual disturbance, epigastric pain and hyperreflexia.", "B": "Diagnose with BP 140/90 mmHg or higher plus proteinuria (PCR 30+ or ACR 8+) or maternal organ/uteroplacental dysfunction after 20 weeks.", "C": "First-line antihypertensive is oral labetalol (nifedipine or methyldopa if contraindicated); target BP 135/85 or lower.", "D": "Monitor blood pressure, FBC, U and Es, LFTs and fetal growth/wellbeing; grade severity.", "E": "Severe or term disease shifts toward magnesium and delivery.", "F": "Severe pre-eclampsia or eclampsia (seizure): IV magnesium sulfate (loading then maintenance) to treat/prevent seizures, plus control BP; watch for magnesium toxicity (reflexes, respiratory rate, urine output).", "G": "Delivery is definitive; timing balances maternal risk against prematurity (give steroids for fetal lungs if preterm).", "H": "If stable and preterm, expectant management with intensive monitoring to gain fetal maturity.", "I": "Give aspirin 75-150 mg daily from 12 weeks to women at high risk of pre-eclampsia."}}, cluster: "Antenatal & obstetric", name: "Pre-eclampsia", keyFacts: "New hypertension with proteinuria after 20 weeks; it can progress to eclampsia (seizures).", epidemiology: "Affects a few percent of pregnancies, more so in first pregnancies.", aetiology: "Risk with first pregnancy, extremes of age, obesity, diabetes, chronic hypertension and prior pre-eclampsia.", pathophysiology: "Abnormal placentation causes widespread endothelial dysfunction, raising blood pressure and damaging the kidneys, liver and brain.", presentation: "New hypertension and proteinuria after 20 weeks; headache, visual change, oedema, epigastric pain.", investigations: "BP, urine PCR, bloods (FBC, LFT, U&E), fetal monitoring.", treatment: "Labetalol, monitor closely, magnesium sulfate to prevent eclampsia; delivery is definitive." },
      { id: "repro_pph", management: {"source": "RCOG", "def": "A[\"Postpartum haemorrhage\"]:::start --> B[\"Call for help, ABC, two large-bore cannulae, crossmatch\"]:::danger\nB --> C{\"Cause? (the 4 Ts)\"}:::decision\nC -- \"Tone (atony, commonest)\" --> D[\"Rub up fundus, then oxytocin, ergometrine, carboprost\"]:::good\nC -- \"Trauma / Tissue / Thrombin\" --> E[\"Repair tears, remove tissue, correct clotting\"]:::good\nD -- \"ongoing bleeding\" --> F[\"Bimanual compression, balloon tamponade\"]:::warn\nF -- \"refractory\" --> G[\"Surgery: B-Lynch, artery ligation, hysterectomy\"]:::danger", "tips": {"A": "Blood loss of 500 mL or more after vaginal birth (1000 mL after caesarean), or any loss causing haemodynamic compromise - an obstetric emergency (RCOG).", "B": "Simultaneously call for help (senior obstetrics, anaesthetics, midwives), resuscitate (ABC, high-flow oxygen, two large-bore cannulae, crossmatch, major haemorrhage protocol) and treat the cause.", "C": "The causes are the 4 Ts: Tone (uterine atony, ~70%), Trauma (tears), Tissue (retained placenta) and Thrombin (coagulopathy).", "D": "For atony (commonest): rub up the fundus and empty the bladder, then give uterotonics in sequence - oxytocin (bolus then infusion), ergometrine, carboprost (avoid in asthma) and misoprostol; give tranexamic acid early.", "E": "Trauma: repair genital-tract tears. Tissue: remove retained placenta (manually in theatre). Thrombin: correct coagulopathy with blood products.", "F": "If bleeding continues despite drugs: bimanual uterine compression and intrauterine balloon tamponade (Bakri).", "G": "Refractory PPH: surgical measures - B-Lynch compression suture, uterine or internal iliac artery ligation, interventional radiology embolisation, and hysterectomy as a life-saving last resort."}}, cluster: "Antenatal & obstetric", name: "Postpartum haemorrhage", keyFacts: "Blood loss over 500 mL after vaginal birth (or 1000 mL after caesarean); a leading cause of maternal death, most often from uterine atony.", epidemiology: "A common and important obstetric emergency.", aetiology: "The 4 Ts: Tone (uterine atony, the commonest), Trauma (tears), Tissue (retained placenta) and Thrombin (coagulopathy).", pathophysiology: "Failure of the uterus to contract and compress the placental-bed vessels (or trauma, retained tissue or coagulopathy) causes major blood loss.", presentation: "Heavy vaginal bleeding after delivery with signs of hypovolaemia; primary within 24 hours, secondary from 24 hours to 12 weeks.", investigations: "Assess blood loss and shock; FBC, clotting and cross-match; identify the cause using the 4 Ts.", treatment: "ABC resuscitation with fluids and blood; uterine massage and uterotonics (oxytocin, ergometrine, carboprost) and tranexamic acid; balloon tamponade or surgery; treat the cause." },
      { id: "repro_afe", cluster: "Antenatal & obstetric", name: "Amniotic fluid embolism", keyFacts: "A rare, unpredictable obstetric emergency in which amniotic fluid and fetal cells enter the maternal circulation, triggering cardiovascular collapse, hypoxia and disseminated intravascular coagulation (DIC), usually during labour or immediately after delivery.", epidemiology: "Rare (around 1-2 per 100,000 maternities) but a leading direct cause of maternal death, with high maternal and neonatal mortality.", aetiology: "Entry of amniotic fluid into the maternal circulation; associations include rapid or tumultuous labour, induction, operative or instrumental delivery, placental abruption, placenta praevia, polyhydramnios and older maternal age.", pathophysiology: "An anaphylactoid reaction to fetal antigens causes acute pulmonary vasoconstriction and right heart failure, then left ventricular failure and profound hypoxia, followed by a consumptive coagulopathy (DIC) with massive haemorrhage.", presentation: "Sudden collapse during labour or within about 30 minutes of delivery: breathlessness, hypoxia, hypotension, seizures and cardiac arrest, followed by torrential haemorrhage from DIC, with fetal distress.", investigations: "A clinical diagnosis of exclusion - do not delay resuscitation; supportive tests include arterial blood gas, full blood count, coagulation screen and fibrinogen, ECG and echocardiography. It is often confirmed only at post-mortem.", treatment: "Immediate ABCDE resuscitation and an emergency multidisciplinary call (obstetrics, anaesthetics, haematology, intensive care); high-flow oxygen with early intubation, circulatory support, prompt delivery of the baby (perimortem caesarean if in arrest), and aggressive treatment of DIC and haemorrhage with blood products.", management: {"source": "Obstetric emergency", "def": "A[\"Sudden collapse in labour or postpartum\"]:::start --> B[\"Call for help: obstetrics, anaesthetics, ICU\"]:::danger\nB --> C[\"ABCDE, high-flow oxygen, early intubation\"]:::good\nC --> D[\"Circulatory support: fluids, vasopressors, monitoring\"]:::good\nD --> E{\"Cardiac arrest?\"}:::decision\nE -- \"yes\" --> F[\"CPR + perimortem caesarean within 5 min\"]:::danger\nE -- \"no, ongoing\" --> G[\"Expedite delivery, then ICU\"]:::good\nD --> H[\"Treat DIC and haemorrhage (blood products)\"]:::warn", "tips": {"A": "Amniotic fluid embolism - sudden maternal cardiovascular collapse, hypoxia and coagulopathy during labour or just after delivery; a clinical diagnosis, so treat immediately.", "B": "Declare an emergency and summon a multidisciplinary team early: senior obstetrics, anaesthetics and intensive care, haematology and the blood bank.", "C": "ABCDE resuscitation: high-flow oxygen and early airway control (often intubation) for profound hypoxia.", "D": "Support the circulation with IV fluids, vasopressors and inotropes, and invasive monitoring; anticipate right heart failure.", "E": "Cardiac arrest shifts the priority to CPR and rapid delivery.", "F": "In arrest, start CPR with left uterine displacement and perform a perimortem caesarean within 5 minutes to aid maternal resuscitation.", "G": "If not in arrest, expedite delivery of the baby and transfer to intensive care.", "H": "Anticipate and treat disseminated intravascular coagulation and massive haemorrhage - activate the major haemorrhage protocol and give blood products (red cells, fresh frozen plasma, platelets, cryoprecipitate or fibrinogen)."}} },
      { id: "repro_breast_lump", cluster: "Breast", name: "Breast lump assessment", fieldLabels: ["📋 Presenting features", "🔍 Triple assessment", "✅ Management & referral"], presentation: "New lump, skin or nipple change, or pain; assess cancer risk.", investigations: "Triple assessment: examination, imaging (mammogram/ultrasound), biopsy.", treatment: "2-week-wait referral for suspicious features; manage benign causes; participate in screening." },
      { id: "repro_mastitis", cluster: "Breast", name: "Mastitis", keyFacts: "Painful breast inflammation, usually during lactation; continue breastfeeding and treat early to prevent an abscess.", epidemiology: "Common in breastfeeding women, especially in the first few weeks.", aetiology: "Milk stasis, often with infection by Staphylococcus aureus entering through a cracked nipple; non-lactational forms also occur.", pathophysiology: "Obstructed milk drainage and inflammation, with or without bacterial infection of the breast tissue.", presentation: "A painful, red, swollen, wedge-shaped area of breast with fever and flu-like symptoms, usually while breastfeeding.", investigations: "Clinical; milk culture if not settling; ultrasound if an abscess is suspected.", treatment: "Continue breastfeeding and effective milk removal; analgesia; flucloxacillin if infection is suspected or it is not improving; drain an abscess; exclude inflammatory cancer if persistent." },
    ],
  },
  {
    id: "paediatrics",
    name: "Paediatrics & Child Health",
    icon: "🧒",
    conditions: [
      { id: "paeds_jaundice", cluster: "Neonatal", name: "Neonatal jaundice", keyFacts: "Yellow discolouration from raised bilirubin in the newborn; within 24 hours it is always pathological.", epidemiology: "Very common, with most physiological jaundice appearing after day 2.", aetiology: "Physiological, breast-milk, haemolysis (rhesus or ABO), sepsis, or biliary atresia when prolonged.", pathophysiology: "Immature bilirubin handling or excess production raises unconjugated bilirubin, which at high levels risks kernicterus.", presentation: "Yellow skin in a newborn; within 24h is always pathological.", investigations: "Bilirubin on treatment threshold chart, blood group/Coombs, FBC.", treatment: "Phototherapy or exchange transfusion by level and age; investigate prolonged jaundice." },
      { id: "paeds_neonatal_sepsis", management: {"def": "A[\"Neonatal sepsis\"]:::start --> B[\"Identify red flags and risk factors\"]:::process\nB --> C[\"Blood culture and investigations (do not delay)\"]:::process\nC --> D[\"IV antibiotics within 1 hour\"]:::danger\nD --> E[\"Benzylpenicillin + gentamicin (early-onset)\"]:::good\nE --> F[\"Review at 36 h: stop if cultures negative and well\"]:::process\nA -- \"meningitis suspected\" --> G[\"Lumbar puncture, broaden antibiotics\"]:::warn", "tips": {"A": "Sepsis in the first 28 days is often non-specific (temperature instability, poor feeding, lethargy, respiratory distress, jaundice); early-onset (under 72 h, usually Group B Strep or E. coli) versus late-onset.", "B": "Assess risk factors (maternal GBS, prolonged rupture of membranes, maternal fever or chorioamnionitis, prematurity) and red-flag clinical features (NICE NG195).", "C": "Take a blood culture and baseline investigations (FBC, CRP) but do NOT let them delay treatment.", "D": "Give IV antibiotics within 1 hour of the decision to treat - neonatal sepsis progresses rapidly.", "E": "The empirical early-onset regimen is IV benzylpenicillin plus gentamicin (per local policy); adjust for late-onset or hospital-acquired cover.", "F": "Reassess at 36 hours with CRP and cultures: stop antibiotics if the baby is well, cultures are negative and CRP is reassuring.", "G": "If meningitis is suspected (or cultures are positive), perform a lumbar puncture and broaden or prolong antibiotics accordingly."}}, cluster: "Neonatal", name: "Neonatal sepsis", keyFacts: "Serious infection in the first 28 days of life; non-specific signs mean a high index of suspicion and prompt antibiotics are vital.", epidemiology: "An important cause of neonatal morbidity and mortality, with risk rising with prematurity.", aetiology: "Early-onset (under 72 hours): group B streptococcus and Escherichia coli. Late-onset: coagulase-negative staphylococci and hospital organisms. Risk factors include maternal group B strep, prolonged rupture of membranes, prematurity and chorioamnionitis.", pathophysiology: "An immature immune system allows rapid spread of infection, often acquired from the maternal genital tract or the environment.", presentation: "Non-specific: temperature instability, poor feeding, lethargy, respiratory distress, jaundice, apnoea, irritability or a bulging fontanelle.", investigations: "Full septic screen: blood cultures, FBC, CRP and lumbar puncture; chest X-ray and urine as indicated.", treatment: "Start empirical IV antibiotics immediately (e.g. benzylpenicillin and gentamicin) without waiting for results; supportive care." },
      { id: "paeds_hdn", cluster: "Neonatal", name: "Haemorrhagic disease of the newborn", keyFacts: "Vitamin K deficiency bleeding in the newborn; preventable by the routine vitamin K given at birth.", epidemiology: "Higher risk in breastfed babies who did not receive vitamin K prophylaxis.", aetiology: "Vitamin K deficiency (poor placental transfer, low levels in breast milk, an immature gut flora); maternal enzyme-inducing drugs increase the risk.", pathophysiology: "Vitamin K is needed to make clotting factors II, VII, IX and X, so deficiency impairs coagulation and causes bleeding.", presentation: "Bruising, bleeding from the umbilical stump or gastrointestinal tract, or intracranial haemorrhage; early, classic (day 2-7) and late forms occur.", investigations: "A prolonged prothrombin time with normal platelets and fibrinogen.", treatment: "Intramuscular vitamin K at birth prevents it; treat bleeding with vitamin K and, if severe, fresh frozen plasma." },
      { id: "paeds_bpd", cluster: "Neonatal", name: "Bronchopulmonary dysplasia", keyFacts: "A chronic lung disease of prematurity, defined as a need for supplemental oxygen or respiratory support at 36 weeks' corrected gestational age; the result of injury to an immature lung.", epidemiology: "Mainly affects very preterm, low-birth-weight infants, particularly those who needed prolonged mechanical ventilation and oxygen; incidence rises with decreasing gestational age.", aetiology: "Injury to a structurally immature lung from mechanical ventilation (barotrauma and volutrauma), oxygen toxicity, infection and inflammation; antenatal factors such as chorioamnionitis contribute.", pathophysiology: "Ventilation and oxygen injure the developing alveoli and pulmonary vasculature, arresting alveolar development (fewer, larger, simplified alveoli) and causing airway inflammation and fibrosis, which impairs gas exchange.", presentation: "A preterm infant with a persistent oxygen requirement, tachypnoea, increased work of breathing, poor weight gain and recurrent respiratory infections; wheeze and exercise limitation may persist into childhood.", investigations: "Largely clinical (oxygen dependence at 36 weeks corrected gestation); chest X-ray shows hyperinflation, cystic change and fibrosis; monitor oxygen saturations and growth.", treatment: "Prevention is key - antenatal corticosteroids, surfactant, gentle ventilation strategies and caffeine. Support with oxygen to maintain saturations, good nutrition, and a short course of corticosteroids (e.g. dexamethasone) to aid ventilator weaning in severe cases; give palivizumab (RSV prophylaxis) and routine immunisations. Most improve as the lungs grow." },
      { id: "paeds_ttn", cluster: "Neonatal", name: "Transient tachypnoea of the newborn", keyFacts: "The commonest cause of neonatal respiratory distress; benign and self-limiting, caused by delayed clearance of fetal lung fluid, and usually resolving within 1-2 days.", epidemiology: "Most common after caesarean section (especially before labour) and in late-preterm and term infants; more common with maternal diabetes.", aetiology: "Delayed reabsorption of the fluid that fills the fetal lungs; labour and passage through the birth canal normally help clear it, so it is commoner after an elective caesarean.", pathophysiology: "Retained alveolar fluid reduces lung compliance and impairs gas exchange, causing tachypnoea and mild respiratory distress until the fluid is reabsorbed.", presentation: "Tachypnoea (respiratory rate over 60) with mild recession, nasal flaring and grunting within the first few hours of life; the baby is otherwise well and it settles within 24-48 hours (up to 72).", investigations: "A diagnosis of exclusion; chest X-ray shows hyperinflation and fluid in the horizontal fissure (wet lung); exclude sepsis and other causes of respiratory distress.", treatment: "Supportive - observation, supplemental oxygen if needed to keep saturations normal, and support with feeding; it is self-limiting. Consider a septic screen and antibiotics if sepsis cannot be excluded." },
      { id: "paeds_cdh", management: {"source": "Neonatal emergency", "def": "A[\"Congenital diaphragmatic hernia\"]:::start --> B[\"Deliver at a tertiary centre (often antenatal diagnosis)\"]:::process\nB --> C[\"Intubate and ventilate, pass wide-bore NG tube to decompress\"]:::danger\nC --> D[\"AVOID bag-and-mask ventilation (distends herniated bowel)\"]:::warn\nD --> E[\"Gentle ventilation, treat pulmonary hypertension\"]:::good\nE --> F{\"Stable?\"}:::decision\nF -- \"yes\" --> G[\"Delayed surgical repair of the defect\"]:::good\nF -- \"no\" --> H[\"Ongoing intensive care, consider ECMO\"]:::warn", "tips": {"A": "A diaphragmatic defect lets abdominal viscera into the chest, causing pulmonary hypoplasia and pulmonary hypertension; a neonatal emergency, most often left-sided and frequently diagnosed antenatally.", "B": "Plan delivery at a centre with neonatal surgery and intensive care; many are picked up on the antenatal anomaly scan.", "C": "At birth, intubate and ventilate, and pass a wide-bore nasogastric tube on free drainage to decompress the stomach and bowel.", "D": "Do NOT use bag-and-mask ventilation - it forces air into the herniated bowel, distending it and further compressing the lungs.", "E": "Use gentle, lung-protective ventilation and treat the pulmonary hypertension (for example inhaled nitric oxide); avoid barotrauma to the hypoplastic lungs.", "F": "Surgery is delayed until the baby is physiologically stable - the emergency is the lung disease and pulmonary hypertension, not the hernia itself.", "G": "Once stable, surgically reduce the viscera and repair the diaphragmatic defect.", "H": "If the baby cannot be stabilised, escalate intensive care and consider extracorporeal membrane oxygenation (ECMO) in selected cases."}}, cluster: "Neonatal", name: "Congenital diaphragmatic hernia", keyFacts: "A defect in the diaphragm that lets abdominal organs herniate into the chest, compressing the developing lung and causing pulmonary hypoplasia and pulmonary hypertension; a neonatal emergency.", epidemiology: "Occurs in about 1 in 2500 births; most are left-sided (through the postero-lateral Bochdalek defect) and many are detected on the antenatal anomaly scan.", aetiology: "Failure of the diaphragm to close in embryonic development; usually sporadic, but can be associated with chromosomal and other congenital anomalies.", pathophysiology: "Herniated bowel (and sometimes stomach, liver or spleen) in the thorax restricts lung growth, so the lungs are hypoplastic with an abnormal pulmonary vasculature, producing severe pulmonary hypertension and impaired gas exchange after birth.", presentation: "Respiratory distress and cyanosis from birth, a scaphoid (sunken) abdomen, reduced breath sounds and displaced heart sounds, sometimes with bowel sounds audible in the chest; often an antenatal diagnosis.", investigations: "Frequently diagnosed on the antenatal ultrasound; postnatal chest and abdominal X-ray shows bowel loops in the thorax with mediastinal shift; echocardiography assesses the pulmonary hypertension and excludes cardiac anomalies.", treatment: "Deliver at a tertiary centre. Immediately intubate and ventilate and pass a wide-bore nasogastric tube to decompress the stomach - AVOID bag-and-mask ventilation, which distends the herniated bowel and worsens lung compression. Stabilise with gentle ventilation and treat the pulmonary hypertension (e.g. inhaled nitric oxide), then repair the defect surgically once stable; consider ECMO if unstable. Prognosis depends on the degree of lung hypoplasia." },
      { id: "paeds_fever", management: {"def": "A[\"Febrile child under 5\"]:::start --> B[\"Assess with the NICE traffic-light system\"]:::process\nB --> C{\"Traffic-light category\"}:::decision\nC -- \"red (high risk)\" --> D[\"Urgent assessment, full septic screen\"]:::danger\nC -- \"amber (intermediate)\" --> E[\"Investigate, observe, safety-net\"]:::warn\nC -- \"green (low risk)\" --> F[\"Manage at home with advice\"]:::good\nA -- \"under 3 months with fever\" --> G[\"Septic screen + IV antibiotics\"]:::danger", "tips": {"A": "Fever in a child under 5 - the priority is to spot serious illness and find any source (NICE traffic light).", "B": "Assess colour, activity, respiratory and circulatory status and hydration, look for a focus, and measure temperature, heart rate, respiratory rate and capillary refill.", "C": "The traffic-light category drives investigation and disposition.", "D": "Any red feature (mottled/blue, unresponsive, grunting, marked tachypnoea, reduced skin turgor, non-blanching rash): high risk - urgent assessment, bloods, cultures, and antibiotics if sepsis is suspected.", "E": "Amber features: investigate (urine, consider bloods/CXR), observe, and give clear safety-netting.", "F": "Green (no amber or red features): usually managed at home with antipyretics as needed and advice on when to seek help.", "G": "Infants under 3 months with fever (38C or above) are high risk regardless of how well they look: full septic screen including lumbar puncture, and empirical IV antibiotics."}}, cluster: "Acute illness, fever & infection", name: "Febrile child", presentation: "Fever in a child; use traffic-light system to grade risk of serious illness.", investigations: "Assess for red flags, source; urine, bloods or septic screen as indicated.", treatment: "Antipyretics for distress, safety-net, treat source; admit amber/red features." },
      { id: "paeds_scarlet_fever", cluster: "Acute illness, fever & infection", name: "Scarlet fever", keyFacts: "A group A streptococcal illness with a sandpaper rash, strawberry tongue and sore throat; a notifiable disease.", epidemiology: "Mainly children aged 2-8, with outbreaks in winter and spring.", aetiology: "An erythrogenic exotoxin-producing group A Streptococcus (Streptococcus pyogenes), usually with a pharyngitis.", pathophysiology: "A streptococcal erythrogenic toxin produces the widespread rash on a background of streptococcal infection.", presentation: "Fever and sore throat, then a fine rough sandpaper-like rash with circumoral pallor, flushed cheeks and a strawberry tongue; the rash peels later.", investigations: "Clinical; throat swab or rapid antigen test; a raised ASO titre.", treatment: "Oral penicillin V (azithromycin if penicillin-allergic); notify public health; exclude from school until 24 hours of antibiotics; watch for rheumatic fever and glomerulonephritis." },
      { id: "paeds_parvovirus", cluster: "Acute illness, fever & infection", name: "Parvovirus B19 infection", keyFacts: "Slapped-cheek disease (erythema infectiosum); usually mild, but dangerous in pregnancy and in haemolytic anaemia.", epidemiology: "Common in school-age children, with spring outbreaks.", aetiology: "Parvovirus B19, spread by respiratory droplets.", pathophysiology: "The virus infects and transiently suppresses red-cell precursors in the bone marrow, which matters in those who rely on high red-cell turnover.", presentation: "Mild fever then a bright red slapped-cheek facial rash followed by a lacy body rash; arthralgia is commoner in adults.", investigations: "Usually clinical; serology (IgM) or PCR if the patient is pregnant or immunocompromised.", treatment: "Supportive in healthy children; in pregnancy it risks hydrops fetalis (refer); it causes aplastic crisis in haemolytic anaemia (e.g. sickle cell, spherocytosis)." },
      { id: "paeds_bronchiolitis", management: {"def": "A[\"Bronchiolitis (infant, RSV)\"]:::start -- \"assess & support\" --> B[\"Supportive care, assess feeding and effort\"]:::process\nB --> C{\"Admission criteria?\"}:::decision\nC -- \"apnoea, poor feeding, sats under 92, distress\" --> D[\"Admit: oxygen, NG or IV fluids\"]:::warn\nC -- \"feeding well, not distressed\" --> E[\"Home with safety-net advice\"]:::good\nD --> F[\"Escalate: high-flow oxygen or CPAP\"]:::danger\nA -- \"avoid\" --> G[\"No routine antibiotics, steroids or bronchodilators\"]:::process", "tips": {"A": "A lower respiratory tract infection of infants (usually under 1 year, commonly RSV): coryza then cough, wheeze/crackles, tachypnoea and feeding difficulty. The two arrows from here are parallel - the assess-and-support pathway and the 'what to avoid' advice both apply, not an either/or choice.", "B": "Management is supportive - assess feeding, hydration, oxygen saturations and work of breathing.", "C": "Decide who needs admission.", "D": "Admit for apnoea, inadequate oral intake (50-75% of normal), respiratory distress, or persistent sats under 92% (NICE): give oxygen and nasogastric or IV fluids.", "E": "If feeding adequately and not distressed, manage at home with clear safety-netting on worsening signs.", "F": "Escalate to high-flow humidified oxygen or CPAP, and consider intensive care, if respiratory failure develops.", "G": "Do NOT routinely use antibiotics, corticosteroids, nebulised adrenaline or bronchodilators - they do not help bronchiolitis."}}, cluster: "Respiratory & airway", name: "Bronchiolitis", keyFacts: "A common viral lower-respiratory infection of infants, managed supportively.", epidemiology: "Affects infants under 1, with winter epidemics.", aetiology: "Respiratory syncytial virus in the great majority of cases.", pathophysiology: "Viral infection inflames and obstructs the small airways (bronchioles), causing wheeze, crackles and feeding difficulty.", presentation: "Coryza then cough, wheeze, poor feeding and respiratory distress in infants under 1; RSV.", investigations: "Clinical; oxygen saturations; NPA if admitted.", treatment: "Supportive: feeding support and oxygen; safety-net; no routine antibiotics or steroids." },
      { id: "paeds_croup", management: {"def": "A[\"Croup (barking cough, stridor)\"]:::start --> B[\"Single oral dexamethasone (all severities)\"]:::good\nB --> C{\"Severity\"}:::decision\nC -- \"mild (no stridor at rest)\" --> D[\"Home with safety-net advice\"]:::good\nC -- \"moderate (stridor at rest)\" --> E[\"Observe in hospital\"]:::good\nC -- \"severe / impending obstruction\" --> F[\"Nebulised adrenaline + oxygen\"]:::danger\nF --> G[\"Call anaesthetics/ENT, keep child calm\"]:::warn", "tips": {"A": "Viral laryngotracheobronchitis (usually parainfluenza) in children 6 months to 3 years: barking cough, inspiratory stridor, hoarseness and low-grade fever, worse at night.", "B": "Give a single dose of oral dexamethasone (0.15 mg/kg) to ALL children with croup regardless of severity (oral prednisolone or nebulised budesonide if unavailable).", "C": "Grade severity (e.g. Westley score) to decide disposition.", "D": "Mild (no stridor or recession at rest): manage at home after the steroid, with advice on when to return.", "E": "Moderate (stridor and recession at rest but not distressed): observe in hospital after the steroid.", "F": "Severe (stridor at rest with marked recession, agitation or lethargy): nebulised adrenaline (fast but wears off) plus oxygen.", "G": "Keep the child calm on the parent's lap (distress worsens obstruction); summon senior paediatric, anaesthetic and ENT help for impending airway obstruction."}}, cluster: "Respiratory & airway", name: "Croup", keyFacts: "A viral upper-airway infection causing a barking cough and stridor, treated with dexamethasone.", epidemiology: "Common in children aged 6 months to 3 years, peaking in autumn.", aetiology: "Parainfluenza virus most commonly.", pathophysiology: "Inflammation and oedema of the larynx and subglottic trachea narrow the airway, causing stridor and the barking cough.", presentation: "Barking cough, stridor and hoarseness with coryza in a young child; worse at night.", investigations: "Clinical; avoid distressing the child.", treatment: "Single dose oral dexamethasone; nebulised adrenaline and admission if severe stridor." },
      { id: "paeds_asthma", cluster: "Respiratory & airway", name: "Childhood asthma", keyFacts: "Recurrent reversible airway obstruction in children, with wheeze and cough; needs a written action plan.", epidemiology: "The commonest chronic disease of childhood.", aetiology: "Atopy and genetic predisposition with triggers including viral infection, allergens and exercise.", pathophysiology: "Airway inflammation and hyper-responsiveness cause reversible bronchoconstriction, mucus and oedema.", presentation: "Recurrent wheeze, cough and breathlessness with triggers and atopy.", investigations: "Clinical pattern; spirometry when old enough.", treatment: "Age-appropriate inhaled therapy with spacer; written action plan; treat acute attacks by severity." },
      { id: "paeds_pyloric_stenosis", management: {"def": "A[\"Pyloric stenosis (3-6 weeks old)\"]:::start --> B[\"Confirm: test feed, ultrasound\"]:::process\nB --> C[\"Bloods: hypochloraemic hypokalaemic metabolic alkalosis\"]:::process\nC --> D[\"Correct fluids and electrolytes FIRST\"]:::warn\nD --> E[\"Ramstedt pyloromyotomy (once stable)\"]:::good", "tips": {"A": "Hypertrophy of the pyloric muscle in babies around 3-6 weeks old: projectile non-bilious vomiting after feeds, a hungry baby, visible peristalsis and a palpable olive-shaped mass.", "B": "Confirm with a test feed (visible peristalsis, olive mass) and ultrasound (a thickened, elongated pylorus).", "C": "The classic biochemistry is a hypochloraemic, hypokalaemic metabolic alkalosis from vomiting gastric acid.", "D": "Correct dehydration and electrolyte/acid-base abnormalities with IV fluids BEFORE surgery - it is not a surgical emergency and anaesthesia is unsafe until corrected.", "E": "Definitive treatment is a Ramstedt pyloromyotomy once the baby is rehydrated and biochemically normal."}}, cluster: "Gastrointestinal & surgical", name: "Pyloric stenosis", keyFacts: "Hypertrophy of the pyloric muscle causing projectile non-bilious vomiting in young infants; correct the metabolic disturbance before surgery.", epidemiology: "Presents at around 2-8 weeks of age, commoner in firstborn boys.", aetiology: "Hypertrophy of the pyloric sphincter muscle; multifactorial with a genetic component.", pathophysiology: "Progressive pyloric muscle hypertrophy obstructs gastric outflow, and vomiting of gastric acid causes a hypochloraemic, hypokalaemic metabolic alkalosis.", presentation: "Projectile non-bilious vomiting after feeds in a hungry infant, with weight loss, dehydration, a palpable olive-shaped mass and visible peristalsis.", investigations: "Blood gas and U&E (hypochloraemic, hypokalaemic metabolic alkalosis); ultrasound confirms the thickened pylorus; test feed.", treatment: "Fluid resuscitation and correction of the electrolytes and alkalosis first, then surgery (Ramstedt pyloromyotomy)." },
      { id: "paeds_intussusception", management: {"def": "A[\"Intussusception (6 months to 2 years)\"]:::start --> B[\"Resuscitate: IV fluids, NG tube, analgesia\"]:::good\nB --> C[\"Confirm with ultrasound (target sign)\"]:::process\nC --> D{\"Peritonitis, perforation or shock?\"}:::decision\nD -- \"no\" --> E[\"Air (pneumatic) enema reduction\"]:::good\nD -- \"yes\" --> F[\"Surgery: reduction or resection\"]:::danger\nE -- \"fails or recurs\" --> F", "tips": {"A": "Telescoping of one bowel segment into another (usually ileocolic) in infants: colicky pain drawing up the legs, vomiting, and redcurrant-jelly stool; a sausage-shaped mass may be felt.", "B": "Resuscitate first: IV fluids, nasogastric decompression and analgesia.", "C": "Confirm with abdominal ultrasound (target or doughnut sign).", "D": "Choose between non-operative reduction and surgery based on peritonism, perforation or shock.", "E": "If stable with no peritonitis or perforation: reduction by air (pneumatic) enema under radiological guidance is first-line and usually successful.", "F": "Surgery (manual reduction, or resection if bowel is non-viable) if the enema fails or recurs, or if there is perforation, peritonitis or shock."}}, cluster: "Gastrointestinal & surgical", name: "Intussusception", keyFacts: "Telescoping of one bowel segment into another, the commonest cause of bowel obstruction in infants; the classic sign is redcurrant-jelly stool.", epidemiology: "Mainly infants 3 months to 2 years, commoner in boys.", aetiology: "Usually idiopathic (often after a viral illness with enlarged Peyer's patches); a pathological lead point (Meckel's diverticulum, polyp) in older children.", pathophysiology: "One segment invaginates into the next, dragging its mesentery and causing obstruction and venous congestion that can progress to ischaemia.", presentation: "Episodic colicky pain with drawing up of the legs, vomiting, a sausage-shaped abdominal mass and redcurrant-jelly (blood and mucus) stools.", investigations: "Ultrasound (target or doughnut sign) is the investigation of choice.", treatment: "Resuscitate; air (or contrast) enema reduction first line; surgery if reduction fails or there is peritonitis or perforation." },
      { id: "paeds_hirschsprung", cluster: "Gastrointestinal & surgical", name: "Hirschsprung's disease", keyFacts: "Congenital absence of ganglion cells in the distal bowel causing functional obstruction; suspect it with delayed passage of meconium.", epidemiology: "Affects about 1 in 5000 births, commoner in boys and in Down syndrome.", aetiology: "Failure of neural crest cell migration leaves an aganglionic distal colon; associated with Down syndrome and RET mutations.", pathophysiology: "The aganglionic segment cannot relax, causing functional obstruction with proximal bowel dilatation.", presentation: "Failure to pass meconium within 48 hours, abdominal distension and bilious vomiting in the neonate; chronic constipation later.", investigations: "Abdominal X-ray and contrast enema; rectal biopsy is definitive (absent ganglion cells).", treatment: "Bowel decompression (rectal washouts) then surgical resection of the aganglionic segment; watch for life-threatening enterocolitis." },
      { id: "paeds_mesenteric_adenitis", cluster: "Gastrointestinal & surgical", name: "Mesenteric adenitis", keyFacts: "Inflamed mesenteric lymph nodes causing abdominal pain that mimics appendicitis; a common, self-limiting diagnosis.", epidemiology: "Common in children and young people, often after a viral infection.", aetiology: "Usually viral, following or accompanying an upper respiratory tract infection; sometimes Yersinia.", pathophysiology: "Reactive enlargement and inflammation of mesenteric lymph nodes causes the abdominal pain.", presentation: "Central or right iliac fossa pain with a preceding or concurrent sore throat or coryza and tender cervical nodes; less guarding than appendicitis.", investigations: "Often a clinical and exclusion diagnosis; bloods and ultrasound help exclude appendicitis (enlarged nodes, normal appendix).", treatment: "Supportive with analgesia; it is self-limiting; safety-net and review to ensure it is not appendicitis." },
      { id: "paeds_gastroenteritis", cluster: "Gastrointestinal & surgical", name: "Gastroenteritis & dehydration", keyFacts: "Diarrhoea and vomiting in children, where assessing and correcting dehydration is the priority.", epidemiology: "Very common; rotavirus incidence has fallen since vaccination.", aetiology: "Usually viral (rotavirus, norovirus); bacterial causes are less common.", pathophysiology: "Mucosal infection impairs absorption and increases secretion, causing fluid and electrolyte loss and dehydration.", presentation: "Diarrhoea and vomiting with risk of dehydration in children.", investigations: "Assess hydration and red flags; stool culture if indicated.", treatment: "Oral rehydration solution, continue feeding; safety-net; IV fluids if shocked." },
      { id: "paeds_colic", cluster: "Gastrointestinal & surgical", name: "Infantile colic", keyFacts: "Recurrent excessive crying in an otherwise well, thriving infant; a benign, self-limiting diagnosis of exclusion.", epidemiology: "Very common, peaking around 6 weeks and resolving by 3-4 months.", aetiology: "Unknown; not due to a single identifiable cause.", pathophysiology: "No clear pathology; likely a combination of gut, feeding and developmental factors in a normal infant.", presentation: "Paroxysms of inconsolable crying, often drawing up the legs, in the evenings, in a thriving baby with a normal examination.", investigations: "Clinical; examine to exclude other causes of crying and rule out red flags.", treatment: "Reassurance and support for parents, soothing techniques, and time; safety-net for red flags." },
      { id: "paeds_uti", management: {"def": "A[\"UTI in a child\"]:::start --> B[\"Clean-catch urine for culture\"]:::process\nB --> C{\"Age and level\"}:::decision\nC -- \"under 3 months\" --> D[\"Refer to paediatrics, IV antibiotics\"]:::danger\nC -- \"over 3 months, upper UTI\" --> E[\"Oral (or IV) antibiotics 7-10 days\"]:::good\nC -- \"over 3 months, lower UTI\" --> F[\"Oral antibiotics 3 days\"]:::good\nE --> G[\"Imaging if atypical or recurrent (USS, DMSA, MCUG)\"]:::process", "tips": {"A": "UTI in children can be non-specific (fever, vomiting, poor feeding); confirm with an appropriate urine sample before or alongside antibiotics.", "B": "Obtain a clean-catch urine for culture (NICE); dipstick guides in older children, but culture is key, especially under 3 years.", "C": "Age and whether it is upper or lower tract decide treatment.", "D": "Infants under 3 months with suspected UTI: refer urgently to paediatrics for IV antibiotics and full assessment (treat as possible sepsis).", "E": "Over 3 months with pyelonephritis/upper UTI (fever 38+, loin pain): oral antibiotics (e.g. co-amoxiclav or cephalosporin) for 7-10 days, or IV if not tolerating oral.", "F": "Over 3 months with cystitis/lower UTI: oral antibiotics (trimethoprim, nitrofurantoin or cephalosporin) for 3 days.", "G": "Image atypical (non-E. coli, septic, poor urine flow, raised creatinine) or recurrent UTI: ultrasound, DMSA for scarring, and MCUG for reflux in selected infants."}}, cluster: "Renal & urinary", name: "UTI in children", keyFacts: "Urinary infection in children, often with non-specific features; it may signal an underlying anomaly.", epidemiology: "Common, and an important cause of fever in young children.", aetiology: "Usually ascending Escherichia coli; vesicoureteric reflux and obstruction predispose.", pathophysiology: "Bacteria ascend the urinary tract and infect the bladder or kidneys, and reflux can lead to renal scarring.", presentation: "Non-specific fever, vomiting, irritability in infants; dysuria in older children.", investigations: "Clean-catch urine for dipstick and culture; imaging by age and recurrence.", treatment: "Antibiotics per local guidance; investigate atypical or recurrent infection for renal anomalies." },
      { id: "paeds_enuresis", cluster: "Renal & urinary", name: "Nocturnal enuresis", keyFacts: "Involuntary bedwetting; not clinically significant before about 5 years of age.", epidemiology: "Common, reducing with age; commoner in boys and often with a family history.", aetiology: "Primary (never dry): delayed maturation, an overactive bladder, deep sleep, reduced overnight ADH, family history. Secondary (after 6 months dry): UTI, constipation, diabetes or psychological stress.", pathophysiology: "A mismatch between overnight urine production and bladder capacity, with a failure to wake.", presentation: "Bedwetting in a child over 5; ask about daytime symptoms, constipation, fluid intake and stressors.", investigations: "Urinalysis to exclude UTI and diabetes; assess for constipation.", treatment: "Reassurance and lifestyle measures (fluids, toileting); a star chart, then an enuresis alarm first line; desmopressin for short-term control or if the alarm fails; treat any constipation." },
      { id: "paeds_kawasaki", management: {"def": "A[\"Kawasaki disease\"]:::start --> B[\"Diagnose: fever 5+ days plus 4 of 5 CREAM features\"]:::process\nB --> C[\"IV immunoglobulin (IVIG)\"]:::good\nC --> D[\"High-dose aspirin\"]:::good\nD --> E[\"Echocardiography for coronary aneurysms\"]:::warn\nE -- \"IVIG-resistant\" --> F[\"Second IVIG dose, consider steroids/infliximab\"]:::warn", "tips": {"A": "A medium-vessel vasculitis of young children; the danger is coronary artery aneurysms.", "B": "Diagnose clinically: fever for 5 or more days plus at least 4 of - bilateral non-purulent Conjunctivitis, Rash, Extremity changes (swelling then peeling), Adenopathy (cervical, often unilateral) and Mucosal changes (strawberry tongue, cracked lips). CREAM.", "C": "Give intravenous immunoglobulin, ideally within 10 days, to reduce the risk of coronary aneurysms.", "D": "Give aspirin (high-dose anti-inflammatory, then low-dose antiplatelet) - one of the few paediatric indications for aspirin.", "E": "Arrange echocardiography at diagnosis and on follow-up to detect coronary artery aneurysms.", "F": "For IVIG-resistant disease (persistent fever), give a second dose of IVIG and consider corticosteroids or infliximab."}}, cluster: "Vasculitis & rheumatology", name: "Kawasaki disease", keyFacts: "A medium-vessel vasculitis of childhood whose key complication is coronary artery aneurysms.", epidemiology: "Mainly affects children under 5, commoner in East Asian children.", aetiology: "Unknown, probably an abnormal immune response to an infectious trigger.", pathophysiology: "Systemic vasculitis inflames medium-sized arteries, and coronary involvement can cause aneurysms and later ischaemia.", presentation: "Fever over 5 days with conjunctivitis, rash, lymphadenopathy, red cracked lips and extremity changes.", investigations: "Clinical criteria, inflammatory markers, echocardiogram for coronary aneurysms.", treatment: "IV immunoglobulin and aspirin; cardiology follow-up." },
      { id: "paeds_hsp", cluster: "Vasculitis & rheumatology", name: "Henoch-Schönlein purpura", keyFacts: "The commonest childhood vasculitis: an IgA small-vessel vasculitis with a palpable purpuric rash, usually after an infection; mostly self-limiting.", epidemiology: "Mainly children aged 3-10, often following an upper respiratory infection; commoner in boys.", aetiology: "An IgA-mediated vasculitis triggered by infection (often group A streptococcus or a virus).", pathophysiology: "IgA immune complexes deposit in the small vessels of the skin, joints, gut and kidneys, causing inflammation.", presentation: "The tetrad of a palpable purpuric rash on the buttocks and extensor legs, arthralgia, colicky abdominal pain and renal involvement (IgA nephritis).", investigations: "Largely clinical; urinalysis and BP for nephritis, FBC (normal platelets, distinguishing it from ITP), renal function.", treatment: "Usually supportive with analgesia and rest; monitor BP and urine for nephritis; steroids for severe abdominal or renal disease; most recover fully." },
      { id: "paeds_stills", cluster: "Vasculitis & rheumatology", name: "Still's disease (systemic JIA)", keyFacts: "Systemic-onset juvenile idiopathic arthritis: high spiking fevers, a salmon-pink rash and arthritis.", epidemiology: "A form of juvenile idiopathic arthritis presenting in young children.", aetiology: "An autoinflammatory disorder of unknown cause.", pathophysiology: "Innate immune activation with high inflammatory cytokines (interleukin-1 and interleukin-6) drives the systemic features and arthritis.", presentation: "Daily spiking (quotidian) fevers, an evanescent salmon-pink rash, arthritis, lymphadenopathy and hepatosplenomegaly.", investigations: "Raised inflammatory markers and ferritin and a raised white cell count; ANA and rheumatoid factor usually negative; exclude infection and malignancy.", treatment: "NSAIDs, corticosteroids and biologics (interleukin-1 or interleukin-6 blockers); watch for macrophage activation syndrome." },
      { id: "paeds_febrile_convulsion", cluster: "Neurology", name: "Febrile convulsion", keyFacts: "A seizure with fever in a young child without central nervous system infection; usually benign.", epidemiology: "Affects 2-5% of children aged 6 months to 5 years.", aetiology: "A rapid rise in temperature during a febrile illness in a susceptible child.", pathophysiology: "An immature brain is transiently susceptible to seizure activity provoked by fever.", presentation: "Generalised seizure with fever in a child 6 months to 5 years, no CNS infection.", investigations: "Identify infection source; lumbar puncture if meningism.", treatment: "Manage fever and reassure; safety advice; simple convulsions are benign." },
      { id: "paeds_milestones", cluster: "Development & safeguarding", name: "Developmental milestones", presentation: "Tracking gross motor, fine motor, language and social development; flag delay or regression.", investigations: "Structured developmental assessment, hearing and vision checks.", treatment: "Early referral for delay; MDT support; reassure normal variation." },
      { id: "paeds_immunisation", cluster: "Development & safeguarding", name: "Immunisation schedule", presentation: "Routine childhood vaccinations to prevent serious infection.", investigations: "Check records and contraindications.", treatment: "Follow the UK schedule (6-in-1, MMR, etc.); address vaccine hesitancy; catch-up where needed." },
      { id: "paeds_nai", cluster: "Development & safeguarding", name: "Non-accidental injury", presentation: "Injuries inconsistent with history or development, delayed presentation, concerning interactions.", investigations: "Thorough exam, documentation, skeletal survey, senior and safeguarding involvement.", treatment: "Ensure child's safety, follow safeguarding pathway, refer to social care; share information appropriately." },
    ],
  },
  {
    id: "pharmacology",
    name: "Pharmacology & Prescribing",
    icon: "💊",
    itemNoun: "topics",
    fieldLabels: ["⚙️ Mechanism & uses", "⚠️ Adverse effects & monitoring", "💉 Prescribing & safety"],
    conditions: [
      { id: "pharm_analgesia", cluster: "Analgesics", name: "Analgesia", fieldLabels: ["📋 The analgesic ladder", "💊 Drug options", "⚠️ Cautions"], presentation: "The WHO analgesic ladder steps up by severity: step 1 non-opioids (paracetamol, NSAIDs), step 2 weak opioids (codeine, tramadol), step 3 strong opioids (morphine), with adjuvants at any step.", investigations: "Paracetamol is first-line for most acute pain and NSAIDs for inflammatory pain; adjuvants are used for neuropathic pain (amitriptyline, gabapentin, pregabalin, duloxetine).", treatment: "Use the lowest effective dose for the shortest time; NSAID cautions (gastrointestinal, renal and cardiovascular, with PPI cover); opioid cautions (constipation, dependence, respiratory depression); reassess regularly." },
      { id: "pharm_nsaids", cluster: "Analgesics", name: "NSAIDs", presentation: "Anti-inflammatory analgesics inhibiting cyclo-oxygenase.", investigations: "Assess GI, renal and cardiovascular risk; check interactions.", treatment: "Lowest effective dose with PPI cover when needed; avoid in renal impairment, heart failure and with anticoagulants." },
      { id: "pharm_opioids", cluster: "Analgesics", name: "Opioids", presentation: "Strong analgesics for acute and palliative pain.", investigations: "Assess pain, function, dependence risk and renal function.", treatment: "Start low, co-prescribe laxatives, review regularly; naloxone reverses overdose; cautious in the elderly." },
      { id: "pharm_antihypertensives", cluster: "Cardiovascular & anticoagulation", name: "Antihypertensives", presentation: "ACE inhibitors, ARBs, calcium channel blockers and diuretics lower blood pressure.", investigations: "Check U&E after starting ACE-i/ARB; monitor BP and adherence.", treatment: "Follow stepwise pathway; avoid ACE-i/ARB combination; caution in pregnancy and renal artery stenosis." },
      { id: "pharm_atenolol", cluster: "Cardiovascular & anticoagulation", name: "Atenolol", presentation: "A cardioselective beta-1 blocker used for hypertension, angina, rate control in atrial fibrillation and after myocardial infarction; it reduces heart rate, contractility and renin release.", investigations: "Bradycardia, hypotension, fatigue, cold peripheries, bronchospasm and masking of hypoglycaemia; monitor heart rate and blood pressure.", treatment: "Avoid in asthma, severe bradycardia or heart block; do not stop abruptly (rebound angina and tachycardia); caution with verapamil or diltiazem and in heart failure; renally excreted, so reduce the dose in renal impairment." },
      { id: "pharm_warfarin", cluster: "Cardiovascular & anticoagulation", name: "Warfarin & DOACs", presentation: "Anticoagulants for AF and VTE; warfarin inhibits vitamin K clotting factors, DOACs are direct inhibitors.", investigations: "Warfarin needs INR monitoring; DOACs need renal function and weight; many interactions.", treatment: "DOAC first line for most; warfarin for mechanical valves/antiphospholipid; reverse with vitamin K/PCC or specific agents." },
      { id: "pharm_insulin", cluster: "Endocrine & metabolic", name: "Insulin", presentation: "Replaces or supplements endogenous insulin in diabetes.", investigations: "Glucose monitoring, HbA1c, hypo awareness, injection sites.", treatment: "Tailor regimen; never omit in type 1; manage hypoglycaemia; adjust in illness." },
      { id: "pharm_carbimazole", cluster: "Endocrine & metabolic", name: "Carbimazole", presentation: "An antithyroid drug that blocks thyroid peroxidase to reduce thyroid hormone synthesis; first-line for hyperthyroidism (Graves' disease), by titration or block-and-replace.", investigations: "Agranulocytosis is the key danger; also rash, and it is teratogenic; monitor thyroid function and warn the patient to seek an urgent full blood count if a sore throat or fever develops.", treatment: "Warn every patient about agranulocytosis (stop and check the full blood count if sore throat or fever); avoid in the first trimester (propylthiouracil is preferred); it takes weeks to work, so use a beta-blocker for symptoms meanwhile." },
      { id: "pharm_steroids", cluster: "Endocrine & metabolic", name: "Corticosteroids", presentation: "Potent anti-inflammatory/immunosuppressants for many conditions.", investigations: "Monitor glucose, BP, bone health and mood with prolonged use.", treatment: "Do not stop abruptly (adrenal suppression); sick-day rules; steroid card; gastric and bone protection." },
      { id: "pharm_lithium", cluster: "Other notable agents", name: "Lithium & narrow therapeutic index drugs", presentation: "Mood stabiliser with a narrow safety margin; toxicity risks neurological harm.", investigations: "Levels (12h post-dose), U&E, TFTs and calcium regularly.", treatment: "Maintain hydration, avoid NSAIDs/dehydration; recognise toxicity (tremor, ataxia, confusion); patient-held monitoring book." },
      { id: "pharm_antibiotics", cluster: "Other notable agents", name: "Antibiotics & allergy", presentation: "Choose by likely organism, site and severity; document allergy status accurately.", investigations: "Clarify nature of penicillin allergy; cultures where possible.", treatment: "Use narrow-spectrum where possible; avoid in true anaphylaxis; review and de-escalate." },
      { id: "pharm_paracetamol_od", management: {"source": "TOXBASE", "def": "A[\"Paracetamol overdose\"]:::start --> B[\"Timed paracetamol level (from 4 h post-ingestion)\"]:::process\nB --> C{\"Timing and pattern\"}:::decision\nC -- \"staggered / unknown time / 8h+ delayed\" --> D[\"Start NAC immediately\"]:::danger\nC -- \"single ingestion, timed level\" --> E[\"Plot level on nomogram\"]:::good\nE -- \"above treatment line\" --> D\nE -- \"below line\" --> F[\"No NAC, observe and safety-net\"]:::good\nD --> G[\"Check INR, LFTs, renal function, gas\"]:::process\nG --> H[\"King College criteria: refer for transplant if met\"]:::warn", "tips": {"A": "Paracetamol overdose risks hepatocellular necrosis from the toxic metabolite NAPQI once glutathione is depleted; patients are often asymptomatic early, so treat on level and timing.", "B": "Take a paracetamol level no earlier than 4 hours after ingestion (earlier levels cannot be interpreted).", "C": "Management depends on the timing and pattern of ingestion.", "D": "Give N-acetylcysteine (NAC, which replenishes glutathione) immediately - without waiting for a level - for a staggered overdose, unknown time of ingestion, or presentation 8 or more hours after a significant single overdose. Activated charcoal if within 1 hour of a large ingestion.", "E": "For a single ingestion at a known time, plot the timed level on the paracetamol treatment nomogram.", "F": "If the level is below the treatment line and the patient is asymptomatic, NAC is not needed - observe and safety-net.", "G": "Monitor INR (the earliest marker of hepatotoxicity), LFTs, U and Es and venous blood gas.", "H": "Use the King's College Hospital criteria (arterial pH under 7.3, or the triad of raised INR, raised creatinine and encephalopathy) to identify liver failure needing transplant referral."}}, cluster: "Overdose, poisoning & toxicity", name: "Paracetamol overdose", presentation: "Often asymptomatic early; later right upper quadrant pain and hepatic failure.", fields: [ { label: "☠️ Mechanism & features", value: "Toxic metabolite NAPQI depletes glutathione causing hepatocellular necrosis; early symptoms are mild." }, { label: "🔬 Investigations", value: "Paracetamol level at 4 hours post-ingestion plotted on the treatment line, LFTs, INR, U&E, venous gas." }, { label: "💉 Management", value: "N-acetylcysteine guided by the nomogram or for staggered/late presentations; refer to liver unit if criteria met." } ] },
      { id: "pharm_salicylate_od", management: {"source": "TOXBASE", "def": "A[\"Salicylate (aspirin) overdose\"]:::start --> B[\"ABCDE, IV fluids; salicylate level (4h then serial), gas, U&E\"]:::process\nB --> C[\"Activated charcoal if within 1 hour\"]:::good\nC --> D{\"Severity by level and features\"}:::decision\nD -- \"moderate (>500 mg/L or symptomatic)\" --> E[\"Correct K+, then urinary alkalinisation (IV bicarbonate, urine pH 7.5-8.5)\"]:::good\nD -- \"severe (>700 mg/L, acidosis, CNS, oedema, renal failure)\" --> F[\"Haemodialysis\"]:::danger\nE --> G[\"Avoid ventilation if possible; monitor level and pH\"]:::warn\nF --> G", "tips": {"A": "Aspirin (salicylate) overdose causes a mixed respiratory alkalosis and high anion-gap metabolic acidosis; it stimulates the respiratory centre and uncouples oxidative phosphorylation (TOXBASE).", "B": "Resuscitate and rehydrate; take a salicylate level at 4 hours and repeat every 2-3 hours (absorption is delayed, especially with enteric-coated tablets), with a blood gas, U and Es, glucose, lactate and a paracetamol level to screen for co-ingestion.", "C": "Give activated charcoal if the patient presents within 1 hour of ingestion (consider later for a large or enteric-coated ingestion).", "D": "Grade severity by the salicylate level and clinical features.", "E": "Moderate poisoning (level over 500 mg/L, or symptomatic): correct hypokalaemia first (you cannot alkalinise the urine while hypokalaemic), then give IV sodium bicarbonate to alkalinise the urine (target pH 7.5-8.5), which ion-traps salicylate and enhances its excretion.", "F": "Haemodialysis for severe poisoning - a level over 700 mg/L, a refractory metabolic acidosis, renal failure, pulmonary or cerebral oedema, seizures or coma.", "G": "Avoid intubation and ventilation unless unavoidable: a ventilator may fail to match the patient's high minute ventilation, removing their respiratory compensation and causing a rapid, potentially fatal fall in pH. Give glucose for neuroglycopenia even if the plasma glucose is normal."}}, cluster: "Overdose, poisoning & toxicity", name: "Salicylate (aspirin) overdose", fieldLabels: ["☠️ Features", "🔬 Investigations", "💉 Management"], presentation: "Tinnitus, deafness, nausea and vomiting, sweating and hyperventilation early (direct stimulation of the respiratory centre). Severe poisoning causes agitation, confusion, hyperpyrexia, dehydration, seizures, coma and non-cardiogenic pulmonary oedema. The classic acid-base picture is a mixed early respiratory alkalosis with a high anion-gap metabolic acidosis (the acidosis dominates in severe cases and in children).", investigations: "Serum salicylate level at 4 hours post-ingestion, repeated every 2-3 hours until falling (absorption is erratic and delayed, especially with enteric-coated aspirin); arterial or venous blood gas (mixed respiratory alkalosis and metabolic acidosis); U&E (hypokalaemia), glucose, lactate, coagulation, and a paracetamol level to screen for co-ingestion. A level over 500 mg/L is moderate and over 700 mg/L severe.", treatment: "Resuscitate (ABCDE) and rehydrate with IV fluids; activated charcoal if within 1 hour of ingestion. Correct hypokalaemia, then give IV sodium bicarbonate for urinary alkalinisation (target urine pH 7.5-8.5) to enhance elimination in moderate poisoning. Haemodialysis for severe features - a level over 700 mg/L, refractory acidosis, renal failure, pulmonary or cerebral oedema, seizures or coma. Avoid intubation and ventilation unless unavoidable, because losing the compensatory hyperventilation can precipitate a fatal fall in pH; give glucose for neuroglycopenia." },
      { id: "pharm_benzo_od", management: {"source": "TOXBASE", "def": "A[\"Benzodiazepine overdose\"]:::start --> B[\"ABCDE, mainly supportive\"]:::good\nB --> C[\"Airway support and oxygen, monitor\"]:::good\nC --> D{\"Severe respiratory depression?\"}:::decision\nD -- \"yes, and no dependence / mixed OD\" --> E[\"Cautious flumazenil (specialist)\"]:::warn\nD -- \"usual case\" --> F[\"Observe until sober, supportive care\"]:::good", "tips": {"A": "Benzodiazepine overdose causes CNS and respiratory depression; management is largely supportive as most recover with monitoring.", "B": "Support airway, breathing and circulation; the danger is respiratory depression, especially with co-ingestants (alcohol, opioids).", "C": "Give oxygen and airway support, and monitor conscious level and respiration.", "D": "Reserve the antidote for genuine severe respiratory depression.", "E": "Flumazenil (a benzodiazepine antagonist) is used cautiously and rarely, by specialists - it can precipitate seizures in dependent patients or mixed overdoses (especially with tricyclics), so it is NOT for routine use.", "F": "Most cases: observe until the patient is awake and safe, with supportive care."}}, cluster: "Overdose, poisoning & toxicity", name: "Benzodiazepine overdose", fieldLabels: ["☠️ Features", "🔬 Investigations", "💉 Management"], presentation: "Central nervous system depression: drowsiness, slurred speech, ataxia and respiratory depression, which is worse with co-ingestants such as alcohol or opioids.", investigations: "Clinical; assess airway and breathing; blood gas and glucose, and screen for co-ingestion (paracetamol, salicylate, alcohol, opioids).", treatment: "Mainly supportive (airway and breathing); flumazenil (a benzodiazepine antagonist) can reverse it but is rarely used, as it may precipitate seizures, especially in dependence or a mixed overdose." },
      { id: "pharm_digoxin_od", management: {"source": "TOXBASE", "def": "A[\"Digoxin toxicity\"]:::start --> B[\"ECG, digoxin level, check potassium\"]:::process\nB --> C[\"Correct hypokalaemia and hypomagnesaemia\"]:::good\nC --> D{\"Life-threatening arrhythmia or hyperkalaemia?\"}:::decision\nD -- \"yes\" --> E[\"Digoxin-specific antibody (DigiFab)\"]:::danger\nD -- \"no\" --> F[\"Supportive, stop digoxin, treat cause\"]:::good", "tips": {"A": "Digoxin has a narrow therapeutic index; toxicity causes nausea, confusion, visual disturbance (yellow-green haloes) and arrhythmias, precipitated by hypokalaemia, renal impairment and drug interactions.", "B": "Do an ECG (bradyarrhythmias, AV block, ventricular ectopy, the reverse-tick), check a digoxin level and, crucially, serum potassium.", "C": "Correct hypokalaemia and hypomagnesaemia in chronic toxicity (they worsen it) - but note that in acute overdose potassium is often HIGH.", "D": "Decide on the antidote by the severity of arrhythmia and the potassium level.", "E": "Digoxin-specific antibody fragments (DigiFab) for life-threatening arrhythmias, haemodynamic instability, or significant hyperkalaemia (over 5 mmol/L in acute toxicity).", "F": "Otherwise stop digoxin, give supportive care, treat the precipitant and monitor; avoid calcium for digoxin-related hyperkalaemia."}}, cluster: "Overdose, poisoning & toxicity", name: "Digoxin overdose", fieldLabels: ["☠️ Features", "🔬 Investigations", "💉 Management"], presentation: "Nausea, vomiting, confusion, xanthopsia (yellow-green vision) and arrhythmias (classically bradyarrhythmias); precipitated by hypokalaemia, hypomagnesaemia and renal impairment.", investigations: "Digoxin level, U&E (potassium, where hyperkalaemia indicates severe toxicity), magnesium, and ECG (the reverse-tick sign and arrhythmias).", treatment: "Correct electrolytes; give digoxin-specific antibody fragments (DigiFab) for life-threatening arrhythmias or significant hyperkalaemia; treat arrhythmias and stop the digoxin." },
      { id: "pharm_phenytoin_toxicity", management: {"source": "TOXBASE", "def": "A[\"Phenytoin toxicity\"]:::start --> B[\"Stop or reduce phenytoin\"]:::good\nB --> C[\"Check phenytoin level (and albumin)\"]:::process\nC --> D[\"Supportive care, ECG monitoring\"]:::good\nD --> E{\"Severe (cardiotoxicity, coma)?\"}:::decision\nE -- \"yes\" --> F[\"Cardiac monitoring, IV fluids, consider charcoal\"]:::warn\nE -- \"no\" --> G[\"Observe until level falls\"]:::good", "tips": {"A": "Phenytoin has zero-order kinetics near therapeutic levels, so small dose changes cause toxicity: nystagmus, ataxia and slurred speech, then confusion and, in severe cases, cardiotoxicity.", "B": "Stop or reduce phenytoin; toxicity usually resolves as levels fall.", "C": "Check the phenytoin level and correct for albumin (phenytoin is protein-bound), or measure free phenytoin.", "D": "Management is supportive with monitoring; oral overdose can be treated with activated charcoal if early.", "E": "Severe toxicity (usually IV overdose - hypotension, arrhythmia, coma) needs closer care.", "F": "For severe or IV toxicity: cardiac monitoring, IV fluids for hypotension, and consider multiple-dose activated charcoal; there is no specific antidote.", "G": "Mild toxicity: observe until levels return to range, then restart at a lower dose."}}, cluster: "Overdose, poisoning & toxicity", name: "Phenytoin toxicity", fieldLabels: ["☠️ Features", "🔬 Investigations", "💉 Management"], presentation: "Nystagmus, ataxia, slurred speech, diplopia and drowsiness; phenytoin has a narrow therapeutic index and non-linear (zero-order) kinetics, so small dose increases can tip into toxicity.", investigations: "Phenytoin level (interpret alongside albumin, as it is highly protein-bound) and ECG.", treatment: "Stop or reduce the dose; supportive care; manage any arrhythmia; be mindful of its many interactions, as it is a hepatic enzyme inducer." },
      { id: "pharm_co_poisoning", management: {"source": "TOXBASE", "def": "A[\"Carbon monoxide poisoning\"]:::start --> B[\"Remove from source, 100 percent oxygen\"]:::danger\nB --> C[\"Measure carboxyhaemoglobin on a blood gas\"]:::process\nC --> D[\"Continue oxygen until COHb normal and symptoms gone\"]:::good\nD --> E{\"Severe features?\"}:::decision\nE -- \"LOC, neurology, pregnancy, very high COHb\" --> F[\"Consider hyperbaric oxygen\"]:::warn\nE -- \"no\" --> G[\"Observe, safety-net, check source\"]:::good", "tips": {"A": "Carbon monoxide binds haemoglobin with about 250 times the affinity of oxygen, causing tissue hypoxia; suspect it with headache, nausea, dizziness and confusion, often affecting a whole household (faulty boilers, fires). Pulse oximetry reads falsely normal.", "B": "Immediately remove from the source and give high-flow 100% oxygen via a non-rebreathe mask - this shortens the half-life of carboxyhaemoglobin.", "C": "Measure carboxyhaemoglobin on a blood gas (co-oximeter); the level correlates poorly with severity, so treat clinically.", "D": "Continue high-flow oxygen until carboxyhaemoglobin normalises and symptoms resolve.", "E": "Identify severe or high-risk cases.", "F": "Consider hyperbaric oxygen for loss of consciousness, neurological signs, myocardial ischaemia, pregnancy or very high carboxyhaemoglobin - discuss with the poisons service (evidence is debated).", "G": "Otherwise observe, safety-net for delayed neurological sequelae, and ensure the source is made safe before discharge."}}, cluster: "Overdose, poisoning & toxicity", name: "Carbon monoxide poisoning", fieldLabels: ["☠️ Features", "🔬 Investigations", "💉 Management"], presentation: "Headache, nausea, dizziness and confusion (a flu-like illness without fever), often with several household members or pets affected; cherry-red skin is a late and rare sign; sources include faulty boilers, fires and fumes.", investigations: "Carboxyhaemoglobin level on a blood gas (pulse oximetry reads falsely normal); ECG and cardiac markers; identify the source.", treatment: "High-flow 100% oxygen via a non-rebreathe mask (which speeds carbon monoxide elimination); hyperbaric oxygen in severe cases (loss of consciousness, neurological signs, pregnancy); remove the patient from the source." },
      { id: "pharm_methanol", management: {"source": "TOXBASE", "def": "A[\"Methanol or ethylene glycol poisoning\"]:::start --> B[\"Bloods: gas, osmolar gap, anion gap\"]:::process\nB --> C[\"Antidote: fomepizole (or ethanol)\"]:::danger\nC --> D[\"Correct acidosis with bicarbonate\"]:::good\nD --> E{\"Severe: acidosis, visual loss, high level?\"}:::decision\nE -- \"yes\" --> F[\"Haemodialysis\"]:::danger\nE -- \"no\" --> G[\"Continue antidote until cleared\"]:::good", "tips": {"A": "Methanol and ethylene glycol are metabolised by alcohol dehydrogenase to toxic acids, causing a high anion-gap metabolic acidosis; methanol causes visual loss (snowfield blindness), ethylene glycol causes renal failure and oxalate crystals.", "B": "Look for a raised anion-gap metabolic acidosis and a raised osmolar gap; confirm with drug levels if available.", "C": "Give the antidote fomepizole (or ethanol) - it blocks alcohol dehydrogenase and prevents formation of the toxic metabolites.", "D": "Correct the metabolic acidosis with IV sodium bicarbonate; give folinic acid (methanol) or thiamine and pyridoxine (ethylene glycol) as cofactors.", "E": "Identify severe poisoning.", "F": "Haemodialysis for severe acidosis, visual impairment, high drug levels or renal failure - it removes both the parent alcohol and the toxic metabolites.", "G": "Continue the antidote until the parent alcohol is cleared and the acidosis has resolved."}}, cluster: "Overdose, poisoning & toxicity", name: "Methanol poisoning", fieldLabels: ["☠️ Features", "🔬 Investigations", "💉 Management"], presentation: "Initial inebriation, then after a latent period headache, vomiting, a high anion-gap metabolic acidosis and visual disturbance or blindness; from industrial alcohol or adulterated spirits.", investigations: "Blood gas (a high anion-gap metabolic acidosis), a raised osmolar gap, methanol level, U&E and a visual assessment.", treatment: "Fomepizole (or ethanol) to block alcohol dehydrogenase and prevent toxic formate; sodium bicarbonate for the acidosis; haemodialysis in severe cases; folinic acid." },
      { id: "pharm_pregnancy", cluster: "Prescribing principles & safety", name: "Drugs in pregnancy", presentation: "Teratogenic risk must be weighed against treating maternal illness.", investigations: "Check pregnancy status and trimester; consult resources.", treatment: "Avoid known teratogens (valproate, ACE-i, retinoids, warfarin); use safest effective option; preconception counselling." },
      { id: "pharm_nephrotoxicity", cluster: "Prescribing principles & safety", name: "Drug nephrotoxicity", fieldLabels: ["📋 Culprit drugs", "🔬 Monitoring", "✅ Prevention & action"], presentation: "Common nephrotoxic drugs are NSAIDs, ACE inhibitors and ARBs, aminoglycosides (gentamicin), iodinated contrast, vancomycin, ciclosporin and tacrolimus, and lithium; mechanisms include reduced perfusion, acute tubular necrosis and interstitial nephritis.", investigations: "Monitor renal function (creatinine, eGFR) and urine output; check drug levels for aminoglycosides and vancomycin; urinalysis for interstitial nephritis.", treatment: "Avoid or dose-adjust in renal impairment; hold nephrotoxins in acute kidney injury (the DAMN drugs: Diuretics, ACE inhibitors/ARBs, Metformin, NSAIDs); ensure good hydration and review the medication list." },
      { id: "pharm_tachyphylaxis", cluster: "Prescribing principles & safety", name: "Tachyphylaxis", fieldLabels: ["📋 What it is", "💊 Examples", "🔑 Key points"], presentation: "A rapid reduction in response to a drug after repeated doses over a short time (acute tolerance), distinct from the slower tolerance of chronic use.", investigations: "Classic examples are nitrates (glyceryl trinitrate, hence the need for nitrate-free periods), topical decongestants (rhinitis medicamentosa) and indirectly-acting sympathomimetics such as ephedrine (which depletes noradrenaline stores).", treatment: "Managed by dose-free intervals (for example a daily nitrate-free period), rotating agents, or stopping the drug; the response usually returns after a break." },
      { id: "pharm_polypharmacy", cluster: "Prescribing principles & safety", name: "Polypharmacy in the elderly", presentation: "Multiple medicines raise interaction, adherence and falls risk.", investigations: "Structured medication review, renal function, anticholinergic burden.", treatment: "Deprescribe where appropriate, simplify regimens, align with goals and frailty." },
    ],
  },
  {
    id: "public_health",
    name: "Public Health, Ethics & Evidence",
    icon: "⚖️",
    itemNoun: "topics",
    conditions: [
      { id: "ph_capacity", cluster: "Ethics & law", name: "Consent & capacity", presentation: "Adults are presumed to have capacity; assess understanding, retention, weighing and communication.", investigations: "Capacity is decision- and time-specific; involve the patient fully.", treatment: "Act in best interests if lacking capacity; consider advance decisions and lasting power of attorney; document." },
      { id: "ph_confidentiality", cluster: "Ethics & law", name: "Confidentiality", presentation: "Duty to keep patient information private, with limited justified exceptions.", investigations: "Identify whether disclosure is required or justified in the public interest.", treatment: "Share on a need-to-know basis; breach only when required by law or to prevent serious harm; document rationale." },
      { id: "ph_safeguarding", cluster: "Ethics & law", name: "Safeguarding", presentation: "Protecting children and vulnerable adults from abuse and neglect.", investigations: "Recognise indicators; gather information; seek senior and specialist advice.", treatment: "Act on concerns, refer to safeguarding leads/social care, document; the person's safety is paramount." },
      { id: "ph_smoking", cluster: "Health promotion & screening", name: "Health promotion & smoking cessation", presentation: "Behaviour change opportunities at every contact (Making Every Contact Count).", investigations: "Assess readiness to change, dependence.", treatment: "Very brief advice; nicotine replacement, varenicline or bupropion; refer to cessation services." },
      { id: "ph_screening", cluster: "Health promotion & screening", name: "Screening programmes", presentation: "Detecting disease early in asymptomatic populations; must meet Wilson-Jungner criteria.", investigations: "Understand sensitivity, specificity and lead-time/length bias.", treatment: "UK programmes include cervical, breast, bowel, AAA and antenatal screening; counsel on benefits and limits." },
      { id: "ph_ebm", cluster: "Evidence-based medicine & statistics", name: "Evidence-based medicine", presentation: "Integrating best evidence with clinical expertise and patient values.", investigations: "Appraise study design, bias, confounding and applicability.", treatment: "Hierarchy: systematic review/RCT above cohort/case-control; weigh effect size and confidence intervals." },
      { id: "ph_stats", cluster: "Evidence-based medicine & statistics", name: "Diagnostic statistics", presentation: "Interpreting test performance and trial results.", investigations: "Sensitivity, specificity, predictive values, likelihood ratios, number needed to treat.", treatment: "Choose tests by purpose (rule in vs rule out); understand absolute vs relative risk; p-values and confidence intervals." },
      { id: "ph_death_cert", cluster: "Certification & fitness to drive", name: "Death certification", presentation: "Accurately recording cause of death and knowing when to refer to the coroner.", investigations: "Establish cause; identify reportable circumstances (unknown cause, violence, in custody).", treatment: "Complete the MCCD correctly; refer to coroner where required; medical examiner scrutiny." },
      { id: "ph_dvla", cluster: "Certification & fitness to drive", name: "DVLA & fitness to drive", presentation: "Many conditions affect driving safety and carry a duty to advise patients.", investigations: "Know rules for seizures, syncope, vision, diabetes and cardiac events.", treatment: "Advise the patient of their duty to inform DVLA; breach confidentiality to notify only if they continue to drive against advice." },
      { id: "ph_vaccination", cluster: "Population health", name: "Vaccination & herd immunity", presentation: "Immunisation protects individuals and populations.", investigations: "Check eligibility, contraindications and informed consent.", treatment: "Promote uptake, address hesitancy with empathy, follow the national schedule." },
    ],
  },
];

